do local function f(R)
R(1,"The \"Chow\" Quest (123)aa",[[description="$Tpunk;!  Kill Kobold Vermin, 2 of em. NEW TEST AGAIN",objectives={"Kill Kobold Vermin, 2 of em."}]])
R(2,"沙普塔隆的爪子",[[description="強大的角鷹獸沙普塔隆已經被你殺死了，它的爪子成為你勝利的象徵。碎木崗哨的塞娜尼·雷心一定會對你的戰利品感興趣的。",objectives={"將沙普塔隆的爪子交給梣谷碎木崗哨的塞娜尼·雷心。"}]])
R(5,"饑腸轆轆的基特斯",[[description="我已經困在這個鬼鎮裡好幾個星期了，除了蟲子和野草之外什麼吃的都沒有！我想吃點正常的食物，即使要多花點錢也無所謂。$B$B找點美食來給我，我會給你大筆的報酬。$B$B我聽說夜色鎮血鴉旅店的格魯奧廚師做的黑蟹蛋糕很不錯……",objectives={"和格魯奧廚師談話。"}]])
R(6,"加瑞克·帕德弗特的賞金",[[description="Garrick Padfoot - a cutthroat who's plagued our farmers and merchants for weeks - was seen at a shack near the vineyards, which lies east of the Abbey and across the bridge.  Bring me the villain's head, and earn his bounty!$B$BBut be wary, $N.  Garrick has gathered a gang of thugs around him.  He will not be an easy man to reach.",objectives={"Kill Garrick Padfoot and bring his head to Deputy Willem at Northshire Abbey."}]])
R(7,"剿滅狗頭人",[[description="你的第一個任務是清剿工作，$N。一個狗頭人部族佔據了北邊的森林。到那兒去，把你能看到的狗頭人歹徒都殺掉。儘量減少他們的數量，好讓我們有一天能把他們從北郡徹底趕出去。",objectives={"殺死10隻狗頭人歹徒，然後向治安官瑪克布萊德覆命。"}]])
R(8,"潛行者的交易",[[description="嘿，朋友！幫我一個忙如何？一大堆殭屍和蜘蛛實在讓我應接不暇。$B$B我手裡有一封要送到布瑞爾的信，是要送給一個名叫蕾妮還是什麼的旅店老闆。別管她姓什麼啦！$B$B總之，那裡是一個舒適而溫暖的小地方，裡面都是些努力地想活在這個世界上的瘟疫受害者，當然那裡也是你休息的好去處。你應該自己去看看……如果你願意跑一趟，我會給你不錯的報酬。",objectives={"將一封無聊的信送給在提里斯法林地的布瑞爾旅店老闆蕾妮。"}]])
R(9,"清理荒野",[[description="看看這片土地上都發生了些什麼吧！這片土地曾為一群善良老實的農民們所有。但如今，一群該死的小賊把農民們全部趕走了。當然，除了老子我！但有些看守傀儡一直霸佔著我的田地。$b$b如果你覺著自己能夠勝任這份工作的話，我希望你能幫忙清除掉20台傀儡。完成了任務之後，記得回來拿酬勞。如果你把我這片田地上的傀儡清光了的話，就去清除旁邊田上的傀儡吧。",objectives={"農夫薩丁要求你破壞掉20台看守傀儡。"}]])
R(10,"謝申克的救贖",[[description="啊，這真是太糟糕了！我派我手下最得力的助手，初級勘探員謝申克去沙漠東南面那個叫做大裂口的地方進行探查。但是他現在失蹤了，而他最後一份報告中顯示，大裂口到處都充斥著奇怪的蟲子。該不會這片沙漠上兩大塊重要的地區都被蟲子佔領了吧?$B$B我需要你去大裂口找謝申克，求求你了！也許他已經……但請你把他的勘探設備找回來。恐怕那是可憐的謝申克唯一留下的東西了。",objectives={"尋找初級勘探員謝申克的下落，把他或者他的勘探設備交給加基森的高級勘探員菲茲杜瑟。"}]])
R(11,"懸賞河爪豺狼人",[[description="有人在艾爾文森林的邊界處看見了豺狼人，這些野蠻的動物在這兒肯定不會幹什麼好事。在瞭望塔南邊的樹林裡有一大群豺狼人到處遊蕩，憑我們自己的兵力很難應付他們。另一群則在東邊的石碑湖附近。$B$B任何幫忙清除這些豺狼人的勇士都會受到暴風城軍方的嘉獎。把他們的彩色豺狼人臂章帶給我以證明你殺了他們。",objectives={"帶8個彩色豺狼人臂章給兵營的瑞尼爾副隊長。"}]])
R(12,"西部荒野人民軍",[[description="民兵只有一個目標：保護西部荒野的安寧，並將和平帶回到這片土地上來。不幸的是，和平的代價總是以鮮血來換取的。$b$b我手下的一個斥候報告說，有一群迪菲亞捕獸者正在附近到處流竄並大肆破壞。最新的報告說他們出現在西北方的詹戈洛德礦坑中，摩森農場，以及法布隆的南瓜田。如果你想加入我們民兵的話，那麼就先去殺死15名迪菲亞捕獸者和16名迪菲亞走私者，然後回來找我。",objectives={"哨兵嶺的格萊恩·斯托曼要你殺死15名迪菲亞捕獸者和15名迪菲亞走私者後回去找他。"}]])
R(13,"西部荒野人民軍",[[description="有人看見一群兇殘的迪菲亞搶劫者洗劫了金海岸礦坑、月溪鎮及艾力克斯頓農場，我們人民軍絕不能對這樣的事袖手旁觀。馬上就出發吧，$n，讓聖光重新照耀西部荒野。$b$b金海岸礦坑就在哨塔西邊的海岸附近，作為訓練的第二部分，我希望你能殺死15名迪菲亞搶劫者和15名迪菲亞強奪者。",objectives={"哨兵嶺的格里安·斯托曼要求你殺死15名迪菲亞搶劫者和15名迪菲亞強奪者，然後回去向他報告。"}]])
R(14,"西部荒野人民軍",[[description="一些迪菲亞路霸最近一直在避開我們，到處作惡。根據我手下最可靠的探子情報，這些迪菲亞路霸通常沿著從這裡到西部荒野南部的道路打家劫舍。我們相信他們現在應該就躲在南部的匕首丘陵，計畫著下一步的行動。以民兵之名，去殺死那些傢伙吧!",objectives={"哨兵嶺的格萊恩·斯托曼要你殺死15個迪菲亞路霸、5個迪菲亞巡路者和5個迪菲亞拳匪，然後回去向他報告。"}]])
R(15,"回音山調查行動",[[description="$N，我的探子告訴我說，狗頭人出沒的範圍遠大於我們的想像，一群狗頭人工人剛剛在北邊的回音山礦坑附近駐紮。$B$B到礦坑那裡，把他們都除掉。那裡至少有10隻狗頭人工人，殺了他們，看看他們的數量是不是不止這麼多，之後回報給我。",objectives={"殺死10隻狗頭人工人，然後向治安官瑪克布萊德回報。"}]])
R(16,"葛拉德的飲料")
R(17,"奧達曼的蘑菇",[[description="I've heard about a newly discovered plant called the magenta fungus caps.  They grow in clusters, deep in the Uldaman dig site; they may be elsewhere, but for now that's the only place I know they're at.  I want to study their potential use in alchemy, and that's where you come in.$B$BFind the magenta cap clusters and bring me a dozen caps.  Be warned, the clusters may spew out poison spores if jostled.$B$BDo this for me, and I'll whip up a batch of one of my famous restorative elixirs for you!",objectives={"Bring 12 Magenta Fungus Caps to Ghak Healtouch in Thelsamar."}]])
R(18,"潛行者兄弟會",[[description="最近, 一夥新來的流寇停留在北郡一帶，為禍四方。他們自稱為迪菲亞兄弟會，向東過了河之後就能找到他們。$B$B我不知道他們聚在一起到底想要幹什麼，但我確信他們不是什麼好東西。給我帶回一些他們的紅色粗麻面罩，我就送你一把武器作為獎勵。",objectives={"給北郡的維里副隊長帶回12個紅色粗麻面罩。"}]])
R(19,"薩瑞爾祖恩",[[description="黑石前鋒和黑石背教者經常在這裡和石堡要塞之間伏擊我們，這群前鋒的指揮官是個名叫薩瑞爾祖恩的獸人。把他的頭給我帶來。",objectives={"將薩瑞爾祖恩的頭顱帶給湖畔鎮的治安官馬瑞斯。"}]])
R(20,"黑石氏族的威脅",[[description="黑石氏族穿越了燃燒平原，並且攻下了北方的石堡要塞。他們以那座要塞為據點，劫掠湖畔鎮北邊的居民，全鎮的居民嚇得都不敢外出，只能躲在鎮裡瑟瑟發抖。$B$B幫湖畔鎮居民解決掉這個威脅吧。殺死黑石氏族的獸人，並且帶回十把他們所用的破斧作為證明。$B$B儘管黑石氏族是在北方威脅著我們，但我們也收到了他們在赤脊山脈東南部出現的報告。你可以在那裡找到他們，然後獵殺他們。",objectives={"帶回10把破斧給湖畔鎮的治安官馬瑞斯。"}]])
R(21,"回音山清剿行動",[[description="Your previous investigations are proof that the Echo Ridge Mine needs purging.  Return to the mine and help clear it of kobolds.$B$BWaste no time, $N.  The longer the kobolds are left unmolested in the mine, the deeper a foothold they gain in Northshire.",objectives={"Kill 12 Kobold Laborers, then return to Marshal McBride at Northshire Abbey."}]])
R(22,"豬肝餡餅",[[description="削兩個洋蔥，剝一個大蒜，烤三片麵包，剁半兩香菜，切幾塊蘿蔔，熬一鍋肉醬。現在……我還需要8片豬肝來完成我的絕世美味餡餅！",objectives={"薩爾瑪·薩丁需要8片血牙野豬的肝來烹製豬肝餡餅。"}]])
R(23,"烏薩茍斯的爪子",[[description="強大的熊怪烏薩苟斯被你殺死了，它的爪子是你梣谷狩獵之行的戰利品。爪子上有一小塊新月形的印記，這個印記的意義對你來說還是一個謎。$B$B你應該把這只爪子交給碎木崗哨的塞娜尼·雷心，以此證明你已經殺死了這隻強大的猛獸。",objectives={"將烏薩苟斯的爪子交給梣谷碎木崗哨的的塞娜尼·雷心。"}]])
R(24,"薩杜布拉的頭顱",[[description="曾經敏捷而強大的薩杜布拉現在靜靜地躺在地上，你取得了最後的勝利。牠的頭顱對這次的梣谷狩獵來說是一件非常合適的戰利品，碎木崗哨的塞娜尼·雷心肯定會想要看看這件戰利品，然後對你在梣谷狩獵中取得的成績予以嘉獎。",objectives={"將薩杜布拉的頭顱交給梣谷碎木崗哨的的塞娜尼·雷心。"}]])
R(25,"石爪山的困境",[[description="如果你想做個有用的$c，那為什麼不幫我們解決石爪山那邊的困境呢？$B$B梣谷和石爪山脈之間的交通中斷了，因為湖水中的生物突然開始攻擊任何過路的旅行者……一個都不放過。你要做的並不僅僅是殺死那些水元素，你還要到密斯特拉湖中的眺望臺上去一趟——在那裡可以看到聯盟前哨站的情況。$B$B你準備好了嗎？",objectives={"清除位於碎木崗哨西南和石爪小徑正東的密斯特拉湖一帶的12個污濁的水元素。$B$B在密斯特拉湖上的眺望台中偵查聯盟的前哨站。$B$B返回梣谷的碎木崗哨，向馬斯托克·維爾西斯報告。"}]])
R(26,"必修的課程",[[description="$N, I have been following your progress with much delight.  You are most assuredly developing yourself into a valued protector of nature.$B$BThe time has come for you to learn more about one of the various animal aspects that Cenarius has blessed us with the ability to change into - one that affords you command and mastery of the water.  For this, you must travel to the village of Nighthaven in Moonglade and speak with Dendrite Starblaze of the Cenarion Circle there.  He will guide you further.",objectives={"Speak with Dendrite Starblaze in the village of Nighthaven, Moonglade."}]])
R(27,"必修的課程",[[description="$N, I have been following your progress with much delight.  You are most assuredly developing yourself into a valued protector of nature.$B$BThe time has come for you to learn more about one of the various animal aspects that Cenarius has blessed us with the ability to change into - one that affords you command and mastery of the water.  For this, you must travel to the village of Nighthaven in Moonglade and speak with Dendrite Starblaze of the Cenarion Circle there.  He will guide you further.",objectives={"Speak with Dendrite Starblaze in the village of Nighthaven, Moonglade."}]])
R(28,"湖中試煉",[[description="For your first trial, search the depths of Lake Elune'ara to locate a Shrine Bauble.  It decays rapidly, so proceed with it to the Shrine of Remulos post haste.  Use the bauble at the shrine, and then speak with Tajarri there; she is one of Moonglade's most trusted wardens.$B$BYou only have a set amount of time to complete the task, and you may be competing against other druids searching for baubles themselves.  Mental and physical dexterity will be critical to your success.$B$BGood luck, $N.",objectives={"Find a Shrine Bauble in Lake Elune'ara, and take it to the Shrine of Remulos in northwestern Moonglade.  Once there, use the Shrine Bauble.$B$BYou must speak with Tajarri at the shrine afterwards in order to complete the trial."}]])
R(29,"湖中試煉",[[description="For your first trial, search the depths of Lake Elune'ara to locate a Shrine Bauble.  It decays rapidly, so proceed with it to the Shrine of Remulos post haste.  Use the bauble at the shrine, and then speak with Tajarri there; she is one of Moonglade's most trusted wardens.$B$BYou only have a set amount of time to complete the task, and you may be competing against other druids searching for baubles themselves.  Mental and physical dexterity will be critical to your success.$B$BGood luck, $N.",objectives={"Find a Shrine Bauble in Lake Elune'ara, and take it to the Shrine of Remulos in northwestern Moonglade.  Once there, use the Shrine Bauble.$B$BYou must speak with Tajarri at the shrine afterwards in order to complete the trial."}]])
R(30,"海獅試煉",[[description="For the second trial, you'll need the two halves that make the Pendant of the Sea Lion.  One half draws power from the agility of the sea lion aspect, gliding through water; the other draws power from the incredible endurance of the sea lion aspect.  Druids draw on both these traits equally to embody the aspect of their aquatic form.$B$BSpeak with the locals of Moonglade to learn where the parts may lie, and bring both here to join them together.  Once formed, take the pendant to Dendrite Starblaze.",objectives={"Find the Half Pendant of Aquatic Agility and the Half Pendant of Aquatic Endurance.  Speak with the residents of Moonglade to learn clues as to where these items may be located.$B$BForm the Pendant of the Sea Lion from the two pendant halves.  You need to be in proximity of the Shrine of Remulos to do this.$B$BBring the joined pendant to Dendrite Starblaze in the village of Nighthaven, Moonglade."}]])
R(31,"水棲形態",[[description="You have completed the necessary lessons all young druids are taught before they can adopt an aquatic aspect.  Go now back to your trainer, Turak Runetotem, in Thunder Bluff.  Show him your pendant and prove to him you are ready to learn what he has to teach you.  He will complete your training, allowing you to become one with the water.$B$BGoodbye, young druid.  We shall speak again.",objectives={"Return to Thunder Bluff and show Turak Runetotem the Pendant of the Sea Lion."}]])
R(32,"異種蠍的威脅",[[description="Here's your report.  I urge you to take it to someone who might have working knowledge in this kind of thing.$B$BI know this troll scholar named Zilzibin Drumlore.  He's spent a lot of time studying life forms that are unique to the ecology of Azeroth; he's a historian to boot!  If you want someone to help figure out what exactly this threat is and how to stop it, give this report to him.  We're going to need all the help we can get.$B$BZil lives in a house on the second tier of the Drag in Orgrimmar.",objectives={"Take the report to Zilzibin Drumlore in Orgrimmar."}]])
R(33,"林中的群狼",[[description="我恨透那些骯髒狡猾的森林狼了！但我一直都很愛吃狼排……給我帶6塊硬狼肉來，我會拿一些對你有用的東西做為交換。$B$B你可以在北郡的郊外找到森林狼和幼狼，殺掉它們就可以得到硬狼肉了。",objectives={"帶8塊硬狼肉給北郡修道院外的伊根·派特斯金納。"}]])
R(34,"不速之客",[[description="前幾天我的花園又被搞得一塌糊塗，不過我已經知道是哪個混蛋幹的了。就是被治安官馬瑞斯先生稱作「貝利格拉布」的那隻野豬。$b$b你瞧！在下一季來臨之前，我都不能種我的水仙花了。全毀了！一切都被那隻混蛋野豬給毀了！幫我除掉那個禍害！把它的獠牙帶回來給我，我會付給你酬勞的。它平常就在湖畔鎮西南的田邊閒逛，但有時候也會跑進我的花園裡來。",objectives={"湖畔鎮的瑪蒂·詹羅斯要求你殺死貝利格拉布，並帶回它的獠牙作為證明。"}]])
R(35,"衛兵托馬斯",[[description="如果你擔心關於魚人的傳言可能屬實的話，就去一趟艾爾文森林東部的橋邊和衛兵湯瑪斯談談吧。他最近一個星期都駐紮在那裡，應該很瞭解那個地區的情況。$B$B搞清楚事態之後，把他的報告帶給我。",objectives={"治安官杜漢要你和衛兵湯瑪斯談話。"}]])
R(36,"雜味燉肉",[[description="我從來沒有想過有一天會被迫離開我的農莊。但是現在，那些滿是小賊和強盜的田地對我們來說已經是太過危險了。等法布隆修好他的車之後，我們就要逃離這裡了。$b$b或許你能幫我一個小忙？先讓我把我的獨家絕活雜味燉肉的食譜給抄下來，然後你幫我把它交給薩爾瑪·薩丁。薩丁農場就在路口的另一邊。",objectives={"弗娜·法布隆要求你將她的雜味燉肉食譜交給薩爾瑪·薩丁。"}]])
R(37,"失蹤的衛兵",[[description="A few days ago we sent two Guards, Rolf and Malakai, to investigate along the river, and they have not yet returned.  To complete my report, I must know what happened to those men.$B$BTravel north along the river and find the guards... or their remains.",objectives={"Guard Thomas wants you to travel north up the river and search for the two lost guards, Rolf and Malakai."}]])
R(38,"雜味燉肉",[[description="來幫我完成這道西部荒野燉肉吧！拜託啦，幫我找到這些材料：$b$b3塊禿鷲肉$b3個血牙野豬的鼻子$b3顆魚人的眼睛$b3棵秋葵",objectives={"薩爾瑪·薩丁需要3塊禿鷲肉、3個血牙野豬的鼻子、3顆魚人的眼睛和3棵秋葵。"}]])
R(39,"托馬斯的報告",[[description="Tell Marshal Dughan of Malakai and Rolf's deaths, and report to him that the Murlocs in eastern Elwynn cannot be contained by our current troop presence.$B$BI know we don't have many troops to spare, but hopefully Dughan can find someone.",objectives={"Report to Marshal Dughan in Goldshire."}]])
R(40,"魚人的威脅",[[description="$N，艾爾文森林又遇到新的威脅了！魚人正陸續從東艾爾文森林的河流裡遊過來，把魚嚇跑了之外，還攻擊平民！$B$B我曾經向治安官杜漢提出警告，不過他顯然更擔心那些豺狼人和強盜，而且他不相信魚人能有多危險。$B$B請你和杜漢談談吧，$N，說服他派遣更多的部隊到東邊來！",objectives={"雷米要你去和閃金鎮的治安官杜漢談話。"}]])
R(45,"羅爾夫的下落",[[description="進一步檢查這個地區之後，你發現有蹼狀的腳印沿著石碑湖岸向東延伸。在東邊較遠處，你隱約看見有一個魚人村落。$B$B也許羅爾夫的命運就在那裡劃下了句點……",objectives={"到魚人村去尋找羅爾夫，或是他死亡的証明。"}]])
R(46,"懸賞魚人",[[description="The Stormwind Army has placed a bounty on murloc lurkers and foragers in Elwynn.  Slaughter them and bring me their torn murloc fins, and the Stormwind Army will reward you well.$B$BThe murlocs have built a village at Stone Cairn Lake north of here, and another to the south where the stream forks.",objectives={"Bring 8 Torn Murloc Fins to Guard Thomas at the east Elwynn bridge."}]])
R(47,"金砂交易",[[description="這一帶的狗頭人有時會帶著金砂出來活動。我真的很需要這些金砂……給我找一些來，我會以鎮子裡最高的收購價格買下來——最高的價格！",objectives={"幫閃金鎮的雷米收集10袋金砂，你可以從艾爾文森林的狗頭人身上找到金砂。"}]])
R(48,"琥珀酒",[[description="高高的葡萄樹生長在南方$b蜿蜒的清泉流過樹根旁$b純淨的宛如女神的眼淚$b你快點去給我弄來聖泉水！",objectives={"帶聖泉之水給葛瑞姆·雷釀。"}]])
R(49,"琥珀酒",[[description="琥珀的顏色是我畢生之愛$b就像天邊夕陽下的雲彩$b為了它的誕生呀，勇敢的少年我召喚你$b我要一袋黑麥、大麥和玉米！",objectives={"葛瑞姆·雷釀需要大麥、黑麥和玉米各一袋。"}]])
R(50,"琥珀酒",[[description="I'll mix and mix till we have a mash$bFor this will be our own private stash$bA still must be fashioned of metal strong$bBring me some Truesilver so I can finish this song.",objectives={"Grimbooze Thunderbrew wants Truesilver."}]])
R(51,"琥珀酒",[[description="Not yet filtered but freshly distilled$bLike unseeded land waiting there tilled.$bNext I will fashion our pile of charcoal$bDeliver a sycamore branch, that is your next goal.",objectives={"Bring a Sycamore Branch to Grimbooze Thunderbrew."}]])
R(52,"保衛邊境",[[description="你好，$N。離開閃金鎮越遠，在森林裡遇到的野生動物就越兇猛。東谷伐木場幾乎每天都要受到狼和熊的攻擊！$B$B我們非常需要你的幫助。",objectives={"殺掉8隻覓食的灰狼和5隻年幼的森林熊，然後回到東艾爾文森林的橋邊去找衛兵湯瑪斯。"}]])
R(53,"琥珀酒",[[description="Mellifluous liquid clear as a baby's tears$bTurns a lovely deep amber over the years$bBut before we proceed to get lit to the hilt$bA barrel of charred oak must be built.",objectives={"Bring Grimbooze Thunderbrew a bundle of Charred Oak."}]])
R(54,"去閃金鎮報到",[[description="$N, you are a $c with proven interest in the security of Northshire.  You are now tasked with the protection of the surrounding Elwynn Forest.$B$BIf you accept this duty, then I have prepared papers that must be delivered to Marshal Dughan in Goldshire.  Goldshire lies along the southern road, past the border gates.",objectives={"Take Marshal McBride's Documents to Marshal Dughan in Goldshire."}]])
R(55,"摩本特·費爾",[[description="摩本特·費爾的老巢就在一個可以俯視烏鴉嶺墓園的山頂上。他的日子就快要到頭了……$B$B殺掉他，讓我們不被他的邪惡所侵害。為我復仇吧，也為了夜色鎮的人民！",objectives={"對摩本特·費爾使用摩本特的剋星，殺掉他，然後把摩本特的剋星交給斯溫。"}]])
R(56,"守夜人",[[description="作為守夜人的指揮官，我發過誓要保衛夜色鎮人民的安全。暴風城已經把他們駐守在這裡的部隊撤了回去，現在我們只能依靠自己了。$b$b如果你覺得可以勝任這份工作，就請幫助我們吧！到夜色鎮南部的靜謐花園去，殺掉8個骷髏戰士和6個骷髏法師。我們必須儘量減輕這些不死生物所帶來的威脅！",objectives={"夜色鎮的指揮官奧瑟·埃伯洛克要你去殺掉8個骷髏戰士和6個骷髏法師。"}]])
R(57,"守夜人",[[description="$N，我收到報告說有不死生物在森林裡出沒！如果你能應付的話，就到烏鴉嶺的大墓地去殺15個骸骨魔和15個恐怖骸骨。另外，就在夜色鎮南部的靜謐花園一帶也都發現有骷髏出沒。我們一定要把這些不死生物趕出暮色森林！",objectives={"指揮官奧瑟·埃伯洛克要你去殺死15個骸骨魔和15個恐怖骸骨。"}]])
R(58,"守夜人",[[description="烏鴉嶺的形勢仍然十分嚴峻，夜色鎮的安全繫在你的手上，$N。我沒有足夠的人手來保衛夜色鎮的安全。你必須再次到烏鴉嶺去除掉20個在東部的墓裡的瘟疫食屍鬼。",objectives={"夜色鎮的指揮官奧瑟·埃伯洛克要你到烏鴉嶺的東部陵墓去殺20個瘟疫食屍鬼。"}]])
R(59,"布甲和皮甲",[[description="For your shrewdness and valor, I have a marker here that is good for one piece of armor.  I want you to take it to Sara Timberlain at the Eastvale Logging Camp.  Give her the marker, and she will fashion the armor for you.  And after you receive it, $N, use it in the defense of Elwynn.$B$BThe Eastvale Logging Camp is beyond Guard Thomas' post to the east.",objectives={"Give Sara Timberlain the Stormwind Armor Marker."}]])
R(60,"狗頭人的蠟燭",[[description="你好，$g親愛的先生:尊貴的女士;！你有時間嗎？$B$B我和我兄弟在暴風城開了間藥店，我現在正在這一帶收集些大蠟燭，以便提取其中的蠟。你能幫助我嗎？$B$B你可以在狗頭人的身上找到大蠟燭，我聽說在艾爾文森林的礦坑一帶有很多狗頭人……在南邊的法戈第礦坑和東邊的玉石礦坑裡也有不少。我建議你去這兩個礦坑裡看看。",objectives={"幫閃金鎮的威廉·匹斯特收集8支大蠟燭。"}]])
R(61,"送往暴風城的貨物",[[description="My brother Morgan is waiting in Stormwind for my shipment of candles.  I don't have enough time to make the trip myself, but if you'd like to take him the shipment, he'll pay you well.$B$BI've packed up the candles, and you can find Morgan in our shop, Pestle's Apothecary, in the Stormwind Trade District.",objectives={"Bring William's Shipment to Morgan Pestle in the Stormwind Trade District."}]])
R(62,"法戈第礦洞",[[description="出問題的還不止北郡的礦坑！我接到報告說艾爾文森林的法戈第礦坑已經成了狗頭人的天堂。$B$B去那裡查看一下這些報告是否屬實，然後回來告訴我。法戈第礦坑就在閃金鎮的正南方，斯通菲爾德農場和馬科倫農場之間。",objectives={"調查法戈第礦坑，然後回到閃金鎮去見治安官杜漢。"}]])
R(63,"水之召喚",[[description="Along the coast of Silverpine, west of the Sepulcher, you will find a shrine that has become tainted by the plague. The spirits there no longer speak to our people and it will be up to you to defeat the manifestation and cleanse the pool.$B$BTake the elemental's bracers, along with the remaining drops of Brine's potion, and place them on the brazier. The ritual should be enough to summon a pure spirit for you to communicate with.$B$BBring me proof the task is done, and I will reward you with your totem.",objectives={"Defeat the Corrupt Manifestation of Water and place the Corrupted Manifestation's Bracers along with the Remaining Drops of Purest Water on the Brazier of Everfount in Silverpine Forest."}]])
R(64,"遺失的懷表",[[description="太可怕了！弗娜一聽到田裡的騷動就把我叫醒了。田裡全都是小流氓。我們只能連夜逃出來，結果我就把我的懷錶給忘在家裡了。那隻懷錶是弗娜的爸爸在我們結婚那天送給我的，我可不想讓它落在那些盜賊手裡。我把那隻錶放在小農舍的衣櫃裡，就在西邊的那片南瓜田邊上——不可能找不到的。如果你能把它拿回來給我，我會對你感激不盡的！",objectives={"農夫法布隆希望你能幫忙找回他的懷錶。懷錶放在西邊南瓜田旁邊的農舍衣櫃裡。"}]])
R(65,"迪菲亞兄弟會",[[description="那群自稱為迪菲亞兄弟會的流寇賊子將我們這些善良的平民趕離西部荒野，他們一定要為自己的罪行負責！我要求你去打探一下，我們必須知道到底誰是他們的頭兒，還有他們都藏在哪兒。在湖畔鎮的旅館裡有個叫威利的小賊以前欠了我一個人情，你可以找他幫忙。$b$b到艾爾文森林東邊的赤脊山去吧，湖畔鎮就那座山的腳下，到那裡去碰碰運氣。",objectives={"格里安·斯托曼要求你去和湖畔鎮的威利談話。"}]])
R(66,"斯塔文的傳說",[[description="Last night a horrible disturbance rippled through my veins.  I sensed that my granddaughter, Alyssa, was in great danger.  I consulted the cards and Death stared up at me from the table.$b$bAfter taking a long journey through a dark trance I was able to uncover a clue to this terrifying mystery.  A name came to me, the name of Stalvan.$b$bSeek out the Clerk in the Town Hall and see if you can find out more about this character.  I fear for us all.",objectives={"Seek out the Clerk Daltry in the Darkshire Town Hall."}]])
R(67,"斯塔文的傳說",[[description="斯塔文？讓我查查鎮裡的記錄。$b$b斯塔文…斯塔文…讓我找找……啊，找到了！這裡有份斯塔文·密斯特曼托的檔案。記錄上最後地址是在月溪鎮的學校裡。哎呀，都是過時的東西了！$b$b朋友，你能幫我個忙嗎？如果你碰巧路過月溪鎮的話，也許能找到一些有關這個傢伙的新消息，別忘了告訴我一聲，好讓我更新檔案。",objectives={"到月溪鎮的學校尋找關於斯塔文的新資訊，給書記員官達特利。"}]])
R(68,"斯塔文的傳說",[[description="你在舊手提箱裡找到了一封覆滿灰塵的信。",objectives={"把覆滿灰塵的信交給書記官達特利。"}]])
R(69,"斯塔文的傳說",[[description="哎呀！我上次肯定漏掉這個了。斯塔文檔案中的第一個地址下面還有另一個地址，這個地址被擦掉了一部份。看起來他好像去閃金鎮的獅王之傲旅店了。去那裡查查看吧，$N。",objectives={"到獅王之傲旅店去問問那裡的人，看看他們是否聽說過斯塔文這個人。"}]])
R(70,"斯塔文的傳說",[[description="斯塔文這個名字讓我想起點什麼…哦，我想起來了！$b$b很多年前的一個雷雨交加的夜晚，有個信差到這兒來借宿。快到午夜12點的時候，他一邊尖叫著一邊從樓上跑下來，蒼白的臉上滿是惶恐的神情，最後他穿著睡衣消失在傾盆的大雨中。$b$b由於走得太匆忙，他忘了拿走樓上箱子裡的信。他後來也沒有再回來拿走。其中一封就是那斯塔文寫給一個住在暴風城運河區的朋友的信，你自己拿去看吧。",objectives={"從箱子中拿走斯塔文未寄出的信，把它送到暴風城的運河區。"}]])
R(71,"回復托馬斯",[[description="Now that you have both medallions, deliver them to Guard Thomas at the bridge so that he might know the fate of his murdered guards.",objectives={"Deliver Rolf and Malakai's Medallions to Guard Thomas at the eastern Elwynn bridge."}]])
R(72,"斯塔文的傳說",[[description="我父親從前是這幢宅子的管家，在那場大屠殺之後，他費了好大的工夫才把地上的血跡清乾淨，不過這跟我們要談的事情沒什麼關係。$b$b弗林特雷家的基金早就用光了，現在家裡最後的財產也都已經準備要拍賣掉了，那些像禿鷲一樣貪婪的徵稅官！你要是真想找些什麼資料，不妨在這堆垃圾裡找找看，天知道你能找到什麼。",objectives={"在打包的東西裡尋找線索。"}]])
R(73,"<TXT> No Reward")
R(74,"斯塔文的傳說",[[description="你在箱子裡找到了幾樣東西：一些有霉味的、看起來像是傳家寶的東西，一副家庭肖像畫，一些打獵所得的戰利品和幾本舊書。在箱子底部的一個花瓶下面，你找到了一頁破損的日記。",objectives={"你找到的這張被撕破的日記書頁又提供了你一個線索。"}]])
R(75,"斯塔文的傳說",[[description="我剛搬進來的時候發現樓上的箱子裡有一捆羊皮紙，我想看看那些羊皮紙上寫了什麼，但是我的視力卻讓我只能看到一團迷濛。$b$b幫我這個快瞎了的老人一個忙吧，去檢查一下樓上箱子裡的東西，看看有沒有什麼有關那個斯塔文的資訊。我記得有一頁褪色的日記，你肯定會對它感興趣的。把它拿過來，我會盡力幫助你的。",objectives={"治安官哈迦德要你從樓上的箱子裡找出一頁褪色的日記。"}]])
R(76,"玉石礦洞",[[description="感謝你，我們現在可以知道法戈第礦坑確實被狗頭人佔據了。現在我們還需要一個人去更遠處的玉石礦坑偵察。$B$B去查看一下玉石礦坑，確定那裡是否有狗頭人。向東沿著大路走，一直走到阿祖拉之塔，然後往北走就會看到山腳下的礦坑。",objectives={"查看玉石礦坑，然後回到閃金鎮去向治安官杜漢報告。"}]])
R(77,"收集蜜糖",[[description="I possess original packaging materials for the ripple Dran Droffers seeks.  I will assist you in packaging the ripple for Malton's abrasive father... for a fee of two additional bottles of said ripple.  They are located in crates found in the abandoned Horde base near Skulk Rock.$B$BIt will be an arduous task, to wit; foul slimes and oozes will be found sticking to the ruins; rumor has it they are led by some sort of master ooze.  Regardless, procure the ripple and return to me here for packaging.",objectives={"Recover 10 bottles of Hinterlands Honey Ripple from the crates located around the abandoned Horde base in Skulk Rock."}]])
R(78,"斯塔文的傳說",[[description="我知道有誰可以幫你。我以前帶領暴風城衛隊的時候，經常去夜色鎮的血鴉旅店喝酒。那兒的老闆史密茲對當地的情況瞭若指掌。把這張東西給他，看看他有什麼看法。",objectives={"把褪色的日記內頁帶給旅店老闆史密茲。"}]])
R(79,"斯塔文的傳說",[[description="多年來我一直在追尋這個斯塔文的消息。幾年前那些來訪的貴族被殺之後，我曾和哈迦德一起去調查。我發現了這些沾滿淤泥的日記，但是一直沒有辦法把這上面的筆跡和樹林裡的那個瘋子聯在一起。你提供的線索證明了他的罪行。趕快把這個交給指揮官奧瑟·埃伯洛克，告訴她你所發現的一切。",objectives={"把沾滿淤泥的日記內頁交給指揮官奧瑟·埃伯洛克。"}]])
R(80,"斯塔文的傳說",[[description="有一段時間我一直注意著斯塔文這個討厭的傢伙。如果這些東西都是他寫的，那就足以給他定罪了。$b$b書記員達爾塔多年以來一直負責著鎮裡的檔案，他很擅長辨認筆跡。把這張紙給他，看看是否和檔案裡面斯塔文的簽名筆跡相吻合。",objectives={"把染血的日記書頁交給書記員達爾塔。"}]])
R(81,"送回蜜酒",[[description="I have taken the extra step of securing not only Dran's packaged ripple in the barrel, but also the extra bottles of ripple he is purloining.  While I may not hold Dran very highly, there is nothing worse than jostled ripple.  You're welcome.$B$BNow, deliver yon barrel to Dran Droffers in his salvage emporium in Orgrimmar.  Pray tell, please extend my warmest greetings to Malton; let him know that should he ever thirst for fine drink and finer drinking companions, we would be honored with his visit.",objectives={"Deliver the barrel to Dran Droffers in Orgrimmar."}]])
R(82,"腐化之巢",[[description="好，你的報告中提到了蟲子……我們現在知道的是它們正在吸乾原本是腐化之巢所在區域的水池，但其他方面我們完全一無所知。$B$B讓我們先搞清楚敵人到底是誰！你得去腐化之巢那裡弄些蟲子的肢體回來給煉金術士匹斯特蘇格研究，有他的幫忙，我們就可以確定到底是誰在那裡搞鬼了！",objectives={"從腐化之巢找5個森提帕蟲的肢體，把它們交給加基森的煉金術士匹斯特蘇格。"}]])
R(83,"紅色亞麻布",[[description="北郡的迪菲亞盜賊戴的是粗麻布面罩，而艾爾文森林的迪菲亞盜賊戴的則是亞麻布做的，我可以用這些亞麻布做些不錯的東西。$B$B給我些亞麻布面罩，我就可以做點什麼給你。$B$B迪菲亞盜賊在整個艾爾文森林地區都有營地。",objectives={"帶去6塊紅色亞麻布面罩給東谷伐木場的薩拉·迪博雷恩。"}]])
R(84,"比利的餡餅",[[description="Here you go.  And when you give this pie to that Billy, you tell him I hope he chokes on it!",objectives={"Bring the Pork Belly Pie to Billy Maclure at the Maclure Vineyards."}]])
R(85,"丟失的項鏈",[[description="我的項鏈不見了，一定是那個討厭鬼比利·馬科倫拿走的！他總是像隻老鼠一樣在東邊的馬科倫農場裡竄來竄去。$B$B請把我的項鏈拿回來給我，讓我這可憐的寡婦得到一些安慰吧。",objectives={"和比利·馬科倫談話。"}]])
R(86,"比利的餡餅",[[description="Maybe if I got a pie, I could tell you who has that necklace.  And you know, I think that old Bernice lady at that other farm makes great Pork Belly Pies... $B$BMaybe if you gave her some chunks of boar meat from the boars that hang around our farms, and told her what it was for, she'd bake up a pie for you.",objectives={"Bring 4 Chunks of Boar Meat to Auntie Bernice Stonefield at the Stonefield's Farm."}]])
R(87,"金牙",[[description="我在法戈第礦坑旁邊玩的時候，好像不小心弄掉了那條，呃……我是說我看見了老太太的那條項鏈。別問我它怎麼會跑到那兒去……和我沒有關係！$B$B不管怎樣，我看到一個很壯碩，鑲著金牙的狗頭人……撿起項鏈跑到礦坑裡了。你去找那個狗頭人吧，我發誓，你肯定能在他身上找到項鏈的！",objectives={"把波尼斯的項鏈帶給斯通菲爾德農場的波尼斯·斯通菲爾德。"}]])
R(88,"公主必須死！",[[description="布拉克威爾一家有一頭得過獎的豬，它名叫「公主」。這頭母豬巨大無比，還經常偷偷溜到我的農場裡偷吃我的蔬菜！$B$B在它再次糟蹋了我的農場之前……必須把它給宰了！把它的項圈帶回來證明你殺了它，我會給你一些獎賞的！$B$B公主一般在布萊克威爾南瓜田出沒，那個南瓜田就在東邊，比馬科倫農場還要往東。在它肚子餓了之前殺死她，然後再回來告訴我！",objectives={"殺掉公主，把它的項圈帶給斯通菲爾德農場的斯通菲爾德媽媽。"}]])
R(89,"止水湖上的橋",[[description="上次獸人入侵的時候，我們被迫把所有能找到的鐵都熔了來製造子彈、刀劍和盔甲。我們向暴風城請求援助，讓他們運一些材料過來。誰料一群赤脊山豺狼人劫持了這批貨物，並逃進了湖畔鎮後的山中。$b$b這樣一來，我們這座橋的重修工程馬上就要面臨缺少材料的困境了。如果你能給我帶回5根鐵矛和5個鐵鉚釘，我一定會獎勵你的。$b$b快點去吧！",objectives={"帶5根鐵矛和5個鐵鉚釘給湖畔鎮的工頭奧斯洛。"}]])
R(90,"幹烤狼肉串",[[description="烤狼肉串是道家喻戶曉的美食！我當然可以為你做一些，不過得先有材料。給我找些暴風城特製調味料和10塊狼肋排。這兒的森林裡遍地都是狼，想找點肋排肯定不是問題。至於調味料，你得到暴風城運河區的花店裡去找菲利希亞·加姆。",objectives={"收集10塊狼肋排和1份暴風城特製調味料，再回夜色鎮去找格魯奧廚師。"}]])
R(91,"所羅門的律法",[[description="暴風城的敵人在赤脊山東側的山腳下建立了一片營地，這個無賴利用秘術不斷的對我們小鎮及人民傳播著恐懼和悲痛。莫甘斯，就是這群惡徒的首領。$b$b他控制了暗皮豺狼人氏族，讓那些邪惡的野獸為他賣力。根據湖畔鎮的法律規定，救助王國的罪犯是可以被判處死刑的。$b$b這些骯髒的豺狼人一定要被處死！$b$b交10個暗皮墜飾回來給我，你就可以得到獎勵。",objectives={"帶回10個暗皮墜飾給湖畔鎮大廳的拜里弗·科納徹爾。"}]])
R(92,"赤脊山燉肉",[[description="Nothing would please me more than to make you some Redridge Goulash. But there's a slight problem. During the recent orc uprising I fed the entire brigade of Stormwind troops. My cupboard is now bare. But if you can provide me with the ingredients, I'd be happy to oblige.$b$bJust bring me five pieces of Tough Condor Meat, five Great Goretusk Snouts and five helpings of Crisp Spider Meat.",objectives={"Chef Breanna of Lakeshire wants five pieces of Tough Condor Meat, five Great Goretusk Snouts and five helpings of Crisp Spider Meat."}]])
R(93,"黑蟹蛋糕",[[description="我可以告訴你一個小秘密——黑「螃蟹」蛋糕實際上是用蜘蛛腿做的！我知道這聽起來有點噁心，不過這種蛋糕的味道絕對芳香美味而且是很好的點心！幫我找點黏糊的蜘蛛腿來，我很快就能做好給你。$B$B我聽說結網毒蜘蛛身上很容易拿到這種東西——它們的巢穴就在北邊，在山丘和小河之間。",objectives={"收集6條黏糊的蜘蛛腿，把它們交給夜色鎮的廚師格魯奧。"}]])
R(94,"法師的眼線",[[description="我的對手莫甘斯是個強大而邪惡的法師，他就住在赤脊山的伊爾加拉之塔里。我已經找到了一種監視他的方法，只要通過阿祖拉之眼，就可以在很遠的地方看到他的一舉一動。$B$B不過要研究他的思想……我還需要進一步的幫助。$B$B如果你願意的話，就帶著這個銘文飾品到伊爾加拉之塔去，把它放置在塔旁邊的獅子雕像身上。$B$B完成之後，阿祖拉的銘文飾品就會告訴我們，莫甘斯又在準備什麼邪惡的計畫。",objectives={"把阿祖拉的銘文飾品放置到赤脊山伊爾加拉之塔旁邊的獅子雕像身上。"}]])
R(95,"斯溫的復仇",[[description="我原來在東南部的一座農場裡工作……直到有一天，從逆風小徑來的黑暗強盜洗劫了我的農場，趁我不在的時候殺了我的全家！$B$B我回來時發現有個模糊的人影在我家的谷倉附近埋了一件什麼東西，可惜我沒能抓住他。我也不敢在這裡繼續逗留，因為我害怕會有黑暗強盜追蹤我。直到現在，我都都不知道那人到底藏了什麼。$B$B如果你能去找出真相，我一定會感激你的。那人埋東西的地方就在我的谷倉附近的一個老樹樁後面。",objectives={"到斯溫的農場去找出埋在老樹樁後面的是什麼東西。"}]])
R(96,"水之召喚",[[description="Take shard. Take shard and give life.$B$BGive life and understand. Understand water is life... corruption stops life.$B$BYou protect and give life with water's power.",objectives={"Bring the Shard of Water to Islen Waterseer in the Barrens."}]])
R(97,"斯塔文的傳說",[[description="$N，趕快去告訴指揮官奧瑟·埃伯洛克，這兩個筆跡完全符合！她的懷疑是正確的！",objectives={"把這個消息告訴指揮官奧瑟·埃伯洛克。"}]])
R(98,"斯塔文的傳說",[[description="斯塔文·密斯特曼托是個惡貫滿盈的罪犯，很多無辜的人都死在他手中。毫無疑問，他犯下了無數宗的罪案，現在這個瘋子威脅到夜色鎮了。天知道這個惡棍又在策劃什麼邪惡的行動。斯塔文的家就在小鎮北邊，$C，為我一勞永逸，去把他就地處死吧。$b$b完成以後把他的家族戒指交給伊瓦夫人作為證明，畢竟是她的預感才讓我們發現這個可怕的兇手，因為她夜色鎮才能更安全。",objectives={"幹掉斯塔文·密斯特曼托，把他的家族戒指交給伊瓦夫人。"}]])
R(99,"阿魯高的愚行",[[description="在我對阿魯高的魔法越來越瞭解的同時，我對這個蠢貨的鄙視與輕蔑也日益加深。我已經快要完成對他所謂的「拯救行動」研究。$b$b在我瞭解到底是什麼樣的巫術導致了焚木村的奇怪現象之後，我就算是完全瞭解透徹了。白天，那些農夫們都是好端端的人。但太陽一下山，他們就變成了月怒狼人。$b$b我需要從阿魯高給他們戴上的魔法鐐銬中汲取一些能量。帶6副焚木鐐銬來給我，$N。",objectives={"帶6副焚木鐐銬給瑟伯切爾的達拉爾·道恩維沃爾。"}]])
R(100,"水之召喚",[[description="Light explodes as you finish the incantation. The sounds of the water drops hitting the flame have died down and your senses are overcome as the corrupt spirits around you are destroyed.",objectives={"Speak to the Minor Manifestation of Water in Silverpine Forest."}]])
R(101,"懲罰圖騰",[[description="有一股神秘而邪惡的勢力在森林裡蔓延，我們必須更加小心地保護自己，$N。風兒悄悄的告訴我，他們說有一個很巨大的危機正在不遠的將來耐心地等候著你。$b$b尊貴的$c，如果你想保護自己，就帶10顆食屍鬼的牙齒、10根骷髏的手指和5瓶蜘蛛毒液來給我。我會為你製作一個懲罰圖騰，讓那些企圖傷害你的敵人自食惡果。",objectives={"收集10顆食屍鬼的牙齒、10根骷髏的手指和5瓶蜘蛛毒液，把它們交給夜色鎮的伊娃夫人。"}]])
R(102,"西部荒野的豺狼人",[[description="暴風城已經把我們給遺棄了。一股腐朽與墮落的狂風正肆虐在西部荒野的平原之上。這裡是我的故鄉，我絕對不會背叛那些和我一樣堅持留在這裡的民眾們。我們這些農夫必須站出來，為自己贏得生存的空間。$b$b若你願意接受我們派給你的任務，就去巡視西部荒野的草原吧。找到那些可惡的狗頭人，把它們除掉，這些傢伙似乎與死亡礦坑裡的小賊們有些聯繫。帶八隻豺狼人的爪子回來給我，我會獎勵你的英勇行為的。",objectives={"帶8隻豺狼人的爪子給哨兵嶺的丹努文隊長。"}]])
R(103,"長明的燈塔",[[description="燈塔管理員一家被殺的那一個晚上實在是太可怕啦！我只能眼睜睜地看著老瞎眼帶著那群魚人毀了他們全家，但卻幫不上任何忙。但過去的事就讓它過去吧，我現在關心的是無盡之海中那些正把船隻駛近暗礁水手們的生命。如今，維持著燈塔上火炬不熄滅的任務就落在我一個人身上了。$b$b幫我從那些收割機器人身上找來5瓶燈油吧，這樣我才能讓火炬繼續照亮下去。",objectives={"帶回5瓶燈油給西部荒野燈塔中的葛瑞森船長。"}]])
R(104,"海岸上的威脅",[[description="當我的生命終結在了那片岩石上之後，我根本不知道死後的世界會是怎樣的。那天晚上的燈塔一片漆黑，因為老瞎眼嚇跑了管理員全家。他們後來又回來想要點亮燈塔，但是老瞎眼迫使一群意志薄弱的魚人突襲了燈塔。這一次，管理員全家沒那麼幸運了，他們都在我面前無助地死去。$b$b如果你在海岸邊看到老瞎眼的話，就殺死它，把它的鱗片帶一片回來給我，我會獎勵你的。",objectives={"將老瞎眼的鱗片交給西部荒野燈塔旁的葛瑞森船長。"}]])
R(105,"啊，安多哈爾！",[[description="啊，進攻安多哈爾並徹底擊敗那個巫妖的時刻終於來臨了！$B$B你這個城市的廢墟裡就是巫妖 - 召喚者阿拉基統治的地方。無數的天譴軍團守護在城中心的廢墟周圍，而他的貼身隨扈守衛更是令人畏懼。你需要帶眾多的盟友前往才可能有機會成功挑戰它。$B$B消滅阿拉基，$N，從它的護符匣裡拿出一塊碎片來，作為你獲勝的證據！",objectives={"把阿拉基的護符匣碎片交給西瘟疫之地亡靈壁壘的高級執行官德靈頓。"}]])
R(106,"年輕的戀人",[[description="天哪，我太痛苦了！我愛上了湯米·喬·斯通菲爾德，但我們兩家卻有著不共戴天的仇恨。所以我不能去見他，可是我無時無刻不在想念那張英俊的臉孔啊！$B$B請你把這封信交給湯米·喬，他一般會在斯通菲爾德農場西邊的河流附近，他們的農場就在這裡的正西方。",objectives={"送梅貝爾的情書給湯米·喬·斯通菲爾德。"}]])
R(107,"給威廉·匹斯特的信",[[description="I bet William Pestle has a potion to unite our two young lovers!$B$BHere, take this note to William.  He's staying at the Lion's Pride Inn in Goldshire.",objectives={"Take Gramma Stonefield's Note to William Pestle."}]])
R(108,"<TXT> Mystery Reward")
R(109,"向格裏安·斯托曼報到",[[description="看起來你參加過不少戰鬥，$c。如果你還沒有去格里安·斯托曼那裡報到的話，就趕快去吧。他是人民軍的領袖，這是個專門負責保衛西部荒野的民兵組織，我敢說你是能幫他一些忙的。一般來說，你可以在哨兵嶺的石塔周圍找到他，那地方就在西部荒野中部的路邊上。",objectives={"去和格里安·斯托曼談一談，他一般就在哨兵嶺的石塔旁，這座石塔位於西部荒野中部地區的路邊。"}]])
R(110,"昆蟲研究",[[description="我要花點時間檢視一下謝申克的調查裝備……然後把他的東西整理一下。我有預感我們還有更多的損失。$B$B我希望你去見見煉金術士匹斯特蘇格，瞭解一下他是不是已經研究過我們給他的昆蟲肢幹了。如果他已經完成了，就向我回報。",objectives={"到加基森的煉金術士匹斯特蘇格那裡去瞭解關於昆蟲的研究有沒有新的進展。"}]])
R(111,"托米的祖母",[[description="Please, $N, talk with my Gramma.  If anyone can find a way to bring me together with Maybell, she can.$B$BShe's inside our house east of here.",objectives={"Speak with Gramma Stonefield."}]])
R(112,"收集海藻",[[description="I can make an invisibility liquor for Maybell, so she can slip away from the Maclure Vineyards and go to Tommy Joe.  But to make the Liquor, I need some crystal kelp.$B$BAlthough the kelp usually grows in the ocean... sometimes murlocs collect it.  See if the murlocs near Crystal Lake have any.  Crystal Lake is just east of Goldshire.",objectives={"Bring 4 Crystal Kelp Fronds to William Pestle in Goldshire."}]])
R(113,"昆蟲研究",[[description="資深勘查員菲茲杜瑟必須立刻看到這份報告。實際上……每個識字的人都應該看看這份報告：我們正面臨著一個巨大的威脅，這個威脅不僅僅涉及到塔納利斯和加基森，如果不及時處理的話，整個卡林多大陸的南部地區都會有麻煩！甚至整個艾澤拉斯大陸都會捲進去。而且這個威脅顯然不會就此平息。$B$B讓菲茲杜瑟把這份報告給你複製幾份，然後你去把它廣為傳播。一定要讓所有人都知道這個威脅的存在！",objectives={"把這份報告送給加基森的資深勘查員菲茲杜瑟，確認他有按照煉金術士匹斯特蘇格的要求複製一份報告給你。"}]])
R(114,"梅貝爾的隱形水",[[description="把隱形藥水交給梅貝爾·馬科倫。它的隱形效果應該可以持續到她見到湯米·喬。",objectives={"把隱形藥水交給梅貝爾·馬科倫。"}]])
R(115,"暗影魔法",[[description="黑石氏族的獸人在赤脊山脈的侵略行動得到了暗影法師的支援，他們帶著一種具有強大黑暗力量的器具—午夜寶珠。這些寶珠對赤脊山脈的防禦者們造成了巨大的傷亡，並迫使我們放棄所有在戰鬥中被這種寶珠污染了的物品。$B$B殺掉這些黑石暗影法師，把他們身上的午夜寶珠拿回來給我。我會把他們妥善地處理掉，還這世界一片清淨！",objectives={"帶3個午夜寶珠給湖畔鎮的治安官馬瑞斯。"}]])
R(116,"旱季",[[description="我最近真是感覺有點沒勁，$N。這些酒瓶子都快空了，運酒的船也很久沒來了，這都怪那些該死的獸人。$b$b也許你幫我一個小忙？$b$b我希望你能從住在西部荒野的葛瑞姆·雷酒那裡搞一桶雷霆啤酒，從暴風城搞一桶葡萄酒，從夜色鎮搞一瓶月光酒，還有還有，再從閃金鎮搞一袋蜂蜜酒來。把這些好酒都給我弄來，我會重重謝你的。",objectives={"湖畔鎮的酒吧老闆丹尼爾需要一桶雷霆啤酒，一桶葡萄酒，一瓶月光酒，還有一袋蜂蜜酒。"}]])
R(117,"雷霆啤酒",[[description="快點，朋友，動作要快$b釀出更多的酒來賣$b喝酒的人多吃菜的人少 $b想要釀酒就得要有蛇麻草。",objectives={"帶5束蛇麻草給葛瑞姆·雷釀以完成他的特製啤酒。"}]])
R(118,"馬掌",[[description="我用了很多的鐵用來打造暴風城衛兵的裝備，結果沒有足夠的鐵來打馬蹄鐵了！$B$B把這封信帶給閃金鎮的鐵匠阿古斯，信上說明了我現在的情況，並向他要一批馬蹄鐵過來。",objectives={"把弗納的字條交給閃金鎮的鐵匠阿古斯。"}]])
R(119,"回復弗納",[[description="好，我會給他50套馬蹄鐵……$B$B就在這裡，你看，全部都打包好了，隨時可以帶走！告訴弗納，我很高興和他做生意，哦，對了，提醒他看清楚箱子上的字條！",objectives={"回去赤脊山找弗納·奧斯古，把馬蹄鐵交給他。"}]])
R(120,"送往暴風城的信",[[description="These are trying times, $c.  The township is under constant siege.  Without reinforcements, we will certainly face defeat.  The message I now entrust to you is of utmost importance.  Get this report to General Marcus Jonathan of Stormwind immediately.  Once your delivery is made, return to me at once with any news, be it good or bad. $b$bNow make haste!",objectives={"Magistrate Solomon has given you a report which must be delivered to General Marcus Jonathan in Stormwind.  The judge wants you to return to him as soon as the delivery has been made."}]])
R(121,"送往暴風城的信",[[description="在我等待國王陛下的回應時，我希望你能把這封信交給所羅門鎮長。$b$b解散，$c！",objectives={"將馬庫斯·喬納森將軍的回信帶給湖畔鎮的所羅門鎮長。"}]])
R(122,"雛龍的鱗片",[[description="我需要一些黑色雛龍腹部的鱗片來支付從阿古斯那裡買馬掌的錢。如果你能幫我搞到6塊鱗片的話，在付給阿古斯一些以後……我還能用剩下的給你做點好裝備。$B$B黑色雛龍經常在湖畔鎮南方遊蕩，獵殺它們的時候要多加小心。",objectives={"從黑色雛龍身上收集6片雛龍的腹鱗，把它們交給赤脊山的弗納·奧斯古。"}]])
R(123,"收貨人",[[description="這是一張日程表，記錄了某個人被稱作「收貨人」的人在某天某時會收到從艾爾文森林的礦坑運來的一車黃金。$B$B根據日程表所述，這個收貨人好像就住在艾爾文森林東部的布萊克威爾南瓜田附近。$B$B這件事非常重要，你必須向閃金鎮的治安官杜漢報告。",objectives={"去閃金鎮找治安官杜漢，把收貨人的交易日程表交給他。"}]])
R(124,"豺狼人的亂吠",[[description="有一群整天攻城的獸人好像還不夠！最近又來了一群豺狼人蠻兵和秘法師，鬼鬼祟祟地在我的馬場北邊的山脊上遊蕩，而且還偷我走失的馬……$B$B如果你能把這些豺狼人都除掉的話，我和我的馬都會感謝你的。",objectives={"殺掉10名赤脊山蠻兵和8名赤脊山秘法師，然後回來找弗納·奧斯古。"}]])
R(125,"丟失的工具",[[description="我本來可以在這兒大幹一場的, $N。可是，我的工具還沒運到，由於這個小鎮被包圍了，我們很難得到外面來的補給。我本來託人從閃金鎮把工具用馬車運過來，可是橋被炸斷了，我們只好改用船運，結果那船又被獸人的投石車給打沉了。不過，我運氣不錯，我的工具箱沒壞，只是沉進了湖底。$b$b幫我把工具箱找回來吧，$N，我會付給你相當不錯的酬勞的。",objectives={"湖畔鎮的工頭奧斯洛希望你幫他找回沉入止水湖底的工具箱。"}]])
R(126,"群山中的嚎叫",[[description="$N，那些豺狼人還在那裡！我還能聽見他們在湖畔鎮周圍的山區裡打獵時發出的嚎叫聲。其中有一個聲音喊得最響——那是猶勒，他們的頭目。$B$B幹掉猶勒，把牠的手下都給轟走！把牠的爪子給我帶回來。$B$B不過你得小心點，這傢伙能當上他們的頭目自然是有兩把刷子的。猶勒可不是個低能的混血豺狼人的……",objectives={"將猶勒的爪子帶回給湖畔鎮的弗納·奧斯古。"}]])
R(127,"賣魚",[[description="止水湖之所以出名都是因為它的班點太陽魚。它們總是供不應求……可是我這裡的存貨已經不夠了！$B$B幫我帶回10條魚來，我會好好酬謝你的。哦，如果你不會捕魚的話……可以從魚人那兒搶來！",objectives={"帶10條斑點太陽魚給湖畔鎮的碼頭管理員巴倫。"}]])
R(128,"懸賞：黑石氏族",[[description="我們一定得摧毀黑石氏族。這群強盜入侵了我們的土地，佔據了本應屬於暴風王國的群山。根據線報，在他們的氏族中，每個分隊的首領都被稱為「勇士」，你可以很容易的在北方的營地中找到他們。就在通向燃燒平原的道路西邊。$b$b所羅門鎮長希望能把這群卑鄙邪惡的傢伙通通消滅。去殺死15名黑石勇士，然後回來向我覆命。",objectives={"殺死15名黑石勇士，並向湖畔鎮的衛兵豪威覆命。"}]])
R(129,"免費的午餐",[[description="你能幫我一個小忙嗎？我給衛兵派克準備好了午飯，可是他出去巡邏了……他是一個又高又壯的暴風城衛兵。他在外面是能自己保護自己的，可是像我這樣的尋常市民就不行了，$B$B所以呢，如果你能幫我把他的午餐帶給他的話，我也給你一份免費的午餐！派克就在通往暮色森林的路上巡邏。",objectives={"將衛兵派克的午餐帶給他，他就在通向夜色鎮的路上巡邏。"}]])
R(130,"尋訪草藥師",[[description="你回去找達希的時候，能替我帶幾朵花給她嗎？你可以在湖畔鎮西邊的草藥店裡買到花。$B$B不過，你去買花的時候……千萬別告訴瑪蒂這花是誰買的，也別說是要送給誰的……",objectives={"找到草藥師瑪蒂·詹羅斯並和她談話。"}]])
R(131,"水仙訴衷情",[[description="這是你要的花。我為你選了水仙，這是我最喜歡的花兒！",objectives={"將水仙花送給達希。"}]])
R(132,"迪菲亞兄弟會",[[description="我現在可是冒著生命危險在和你說話。迪菲亞那幫人也是聽命於某個神秘人士，我上次聽說他們與許多種族都有過合作，豺狼人，狗頭人，甚至還有哥布林。$b$b把這張字條交給斯托曼。上面寫著我所知道的關於迪菲亞兄弟會的一切。",objectives={"將威利的字條交給西部荒野的格萊恩·斯托曼。"}]])
R(133,"食屍鬼假人",[[description="I live so far from the protection of town, it's a wonder the ghouls and the walking dead haven't eaten me!  In fact, just yesterday a pack of Bone Chewers was pounding on the walls of my house!$B$BI want to make an effigy - a kind of \"scarecrow\" for Ghouls.  To do that I need some Ghoul Ribs.  You can get them from Flesh Eaters, Bone Chewers, Brain Eaters, Rotted Ones and Plague Spreaders.$B$BGet the ribs for me, and I will repay you with some coin.",objectives={"Gather 7 Ghoul Ribs and bring them to Abercrombie at his shack."}]])
R(134,"食人魔潛行者",[[description="幾個星期前，我離開家去遠處採草藥，有一群巨魔襲擊了我！我落荒而逃的時候丟棄了一箱珍貴的工具和草藥。$B$B這些巨魔在把我趕跑之後，就大搖大擺地回到了暮色森林南邊的巨魔丘上，我的箱子肯定就在那一帶。$B$B請幫幫我吧，$N，我很需要這個箱子，請你一定要幫我拿回來。",objectives={"把亞伯克隆比的箱子拿回來給他。"}]])
R(135,"迪菲亞兄弟會",[[description="我現在很想知道威利所提到的「石匠」是什麼意思，或許這只是一個口誤？石匠公會跟迪菲亞真的有聯繫嗎？原來只有暴風城軍情七處的首領馬迪亞斯·肖爾才知道真相。把威利的字條拿給他，看看他對這個越來越大的謎團有什麼想法吧。如果你找不到他，就去舊城區的兵營看看吧。",objectives={"將威利的字條交給暴風城的馬迪亞斯·肖爾。"}]])
R(136,"杉德爾船長的寶藏",[[description="如果你讀到這封信的話，那就意味著我，桑德爾船長，已經長眠在深深的水底了。所以，只要按照我的線索去做，我的寶藏就是你的了。$b$b首先你必須要找到我的手提箱，它應該就在西部荒野西邊海岸的某處船隻殘骸旁，如今應該八成都埋在沙裡了。海岸邊有許多處船隻的殘骸，但只有一隻沉船旁有個鏽掉的錨。找到錨你就找到箱子了！在箱子裡面，你可以找到下一條線索。",objectives={"找到桑德爾船長的手提箱，在箱子中尋找下一條線索。"}]])
R(137,"<NYI> <TXT> Stormwind Commendation",[[description="If you earn a commendation from one of our Marshals, then bring it to me.  It will be good for one of our Lion Emblem gloves.",objectives={"General Marcus Jonathan in Stormwind will accept a commendation from Elwynn Forest.  Bringing him such a document will reward you with a choice of armor."}]])
R(138,"杉德爾船長的寶藏",[[description="The clue to the treasure reads: Good work, matey!  Now ye need to head due east.  East up the bluffs, east to the road.  Look for the ol' chimney ruins near the side of the road.  There you'll find an old barrel with your next clue.",objectives={"Find the old barrel near the ruined chimney and search it for your next clue."}]])
R(139,"杉德爾船長的寶藏",[[description="Searching through the barrel you discover another piece of parchment.  This one reads:  Now from this here barrel, face ye North.  Straight as the crow flies, keep ye walkin' till you see the empty jug next to the lone windmill on the sea bluffs.  If ye poke around that jug, ye just might find what you're lookin' for.",objectives={"Search the empty jug next to the windmill for the next clue."}]])
R(140,"杉德爾船長的寶藏",[[description="Sure enough, deep within the Old Jug there is another clue to Sander's treasure.  The ink has run in some places and the paper smells like whiskey but you can make out some of the text:  Now that ye found me ol' whiskey jug, you're almost to the treasure!  Just face West from the bottle and walk down to the shore.  Once ye get to the water, keep going!  Swim straight west till you find the island with me treasure chest!",objectives={"Locate Captain Sanders' chest and open it for your reward."}]])
R(141,"迪菲亞兄弟會",[[description="過去的石匠公會是由一個名叫艾德溫·范克里夫的人所經營的。第一次獸人戰爭結束後，范克里夫承接下了在獸人們留下的廢墟上重建暴風城的重任。很顯然的，范克里夫對國王陛下在重建工程完成之後給予他們的待遇非常不滿意。這也許只能解釋其中一些事情。$b$b我已經寫了一份詳細的說明，要讓你拿到西部荒野交給你的老大。趕快拿去給他吧！",objectives={"將肖爾的報告交給西部荒野的格萊恩·斯托曼。"}]])
R(142,"迪菲亞兄弟會",[[description="我們必須找出迪菲亞兄弟會的巢穴。$N，我的探子報告說，迪菲亞幫的信差經常出現在月溪鎮、金海岸礦坑和詹戈洛德礦坑之間的路上。我希望你能抓住他，要是他試圖反抗，就把他殺了，然後把他身上所有的東西帶回來。",objectives={"追蹤西部荒野的迪菲亞信差，並將他身上攜帶的信件交給斯托曼。"}]])
R(143,"送往西部荒野的信",[[description="Something odd is afoot with the Stormwind Army.  They should have been here in force by now.  Time is a luxury we don't have, however.  I will not stand by and watch the people of Lakeshire give their lives without trying to enlist more help.  I've heard word of a people's militia forming in Westfall.$b$bTake this plea to their leader, Gryan Stoutmantle.  Perhaps Stoutmantle's men can lend some support here until the King sends reserves.",objectives={"Magistrate Solomon wants you to take his written plea to Gryan Stoutmantle in Westfall."}]])
R(144,"送往西部荒野的信",[[description="Magistrate Solomon's note pains me to read.  But it is obvious he knows not the war which is waged in Westfall or else he would know better than to expect aid from the Militia.  If Stormwind had not deserted us as well, we would not have the need for the Militia.$b$bTake this response to your master in Redridge, $c.  And let him know that my heart is heavy with the loss of good men.",objectives={"Return to Magistrate Solomon with Gryan Stoutmantle's response."}]])
R(145,"送往夜色鎮的信",[[description="看來我又有事要麻煩你了。我寫了封信給艾羅·埃伯洛克公爵，請求他派出他的精銳部隊——暮色森林守夜人——來協助湖畔鎮的防務。這封信必須馬上送去給他，你在旅途中要多加小心。埃伯洛克公爵是夜色鎮的行政官，那座小鎮就在暮色森林中，不要離開道路的範圍。",objectives={"所羅門鎮長要求你送一封信給夜色鎮的埃伯洛克公爵。"}]])
R(146,"送往夜色鎮的信",[[description="如果不是和所羅門鎮長私交甚密的話，我一定會以為他是個瘋子的。因為暴風城拒絕出兵援助，就讓我把守夜人部隊派去湖畔鎮？守夜人部隊就是因為暴風城這片土地被邪惡的魔法入侵時卻遺棄我們，所以才被建立起來的。如果我把他們派離這裡的話，恐怕還沒等到他們走出這片森林，這裡就會被邪惡的勢力徹底吞沒。$b$b把這封回信帶給你在湖畔鎮的主人吧。",objectives={"將埃伯洛克公爵的回信送回去給所羅門鎮長。"}]])
R(147,"獵殺收貨人",[[description="如果這個「收貨人」是私自從我們的礦坑裡開採黃金的話，那麼他就是在偷竊王國的金庫！把他就地正法，然後把他的交易日程表上提到的戒指帶給我。也許這枚戒指能告訴我們這個「收貨人」是在為誰工作……$B$B那張交易日程表上說「收貨人」就藏在布萊克威爾南瓜田裡，你應該到那兒去找他。",objectives={"找到「收貨人」並將他殺掉，然後帶著收貨人的戒指回來見治安官杜漢。"}]])
R(148,"來自夜色鎮的貨物",[[description="哦，一個可憐的老人家還能做什麼呢？我需要從夜色鎮弄點補給品，不過路途太遙遠，我又太老了……實在是走不動啊。$B$B你能去夜色鎮幫我拿點幽靈的髮絲回來嗎？你可以向伊娃夫人要這東西，她的家就在夜色鎮的廣場旁。",objectives={"和伊娃夫人談話。"}]])
R(149,"幽靈的發絲",[[description="有個可憐的亡魂叫盲眼瑪麗，她總是在夜色鎮南部山丘上的一間農宅裡出沒。$B$B拿著這把幽靈髮梳，去讓盲眼瑪麗用它梳頭。然後再把梳子拿回來，我可以從上面收集到需要的幽靈的頭髮。$B$B小心點，那個屋子附近潛伏著一些可怕的東西……",objectives={"把幽靈髮梳帶給盲眼瑪麗。"}]])
R(150,"魚人偷獵者",[[description="魚人們開始變成了一個問題。大群的魚人漁民在止水湖沿岸下錨撒網，都快把湖裡的魚撈光了！我們得在他們把湖裡的魚都吃光之前把他們趕走！$B$B去獵殺那些魚人！帶8片魚人的鰭回來給我，我會獎勵你的。",objectives={"帶8片魚人的鰭回來給湖畔鎮的碼頭管理員巴倫。"}]])
R(151,"老馬布蘭契",[[description="可憐的老布蘭契呀！我們讓牠承擔的工作實在是太多了，看來牠已經要累垮了。雖然我在離開農場以前就餵過牠，可是誰會料到馬車會在半路上壞掉呢？如果你能從田裡替牠拿幾捧燕麥的話，我會對你感激不盡的。我想你可以在西部荒野所有的農場邊找到燕麥，不過你首先要將周圍那些可怕的機器人先除掉。這裡的西南邊就有幾個農場。",objectives={"西部荒野的弗娜·法布隆要你帶８捧燕麥給她。"}]])
R(152,"清理海岸",[[description="你或許已經注意到海岸邊有許多船隻的殘骸。無盡之海確實是非常凶險，我們必須保持西部荒野海岸線的淨空，只有這樣水手們才能安全地找到靠港的路線。這些魚人實在是很麻煩，$b$b去殺死7名魚人潮行者、7名魚人戰士、7名魚人智者，還有7名魚人灘行者，完成任務之後到我這裡來領取獎賞。",objectives={"殺死7名魚人潮行者、7名魚人戰士、7名魚人智者，還有7名魚人灘行者，然後回去找西部荒野燈塔中的葛瑞森船長。"}]])
R(153,"紅色皮質面罩",[[description="我們與迪菲亞兄弟會的戰局總是瞬息萬變。最近我一直在監視著他們的活動，根據長期觀察的結果，我發現他們的成員都戴著一種特殊的紅色皮面罩。$b$b幫我帶15條這種面罩回來吧，我會給你獎勵的。",objectives={"帶15條紅色皮質面罩回來給哨兵嶺的哨兵加里安。"}]])
R(154,"歸還梳子",[[description="不！！！！！$B$B把它拿走，快把這個梳子拿走！$B$B我是個怪物，不會再有人說我好看了！",objectives={"把幽靈的梳子拿回去給夜色鎮的伊娃夫人。"}]])
R(155,"迪菲亞兄弟會",[[description="這麼說，斯托曼就派了你這麼一個骨瘦如柴的，$r，來保護我？看來你有得努力了，你最好再叫上幾個朋友幫忙比較保險。$b$b你知道你要做些什麼吧？我會帶你到迪菲幫的藏身之地，而你呢，就得好好保護我。當然，你最好離我近一點，越近越好。現在全迪菲亞兄弟會的人都想要我的腦袋呢。要是他們看見我和你在一起，一定會把我給宰了的。$b$b等你和你的朋友如果有準備好的話，就來跟我說一聲吧。",objectives={"護送迪菲亞叛徒前往迪菲亞兄弟會的秘密藏身處。一旦迪菲亞叛徒把你帶到范克里夫和他的手下的藏匿地點之後，儘快回去向格萊恩·斯托曼彙報相關資訊。"}]])
R(156,"收集腐敗之花",[[description="If you bring me some rot blossoms then I can brew you up a batch of zombie juice.$B$BRot blossoms grow in strange places.  In particular, I hear you can find them inside the skulls of Skeletal Horrors and Skeletal Fiends... not that I've gotten close enough to look!$B$BThe Raven Hill Cemetery and the Tranquil Gardens are both lousy with those skeletons.  You may as well get rid of them while you're looking for rot blossoms.  The town of Darkshire would be grateful.",objectives={"Gather 8 Rot Blossoms and bring them to Tavernkeep Smitts in Darkshire."}]])
R(157,"幽靈的發絲",[[description="這是你要的線，$N。它的用途不勝枚舉，比如用來束縛邪惡的亡魂，或者給沒有生命的東西注入生命。",objectives={"把幽靈的髮絲交給亞伯克隆比，他住在烏鴉嶺墓園北邊的房子裡。"}]])
R(158,"僵屍",[[description="我需要一瓶叫做殭屍汁的飲料。夜色鎮血鴉旅店的老闆史密茲應該有些存貨。$B$B請動作快點，最近晚上寒風刺骨，我得來點殭屍汁，好讓我的血液重新沸騰起來。",objectives={"和旅店老闆史密茲談話。"}]])
R(159,"僵屍酒",[[description="Here's your Zombie Juice...$B$B...and be careful with this stuff.  It's strong enough to raise the dead!",objectives={"Bring the Zombie Juice to Abercrombie at his shack."}]])
R(160,"給鎮長的信",[[description="Take this note to Ello Ebonlocke, the Mayor of Darkshire.$B$BHe and I are old friends...and when he reads it and discovers what you did for me...I'm sure he'll be just as happy as I am!  Hahahaha!",objectives={"Bring Abercrombie's Letter to Ello Ebonlocke, Mayor of Darkshire."}]])
R(161,"水壩危機",[[description="如果我的懷疑沒錯的話，這是某種火藥粉末。我們應該找個爆破專家來分析一下這到底是什麼東西，才知道我們到底面對的是什麼。阿胥蘭·暗石就在丹莫德和薩多爾大橋一帶負責那裡的警戒工作，我需要你儘快去找他，這是一段重要而危險的旅程，$N。$b$b穿過奧加茲隘口，沿著穿過潮濕之地的道路一直到丹莫德去找阿胥蘭。記住我的忠告：沿著大路走，不要停下腳步！",objectives={"總工程師辛德維爾要你把怪味粉末交給丹莫德的炸藥專家阿胥蘭·暗石。"}]])
R(162,"異種蠍的威脅",[[description="我希望你儘快把這份報告送到對處理此類事件有經驗的人手裡。$B$B我知道有一位名叫格拉希娜·靈風的夜精靈學者，她致力於研究卡林多大陸上那些與艾澤拉斯的普通生物截然不同的生物形態，她簡直就是一本活的生物百科！如果你想要知道我們面臨的是怎樣的威脅，以及如何解決這個威脅，那就把這份報告交給她吧，我們現在急需她的幫助。$B$B我聽說她住在達納蘇斯的月神殿裡。",objectives={"把報告帶給達納蘇斯的格拉希娜·靈風。"}]])
R(163,"烏鴉嶺",[[description="烏鴉嶺出了點問題，$n。卡洛爾信誓旦旦的說在那邊的房子裡有某個人——或者某個東西——出沒。有兩個晚上，他發現有個身影在活動，第三個晚上，某扇窗戶裡還透出了燈光。$b$b你如果真的關心暮色森林的安危，就去查查看看到底是什麼樣的怪物在烏鴉嶺搞鬼。",objectives={"查出是什麼東西在烏鴉嶺搞鬼。"}]])
R(164,"斯溫的貨物",[[description="你認識斯溫嗎？謝天謝地，終於有人能幫我了！斯溫和他的同伴在暮色森林的西北邊有個營地。$b$b不幸的是，他們的人手太少了，少到派不出人回鎮裡來取一些必需的補給品。你能把這些物資送給斯溫嗎？",objectives={"送補給物資給斯溫。"}]])
R(165,"隱士",[[description="有個老人經常會到鎮裡來買東西，不過我已經有些日子沒見過他了。如果我沒記錯的話，他就住在一個可以俯瞰烏鴉嶺墓園的小屋裡。也許你該去看一看是不是出了什麼事？",objectives={"去烏鴉嶺墓園附近的小屋查看老人的情況。"}]])
R(166,"迪菲亞兄弟會",[[description="你只剩下最後一個任務需要去完成。我們必須除掉艾德溫·范克里夫。雖然對一個活生生的人宣判死刑實在令我非常難過，但為了西部荒野人民的利益，我不得不讓范克里夫永遠安息。當你完成這件事之後，就把他的頭帶來給我。",objectives={"殺死艾德溫·范克里夫，把他的頭交給格萊恩·斯托曼。"}]])
R(167,"我的兄弟……",[[description="那時我們正在西部荒野的一個大礦坑中工作，就是那個隱藏在月溪鎮的谷倉底下的礦坑……沒人知道當時那些可惡的盜賊是那從那裡出現的。總之礦道突然坍塌了，我逃了出來……可是其他人……就再也沒聽到過其他人的下落了。$b$b你看起來運氣可能會比我們好一點。如果你能幫我找到我弟弟的話，我會非常感謝你的。他總是戴著他的探險者協會徽章。如果你找不到他的話，那塊徽章至少還能給我帶來一些安慰……",objectives={"將工頭希斯耐特的探險者協會徽章帶回去給暴風城的維爾德·希斯耐特。"}]])
R(168,"收集記憶",[[description="我的許多朋友都在那次可怕的礦坑倒塌中送掉了性命。如果你的冒險正好需要到月溪鎮的那個礦坑的話，請幫忙留意一下有沒有什麼可以辨認他們身份的標誌或是物品。如果你恰巧找到他們的礦業工會會員卡的話，請一定要帶回來給我，好讓他們的家人可以明白那場恐怖的意外結果。",objectives={"找回4張礦業工會會員卡並送回給暴風城的維爾德·薊草。"}]])
R(169,"通緝：加塞爾佐格",[[description="懸賞！加塞爾佐格是黑石氏族襲擊石堡和多次劫掠湖畔鎮等行動的領導者。$b$b他是個十分危險的傢伙。根據線報，他躲藏在剛剛被他們攻陷的要塞中，謀劃著黑石氏族的下一次劫掠行動。我們必須不惜一切代價把這些在我們的國土上橫行的獸人鎮壓下去。如果有那個勇士能把加塞爾佐格的頭帶到所羅門鎮長面前的話，他將會得到重賞。",objectives={"殺死加塞爾佐格並將他的頭顱帶回來交給湖畔鎮的所羅門鎮長。"}]])
R(170,"新的威脅",[[description="我希望你是到這裡來助我們一臂之力的，$c。在上一次石齶怪襲擊之後，我們的人手就明顯不夠了。$b$b我聽說他們現在已經遍佈我們的國土，看來寒脊山谷也不例外。東南部的山區和湖畔已經到處都是石齶怪的身影了。$b$b糟糕的事情還不只是這些，幾天前，他們襲擊並佔領了我們西邊的營地！$b$b我們這兒人手有些不足，$g小伙子:小姑娘;，我們需要強大的武力幫助我們趕走這些傢伙。",objectives={"巴爾林·霜錘要你去殺死6個石齶穴居人和6個壯實的石齶怪。"}]])
R(171,"聯盟孤兒的看護者",[[description="You have been so very kind to me, $N.  I never dreamed that I'd have so much fun during Children's Week.  Thank you.  I don't wanna be sad about what's happened to me and all - my folks always told me to rise above anything bad that happens.  You know, when I grow up I wanna be a hero... just like you.$B$BI'm sad to say this, but it's time for me to go home.  Let's go back and I'll tell the matron what an awesome person you are!",objectives={"Return your ward to the Stormwind orphanage by handing in the Human Orphan Whistle to Orphan Matron Nightingale in the Cathedral District."}]])
R(172,"兒童周",[[description="Lord Ebonlocke sent me to Stormwind to represent Darkshire at the recent council of the House of Nobles. I was tasked with requesting military aid in light of the undead infestation which has taken over the forest.But on my way back a band of thieves ambushed me. I was forced to drive my cart to The Rotting Orchard in southern Duskwood.Before the thieves could rob me of my goods, a pack of ferocious Worgen overtook the thugs. Now I need you to retrieve my satchel from the chest in the wagon.",objectives={"Retrieve Ambassador Berrybuck's satchel and bring it back to him in Darkshire."}]])
R(173,"森林裏的狼人",[[description="黑暗的勢力正在籠罩暮色森林，而卡爾文主人正在努力驅除邪惡，保護夜色鎮人民的安全是我們的職責。$b$b你覺得自己有能力加入我們嗎？$b$b我以前也跟你想的一樣，因為對哨所的安逸悠閒感到絕望，我投靠了卡爾文主人。如果你想要證明自己的實力，不是只靠嘴皮子說說就可以的。$b$b去找夜行織影狼人較量較量吧，他們經常在陽光樹林——陽光，哈！——和爛果園出沒。",objectives={"為夜色鎮的卡洛爾殺掉6個夜行織影狼人。"}]])
R(174,"仰望星空",[[description="我的地精朋友考格答應過要幫我製造一個可以用來觀察星星的裝置。除了魔法之外，我相信還有別的理由可以解釋發生在這片森林中的奇怪變化。$b$b根據考格的設計圖，我們的第一步得先去找根由手藝高超的技師所做的青銅管。",objectives={"夜色鎮的維克托·安特拉斯要你給他一根青銅管。"}]])
R(175,"仰望星空",[[description="根據考格的設計圖，現在我還需要一個東西來反射光線。我記得有個叫瑪麗的女人因為總是戴著單眼透鏡而在這一帶人人皆知，你可以去找找她，向她借一個反光鏡。我記得她曾經住在暮色森林南部……",objectives={"找到瑪麗，說服她借給你一個反光鏡，用於維克托的計畫。"}]])
R(176,"通緝：霍格",[[description="通緝：霍格$B$B巨型豺狼人霍格，現正在艾爾文森林西南部的樹林裡遊蕩。他成功地對抗了目前為止所有追捕他的行動。$B$B暴風城已經為除去這只豺狼人設下了酬金，想得到酬金的獵手必須向閃金鎮的治安官杜漢提供殺死霍格的證據。",objectives={"殺死豺狼人霍格，把他那巨大的豺狼人爪帶給治安官杜漢。"}]])
R(177,"仰望星空",[[description="那隻單眼透鏡是我最珍貴的寶物，不過在發生了一件事情之後……我就把它丟在穀倉後面了。有個瘋狂的食屍鬼曾經在那一帶徘徊，可能是它把東西給撿走了。有人說那個邪惡的傢伙住在靜謐的花園墓場。",objectives={"從瘋狂的食屍鬼那裡拿回盲眼瑪麗的單眼透鏡，把它交給夜色鎮的維克托。"}]])
R(178,"塞歐克瑞圖斯的墜飾",[[description="<你聽到某種飄渺的聲音>$B$B不要害怕。我是塞歐克瑞圖斯，艾爾文森林的阿祖拉之塔裡的高階法師。你手上拿著的墜子是暗皮豺狼人和他們的主人莫甘斯用來聯絡的工具。$B$B根據這幾個月的研究，我相信我已經掌握了使用這些墜子進行通訊的方法。如果你能聽到我所說的話，就證明我的法術成功了。$B$B把這個墜子帶來給我，我會給你酬勞的。",objectives={"暗淡的暗皮墜飾帶給法師塞歐克瑞圖斯。"}]])
R(179,"矮人的交易",[[description="嘿，你是新來的吧？看來你需要些暖手的東西，對嗎？$b$b我想你應該想要一副保暖的手套。我是個熱心腸，很願意給你一副手套，不過我有個條件。$b$b你幫我弄些狼肉來，我保證你不會被凍掉手指頭。你覺得怎麼樣？",objectives={"斯登·粗臂想要8塊硬狼肉。"}]])
R(180,"通緝：範高雷中尉",[[description="懸賞：范高雷$b$b惡行累累的豺狼人頭目范高雷在湖畔鎮及王國的敵人莫甘斯的指使下，帶著暗皮豺狼人氏族到處為非作歹。鎮長所羅門下了命令，懸賞殺死這個萬惡的東西。將他的手掌割下來拿給鎮長，以此證明他的死亡。",objectives={"殺死范高雷並將他的手掌割下，向湖畔鎮的所羅門鎮長覆命。"}]])
R(181,"仰望星空",[[description="根據考格的設計圖，我們還需要一種透鏡來完成整個裝置。我知道什麼地方有合適的透鏡，不過很難拿到。$b$b有個叫札克烏爾的巨魔住在暮色森林南部的土丘上，如果可以的話，你去把他的單片眼鏡拿來吧，我可以用它做成透鏡。",objectives={"在暮色森林南部的巨魔土丘上找到札克烏爾，把他的單片眼鏡帶回夜色鎮交給維克托。"}]])
R(182,"巨魔洞穴",[[description="我和我的兄弟森內爾被派來調查丹莫洛各個地區的食人妖活動情況。參議院正在忙著對付那些不知道從哪裡冒出來的穴居人，已經沒工夫再關心食人妖了。$b$b據我所知，在寒脊山谷南部山洞裡生活的食人妖們日子並不好過，所以我覺得派大批軍隊去圍剿它們是殺雞用牛刀，只要一兩支訓練有素的小分隊就已經綽綽有餘了。$b$b你也許能給我們提供些幫助吧？當然，我會對你的幫助給予一定的報酬。",objectives={"格瑞林·白鬚要你去殺掉14個小霜鬃食人妖。"}]])
R(183,"獵殺野豬",[[description="沒什麼能比得上用一整天的時間去打野豬更讓人愉快的了，對吧？不過，寒脊山谷裡的野豬太多了，你幾乎已經不可能在那裡再感受到狩獵的樂趣。你根本不需要去激怒它們，因為它們早就是怒氣衝天，隨時準備用獠牙把你拱上天了！事實上，這些過剩的野豬已經對我的日常狩獵形成了威脅。$b$b長話短說吧，如果你能幫我殺掉些野豬，我真的會非常感激你的。",objectives={"塔林·銳眼讓你去殺掉12隻小型峭壁野豬。"}]])
R(184,"法布隆的地契",[[description="這是西部荒野一片農田的地契，由希歐多爾·法布隆和他的妻子弗娜聯名簽署。地契背面有著潦草的字樣：$B$B「我們到法布隆家裡走了一趟，弄到了他的地契。我們覺得你可以很輕易地將其中一份偽造成自已的土地。$B$B法布隆家的人不會找我們的麻煩，我最後一次看到他們的時候，他們正準備離開西部荒野，不過他們的四輪貨車壞在路上了。」$B$B你認為法布隆夫妻倆可能會想要拿回這張地契……",objectives={"把法布隆的地契交給農夫法布隆。"}]])
R(185,"獵虎",[[description="當我還只是個小女孩的時候，我的父親就開始訓練我捕獵老虎。$b$b一般來說，你會發現虎崽是非常容易追蹤和獵殺的。因此，要獵殺它們根本不是什麼麻煩的事情，你在探險隊的營地附近很容易就能找到虎崽。$b$b讓我們來測試一下你的追蹤技巧，看看你是否能獵殺這些野獸。",objectives={"奈辛瓦里遠征隊的艾耶克·羅歐克要求你殺死10隻小荊棘谷猛虎。"}]])
R(186,"獵虎",[[description="你學得很快，$c。讓我們來測試一下你是否能夠殺死成年的猛虎了，這次你的任務是去殺死十隻荊棘谷猛虎。",objectives={"奈辛瓦里探險隊的艾耶克·羅歐克要你去殺死10隻荊棘谷猛虎。"}]])
R(187,"獵虎",[[description="現在我要讓你冒更大的危險以真正地測試你的技巧。去殺死十隻老年荊棘谷猛虎以證明你的能力吧。如果你能做到的話，你就可以準備去面對最後的挑戰了，到時我會在奈辛瓦里大人的面前授予你獵虎大師的稱號。$b$b老年荊棘谷猛虎不但非常難找，而且也是最難以對付的。",objectives={"奈辛瓦里遠征隊的艾耶克·羅歐克要你去殺死10隻老年荊棘谷猛虎。"}]])
R(188,"獵虎",[[description="現在你要面對的將是最後的挑戰。幾週以來一直在追蹤一隻神秘的老虎，我們稱牠為辛達爾。現在讓我們來看看你能不能做到以前從來沒有任何$r可以做到的事吧：獵殺辛達爾！把牠的爪子帶回來做為證明。$b$b要追蹤到牠可不是一件簡單的任務。",objectives={"奈辛瓦里探險隊的艾耶克·羅歐克要你去殺死辛達爾並帶回牠的爪子。"}]])
R(189,"血頂巨魔的耳朵",[[description="該死的食人妖！他們不斷的殺死我們派到叢林裡去的人！和他們的衝突已經讓我損失太多優秀的護衛了。我們的花費也因此節節上升！要我怎麼向大財主里維加茲解釋呢？$b$b是該做決定的時候了……想想看，科博克……你可不是被派到這裡來整日無所事事的……啊，有啦！你……你就是$n，是不是？你會幫我的，對不對？這份工作的獎勵可是很豐厚的哦！$b$b條件如下，幫我弄15個血頂食人妖的耳朵來，我會重重地酬謝你的。",objectives={"拿15個血頂食人妖的耳朵回來給藏寶海灣的科博克。"}]])
R(190,"獵豹",[[description="如果你想加入這個由赫米特先生組建的最強狩獵隊，就必須先證明自己是一個能幹的獵豹高手。放心，一開始不會太難的。先去獵殺1０ 隻小獵豹做為開始吧。$b$b找到牠們是這個挑戰的上半場而已……",objectives={"奈辛瓦里遠征隊的艾爾加丁爵士要你去殺死1０隻小獵豹。"}]])
R(191,"獵豹",[[description="現在你已經可以更進一步了。如果你想繼續證明自己有資格和我們這些優秀的狩獵高手合作的話，就去獵殺十隻黑豹。$b$b這些大傢伙們都很強壯，它們可不像你之前殺的那些年幼的獵豹那麼好殺。",objectives={"奈辛瓦里探險隊的艾爾加丁爵士要你去殺死10隻黑豹。"}]])
R(192,"獵豹",[[description="接下來的部分可就比較困難了。一個真正的獵豹高手，可以藉由掠倒深喉獵豹這種荊棘谷中最危險的生物來展現他的技巧。殺死十隻深喉獵豹，向我們證明你的獵豹能力吧！$b$b如果你很難找到它們的蹤跡的話，就等到你想殺的時候再去吧……",objectives={"奈辛瓦里探險隊的艾爾加丁爵士要你去殺死10隻深喉獵豹。"}]])
R(193,"獵豹",[[description="你幾乎已經證明自己是一位優秀的獵豹高手了。有一隻名叫巴爾瑟拉的豹子目前正潛伏在這片森林裡，我們一直都沒能找到它。去試試獵殺巴爾瑟拉吧，記得用上你所掌握的全部技巧。$b$b將巴爾瑟拉的牙齒帶回來給我，如果你成功了，你就將贏得我的尊敬！",objectives={"奈辛瓦里遠征隊的艾爾加丁爵士要求你殺死巴爾瑟拉，並帶回它的牙。"}]])
R(194,"獵龍",[[description="你覺得你的狩獵技術是最頂尖的？我馬上就檢驗一下，看看你是不是在騙人。到叢林裡去殺幾隻荊棘谷迅猛龍，這樣一來我們就知道你是不是所謂的王牌獵人了。$b$b當然，我是絕對不會告訴你在哪裡才能找到它們的！追蹤野獸本身就是挑戰的一部分。",objectives={"赫米特·奈辛瓦里要求你殺死10隻荊棘谷迅猛龍。"}]])
R(195,"獵龍",[[description="現在讓我們看看你能不能應付更大的挑戰吧。深入叢林裡去幹掉十隻殘暴的鞭尾迅猛龍。可別說你不行啊！",objectives={"赫米特·奈辛瓦里要你去殺死1０隻鞭尾迅猛龍。"}]])
R(196,"獵龍",[[description="讓我們來看看你能不能對付下一個挑戰吧。這附近棲息著一種非常狡猾的迅猛龍，我們叫它叢林捕獵者。它們遠比你之前捕獵的目標更難追蹤和獵殺。獵殺十隻叢林捕獵者，然後我就會告訴你這裡最惹眼的目標是什麼。",objectives={"赫米特·奈辛瓦里要求你殺死10隻叢林捕獵者。"}]])
R(197,"獵龍",[[description="你已經證明了自己在這片叢林裡的每次捕獵都不會空手而歸，總能帶回我們要求的獵物，因此我決定告訴你有關那隻我從來也沒能獵到的、最兇暴最殘忍的迅猛龍的事情，艾耶克把那隻迅猛龍叫作泰希斯。$b$b如果你想證明自己真的是個捕獵專家的話，就把泰希斯殺掉，把它的爪子給我帶回來，這可是其他王牌獵人都從沒完成過的壯舉。",objectives={"赫米特·奈辛瓦里要求你殺死荊棘谷中最危險最狡猾的迅猛龍泰希斯。"}]])
R(198,"列兵索爾森的補給物資",[[description="嗯。沒錯，我這裡確實有件適合你做的事。目前佈署在荊棘谷北部的多倫上尉和他的部下需要我們的定期補給。$b$b由於食人妖的攻擊，這些補給物資一直沒有送出去，我得找人來幫我處理這件事。多倫的營地就在從暮色森林進入荊棘谷的道路西北方，你只要把補給品交給士兵索爾森就行了，如果他不在營地裡，那可能是他在營地的南邊巡邏。他會處理好這些東西的。$b$b提醒你，如果你失敗了的話，就得賠償我們的損失。",objectives={"將各式各樣的哥布林補給品交給士兵索爾森。"}]])
R(199,"水壩危機",[[description="You take a sample of the strange smelling powder.",objectives={"Return to Chief Engineer Hinderweir and show him the clue that you discovered."}]])
R(200,"書呆子赫羅德",[[description="既然連庫爾森都知道了這個秘密，那麼他們一定也在我們這邊安插了一個臥底。我們必須得搞清楚這些機密內容是怎麼洩露出去的！$B$B索爾森在那邊的線人是書呆子赫羅德，他是庫爾森的後勤官，瞭解庫爾森的營地裡的一切事務。如果你能搞到他的筆記或者檔案什麼的話，或許我們能分析出索爾森到底是怎麼被發現的。$B$B當初，我們還跟庫爾森一起共事的時候，書呆子的辦公室是在營地裡唯一一座兩層房屋的二樓，他的檔案應該還在那裡。",objectives={"找到書呆子赫羅德的檔案。"}]])
R(201,"調查營地",[[description="我收到一條報告說，有一群獵人在風險投資公司營地所在的納菲瑞提湖的上游建立了一片營地。通常我根本不會在意這件事，但當我聽說赫米特·奈辛瓦里也是那群獵人中的一員時，我改變了想法。那傢伙可是個名聲顯赫的人物，如果你瞭解我的意思的話，就會不像現在這樣無動於衷了。$b$b你為什麼不去那片營地裡偵察一下呢，$n？去看看他們到底想幹點什麼吧。",objectives={"找到獵人營地並向藏寶海灣的克拉茲克報告這個營地的位置。"}]])
R(202,"庫爾森上校",[[description="你一次又一次地證明了自己的能力，而你的足智多謀略似乎甚至能與庫爾森媲美。如果……如果你願意徹底投身到與庫爾森鬥爭的事業中去的話……也許你將成為我們反抗軍的救星！$B$B他就躲在那個名叫「儲藏室」的洞穴深處發號施令。你必須進入那個洞穴，幹掉他身邊的保鏢，最終把庫爾森和他的副官們都給除掉。$B$B出發吧，$N。我們的生命與希望，如今都已經全部掌握在你的手中了。",objectives={"殺掉6名庫爾森精英和4名庫爾森副首領，並將庫爾森的頭顱交給反抗軍營地裡的多倫上尉。"}]])
R(203,"以彼之道還施彼身",[[description="我們正在與庫爾森進行一場艱難的戰鬥。他是個非常優秀的戰術大師，而且他的手下士兵的數量是我們的十倍！如果我們想要勝利的話，就必須使用他擅長的戰術來對付他。$B$B到他在東邊設立的營地裡去，殺掉他的士兵，越多越好，然後在增援趕來之前撤退。",objectives={"殺死15名庫爾森叢林戰士，然後向反抗軍營地的尤瓦中士覆命。"}]])
R(204,"庫爾森的藥物",[[description="要想和庫爾森搏上一搏，我們就必須削弱他們的醫療隊伍。他在那裡聚集了大批醫療人員，他們能用密林藥劑治療自己的部隊，並用毒草汁液對我們的人下毒。$B$B我們要用這些藥物來治療我們自己的戰士，同時我們也需要一份毒液的樣本來研製解藥。到庫爾森的營地去把這兩樣東西找來吧，藥品應該就在那些醫療人員的身上，而毒草汁液大概是保存在營地中的一些物資箱裡的。",objectives={"給反抗軍營地裡的尤瓦中士帶回7份密林藥劑和1份毒草汁液。"}]])
R(205,"巨魔巫術",[[description="在我研究這些食人妖傳說的時候，我希望你能幫我收集一些食人妖們施展邪惡魔法時必備的法器。到南邊的那個劈顱食人妖部族的地盤上去，從他們的巫醫和秘法師那里弄一些劈顱食人妖的神像回來吧。",objectives={"給叛軍營地的尼麥茲修士帶回4只劈顱食人妖的神像。"}]])
R(206,"麥佐斯",[[description="庫爾森的確是該死，不過……到底是誰將他帶上了這條邪惡的道路呢？通過研究，我已經找到了真相：是一個名叫麥佐斯的巨魔法師幹的。他住在荊棘谷東部的巨魔山中，據說他擅長心靈控制魔法，我也確信正是他使得庫爾森上校墮落的。$B$B如果麥佐斯繼續活在這世上，他的邪惡法術就有可能影響到更多人，或許又會出現另一個庫爾森上校。$B$B殺死他，把他的心靈之眼帶回來，這正是他用來誘惑他人墮落的物品。",objectives={"將心靈之眼交給反抗軍營地裡的尼麥茲修士。"}]])
R(207,"庫爾森的秘密",[[description="庫爾森上校曾是個偉大而高貴的人，我必須得找到讓他墮落至此的原因！他一定是被食人妖的魔法給控制了。要想搞清楚這一點的話，我們就得先研究一下食人妖的傳說故事。$B$B據說荊棘谷中的食人妖遺跡中隱藏著四塊石板，我必須得看看這些石板上到底記述了些什麼東西！你去給我拓一份這些石板上的文字來，把拓片都交給我。$B$B第一塊石板在巴拉爾廢墟裡，第二塊石板在暗礁海的海底，第三塊和第四塊應該都在祖昆達廢墟裡。",objectives={"找到4塊石板並將上面的內容帶回去交給尼麥茲修士。"}]])
R(208,"王牌獵人",[[description="$N，你現在已經成為了一位夠格進入我們狩獵隊的獵手了。無論是羅德隆的戰場還是危機四伏的叢林，我在哪裡都沒有見過有誰能像你這樣擁有如此強大的戰鬥能力。$b$b你成功地殺死了兇殘的辛達爾，狡猾的巴爾瑟拉和強悍的泰希斯。但對於這片叢林中的獵人們來說，虎王邦加拉西的頭才代表著至高無上的榮耀。這只白虎正是我來這裡的原因，我注意它已經很久了。如果你能殺死虎王邦加拉西，那麼你無疑是這裡最優秀的獵人。",objectives={"赫米特·奈辛瓦里要求你將虎王邦加拉西的頭帶回來給他。"}]])
R(209,"劈顱巨魔的獠牙",[[description="靠不停地獵殺老虎來保證對南海島嶼的虎牙出口實在是苦差事，不僅難度高，而且花費也也高。幸虧我們找到了一種替代品，就是這些劈顱部族的食人妖的獠牙。$b$b嘿，只要你不說，買家就不會知道，對吧？給我搞一批食人妖獠牙來吧，這樣我們就能應付每月一次的供貨啦！",objectives={"給藏寶海灣的科博克帶回18根劈顱食人妖的獠牙。"}]])
R(210,"克拉茲克的烹調鍋",[[description="在營地裡，我是專門負責伙食的。過去的活真的很多，讓我每天都要忙到死，直到我從藏寶海灣的哥布林商人那裡買了台多功能機械烹調鍋才有所改觀。這鍋實在是太棒了！它節省了我許多的時間……我是說，在它壞掉之前！$B$B你能幫我把這鍋帶到那個哥布林商人那裡去，讓他給我修理一下嗎？他的名字叫克拉茲克。",objectives={"把克拉茲克的烹調鍋帶給藏寶海灣的哥布林克拉茲克。"}]])
R(211,"啊，安多哈爾！",[[description="啊，進攻安多哈爾並徹底擊敗那個巫妖的時刻終於來臨了！$B$B你這個城市的廢墟裡就是巫妖 - 召喚者阿拉基統治的地方。無數的天譴軍團守護在城中心的廢墟周圍，而他的貼身隨扈守衛更是令人畏懼。你需要帶眾多的盟友前往才可能有機會成功挑戰它。$B$B消滅阿拉基，$N，從它的護符匣裡拿出一塊碎片來，作為你獲勝的證據！",objectives={"把阿拉基的護符匣碎片交給西瘟疫之地冰風崗的指揮官阿胥拉姆·瓦羅菲斯特。"}]])
R(212,"冷餐會",[[description="我的拿手菜之一就是橙味凍蜥肉，但現在的問題是……這種肉很容易變質，而且我今天晚上必須得在一位貴族的生日晚宴上做這道菜！$B$B救場如救火，如果你能馬上從剛被宰掉的冷眼蜥蜴身上割塊冷蜥蜴肉給我的話，我就給你做頓堪比國宴的美味嘗嘗！$B$B冷眼蜥蜴一般會在荊棘谷西北海岸的沙灘上曬太陽，離這裡有點遠，不是麼？所以你得趕緊行動啦！",objectives={"殺死一隻冷眼蜥蜴，取一塊冷蜥蜴肉並把它帶給「藍色隱士」旅店裡的安古斯·斯特恩。$B$B<如果你在任務過程中死亡則任務失敗>"}]])
R(213,"惡性競爭",[[description="太倡狂了！吉爾里茲把貿易親王們指定的要員們都從這裡趕了出去，這件事已經夠糟的了，現在他居然還和那些聲名狼籍的海盜們往來！$b$b里維加茲不會坐視不理的，他允許我按自己的方式來解決這些問題。$b$b我的方式是什麼？偷！最近，風險投資公司的地質學家們正在研究他們從礦裡挖出的一種奇怪的藍色水晶，從那群地質學家手裡搞些樣本回來給我，當然，我不關心你用怎樣的手段去搞。",objectives={"給藏寶海灣的科博克帶回8塊打磨過的水晶。"}]])
R(214,"紅色絲質面罩",[[description="迪菲亞兄弟會的人都會戴著一種紅色的面罩，這顯然已經是個盡人皆知的秘密了。但我們又瞭解到，這個面罩的材料是他們的成員在幫會內部地位的象徵。$b$b既然如此，那麼我希望你出馬殺死一些兄弟會的高階成員。他們的最高階成員無疑都躲在范克里夫的秘密藏身處附近。作為證據，你要給我帶回10條紅色絲質面罩來，這樣我才能給你獎勵。祝你好運，$N。",objectives={"給哨兵嶺哨塔的哨兵瑞爾帶回10條紅色絲質面罩。"}]])
R(215,"叢林中的秘密",[[description="謝謝你救了我的命，$N。我知道這聽起來有點奇怪，但……請聽我解釋。$B$B多倫上尉讓我和庫爾森的手下一起重新回到軍隊裡，讓我扮演臥底的角色，為我們反抗軍搞一些有用的情報。我原本以為這裡很適合我滲透入庫爾森的營地，但我錯了。再次感謝你救了我一命。$B$B這是個機密任務，所以你千萬不能把它告訴任何人。但如果你去和多倫上尉談談的話，他會給你一個解釋的。",objectives={"與反抗軍營地裡的多倫上尉談話。"}]])
R(216,"薊皮熊怪的麻煩",[[description="The Thistlefur furbolgs are threatening our expansion!  Thistlefur Village to our east blocks the way between us here and the Splintertree Post.  It's a path that would circumvent the village of Astranaar; without it, we give the Alliance an extra expansion path.$B$B$N, we must not allow... an expansion path gap!$B$BProceed to Thistlefur Village and thin out the furbolgs.  You will be given compensation for this task, but more importantly you will be doing your duty for the Horde!",objectives={"Take down 12 Thistlefur Avengers and 12 Thistlefur Shaman; most are located east of Zoram Strand in Thistlefur Village.  Once completed, return to Karang Amakkar at Zoram'gar Outpost, Ashenvale."}]])
R(217,"保衛國王的領土",[[description="$N，我的偵察兵已經找到了最近一段時間來頻頻組織穴居人對我們發動襲擊的首領。這幫洛克莫丹的怪物好像是由一個叫格勞姆格的酋長領導的，不過格勞姆格身邊守衛森嚴，有兩個精英護衛納什爾和布勞勒爾從不離他左右。$b$b如果你想證明自己的價值的話，$N，我希望你能接下殺掉格勞姆格和他那兩個手下的任務。一旦穴居人失去了領導，我們就有機會把這些怪物重新趕回地下。",objectives={"殺掉穴居人首領格勞姆格及他的兩個護衛，納什爾和布勞勒爾。然後回到南部警戒塔向拉格弗斯上尉報告。"}]])
R(218,"被竊取的日記",[[description="我的日記！那幫食人妖把它拿到洞穴裡去了。拿著日記的那個傢伙……他是一個皮膚和面頰上都塗著奇特印記的青面獠牙的傢伙，我打從娘胎裡出來後還沒見過像他那樣醜的。$b$b你應該能對付那些食人妖，幫我把我的日記拿回來怎麼樣？",objectives={"格瑞林·白鬚要你去殺掉冷酷的格瑞克尼爾，並取回他的日記。"}]])
R(219,"失蹤人員",[[description="終於…有人來了……來自聯盟的朋友！$b$b救救我…求你了…$b$b我只記得…一群邪惡的獸人讓我們團全軍覆沒……大多數人都被殺了，我的頭被狠狠地打了一下，眼前一黑就倒下去了。現在我被關在這個洞裡，奄奄一息……$b$b我必須得回到鎮上去…拜託了…你是我最後的希望了……",objectives={"保護基沙恩下士回到赤脊。"}]])
R(220,"水之召喚",[[description="Islen will have one more task for you before rewarding you with your next totem. The vial of water I've given you is necessary for whatever that task is.$B$BGo now and find her. We shall meet again some day.",objectives={"Bring the Vial of Purest Water to Islen Waterseer in the Barrens."}]])
R(221,"森林裏的狼人",[[description="You might have noticed some larger worgen wandering around with the Shadow Weavers in the woods? From what we can tell, these Dark Runners make up the bulk of the worgen numbers.$b$bOn my rangings, I've also noticed that they have overrun the Rotting Orchard southwest of town. These worgen are a bit tougher than the last you faced.$b$bBe on your guard.",objectives={"Kill 12 Nightbane Dark Runner worgen for Calor in Darkshire."}]])
R(222,"森林裏的狼人",[[description="你之前的功績使我確信，你已經可以去對付森林裡最兇猛的狼人了。$b$b在這一帶所有的狼人中，夜行邪齒狼人和夜行墮落狼人是最危險的。他們就住在南邊的洞穴和礦坑裡。$b$b你甚至能從很遠的地方看見他們的營火。",objectives={"為夜色鎮的卡洛爾殺掉8個夜行邪齒狼人和8個夜行墮落狼人。"}]])
R(223,"森林裏的狼人",[[description="拿著這個，$n。把這個帶給卡爾文主人。$b$b<他取出一張褪色的羊皮紙交給你>$b$b如果再多些像你這樣的力量加入，我們就能讓守夜人相形見拙！也許到那個時候，我們就能夠徹底解決這些現在令我們疲憊不堪的危機。",objectives={"把卡洛爾的便箋交給喬納森·卡爾文。"}]])
R(224,"保衛國王的領土",[[description="我們要保衛洛克莫丹，$N！國王的士兵都在遙遠的戰場上英勇作戰，但我們的家園卻危機叢生。每個裂縫裡都有穴居人在不斷冒出來！四處橫行的穴居人已經成了鐵爐堡最大的威脅，我們一定要消滅這些噁心的怪物！$b$b我們需要像你這樣勇敢的冒險家來幫忙消除穴居人的威脅。殺掉10個碎石穴居人和10個碎石怪斥候，然後回來向我彙報。",objectives={"南部警戒塔的巡山人庫伯弗林特要你殺掉10個碎石穴居人和10個碎石怪斥候。"}]])
R(225,"飽經風霜的墓碑",[[description="The weathered grave marker reads simply:$b$bMORGAN LADIMORE$b$b<Upon further examination, you notice that dirt over the grave has been recently disturbed, and that a good amount of the dirt seems to have been displaced...>",objectives={"Speak with Sirra Von'Indi in Darkshire."}]])
R(226,"惡狼成群",[[description="我和斯溫的處境越發危險了，這兒就我們倆，要吃飯就得打獵捕魚。但是每次我們帶著肉和魚回營地的時候，那些從森林跑出來的恐狼都好像要撲上來咬一口似的。別提有多危險了！$B$B如果你能替我們除掉這些狼，也許我們就能過得輕鬆些。它們經常在北邊和東邊的小河周圍出沒。",objectives={"殺掉12只饑餓的恐狼和8隻瘋狂的恐狼，然後到斯溫的營地中向拉爾斯交差。"}]])
R(227,"摩根·拉迪莫爾",[[description="<He searches through the shelves and comes up with a leatherbound book.>$b$bIf you would like to know more, you might ask Althea, she's been the one to handle the... trouble... with him of late.",objectives={"Speak with Commander Althea Ebonlocke in Darkshire."}]])
R(228,"摩拉迪姆",[[description="我的探子說摩拉迪姆沿著一條穿過墓地的彎曲怪異的小路，在暮色森林中四處遊蕩。我們曾把他的屍體埋在山上那座小屋的後面，你知道在哪兒吧？$b$b除了祝你好運之外，我沒什麼能幫你的了。",objectives={"殺掉摩拉迪姆，把他的頭骨交給夜色鎮的指揮官阿勒泰婭·埃伯洛克。"}]])
R(229,"幸存的女兒",[[description="我應該早點告訴你的……$b$b該怎麼說呢……$b$b摩根可能以為他的家人都死了，不過實際上他的女兒莎拉·拉迪莫爾還活著，她現在也是個守夜人。她一直在因為她父親死了以後所發生的……那些事情而苦惱。我想，你可以把關於她父親的最新消息帶給她。",objectives={"去和夜色鎮的守夜人莎拉·拉迪莫爾談話。"}]])
R(230,"斯溫的營地",[[description="Digging through the mound, you find a small, dirt-stained book.$B$BThe book has no title, but...it has information Sven would like to know.",objectives={"Bring the Book from Sven's Farm to Sven."}]])
R(231,"女兒的愛",[[description="拿著這個，請把這個放到他的墳墓上。也許…也許這樣他就可以知道我現在過得很好，而且我們也不會因為他所做的事責怪他。$b$b<她含著眼淚，把戴在右手上的一隻戒指摘下放在你手裡>$b$b還有……謝謝你，$n。",objectives={"把莎拉·拉迪莫爾的戒指拿到摩根·拉迪莫爾的墳墓上去。"}]])
R(232,"金格的貨物",[[description="The Royal Apothecary Society needs your assistance.  Listen closely, and both of us may profit from my plan.$B$BApothecary Keever in the next room may be... touched... but his research does potentially bear fruit if it were pursued by a clever researcher.  Fortunately, I am such a researcher.  I want you to take this purchase order to Alessandro Luca, the proprietor of Blue Moon Odds and Ends; he'll give you a testing kit.  When you have it, bring it back to me and I'll outline your task in detail.",objectives={"Take the purchase order to Alessandro Luca in the Undercity."}]])
R(233,"寒脊山谷的送信任務",[[description="嗯，$g小子:姑娘;，我想也許你不會幫我這個忙的。今天從隧道那邊來了一大堆信，我想我沒時間把它們都給發出去了。$b$b這些信都是寄給塔林·銳眼的。沿著這條路向西走就能找到他，就在結冰的湖泊附近。$b$b你能幫我這個忙麼？",objectives={"把這一疊信件送給塔林·銳眼。"}]])
R(234,"寒脊山谷的送信任務",[[description="如果我沒記錯的話，格瑞林的營地就在這條路的盡頭，沿著路往東南方走就是了，他一定正在等著這封信呢。",objectives={"把這封信送給格瑞林·白鬚。"}]])
R(235,"灰谷狩獵",[[description="年輕的冒險者們，注意了！梣谷的野獸正在等著你們！$B$B部落在貧瘠之地以北的區域建立了強大的基地。我們的兩個前哨站——碎木崗哨和左拉姆海岸崗哨——正在努力地為部落的榮耀而戰！想要證明自己能力的勇士就到那兒去吧。碎木崗哨位於貧瘠之地的正北方，塞娜尼·雷心正在那裡招募願意參與梣谷狩獵中的冒險者！",objectives={"與梣谷碎木崗哨的塞娜尼·雷心談話。"}]])
R(236,"Awaiting Word",[[description="A few weeks ago, I dispatched Watcher Callahan and a few others to the northern border of Duskwood to deal with the wolf infestation. I haven't heard word from him for quite some time. If he followed my instructions, he'll be camped out on the road north from Darkshire. $B$BIf it's on your way, please check up on him and inform him that I am awaiting a progress report from him.",objectives={"Speak with Watcher Callahan."}]])
R(237,"保衛國王的領土",[[description="巡山人庫伯弗林特總是在我面前稱讚你，$c。因此現在我要交給你一個極其重要的任務，你必須不斷給那些入侵的穴居人施加壓力，直到我們的兄弟們從聯盟前線回來。$b$b到南部的丘陵去，殺掉10個碎石怪擊顱者和10個碎石怪先知。你的行動可以為我們贏得一點時間，完成任務後就回來向我報告。",objectives={"南部警戒塔的巡山人格拉維戈要你殺掉10個碎石怪擊顱者和10個碎石怪先知，然後回去向他彙報。"}]])
R(238,"金格的貨物",[[description="The kit is ready, $n.  No doubt that Apothecary Zinge will want this as soon as possible.  Take it to her without delay, and let her know that I will add the cost of the kit to the Society's tab.  Also, please extend to her my warmest salutations.$B$BWell, don't just stand there.  Such is the life of a simple courier, yes?",objectives={"Bring the Field Sampling Kit to Apothecary Zinge in the Undercity."}]])
R(239,"西泉要塞",[[description="我們位於西部邊界的要塞報告說，那裡的豺狼人和迪菲亞盜賊最近越來越猖獗了。他們要求我從暴風城派更多士兵過去……但是我們已經沒有多餘的人可派了！$B$B如果你願意幫忙的話，就去和西泉要塞的瑞尼爾副隊長談一談，看看他需要你做些什麼。$B$B沿著這條路往西走，過了橋之後向右轉就是要塞。",objectives={"到西泉要塞去和瑞尼爾副隊長談話。"}]])
R(240,"基特斯的美餐",[[description="完成了——格魯奧烹製的黑「蟹」蛋糕！",objectives={"把黑蟹蛋糕拿回去交給基特斯。"}]])
R(241,"<TEST> HEY MISTER WILSON!",[[description="Description",objectives={"Log"}]])
R(242,"<UNUSED>",[[description="Throm-ka, $c. There is no time to waste. Orcs of the Dragonmaw clan have fortified themselves in the valley to the south of here. $b$bThey have denied the Warchief's mandate, leaving us only one course of action. We will eliminate them so that they will no longer dirty the name of the Horde.",objectives={"Kill 8 Dragonmaw Raiders, 3 Dragonmaw Bonewarders, and a Dragonmaw Battlemaster."}]])
R(243,"進入沙漠",[[description="You will be headed to the Tanaris desert, testing the tissue consistency of the basilisks, scorpids, and hyena native there.  Obtain tissue samples and use them with the testing kit in tow; expect a chunk of the samples to fail.  I need eight acceptable samples of each creature type.$B$BIn addition, the goblins of Gadgetzan have a power source that must be used with this kind of modified kit.  Speak to Chief Engineer Bilgewhizzle and acquire one for the kit.$B$BReturn to me only when you are successful.",objectives={"Speak to Chief Engineer Bilgewhizzle in Gadgetzan about getting a power source for the testing kit."}]])
R(244,"豺狼人的入侵",[[description="你好，$c。我是負責這段道路巡邏任務的衛兵。雖然這條道路現在是安全的，但我曾經在這附近的東北方看見過豺狼人的宿營地。$B$B湖畔鎮必須得提防著這群豺狼人才行。請你把這條消息報告給湖畔鎮的菲爾頓副隊長,我想他一定會非常樂意給你的偵察行動付上一筆酬勞的。$B$B菲爾頓一般在湖畔鎮橋南的地區執行警戒任務。",objectives={"找到菲爾頓副隊長。"}]])
R(245,"蜘蛛的威脅",[[description="你好啊，$c。你有沒有看到過在西邊出沒的那些蜘蛛？這些八條腿的東西實在是太多了，多到我們沒法應付，指揮官又沒有多餘的人力可以從夜色鎮派來協助我們。$b$b我實在是不好意思向你開口，不過……看樣子你好像能對付它們。我不能承諾給你什麼貴重的寶貝，不過如果你幫助我們除掉這些骯髒的臭蟲，我肯定會獎賞你的。$b$b哦，對了，給你個忠告：儘量別碰到它們的毒液。",objectives={"守夜人道茨要你殺15隻小型結網毒蜘蛛。"}]])
R(246,"審時度勢",[[description="我們實在是沒有多餘的人手了，但我們也不能對你報告中提到的那些豺狼人不聞不問。$B$B偵察南赤脊山附近豺狼人的動向,並盡可能地殺掉足夠多的豺狼人,然後向我回報他們的數量，好讓我們對他們的威脅大小有個正確的認識。$B$B暴風城軍方需要你的幫助，$N，你會得到獎賞的。",objectives={"殺死10個混血赤脊山豺狼人和6個赤脊山偷獵者，然後向湖畔鎮的菲爾頓副隊長覆命。"}]])
R(247,"完成狩獵")
R(248,"監視",[[description="我監視伊爾加拉之塔已經很久了，並且我發現，莫甘斯與佔據了石堡要塞的獸人之間起了矛盾。我不知道他們之前產生紛爭的原因是什麼，但你可以幫我揭開謎底。$B$B帶上阿祖拉的銘文飾品，然後到那個能監視石堡要塞的崗哨頂部去。$B$B找一個合適的地方，把銘文飾品放進去，一個盒子或者罐子之類的東西都可以，只要銘文飾品不會被注意到就行，那樣我的目的就達到了。",objectives={"爬上石堡要塞一旁的哨塔。$B$B為阿祖拉的銘文飾品找一個合適的容器。"}]])
R(249,"莫甘斯",[[description="在長期的偵察監視之後，我終於發現了莫甘斯的計畫。$B$B他正在尋找月神鐮刀……而且，他甚至可能已經找到了。如果他有了那東西，整個赤脊山脈地區，甚至是整個暴風王國都會被他的黑暗力量所征服。$B$B我還沒有想到對付莫甘斯的辦法，但我怕如果現在不行動的話，也許以後就沒有機會了。所以我希望你能殺進伊爾加拉之塔與莫甘斯交戰。$B$B戰勝他，然後把他的暗影墜飾帶回來給我。如果你成功了的話，整個王國都將以你為傲。",objectives={"擊敗莫甘斯。$B$B將他的陰影墜飾帶給塞歐克瑞圖斯，他就在艾爾文森林內的阿祖拉之塔中。"}]])
R(250,"水壩危機",[[description="老天保佑，現在終於有人關心水壩的安全了。先是有人摧毀了薩多爾大橋，然後又有人搶劫丹莫德！我敢說這座大壩肯定會是黑鐵組織下一次襲擊的目標。這裡的駐軍——包括我的長官在內——大部分都開到了聯盟前線。$b$b這就是我需要你的原因，$N。我看見有幾個黑鐵工兵在水壩東邊的斜坡下轉悠。去那裡查看一下，帶回點線索給我。",objectives={"查看水壩東邊斜坡附近的區域，調查一下黑鐵矮人準備做什麼，然後把線索帶給主工程師辛德維爾七世．"}]])
R(251,"翻譯亞伯克隆比的信",[[description="Take the note you gave me to Sirra Von'Indi.  He's very learned in languages and ancient arts - if anyone here can translate this message, it's he.",objectives={"Bring the Letter to Ello to Sirra Von'Indi."}]])
R(252,"翻譯好的信件",[[description="Oh my!  If what is written on this note is true, then Abercrombie's done something...unspeakable.$B$BYou better bring the translated note back to Ello.$B$BAnd do so quickly, for I fear a doom already lumbers toward our town...",objectives={"Bring the Translated Letter to Lord Ello Ebonlocke"}]])
R(253,"藏屍者的妻子",[[description="藏屍者是個我們經常用來嚇唬孩子的故事裡的人物。他曾是個善良的煉金師，但因為妻子伊莉莎的死而變得瘋狂。為了讓妻子復活，藏屍者用黑暗的魔法將自己的心臟放入了亡妻的胸膛裡。$B$B伊莉莎復活了……不過她也受到了詛咒，開始瘋狂地吞食人類的血肉，藏屍者不得不將他的妻子埋了起來。$B$B他的心臟就是他全部的力量，找到他妻子的墳墓，把他那顆仍在跳動著的心臟拿回來，就可以打破他的力量。",objectives={"找到伊莉莎的墳墓，從她的身上取回藏屍者的心臟，把它交給艾爾羅·埃伯洛克。"}]])
R(254,"掘墓")
R(255,"雇傭兵",[[description="我等了兩個月才得到了從鐵爐堡傳來的消息，說是會有少量士兵來幫助我們防守塞爾薩瑪，不過他們還得再等兩個月才能到這兒來！我們的鎮子沒人守衛已經夠糟了，但是我們的挖掘場和水壩——這些地方都隨時面臨著被襲擊的危險！$b$b看來我已經沒有選擇了，必須臨時徵召一點士兵才行。$b$b你怎麼樣？你看起來挺合適的，$c。有一群巨魔在洛克湖的東北方安營紮寨，你能不能幫忙再召集點人，去把那些傢伙趕走？",objectives={"塞爾薩瑪的鎮長埃羅恩·鈍鼻雇你去殺掉4個莫格羅什巨魔、4個莫格羅什蠻兵和4個莫格羅什執行者。"}]])
R(256,"通緝令：卓克蘇爾",[[description="以塞爾薩瑪鎮長之令：$b$b卓克蘇爾，襲擊塞爾薩瑪鎮、巨石水壩及挖掘場的巨魔的領導者和組織者。現要求不惜採用一切手段殺死卓克蘇爾。$b$b若有人呈上殺死卓克蘇爾的證明，鎮長將給予巨額獎金。$b$b卓克蘇爾最後一次出現是在洛克莫丹東北部的巨魔營地裡。",objectives={"殺了卓克蘇爾，把他的頭顱帶給塞爾薩瑪的鎮長埃羅恩·鈍鼻。"}]])
R(257,"自豪的獵人",[[description="Think you can match wits with Daryl the Bold, huh? I should think not! Of course, you're more than welcome to try. Here's a challenge that should prove to be above your abilities, so don't feel too bad if you can't face up to it.$b$bA flock of buzzards has nested here in Loch Modan. Why don't you try to take down some of the beasts? Tell you what, if you meet my challenge in fifteen minutes, I'll give you my bow or gun.$b$b<He looks you over dismissively.>$b$bIt seems you haven't much to lose, anyways.",objectives={"Kill 6 Mountain Buzzards and return to Daryl the Youngling in the Farstrider Lodge within 15 minutes."}]])
R(258,"獵人的挑戰",[[description="$nath, is it? I can tell you're bursting with pride over completing the first test, hm? As I told you before, it's no large feat.$b$bYou should try your hand at boar hunting. Trust me, this is no Coldridge Valley boar hunt, so you'd best have a care with them. I'll give you just twelve minutes this time.$b$bDon't feel bad if you fail. I'd give you the shirt off my back if you succeeded!$b$bHave I ever related to you the story of how I received my famous scar? No? It was two years ago...",objectives={"Kill 5 Elder Mountain Boars and return to Daryl the Youngling in the Farstrider Lodge within 12 minutes."}]])
R(259,"<UNUSED>",[[description="Hello there, $n. I've heard much about your exploits, and must say I'm honored to meet you. I don't suppose you've heard the story of Ol' Kelt? Ah, well, Ol' Kelt--Kelt Thomasin, that is--was once considered one of the finest hunters in all the realm. There wasn't much he hadn't done, but then, one day, he became obsessed with an ancient story... a myth, really. Well, as the stories go, a huge threshadon lives in the waters of the lake. Hogwash, if you ask me. If you're interested, you might talk to Kelt.",objectives={"Talk to Kelt Thomasin."}]])
R(260,"<UNUSED>",[[description="Now, this will no doubt convince you that I am, as they say--and don't deny it, I know what they say--of an addled mind, obsessed with an impossible legend. An old dwarven legend, it is, of an enormous monster that lives in the depths of the Loch. I spent a good bit of my life trying to track it down, and I believe I got close, but alas, I fear old age has caught up to me. If you would like to try hunting down the monster of the Loch, bring me some treshadon teeth and claws.$B$B<He smiles mysteriously.>",objectives={"Collect 5 Threshadon Teeth and 5 Threshadon Claws, then bring them to Kelt Thomasin."}]])
R(261,"血色之路",[[description="坦率地說，我們現在正在與天譴軍團交戰。他們是一群致力於腐化我們的人民、污染我們的土地的惡魔。我們一定要在他們將我們最後的堡壘徹底血洗、將我們的世界徹底拖入黑暗之前阻止他們。我們血色十字軍發誓要奉獻出全部身心，與天譴軍團鬥爭到底。$B$B如果你也如此宣誓了的話，鼓起你的勇氣並證明你的忠誠——去與淒涼之地的亡靈劫掠者們作戰吧，它們都聚集在那個地區南部的白骨之谷裡。$B$B只有這樣，十字軍才會接納你。",objectives={"殺掉30個亡靈劫掠者，然後向尼耶爾前哨站的安東修士覆命。"}]])
R(262,"模糊的人影",[[description="I must know who was that skulker in the shadows I saw the night my family was killed!$B$BPlease, $N, you have shown your resourcefulness.  Please find that shadowy figure.  I must learn what secrets he holds!$B$BI do not have clues that you do not already know, but here - take the book you found at my farm.  Perhaps some of the townsfolk can link this book with its owner.",objectives={"Take the book you found at Sven's farm and show it to townsfolk in Darkshire."}]])
R(263,"保衛國王的領土",[[description="The Mountaineers tell me you are quite brave and capable, $N.  We need a $r like you around here.  The Trogg problem isn't getting any better.  The reserves have been called to the front and we're all alone out here.  But now that we have a seasoned $c here, let's see what you can do.$b$bGo out and kill 10 Stonesplinter Shaman and 10 Stonesplinter Bonesnappers.  Let's see if you live up to your reputation, Trogg-Slayer.",objectives={"Mountaineer Wallbang in the southern guard tower wants you to kill 10 Stonesplinter Shaman and 10 Stonesplinter Bonesnappers."}]])
R(264,"至死方休",[[description="太過份了！他因為那該死的十字軍離開了我，說什麼「聖光是我們用來與不死族抗爭最重要的東西。」$B$B那麼，他的孩子呢？我呢？我日復一日地等他……一直在默默地支持著他那該死的職責！$B$B好吧，看看「正義」帶給你的一切，$N！他已經死了，而我卻成了他曾經想要阻止的人！$B$B把這個垃圾放到他在瑟伯切爾的墳墓上吧。我不想再跟這個東西…或是他有任何聯繫了！",objectives={"把克拉莉斯的墜飾放在銀松森林尤瑞夫的墳墓上。"}]])
R(265,"繼續搜尋",[[description="Here is your book back, $N, and I bid you fortune with your search.  If you ask others in town, perhaps they can offer you more clues.$B$BAnd here is one more for you - although the author of this book is a stranger to Darkshire, the book itself was purchased here.",objectives={"See if other townsfolk have clues about the shadowy figure."}]])
R(266,"調查旅店",[[description="Here is your book, and good luck with your inquiries.$B$BYou might want to expand your search to the inn.  If the person whom you seek spent time in town, then chances are someone saw him there.",objectives={"Search the inn for clues about the shadowy figure."}]])
R(267,"穴居人的威脅",[[description="$C，你可能不知道矮人的領地正在面臨著穴居人的威脅。鐵爐堡的預備部隊已經被派到聯盟前線去了，只有很少一部分被留下來負責保衛這裡的安全。我的部隊負責看守這裡的大門，提防隨時可能到來的攻擊，我們絕不能因為害怕而離開這裡。$b$b不過我們得給山裡的那些穴居人施加點壓力。如果你能勝任這個工作，就去幹掉這些穴居人，然後帶8顆穴居人的石牙回來作為勝利的證明。",objectives={"給南部警戒塔的拉格弗斯上尉帶去8顆穴居人的石牙。"}]])
R(268,"回復斯溫",[[description="The book you found was only half finished.  I had to leave it at Sven's farm when I fled there...$B$BHere.  Take my completed journal to Sven.  It describes more fully what happened at his farm.$B$BAlthough this journal has been my only company these past weeks, if giving it up keeps me from having to face Sven and his wrath, then I do it willingly!",objectives={"Return to Sven with Jitters' completed journal."}]])
R(269,"尋求指引",[[description="到暴風城去找光明大教堂的主教法席恩，把基特斯的日記給他看一看，告訴他你決心要和摩本特·費爾進行面對面的較量。$B$B雖然暴風城拋棄了夜色鎮，但是法席恩主教是個善良而又睿智的人，也許他能給你一些幫助。$B$B你的使命非常危險，不過請動作快點，$N。籠罩夜色鎮的黑暗力量無時無刻不在變得更加強大。",objectives={"把基特斯的日記交給暴風城的主教法席恩。"}]])
R(270,"被詛咒的艦隊",[[description="幾年前，庫爾提拉斯的第三艦隊在濕地的海岸線附近全軍覆沒，對，就是丹莫洛北方的那塊濕地。其中一條船上滿載著光鑄鐵。$B$B這種金屬對我們來說相當珍貴，它們可以用來製造出附有神聖力量的武器。如果你要去與摩本特·費爾作戰的話，應該會需要這樣一把武器。$B$B去米奈希爾港找我的矮人同事戈羅林·鋼眉談談吧，如果你可以找到那些丟失了的金屬，他應該會知道該到哪裡去找。",objectives={"到濕地的米奈希爾港去，找戈羅林·鋼眉談話。"}]])
R(271,"維林的報復",[[description="你沒被達瑞爾氣得昏頭昏腦吧？雖然我不願意承認，但達瑞爾還是有點能耐的。$b$b一年前，整個旅行者營地裡的獵人都在捕獵一隻巨熊，不過沒有一個人能解決掉它。後來，達瑞爾也去試了試，結果他的臉上就留下一道了醜陋的傷疤。$b$b如果你能殺了那隻熊，就算是達瑞爾也會啞口無言的。$b$b那隻名叫奧爾蘇迪的熊就住在塞爾薩瑪附近的山上。",objectives={"殺掉奧爾蘇迪，把它的頭顱帶給旅行者營地裡的達瑞爾。"}]])
R(272,"海獅試煉",[[description="For the second trial, you'll need the two halves that make the Pendant of the Sea Lion.  One half draws power from the agility of the sea lion aspect, gliding through water; the other draws power from the incredible endurance of the sea lion aspect.  Druids draw on both these traits equally to embody the aspect of their aquatic form.$B$BSpeak with the locals of Moonglade to learn where the parts may lie, and bring both here to join them together.  Once formed, take the pendant to Dendrite Starblaze.",objectives={"Find the Half Pendant of Aquatic Agility and the Half Pendant of Aquatic Endurance.  Speak with the residents of Moonglade to learn clues as to where these items may be located.$B$BForm the Pendant of the Sea Lion from the two pendant halves.  You need to be in proximity of the Shrine of Remulos to do this.$B$BBring the joined pendant to Dendrite Starblaze in the village of Nighthaven, Moonglade."}]])
R(273,"挖掘場的補給品",[[description="It's not too late though, you're welcome to go look for Huldar. He can't have made it very far, strong as they are, Miran and Saean can only move so fast laden down with those barrels.$b$bThey're taking the normal route to the site, leaving south out of town and following the curve of the Loch.$b$bShouldn't have a problem finding them unless they've already gotten there.",objectives={"Speak with Huldar."}]])
R(274,"水壩危機",[[description="This ain't no ordinary blast powder.  Look at the tiny silver crystals.  And the distinct smell!  Why it's clear as daylight that this is Seaforium Powder.  Seaforium is harmless enough.  But once it's wet it could blow Ironforge out of the mountain.$b$bThe chemical reaction can be defused by mixing four components:  lurker venom, crushed Mo'Grosh crystal, a crocolisk tear and this disarming colloid.  Now tell Hinderweir before it's too late!",objectives={"Ashlan Stonesmirk wants you to return to Chief Engineer Hinderweir and inform him of the new discovery."}]])
R(275,"大地上的膿皰",[[description="我不知道是怎麼回事，但是墮落正在濕地上蔓延。沼澤爬行者出現了，他們就像是腐爛而危險的膿皰。要制止這些膿皰，就必須把他們驅散開，把它們趕回沼澤。$B$B這些沼澤爬行者一般都在濕地的水道裡活動。",objectives={"殺死12隻沼澤爬行者，然後向濕地的綠色守衛者雷希耶爾覆命。"}]])
R(276,"踐踏之爪",[[description="The Mosshide Gnolls have lived in the Wetlands peacefully for many years, but now grow in numbers.  Their feet stamp flat the fen's bushes and flowers, and their foul axes cut too much wood to fuel their fires.$B$BThey are no longer in balance with the land.  For the Wetlands to survive, the Gnolls must be reduced.$B$BKill 15 Mosshide Gnolls and 10 Mosshide Mongrels.  Hunt them to the south, near the Dwarven gate of Algaz.  After you do this, return to me.",objectives={"Kill 15 Mosshide Gnolls and 10 Mosshide Mongrels, then return to Rethiel the Greenwarden in the Wetlands."}]])
R(277,"火焰管制",[[description="The Mosshides are cutting the trees of the Wetlands, using the trees' flesh to warm themselves with fire.  I will suffer this pain no longer!$B$BRid the Mosshides of their crude flints, the tools they use to make fire.  The flints are borne by all Mosshides except the smaller Mosshide gnolls and Mosshide mongrels.",objectives={"Bring Rethiel the Greenwarden 9 Crude Flints."}]])
R(278,"水壩危機",[[description="你必須立刻去收集拆彈用的原料，$N。潛伏者的毒液在洛克莫丹的蜘蛛身上可以找到，鱷魚的眼淚在洛克湖一帶的鱷魚身上也有。不過莫格羅什水晶很難找到。東北邊礦坑裡的巨魔開採這種水晶，不過即使在那裡，莫格羅什水晶也不常見。$b$b我們必須要作好準備才能粉碎黑鐵矮人的計畫！你找齊了這些材料之後就立刻回來找我，我會把它們做成拆彈劑。",objectives={"主工程師辛德維爾七世要你收集一份潛伏者的毒液，一塊莫格羅什水晶和一滴鱷魚的眼淚。"}]])
R(279,"海中的魚人",[[description="可惡的魚人正在從深海裡源源不斷地爬出來，它們沿著海岸線建立自己的村莊和定居點。這些傢伙給我們的漁民和商人帶來了極大的困擾，我們必須要阻止這種行為。$B$B它們當中有一個叫高布勒爾的頭目最近一直帶著一群藍腮魚人埋伏在道路旁，搶劫過往的商旅，得手之後又馬上撤回它們的村子。現在我們的通商道路非常危險，所以我們想要通過懸賞來解決這個問題。$B$B高布勒爾和它的跟班們就躲在北邊的河口附近。找到它，把它幹掉，然後把它的頭給我帶回來。",objectives={"殺掉12個藍腮魚人。$B$B殺掉高布勒爾並砍下它的頭。$B$B將高布勒爾的頭顱交給米奈希爾港的卡爾·波蘭。"}]])
R(280,"水壩危機",[[description="今天早些時候我發現有一些黑鐵矮人背著一隻大木桶向水壩遊去，糟糕的是那一帶沒有巡山人可以攔住他們！我懷疑他們已經把爆鹽炸藥放到了水壩下面，隨時都有可能爆炸！我馬上就把這些成分混合在一起製成拆彈劑。$b$b完成了！現在我要你把這個混合劑拿去，和木桶裡的炸藥攪拌在一起！快一點！我們沒時間了！",objectives={"主工程師辛德維爾七世要你遊到水壩底部，找到裝著炸藥的木桶，然後把拆彈劑放進去，阻止將要發生的爆炸。"}]])
R(281,"奪回雕像",[[description="不久之前，有一艘名叫「盲眼公主」的商船遭到了一群魚人的襲擊。儘管這艘船完完整整地逃了出來，但船甲板上放著的貨物都被那些該死的魚人給拖下水搶走了，其中甚至包括一座十分寶貴的泰瑞納斯·米奈希爾的雕像。我們希望有人能把這座雕塑給搶回來。$B$B到海岸邊的魚人村落裡去，仔細找找看有沒有木箱、木桶，或者其他丟失貨物的蹤跡。在那裡找到米奈希爾雕像，然後回來向我覆命。",objectives={"搜索海邊魚人村落中的木箱和木桶。"}]])
R(282,"森內爾的觀察站",[[description="我原本打算讓我的學徒幫我把報告送去給我的兄弟森內爾。但是如果有個更可靠的人替我送去的話就更好了。如果你不介意的話，可以去一趟嗎？$b$b嗯……你必須穿越隧道到卡拉諾斯去。$b$b在穿越隧道前，別忘了和巡山人泰洛斯聊聊，那裡的穴居人簡直氾濫成災了。$b$b順著這條路回安威瑪，然後向東走就能到隧道了，泰洛斯就駐守在附近。",objectives={"和巡山人泰洛斯談話。"}]])
R(283,"水壩危機",[[description="木桶發出了輕微的嘶嘶聲。",objectives={"拆彈劑看來已經產生了效果。你可以回去向主工程師辛德維爾七世彙報這個好消息了。"}]])
R(284,"繼續搜尋",[[description="你繼續在魚人的村莊中仔細搜索著，但沒有找到任何關於米奈希爾雕像的蛛絲馬跡。$B$B也許北邊和東北邊的另兩處魚人村落那會有些什麼線索。",objectives={"搜索米奈希爾雕塑。"}]])
R(285,"搜尋雕像",[[description="你仔細地搜索了這幾處魚人村落，但卻沒什麼有價值的發現。$B$B……但你有一種直覺，就是你在下次搜索中一定能找出一些很有價值的線索。$B$B北邊的最後幾處村落裡一定會有米奈希爾雕像！",objectives={"繼續在魚人村落中搜尋米奈希爾雕像的蹤跡。"}]])
R(286,"歸還雕像",[[description="你把這個木桶從垃圾裡拖了出來，剛一打開它，一尊精心包裹在稻草中的銀制小雕像就掉了出來。這是一個頭髮很長的年輕聖騎士高舉戰錘的樣子。$B$B這一定就是米奈希爾雕像了！你必須馬上把它交還給米奈希爾港的卡爾·波蘭。",objectives={"將米奈希爾雕像還給卡爾·波蘭。"}]])
R(287,"霜鬃巨魔要塞",[[description="我快要來不及提交報告了，你能幫我一下嗎，$n？我只想知道這些食人妖躲在什麼地方，不過我看見這麼多的食人妖就怕得不敢進去了。$b$b你要做的是……進到山洞裡，在裡面到處走走，幹掉一些食人妖，然後再回來。$b$b順著向北的路離開卡拉諾斯，當你走到一座橋前的時候，再沿著冰凍的河流向西一直走到湧冰湖。你會發現烈酒村就在湖的西岸，而食人妖要塞就在村莊的西南邊。",objectives={"偵查霜鬃食人妖要塞，替卡拉諾斯的森內爾·白鬚殺掉5個霜鬃獵頭者。"}]])
R(288,"第三艦隊",[[description="我曾經是浪花女神號上的大副——浪花女神是庫爾提拉斯第三艦隊的主力戰艦。這是一支多災多難的艦隊，說它多災多難是因為……它在最後一次出航中遇到了紅龍的襲擊。這些龍是被獸人控制的！$B$B紅龍噴出的火焰對我們的戰艦來說簡直是毀滅性的……我們的艦隊在這片海域被燒得一乾二淨，全軍覆沒。我是那次災難的唯一倖存者……$B$B……哦，我的頭疼得像鼓槌在敲！我需要一些讓我頭腦清醒的東西，好讓我繼續講述我的故事。",objectives={"為大副菲茲莫斯買一份壺裝蜜酒。"}]])
R(289,"被詛咒的船員",[[description="<緩過氣來的菲茲莫斯繼續講述他的故事……>$B$B我是這支倒楣的庫爾提拉斯第三艦隊中唯一的倖存者，整支艦隊都在北方的海岸附近覆滅了。不過，雖然我是艦隊中唯一活著的人，卻不是唯一一個依然在這裡出現的人！因為，在一條已經沉沒的船裡，藏有巨大的、可怕的寶藏，它所擁有的可怕魔力將我的弟兄們的靈魂束縛在被海水侵蝕的船體裡。$B$B如果你能超渡我的那些被詛咒的弟兄們，也許你就能破除那個詛咒。",objectives={"殺死13個被詛咒的水手、5個被詛咒的水兵和大副斯涅利格。把斯涅利格的鼻煙盒交給米奈希爾的大副菲茲莫斯。"}]])
R(290,"解除詛咒",[[description="為了破除詛咒解救我所有的同胞，就必須要把裝在我船上的那個...鬼東西...拿回來進行淨化！我不知道它是什麼，但我知道它被存放在船上的保險箱裡，而保險箱的鑰匙一向是由哈林多爾船長保管的。$B$B我的老船長仍時常出現我的夢裡，我知道他就在我那艘已毀滅的無畏號上走來走去。向他拿到鑰匙，用它打開無畏號上的保險箱。$B$B然後，在你獲得那件被詛咒的東西以後，把它交給鎮上的牧師，戈羅林·鋼眉。",objectives={"從哈林多爾船長那裡拿到無畏號的保險箱鑰匙。$B$B用鑰匙打開無畏號上鎖的保險箱。"}]])
R(291,"森內爾的報告",[[description="好極了！把我的報告交給參議員巴林·紅石。他是個酸溜溜的傢伙，你可別在意。他在鐵爐堡，麥格尼陛下的宮殿裡。$b$b你不知道去鐵爐堡的路？順著這條路向北走出卡拉諾斯，穿過一座橋，然後沿著路向東走——在路邊山上應該有個很大的路標。$b$b順便說一句，你最好不要提及你是如何幫助我的，不要讓他們以為我在這裡沒有好好工作，好嗎？",objectives={"把森內爾的報告交給鐵爐堡的參議員巴林·紅石。"}]])
R(292,"帕雷斯之眼",[[description="打開箱子之後，你看到了一顆發黑的寶珠，它還在閃爍著可怕的光芒。這就是菲茲莫斯所說的寶藏：一顆被詛咒的帕雷斯之眼。$B$B把被詛咒的帕雷斯之眼交給住在米奈希爾港的矮人牧師戈羅林·鋼眉，請他驅除附著在它上面的詛咒。",objectives={"把被詛咒的帕雷斯之眼交給戈羅林·鋼眉。"}]])
R(293,"凈化帕雷斯之眼",[[description="我無法驅散帕雷斯之眼上的詛咒。它是由人類牧師手工製造的，所以你最好去暴風城尋找幫助。去和大主教本尼迪塔斯談談吧，他是暴風城光明大教堂的領導者，他能幫你解決問題。$B$B我希望如此。",objectives={"把被詛咒的帕雷斯之眼交給大主教本尼迪塔斯，他就在暴風城的光明大教堂裡。"}]])
R(294,"奧莫爾的復仇",[[description="目前我們所面臨的形勢十分嚴峻，這已經是眾所周知的事了。我們剛挖出這些骨頭，它們就招來了一大群迅猛龍。這些兇殘的野獸殺光了我的弟兄們，並把我、麥琳和可憐的勘察員困在了這上面。$b$b幫我把濕地裡的這些迅猛龍都給殺光，$N。雜斑迅猛龍和雜斑尖嘯龍就在山崖的西邊，要是你有能力對付它們的話，每種都給我殺上十隻。$b$b這只不過是我對它們的復仇計畫的開始而已！",objectives={"維爾加挖掘場的奧莫爾·鐵衣要求你殺死10隻雜斑迅猛龍和10隻雜斑尖嘯龍。"}]])
R(295,"奧莫爾的復仇",[[description="現在是時候讓這些該死的迅猛龍為它們的嗜血而後悔了。在懸崖下面還有一些雜斑刺喉龍和雜斑鋸齒龍，每種都給我殺10隻，它們要為自己的所作所為付出代價！",objectives={"奧莫爾·鐵衣要求你殺死10隻雜斑刺喉龍和10隻雜斑鋸齒龍，然後回到維爾加挖掘場向他覆命。"}]])
R(296,"奧莫爾的復仇",[[description="While you were down there I happened to notice that one of those beasts stood out from the rest.  He was bigger and more menacing.  I bet he's the one who led the others here to cause the disruption to the dig site.$b$bI ask of you now one final task, $N.  See to it that Sarltooth is brought to justice.  And considering the gravity of his crimes, justice in this case means death!  Bring me one of his talons as proof of his death.",objectives={"Ormer Ironbraid at the Whelgar Excavation Site wants you to kill Sarltooth and return to him with one of his talons once the task is fulfilled."}]])
R(297,"收集石像",[[description="Recently, just before the Troggs surfaced within the site, we had uncovered a large number of strange, carved idols.  But we didn't have the chance to study them, for soon after their discovery the Troggs chased us away from the ruins!  And those idols have a strange effect on the Troggs.  It makes them go berserk!$B$BBring me 8 idols - I want to study them, and I want them out of Trogg hands!  You can find the idols on the Troggs infesting the site.",objectives={"Bring Magmar Fellhew 8 Carved Stone Idols."}]])
R(298,"挖掘進度報告",[[description="I need a progress report sent to Thelsamar - a progress report, and a restatement of my request for more blastpowder!  Here's the report.  Take it to Jern Hornhelm.  He's our local contact in Thelsamar.$B$BIt's not a difficult task, but it must be done.",objectives={"Bring Ironband's Progress Report to Jern Hornhelm in Thelsamar."}]])
R(299,"發現歷史",[[description="在迅猛龍大舉入侵之前，我找到了一塊名叫戈奧茲之石的巨大石碑。我翻譯好的文字被分成了四部分，散落在挖掘場中的四個不同的地方。這些文字描述的是一個「神聖的計畫」和一個「註定的命運」。$b$b我們應該馬上把它們都收集起來，而不是繼續在這裡浪費時間。但是我已經很老了，恐怕沒辦法再殺出去跟那些兇猛的野獸作戰了。但是你不同，你年輕而強壯。$b$b到挖掘場裡去搜索這四片失落的石板：阿度斯石板、莫德爾石板、高爾姆石板和奈爾魯石板。它們應該被藏在某些古董器物裡，另外你也得留意土壤鬆動的地方。把它們拿回來給我，這樣我才能揭開這個秘密！",objectives={"勘察員維爾加要求你在挖掘場中搜索4塊石板的碎片，它們是阿度斯碎片、莫德爾碎片、高爾姆碎片和奈爾魯碎片。"}]])
R(301,"向鐵爐堡報告",[[description="We'll need approval to get Ironband more blastpowder. You'll have to take his report to the Explorers' League headquarters in Ironforge.$B$BHere's the report. Give it to Prospector Stormpike, and don't forget to duck after you deliver it. Stormpike is hotheaded, and he won't be happy to hear of Ironband's slow progress at the site.$B$BYou'll find Stormpike in the Assembly of Explorers.",objectives={"Take Ironband's Progress Report to Prospector Stormpike."}]])
R(302,"鐵環的火藥",[[description="If Ironband still needs blastpowder, then by Magni he'll have it!  I sent the approval on ahead with a messenger to Jern Hornhelm in Thelsamar.  He'll prepare the powder and other supplies to take to Ironband.$B$BAnd one more thing: I want you to personally see that the shipment of powder reaches its destination.  The last one didn't, so keep your mind sharp and your eyes open.",objectives={"Speak with Jern Hornhelm in Thelsamar."}]])
R(303,"黑鐵戰爭",[[description="戰火席捲了整個世界。當許多精銳的矮人士兵們為了聯盟而犧牲在前線時，我們自己的土地卻淪為了這群邪惡的黑鐵矮人覬覦的目標。他們已經攻陷了薩多爾大橋，丹莫德也岌岌可危。$b$b我們要你去聚集起一股力量，並將戰線推回去。如果你能殺死十五名黑鐵矮人、五名黑鐵隧道工、五名黑鐵破壞者和五名黑鐵爆破手的話，就能為我們組織反擊爭取到寶貴的時間。$b$b兵貴神速，快出發吧！",objectives={"丹莫德的莫特雷·加瑪森要求你殺死15名黑鐵矮人、5名黑鐵隧道工、5名黑鐵破壞者和5名黑鐵爆破手。"}]])
R(304,"艱巨的任務",[[description="我手下的大部分士兵都在丹莫德的戰役中死去了，我的親兄弟也在薩多爾峽谷上的西橋被毀的時候不幸犧牲。唉，黑鐵矮人真是個像惡魔一般邪惡的族群。根據羅戈收集到的情報，這群在濕地四處肆虐的暴徒的領袖是一個名叫巴爾加拉斯的術士。他是個十分膽小謹慎的傢伙，在把手下的士兵送上戰場執行命令的時候，他自己往往卻躲藏在某個不為人知的地方，躲避著任何可能面臨的危險。$b$b如果你能找到這個懦夫，殺了他，把他的耳朵拿來給我，我會給你支付可觀的酬勞的，$c。",objectives={"殺死邪惡的巴爾加拉斯，把他的耳朵帶給丹莫德外的布萊德·長鬚。"}]])
R(305,"尋找挖掘隊",[[description="啊，天呀，你一定就是長鬚派來的幫手！你真是不知道我有多擔心。$b$b我的老婆麥琳上個月的時候每禮拜都會給我寫一封信的。她是維爾加挖掘隊的成員，她最後一次寫信過來是兩週前的事了。一定是出了什麼事！$b$b長鬚說，要是我們一直都沒有收到挖掘隊那邊送來的信，那麼他就會派出一名探子去看看情況。我猜那個探子應該就是你吧，$N。快去東邊的挖掘場裡找到麥琳！",objectives={"塔雷爾·石紋要求你到挖掘場裡去找到麥琳·石紋。"}]])
R(306,"尋找挖掘隊",[[description="這太恐怖啦！我們剛剛發現了一些十分稀有的古物，而且正在把這些巨大的骸骨挖掘出來，這個時候，可怕的事就發生了，在我們反應過來之前，多到數不清的雜斑迅猛龍沖進了挖掘場，咬死了許多人！$b$b勇敢非凡的奧莫爾救下了我和勘察員，並一直把我們護送到了一處藏身之所。現在我們被徹底困在這裡了，逃也逃不出去，我們努力工作的成果也全毀了。$b$b給，把這封信帶回去交給我親愛的塔雷爾，我已經在信裡把事情跟他解釋清楚了。",objectives={"把麥琳的信件交給塔雷爾·石紋覆命。"}]])
R(307,"骯臟的爪子",[[description="東邊的銀泉礦坑很久以前就枯竭了。礦工聯盟把它改造成了儲藏庫，不過現在狗頭人佔據了那裡，把他們骯髒的爪子放在了我們矮人製造的工具上！$B$B我們很快就能把這些害人蟲趕走，但是礦工聯盟要求我們在衝進去大開殺戒之前，先把洞裡的礦工裝備拿出來。這是個艱難的任務——你也許需要幾個幫手。$B$B他們的裝備就在礦工聯盟的儲物箱裡，祝你好運。",objectives={"到銀泉礦坑去收集4套礦工裝備，然後向巡山人卡爾·雷矛覆命。"}]])
R(308,"加文的愛好")
R(309,"護送貨物",[[description="Ready to go, $n?$b$bFirst, we need to get this powder to Ironband. It'll be a lot for me to carry, and these parts can get dangerous -- and who knows what else the Dark Irons might have in store for me.$b$bI'll feel a lot better with you coming along.",objectives={"Ensure Miran and the shipment arrive at the excavation site, then inform Prospector Ironband."}]])
R(310,"針鋒相對",[[description="我不得不承認，雷酒家族的那幫傢伙釀酒水準還真不賴。但是他們應該知道他們的酒並不是世界上最好的！也許你能幫我讓他們瞭解這一點……$B$B拿著，帶著這桶熱麥酒，想辦法潛入卡拉諾斯的雷酒釀製廠的酒窖，把他們的雷霆啤酒和我們的換一下。然後，我們就等著看好戲吧，顧客們肯定會更喜歡我的酒！$B$B如果有人看著酒桶的話，你就得想辦法轉移他的視線……",objectives={"到卡拉諾斯的雷酒釀製廠酒窖裡去，把一桶雷霆啤酒換成熱麥酒。"}]])
R(311,"向馬萊斯回報",[[description="把一桶馬萊斯的熱酒放進了卡拉諾斯釀酒間的地窖裡之後，你取回一桶雷霆麥酒作為行動成功的證明。",objectives={"把雷霆麥酒交給烈酒村的馬萊斯·麥酒。"}]])
R(312,"馬克格拉恩的幹肉",[[description="我原本儲備了一個月的乾醃肉準備過冬，為了防止野熊把肉銜走，我把它們鎖在了儲藏櫃裡。但是在我外出打獵的時候，一個叫做冰鬚的野獸偷走了我的儲藏櫃！可笑的是那個蠢貨撬不開這只用瑟銀鑄成的櫃子。$B$B但是如果拿不回這些肉，我就會餓死的。你的身手看來不錯，也許你能幫我取回儲藏櫃？你瞧我拖著這條廢腿也沒辦法把那只櫃子搶回來……",objectives={"從冰鬚的洞穴裡拿回裝有馬克格拉恩的乾肉的儲藏櫃。"}]])
R(313,"灰色洞穴",[[description="不是每個人都能駕駛攻城坦克的，你必須要有強壯的身體和鋼鐵般的神經……幸運的是，這兩個條件我都有！你呢？你有足夠的勇氣嗎？想不想證明給我看？$B$B啊……我想把我的「食人妖碾壓者」號坦克改造得更舒適些，你去幫我在卡拉諾斯西邊的灰色洞穴里弄一堆雪怪的鬃毛來吧，我要用那些鬃毛做一張大毯子來裝飾我那「食人妖碾壓者」的駕駛艙。",objectives={"收集8束雪怪的鬃毛，把它們交給駕駛員迪恩·石輪。"}]])
R(314,"保護牲畜",[[description="午夜的時候，我們聽到了吵鬧的聲音。今天早上我才發現羊圈裡少了兩隻羊，那頭名叫瓦加什的野獸襲擊了我們的牲畜。由於國王麥格尼的軍隊大都在遙遠的戰場上與聯盟其他的種族並肩作戰，所以沒有人能對付得了瓦加什。$b$b也許你有勇氣找到這只猛獸並殺了它。把它的一顆牙齒交給我作為證明，我會獎賞你的。瓦加什就躲在這裡的農場附近，小心點，它非常兇殘。",objectives={"山羊農場的魯德拉·凍石要你殺了瓦加什，並且把它的牙齒給她帶回去。"}]])
R(315,"完美烈酒",[[description="我正在尋找，尋找可以釀製完美烈酒的方法。我知道我能做到 - 釀酒就像我的生命一樣。我缺的只是一份正確的釀酒配方……$B$B霜鬃食人妖在東邊的山坡上種植了一種叫做微光草的植物。他們通常在奇怪的部族儀式才會用到它。我們矮人還沒有發現這種草有太多的用途，不過它有種非常獨特的味道……我要用這種植物釀造我的酒！$B$B從霜鬃先知那裡弄一些微光草來給我，或者你也可以從食人妖用來裝微光草的籃子裡偷一些。",objectives={"收集6束微光草，把它們交給烈酒村的雷傑德·麥酒。"}]])
R(316,"<UNUSED>")
R(317,"貝爾丁的補給",[[description="我正在準備為攻城坦克旅執行一項任務。這次任務會持續很長時間，所以我得預先收集能夠維持一個月的物資。貝爾丁正忙著修理我的坦克，你能幫我去弄一些東西來嗎？$B$B我需要一些毛皮來做床墊，還要一些野豬肉作為食品儲備。豬肉當然是從野豬身上割下來的，最好的毛皮是熊皮……在灰色洞穴南部的雪地上到處都是這兩種動物的蹤跡。",objectives={"收集4大塊野豬肉和2張厚熊皮，把它們交給鋼架補給站的駕駛員貝隆·風箱。"}]])
R(318,"艾沃沙酒",[[description="雷傑德·麥酒一直以來都親口試驗他自己釀製的酒。有的好喝，有的難喝，還有的連酒量最好的矮人都能輕鬆放倒。$B$B他住在烈酒村，那地方就在卡拉諾斯的西邊。我需要一些他釀造的那種叫作艾沃沙的酒，在寒冷的旅程中，喝這種酒能幫我暖暖身子。$B$B還有……這種酒實在是太烈了，在緊要關頭還可以當燃料使，只要把它注入我那坦克車的油箱裡，整輛坦克都會爆發出無窮的力量！這個小訣竅讓我不止一次地化險為夷。",objectives={"從烈酒村的雷傑德·麥酒那里弄到一桶艾沃沙酒。"}]])
R(319,"艾沃沙酒",[[description="我有一桶釀製好的艾沃沙酒，不過……你能幫我個忙嗎？烈酒村急需人手去對付在村子附近溜達的野獸。有時它們離我們非常近，那真是太危險了。$B$B我們並不害怕這些熊啊，豹啊，野豬啊——任何一個有自尊的矮人都不會害怕——不過，如果你能替我把它們搞定的話，我就能騰出更多的時間來釀酒了。",objectives={"殺掉6頭冰爪熊、8隻老峭壁野豬和8隻雪豹，然後回到烈酒村的雷傑德·麥酒那裡。"}]])
R(320,"艾沃沙酒",[[description="這是你要的艾沃沙酒，$N。再次感謝你給予我們的幫助。",objectives={"把這桶艾沃沙酒交給鋼架補給站的駕駛員貝隆·風箱。"}]])
R(321,"光鑄鐵",[[description="這附近的海灘上的船隻殘骸大多是屬於庫爾提拉斯第三艦隊的，在上一次大戰中，那支艦隊曾與紅龍們在此激戰，不幸全軍覆沒了。$B$B那支艦隊裡的船大多是羅德隆的戰艦，但有一艘船卻不是，那是一艘名叫「飛翔魚鷹」的精靈驅逐艦。它運著滿滿一船的光鑄鐵加入了第三艦隊的船隊中，本以為這樣就足夠安全了，結果卻諷刺性地落得個被紅龍擊沉的厄運……$B$B故事就講到這兒吧，飛翔魚鷹的殘骸就在米奈希爾港的南邊。如果你能在那裡找到光鑄鐵的話，就把它給我帶回來吧。",objectives={"搜索飛翔魚鷹號的殘骸。"}]])
R(322,"格瑞曼德·艾爾默",[[description="暴風城矮人區有一個名叫格瑞曼德·艾爾默的矮人武器匠會用這種光鑄鐵來打造武器。$B$B我已經把你找到的這些鐵錠用木箱裝好了。把這個箱子交給格瑞曼德，再把你的事情告訴他。我敢打賭他一定會義憤填膺地馬上著手為你打造武器的，嘿嘿，那肯定是把就連摩本特·費爾看到了也會心驚膽顫的武器！",objectives={"將這箱光鑄鐵錠交給格瑞曼德·艾爾默。"}]])
R(323,"證明妳的實力",[[description="摩本特·費爾是個亡靈巫師，也是黑暗強盜的幫兇。我希望你能去除掉摩本特·費爾，不過在瞭解你真正的實力之前，我還不能貿然拿你的生命開玩笑。$B$B你已經證明了你的勇氣，不過如果你想要面對面地和這個巫師作戰，首先得證明你能應付得了他的爪牙。",objectives={"殺掉15個骷髏襲擊者、3個骷髏醫師和3個骷髏看守，然後回來見斯溫。"}]])
R(324,"丟失的鐵錠",[[description="你好不容易把那塊光鑄鐵錠從泡在水裡的箱子中拿了出來，顯然，是魚人偷走了其餘的鐵錠。獵殺飛翔魚鷹號殘骸周圍的魚人，拿到它們身上帶著的光鑄鐵錠。",objectives={"收集5塊光鑄鐵錠，把它們交給濕地的戈羅林·鋼眉。"}]])
R(325,"整裝待發",[[description="你已經準備好了嗎，$N？祝你好運！我期待著你凱旋歸來！",objectives={"現在你已經得到了強大的武器，去向暮色森林的斯溫覆命吧。"}]])
R(328,"隱藏的鑰匙",[[description="儘管在這些檔案裡都沒有提到列兵索爾森，但你發現在赫羅德的一本帳薄後面綁著一隻小小的黃銅鑰匙。$B$B你還在研究他的其他筆記時發現了其中有一小部分提到，在一個「安全的保險箱」中裝有大量的文件。這個保險箱應該在庫爾森營地後山的某處洞穴之中，他們把那裡稱為「儲藏室」。$B$B如果你能找到這個保險箱並用這把黃銅鑰匙打開它的話，或許裡面的文件有助於找到導致索爾森身份暴露的內鬼。",objectives={"使用黃銅鑰匙打開書呆子赫羅德的保險箱。"}]])
R(329,"找出內鬼！",[[description="在箱子裡的這些貴重物品之中，還有一張滿是灰塵且寫得十分潦草的便箋。儘管幾乎已經沒法辨認了，但你能看出來這便箋上面似乎描述了列兵索爾森所走的路線。這應該是他的巡邏路線，以及反抗軍方面與他接頭的人員與時間。簽名只有一個字母：M。$B$B毫無疑問，這應該是索爾森身邊的人寫下的便箋，而且這個人就是反抗軍營地中的臥底。",objectives={"將沾泥的便箋交給叛軍營地裡的多倫上尉。"}]])
R(330,"巡邏時間表",[[description="你給我的便箋上的簽名只有一個字母「M」……我也不知道這代表誰。$B$B但是……這便箋同時也告訴我們，這個人應該是上週與索爾森一同巡邏的同伴。所以，只要知道上週誰和索爾森一起巡邏過，那他就應該是內鬼沒錯了！$B$B去找塞斯曼下士問一問，他是負責制訂巡邏時間表的人，可以告訴你那個時候索爾森和誰在一起。",objectives={"與塞斯曼下士談話。"}]])
R(331,"向多倫報告",[[description="多倫上尉不是說要你向他回報關於巡邏時間安排的情況嗎？",objectives={"與多倫上尉談話。"}]])
R(332,"酒店的廣告",[[description="無論你跟任何人談起酒，大家都會告訴你加林納家賣的酒是全暴風城最好的。而且那裡離我們這兒並不遠，就在貿易區中，運河的邊上。$B$B給，拿著這張酒票。把這個拿到店裡去，交給我的姐姐蘇澤塔，她會送你一瓶我們釀造的最有名的黑葡萄酒。你絕對不會後悔的！",objectives={"到加林納酒店去, 將酒票交給蘇澤塔·加林納以換一瓶免費的酒。"}]])
R(333,"哈蘭需要供貨",[[description="我們過幾天肯定會有大單的生意。現在似乎每個人都在購買盔甲和結實的衣服，好像他們都以為明天就會變得天寒地凍一樣……$B$B但那是以後的事了。我現在最擔心的是我已經賣完了全部庫存的針織布，需要一次大批量的供貨。$B$B如果你能把我的這個要求帶給運河裁縫店的雷瑪·施涅德的話，我會非常感謝你的。",objectives={"找到運河裁縫店，並將哈蘭·巴格雷的布料訂單帶給雷瑪·施涅德。"}]])
R(334,"薩爾曼的針線包",[[description="我的兒子薩爾曼在法師區的拉爾森服裝店裡當學徒。他今天早上走得太著急了，忘了他的剪子和針線。我知道你這樣偉大的$C一般都會有些重要的事要做，可要是沒了工具的話，薩爾曼可沒辦法做他的工作呀！$B$B拜託了，$N。你能幫我把他的針線包拿去給他嗎？拉爾森服裝店是法師區裡的兩家裁縫店之一，在比較靠裡面的地方，也就是靠近法師塔的地方。",objectives={"到暴風城法師區的拉爾森服裝店去，將針線包帶給薩爾曼·斯涅德。"}]])
R(335,"名釀",[[description="維沙克公爵最近在貴族議會中造成了一股騷動。他知道我們在這裡的小小「建設」，而且還遊說其他議員進行一次全面調查。我有一個計畫能讓維沙克「忙不過來」，但我需要你的幫助。$b$b在夜色鎮郊區的斯塔文花園裡生長著一種花。這朵白色小花叫做蒂羅亞之淚。另外我還需要一些麝鼠根，那種東西只生長在濕地，就在巨石水壩下的瀑布底部。",objectives={"黑爪加爾德斯要求你從夜色鎮給他摘1朵蒂羅亞之淚，再從濕地給他采一塊麝鼠根。"}]])
R(336,"名釀",[[description="和所有人相同，維沙克公爵有自己的弱點。他對酒的愛好勝過一切。這種偽善令人震驚。這個蠢貨整天想著讓我們這個小小的酒館關門大吉，而他自己卻待在樓上整夜地喝個不停製造他付不出來的帳單。好吧，讓我們看看維沙克會多喜歡我們給他準備的這種特製佳釀：黑爪烈酒。這一定會很有意思的，$n。$b$b把這個帶給他，看看他的反應如何。這老糊塗大部分時間會在祈願廳裡閒晃。",objectives={"將黑爪烈酒帶給祈願廳裡的維沙克公爵。"}]])
R(337,"壹本破舊的歷史書",[[description="這本書的封面已經有被刮壞的痕跡，還沾上了泥汙，但是書脊上「暴風城的歷史」的字樣仍然清晰可見。打開書的第一頁，可以看到上面蓋著暴風城圖書館的印章。$B$B看起來似乎有人從圖書館借出了這本書卻從來沒有歸還……",objectives={"把《暴風城的歷史》這本書還給暴風城圖書館。"}]])
R(338,"荊棘谷的青山",[[description="如果奈辛瓦里知道了這一切，他一定會很生氣的！$b$b出於對我的信任，他讓我來校對他的小說《荊棘谷的青山》的手稿。一開始事情進行得非常順利，但昨天一陣大風吹過了營地，結果把手稿吹得滿天都是！$b$b我已經很努力地找回了大部分的書頁，但還是有幾頁被吹進了叢林中。請你幫我把這四章裡的掉落的那幾頁書都給收集起來吧。$b$b等這四章手稿都搜集齊了以後，把它們還給我。",objectives={"收集《荊棘谷的青山》的手稿中丟失的頁面。在集齊四章書之後，將它們還給巴尼爾·石罐。"}]])
R(339,"荊棘谷的青山 - 第壹章",[[description="第一章實在是太精彩了，令人欲罷不能！奈辛瓦里設定了小說的背景，而且在小說裡提到了他的同伴們，甚至包括我！$b$b不過，糟糕的是……有幾頁好像弄丟了。似乎第1頁，第4頁，第6頁和第8頁落在叢林中的什麼地方了！",objectives={"將奈辛瓦里的小說《荊棘谷的青山》的第1頁，第4頁，第6頁和第8頁帶給巴尼爾·石罐以湊齊第一章。"}]])
R(340,"荊棘谷的青山 - 第二章",[[description="第二章是整個激動人心的狩獵故事的楔子。可是裡面也有幾頁找不到了，我真想踢自己幾腳！$b$b看來我必須得找到第10頁，第11頁，第14頁和第16頁才能湊出完整的第二章。",objectives={"將奈辛瓦里的小說《荊棘谷的青山》的第10頁，第11頁，第14頁和第16頁帶給巴尼爾·石罐以湊齊第二章。"}]])
R(341,"荊棘谷的青山 - 第三章",[[description="第三章是我最喜愛的部分。裡面詳細講述了艾爾加丁爵士和羅歐克女士使用矮人步槍完成的第一次狩獵。而且第三章的結尾也寫得極好，為什麼？因為實在是太扣人心弦了！$b$b不過，讓我看看，似乎我們仍然要需要找回第18頁，第20頁，第21頁和第24頁來湊齊這一章。這些書頁不知被風吹到哪裡去了……",objectives={"將奈辛瓦里的小說《荊棘谷的青山》的第18頁，第20頁，第21頁和第24頁帶給巴尼爾·石罐以湊齊第三章。"}]])
R(342,"荊棘谷的青山 - 第四章",[[description="啊，第四章，大結局！多麼精彩的結局啊！$b$b第四章裡我們只丟了3頁，也就是第25頁，第26頁和第27頁。",objectives={"將奈辛瓦里的小說《荊棘谷的青山》的第25頁，第26頁和第27頁帶給巴尼爾·石罐以湊齊第四章。"}]])
R(343,"關於堅韌的演講",[[description="我正要作一次關於「堅韌的靈魂」的演講，我想引用一本關於金屬學的著作《金屬的延展性》裡的一些段落。暴風城堡裡的皇家圖書館裡應該有這本書的副本。你能把它拿來給我嗎？如果可以的話，聖光定會保佑你的！$B$B皇家圖書館很大，但首席管理員密爾頓·西弗對每一個書架上有些什麼書都瞭若指掌。告訴他我需要什麼，他就會把書找給你的。",objectives={"到暴風城堡的皇家圖書館去與密爾頓·西弗交談，他將會為你找到克里斯多夫修士所需要的關於冶金學的書。"}]])
R(344,"帕克斯頓修士",[[description="《金屬的延展性》？是的，我知道這本書。那是本非常好的書，是十幾年前一位矮人礦工馬戈爾夫·布拉貢寫的。他的一生似乎都奉獻給了卡茲莫丹的群山，整日在那裡挖礦。他是個很聰明的傢伙！$B$B但這書在哪來著？哦，對了，《金屬的延展性》！這本書被我送到北郡修道院去了。那裡的管理員帕克斯頓修士想為他那裡的圖書館抄寫一份留作副本。$B$B但這是幾個月前的事了，我不知道他為什麼會花這麼長的時間……",objectives={"與北郡修道院的帕克斯頓修士談話。"}]])
R(345,"墨水短缺",[[description="I've been meaning to finish my copy of The Stresses of Iron, but...$B$BWell you see, I make my own ink for books I copy.  It's my own recipe; it doesn't run or smear, and it dries very quickly  Unfortunately, it dries too quickly!  My last batch dried up before I could finish the copying job, and I haven't had the chance to make more ink!$B$BTo make more I need Rethban Iron Ore from the Redridge Mountains.  Foreman Oslow in Lakeshire is my usual supplier.",objectives={"Speak with Foreman Oslow in Lakeshire and ask him for Rethban Iron Ore."}]])
R(346,"克裏斯托弗的書",[[description="現在我已經把這本書抄完了，這裡是《金屬的延展性》的原本。感謝你的耐心，還有，如果你見到密爾頓的話，請替我向他道歉，我拖了那麼長時間真有些不好意思。",objectives={"回到教堂廣場，將《金屬的延展性》交給克里斯多夫修士。"}]])
R(347,"瑞斯班礦石",[[description="Rethban Ore is named after the man who first found it, Bart Rethban.  When smelted it's not as strong as iron, but its ore has a dark, flat color that some scribes use in their dyes.  It can be found in the Rethban Caverns, north of here.$B$BWe usually have some in stock, but we're too busy preparing for Orc attacks to gather any.  And besides...Redridge Gnolls are now living in the Rethban Caverns and their Drudgers are gathering the ore themselves.$B$BSo if you need some, you'll have to get it yourself.",objectives={"Gather 5 loads of Rethban Ore and bring it to Brother Paxton in the Northshire Library."}]])
R(348,"荊棘谷熱疫",[[description="我病了…病得……非常厲害……$b$b我…染上了…荊棘谷熱疫…致死的疾…疾病……$b$b……只…只有吃下…野人莫…莫…莫克…的心臟…才…才有救…那…是…一隻殘忍而…狡猾的…野獸。$b$b……巫醫安巴格瓦巫師…是…唯一會…召喚…它…的人……$b$b找到…住在南邊…靈魂…洞穴…裡的安巴格瓦……$b$b……快點…我就要死了…就要死了……",objectives={"找到巫醫安巴格瓦並要求他召喚出野人莫克，然後將野人莫克的心臟交給芬·菲茲拉克。"}]])
R(349,"荊棘谷熱疫",[[description="temp text 02 - description",objectives={"temp text 02 - log"}]])
R(350,"老朋友",[[description="That Marzon would be contacting a member of the Defias and have ties to Lescovar...$B$BHaving killed VanCleef and Thredd, it would be hard to see Lescovar brought to proper justice, as your evidence is nothing without their testimonies. That is not even considering the fact that Lescovar is a noble and well connected. It effectively makes him above the law.$B$BYou'll need other help. I loathe to do so, but there is someone I know that will aid us. You'll find Trias in the Trade District of the city.",objectives={"Speak to Elling Trias in Stormwind."}]])
R(351,"尋找OOX-17/TN！",[[description="你發現了一個奇怪的蛋形金屬物體。隨便撥弄了幾下之後，它居然打開了，變成了一個看起來像是由地精創造的那種機器裝置！一個劈哩啪啦的聲音從這個蛋形機器裝置中傳了出來。$B$B「我的名字叫奧格索普，我的母體機器人不見了！如果你能幫我找到它的話，我會獎勵你的！請把這個定向器帶到我的母體機器人那裡。我現在已經為你勘探出了它的所在地！它現在就在塔納利斯的大裂口那裡！」",objectives={"把定位器帶到奧格索普的母體機器人那裡。"}]])
R(352,"<UNUSED>",[[description="Great Mammoda. Enormous, she was, with claws and teeth like swords. Now, I was caught off my guard, but I don't think being ready would have helped my cause much. One swipe and poof! Darkness. They say I'm lucky to walk now...$b$bWell, not much enjoyment to be had in hearing that old story now, is there? Anyways, $n, if you'd like to try yourself against her, the Lady of the Loch,"]])
R(353,"雷矛的包裹",[[description="雷矛部族是一個倍受尊敬的矮人部族，他們向來以獨具慧眼著稱——所以遠在鐵爐堡的巡山人才會托人不遠千里地讓人傳信，委託我幫他們製造一把武器，哈哈！$B$B這把武器已經完成了，但是巡山人卡爾·雷矛住在洛克莫丹，離這裡實在是太遠了。如果你正好要到那邊去的話，就替我把這個包裹帶給他吧。$B$B巡山人卡爾·雷矛最後一次和我聯絡的時候，他說他在洛克莫丹北部的哨塔裡。",objectives={"把給卡爾·雷矛的包裹交給洛克莫丹北部哨塔里的巡山人卡爾·雷矛。"}]])
R(354,"阿加曼德家族",[[description="阿加曼德家族曾是提里斯法林地中最富有的家族。我過去曾在他們的磨坊裡工作……當然，我是說在瘟疫降臨之前。$B$B天譴軍團入侵的時候，阿加曼德家族的人們加固了他們的莊園，並說服了在他們家做工的人留下來幫助他們抵抗天譴軍團。我們實在是太蠢了，但我們至少是愚蠢而忠誠。$B$B而阿加曼德家族用榮耀之類的幌子讓我們去送死，結果現在他們倒成了天譴軍團的走狗！$B$B為了被遺忘者，你必須去剿滅墮落於瘟疫之中的阿加曼德家族！把他們的屍體帶回來給我。",objectives={"把格里高的遺骸、妮薩的殘骸和薩爾曼的遺骸交給布瑞爾的庫勒曼·法席恩。"}]])
R(355,"與塞弗倫交談",[[description="You have given me the remains of the Agamands, and satisfied my desire for revenge.  But the Agamand Mills hold a threat to all the Forsaken, not just to me.$B$BI have spoken to Magistrate Sevren of your exploits against the Agamands, and he wishes to speak with you.",objectives={"Speak with Magistrate Sevren in Brill."}]])
R(356,"巡查後方",[[description="亡靈壁壘上的衛兵們時刻都在提防著從瘟疫之地潛入提里斯法的敵人，但仍有些天譴軍團的士兵能躲過這樣的警戒線。$B$B如果想要成功地維持我們對這一帶的控制，就必須進行一次清查行動——我們絕對不能腹背受敵。如果補給線被切斷了的話，那後果就將是災難性的。$B$B去協助亡靈壁壘的衛兵進行防禦吧。往東邊一路巡邏過去，如果你發現任何天譴軍團的爪牙，就直截了當地把他們幹掉。特別注意一下東邊的巴尼爾農場，那裡已經到處都是天譴軍團的散兵了。",objectives={"殺死8個可怕的血殭屍和8個遊蕩的幽靈，然後向亡靈衛兵林奈彙報。"}]])
R(357,"巫妖的身份",[[description="北邊澈水湖中的一個小島上住著一個巫妖。雖然他是個獨立的亡靈，不過他認為其他所有的亡靈都是天譴軍團的奴隸，他的爪牙會襲擊任何靠近他的人。$B$B他是個無主之人，所以黑暗女王想要招降他。如果他確實精通於巫術的話，那麼他的知識會對我們很有幫助。$B$B不過我得先看過他的法術書才能瞭解他的身份和學問。潛入他的營地，把書拿回來見我。",objectives={"把巫妖的法術書帶給幽暗城的比索·埃斯沙德。"}]])
R(358,"盜墓賊",[[description="北邊的加倫鬼屋你去過嗎？那個地區的西南角是一大片亂葬崗，裡面葬著提里斯法一帶的大量因瘟疫而死的人。$B$B那邊墳墓裡的屍體大多沒能變亡靈，但最近天譴軍團派出了一群腐皮豺狼人到那裡去收集屍體，以此來壯大他們的軍隊。我們不能允許這樣的事情發生！$B$B你的任務有兩個：殺光躲在亂葬崗和加倫鬼屋裡的腐皮豺狼人，並把他們身上的防腐劑搶回來，正是這種防腐劑使他們活過來的。",objectives={"殺死腐皮盜墓賊和混血腐皮豺狼人。$B$B給布瑞爾的執政官塞弗倫帶回8瓶防腐劑。"}]])
R(359,"亡靈衛兵的職責",[[description="I need a fresh report from our Deathguard waystation to the east.$B$BI must know if more Scourge forces have slipped past The Bulwark and into Tirisfal.  Our vigilance on the border to the Plaguelands must be maintained - we can't let the Scourge get a stronger foothold here!$B$BTravel south along the road, then east at the fork to the waystation.  Speak with Deathguard Linnea.  She has the information I need.",objectives={"Speak with Deathguard Linnea."}]])
R(360,"向塞弗倫回報",[[description="現在帶著這些情報回到執政官塞弗倫那裡去吧。他急需這幾份報告，你動作最好快點。$B$B如果你回程的路上看見了任何天譴軍團的成員，就順便幹掉他們，我們可不能讓這些垃圾在我們的地盤上胡作非為。",objectives={"向布瑞爾的執政官塞弗倫報告。"}]])
R(361,"未寄出的信件",[[description="這封信的作者是格里高·阿加曼德的長子薩爾曼。收件人則是一位名為伊維特·法席恩的女士，儘管現在看來這封信顯然是沒寄到她手上……",objectives={"找到伊維特·法席恩，將薩爾曼·阿加曼德的信交給她。"}]])
R(362,"鬧鬼的磨坊",[[description="代弗林·阿加曼德是阿加曼德家的兩個男孩中最小的一個，但這兩個男孩子卻完全不像是兄弟。薩爾曼身材高大而且待人彬彬有禮，而他的弟弟代弗林卻身體虛弱，而且嘴巴很刻薄惡毒。$B$B當阿加曼德磨坊遭遇瘟疫的時候，他是第一個被感染的。現在，只要你靠近通向阿加曼德磨坊的道路，就仍能聽見他那喋喋不休的囈語。$B$B我正在收集阿加曼德家族所有人的遺骸，首先，我想弄到可憐的代弗林的屍骨。找到並摧毀他，然後把他的遺骨帶回來給我。",objectives={"殺死代弗林·阿加曼德，然後將代弗林的遺骸交給布瑞爾的庫勒曼·法席恩。"}]])
R(363,"突然醒來",[[description="你醒得可真是時候。我們本來還準備把你和其他的死人一起火葬了，沒想到你居然醒來了。$b$b我是摩爾多，喪鐘鎮墓穴的看護人。現在你已不再是巫妖王的奴隸了。$b$b暗影牧師薩維斯就在山腳下的教堂裡，去和他談談吧，他會告訴你更多你必須瞭解的事情。",objectives={"和暗影牧師薩維斯談話。"}]])
R(364,"無腦的僵屍",[[description="我們被遺忘者正在與巫妖王的天譴軍團作戰，那支軍隊包括用亡靈法術喚起的亡靈軍隊，大陸北方的那些愚蠢的野獸，還有那些永遠遭受折磨的鬼魂。$b$b在這個村莊的北部有大量的無腦殭屍到處橫行，我們必須消滅他們。消滅他們，即使他們以前可能是我們的兄弟姐妹也不要手軟，那些行屍走肉如今只不過是巫妖王的奴隸罷了。",objectives={"暗影牧師薩維斯讓你殺掉8個無腦的殭屍和8個醜陋的殭屍。"}]])
R(365,"悲傷之地",[[description="看看誰來了？你看起來是個菜鳥$c吧。如果你想向黑暗女王陛下證明自己的實力，就得先學會我們被遺忘者行事的幾條基本原則。$b$b這裡的西邊有個農場，人類寄生其上有如腐屍身上的黴菌。更糟糕的是，血色十字軍會從他們的哨塔到附近巡邏。給這些渣滓們好好地上一課吧，把他們的寶貝南瓜給我偷10顆來。$b$b偷到10顆南瓜以後，就把它們交給布瑞爾的藥劑師喬漢。",objectives={"從位於布瑞爾西邊、喪鐘鎮北邊的農場中偷10顆南瓜來，把它們交給布瑞爾的藥劑師喬漢。"}]])
R(366,"歸還書籍",[[description="很久以前，岡瑟爾和我，還有現在隸屬於天譴軍團的圖勒·鴉爪，我們三人是很好的朋友，我們曾一起在肯瑞托學習魔法。$B$B岡瑟爾和我都是大瘟疫的犧牲品，岡瑟爾後來成為了巫妖王的手下。現在我得知他脫離了巫妖王的魔爪，這真是個好消息。$B$B我們一定要找到他。我給他的書上施放了一個魔咒，當他看到這本書的時候就會知道我也已經擺脫了巫妖王的控制，希望他在知道這一點以後會加入我們。",objectives={"到岡瑟爾居住的小島去歸還他的法術書。"}]])
R(367,"新的瘟疫",[[description="希瓦娜斯大人最近交給了我們皇家藥劑師學會一項很有挑戰性的命令。黑暗女王相信我們的知識與新發明的魔法將會是她擊敗阿薩斯的有力武器，她要求我們研製出一種新的瘟疫，這種瘟疫要比以前出現在艾澤拉斯大陸上的任何一種疾病都要更加猛烈，它會把阿薩斯和他的天譴軍團徹底毀滅。$b$b我的研究結果表明，野獸的血液也許是一種重要的藥引。給我帶回五瓶黑暗犬的血液來，我要驗證一下自己的理論。",objectives={"布瑞爾鎮裡的藥劑師喬漢要求你收集5瓶黑暗犬的血液。"}]])
R(368,"新的瘟疫",[[description="While you were collecting samples for me, my experiments led me to realize that more reagents will be required for this new disease to spread properly. Poisoning some hapless victim is child's play. Plaguing an entire world proves to be a bit more complicated.$b$bI will need 5 Vile Fin Scales from Murlocs in the vicinity.  You will find the creatures along the coast to the north or to the west.",objectives={"Apothecary Johaan of the town of Brill needs 5 Vile Fin Scales from Murlocs in Tirisfal Glades."}]])
R(369,"新的瘟疫",[[description="在你出去收集鱗片的時候，我已經在我的藏書中找到了一些古老而有趣的文章。這些文章裡面提到，以前曾有一種古代的瘟疫殺死過成百上千的人，而後來又有人發現在夜行蜘蛛的毒液中就能提取到這種瘟疫的致病物質。$b$b給我帶些夜行蜘蛛的毒液來，讓我完成這個實驗。我想知道毒液中的感染性元素是否能和我最新研製出來的瘟疫病原體共存。據說這種蜘蛛一般在提里斯法林地的東部出沒。",objectives={"布瑞爾鎮裡的藥劑師喬漢要你去收集4份邪惡的夜行蜘蛛的毒液樣本。"}]])
R(370,"與血色十字軍的戰爭",[[description="The strategic documents from Executor Arren contain all the details we need to wipe the human infestation from the lands.  According to the information, The Scarlet Crusade has assigned Captain Perrine and a brigade to the ruined tower southwest of Brill.$b$bKill Perrine along with 3 Zealots and 3 Missionaries and report back to me.",objectives={"Executor Zygand in Brill wants you to kill Captain Perrine, 3 Scarlet Zealots and 3 Scarlet Missionaries."}]])
R(371,"與血色十字軍的戰爭",[[description="我們仍然處於戰爭狀態中，而且血色十字軍正在逐漸壯大。執行官阿倫給我的報告中提到，在瓦松隊長的指揮下，血色十字軍正以提里斯法東南部巴尼爾農場附近的那座廢塔為據點肆意劫掠。$b$b去殺掉瓦松和5名血色十字軍苦行修士，這對十字軍來說將是一次沉重的打擊！",objectives={"布瑞爾的執行官塞加德要求你殺掉瓦松隊長和5名血色苦行修士。"}]])
R(372,"與血色十字軍的戰爭",[[description="血色十字軍已經從提里斯法林地北部的廢塔出發，穿過了法奧之墓。根據目前我們所掌握的情報，一個名叫麥拉其的軍官指揮著這支邪惡的部隊，他是個非常殘忍的傢伙。$b$b我相信你能完成這個非常重要而又危險的任務。以黑暗女王陛下的名義，殺死麥拉其和他的兩名保鏢！",objectives={"布瑞爾的執行官塞加德要求你刺殺麥拉其隊長及他的兩名保鏢。"}]])
R(373,"未寄出的信",[[description="搜查艾德溫·范克里夫的屍體時，你從一堆雜亂的物品中找到了一封還未來得及發出的信。地址一欄上寫著巴洛斯·艾力克斯頓，暴風城石工協會，城市大廳，教堂廣場。$B$B這顯然是最近剛剛寫好並封上的。",objectives={"將艾德溫·范克里夫的信交給巴洛斯·艾力克斯頓。"}]])
R(374,"死亡證明",[[description="Executor Zygand tells me you've been out killing Scarlet Crusaders. Tirisfal Glades is crawling with them.$b$bVarimathras, lieutenant to The Dark Lady, is seeing to it personally that the scum of Azeroth, the Human race, gets wiped into oblivion. Here in Tirisfal Glades we face a particularly annoying breed of humans: The Scarlet Crusade.$b$bVenture forth and wage an offensive on the Scarlet Crusade, $c. Bring me back 10 Scarlet Insignia Rings as proof of your loyalty to Varimathras and The Dark Lady.",objectives={"Bring 10 Scarlet Insignia Rings to Deathguard Burgess in Brill."}]])
R(375,"死亡之寒",[[description="It's so cold, now.  The Plague of Undeath crawls through my veins like an icy serpent.  The Mindless State will be upon me soon.  But no doomed destiny will prevent me from serving our Dark Lady.  When the call arose I sewed body bags for the fallen soldiers of Sylvanas's mighty army.$b$bNow my hands shake from the chill.  If you would bring me five Duskbat Pelts and some Coarse Thread I could sew myself a blanket.  Help me, $N, so that I can continue to serve the cause.",objectives={"Bring five Duskbat Pelts and some Coarse Thread to Gretchen Dedmar in Brill."}]])
R(376,"被詛咒者",[[description="我的任務包括照料受傷的士兵，縫製鎧甲和衣服，還有為暗影牧師薩維斯提供任何他可能需要的支援。$b$b看起來，你也即將加入到為他效力的隊伍中……我猜是要獵殺那些沒腦子的傢伙。好吧，如果你還想留著你的小命的話——我想你一定是的——也許我能幫助你。我這裡沒有足夠的狼爪子和蝙蝠翅膀了，如果你能幫我弄一些來的話，我會幫你找幾件鎧甲。在這裡的西北方可以找到大群的狼和蝙蝠。",objectives={"新兵艾爾雷斯需要6隻食腐狼的爪子和6隻夜行蝙蝠翼。"}]])
R(377,"罪與罰",[[description="貴族議會好像嫌他們對暮色森林的漠不關心還不夠過分，現在他們居然無視夜色鎮議會的存在，決定把迪克斯特·瓦德囚禁在暴風城，而不是按照埃伯洛克公爵大人的判決將這個惡棍斬首！$b$b迪克斯特·瓦德是在把墓地裡的屍體賣給摩本特·費爾時被抓住的，這理應是死罪。可是暴風城卻認為他們才擁有對他的處決權！$b$b去暴風城的監獄把瓦德殺掉，把他的手給我帶回來作為證明，我會獎賞你的。",objectives={"夜色鎮的米爾斯迪普議員要你殺死迪克斯特·瓦德，並把他的手帶回來作為證明。"}]])
R(378,"卡姆·深怒",[[description="You have proven your loyalty to King Magni, $c.  And your hatred for the Dark Iron scum is as great as my own.$b$bThere is a task I wish to complete myself but I am bound by honor to stay with Longbraid.  But Roggo has gathered intelligence that proves Kam Deepfury was a conspirator in the attack on the Thandol Span.  It was by Deepfury's planning that Longbraid lost his kin.$b$bDeepfury is being held for political reasons in the Stormwind Stockade.  I want him dead, $N.  For Longbraid!  Bring me his head!",objectives={"Motley Garmason wants Kam Deepfury's head brought to him at Dun Modr."}]])
R(379,"口渴的比格維茲",[[description="You want a power source.  I can help you with that.  Know what I want?  I want something to drink!  Bring me five Wastewander Water Pouches, and I'll give you the 4711-FTZ.$B$BNow... guess where you can find Wastewander Water Pouches!  Why don't you walk up to one of the Wastewander nomads to the east of here and ask them for one.  Let me know how that works out for you.",objectives={"Bring 5 Wastewander Water Pouches to Chief Engineer Bilgewhizzle in Gadgetzan."}]])
R(380,"夜行蜘蛛洞穴",[[description="我們的一項最重要的任務就是獲取賴以生存的自然資源。即使在當年聯盟最鼎盛的時候，黃金資源也是非常缺乏的。$b$b這裡的西北面有一處金礦，我們需要礦坑裡的資源，但是那裡蜘蛛橫行，我們根本無法進去採掘金礦。我手上沒有人可以去完成這項任務，所以我們只有一步一步慢慢地來。去那裡看看吧，也許你能做些什麼……",objectives={"執行官阿倫要你去殺掉10隻小夜行蜘蛛和8隻夜行蜘蛛。"}]])
R(381,"血色十字軍",[[description="得知我們在金礦的進展非常順利，你一定很開心吧？得益於你的幫助，我們終於可以把注意力放到別的事情上了。$b$b我的斥候報告說，一支血色十字軍的小分隊在東南方建立了營地。血色十字軍是一個卑鄙的組織，他們視我們為死敵，只要有一個亡靈——無論是巫妖王的爪牙還是我們被遺忘者——還活著，他們就不會停止追殺我們的行動。所以我們必須先發制人！$b$b你要多加小心，這些邪惡而狂妄的十字軍是一群非常危險的傢伙。",objectives={"從血色信徒和血色新兵身上收集12枚血色十字軍臂章，把它們交給執行官阿倫。"}]])
R(382,"十字軍信使",[[description="布瑞爾那邊的上級發來給我的檔案顯示，有一個從血色修道院出發的血色十字軍斥候已經潛入了喪鐘鎮。有報告說這個人攜帶著非常重要的情報。至於更多的細節，我不得而知。但不管怎麼樣，我們必須得到這份情報！$b$b你是我眼前能配合調動的最適人選，$n。找到那個信差，帶回你能取得的任何情報。",objectives={"到十字軍營地去殺掉信差邁文·考加爾，將你發現的情報交給執行官阿倫。"}]])
R(383,"重要情報",[[description="我必須將這些東西交給我的上級——執行官塞加德，他就在布瑞爾。有了這份詳盡的情報，我們就能給血色十字軍以沉重的打擊。你在喪鐘鎮對我們做出了很大的貢獻，現在我要你去把這份情報及時交給塞加德，我想他能幫你找到更多能讓你大展身手的工作。$b$b沿著這條路向北走出喪鐘鎮，在進入提里斯法林地以後，你很快就會來到一個十字路口，這時向東走，然後一直向前就可以到布瑞爾了，路上有一座爐灰莊園可以幫你確認自己的方向。",objectives={"把血色十字軍檔案交給布瑞爾的執行官塞加德。"}]])
R(384,"啤酒烤豬排",[[description="啤酒烤豬排是我的老主顧們最喜歡的大餐！問題是，為我提供豬排的獵手被國王徵募去打仗了。$b$b也許你能幫幫我？如果你可以給我弄六塊峭壁野豬肋排，外加一杯酒店裡賣的狂想麥酒的話，我就把祖傳的啤酒烤豬排的烹飪方法教給你，而且我還可以讓你免費品嘗我做出來的美食！秘密就在麥酒裡！",objectives={"卡拉諾斯的拉格納·雷酒需要6塊峭壁野豬肋排和1杯狂想麥酒。"}]])
R(385,"捕獵鱷魚",[[description="Many a hunter is attracted to Loch Modan to hunt our famous crocs. There are always merchants who seek out crocolisk skins for clothing items or armor, and there are also some who enjoy the taste of their meat.$b$bWe do some trade in this, but not a huge amount, as the crocolisks are ferocious and have entrenched themselves on the islands in the Loch. But don't let me dissuade you, it's quite an experience, wrestling with the jaws of the beasts.$b$bWhy, this one time...",objectives={"Get 5 pieces of Crocolisk Meat and 6 Crocolisk Skins for Marek Ironheart at the Farstrider Lodge."}]])
R(386,"伸張正義",[[description="可怕的塔高爾是加塞爾佐格手下的一個高級殺手。他殺人的手法十分殘忍，即使以獸人的標準來看也是殘暴無比。那些為了保衛國家而奮勇作戰的戰士們落在他手裡都會被他折磨致死。這個惡棍現在被關在暴風城的監獄裡，被判處了死刑。不過，這件事情好像出了點小差錯。一個官僚習氣十足的貴族延遲了處死他的日期。我敢打賭這裡面一定有鬼。$b$b處死塔高爾吧，$N。到暴風城的監獄裡去，在他玩出什麼把戲之前把他幹掉。",objectives={"把塔高爾的頭顱帶給湖畔鎮的衛兵伯爾頓。"}]])
R(387,"鎮壓暴動",[[description="我們必須把暴動給鎮壓下去！我需要你的幫助。如果外面的人知道監獄裡面已經失去了控制，我一定會丟了飯碗的！這是我所見過最無聊的鬧劇了。現在最重要的是逼迫這些囚犯投降，這樣才能保證暴風城的安全。$b$b叛亂的代價就是死亡。去殺掉一些囚犯，這樣叛亂才能得到控制！",objectives={"暴風城的典獄官塞爾沃特要求你殺死監獄中的10名迪菲亞囚犯、8名迪菲亞罪犯和8名迪菲亞叛軍。"}]])
R(388,"鮮血的顏色",[[description="痛苦如同冰冷的河水一樣從我的血管中流過。我的孫子麥克是個多好的孩子呀，他只有14歲。當暴風城的軍隊被派往前線的時候，麥克也拿起了武器去守衛城市。他是監獄的守衛，那座監獄裡關押著許多迪菲亞兄弟會的成員。有一些囚犯們把他們的羊毛毯改織成他們組織的頭巾，麥克把這件事情上報了，結果他遭到了報復，被人從後面刺了一刀。$b$b我要報仇。給我帶回10條迪菲亞盜賊們的羊毛面罩，像鮮血一樣殷紅的那種。",objectives={"暴風城的尼科瓦·拉斯克要你取得10條紅色毛紡面罩。"}]])
R(389,"巴吉爾·特雷德",[[description="VanCleef and I were members of the Stonemasons Guild. Our main project was to rebuild Stormwind after the War.$B$BWhen we had finished our duties, we were cheated. The nobles refused to pay us for our work. Some of the more senior of the Stonemasons were offered governmental jobs, but VanCleef refused it out of loyalty to all the Stonemasons. He led a riot and left the city, swearing revenge.$b$bHis lieutenant, Bazil Thredd, might know more about VanCleef's plans. He's being held prisoner in the Stockade.",objectives={"Speak with Warden Thelwater in the Stockade."}]])
R(390,"<UNUSED>")
R(391,"監獄暴動",[[description="讓我們把話挑明瞭說吧，$n：我不信任你。但是，現在的情況緊急，我也管不了那麼多了。$b$b你到下面去幹掉那個該死的斯瑞德，把他的腦袋砍下來帶給我。$b$b還有，如果你膽敢跟他合計什麼把戲，或者你不上來了的話……只要被我抓到你，就準備跟那群蛆死在一塊吧。",objectives={"殺死巴基爾·斯瑞德，把他的頭帶給監獄的典獄官塞爾沃特。"}]])
R(392,"好奇的訪客",[[description="During the first years of Thredd's imprisonment, he never had any visitors. I figured that he was no longer of use to the Brotherhood, so they abandoned him.$B$BAnyway, a few months ago, that all changed; he started to get regular visits... once, maybe twice a week. It was a strange man--the quiet type. I had my suspicions, but all his papers checked out.$B$BHis documents claimed his name was Maelik; here's his description. I don't think he'll be coming to visit Thredd anymore.",objectives={"Bring the Sealed Description of Thredd's Visitor to Baros Alexston in Stormwind."}]])
R(393,"往日的陰影",[[description="I really haven't a clue, $N. There is someone else who might be able to help you, and it so happens that he owes me a favor for--well, let's not get into that. Master Mathias Shaw of SI:7 can be found in the barracks in Old Town. Shaw has his thumb on most of the shady, or underhanded dealings of the city.$B$BIf anyone knows, it'd be him.",objectives={"Bring the Sealed Description of Thredd's Visitor to Master Mathias Shaw in Stormwind."}]])
R(394,"禽獸的首級",[[description="Find Shaw in Old Town. Let him know that the Lescovar threat has been dealt with and about your involvement in the Lord's plots against the city. I'm sure he'll be proud to have another hero among Stormwind's citizens.$B$BHe'll more than likely send you off to meet with the Prince or some other noble. Don't let it get to your head, $N. The nobles can think they rule the city all they want, but some things remain out of their hands.",objectives={"Speak to Mathias Shaw in Stormwind."}]])
R(395,"兄弟會的滅亡",[[description="Ah, I almost forgot. Alexston came while you were away, he wished to speak with you. No doubt he wishes to report the goings-on of the Defias Brotherhood to the nobles.$B$BA bit of advice, $N: if anyone should ask, I would provide all details but that it was your hand that slew Lescovar. Trust me. I am... acquainted... with the ways of such things.$B$BAnd as far as Trias goes, well, speak to no one of him... ever... if you can help it.",objectives={"Speak with Baros Alexston in Stormwind."}]])
R(396,"覲見國王",[[description="I have prepared a report for the King. I believe you should be the one to deliver it to him, along with an account of your findings. Do not worry, there is no doubt that he will commend you for doing your duty to the people of Stormwind.$B$BYour audience is scheduled soon, so you'd best hurry, it's a bit of a ways to Stormwind Keep.",objectives={"Deliver Baros Alexston's report on the Defias Brotherhood to King Varian Wrynn in Stormwind Keep."}]])
R(397,"幹得好",[[description="I hear Lord Wishock enjoyed his beverage.  $b$bYou have served us well, $N.  The Warlocks of Stormwind will be able to practice our ways without disturbance, thanks to you.  For your efforts, I have prepared a special gift for you.  Speak with my servant, Zggi, and claim your reward.",objectives={"Speak with Zggi, the servant of Zardeth the Blackclaw, to claim your reward."}]])
R(398,"懸賞：蛆眼",[[description="懸賞：蛆眼！$b$b這只名叫蛆眼的豺狼人臭名昭著，即使是在它的同類眼中都顯得非常邪惡而污穢，它因為對被遺忘者們犯下了不可饒恕的罪名而被判處了死刑，這只卑鄙的野獸為巫妖王的軍隊偷盜了無數的屍體。上次有人看到蛆眼作惡是在布瑞爾北邊的加倫鬼屋。$b$b布瑞爾鎮將為執行這項判決的勇敢者提供一份高額的獎金。完成任務之後，請將這只野獸的爪子交給執行官塞加德。$b$b只有弱者才會有憐憫之心。",objectives={"殺死蛆眼，並將他的爪子交給布瑞爾的執行官塞加德以換取酬勞。"}]])
R(399,"童年的記憶",[[description="許多年前，我是個在西部荒野的農場裡工作的小男孩，不過現在看來，這會是個永恆的回憶。俗話說時光一去永不回，這句話果然沒錯，在我身上更是獲得了雙重的印証，我家的房子已經被燒毀，又給一群盜賊給佔據了。$b$b我曾向父親詢問過我的一些物品的下落——包括我的第一個指南針，他說他沒辦法把那些東西拿回來。但是他又說它們應該還藏在農場的什麼地方。$b$b你可以在哨兵嶺的西邊找到艾力克斯頓農場。也許你能去幫我把那些東西找回來？",objectives={"到巴洛斯·艾力克斯頓在西部荒野的房子裡找尋他的指南針，並帶回暴風城教堂區給他。"}]])
R(400,"貝爾丁的工具",[[description="貝爾丁·鋼架在本地擁有一間機械店，他也是本地最好的攻城坦克機械師！不過他從來不愛護他的工具。他弄壞扳手的速度遠遠大於我們的供貨速度！$B$B我們剛剛才趕出他最近訂的一批貨。如果你能把這些東西交給他，我想他一定會讓你感到不虛此行的。$B$B他開的鋼架補給站就在卡拉諾斯的東北邊。老牌的攻城坦克駕駛員們經常在那裡碰頭，所以你到了那裡之後要睜大眼睛，說不定能找到一些好機會。",objectives={"把貝爾丁的工具交給貝爾丁·鋼架。"}]])
R(401,"等待希拉完工",[[description="I'm almost finished translating that note.  If you come back in a few moments I should be done.",objectives={"Wait a moment, then speak with Sirra Von'Indi again."}]])
R(403,"戒備森嚴")
R(404,"腐爛的爪子",[[description="有一小撮天譴軍團的士兵已經滲入了提里斯法林地，在布瑞爾以西一帶的舊橋附近活動。$B$B到那邊去增援我們的部隊，擊退所有你見到的腐爛的死者和破碎的屍體。拆散他們的骨頭，然後把他們那腐爛的爪子給我帶回來，亡靈衛兵會獎勵你的。",objectives={"給布瑞爾的亡靈衛兵迪林格爾帶回7隻腐爛的爪子。"}]])
R(405,"流浪的巫妖",[[description="Bethor Iceshard, a high-ranking and powerful mage in the Undercity to the south, commands me to send him an agent with proven worth against the Scourge.  You, $N, will be that agent.$B$BPresent these orders to Bethor.  He will then instruct you on your mission.  I don't know its details, but it deals with recruiting a wayward Lich.  And it will be dangerous.$B$BSo ready yourself, $C.  You must not fail.$B$BYou may find Bethor in the Magic Quarter of the Undercity.",objectives={"Present Sevren's Orders to Bethor Iceshard in the Undercity."}]])
R(406,"<UNUSED>")
R(407,"悲傷之地",[[description="這南瓜看起來沒什麼異樣吧？至少光看外表是無害的。如果我們想要阻止北邊來的阿薩斯軍隊，外加阻擋南方橫行的人類勢力，那麼我們必須從現在開始就意識到自己身為亡靈的優勢。$b$b只要稍微耍點小把戲，一個簡單的南瓜就能讓任何人成為黑暗女王的優秀探子。我最新培育的這種南瓜就可以做到這一點。$b$b據說現在又有個血色十字軍被俘虜了，他被關在恐懼之末旅店的某房間裡。把這個南瓜拿去給那個蠢蛋。",objectives={"將斑紋南瓜帶給被關在恐懼之末旅店地下室中的血色十字軍俘虜。"}]])
R(408,"家族墓穴",[[description="如今阿加曼德磨坊已經成了天譴軍團的一處重要據點，其中防守最為堅固的地方就是阿加曼德的家族墓穴了。天譴軍團的一個兵團就駐守在那裡，他們由一個名叫達高爾隊長的骷髏領導著。他們還利用某種通靈術復活了阿加曼德家族的死者們，並打算利用它們來對付我們。$B$B我們絕對不能允許這種事情發生，你必須阻止它。到阿加曼德家族墓穴去，戰勝那些還魂的阿加曼德家族的死屍們。$B$B還有，把達高爾隊長的顱骨也給我帶回來。",objectives={"殺死8個哀嚎的鬼魂和8個腐爛的古屍。$B$B消滅達高爾隊長，並將他的顱骨交給布瑞爾的執政官塞弗倫。"}]])
R(409,"證明忠誠",[[description="你說你沒有被巫妖王控制住自己的思想，這一點已經由比索在我書上灌入的魔法證實了。但是，你仍然得先證明自己是天譴軍團的敵人，這樣我才會徹底相信你。$B$B在這座島嶼的南方海邊有一個古老而血腥的祭壇，由一個強大的天譴軍團斥候莉莉絲·奈法拉所佔據著。$B$B從我身邊的箱子裡拿出一根誘靈蠟燭，在祭壇上點燃蠟燭，莉莉絲就會醒來。消滅莉莉絲，我就相信你確實是巫妖王的敵人。",objectives={"取得一根誘靈蠟燭。$B$B召喚出莉莉絲·奈法拉並殺死她。$B$B然後回去島上找岡瑟爾。"}]])
R(410,"潛伏的陰影")
R(411,"巫妖歸順",[[description="拜託你，請將這塊虛空寶石帶給我的老朋友比索。這樣我就能和他交流了……我有好多事想和他說呢。",objectives={"將虛空寶石交給幽暗城的比索·埃斯沙德。"}]])
R(412,"自動凈化裝置",[[description="透過對諾姆瑞根現狀的進一步分析，我們發現不但那些該死的穴居人沒有被消滅，反而有更多的地精變成了喪心病狂的、邪惡的怪物。$b$b我和奧齊希望用我們的最新發明——自動淨化裝置——來扭轉這種局面。這台機器即將大功告成，不過我們急需一些多檔齒輪和自適應齒輪才能搞定最後的部分，請從諾姆瑞根的麻瘋地精那裡弄些過來吧。",objectives={"收集8個多檔齒輪和8個自適應齒輪，把它們交給卡拉諾斯的拉茲·滑鏈。"}]])
R(413,"微光酒",[[description="I'd like my brother Wellart to try my new Shimmer Stout.  He's a Mountaineer stationed in the southern guard tower, one of two towers on the border to Loch Modan.$B$BHe may not be a brewer like the rest of us Barleybrews, but he loves his drinks and I know he'll like this one.$B$BCan you bring him this Barrel of Shimmer Stout for me?",objectives={"Take the Barrel of Shimmer Stout to Mountaineer Barleybrew."}]])
R(414,"卡德雷爾的酒",[[description="I've been drinking more of that Shimmer Stout my brother made - it's great stuff!  I want a fellow Mountaineer to try it.  His name's Kadrell, and he's usually patrolling the road through Thelsamar in Loch Modan.$B$BTo get to Thelsamar, go southeast through the tunnel, then turn northeast when the path forks into a road.  Follow that road straight into Thelsamar.$B$BGive Mountaineer Kadrell this cask of Shimmer Stout and see what he thinks!",objectives={"Take the Cask of Shimmer Stout to Mountaineer Kadrell."}]])
R(415,"雷傑德的新酒",[[description="Rejold Barleybrew at Brewnall Village has been asking for you.$B$BHe wants to talk to you about a new drink he's been brewing...said something about you helping him with it.  You might want to head back to Brewnall Village and see what he has to say.$B$BThere could be some free booze in it for you...",objectives={"Speak with Rejold Barleybrew."}]])
R(416,"狗頭人的耳朵",[[description="我們在西邊遇到了點麻煩。坑道鼠狗頭人在那裡的丘陵地帶建起了巢穴，把我們的地盤弄得烏煙瘴氣！$B$B我們必須把他們給消滅掉。去捕殺那些坑道鼠狗頭人，把他們的耳朵拿回來給我，我就給你賞金。$B$B坑道鼠狗頭人的巢穴就在塞爾薩瑪北邊的山腳下。",objectives={"收集12隻坑道鼠的耳朵，把它們帶給塞爾薩瑪的巡山人卡德雷爾。"}]])
R(417,"駕駛員的復仇",[[description="莫里·鐵鑽在他的日記中寫著，他遭到一頭名叫癩爪的巨型冰爪熊的攻擊。他趕走了這隻野獸，不過自己也已身受重傷。$B$B從莫里屍體上的傷痕判斷，癩爪一定在之後又回來殺死了他。$B$B無論如何，莫里在他的日記中寫下了他最後的遺願：$B$B殺死癩爪，為我復仇。",objectives={"殺死癩爪。$B$B把牠的骯髒的爪子和莫里·鐵鑽的日記交給駕駛員塞克·錘足。"}]])
R(418,"塞爾薩瑪血腸",[[description="塞爾薩瑪這兒饑腸轆轆的人可真不少，有跑進跑出的孩子，也有在挖掘場忙了一整天的工人。我們這兒有一道出名的菜色——血腸，你大概還沒嘗過吧？$b$b沒有？在這兒要吃飯就得幹活，別以為你是個出色的$c就可以例外。$b$b我需要熊肉、做腸衣用的豬大腸，還有做調料用的蜘蛛的毒液。把這些東西找來，剩下的就交給我維德拉好了！",objectives={"收集3塊熊肉、3根豬大腸和3份蜘蛛的毒液，把它們交給塞爾薩瑪的維德拉·壁爐。"}]])
R(419,"失蹤的駕駛員",[[description="我的朋友，同時也是同一蒸汽坦克車組的同事——莫里·鐵鑽，在山上失蹤了。我們當時正在尋找一種可以用來製作高爆炸藥的稀有礦石。在我們搜尋的過程中，莫里駕駛著他的坦克攀上一處陡峭的山坡後拋錨了！$B$B他確信礦石就在這片山地裡，所以就讓我守著我們的機車，而他一個人步行繼續去搜索。$B$B莫里已經有好些天沒回來了，夜裡我時常能聽見山中的野獸發出的咆哮。莫里是個硬漢，不過我還是有點為他擔心。$B$B求求你，$N，幫我找到他。",objectives={"找到駕駛員莫里·鐵鑽。"}]])
R(420,"森內爾的觀察站",[[description="隧道裡的穴居人非常具有攻擊性，它們會毫不猶豫地對隧道中的過客發動襲擊。不過你看起來挺結實的，應該不會有什麼危險。$b$b方向？如果你要找森內爾，就到卡拉諾斯去吧。$b$b一直穿過隧道，出去之後沿著大路向前走，沒幾步就到卡拉諾斯了。",objectives={"把格瑞林的報告交給卡拉諾斯的森內爾·白鬚。"}]])
R(421,"證明妳的價值",[[description="Lady Sylvanas has charged Varimathras with the conquering of the human and dwarven lands to the south.$b$bBut that fool, Arugal -- charlatan of Dalaran and now cursed beast of Shadowfang Keep -- let his reckless magic wreak havoc with the strategic stronghold of Silverpine Forest.$b$bI need someone skilled in the ways of combat to help clean up Arugal's mess.  Prove yourself to me by killing 5 Moonrage Whitescalps.  The wretched beasts can often be found just off the road, down the hill below.",objectives={"Dalar Dawnweaver at the Sepulcher wants you to kill 5 Moonrage Whitescalps."}]])
R(422,"阿魯高的愚行",[[description="How Arugal gained acceptance within the Kirin Tor is beyond me.  His spell-casting knowledge seemed as transparent as a blown glass bauble.$b$bWhat's important now is learning exactly what magic Arugal used so that I can turn it against him and secure Silverpine Forest for the Dark Lady.$b$bArugal first stayed at the wheat farm just north of the bridge.  One of the Deathstalkers reported seeing some spellbooks but could not secure them.  Retrieve for me the spell labeled Remedy of Arugal from those books.",objectives={"Retrieve the Remedy of Arugal for Dalar Dawnweaver at the Sepulcher."}]])
R(423,"阿魯高的愚行",[[description="After examining Arugal's work my worst suspicions were confirmed.  The old hack was not qualified to clean chamber pots in Dalaran let alone represent the Kirin Tor in its most dire hour.  Fools!$b$bArugal used enchanted items to reinforce his weak magic.  I need to examine these items first hand.  Travel forth and slay Moonrage Gluttons and Moonrage Darksouls until you have collected enough of their enchanted shackles for my research.  The foul creatures have been seen to the north and east.",objectives={"Bring 6 Glutton Shackles and 3 Darksoul Shackles to Dalar Dawnweaver at the Sepulcher."}]])
R(424,"阿魯高的愚行",[[description="It will indeed take me longer than I had thought to uncover the dark secrets behind the enchantments Arugal was using.$b$bBut in the meantime I need you to take care of a slight problem our Darkstalkers have discovered.  It seems that Arugal let his magic spread to the Deep Elem Mine in the hills to the southeast.$b$bThe mine would prove to be quite a resource for Varimathras's advance.$b$bI want you to behead the tainted foreman of the mine, Grimson the Pale.  With his death, the mine shall be ours.",objectives={"Kill Grimson the Pale and bring his head to Dalar Dawnweaver at the Sepulcher."}]])
R(425,"邪惡的伊瓦",[[description="My brother Quinn and I were tasked to recon Silverpine Forest and report to High Executor Hadrec.  But we didn't get far -- when moving through this farm we were attacked by the ghoul Ivar the Foul.$B$BWe escaped from Ivar, but he seriously mauled Quinn.  He's healing from the potion you gave him, but Ivar may return before Quinn recovers.$B$BKill Ivar so Quinn will have time to heal.  Ivar is usually in the barn yonder, waiting for my guard to drop.",objectives={"Kill Ivar the Foul, and bring Ivar's Head to Rane Yorick at the Ivar Patch."}]])
R(426,"磨坊告急",[[description="The Scourge are trying to form a base at the Agamand Mills.  If they do, then they can stage further attacks within Tirisfal.$B$BThe orders have been given.  The Scourge in the Mills must be destroyed.$B$BGo to the Mills.  Collect Notched Ribs from Rattlecage and Cracked Skull Soldiers, and Blackened Skulls from Darkeye Bonecasters.$B$BTo get to the Mills, follow the road west.  After crossing the bridge, take the next fork north then keep going north.  When you see windmills, the battle will begin.",objectives={"Gather 5 Notched Ribs and 3 Blackened Skulls, then return to Deathguard Dillinger in Brill."}]])
R(427,"與血色十字軍的戰爭",[[description="執行官亞倫大人提供給我們的資料中正是我們與那些卑劣的血色十字軍進行的戰爭中所要的突破點。我們現在知道他們在整個提里斯法林地的確切位置了。$b$b但亡靈衛兵還有其他更艱鉅的任務，巫妖王的軍隊每個夜晚都在逐漸的壯大著。我們需要一些像你這樣的志願者來把那群血色十字軍送進墳墓。$b$b順著鎮外的道路向西走，穿過索利丹農場到廢塔那裡去，殺死10名血色十字軍戰士。以此來證明你有足夠的能力為黑暗女王陛下服務。",objectives={"布瑞爾的執行官塞加德要求你去殺掉10名血色十字軍戰士。"}]])
R(428,"失蹤的亡靈哨兵",[[description="A couple weeks ago two of our Deathstalkers, Rane and Quinn Yorick, were sent on a reconnaissance mission through northern Silverpine.  We have not heard from them.$B$BThey may have become victim to the Scourge, though if that is true then I want it confirmed.  Find these Deathstalkers.$B$BTheir first objective was to scout the farms in northern Silverpine.  You should begin your search there.",objectives={"Find the Deathstalkers Quinn and Rane Yorick."}]])
R(429,"荒野之心",[[description="My brother Quinn was badly hurt by the ghoul, Ivar the Foul, and I don't know if he will heal properly without magical aid.  Although I am not an apothecary, I do know that our apothecaries can make healing potions from the discolored hearts of worgs.$B$BGather such hearts and take them to Apothecary Renferrel at the Sepulcher to the south.  Then return here with the potion.$B$BYou can find plenty of worgs between here and Malden's Orchard to the east.",objectives={"Gather 6 discolored worg hearts and bring them to Apothecary Renferrel at the Sepulcher."}]])
R(430,"回到奎恩身旁",[[description="Here is the potion to aid in Quinn Yorick's recovery.$B$BNow if you will excuse me, I have very important work to continue...",objectives={"Bring Quinn's potion to Quinn Yorick at the Ivar Patch, north of the Sepulcher."}]])
R(431,"誘靈蠟燭")
R(432,"該死的石齶怪！",[[description="那些該死的石齶怪，它們把我的工作地點變成了一片廢墟！看那裡，又一個火藥桶！$b$b啊啊啊啊啊，我真想鑽到地底下去扭斷它們那豆芽一樣的脖子！我要把它們趕盡殺絕！$b$b即使這樣也無法消除我的憤怒……它們留給了我什麼？什麼也沒有！$b$b我要親手殺了它們，不過我的胳膊已經不再那麼有力了！到採石場去，幹掉那幫該死的傢伙！我會獎賞你的！只要你去幹掉它們！",objectives={"在古博拉採掘場裡替工頭喬尼·石眉殺死6個石齶擊顱者。"}]])
R(433,"公僕",[[description="作為參議院與探險者協會的一員，我決定開始瞭解這個地區石齶怪氾濫的事情。$b$b牠們把古博拉採掘場搞了個天翻地覆，而且這種行為看起來毫無理由。當我們在挖掘礦石的時候，牠們突然出現，毀壞了我們的設備，趕走了我們的礦工。我們別無選擇，只得殺光牠們，之後我們才能重建工地並繼續工作。$b$b如果你願意幫助我解決掉那些石齶怪的話，我會很樂意報答你的。",objectives={"到古博拉採掘場裡替參議員梅爾·聖石殺死10個石齶斷骨者。"}]])
R(434,"伏擊！",[[description="After I put on Spybot's disguise, he'll head in to talk to Lescovar. The guards should let him pass no problem.$B$BWhile you were getting materials for me, I took care of informing Marzon that it was time for him and Lescovar to meet again. I even dropped some false information.$B$BLescovar will dismiss his guards and wait for Marzon out here in the garden. After you catch wind of talk about the Defias, make your move. You need to kill them both before the guards return! When you're done, speak to Trias.",objectives={"Remain in the garden until Lord Gregor Lescovar and Marzon the Silent Blade have had their conversation. Afterwards, kill them both before returning to Elling Trias in Stormwind."}]])
R(435,"護送埃蘭德",[[description="The wolves outside won't leave, and they eye me evilly every time I step foot out that door.  They must be incredibly hungry to think I'm worth eating.$B$BI have to report to my teammate, the Deathstalker Rane Yorick.  And to get to Rane, I'll need help against those wolves.$B$BPlease escort me!  And there are a lot of wolves out there, so we'll have a better chance if you have friends who can help...",objectives={"Escort Erland through the wolves, to Rane Yorick."}]])
R(436,"鐵環挖掘場",[[description="Prospector Ironband is heading an excavation of ancient ruins east of the lake.  His progress has been slow lately, especially considering all the supplies we've sent him.$B$BIronband's a stout, honest dwarf who values results, which has me worried that forces are at work against him.$B$BGo to Ironband's Excavation and speak with Magmar Fellhew.  He manages the details of the site and will know why there's a slowdown.$B$BTo get to the excavation site, go around the southern tip of the lake, then head east.",objectives={"Speak with Explorer Fellhew."}]])
R(437,"亡者農場",[[description="Our initial scouting reports of Silverpine show the rot hides have a base at an old farm to the north, the Dead Fields.  We have sent small assaults against them, but each time they are reinforced by the banshee Nightlash, who uses her magic to rout our forces.$B$BWe want Nightlash destroyed.$B$BGo to the Dead Fields and assault the rot hides.  If you don't see Nightlash then kill the rot hides until she appears, then defeat her.$B$BHer essence will turn to dust.  Bring me that dust as proof.",objectives={"Kill rot hide gnolls at the Dead Fields.$B$BWhen Nightlash appears, kill her.$B$BBring the Essence of Nightlash to High Executor Hadrec at the Sepulcher."}]])
R(438,"破舊渡口",[[description="$N, we've discovered a new hive for the Scourge: the Decrepit Ferry.  The ferry lies east of the Sepulcher, and is heavily patrolled by rot hides and other undead.$B$BThere must be a reason for the Scourge's occupation of the area.  Go to the Decrepit Ferry and find out why the Scourge are there.",objectives={"Go to the Decrepit Ferry.$B$BSearch for the reason the Scourge are there."}]])
R(439,"線索",[[description="Among the corpses a hand protrudes, unwrapped.  It is the hand of a woman, pockmarked from the plague but relatively fresh.  $B$BOn the hand is a ring.  Removing the ring and inspecting it reveals an engraving:$B$B\"For Deliah\"",objectives={"Bring Deliah's Ring to High Executor Hadrec at the Sepulcher."}]])
R(440,"黛麗婭的戒指",[[description="If you want to find the husband or beloved who gave Deliah her ring... then speak with Magistrate Sevren in Brill.  He should have records of recent deaths and, with luck, can discover who Deliah is.$B$BBut I wouldn't hope.  Whoever gave her the ring is probably dead.  Or if he's undead he probably no longer cares about Deliah.",objectives={"Bring Deliah's Ring to Magistrate Sevren in Brill."}]])
R(441,"拉林夫與幽暗城",[[description="Deliah had a husband, Raleigh, who now dwells in the Undercity.  If the Deliah who lived in Brill is the one who owned this ring, then Raleigh will know.$B$BRaleigh is in the Trade Quarter of the Undercity.",objectives={"Bring Deliah's Ring to Raleigh."}]])
R(442,"突襲芬裏斯島",[[description="Now is the time to assault the Scourge's place of strength in Silverpine: Fenris Isle.$B$BYou must again go to the Isle and destroy Thule Ravenclaw.  I want his head!$B$BThis mission is as dangerous as it is vital, $N.  You must not fail.",objectives={"Bring Thule's Head to High Executor Hadrec at the Sepulcher."}]])
R(443,"腐皮豺狼人的膿液",[[description="在我們對芬里斯島展開一次突襲行動之前，我們必須得弄清楚誰是腐皮豺狼人背後的真正主人，我們的藥劑師們相信它們的體內發生了某種神秘的變化。$B$B到破舊渡口東邊的芬里斯島去，收集一些腐皮豺狼人身上流出的膿血，然後把膿液交給瑟伯切爾外的藥劑師倫弗利爾。",objectives={"給瑟伯切爾的藥劑師倫弗利爾帶去8瓶腐皮豺狼人的膿液。"}]])
R(444,"腐皮豺狼人的產生",[[description="I have reduced the ichor you brought me and separated it into its base components.  My findings are not conclusive, but I have determined that warlock and necromantic magics were used in the ichor's creation.$B$BWhile I continue to study the ichor, I want you to take a sample to Bethor Iceshard in the Undercity.  Bethor is not an apothecary, but his knowledge of magic may help to unravel the mystery of the rot hides.$B$BGo.  You will find Bethor in the Magic Quarter of the Undercity.",objectives={"Bring the Sample Ichor to Bethor Iceshard in the Undercity."}]])
R(445,"給銀松森林送信",[[description="如今，對我們這些希瓦娜斯女士的僕從來說，時間就是一切。顯然現在你也非常清楚這一點。$b$b身為皇家藥劑師學會的一員，我必須將我的研究成果與同事們分享，只有依靠所有會員的共同努力，我們才能向黑暗女王陛下提供她最期望的新瘟疫。$b$b將這些報告帶給住在銀松森林瑟伯切爾裡的藥劑師倫弗利爾，從布瑞爾向南走，到了幽暗城再轉往西南就可以了。",objectives={"將藥劑師喬漢的研究成果帶給銀松森林的藥劑師倫弗利爾。"}]])
R(446,"圖勒·鴉爪",[[description="這種膿液是我以前的一個同僚圖勒·鴉爪製成的。在大戰之前，他是一個有著大好前途的年輕法師，但在巫妖王的勢力崛起之後，他背叛了他的朋友與兄弟，加入了天譴軍團。$B$B我沒料到他還活著，更沒有想到的是，原來是他在領導腐皮豺狼人與我們對抗。$B$B我對他的許多法術都有所瞭解，應該能幫忙調製出一種能擊敗他們的藥劑。把這個卷軸交給藥劑師倫弗利爾，卷軸上面寫著調製藥水所需要的咒語。",objectives={"把比索的卷軸交給銀松森林中的藥劑師倫弗利爾。"}]])
R(447,"致命的配方",[[description="Arthas's numbers are overwhelming. But with a New Plague we could eradicate both the Scourge Army and the Human infestation once and for all.$b$bMy studies have proven that spider blood combined with a toxin derived from a grizzled bear heart results in a deadly elixir. Collect samples from the spiders in the Skittering Dark to the northwest and from the bears wandering throughout Silverpine Forest. Deliver the reagents to Master Apothecary Faranell of the Royal Apothecary Society in the Undercity.",objectives={"Collect 6 Grizzled Bear Hearts and 6 samples of Skittering Blood and deliver them to Master Apothecary Faranell in the Undercity."}]])
R(448,"給哈德瑞克的報告",[[description="Before you launch an assault on Fenris Isle, report to High Executor Hadrec.  He may have additional information or equipment you'll need.",objectives={"Report to High Executor Hadrec at the Sepulcher."}]])
R(449,"亡靈哨兵的報告",[[description="Although Quinn's wounds are mending, I want to get our report to High Executor Hadrec as quickly as possible.  It has information that is vital to the Forsaken's occupation of Silverpine.",objectives={"Bring the Deathstalker Report to High Executor Hadrec at the Sepulcher."}]])
R(450,"致命的配方",[[description="其實你還能為皇家藥劑師學會再做一些事情，$N。$b$b當初阿魯高在整個森林中施展了他那可惡的魔法時，我們當中一位最有前途的成員——藥劑師博拉爾德，也被他詛咒了。現在博拉爾德已經變成了一個忠於阿魯高的傀儡，換句話說，他對我們已經徹底沒用了。但是他的研究成果可能對我們非常有用，因為他在多年以前曾經研究過一種殺死了洛丹米爾湖中所有生物的瘟疫。$b$b將伯納德的日記從他在焚木村旅店中的研究室裡偷出來，然後把日記交給藥劑師倫弗利爾。",objectives={"從焚木村的旅店中找到伯納德的日記，把它交給瑟伯切爾的藥劑師倫弗利爾。"}]])
R(451,"致命的配方",[[description="According to Berard's Journal the moss from Lake Skulkers and Creepers might prove useful for our quest to brew a new plague.  Those beasts dwell on the islands in Lake Lordamere to the east.$b$bHe also mentions a very rare Hardened Tumor that he discovered on a Vile Fin murloc.  Apparently the tumor is so rare Berard was only able to obtain one.$b$bCollect samples of the moss as well as the rare hardened tumor and take them to Master Apothecary Faranell in the Undercity.",objectives={"Bring 6 samples of Lake Creeper Moss, 6 samples of Lake Skulker Moss and a Hardened Tumor to Master Apothecary Faranell in the Undercity."}]])
R(452,"焚木村中的伏擊",[[description="你來得正好，$N！$b$b焚木村議會隨時都有可能回來，而阿魯高此時正好無暇顧及這裡。他利用議會作為傀儡控制著焚木村中無知的村民們，我相信如果沒有議會的引導，阿魯高的奴隸們一定會反戈一擊，背叛他們的主人。$b$b我無法獨自應付他們所有人。我需要你的幫助，只要齊心協力，我們一定能為希瓦娜斯主人消滅焚木村議會。",objectives={"幫助亡靈哨兵費雷亞消滅焚木村議會。"}]])
R(453,"搜尋烏鴉嶺",[[description="Good luck, $N.  I hope you find the chap, and I hope you find him alive.$B$BIf he's left the safety of Darkshire then he could be prey to the beasts of the wilds.",objectives={"Find the Shadowy Figure.  Your clues:$B$BHe is not native to Darkshire.$B$BHe is a nervous, jittery person.$B$BHe left Darkshire and headed west."}]])
R(454,"惡戰之後",[[description="We'd been hauling the barrels of powder back and forth in trips before this... business. Now we have to split up the work, Miran's taking the barrels and I'm watching over the other ones.$b$bI don't feel safe letting Miran haul the rest of the shipment by himself. When he's ready to go, maybe you could escort him on his next trip?",objectives={"Speak with Miran."}]])
R(455,"丹奧加茲告急",[[description="龍喉氏族的獸人在濕地有了一處巢穴，現在他們的勢力已經快擴展到丹奧加斯了！我們可絕不能讓他們在這裡立足，不然，我們在濕地唯一的港口與要塞——米奈希爾港與洛克莫丹的聯繫將會被切斷。$B$B穿越丹奧加茲到濕地那邊去，向米奈希爾港的瓦斯塔格·鐵齶報到，路上順便殺它幾個獸人玩玩！$B$B米奈希爾就在丹奧加茲的另一邊，只要先順著路向北，然後在岔路口轉向西邊就是。$B$B我們寄希望於你，$N。可別讓我們失望。",objectives={"翻越丹奧加茲。$B$B殺死8個龍喉斥候和6個龍喉步兵。$B$B向米奈希爾港的瓦斯塔格·鐵齶報到。"}]])
R(456,"自然的平衡",[[description="你好，$N。我是管理員伊爾薩萊恩。我的職責是維護幽影谷一帶的自然平衡。$b$b今年的春雨似乎比往年來得都要連綿不絕，這導致了森林中某些動物的過度繁殖，而其他動物就遭了殃。$b$b其中，夜刃豹和草刺野豬的族群已經過於龐大了，幽影谷無法為它們提供更多的食物。去吧，年輕的$c，去減少野豬和夜刃豹的數量，以保證自然的和諧。",objectives={"殺死7隻小夜刃豹和4隻小草刺野豬，然後向管理員伊爾薩萊恩覆命。"}]])
R(457,"自然的平衡",[[description="削減幽影谷地中生物幼獸的數量是一個很好的開始，$N，但這還遠遠不夠。$b$b如果問題不能得到根本解決的話，森林中的資源還是很快就會被耗盡的。殺死某些生物對於生長在這片土地上的所有生物來說都是有益的。為了自然的平衡，到森林裡去清除一些癩皮夜刃豹和一些草刺野豬吧。",objectives={"管理員伊爾薩萊恩要求你殺死7隻癩皮夜刃豹和7隻草刺野豬。"}]])
R(458,"森林守護者",[[description="謝天謝地你在這兒，$c。森林中的小精靈們告訴了我一些奇怪的消息。$b$b神秘的森林守護者塔琳德拉又回到了幽影谷。這位林精的身影已經許多年都沒有在卡林多大陸上的森林中出現過了。她既然回到了這裡，就意味著這裡一定出了什麼事情。$b$b找到了塔琳德拉，並且問問她我們的森林到底怎麼了。有個哨兵向我報告過，塔林德拉曾在奧達希爾的西邊出現過。",objectives={"找到林精塔琳德拉。"}]])
R(459,"森林守護者",[[description="一些邪惡的事物正在泰達希爾的森林中滋生著。看看那些原先性情溫和的熊怪們居住的地方吧。他們放棄了自己的家園，聚集在了所謂的脊骨部落的名下。$b$b一定是那些腐朽毒惡的魔苔的瘴氣造成了這種變異。小劣魔和劣魔也在幽影谷滋生開來，驚擾著這裡的居民。$b$b去和這些小劣魔和劣魔戰鬥吧，$N，觀察一下他們是否真的是受了魔苔的影響。",objectives={"收集8塊魔苔，把它們交給塔琳德拉。"}]])
R(460,"支離破碎",[[description="你看起來跟那幫腐皮豺狼人不一樣，這真好。我都快絕望了……$B$B我叫奧拉瑞克，過去曾是圖勒的大管家兼保鏢。他用他的魔法「保護」了我，使我免受「亡靈瘟疫」的影響，但他的魔法也讓我變成了這個半死不活的樣子。而且，自從圖勒創造了那群該死的腐皮豺狼人之後，他竟然砍了我的頭……還把我的頭給那群豺狼人當球踢！$B$B拜託，把我帶到我的身體那兒去。那群豺狼人大概是把它埋在了芬里斯城堡的馬廄旁……",objectives={"將奧拉瑞克的頭顱帶到他的墳墓旁。"}]])
R(461,"密室",[[description="I know of a hidden niche within the keep that holds an item dear to Thule, and his old colleagues.  It also holds something you might find useful.  Take me there!$B$BThe alcove is in the southwestern tower of the keep, behind a dusty shelf.$B$BTake my body, but leave my boots.  They never fit me anyway...",objectives={"Take Alaric to the hidden alcove."}]])
R(462,"<UNUSED>",[[description="Other than you, we sent two scouts through Algaz.  Only one returned.  Here's what he discovered:$B$BThe Dragonmaws sent one of their Lieutenants, Maruk Wyrmscale, to organize a crew of orcs in Algaz and cut off the land route to Menethil Harbor!$B$BWe have to stop this, now.  Take out Maruk, and then report to Valstag Ironjaw in Menethil Harbor.$B$BMaruk is headquartered in a small cave, across a pond between the second and third tunnels of Algaz.  Menethil is through Algaz, then west along the road.",objectives={"Kill Maruk Wyrmscale$B$BReport to Valstag Ironjaw in Menethil Harbor."}]])
R(463,"綠色守衛者",[[description="You've heard of the Greenwarden?  You're not looking for him, are you?  Well I say you're crazy if you are, but who am I to keep a fool from $ghis:her; death?$B$BIf you are seeking that beast, then I hear he is in the marsh, east of the road where it forks to Dun Modr.  He's lurking there among the crocs...and worse!$B$BAnd leave your money here.  You won't need it where you're going...and you don't want to chip ol' Greenie's tooth on your gold when he bites you in half, do you?",objectives={"Find the Greenwarden."}]])
R(464,"龍喉戰旗",[[description="The Dragonmaw orc clan was all but destroyed by the end of the Second War, after they lost control of their red dragon pets.  The dragons were not very happy with their old masters, and fiercely hunted the Dragonmaws.  What few remained fled from Grim Batol and into the Mountains east of Whelgar's Excavation.$B$BNow they've gained strength, and have an encampment northeast of Menethil.$B$BWe want you to attack that encampment.  Gather and bring me their war banners as proof.",objectives={"Bring 8 Dragonmaw War Banners to Captain Stoutfist."}]])
R(465,"納克羅什的優勢",[[description="當你在和那些龍喉氏族的獸人作戰時，我們又獲得更多有關他們的作戰計畫情報。$B$B首先是一個壞消息，納克羅什正在大量地建造投石車，計畫一舉攻陷米奈希爾！還有一個好消息，經過在丹奧加茲一帶的艱苦奮戰，我們已經把他們的援軍徹底擋了回去！$B$B現在你所要做的就是毀掉那些投石車，它們目前仍被停放在龍喉氏族的營地裡。$B$B拿著，帶上這些火絨。你得先在營地裡殺出一條血路，找到那些投石車，然後再用這些火絨燒了它們。$B$B完成這一切之後，就去找納克羅什，把他給幹掉。我們必須徹底地將這些龍喉氏族的獸人消滅掉！",objectives={"摧毀所有的龍喉投石車。"}]])
R(466,"火巖礦石",[[description="I heard that a rare ore, incendicite, was found in the Wetlands, in a cave northwest of Algaz Gate.  Incendicite is volatile stuff and hard to use without blowing yourself up, but I'm sure if it's smelted the right way it could make cannon shells that pack a mighty punch!$B$BGet me incendicite ore and I'll find someone brave enough to experiment with it.$B$BOh, and to extract that ore from a vein you'll need skill in mining.  If you don't have it, then ... bring a friend who does to that cave!",objectives={"Bring 6 loads of Incendicite Ore to Pilot Stonegear in Dun Morogh."}]])
R(467,"迪恩·石輪的夢想",[[description="駕駛員迪恩·石輪和其他駕駛員一樣非常喜歡他的攻城坦克，他一直都想要找到加強坦克火力的方法！$B$B他聽說有一種罕見的礦石，現在正在到處找人為他尋找這種礦石呢。如果你的腳癢癢的，那就去丹莫洛的鋼架補給站找他吧，看看他需要些什麼。",objectives={"和駕駛員迪恩·石輪談話。"}]])
R(468,"向巡山人羅克加報告",[[description="Mountaineer Rockgar is looking for volunteers for a mission through Dun Algaz and into the Wetlands.  $B$BIf you want to get your boots wet in that soggy county to the north, then speak with Rockgar at Dun Algaz.  Dun Algaz is north up the road, beyond the guard tower.",objectives={"Speak with Mountaineer Rockgar."}]])
R(469,"日常供貨",[[description="你好，旅行者！$b$b你是不是要去米奈希爾港？如果不是的話，我建議你就留在這裡吧，你要是想買點東西啊，喝一杯啊，或者放鬆放鬆神經什麼的話，這裡就再合適不過啦。$b$b如果你確實是要去米奈希爾的話，那麼……我想……你應該不會介意把這捆鱷魚皮捎給皮匠詹姆士·哈洛倫吧？$b$b我本來是想自己親自走一趟的，但我那個在城裡的老婆最近正發脾氣呢，我實在不想馬上就見到她，能拖多久就拖多久。",objectives={"將這捆鱷魚皮帶給米奈希爾港的皮匠詹姆士·哈洛倫。"}]])
R(470,"搜尋軟泥怪",[[description="我每週都要對西北方山腳下的鐵鬚之墓進行例行的拜訪。然而，上次過去的時候，我竟然遭到了那些可怕的軟泥怪的攻擊，我當時自然是嚇壞了。$b$b我身上也沒帶武器，只好抓起背包丟它們，不過那完全沒有用！軟泥怪很輕鬆地把我的背包給吞掉了……不過，幸運的是，這也為我爭取到了逃跑的時間。$b$b但是我現在很需要背包裡的東西！$b$b我已經忘記把包扔進哪隻軟泥怪裡了，它們看起來都是一模一樣的！所以呢，你恐怕得多殺個幾隻才能找到我的背包。鐵鬚之墓就在東北方，丹奧加斯附近。多謝你啦！",objectives={"鐵鬚之墓中的某隻軟泥怪身上有塞達的背包，奪回背包，把它送還給米奈希望港的塞達。"}]])
R(471,"學徒的職責",[[description="我把我的學徒派到了沼澤那邊去，希望他能給我搞到一些著名的巨型鱷魚的皮回來。然而他一直都沒回來，我只好親自去找他……怎麼說呢，反正我當時看到了一些比較慘的場面。$b$b醫生說他很快就會恢復健康的，但現在，我仍然急需鱷魚皮！$b$b……要是你能幫我殺幾條這種兇猛殘忍的大鱷魚，從它們身上給我剝幾張皮下來，我會非常高興的。沿著海岸北上，走過了那些魚人搭建的簡陋小屋之後就能找到鱷魚了。",objectives={"為米奈希爾港的詹姆士·哈洛倫帶回6張巨型鱷魚的皮。"}]])
R(472,"丹莫德的陷落",[[description="丹莫德已經被黑鐵矮人攻陷了！$b$b我傷得很重，$c。我們的大多數戰友都已經犧牲了！我們在薩多爾橋遭遇了伏擊，正在重整部隊的時候，那群該死的黑鐵矮人再度突襲了我們。$b$b我們的領袖布萊德·長鬚被迫吹響了撤退的號角。我們剛一離開鎮子，我就被人從背後砍了一斧頭，然後就眼前一黑昏死了過去。$b$b當我醒來的時候已經身在米奈希爾了，但是，我現在很擔心我手下的士兵們。我依然保有一絲希望，也許布萊德·長鬚還活著！看看你能不能在丹莫德附近找到他吧，$c！",objectives={"在丹莫德鎮附近尋找布萊德·長鬚的蹤跡。"}]])
R(473,"向斯托菲隊長報告",[[description="$N.  The Dragonmaw orc clan is showing its strength in more than just Algaz.  Captain Stoutfist has asked to speak with those willing to offer aid against these orcs.  He is inside the keep, in the war room.",objectives={"Speak with Captain Stoutfist."}]])
R(474,"擊敗納克羅什",[[description="現在所有的投石車都被燒掉了，找到納克羅什酋長，把他幹掉。",objectives={"殺掉納克羅什酋長。$B$B將納克羅什的頭顱交給斯托菲隊長。"}]])
R(475,"煩惱之風",[[description="一陣令人煩惱的微風吹過了森林。$b$b蓋洛拉斯·塔文斯倫一直負責為那些在班奈希爾獸穴中休眠的猛禽德魯伊們放哨。作為沉睡者們的保護者，他的職責是確保德魯伊們的安全，從而使他們可以履行與伊瑟拉定下的契約。$b$b但是我很久都沒有收到蓋洛拉斯的消息，現在我已經越來越緊張了。到東邊的星風村去一趟，幫我把蓋洛拉斯的報告帶回來，這樣會讓我心裡輕鬆一些。",objectives={"在星風村找到蓋洛拉斯·塔文斯倫。"}]])
R(476,"瘤背熊怪的墮落",[[description="瘤背部族的熊怪已經墮落了！$b$b曾經愛好和平的熊怪現在轉而與森林的保護者為敵。我剛剛動身準備去班奈希爾獸穴的時候就遭到了它們的伏擊，而熊怪們現在還準備掠奪星風村！它們的首領——大槌烏薩爾——正在運用魔苔的邪惡力量使它們變得更加瘋狂。$b$b我傷得太重了，無法返回去把這個十萬火急的消息告訴阿斯瑞達斯。這個任務就交給你了，年輕的$c。我們只能希望瘋狂的瘤背熊怪還沒有對班奈希爾下手！",objectives={"返回多蘭納爾去見阿斯瑞達斯·熊皮。"}]])
R(477,"越境",[[description="As you may know, the town of Ambermill remains a source of human opposition, mainly through the support they receive from the wizards of Dalaran.$b$bI don't know what their plan is, but for them to show interest in a backwater village like Ambermill indicates that it must have some greater importance.$b$bThey've been shipping crates by the wagon from Hillsbrad. Many of those supplies end up at a small camp north of Pyrewood Village. Retrieve the contents of a crate and return them to me.",objectives={"Retrieve the contents of one of the Dalaran wizards' crates. You will find Pyrewood Village to the south."}]])
R(478,"地圖與符記",[[description="<You quickly remove the pendant from the crate and replace the lid.>",objectives={"Bring the strange pendant to Shadow Priest Allister at the Sepulcher."}]])
R(479,"調查安伯米爾",[[description="達拉爾正在嘗試著定位出達拉然法師們施法時的能量流向。現在，我們必須要盡我們一切努力來暫緩他們的進程……$b$b那些咒術師、法師和保衛者恐怕會拼死保護墜飾。你必須清除掉這些阻礙，並把飾物搶到手。$b$b沿著大路向南走，在岔路口轉向東邊就可以到安伯米爾了。",objectives={"為瑟伯切爾的暗影牧師奧利斯特搶到8個達拉然墜飾。"}]])
R(480,"法師的頭領",[[description="An archmage of great power is overseeing the reactivation of the ley energy node. With the progress they have made, our only hope of stopping them is by killing him. It will be difficult, he is no doubt protected by many other mages and warders.$b$bYou must go, and you must dispatch him quickly. When he is dead, retrieve his staff for me. Go now.",objectives={"Kill the Dalaran archmage, then retrieve his staff for Shadow Priest Allister at the Sepulcher."}]])
R(481,"達拉爾的推理",[[description="Take the pendant to Dalar Dawnweaver, perhaps he can shed some light on the wizards' plans.",objectives={"Take the rune-inscribed pendant to Dalar Dawnweaver at the Sepulcher."}]])
R(482,"達拉然的意圖",[[description="Of course! How could I have forgotten?$b$bAmbermill was one of the sites earmarked by the Kirin Tor, noted because it houses a dormant ley energy node. The wizards must be planning to reactivate the node and use its energies for some greater purpose.$b$bWe cannot allow this to happen...$b$bIt will take a great amount of power to activate the area's ley energies, we can stall them by taking the pendants away from the wizards.$b$bRelay this information to Allister, he will decide a course of action.",objectives={"Speak with Shadow Priest Allister at the Sepulcher."}]])
R(483,"喚醒聖物",[[description="瘤背部族的熊怪正在西邊的班奈希爾獸穴裡肆虐。$b$b除非我們伸出援手，否則那些正在沉睡的德魯伊將永久地陷於翡翠夢境中，對即將降臨的噩運渾然不覺。只有拿到所有的喚醒聖物，我們才能將休眠儀式打斷。$b$b到獸穴裡去幫我找回鴉爪神符、黑色羽毛、天藍寶石和築巢符文。德魯伊們把這些聖物藏在神聖的盒子裡，把它們帶給我，我要準備進行喚醒儀式。",objectives={"尋回四件喚醒聖物,把它們帶給多蘭納爾的阿斯瑞達斯·熊皮。"}]])
R(484,"小鱷魚皮",[[description="我是皮匠詹姆士·哈洛倫。我用鱷魚皮做東西的手藝可是艾澤拉斯第一流的，每天都有大船把我的產品一箱一箱地運到世界各地的港口去。$b$b你見過埃納爾了吧？他也是專門為我提供新鮮鱷魚皮的諸多獵人之一。$b$b最近我這裡的小鱷魚皮供應量在直線下降，鑒於目前我真的很缺貨，如果你能幫我弄些小鱷魚皮回來，我會給你開出一個非常不錯的價碼。你可以在鎮外的沼澤裡找到那種小鱷魚。",objectives={"為米奈希爾港口的詹姆士·哈洛倫帶回4張小鱷魚皮。"}]])
R(485,"找到OOX-09/HL！",[[description="你發現了一個奇怪的蛋形金屬物體。隨便撥弄了幾下之後，它居然自動打開了，變成了一個看來是由地精製造的機器裝置！一個奇怪的聲音從這個蛋形機器裝置中傳了出來。$B$B「我的名字叫奧格索普，我的母體機器人不見了！如果你能幫我找到它，我就會獎勵你的！請把這個定向器帶到那個母體機器人那裡。別擔心，我現在已經檢測到了它的所在地！它現在就位於藏身石那一帶的河水源頭附近！」",objectives={"把定位器帶到奧格索普的母體機器人那裡去。$B$B奧格索普的母體機器人位於辛特蘭的河水源頭，就在藏身石的附近。"}]])
R(486,"大槌烏薩爾",[[description="Now the time has come to save the Druids of the Talon. If we fail now, $N, they will be forever lost in sleep.$b$bI shall prepare the Relics of Wakening and perform the ritual. For my work to take effect, the cursed beast responsible for this horrible situation must be slain.  Only then will the ritual be complete.$b$bIt was Ursal the Mauler who meddled with our brethren's calling and it is Ursal the Mauler who must now pay so they can be freed.  Travel to Gnarlpine Hold in the southwest and slay him.",objectives={"Kill Ursal the Mauler and return to Athridas Bearmantle in Dolanaar."}]])
R(487,"達納蘇斯之路",[[description="我們必須保證通往達納蘇斯的道路的安全。有報告說，從多蘭納爾去達納蘇斯的旅行者經常會受到來自瘤背熊怪的殘忍襲擊。$b$b每天都有無數重要的資訊在這條路上進行傳遞，因此我們絕對不能容忍這幫墮落的熊怪整日恐嚇無辜的旅者。$b$b以神聖森林的名義拿起武器，$c。熊怪們的巢穴就在這個高地下面的某個地方。去殺死6個瘤背伏擊者，然後再回來向我報告。",objectives={"殺掉6個瘤背伏擊者，然後向多蘭納爾城外的哨兵阿瑪拉·夜行者報告。"}]])
R(488,"賽恩的要求",[[description="我知道你渴望工作，對你來說今天是個幸運的日子，因為我今天只能靠你這個乳臭未乾的$c來幫忙了。$b$b你知道，$N，我可以使你非常幸福，我可以讓你擁有你從未想過的好東西。但是首先，你必須給我帶些東西來。$b$b我在森林裡的工作需要一些材料……給我拿來三顆夜刃豹的牙齒、三根巨翼梟的羽毛和三份樹林蜘蛛絲。",objectives={"給多蘭納爾外面的賽恩·腐蹄帶去3顆夜刃豹的牙齒、3根巨翼梟的羽毛和3份樹林蜘蛛絲。"}]])
R(489,"尋求救贖！",[[description="森林議會聽說你幫助了賽恩·腐蹄，這個險惡的薩特是森林的敵人。作為一個$r，你應該更清楚我們不能殺害自然的生物，玷污聖潔的森林。$b$b如果你希望繼續做泰達希爾的朋友的話，你就必須在眾人的關注下挽回這個過錯。$b$b給賽恩·腐蹄一個教訓，你就可以得到原諒。魔錐果是從樹上掉落的腐壞的種子，一般都冒著綠色的煙氣。$b$b給賽恩帶去3個魔錐果，他會以為那些只是無害的點心。",objectives={"收集3個魔錐果，把它們給在多蘭納爾外面的賽恩·腐蹄。"}]])
R(490,"Bounty: Gnarlpine Furbolg",[[description="By strict orders from the Council of Darnassus, I am commissioning a bounty on the Gnarlpine Tribe. They are no longer friends of the forest. Their corruption has left them mindless threats to our people and the creatures of the glade.$b$bAs decreed by the Council, you shall be rewarded for removing the furbolg menaces from Kalidar. Bring to me their fangs as proof of your deeds.",objectives={"Shayla Nightbreeze outside of Darnassus wants you to bring her 20 Gnarlpine Fangs."}]])
R(491,"給比索的魔杖",[[description="Thule once told me that, long ago, he and two colleagues created a magic wand, woven together from the apprentice wands each mage possessed.  This wand was a symbol of their friendship, and although Thule came to despise it he could not part with it, nor could he let the others have it.  So he stole the wand, and hid it in Fenris Keep.$B$BHere.  Take the wand to Bethor Iceshard, one of Thule's friends from years past.  I'm sure he will want it.",objectives={"Take the Woven Wand to Bethor Iceshard in the Magic Quarter of the Undercity."}]])
R(492,"新的瘟疫",[[description="亡靈衛兵們說，他們又抓住了一個愚蠢的矮人巡山人。在對這個俘虜做出「妥善」處理之前，衛兵們似乎打算把他先關在恐懼之末旅店的地下室裡。$b$b不如你幫我跑一趟，去看看這位可憐的俘虜喜歡不喜歡我為他特製的飲料吧。那飲料裡只摻了一丁點黑暗女王想在整個艾澤拉斯大陸上使用的那種東西……",objectives={"將喬漢的特製飲料交給被俘虜的巡山人。"}]])
R(493,"前往希爾斯布萊德丘陵",[[description="為了給黑暗女士研究出一種新的瘟疫，皇家藥劑師學會最近正承受著巨大的壓力。當然，我們一直在努力工作並取得了突破性的進展。我們堅信，如果我們學會的成員彼此分享研究成果的話，進展將會更快。$b$b因此我要求你將這些我的最新發現送到塔倫米爾的藥劑師林度恩那裡去。塔倫米爾是一座位於希爾斯布萊德丘陵地帶的小鎮，這趟路程可能會很遠。$b$b順路一直向南走，記得看路標！",objectives={"將倫弗利爾的研究成果交給希爾斯布萊德丘陵塔倫米爾的藥劑師林度恩。"}]])
R(494,"進攻的時機",[[description="Be silent and pay attention, $c.$b$bI was sent to this position in order to survey the town of Hillsbrad.  My mission is one of reconnaissance.  It is imperative that you send word to High Executor Darthalia in Tarren Mill at once.  Let her know that I, Deathstalker Lesh, send the following message:$b$b\"The raven's cry from the west doth beckon.\"$b$bFollow the road to the east and pay close attention to the signs.  Now, hurry!  Off you go to Tarren Mill, and with urgency I might add!",objectives={"Travel to Tarren Mill to deliver Deathstalker Lesh's message to High Executor Darthalia."}]])
R(495,"意誌之冠",[[description="Mug'Thol and his ogre warband was sent to Alterac to retrieve the Crown of Will for Lady Sylvanas. Unfortunately, instead of returning it, the idiot decided to try it on... I suppose ogres can't resist anything bright and shiny.$b$bHis bumbling actions have become something of a problem, however. The Crown of Will enabled him to resist the possession placed upon him to serve Lady Sylvanas.$b$bThe Dark Lady wants an example made, travel to Tarren Mill in Hillsbrad and report to Melisara, my lieutenant.",objectives={"Report to Melisara at Tarren Mill in the Hillsbrad Foothills."}]])
R(496,"受難藥劑",[[description="Ah, another wretched day in Tarren Mill.  All of this clean air puts me in such a foul mood, $N.$b$bThe sooner we can plague the humans here, the better.  I've been conducting intense studies on possible killing agents to use in my concoctions but I haven't the time to collect them all.$b$bIf you want to make yourself of use, procure the following items for me:  10 Gray Bear Tongues and the very rare and hard to find, Creeper Ichor.  You'll find both bears and creepers just outside of Tarren Mill.",objectives={"Apothecary Lydon of Tarren Mill wants 10 Gray Bear Tongues and some Creeper Ichor."}]])
R(497,"<UNUSED>",[[description="As a child, raised as a gladiator at Durnholde Keep, I was befriended by Taretha, the daughter of my wet nurse and mistress of the damned bastard Blackmoore.$b$bThe past is the past, $n, but reports of human movements in Hillsbrad reminded me of that time. I dispatched a small party to the area to investigate and to retrieve an... item... given to me by Taretha, if they could.$b$bA fruitless task, no doubt, but perhaps...$b$bThey should have returned by now, I want you to go to Tarren Mill to investigate.",objectives={"Go to Tarren Mill and find out the status of the party sent by Thrall."}]])
R(498,"拯救行動",[[description="Me and some other warriors were sent by the Warchief to retrieve an object from Durnholde and to investigate this so-called Syndicate.$b$bWe went to Durnholde to take a look around, but we were taken by surprise by a large number of the humans. We fought bravely, but their sheer numbers were enough to defeat us. They took a few of us captive, but I was able to escape.$b$bDurnholde is just southeast of here, across the river. Drull and Tog'thar are being held there, you must go and rescue them.",objectives={"Krusk in Tarren Mill needs you to free Drull and Tog'thar from Durnholde Keep."}]])
R(499,"受難藥劑",[[description="It will take but a moment for me to mix these components into what I have deemed an Elixir of Suffering.$b$bThere we go!  Ah, nothing brightens a gloomy day in these miserable foothills like bringing a little suffering into the world.$b$bLet us see if our little potion has achieved its desired effect.$b$bGive my assistant Umpi a taste of what the Dark Lady has planned for both humans and Scourge alike.",objectives={"Give Umpi the Elixir of Suffering."}]])
R(500,"破碎嶺食人魔",[[description="破碎嶺巨魔在奧特蘭克城廢墟附近的山上挖了一座小丘。我的偵察兵告訴我，他們現在還佔領了那片遺跡。$B$B我們可不能讓他們在那兒享福，一旦他們覺得在那兒生活很安全，下一步就會轉移到丘陵地帶，然後就是我們南海鎮了！$B$B到北方的奧特蘭克山去獵殺幾個巨魔。把他們那骯髒的指節骨帶回來，我會給你獎賞的。",objectives={"從奧特蘭克山的破碎嶺巨魔身上收集9個骯髒的指節骨，把它們帶給南海鎮的治安官雷德帕斯。"}]])
R(501,"痛苦藥劑",[[description="Oh, $N. . .the flowers are blooming in Hillsbrad and the air is so fresh and brisk.  I can't help but to wallow in the misery of it all.  I look out my grimy window and long for the day when our New Plague brings this world the death it deserves.$b$bAs much as I would love to sit and brood all day, my duty to the Dark Lady calls.  Help me, would you?  My research leads me to believe I can make the most splendid death-brew with the blood of a Mountain Lion.  Bring some to me and we'll have a little fun.",objectives={"Bring 10 vials of Mountain Lion Blood to Apothecary Lydon in Tarren Mill."}]])
R(502,"痛苦藥劑",[[description="Ah, nothing like the smell of fresh blood in the foothills!$b$bNow we'll mix in a touch of this and a little of that and let the real fun begin!  What I have created with this blood, I like to call an Elixir of Pain.  If my calculations are correct this concoction could be the start of something very beautiful for Lady Sylvanas.  But what we need is a test.$b$bTake this elixir out to the northern farm in Hillsbrad Fields to the southwest.  Let's see how Farmer Ray's little dog Stanley likes this \"treat.\"",objectives={"Feed the Elixir of Pain to Stanley."}]])
R(503,"高迪爾",[[description="從你拿到的檔案看來，高迪爾被關在北邊的一個辛迪加基地裡，很有可能就在奧特蘭克山。他已經被關押太久了，你必須儘快把他救出來。",objectives={"救出高迪爾，然後回到塔倫米爾去見克魯斯克。"}]])
R(504,"破碎嶺好戰者",[[description="你已經和破碎嶺巨魔打過交道了，現在我要你去好好教訓教訓他們……$B$B到奧特蘭克遺跡去獵殺那些破碎嶺好戰者。我希望你多幹掉一些——只有這樣才能讓這幫畜生離聯盟的領土遠一點。",objectives={"殺死15個破碎嶺好戰者，然後回南海鎮向治安官雷德帕斯報告。"}]])
R(505,"辛迪加刺客",[[description="我是南海鎮的新鎮長，前一任鎮長被刺殺之後，我剛剛上任。那些刺客一直都沒有找到，不過據我們調查，幾乎可以肯定他們是由辛迪加雇傭的——辛迪加是一個由邪惡的貴族掌管著的盜賊組織，而那些貴族則是已經陷落的奧特蘭克王國的遺老遺少。$B$B根據我們最新的消息，辛迪加在由部落佔據的小鎮塔倫米爾的北方設有一個營地，到那兒去殺掉那裡的辛迪加成員。",objectives={"殺死12個辛迪加劫匪和8個辛迪加盜賊，然後回到南海鎮向赫尼·馬雷布鎮長報到。"}]])
R(506,"布萊克摩爾的余孽",[[description="A day or two ago, I was visited by the leader of this Syndicate. His name was Aliden Perenolde, and styled himself lord of this land. He confided in me his plans to take the orcs that stood against him as slaves, just as his father and his mentor, the despised Blackmoore, had planned.$b$bMore important was that he brought his mistress, a wisp of a girl named Elysa. Around her neck was the pendant the Warchief desires.$b$bNow go, I will make my own way, after I have settled my business here.",objectives={"Return the information gathered by Gol'dir to Krusk in Tarren Mill."}]])
R(507,"奧裏登·匹瑞諾德",[[description="It is clear that Perenolde must be killed, his foulness removed from the world. His manor lies a ways to the north of here, on the shores of Lordamere Lake. Do your duty, $n, then retrieve the pendant that the Warchief desires, and return here.",objectives={"Kill Lord Aliden Perenolde and ask his mistress, Elysa, about Taretha's pendant."}]])
R(508,"塔蕾莎的禮物",[[description="The pendant? Of course you can have it... Take it! I want no memory of him... just please, please leave in peace...",objectives={"Return Taretha's pendant to Krusk in Tarren Mill."}]])
R(509,"苦楚藥劑",[[description="Another day, another elixir to be made. If it were up to me, I'd just let the pathetic humans and Scourge fight it out.  They seem bent on killing each other as is.$b$bAlas, our Dark Lady wants to help speed up the process a tad so why not pass these morbid days by spreading a little death and disease across the land?$b$bHere's the plan, $N: you go out to Nethander Stead, south of Tarren Mill and east of the river and Southshore. Collect for me 6 Mudsnout Blossoms from the field for my next elixir.",objectives={"Bring 6 Mudsnout Blossoms to Apothecary Lydon in Tarren Mill."}]])
R(510,"預備行動計劃",[[description="這些文件當中有一份物資清單，清單裡包括各種日常物品（食物、武器、衣服）和其他工具（面具、油、毒藥）。$B$B不過其中提到最重要的就是：儘快取得清單中的物資，為文件裡所說的「針對南海鎮的重要使命」進行準備。",objectives={"把預備行動計畫帶給南海鎮的赫尼·馬雷布鎮長。"}]])
R(511,"密文信件",[[description="桌上有一封用密文寫成的信，你根本沒法讀懂。",objectives={"把密碼信交給南海鎮的博學者迪布斯。"}]])
R(512,"貴族之死",[[description="我擔心辛迪加的幕後首腦想要毀滅南海鎮，因此我們必須在他們的計畫得以實現之前幹掉這些頭目。$B$B你去北邊奧特蘭克山裡的斯坦恩布萊德廢墟調查一下，我們覺得那裡是辛迪加的指揮部。$B$B我們知道這幫刺客是以前的奧特蘭克貴族指使的，貴族們可能會打扮成普通辛迪加密探的樣子，不過通過他們手上戴著的徽記之戒就能很容易地判斷他們是不是貴族了。$B$B把他們的徽記之戒給我拿來。",objectives={"為南海鎮的赫尼·馬雷布鎮長收集7個奧特蘭克徽記之戒。"}]])
R(513,"苦楚藥劑",[[description="Just when I thought another day was going to pass devoid of any joy, you brought me those marvelous Mudsnout Blossoms.$b$bFirst I will mix them down into a fine composite.  We'll then need Master Apothecary Faranell in the Undercity to apply his colloid of decay to it and then we'll be ready for some good fun indeed!$b$bHere, take this Mudsnout Composite and run it off to Master Faranell at once, $N.",objectives={"Take the Mudsnout Composite to Master Apothecary Faranell in the Undercity."}]])
R(514,"鐵爐堡的譯碼者",[[description="我在鐵爐堡有個同僚也許可以幫忙破譯這封信。到鐵爐堡的探險者聯盟去找勘察員塔伯斯·雷矛談一談，告訴他是我讓你去的，把這封信給他看。黑石塔以北如果還有人能讀懂這封信的話，那一定就是他了。",objectives={"把密碼信帶給鐵爐堡的勘察員塔伯斯·雷矛。"}]])
R(515,"苦楚藥劑",[[description="泥頭花藥？太棒了！我怎麼沒想過這個呢？$b$b讓我在這種可怕的藥劑裡加入我研製的腐蝕膠體。$b$b如果要啟動泥頭花水裡的污染成分，林度恩就得先弄到強力食人妖之血藥水，還有希爾斯布萊德丘陵南海岸的刺脊納迦的鱗片和碎鰭魚人的眼球。你去找到這些試劑，林度恩會知道怎麼處理它們的。天哪，我真想早點知道他的實驗進行得怎麼樣了！",objectives={"把泥頭花水、1瓶強力食人妖之血藥水、5塊刺脊納迦的鱗片和5顆碎鰭魚人的眼球交給塔倫米爾的藥劑師林度恩。"}]])
R(516,"博倫的巢穴",[[description="我收到報告說，一群天譴軍團的亡靈正在附近集結，準備對我們進行一次襲擊。既然得到了這樣的情報，我們就本應該先下手攻擊他們，把他們的計畫粉碎在繈褓中才對。$b$b但不幸的是，我的情報十分有限，只知道他們在一個名為博倫的巢穴的山洞裡集結。確切的位置我也不清楚，但應該在安伯米爾附近的山區中。$b$b我相信以你的能力和才智，一定可以找到他們，幹掉他們。",objectives={"找到博倫的巢穴，殺死6名鴉爪苦工和6名鴉爪守護者，然後向瑟伯切爾的暗影牧師奧利斯特彙報。"}]])
R(517,"苦楚藥劑",[[description="This new elixir is finally ready to be tested.  But why let a perfectly good, highly contagious plague go to waste on a mere frog or dog?  Let's have us some true fun in the name of Lady Sylvanas.$b$bHead down to Dun Garok.  You know the barracks where those filthy little dwarves skitter about.  Steal me a keg of their Shindigger Stout.  Once I have that keg, you and I will have quite the party, $N.",objectives={"Bring a keg of Shindigger Stout to Apothecary Lydon in Tarren Mill."}]])
R(518,"意誌之冠",[[description="瑪格索爾和他的破碎嶺巨魔在奧特蘭克廢墟已經氾濫成災了。不減少巨魔的數量的話，我們就很難去對付瑪格索爾。$b$b等他們的實力被削弱以後，我們就能繼續前進了。$b$b懂了嗎？好的。去吧。",objectives={"塔倫米爾的梅裡薩拉要你去殺掉14個破碎嶺虐待者。"}]])
R(519,"意誌之冠",[[description="Targ, Muckrake, and Glommus are Mug'Thol's lieutenants. They are loyal to him, though who can say what drives an ogre to loyalty.$b$bBring me their heads, $n, and then all that will remain is to remove Mug'Thol's head, crown and all.",objectives={"Kill Targ, Muckrake, and Glommus and bring their heads to Melisara in Tarren Mill."}]])
R(520,"意誌之冠",[[description="With Mug'Thol's lieutenants dead, all that remains is to kill Mug'Thol and retrieve the Crown of Will. I have no doubt he'll be reluctant to part with it. Most likely expecting you, too, given the... departure... of his fellows.$b$bFind Mug'Thol, and deliver his head and the Crown to me. The Crushridge resistance will be at an end.",objectives={"Kill Mug'Thol, and return his head with the Crown of Will to Melisara in Tarren Mill."}]])
R(521,"意誌之冠",[[description="All that remains is to deliver the Crown of Will to Sharlindra in the Undercity. She will see that it is delivered to Lady Sylvanas. I would warn you against thinking to use it for your own purposes, $n, Mug'Thol's fate should be illustration enough.",objectives={"Deliver the Crown of Will to Sharlindra in the Undercity."}]])
R(522,"刺客的契約",[[description="這是一份刺殺赫尼·馬雷布鎮長的契約。合約已經封好，並用一個特殊的徽記之戒在紅蠟上做了標記。",objectives={"把刺客的契約帶給南海鎮的赫尼·馬雷布鎮長。"}]])
R(523,"男爵之死",[[description="你找到的契約是瓦杜斯男爵簽署的，他是以前的奧特蘭克王國的貴族，並且一向以冷酷和殘暴而著稱。這件事的背後由瓦杜斯這樣的人主使，我對此一點也不感到奇怪。$B$B去找到他，讓他受到正義的制裁。他一定在辛迪加經常出沒的地方活動，也許在斯坦恩布萊德的廢墟，也許在廢墟北面的山谷裡。",objectives={"把瓦杜斯男爵的頭帶給南海鎮的赫尼·馬雷布鎮長。"}]])
R(524,"苦楚藥劑",[[description="Next door the Deathguards are holding a few captured farmers hostage.  High Executor Darthalia suspected one of the military strategists from Stormwind to be hiding out amongst them.  Apparently the military chap was found dead in the Plaguelands last night.  Darthalia, always looking out for me, decided the prisoners would be left to my disposal.$b$bI think it's time we threw those farmers a party.  Sounds like a grand ol' time!$b$bPlace this tainted keg on the rug in their room.  Plagued brew for all!",objectives={"Place the Tainted Keg on the rug for the captured farmers."}]])
R(525,"更大的謎團",[[description="我已經譯出了這封信，不過還是不知道它是什麼意思。你是在奧特蘭克丘陵的盜賊身上找到這封信的嗎？真奇怪……$B$B你應該把它拿去給南海鎮的鎮長看看。雖然這封信的含義不甚明瞭，但是南海鎮離奧特蘭克最近，如果有什麼威脅正在臨近的話，我想應該先告訴他。",objectives={"把被破譯的信件交給南海鎮的赫尼·馬雷布鎮長。"}]])
R(526,"光鑄鐵錠",[[description="You might have found one lightforge ingot in that chest, but that's not enough to craft anything decent!$B$BYou should go back there and look for more.  Maybe the murlocs around that wrecked ship have lightforge ingots on them.",objectives={"Gather 5 lightforge ingots, then return to Glorin Steelbrow in the Wetlands."}]])
R(527,"希爾斯布萊德之戰",[[description="Stand at attention while addressing me, $c.$b$bI am under direct command of Varimathras.  We are to quell the human infestation until our apothecaries can develop the new plague.$b$bOur information leads us to believe that the town of Hillsbrad is vulnerable to attack.  Your first assignment is aimed at disrupting their food supply and infrastructure.$b$bTravel west.  Raid the northernmost farms of Hillsbrad Fields.  Make sure that the landowners, Farmer Ray and Farmer Getz, are executed as well.",objectives={"Kill 6 Hillsbrad Farmhands, 6 Hillsbrad Farmers, Farmer Ray and Farmer Getz and report back to Darthalia in Tarren Mill."}]])
R(528,"希爾斯布萊德之戰",[[description="Word of the attack on the northern farms has the townsfolk panicked.  Most excellent.$b$bOur Deathstalkers report peasants fleeing to the fields in southern Hillsbrad.  The fools think they can hide in the orchards and escape their doom.$b$bProve them wrong, $N.  Return to Hillsbrad Fields and seek out the cowering peasants.  Lay waste to them in the name of our Dark Lady.$b$bDismissed!",objectives={"Kill 15 Hillsbrad Peasants and report back to Darthalia in Tarren Mill."}]])
R(529,"希爾斯布萊德之戰",[[description="希爾斯布萊德的人類進行了頑強的抵抗，這實在有點出乎我的意料。問題的關鍵在於，有幾個鐵匠在為那些鎮民提供武器，我們得切斷他們的所有供給線。$b$b你的任務是幹掉鐵匠維林坦，還有他的那些學徒也得殺了。還有，把他們庫存的鐵也給搶回來。等我們征服了希爾斯布萊德並開始準備進攻南海鎮的時候，這些物資就顯得非常重要了。",objectives={"殺掉鐵匠維林坦和4個希爾斯布萊德見習鐵匠，並從那裡搶回一箱鐵材，然後向塔倫米爾的達薩利亞彙報。"}]])
R(530,"丈夫的復仇",[[description="瓦德雷曾經是我的好朋友，但他也是殺害我妻子的兇手。雖然我已經不知道悲傷為何物了，但我復仇的念頭卻一直沒有改變。去幫我殺了瓦德雷，把他那雙邪惡的手帶給我，我會獎賞你的。$B$B我最後一次聽到他的消息時，他正準備從銀松森林南部的格雷邁恩之牆逃往吉爾尼斯王國。",objectives={"殺掉瓦德雷·莫萊。$B$B把他的雙手帶給幽暗城的拉林夫·安迪恩。"}]])
R(531,"維林的報復",[[description="Light! Don't bring things like that into the Lodge... it's unsanitary, unspeakable, un... un... unsanitary!$b$bJust get it out of here, will you? No one wants to see your bloody little trophy, really!",objectives={"Bring Ol' Sooty's head to Vyrin Swiftwind at the Farstrider Lodge."}]])
R(532,"希爾斯布萊德之戰",[[description="The town of Hillsbrad is in disarray and we believe it will soon fall.  We must, however, persist in our ruthlessness until the human scum are wiped from the foothills for eternity.$b$bDespite their overwhelming losses, the humans rally around their leadership and keep fighting.  We must eliminate their leader, Magistrate Burnside, as well as the town council.  Destroy their revered political document as well, the Hillsbrad Proclamation.  And while you're at it, steal the town registry.",objectives={"Kill Magistrate Burnside and 5 Hillsbrad Councilmen.  Destroy the Hillsbrad Proclamation.  Steal the Hillsbrad Town Registry.  Report back to Darthalia in Tarren Mill afterwards."}]])
R(533,"秘密潛入",[[description="At last we begin to hear word and rumor, find evidence of Gol'dir's whereabouts. The humans have been moving him around, but we are narrowing down our search and focusing on the large Syndicate camp just north of here.$b$bGo there, $n, and bring back whatever information you can get your hands on.",objectives={"Retrieve information about Gol'dir's whereabouts for Krusk in Tarren Mill."}]])
R(534,"<UNUSED>")
R(535,"仆從瓦裏克",[[description="Urrgh... Injured and dying and confronted with the enemy.$b$bNo doubt you'll kill me anyway, but if you bring me some Southshore stout--your kind does drink, don't they?--I'll tell you what you want to know.",objectives={"Bring a mug of Southshore Stout to Valik in the Syndicate camp."}]])
R(536,"清理海岸",[[description="我從暴風城守衛被調到這個鳥不生蛋的南海鎮來做守衛，這鎮子簡直是一無是處……整日整夜都是一股魚腥味。$b$b更別提治安官雷德帕斯了……他還想要我去對付那幫魚人，哈！$b$b我很難打起精神去跟西部海岸上的那群奇形怪狀的魚人作戰。如果你願意替我去幹掉它們，我會很感激你的。",objectives={"南海鎮的法爾林·奧裡涅爾中尉要你去殺掉10個碎鰭潮行魚人和10個碎鰭智者。"}]])
R(537,"黑暗議會",[[description="你拿來的信是一個自稱為納伽茲的人寫的，他是「阿古斯復甦」的一員。我不知道這個「阿古斯復甦」是個什麼樣的組織，不過如果他們和辛迪加是一夥的話，就是我們的威脅。$B$B我要你去查查這封信上提到的納伽茲和阿古斯暗影法師。找到他們，把他們幹掉。$B$B去高地看看，那裡是辛迪加的勢力範圍，就在斯坦恩布萊德的北面。$B$B如果運氣夠好的話，你就能在那兒找到這些「阿古斯復甦」的特使。",objectives={"殺死4個阿古斯暗影法師。$B$B把納伽茲的頭帶給南海鎮的馬雷布鎮長。"}]])
R(538,"南海鎮",[[description="$N，如果你不介意多跑點路的話，我有件任務給你，好為我們的暴風城圖書館增加一些書籍。$B$B古代王國奧特蘭克在大戰之後就已經衰落了，但那裡有著大量的藏書。奧特蘭克的都城被毀實在是個悲劇，但如果他們的知識也失傳了的話，那就將是個更大的悲劇！我們必須竭盡全力地挽救我們能挽救的東西。$B$B南海鎮是最接近奧特蘭克廢墟的地方，到那裡去找博學者迪布斯吧，他會告訴你在哪裡可以找到書。",objectives={"與南海鎮的博學者迪布斯交談。"}]])
R(539,"希爾斯布萊德之戰",[[description="The Hillsbrad Town Registry indicates that the Azureload Mine is under Alliance control.  Furthermore, the mine is a prime source of iron ore for the Alliance armories.$b$bEven though we've struck a decisive blow to the town of Hillsbrad, the Alliance still supports and protects the Azureload Mine fervently.$b$bThe mine lies due south of Hillsbrad.  Go there and slay the foreman, a human by the name of Bonds.  Kill his miners as well.  That should send a clear message to the Alliance.",objectives={"Kill Foreman Bonds and 10 Hillsbrad Miners and report back to Darthalia in Tarren Mill."}]])
R(540,"保全書籍",[[description="那些野蠻的巨魔現在就駐紮在奧特蘭克廢墟，一想起他們會把那裡的書籍怎麼樣，我就感到毛骨悚然。你一定要盡力去完成我給你的任務！$B$B進入奧特蘭克廢墟，找到巨魔奪走的書籍。把你找到的所有東西都帶給我，特別是這本書：《格里雷克之臂》。這本書裡寫著食人妖的古老學說，我一定要學。奧特蘭克是完整保存這本書的唯一地方。",objectives={"把5本失而復得的書籍和包含《格里雷克之臂》的破舊的皮書帶給南海鎮的博學者迪布斯。"}]])
R(541,"希爾斯布萊德之戰",[[description="Dwarves aiding the humans?  Damn those filthy little beasts.$b$bWe shall test the strength of the so-called Alliance.  We'll see how anxious those little ankle-bashers are to help the humans once they feel our wrath.  We know exactly where their stronghold is in this territory.$b$bThey have established a barracks in southeastern Hillsbrad along Thoradin's Wall called Dun Garok.  The final mission of this battle is to lay siege on Dun Garok, $c.  Captain Ironhill, their leader, must die.",objectives={"Travel to Dun Garok and kill 10 Mountaineers, 8 Riflemen, 4 Priests and Captain Ironhill and report back to Darthalia in Tarren Mill."}]])
R(542,"向米爾頓回復",[[description="I need to spend some time studying the Arm of Gri'lek book you brought me, though I'm sure Milton is eager to get the other recovered books into Stormwind's collection.$B$BHere are the books you gathered from the Ruins of Alterac, packed and catalogued.  Take them back to Milton Sheaf in Stormwind and I'm sure he'll be grateful.",objectives={"Bring the Tomes of Alterac to Milton Sheaf in Stormwind."}]])
R(543,"匹瑞諾德王冠",[[description="匹瑞諾德王冠據說是奧特蘭克王國被毀滅之前的「名門望族」匹瑞諾德家族的傳家之寶，有人說它是由鐵爐堡的珠寶大師們用最美麗的翡翠製成的。$B$B當奧特蘭克家族被毀滅的時候，王冠也隨之遺失了。但有傳聞說有一個巨魔法師——叫什麼守財奴格雷爾伯格的傢伙——得到了它，那傢伙現在還在奧特蘭克遺跡附近遊蕩，想要找到更多的財寶。$B$B我們希望你能為我們取回王冠。",objectives={"將匹瑞諾德王冠帶給暴風城的雷明頓·瑞治維爾。"}]])
R(544,"入室偷竊",[[description="I came to Tarren Mill to research, but now must resolve a crisis.  You see, four Forsaken fled the Undercity a few months ago.  They turned their backs on their brethren, but what's worse...they stole from the Dark Lady.$B$BThese thieves broke into a secure vault and stole four artifacts, items our apothecaries required in certain studies.  Sylvanas would have these artifacts returned.$B$BThe thieves fled the Undercity to Dalaran, and those wizards quarantined them in the Lordamere Internment Camp.",objectives={"Find the traitors and recover their artifacts, then return to Magus Voidglare in Tarren Mill."}]])
R(545,"達拉然巡邏隊",[[description="達拉然的巫師在他們的城市中心建起一個巨大的魔法護罩。有人認為那是為了防止城市遭到攻擊，還有人認為他們只是想有個安靜的地方供他們進行魔法研究。$B$B不管那到底是什麼原因，我關心的是在那個護罩之外的郊區廢墟裡是否藏著有用的魔法物品。$B$B不過那裡有許多巫師和他們的元素奴僕在到處巡邏。$B$B去殺了他們，殺到你手軟之後再回來吧。",objectives={"殺掉6個達拉然召喚師和12個元素奴僕，然後回到塔倫米爾去見大法師沃迪恩·伍德格賴爾。"}]])
R(546,"死亡的紀念品",[[description="I hear you were enlisted by Darthalia to wage war on the humans of Hillsbrad.  So jealous I am. . .$b$bWhile you're off having all the fun -- slaying humans, pillaging the town, terrorizing innocent people -- I am stuck standing guard here in Tarren Mill.$b$bPerhaps you'll take pity on an old Deathguard like myself?  You see I am collecting human skulls.  And you will be fighting humans for quite some time.  Over the course of your long battle, bring me 30 skulls and I will make it worth your while.",objectives={"Deathguard Samsa of Tarren Mill wants 30 Hillsbrad Human Skulls."}]])
R(547,"亨伯特的長劍",[[description="高級執行官達薩利亞派我從遠處監視丹加洛克。我在一個隱蔽的角落裡紮了營，但是那天早上我在燒水的時候離開了一會兒去找柴火……$b$b等我回來時，發現放在營地裡的裝備已經不見了。$b$b一定是那些丹加洛克的矮人偵察兵從這兒經過的時候把東西拿走了。我必須得拿回我的劍！如果你能幫我拿回來的話，我會很感激你的。但是那兒的矮人真是太多了……也許你很難在他們當中找出那個小偷。",objectives={"從丹加洛克拿回亡靈衛兵亨伯特的長劍，然後回到塔倫米爾把劍還給他。"}]])
R(548,"<NYI> <TXT> Bloodstone Pendant",[[description="This will start the Bloodstone Pendant quest line...<NYI>"]])
R(549,"通緝：辛迪加成員",[[description="By the authority of Lady Sylvanas, all members of the organization known as the Syndicate are wanted dead. Those brought into custody or taken prisoner will be summarily executed. They are currently known to be amassing in the ruins of Durnholde Keep, to the southeast of Tarren Mill.$b$bA handsome reward is offered to all who bring proof of their deeds to High Executor Darthalia.",objectives={"Kill 10 Syndicate Rogues and 10 Syndicate Watchmen. Return to High Executor Darthalia in Tarren Mill for your reward."}]])
R(550,"希爾斯布萊德之戰",[[description="Because you fought with such valor and perseverance in the Battle of Hillsbrad, I have written this commendation, extolling your heroics in combat for the high command to recognize.$b$bTake this sealed commendation to Varimathras in the Undercity.  Go with pride, $c.",objectives={"Take Darthalia's Sealed Commendation to Varimathras in the Undercity."}]])
R(551,"附有魔法的羊皮紙",[[description="這張羊皮紙上被施加了某種咒語，使其無法被破譯。但是，卷首的一個詞卻很容易辨認：$B$B$B      納伽茲$B$B",objectives={"將這張附有魔法的羊皮紙帶給南海鎮的博學者迪布斯。"}]])
R(552,"赫爾庫拉的復仇",[[description="Master Helcular was almost complete with his transformation into a Lich when a human lynch mob discovered his ritual lair in the hills and brutally killed him.  To make matters worse they buried his corpse in the Southshore cemetery.$b$bSuch disregard for the great wizard is unacceptable.  As his apprentice I shall see to it that the rains of vengeance fall upon the town of Southshore.$b$bWe will need Helcular's Rod first.  Yeti overtook his ritual lair.  Undoubtedly one of the beasts has it.",objectives={"Retrieve Helcular's Rod from the Yeti and bring it back to Novice Thaivand in Tarren Mill."}]])
R(553,"赫爾庫拉的復仇",[[description="Here, take the Rod of Helcular. You will need it.$b$bHelcular fashioned 3 ceremonial pyres as part of his most powerful spell.  The Flame of Azel and the Flame of Veraz lie within the Foothill Caverns. The Flame of Uzel lies in a cave above the caverns, further north in the mountains.$b$bThe Rod of Helcular must be charged from each of the three flames. Once the ritual is complete, drive the rod into Helcular's grave in Southshore, the heavily guarded human town to the south.  Vengeance shall be ours!",objectives={"Charge the Rod of Helcular with the powers of the Flame of Azel, Flame of Veraz and the Flame of Uzel.$b$bDrive the charged rod into Helcular's grave in Southshore."}]])
R(554,"解碼高手",[[description="勘察員塔伯斯·雷矛是解碼和解碼的高手。把你找到的羊皮紙交給他，運氣好的話，他說不定能弄清楚這裡面寫著什麼。塔伯斯·雷矛現在正在鐵爐堡的勘礦指揮部進修。$B$B見到他的話，就說你已經跟我談過了，好像我最近給他添了不少的麻煩……",objectives={"把附有魔法的羊皮紙帶給鐵爐堡的勘察員塔伯斯·雷矛。"}]])
R(555,"海龜湯",[[description="關於南海鎮，你最需要瞭解的是我們這兒有暴風城以北地區最好的美食！$b$b比如說我的秘密食譜：海龜湯。我聽說曾有人遠從夜色鎮趕來這裡，只為品嘗一碗海龜湯！不過我最近一直都沒做過這種美食。我曾經從達拉然一直走到洛丹米爾湖去捕獵鉗嘴龜，不過現在實在不是外出冒險的時候。如果你從北邊那條河里弄點鉗嘴龜身上的海龜肉來給我，外加一份舒心草的話，我就能很快做出點海龜湯來讓你大飽口福。",objectives={"給南海鎮的廚師傑森帶去10塊海龜肉和一些舒心草。"}]])
R(556,"石雕",[[description="A notable talent of the wizards of Dalaran is their familiarity with elementals: powerful creatures from other dimensions.  The wizards use magical tokens as a means to control these elementals.  Magus Voidglare would like some of these tokens to study.$B$BEnter the territories of the Dalaran wizards, west of Hillsbrad, and gather the tokens.$B$BYou might find the tokens on any citizen of Dalaran, but I suggest hunting at the internment camp.  It's safer than Dalaran itself.",objectives={"Bring 10 Worn Stone Tokens to Keeper Bel'varil in Tarren Mill."}]])
R(557,"地縛護腕",[[description="大法師會對你帶回來的石雕進行研究，不過我知道他會需要一些和石雕配合的東西，也就是地縛護腕。法師們將這些護腕帶在元素生物的手腕上，以此來束縛他們。$B$B去幹掉幾個在達拉然廢墟裡遊蕩的元素生物，把它們的地縛護腕拿回來，大法師一定會很滿意的。",objectives={"為塔倫米爾的看守者貝瓦里爾收集4個地縛護腕。"}]])
R(558,"珍娜的簽名",[[description="They say that Lady Jaina Proudmoore in Theramore is one of the greatest heroes the Alliance has ever had.  When I grow up, I wanna be a hero of the Alliance too!$B$BDo you know Jaina, $N?  Could you do me a favor, please?  Could you get her autograph for me?  I dunno how to ask her, and she'd probably be too busy for someone like me... but you!  You're an adventurer just like she is!  I bet she'd give you her autograph easy!$B$BPlease?",objectives={"Travel to Theramore to see about getting Lady Jaina Proudmoore's autograph for your ward."}]])
R(559,"法爾林的證據",[[description="你相信嗎，$n？雷德帕斯對咱們殺了那麼多魚人還是不滿意——哦，別謙虛了，你在這方面還挺有本事。現在他又要我證明我真的殺過魚人，他要我把那些冰涼的、粘糊糊的魚人的頭給砍下來讓他過目，這樣我才能得到他的肯定。",objectives={"南海鎮的法爾林·奧里涅爾中尉要你從西部海岸的魚人身上收集10顆魚人的頭顱。"}]])
R(560,"法爾林的證據",[[description="你知道，$n，我真的不想碰這些魚人的腦袋……既然是你解決了它們，那你能不能再幫我把它們送去給雷德帕斯？",objectives={"把一袋魚人的頭顱交給南海鎮的治安官雷德帕斯。"}]])
R(561,"法爾林的證據",[[description="請告訴法爾林·奧裡涅爾中尉，我覺得他應該把注意力重新集中在滋生於東部海灘的納迦身上。告訴他，一旦有什麼進展，就親自來向我彙報。",objectives={"和南海鎮的法爾林·奧裡涅爾中尉談話。"}]])
R(562,"升官之道",[[description="我以前在暴風城的導師發來消息告訴我聯盟的高級將領已經開始關注納迦帶來的威脅了。根據他打聽來的消息，任何人在這方面有所表現的話，都很有可能得到提拔，或者至少是調動工作崗位。$b$b不過有一個小問題……我對付不了納迦，$n。哦，當然，我能阻止酒吧裡的醉漢互相爭吵，也能拖走好鬥的乞丐，不過納迦對我來說就太難對付了。你一定得幫我這個忙，$n。",objectives={"南海鎮的法爾林·奧裡涅爾中尉要你去殺掉10個刺脊灘行者和10個刺脊海妖。"}]])
R(563,"人事調動",[[description="我的這份報告看來應該是沒什麼問題了。新的守衛長官山繆森少校曾是我的導師。有了這份報告，他就完全有理由把我調回暴風城了。我需要你幫忙把報告交給他，不過……你可別讓雷德帕斯拿到它。",objectives={"把法爾林的報告交給暴風要塞裡的山繆森少校。"}]])
R(564,"損失慘重",[[description="沒有什麼事比失去這些駿馬更讓我煩心了。相信我，就是那些討厭的亡靈、可惡的辛迪加惡匪和其他害人的東西在這一帶到處遊逛，殺了我們不少的馬匹。$b$b不過我可以對著我爺爺的墓碑發誓，對這些馬匹威脅最大的還是奧特蘭克上的山地獅。它們總是從山上跑下來給我搗亂！$b$b你覺得自己是個英雄？那就去做點什麼來證明吧！",objectives={"南海鎮的達倫·瑪爾維要你殺掉8隻山地獅和10隻巨型山地獅。"}]])
R(565,"巴圖羅的雪人毛皮披風",[[description="我，偉大的巴圖羅，將為你做一件聞名世界、全聯盟皆知的雪人毛皮披風！$b$b不信你就到處跑跑看，能不能再找件更棒的。每個人都會說：「巴圖羅，沒有比這更好的披風了！」當然，當然沒有。$b$b巴圖羅需要一個毛布卷，一件由技藝高超的製皮匠縫製的山地披風，一股細線，當然還要有雪人的毛皮！把這些東西帶給我，我就讓你看看我的本事！",objectives={"給南海鎮的巴圖羅·吉塞提找一個毛布卷、一件山地披風、一股細線和10塊雪人的毛皮。"}]])
R(566,"通緝：瓦杜斯男爵",[[description="高級執行官達薩利亞發出命令，通緝名叫瓦杜斯男爵的人類，此人對被遺忘者犯下了重罪。瓦杜斯是辛迪加組織的高級人物。$b$b最後一次有人見到他是在塔倫米爾北部的奧特蘭克山高地上。$b$b殺死他，然後帶著他的頭去見高級執行官達薩利亞換取報酬。",objectives={"殺了瓦杜斯男爵，把他的頭帶給塔倫米爾的高級執行官達薩利亞。"}]])
R(567,"危險！",[[description="危險！$b$b以下這個希爾斯布萊德人是危險人物，已被高級執行官達薩利亞懸賞捉拿：$b$b通緝犯書記員赫拉斯·懷特斯蒂德殺害了亡靈衛兵托馬。$b$b通緝犯平民維爾克斯殺害了藥劑師埃利。$b$b通緝犯礦工哈克特殺害了亡靈衛兵弗雷。$b$b通緝犯農夫卡拉巴伏擊運往幽暗城的物資。$b$b這些敵人都躲藏起來了，很難找到，殺掉他們有重賞。",objectives={"塔倫米爾的高級執行官達薩利亞懸賞通緝書記員赫拉斯·懷特斯蒂德、平民維爾克斯、礦工哈克特和農夫卡拉巴。"}]])
R(568,"格羅姆高保衛戰",[[description="Throm'ka, $c!$b$bYour arrival at Grom'gol is timely, indeed.  As commander of the Warchief's base camp here in the jungle I am bound by honor to ensure the safety of all members of the Horde.  Our mission to provide a safe chain of supply to Stonard is being hampered by some of the local inhabitants.$b$bI am putting you in charge of thinning out the raptor population outside of Grom'gol.  Once you have made significant progress, report back to me for reassignment.",objectives={"Commander Aggro'gosh of the Grom'gol base camp wants you to kill 15 Lashtail Raptors."}]])
R(569,"格羅姆高保衛戰",[[description="在第一次進入這片叢林中的時候，我們根本就沒想和當地的土著部落發生任何衝突。我們任務中最重要的部分就是保持對斯通納德的供應線的暢通。但目前的情況很複雜，附近的一群巨魔佔領了格羅姆高東南方的米札廢墟。他們從來就沒把我們的警告放在眼裡，頻繁地伏擊我們的補給車隊。$b$b我授命你去解決掉這群冥頑不化的巨魔。$b$b到米札遺跡去吧，就算不能把他們驅逐出這片地區，至少也得讓他們好好嘗嘗苦頭。",objectives={"格羅姆高營地的指揮官阿格羅戈西要求你殺死10個巨魔蠻兵和5個巨魔巫醫。"}]])
R(570,"摩克薩爾丁的魔法",[[description="The power of the jungle's magic must be realized and then harnessed by the Horde.  My rituals have proven successful so far.  I can cast very powerful enchantments.  For you, brave $c, I shall make a special item indeed.$b$bBring to me some Shadowmaw Panther claws along with a Tigress fang.  Not just any fang will do.  It must be in pristine condition.$b$bThe beasts lurk throughout the jungle but you will find some close by, just across the river from Mizjah Ruins to the southeast.",objectives={"Far Seer Mok'thardin at the Grom'gol base camp wants 8 Shadowmaw Claws and a Pristine Tigress Fang."}]])
R(571,"摩克薩爾丁的魔法",[[description="What I need from you now will be very difficult to obtain.$b$bTo hold all these feathers, claws and the pristine fang in place I require a magical tether.  Only an aged gorilla sinew will work.$b$bYou will only be able to find one on an Elder Mistvale Gorilla.  They are known to forage to the east of Booty Bay.$b$bThe sinew must be perfect.  It might take quite a few kills for you to find exactly what I need but it will be well worth the hunt.",objectives={"Bring an Aged Gorilla Sinew to Far Seer Mok'thardin in Grom'gol."}]])
R(572,"摩克薩爾丁的魔法",[[description="The items you gathered from the feline beasts of the Vale are only the first requirement for a powerful enchanted item.  These jungle trinkets combined with my shamanistic ritual will provide you with a very useful tool in assisting the Horde and the Warchief.$b$bBut now you must gather for me some Jungle Stalker Feathers.  The feathers are traditionally worn by the beasts on their armbands.  You will find a tribe of the raptors directly south of Grom'gol, not far from the great arena.",objectives={"Bring 10 Jungle Stalker Feathers to Far Seer Mok'thardin at the Grom'gol base camp."}]])
R(573,"摩克薩爾丁的魔法",[[description="There is but one final reagent needed to complete the enchantment.$b$bIn the south, towards the western coast, high above the bluffs, lies a Holy Spring.  This spring is the subject of great conflict amongst religious and mystical scholars.  Every race in Azeroth claims that the spring waters were made divine for their people.$b$bMy final request of you: bring to me Holy Spring Water.  Be warned.  An expedition of naga explorers have advanced upon the spring.  They will need to be dealt with as well.",objectives={"Far Seer Mok'thardin of Grom'gol needs Holy Spring Water.  He also wants you to kill 10 Naga Explorers."}]])
R(574,"特種部隊",[[description="如今我們已經在很大程度上削弱了他的正規部隊，但這就意味著你得直接去面對他手下的精銳部隊。如果那些傢伙沒有被派出去襲擊我們落單的士兵的話，他們就應該駐紮在庫爾森營地後山上一處名為「儲藏室」的洞穴裡。$B$B我私下裡認識許多庫爾森的手下，他們都是身經百戰的老兵，對庫爾森忠心耿耿，而且最要命的是，他們對敵人毫不手軟。這對你來說恐怕不是個簡單的任務，$N。多加小心。$B$B你戰勝了他們以後，就去向我的長官多倫上尉覆命吧。",objectives={"殺掉10名庫爾森特種兵和6名庫爾森精神醫師。$B$B然後向反抗軍營地的多倫上尉覆命。"}]])
R(575,"供與求",[[description="「前無古人，後無來者，南海一帶最好的也是世界最好的皮匠。」他們就是這麼叫我的。我！崔斯里克！最好的皮……呃，好吧。$b$b我的皮貨以品質優質而遠近聞名，都是鑒賞家們的首選之物！$b$b我最近收到了來自工匠行會的雷德沃克斯主管的訂單，他需要十二雙刨花皮靴。啊，就是那種由我製作的、非常搶手的靴子。$b$b不過要想做那種靴子的話，我需要一些鱷魚皮才行。在荊棘谷北邊的河邊有很多鱷魚，你看能不能……",objectives={"收集2張淡水鱷的皮，把它們交給藏寶海灣的崔斯里克。"}]])
R(576,"海盜的眼睛",[[description="站住！誰在那邊？$b$b啊，如果沒有那隻特製的魔法眼，我就是個廢人了。當初在一次戰鬥中，我失去了我的眼睛！但幸運的是，我們的船停靠在米奈希爾港時，一位旅行法師送給了我一隻特製的玻璃眼，這樣我才又能看見東西了。$b$b不過昨天晚上我參加了襲擊血帆海盜的行動，在跳出船的時候玻璃眼睛不小心給弄丟了。一定是那幫血帆海盜拿走了我的眼睛！看來他們這群混蛋已經找到了到藏寶海灣來的路。$b$b你能不能幫幫我這個老海盜，把我的眼睛給找回來？",objectives={"藏寶海灣的獨眼迪茲要求你從血帆海盜那裡找回他的眼睛。"}]])
R(577,"收集鱷魚皮",[[description="嗯，這些靴子已經基本定型，接下來就要開始打磨表面了。但你帶來的皮似乎少了點，做不出足夠的鞋墊來。$b$b「那現在我們得幹什麼呢，崔斯里克？」你肯定會馬上問這種問題，哈哈，你跟崔斯里克說話可真不幸啊，因為我馬上就要給你派活幹啦！$b$b沒人會去觀察鞋墊的，所以我們只要找點又厚又便宜的鱷魚皮就行了。納菲瑞提湖旁邊的那種鉗嘴鱷魚就不錯。",objectives={"給藏寶海灣的崔斯里克帶回5張鉗嘴鱷魚的皮。"}]])
R(578,"海潮之石",[[description="如果個島上確實有水元素和哥布林法師的鬼魂的話，也就是意味著在那裡可以采到海潮之石！$b$b我希望你能找到這座鬧鬼的島嶼，去看看上面到底是怎麼回事。哦，如果你想知道更多的有關海潮之石的資訊的話，可以帶著這張憑證去暴風城圖書館，他們會幫你找到我最初讀過的那本傳說的手抄本。$b$b真的是加茲班首先發現那種石頭的嗎……?",objectives={"為藏寶海灣的大財主里維加茲找到鬧鬼的島嶼。"}]])
R(579,"暴風城圖書館")
R(580,"威士忌斯利姆的酒",[[description="我們那天喝醉了，結果從很遠的辛特蘭那邊掉下了船，活活地漂到瞭望海崖這裡來，險些喂了魚。$b$b而且我斯利姆從小就沒怕過水！我們船長從一艘去暴風城的私掠船上搶來了一箱紫葡萄酒。$b$b我們在辛特蘭被風暴襲擊的時候，我東倒西歪地撞碎了那個箱子，結果那裡面的酒在大風大浪裡全都掉進海裡了。我要是不把它們給找回來的話，船長見了我非拿我餵貓不可！幫幫我吧！",objectives={"藏寶海灣的威士卡斯利姆想要你幫他找回弄丟的紫葡萄酒。"}]])
R(581,"耶尼庫的下落",[[description="A doom, there is.  A doom on my chief's youngest son, Yenniku.  As is a custom with our people, he was given to the Gurubashi Trolls of Zul'Gurub, but after my tribe, the Darkspear tribe, left with the orc Thrall, poor Yenniku was lost to us.  I was sent from distant Orgrimmar, back to Stranglethorn, to search for my chief's son.$B$BAnd I believe the Bloodscalp tribe has him.$B$BIf you would help me, then hunt the Bloodscalps.  You may find them to the north.  Gather their tusks and return to me.",objectives={"Bring 9 Bloodscalp Tusks to Nimboya at the Grom'gol Base Camp."}]])
R(582,"獵頭行動",[[description="我們必須弄清楚耶尼庫是否還活著。$B$B殺掉一些血頂部落的獵頭者，並把他們身上掛著的皺縮的頭顱給我取回來。你必須要收集盡可能多的首級回來，這樣我才能檢查一下耶尼庫的頭在不在其中。$B$B如果耶尼庫真的被血頂氏族給殺了，他們的酋長，那個名叫甘祖拉恩的傢伙，就一定會遭受長達600年的惡毒詛咒！$B$B去吧，$N。沿海岸北上，在祖丹亞廢墟和祖昆達廢墟那裡就有很多血頂獵頭者在活動。",objectives={"給格羅姆高營地的尼姆布亞帶去20個皺縮的頭顱。"}]])
R(583,"歡迎來到叢林",[[description="歡迎來到荊棘谷！$b$b也許你並不關心這個問題，但那邊的那位矮人就是聯盟的一位偉大的戰爭英雄，最最勇敢的獵人赫米特·奈辛瓦里。他並不歡迎陌生人來這個營地，不過你看起來已經見過大世面了，$c。$b$b作為一位久經沙場的老將，奈辛瓦里大人總是很關心你們這樣的小輩。$b$b去和他談一談吧，或許他能教你些狩獵的技巧。",objectives={"與赫米特·奈辛瓦里談話。"}]])
R(584,"血頂之顱",[[description="Yenniku was not among the heads, and I thank the Great Serpent for it.  But we are no closer to finding him.$B$BWe must know the truth, and I fear that only the Bloodscalp chief and his witchdoctor know it.  They are the enemies of the Darkspear tribe and will not speak freely, so we must force the truth from their dead lips!$B$BBring me the heads of Gan'zulah and Nezzliok the Dire and place them within this cauldron.$B$BThey are deep within Zul'Kunda.  Bring their heads...we will then make them talk.",objectives={"Bring Gan'zulah's Head and Nezzliok's Head to the bubbling cauldron at the Grom'gol Base Camp."}]])
R(585,"奈茲裏奧克",[[description="<The head of Nezzliok speaks.>$B$BIt is true.  I know where the child of the Darkspears was taken.  You have bested me and bound my spirit, but I will say nothing without appeasement!$B$BThe Bloodscalps war with the Skullsplitters.  To gain my favor, steal from the Skullsplitters 3 of their trophy skulls and place them here with us, so that my spirit will have slaves in the Nether.  One skull must be from their trophy pile in Balia'mah, another from Ziata'jai, and the last from Zul'Mamwe.",objectives={"Bring a Balia'mah Trophy, a Ziata'jai Trophy and a Zul'Mamwe Trophy to the Bubbling Cauldron at the Grom'gol Base Camp."}]])
R(586,"甘祖拉恩",[[description="<The head of Gan'zulah speaks.>$B$BCurse you!  And curse your ancestors!!$B$BOnly blood and revenge can cool my rage, so if that is your wish, then... do this:$B$BThrow yourself into the heart of the Skullsplitters to the east.  Slay the fiercest among them, and if you survive...then break yourself against their chief, Ana'thek the Cruel.  Hah!  Bring me his shattered armor if you can!$B$BMay he tear off your limbs and leave you to rot and be eaten by carrion.",objectives={"Kill 8 Skullsplitter Hunters, 6 Skullsplitter Headhunters, and 4 Skullsplitter Berserkers.$B$BBring the Broken Armor of Ana'thek to the Bubbling Cauldron at the Grom'gol Base Camp."}]])
R(587,"鼻煙",[[description="啊，海上的生活。我不想說這種生活有多美好，但這就是我的生活。$b$b當我每次入港的時候，我都會找個地方好好喝上一杯，再找點高品質的鼻煙抽抽。壞習慣吧，但海盜們怎麼能沒有壞習慣呢，對吧？$b$b所以你可以想像一下，當我發現鎮上的藥草師賣完了他的全部鼻煙並且已經離開了這座小鎮的時候，我會有多沮喪有多傷心了！據說給他運貨的那條船讓那些該死的血帆海盜給搶劫了。$b$b我相信像你這樣勇敢的$c，一定能說服他們交還船上的貨物，對吧？",objectives={"藏寶海灣的迪格要求你帶給他15份鼻煙。"}]])
R(588,"耶尼庫的命運",[[description="<Nezzliok speaks.>$B$BYou have appeased myself and my chief, so I will tell you that which you seek to discover...$B$BYoung Yenniku is lost to his clan.$B$BHe was taken by the witchdoctor Zanzil the Outcast.  Now Zanzil controls him, body and soul, and only the most potent magic could set him free.$B$BA magic that you do not have, $c.$B$BPerhaps your Darkspear allies can offer a hope of Yenniku's salvation.  But that, I doubt.",objectives={"Speak with Kin'weelay."}]])
R(589,"歌唱水晶",[[description="傳說荊棘谷的中心地帶深藏著一塊寶石，這塊寶石的名字叫心靈之眼，其中蘊涵著巨大的力量。如果你得到了這塊寶石，也許我們就能用它將失落於黑暗之中的耶尼庫拯救出來。$B$B我會與叢林之靈們商談，向他們詢問心靈之眼的位置。與此同時，你要去一趟東南方的水晶礦坑，從那裡的鐵齶蜥蜴身上收集一些藍色波光碎片。這些水晶非常稀有，但我們需要利用其中的魔法能量來控制心靈之眼。",objectives={"給格羅姆高營地的肯維雷帶回3塊藍色波光碎片。"}]])
R(590,"潛行者的交易",[[description="什麼？$B$B什麼？！$B$B你要錢？我可不欠你什麼錢。$B$B信？什麼信？哦，你是不是想打架？好吧，朋友……放馬過來！欠錢咧...",objectives={"打敗喪鐘鎮的卡爾文·蒙泰古。"}]])
R(591,"心靈之眼",[[description="The Mind's Eye is held by an ogre mage, east of here and deep within the Mosh'Ogg ogre mound.  His name is Mai'Zoth.  I know him from when the Darkspears dwelt in Stranglethorn - he is vicious, and his magic is strong.$B$BAnd if he has the Mind's Eye, then his magic will be stronger still.$B$BYou must face Mai'Zoth and wrest from him the Mind's Eye.  It is a perilous task, but it is the only hope we have of saving Yenniku.",objectives={"Bring the Mind's Eye to Kin'weelay at the Grom'gol Base Camp."}]])
R(592,"拯救耶尼庫",[[description="I have reshaped the Mind's Eye into a Soul Gem.  Its purpose is twofold: you must use it to stun Yenniku, and once stunned place it upon his head to entrap his soul.$B$BThen, bring the gem to Nimboya.$B$BYenniku dwells with Zanzil the Outcast, at the Ruins of Aboraz, along the Crystal Shore on the distant Cape of Stranglethorn.",objectives={"Bring the Filled Soul Gem to Nimboya."}]])
R(593,"靈魂寶石")
R(594,"瓶中信",[[description="這張便箋上有極漂亮的字跡：$B$B致任何能幫助我的人$B$B拜託，我迫切地需要幫助。一隻巨大的藍鬃猩猩將我囚禁在了南海的一座島嶼上。$B$B這裡夜晚的星象我以前從未見過，島上全是茂密的叢林，但在天氣晴朗的時候，我能看見西北方的蠻荒的海岸，還有幾條大船在向西南航行。$B$B求求你，請幫幫我吧。",objectives={"找到瓶中信的作者。"}]])
R(595,"血帆海盜",[[description="你看起來特別像要找份活幹似的，夥計。雖然我不清楚為什麼一個喜歡在平地上過日子的$r$c會願意幫助我們這些黑水強盜，但我不會阻攔你的。$b$b我們的船就停泊在藏寶海灣，而我們的死對頭——那些該死的骯髒的血帆海盜——正在整個荊棘谷南部胡作非為。$b$b現在我們這裡的人不是抱著酒瓶子就是抱著姑娘！我需要一個探子來幫我做事。$b$b去偵察一下野人海岸上有些什麼，沒錯，就是藏寶海灣北邊的那片沙灘。",objectives={"大副克拉茲要求你去偵察一下藏寶海灣北邊的海灘。"}]])
R(596,"染血的白骨項鏈",[[description="我是被派來格羅姆高幫助尼姆布亞完成他的任務的，但……我發現這裡還有些更有意義的事要做。$B$B血頂部族是我們的敵人。將敵人的戰利品搶過來將極大地鼓舞我們的士氣，同時也能給對方以沉重的打擊。也許你可以幫我們部族獵殺血頂部族的成員……$B$B他們就居住在北邊，幹掉那些血頂食人妖，把染上它們鮮血的白骨項鏈給我拿回來。你拿回來越多項鏈，我們就會越尊敬你。",objectives={"給格羅姆高營地的肯維雷帶回25串染血的白骨項鏈。"}]])
R(597,"血帆海盜",[[description="這是一張藏寶海灣的地圖，上面用紅筆標叉的地方就是你現在站的位置。$b$b圖上潦草的寫著幾行字：$b$b「你們的任務就是悄悄地在此地紮營，等待南方指揮部發出信號後再開始攻擊。如果任何人試圖阻礙你們，格殺勿論。」",objectives={"將你的發現報告給藏寶海灣的大副克拉茲。"}]])
R(598,"裂骨項鏈",[[description="Now that you have gathered Bloodscalp trophies, I have another task for you.  The Skullsplitter tribe of trolls live to the southeast, and for years we have warred with them.  Although the Darkspears no longer dwell in Stranglethorn, we are bound to our conflict with the Skullsplitters.$B$BSo, hunt them.  Gather their Split Bone Necklaces and return to me.  Aid us in our war, and you will earn the friendship of the Darkspears.",objectives={"Bring 25 Split Bone Necklaces to Kin'weelay at the Grom'gol Base camp."}]])
R(599,"血帆海盜",[[description="太令我吃驚了！那麼血帆海盜正計畫著進攻藏寶海灣嗎？這群發了神經病的惡棍當真是不要命了麼，藏寶海灣永遠都是我們黑水海盜的地盤！$b$b這事比我想得還要嚴重。馬上將你所知道的一切報告給艦隊指揮官卡拉·海角！這群該死的海狗可能已經開始在鎮子外面集結了……",objectives={"把血帆海盜的計畫報告給艦隊指揮官卡拉·海角。"}]])
R(600,"風險投資公司",[[description="最近，風險投資公司在荊棘谷一帶展開了一系列的行動，這讓我們這些誠實努力的哥布林們，你看，比如我，根本沒辦法在這裡討生活了！拜託，你一定要幫幫我！$B$B風險投資公司打算在北邊的水晶礦坑那裡採礦，可是由於那邊的石化蜥蜴到處肆虐，他們根本沒辦法進入礦坑，只能在周圍的山上開採歌唱水晶。$B$B去把他們的水晶都搶來，讓他們知道他們不該在這片叢林裡如此囂張。$B$B還有……嗯嗯……把那些水晶給我帶回來當證據！",objectives={"給藏寶海灣的克蘭克·菲茲巴布帶回10塊藍色歌唱水晶。"}]])
R(601,"水元素",[[description="這些水元素無疑是傳說中發現了海潮之石的哥布林法師加茲班召喚的。也許你知道，海潮之石會詛咒任何挪動它的人，就是說，會讓那個倒楣的傢伙從這個世界上徹底消失。$b$b應該有什麼辦法可以破除這個該死的詛咒，我們可以請一位達拉然的法師來幫我們分析一下水元素胳膊上戴著的護腕裡的魔法。你能不能回到那島上幫我收集一些進行魔力分析所需的樣本？",objectives={"為藏寶海灣的大財主里維加茲收集6個水元素護腕。"}]])
R(602,"魔法分析",[[description="雖然我聽說達拉然的法師們正忙著重建他們那被毀的城市，但我敢說，你肯定能找到一個願意幫我們檢查護腕的法師。根據我對那些法師的瞭解，他們是絕對不會拒絕任何與魔法有關的謎題的。$b$b將這包水元素的護腕拿給他們，讓他們看看能不能找到解除石頭上的詛咒的方法。",objectives={"將水元素護腕交給達拉然的大法師安斯雷姆·魯因維沃爾。"}]])
R(603,"安斯雷姆的鑰匙",[[description="The mage that is in possession of the Stone is amplifying its power through some focal point... an altar of some sort. You should be able to disrupt it by overpowering it.$b$bAs it happens, I know just the thing: an ancient dagger, another troll relic. There's just one... little problem.$b$bYou see, I found the dagger while researching in Stranglethorn, but I gave it to my willful daughter, Catelyn, who ran off to Booty Bay to become a pirate.",objectives={"Talk to Catelyn in Booty Bay."}]])
R(604,"血帆海盜",[[description="克拉茲高度讚揚了你為黑水海盜做出的重要貢獻。我信任你，因此我要賦予你一個對於艦隊來說至關重要的任務。$b$b我們要求你滲透進血帆海盜建立在蠻荒海岸的南方指揮部。偷襲他們的營地，將他們的海圖與計畫書都給我帶回來，我們必須要搞清楚這群渣滓到底想幹點什麼。",objectives={"藏寶海岸的艦隊指揮官卡拉·海角要求你殺死10名血帆流氓並將血帆海圖和血帆計畫書帶回去。"}]])
R(605,"歌唱水晶碎片",[[description="歌唱水晶是荊棘谷的一種特產，它對某些人來說有著非常重要的價值。我本想運一些歌唱水晶到別的地方去賣，可那該死的風險投資公司想要獨佔它，所以，像我這樣誠實的商人看來就無法親自去收集水晶了！$B$B我決定雇傭你。$B$B荊棘谷中的蜥蜴都有吞食這種水晶的習性，這可以使它們的皮膚變得更硬。因此，我們可以從它們身上收穫到一些高品質的水晶。$B$B隨便哪隻蜥蜴身上都會有水晶，但最容易對付的是在北邊的海岸附近活動的那些蜥蜴。",objectives={"為克蘭克·菲茲巴布收集10塊歌唱水晶碎片。"}]])
R(606,"嚇唬病鬼",[[description="你知道這裡最讓我受不了的是什麼嗎？這兒的人都有死也不還賭債的毛病！現在已經有一大群傢伙欠著我的錢了。你能幫我催一下債嗎？$B$B第一個要催的就是住在港口那邊的「病鬼」菲力浦。他上個禮拜欠得實在是太多了，我一定要把這筆錢給要回來！但是要想拿到它，我們就得好好嚇唬嚇唬他。$B$B到鎮子外邊去獵殺一些老邁的迷霧谷猩猩，然後從它們身上搞點內臟雜碎什麼的，把這些玩意丟給那病鬼。最好別讓他想到那是動物內臟，讓他想點更糟的。",objectives={"給藏寶海灣的「病鬼」菲力浦帶回5塊迷霧谷猩猩的內臟。"}]])
R(607,"向馬克基雷回報",[[description="給，把這個布袋給海狼。告訴他，我是想還他錢的！我發誓！！$B$B我只是喝多了點，迷路了而已，還有……總之是一團糟了。他會理解我的——你可別亂說啊！",objectives={"將菲利浦的還款交給「海狼」馬克基雷。"}]])
R(608,"血帆海盜",[[description="打擊一下菲爾拉倫的脆弱神經吧！他連劃著小船穿越水晶湖都做不到，更別說獨自率領整支艦隊來和我們對抗了。$b$b血帆海盜一定會為他們的粗心大意而付出代價的。現在我們已經掌握了他們的攻擊計畫，完全可以在他們什麼還都不知道的時候搶先下手。$b$b我們並不需要派出全部的艦隊，只要一支勇敢的冒險者隊伍就能輕易完成這任務。$n，帶上你最優秀的同伴守在菲爾拉倫的登陸點，殺掉血帆的指揮官。這樣他們的艦隊不用多久就可以去餵魚了……",objectives={"藏寶海灣的艦隊指揮官卡拉·海角要求你殺死血帆海盜的斯蒂沃特船長，尼哈魯船長和艦隊指揮官菲爾拉倫。"}]])
R(609,"討債行動",[[description="我這兒的白條已經少了許多啦，但還是有許多沒信譽的傢伙欠著我的錢。$B$B接下來，我們得對付「畸形足」瑪雷·維爾金斯、火柴棍喬喬，還有拇指蘇克。$B$B這幫傢伙的債欠了好久，我看他們是不想還了！後來，我聽說他們被什麼人給騙到叢林裡去了。我當然不關心他們到底會怎麼樣——我要的是我的錢！$B$B他們應該就在東北方的阿博拉茲廢墟和朱布瓦爾廢墟裡。找到他們，把我的錢拿回來。",objectives={"給藏寶海灣的「海狼」馬克基雷帶回瑪雷的畸形足、喬喬的金色望遠鏡和蘇克的巨型戒指。"}]])
R(610,"帥小夥子鄧肯",[[description="我老爸派你來的？我還以為那怪老頭早就已經放棄我了呢。$b$b我之所以離家出走確實不是他的錯，他只是不應該為我安排好一條乏味的人生道路，並希望我欣然接受它。我怎麼能忍受整天讀著那些發黴的書本，整天和那幫灰頭髮加駝背的乏味老頭法師們在一起！$b$b如果你需要我的匕首，你可能得從一個叫「帥小子」鄧肯的血帆海盜那裡奪回來。我想你只要教訓教訓他，他就會屈服的。",objectives={"從「帥小子」鄧肯那裡奪回凱特琳的匕首。"}]])
R(611,"海潮的詛咒",[[description="這麼說你正在尋找某個祭壇嘍？好吧，雖然我不像我老爸那樣是個研究食人妖遺跡的專家，但我對你正在尋找的島嶼也略知一二，在島的附近有一座沉沒在水底的食人妖城市，我想你應該到那裡去碰碰運氣。$b$b既然是你幫我找回了我的匕首，借去用用當然沒有任何問題……但我希望你用完以後能還給我！",objectives={"用凱特琳的匕首摧毀海潮祭壇，然後殺死加茲班，將海潮之石帶給大財主里維加茲。"}]])
R(613,"瑪雷的腿",[[description="該死！那見鬼的瑪雷居然在他的假腿上安了一個鎖，我還死活都打不開！他的寶貝，還有他欠我的錢，都藏在那條假腿裡！$B$B我們得想辦法找到鑰匙才行。瑪雷這傢伙過去因為喜歡和住在東北邊巨魔山上的莫什奧格巨魔賭博而出名，而且他告訴過我——我是說當他還活著的時候——他每次贏了一票大的之後都會去一趟那裡，所以，或許那邊的巨魔會有他的鑰匙。$B$B要真是如此的話，你八成得大開殺戒才能搞到鑰匙……",objectives={"把瑪雷的鑰匙帶給藏寶海灣的「海狼」馬克基雷。"}]])
R(614,"船長的箱子",[[description="I used to sail a ship from here all the way to Ratchet, in Kalimdor.  I was a successful captain with a sterling reputation.$B$BUntil...$B$BThose cursed sea giants ruined me!  They smashed my ship, killed my crew, and set me on a lifeboat to Booty Bay.  And one of the giants, Gorlash, stole my Captain's Chest.  He said he wanted it for a snuffbox.  The nerve!$B$BI hear Gorlash wanders the coast east of here.  Find him and get back my chest!  Do that, and you'll have earned a captain's gratitude.",objectives={"Bring Smotts' Chest to Hecklebury Smotts in Booty Bay."}]])
R(615,"船長的彎刀",[[description="After I lost my first ship to those giants, I bought another.  Named Smotts' Revenge, I filled it with supplies and crew, and set out to find the villains.  I found them, but...they beat me.  They smashed Smotts' Revenge, killed my second crew and set me on another lifeboat.$B$BThis time another of the giants, Negolash, stole my cutlass.$B$BFace Negolash and bring me my cutlass!$B$BSpeak with Sprogger.  He was my cook on the Smotts' Revenge, and survived the last attack.  He can help you find the giant.",objectives={"Speak with Sprogger."}]])
R(616,"幽靈島",[[description="大財主里維加茲讓我留意最近在藏寶海灣和荊棘谷附近流傳的古怪傳聞。雖然我平時是絕不會關心什麼鬼故事的，但這兩天在酒館裡聽一些水手們說在海岸附近有一座鬧鬼的小島。據他們說，那上面全是水元素和一隻整日說著瘋話的哥布林的鬼魂。$b$b如果你正好要去見里維加茲閣下的話，能替我將這件事轉告給他嗎？",objectives={"與藏寶海灣的大財主里維加茲談話。"}]])
R(617,"壹捆海蛇草",[[description="聽說你正在找活做，$N？要是你夠膽的話，我這兒倒是有件不錯的活正要找人呢。$B$B你聽說過最近有許多人都在找一處泉水麼？是的，有一群納迦也在找。我有個叫格羅伊的朋友吧，他最近出了一大筆錢，想買一些納迦稱之為海蛇草的東西。我也不清楚那到底是什麼，只知道是一種很值錢的海草。他也沒說要那玩意幹什麼，不過他確實出了一個好價錢，大概需要一捆吧。$B$B你幫我搞來10根這種什麼草，那我們就可以跟他做筆交易啦。不久前有人看見這裡北邊的海灘上出現了不少納迦。",objectives={"給藏寶海灣的海盜布勞茲帶回10捆海蛇草。"}]])
R(618,"挑戰奈古拉什",[[description="Negolash is a hungry giant.$B$BWhen the giants destroyed our ship, Negolash went straight for my kitchen.  He wasn't hungry for crew like the other giants.  Negolash wanted wine...and my Barbecued Buzzard Wings.  They're my specialty, and I had to go all the way to the Badlands for the recipe!$B$BIf you want to lure the giant, then get some wine and a heap of buzzard wings.  Put them in our old lifeboat, southeast of here along the coast.  When Negolash smells all that food, he'll come for sure!",objectives={"Bring 10 Barbecued Buzzard Wings and 5 bottles of Junglevine Wine to Captain Smotts' Lifeboat.$B$BKill Negolash, and bring Smotts' Cutlass to Captain Smotts in Stranglethorn."}]])
R(619,"引誘奈古拉什")
R(620,"The Monogrammed Sash",[[description="This fine sash has the letters \"HS\" embroidered along its hem.",objectives={"Return the Monogrammed Sash to its owner."}]])
R(621,"贊吉爾的秘密",[[description="流亡者贊吉爾和他的追隨者們住在藏寶海灣東北方的朱布瓦爾廢墟和阿博拉茲廢墟裡，這個傢伙已經被他的部族放逐了。為什麼？這個……$B$B據說是因為贊吉爾掌握了可以屈服其他人的心志的方法，而他所屬部族的領袖因此非常害怕他。他讓他的追隨者們喝下了一種從叢林的植物中萃取出來的液體，用它來壓抑他們的自我意識並加強他們的力量。$B$B這種藥劑對那些試圖控制別人的傢伙來說有非常大的價值。$B$B給我弄些這種藥劑的樣本來，我要研究一下他們有什麼用處。",objectives={"收集12份贊吉爾的藥劑，把它們交給藏寶海灣的克蘭克·菲茲巴布。"}]])
R(622,"向卡雷布下士回報",[[description="在你離開的這段時間裡我已經把這鍋替你修好啦。我甚至還免費加裝了一個特製的蒸汽哨，看，華麗吧！這下面還裝了一個新的自動菜刀，專門用來切蹄膀的！$B$B沒錯，克拉茲克的烹調鍋將為你帶來百分之百的烹調樂趣，我敢打賭它的主人會非常滿意的！",objectives={"將修理過的烹調鍋交給叛軍營地的卡雷布下士。"}]])
R(623,"壹捆海蛇草",[[description="$N，你不在的時候，格羅伊托人給我捎了一個信兒過來。他說他很滿意我們上次送去的貨，現在又有一位新的顧客也想要一些那種海草。$B$B我可不想花上整整一個禮拜去一趟塞拉摩，如果你願意替我去一趟的話，那就再好不過了。$B$B很有挑戰性吧？你知道那邊的塵泥沼澤吧？你可得小心點，塞拉摩可不是個普通人能去的地方。",objectives={"給塞拉摩的海盜格羅伊帶去一束海蛇草。"}]])
R(624,"科泰羅的謎題",[[description="有一座裝飾華麗，人來人往的橋$b逆風徑東，赤脊山南面之地$b在那之下，它正等待著你$b這可以叫提示，也可以叫線索$b在那裡，無盡的明天正等待著你$b在悲傷沼澤之中靜靜地等待著你",objectives={"解開這道謎題！"}]])
R(625,"科泰羅的謎題",[[description="卡林多上的某個遙遠之地$b危險湮滅了命運與希冀$b貧瘠之地以東的環境糟糕至極$b絕望與威脅伴著沼澤中的塵泥$b但那裡埋藏著線索供你尋覓$b在西南的一處洞穴中可解此謎題",objectives={"解開這道謎題！"}]])
R(626,"科泰羅的謎題",[[description="到羅德隆去！那片混亂中的土地$b在那裡，勇敢的戰士們與亡靈為敵$b在劇烈的動盪中尋找屬於你的路途$b最終你會解開這謎題$b沿著艾瑞匹克山巒，位於瀑布之底$b波光之下的寶藏正等待著你",objectives={"解開這道謎題！"}]])
R(627,"克拉茲克的要求",[[description="在阿拉希高地北部的枯鬚峽谷中有一處山洞，那裡有一種十分稀有的礦石：血石。那個山洞裡的血石雖然不是品質最佳的，但即使是低等級的血石也是很有價值的……當然這只是對那些懂得如何使用它們的人來說。$B$B我需要一些這種血石。$B$B我會在這裡修補你的鍋子，不過，當我修鍋的時候……你去給我弄些血石來吧。對，多帶點回來，我當然會給你報酬的。$B$B嗯嗯，要是你連這點事都搞不定，就去找個能搞定的人幫你！",objectives={"給藏寶海岸的克拉茲克帶去4塊次級血石礦。"}]])
R(628,"刨花皮靴",[[description="裡層的東西都已經做完了，現在只剩下外面的表層部分了。表層部分我只用品質最好的老海鱷魚的皮。這種皮比帆布還要好，還要結實--如果你願意的話--，還可以為我的完美設計增加設計感和特色。$b$b但是要找到一張完美的皮很難，只有老海鱷魚的皮是唯一能配得上我的設計的材料。老海鱷只會在其他鱷魚被攻擊的時候才會出來保護族群，所以你恐怕得先殺些普通鱷魚來引牠們出來。",objectives={"帶1張老海鱷的皮給藏寶海灣的崔斯里克。"}]])
R(629,"暗礁海",[[description="很久以前，有一座古老的食人妖城市因為大地震沉入了西北方的野人海岸水下。現在那裡被一群魚人所佔據著，任何接近的人都會遭到他們的攻擊，我們把那處地方叫作暗礁海。$B$B在那片廢墟之中有一塊古老的石板，上面記錄著一位元名叫格里雷克的食人妖英雄的傳說。那塊石板對於我們暗矛部落來說具有神聖的意義，儘管它太大，沒辦法全部運走，但我仍希望有人能從上面敲下一塊碎片，讓我們帶到奧格瑪的新家去供奉起來。",objectives={"給格羅姆高營地裡的肯維雷帶回一塊石板碎片。"}]])
R(630,"瓶中信",[[description="$N，我的一切都全靠你了！是藍鬃猩猩之王穆克拉把我抓進來的，它統治著這島上所有的野獸，它們不顧我的反抗，用這些鐵鏈把我給鎖在這兒。如果你能殺了它，從它身上找到能夠打開這套鐐銬的鑰匙的話，我會好好報答你的。$B$B它通常在這座島的北邊活動，但你一定得小心，它絕對是一個很難對付的傢伙。",objectives={"殺死穆克拉並帶著鑰匙回去救出普巴爾公主。"}]])
R(631,"薩多爾大橋",[[description="當時，山裡突然傳出了一陣巨大的爆炸聲，而且在山谷中回蕩了很久。那簡直太可怕啦！$b$b士兵們為了守衛薩多爾大橋死傷慘重。長鬚說我們總有一天要向黑鐵矮人們復仇的。$b$b我們目前的情況非常窘迫，而且暫時也得不到任何援軍。長鬚派了老伊本瑟去偵查東邊的那座橋，看看我們是否有機會攻陷那裡。$b$b可這已經是好幾天以前的事了。丹莫德目前全城被圍，我們根本無法抽出人力去聯絡他。$b$b或許你能幫忙去找他……",objectives={"拉格·加瑪森要求你找到老伊本瑟。"}]])
R(632,"薩多爾大橋",[[description="It seems as though poor Ol' Rustlocke ran into a Dark Iron ambush.  You notice a parchment next to his clenched fist.$b$bReport the grim news to Rhag Garmason and show him what you found.",objectives={"Report back to Rhag Garmason and show him the parchment you found on Rustlocke's corpse."}]])
R(633,"薩多爾大橋",[[description="Heavens no!  Poor Rustlocke.  'Tis quite a tragedy indeed.$b$bWe must not let his death pass in vain.  This parchment you discovered indicates that Kam Deepfury, the mastermind behind the original attack, arranged for a cache of explosives to be stashed just across the Thandol Span, in Arathi Highlands.$b$bIf those explosives make it to the bridge, our major supply line to the north will be severed!  The cache must be destroyed, $n!  Return to me when your mission is complete.$b$bYou're our only hope.",objectives={"Destroy the cache of explosives."}]])
R(634,"請求援助",[[description="I ask of you one more small favor, $c.  We await the reserves of Ironforge.  However, Roggo has knowledge of an Alliance camp to the north in Arathi Highlands at Refuge Pointe.$b$bTravel there and seek out Captain Nials.  Ask the good Captain if the Alliance can spare some soldiers to help us reclaim Dun Modr and the Thandol Span.",objectives={"Seek out Captain Nials at Refuge Pointe."}]])
R(635,"山中的水晶",[[description="你拿著這塊碎片，明顯地感覺到它在跳動著……$B$B你感到它在祈求，好像有什麼人想要與你交流，急切地需要你的幫助。$B$B你的腦中出現一幕奇特的影像——在阿拉希的北部山脈上，有一塊明亮的水晶從地面上突出來。$B$B你感覺到自己仿佛被帶到了那個地方……",objectives={"找到你在幻覺中看到的那塊水晶。"}]])
R(636,"Legends of the Earth <NYI>",[[description="This book tells the tale of an elemental princess, Myzrael, and of her imprisonment deep underneath the Arathi Highlands.$B$BIt also tells of a secret outcropping of crystals in the highlands.  These crystals, the Shards of Myzrael, are a window to the princess' prison.$B$BIf a brave soul found the Shards of Myzrael, the perhaps $ghe:she; could speak with her...",objectives={"Find the Shards of Myzrael."}]])
R(637,"蘇利·巴魯的信",[[description="你手中的這封信濕淋淋的，已經面目全非了，只有幾頁像是得到了精心保護的信紙上的字跡還能辨認。$b$b這封信是寫給鐵爐堡的薩拉·巴魯女士的，開頭寫著，「親愛的薩拉……」",objectives={"把蘇利·巴魯的信交給鐵爐堡的薩拉·巴魯。"}]])
R(638,"巨魔之敵",[[description="With Thoras Trollbane dead and Stromgarde in ruins, Vol'jin has instructed that we make every effort to spirit the legendary sword Trol'kalar from the humans' hands, so that we might use it in our coming battles against the trolls of Zul'Gurub.$b$bZengu, one of our seasoned hunters, was dispatched to Hammerfall in northeastern Arathi Highlands to oversee its procurement.",objectives={"Travel to Hammerfall in the Arathi Highlands and speak with Zengu."}]])
R(639,"激流堡符印",[[description="In ancient times, trolls fought against the Arathorian Empire and our most capable adversary, Lord Ignaeus of Strom, named Trollbane. He rode into battle wielding Trol'kalar--troll slayer, in their ancient tongue.$b$bBut now the sons of Trollbane are weakened, their stronghold brought to ruin.$b$bThe sword is protected by several sigils that were divided among the survivors of Stromgarde, and we must retrieve them.$b$bThe first was taken by the Syndicate, one of their men in Stromgarde should have it.",objectives={"Get the Sigil of Strom for Zengu in Hammerfall."}]])
R(640,"破碎的符印",[[description="Thoras Trollbane's tomb is protected by three sigils--the first of which you retrieved from the Syndicate. The other two will be harder to get, as they're held by the firmly entrenched Stromgarde militia.$b$bThe sigil of Thoradin was divided into eleven pieces by Thoras' son, Galen, and dispersed among the Stromgarde defenders. Retrieve the pieces and bring them to Tor'gan, the troll shaman, he will be able to bind them into the complete sigil.",objectives={"Retrieve the 11 Sigil Fragments from the defenders in Stromgarde, and bring them to Tor'gan in Hammerfall."}]])
R(641,"索拉丁符印",[[description="The reconstruction worked flawlessly. The sigil can now be used to unlock the seal on Trollbane's tomb. Return it to Zengu, no doubt he has additional tasks for you to complete.",objectives={"Bring the restored Sigil of Thoradin to Zengu in Hammerfall."}]])
R(642,"被困的公主",[[description="我叫密斯賴爾，我是大地的公主。巨人們俘獲了我，把我拘禁在阿拉希高地的地下深處。這些水晶碎塊是我和外界交流的唯一途徑。$B$B幫幫我。這些巨人的盟友——枯鬚狗頭人——就在東邊的枯鬚峽谷裡活動，那裡有一塊類似水晶碎塊。要啟動那塊水晶，你必須從狗頭人那裡收集到密斯賴爾之塵，然後把它們放在水晶上。$B$B求求你了，$N，幫幫我吧！",objectives={"收集密斯賴爾之塵。$B$B把它們放在枯鬚峽谷中的虹光水晶碎塊上。"}]])
R(643,"阿拉索符印",[[description="Though they can barely be said to control Stromgarde, let alone the whole of Arathi Highlands, the human prince trots the remnants of his cavalry over the countryside. I can't understand why he does it, but who understands the way the humans think, hm?$b$bWhatever his reasoning, more importantly, he has given one of the sigils to Lieutenant Valorcall, their cavalry leader. Locate him and bring his sigil back to me.",objectives={"Retrieve the Sigil of Arathor and return it to Zengu in Hammerfall."}]])
R(644,"托爾貝恩符印",[[description="The final of the sigils needed to unlock the tomb of Thoras Trollbane is held by his son personally. He resides deep within Stromgarde, in a chapel in the militia-held districts. Prince Galen is well protected and no slouch of a warrior himself, so this task could prove most difficult.",objectives={"Kill Prince Galen Trollbane and bring the Sigil of Trollbane to Zengu in Hammerfall."}]])
R(645,"托卡拉爾",[[description="What's this? With the four sigils brought together, they have formed together to create one sigil. There can be no doubt that this will be able to break the wardings placed upon Trollbane's tomb.$b$bTrollbane's remains are entombed in the Sanctum behind the chapel in Stromgarde. Retrieve Trol'kalar.",objectives={"Retrieve Trol'kalar from Trollbane's tomb in Stromgarde."}]])
R(646,"托卡拉爾",[[description="The light slowly fades, the sword Trol'kalar, held within a stone sheath has been released.",objectives={"Deliver Trol'kalar to Zengu in Hammerfall."}]])
R(647,"馬克裏爾的月光酒",[[description="Had quite a bit of the ol' Moonshine last night!  Longbraid would have my head if he knew that I passed out during my watch.$b$bThe noggin hurts something fierce.  Felt as though a whole brigade of siege engines passed overhead, all that rumbling.$b$bOh my, look at the time! I promised Brewmeister Bilger in Southshore that I'd repay my debt to him by sending some Moonshine.$b$bBut there are just 15 minutes left before I'm overdue!  Take him this batch, would you please?  And hurry!",objectives={"Take MacKreel's Moonshine to Brewmeister Bilger in Southshore."}]])
R(648,"拯救OOX-17/TN！",[[description="那個地精的聲音再次從那個機器人中傳了出來：$B$B「我需要你幫忙把OOX-17/TN移動到一個安全的開闊地，這樣它才可以啟動起飛程式。它自帶隱形系統，但是我需要一點時間來遠端啟動這個系統。請你把這個機器人從現在的位置護送到熱砂港去！那裡是個非常理想的起飛點，有足夠的空間作為機器人起飛的跑道！」$B$B「將它護送到那裡，然後再到藏寶海灣來找我！奧格索普·奧布諾提斯——完畢！」",objectives={"將OOX-17/TN護送到熱砂港，然後向藏寶海灣的奧格索普·奧布諾提斯報告。"}]])
R(649,"尋找蜜酒",[[description="I've got some salvage work for you, and if you're an aficionado of fine ripple like I am, then you'll love this task.  Ripple!$B$BIt's a drink, you dummy.$B$BAn abandoned Horde outpost has a stash of Hinterlands Honey Ripple from when they were in business.  You can't get fine ripple like that anymore!  One of Malton's dummy associates knows the shot, so you'll go out there and bring me a case of packaged ripple, and two for my own collection!  Talk to Malton, he'll fill you in on the details.",objectives={"Talk to Malton Droffers in Orgrimmar."}]])
R(650,"尋找蜜酒",[[description="The elf you will need to talk to is Gilveradin Sunchaser.  He can name any wine, vintage and all, just by smell alone!  He can package up the ripple we need, so you'll need to talk with him.  We need six bottles for packaging, two for dad, and how ever many he'll want... and believe me, he'll want some.  When you've packaged the ripple and got dad's two bottles, come back here!$B$BGilveradin's camp is near some high elf lodge in the Hinterlands, and those high elves are not good.  Trust me.",objectives={"Talk to Gilveradin Sunchaser; his camp is located in the Hinterlands."}]])
R(651,"禁錮之石",[[description="在阿拉希高地上散佈著4塊禁錮之石，這些石頭將我牢牢地釘在地下。$B$B要想解除它們，你就必須解除最堅固的那塊：內禁錮之石。首先，你必須搜集到其他三塊石頭的鑰匙。$B$B這些石頭都有守護者在看守，但是如果你足夠聰明或者足夠幸運的話，就能找到消滅這些守衛的辦法。",objectives={"從西禁錮之石、東禁錮之石和外禁錮之石中搜集烈焰鑰匙、海浪鑰匙和雷霆鑰匙。$B$B把它們帶到內禁錮之石處。"}]])
R(652,"打開鑰匙之石",[[description="禁錮之石的開啟基本解開了這些束縛著我的東西，可還有一把牢不可破的鎖讓我無法動彈。你看到這圈石頭中的那塊鑰匙之石了嗎？開鎖的鑰匙在弗茲魯克手中，他是囚禁我的巨人之一，也是這石鎖的看護人。$B$B你必須從弗茲魯克那裡獲得一把名叫「秩序魔棒」的鑰匙來打開鑰匙之石。$B$B你已經為我做了這麼多，$n，只是再幫個微不足道的小忙……我會對你更加感激不盡的！",objectives={"找到並殺死弗茲魯克，然後把秩序魔棒帶到阿拉希高地的鑰匙之石旁。"}]])
R(653,"密斯萊爾的盟友",[[description="<密斯賴爾開始說話。>$B$B自由！我自由了！我終於自由了，我要恢復力量，不過現在我還得躲避那些追捕我的敵人。因為如果他們現在找到我的話，肯定會輕鬆將我降服並重新監禁我。$B$B總有一天我會回到那些巨人的面前，讓他們為禁錮我的行為而後悔！$B$B你是一個高尚的盟友，$N。我會再次需要你的幫助。等我準備好之後，我需要你來將我召喚到地表上。$B$B去和鐵爐堡的葛利·硬骨談談吧，他知道如何召喚我。",objectives={"和鐵爐堡的葛利·硬骨談話。"}]])
R(654,"塔納利斯的樣本",[[description="Activating the power source makes the field testing kit start to glow and vibrate.  It would seem to be working as planned.$B$BAccording to Chief Engineer Bilgewhizzle, you now have two hours to collect the data you need in the Tanaris desert.  If you do not collect it within two hours, all the data will be lost and you will need to buy another power source from him.$B$BReturn to him when you have completed the task.",objectives={"Acquire acceptable samples for 8 basilisks, 8 hyenas, and 8 scorpions.  Bring the testing kit back to Chief Engineer Bilgewhizzle in Gadgetzan before the power source runs out."}]])
R(655,"落錘鎮",[[description="It is still clear to me, like yesterday... So many years without hope, with wood and steel to bind me to this terrible place. Then finally, finally! There was the Warchief. Doomhammer in his midnight plate, his warhammer held high.$b$bIt was... too terrible... That the blow of a coward would strike down our greatest hero. From behind he charged on his horse, and then his lance ran him through... I fell to my knees. What hope was there? What hope is there...",objectives={"Speak with Tor'gan in Hammerfall."}]])
R(656,"召喚大地公主",[[description="你必須在密斯賴爾恢復力量之前打敗她。否則，一旦等到她聚集到足夠的能量，密斯賴爾就會向追捕她的人發起挑戰！有一些人自信能控制住她，但是如果她真能被控制住，巨人們有必要先發制人把她囚禁起來嗎？$B$B這是個瘋狂的邏輯，難道不是嗎？$B$B你必須在第一次和她接觸的密斯賴爾水晶碎塊那裡將她召喚出來，然後打敗她。在打敗她之後搜出她身上的怪異鐐銬，然後與密斯賴爾水晶碎塊縛在一起。$B$B只有這樣做才能再次將密斯賴爾囚禁起來。",objectives={"到密斯賴爾水晶碎塊去召喚她，然後打敗她。$B$B搜出她身上的怪異鐐銬，將其和密斯賴爾水晶碎塊縛在一起。"}]])
R(657,"新的瘟疫？",[[description="<奎艾開始仔細地閱讀這份資料>$B$B這真的很有趣。看起來藥劑師喬瑞爾正在格沙克農場裡進行著一些危險的試驗，很難說這會和希爾斯布萊德有什麼牽連，不過費恩應該不會想見到我們讓這件事繼續下去。$B$B你走了以後，我們看見有一些獸人跑了進來，不過我沒有足夠的實力去幫基恩洛的忙。如果你可以的話，她需要人保護她到農場裡去偷取喬瑞爾那些還沒有送往泰倫磨坊的研究資料。",objectives={"和基恩洛談話。"}]])
R(658,"新的瘟疫？",[[description="是費恩讓你來找我們的吧？我一點都不吃驚，那傢伙總是擔心這個擔心那個的。$B$B我們監視這個農場已經有段時間了，基恩洛說她不久前看到有一個信差從那間小房子裡走出來，往南邊去了。$B$B她平時話有些多，不過在這種危險的地方，我總是相信她的直覺。$B$B嗯……你的追蹤能力怎麼樣？我們認為那個信差可能是帶著信去塔倫米爾了。如果你能弄到那些檔案，就有可能幫助我們搞清楚在希爾斯布萊德所發生的那些怪事。",objectives={"找到被遺忘者信差，把她的密封的信件交給格沙克農場裡的奎艾。"}]])
R(659,"新的瘟疫？",[[description="歡迎你，$N。我帶著一群探險者到這裡來調查最近發生的一些怪事。$B$B我在希爾斯布萊德有個堂兄，他最近殺掉了家養的那只名叫斯坦利的狗，因為這隻狗突然長得很巨大，而且還野蠻地攻擊所有靠近它的人。$B$B我想這一定和亡靈有些關係，我們正在尋找能證明這個猜想的更多證據。$B$B我的兩個同伴奎艾和基恩洛到阿拉希高地上的格沙克農場去了，最近這些天一直沒有她們的消息。你能幫我找到她們嗎？我越來越擔心了……",objectives={"到阿拉希高地上的格沙克農場附近找到奎艾和基恩洛。"}]])
R(660,"新的瘟疫？",[[description="好了，$N。我已經準備好了。$B$B可以出發了嗎？",objectives={"保護基恩洛，直到她回到奎艾身邊。"}]])
R(661,"新的瘟疫？",[[description="就算讓基恩洛在旅店裡睡上一晚，她也不會比現在看起來更健康。你保護她保護得很好。$B$B她從農場拿回來的這些東西，至少能讓費恩瞭解到在阿拉希高地究竟發生了些什麼。為了確保你們的行動不會導致任何報復行動，我們會在這裡繼續留守一段時間。你願意返回南海鎮去和費恩談談嗎？",objectives={"到南海鎮去找費恩·奧德利克。"}]])
R(662,"深海打撈",[[description="O'Breen led the ships into the cove.  We were certain this is where the treasure could be found.  The Harbinger docked safely but as the Maiden's Folly and Spirit of Silverpine approached the tides began to lower.  Strangest thing I've ever seen!$b$bThose two ships ran aground into something... some sort of temple in the reef.  They sank so quickly, was quite a tragedy.$b$bWe need to retrieve their Logs as well as their Charts before we leave.  We can't leave that information behind for prying eyes!",objectives={"First Mate Nilzlix wants you to retrieve the Charts and Logs from the Maiden's Folly and the Spirit of Silverpine."}]])
R(663,"法迪爾海灣",[[description="魯魯看見了一個小$r！魯魯總是待在哨所上！$b$b歡迎來到法迪爾海灣。奧布裡船長說過，我們在這裡待不了多久。我們只要搜集寶藏然後返回藏寶海灣就行了。$b$b但是魯魯認為我們要在這兒待很長很長的時間，我們失去了兩艘船。可憐的銀松之魂號和處女號！她們長眠在海底！$b$b魯魯說，如果你想在這逗留的話，就去和奧布裡船長談談吧。",objectives={"和法迪爾海灣的奧布裡船長交談。"}]])
R(664,"船長的復仇",[[description="Argh, 'tis a horrible life. I should be in a watery grave right now, not sittin' here by the fire, breathin' fresh air.$b$bThe crew tried so hard to save my beautiful Maiden's Folly. Bless the boys, bless their hearts.$b$bO'Breen made it to shore safely but we weren't so lucky. The seas just sank on us, I swear.$b$bOne second we're afloat and the next water is rushin' in. And those beasts! Killed all the survivors. Horrible naga scum. I went black and ended up here, saved.$b$bI want those beasts dead.",objectives={"Captain Steelgut in Faldir's Cove wants you to kill 10 Daggerspine Raiders and 3 Daggerspine Sorceresses."}]])
R(665,"水下寶藏",[[description="Now that we are full-fledged Blackwater Raiders it is our job to help Mr. O'Breen locate the lost elven treasure.$b$bIt is next to impossible to find the gems in the dark sea without aid. The doctor has constructed some goggles that will help. He needs the goggles charged with the energy derived from the enchanted stone in the cave just up the hill.$b$bBut the cave is cursed! When we get close, we get ambushed. Defend me and I can harness the energy from the stone into the goggles.",objectives={"Escort Professor Phizzlethorpe to the cave and back."}]])
R(666,"水下寶藏",[[description="The treasure has been on the sea floor so long that the gems have calcified into thick stone. But the power harnessed in these goggles will allow you to locate them easily.$b$bA little gnomish ingenuity goes a long way!$b$bSo borrow the Goggles of Gem Hunting, $n, and see if you can collect some of the lost treasure for Captain O'Breen.$b$bI'd swim down there myself but...um...well, I have important scientific business to tend to up on the safe, dry land....er, yeah.",objectives={"Doctor Draxlegauge in Faldir's Cove wants you to collect 10 Elven Gems and return the Goggles of Gem Hunting once you are done."}]])
R(667,"水下伏兵",[[description="This is bad. It seems the Daggerspines are amassing for an attack.$b$bNaga are known for their ruthlessness in battle. They will keep attacking until I am dead.$b$bI don't value my own life above that of my crew members, but you must help to defend me. The crew will not be able to make it back to Booty Bay without my knowledge of the seas.$b$bThe naga will be coming from the sea. I need you to remain up here with me to fend off the attack. Man the cannon and drive them back.$b$bAre you ready, $n?",objectives={"Protect Shakes O'Breen during the attack."}]])
R(668,"水下寶藏",[[description="Let's not leave Captain O'Breen waiting. He'll want to see these gems first hand. After all, that's why we're here!$b$bAnd after a few weeks of consorting with these pirates, the professor and I have realized the last thing that's good for our health is to be caught hanging on to their treasure.$b$bHere, $n, take these to O'Breen.",objectives={"Take the Elven Gems to Captain O'Breen."}]])
R(669,"水下寶藏",[[description="Fleet Master Seahorn will want to hear about our find at once.$b$bBut as you can see, we're not in much of a position to get out of here. Not only is the tide too low, but those damned creatures we disrupted are keeping a close eye on our movements.$b$bYou can be of great service to the Blackwater Raiders if you can get word to Fleet Master Seahorn in Booty Bay that we discovered the treasure and are working on extracting more.  Take him this sample as proof.",objectives={"Take the Sample Elven Gem to Fleet Master Seahorn in Booty Bay."}]])
R(670,"水下寶藏",[[description="Say, $n, you seem to be an adventurous type. My fleet is stuck in Booty Bay until we can restock.$b$bThere are some heavy things brewing here and abroad and I need to get some top secret correspondence to Shakes O'Breen who is tied up off the Arathi coast.$b$bCan I trust you to deliver this message safely and in confidence?",objectives={"Deliver Seahorn's Letter to Shakes O'Breen in Arathi Highlands."}]])
R(671,"邪惡的魔法",[[description="I have felt a strangeness in the air... a feeling that simmers in my blood. I had my suspicions. I set off to find the source of my unease and discovered to the west, at Northfold Manor, the residual traces of demonic summoning. As I got close, my blood began to boil and the rage within me grew.$b$bOn the ground I spied an amulet of bloodstone, used to assist in demonic summoning. The one I found was depleted, however. I'll need another to examine, but I dare not return to the manor. Can you bring me some?",objectives={"Get 10 Bloodstone Amulets for Tor'gan in Hammerfall."}]])
R(672,"振奮精神",[[description="We tried to settle him in, cheer him up, telling him stories of our mighty city at Orgrimmar in Kalimdor, but nothing would move him.$b$bTales of our young Warchief, Thrall, who bears the armor and hammer of Orgrim... but, perhaps... Perhaps! A demonstration of our newly found shamanistic magic would give him new hope. It is worth a try!$b$bA small object we could make for him, yes... Bring me some raptor eyes, and I will see what I can do.",objectives={"Acquire 10 Highland Raptor Eyes from Highland Striders and Highland Thrashers for Tor'gan in Hammerfall."}]])
R(673,"邪惡的魔法",[[description="There is no doubt in my mind that a powerful warlock resides within the walls of Stromgarde. From time to time, using an arcane magical relic, this warlock has summoned forth terrible demons in large numbers. We must remove the source of his energy.$b$bFind the warlock and kill him. Bring me whatever magical object you find on his person, and I will take steps to destroy it and see that its power is not used to taint this land any longer.",objectives={"Retrieve Marez Cowl's Bloodstone Orb and bring it to Tor'gan in Hammerfall."}]])
R(674,"振奮精神",[[description="Here, take this amulet to Gor'mul, and see if the raptors' strength can awaken the flame of the warrior that once burned through his veins.",objectives={"Give the Raptor Talon Amulet to Gor'mul."}]])
R(675,"振奮精神",[[description="<Gor'mul tosses the amulet into the ground.>$b$bTor'gan sent you, didn't he? Pah! Why he feels some mercy towards me I would not understand. Mercy was denied me when I was not allowed to die with my Warchief in battle. A cruel blow fate has dealt me...",objectives={"Speak with Tor'gan."}]])
R(676,"落錘之戰",[[description="Weaklings... all of them. You, $c, what are you looking at? Think you're something special, huh? Why not prove it?$B$BThe Hammerfall outpost in Arathi's under attack. Unless we send them help soon, their demise is imminent.$B$BBut before you go rushing off, you may want to test your skills first. Northeast of Stromgarde in Arathi is an ogre mound inhabited by the Boulderfist tribe. When you can handle the ogres and enforcers there, then report to Drum Fel in Hammerfall.",objectives={"Kill 8 Boulderfist Ogres and 10 Boulderfist Enforcers, then find Drum Fel in the Hammerfall outpost in Arathi Highlands."}]])
R(677,"短兵相接",[[description="枯木食人妖和阿拉希的石拳巨魔聯合起來，要把我們趕出這片土地，但我們決不會把命運交給他們掌控！我們要除掉他們，讓他們知道誰是這兒真正的主宰。$B$B食人妖背棄了我們，巨魔想要把我們當作美味的食物——我們決不能允許這種事情發生。$B$B現在，讓我們從南邊的枯木食人妖開始吧。去殺掉他們，讓他們血流成河！",objectives={"殺死10名枯木擲斧者、10名枯木獵頭者和8個枯木巫醫，然後回到落錘村哨所的杜拉姆法爾那裡。"}]])
R(678,"短兵相接",[[description="$N，你的強大已經是有目共睹的了。現在讓我們看看你如何去面對一個真正的敵人。$B$B從這裡往西南走，在通往矮人修建的那座大橋的途中，有一個石拳巨魔的老巢。如果我沒搞錯的話，那兒的虐待者和法師對你來說應該是個難度不小的挑戰——至少到現在為止對於我們來說是這樣的。$B$B盡可能多地殺死他們，無論最終是勝利還是失敗，無論回來見我的是你自己還是你的靈魂，我都會讚賞你在戰鬥表現出的堅韌精神。",objectives={"殺死10個石拳蠻兵和4個石拳法師，然後向落錘村哨所的杜拉姆法爾覆命。"}]])
R(679,"短兵相接",[[description="The head of the beast is ready to be taken off... with great force, $N. You have shown every sign that you are able to help us with this final mighty blow. The leaders of these attacks have made their lair within the ruins of Stromgarde, a glaring symbol of human frailty.$B$BFind and slay those Boulderfist lords and their lackey shaman who would try and drive us from these lands.",objectives={"Kill 15 Boulderfist Shaman and 10 Boulderfist Lords and return to Drum Fel in the Hammerfall outpost."}]])
R(680,"真正的威脅",[[description="You serve my husband well, $c, but he does not know why Hammerfall is under attack.$B$BOr'Kalar, Mug'thol's pawn in Stromgarde, has an intense hatred for my husband, and wishes nothing more than my husband's death for defeating him years ago.$B$BMy auguries tell me that Or'Kalar has laid a trap for my husband, so I have hidden signs of the ogre's presence from him.$B$BMy husband will rush off foolishly if he learns of the ogre's whereabouts and I would ask for your help in slaying the creature.",objectives={"Slay Or'Kalar and bring his Head to Korin Fel in the Hammerfall outpost."}]])
R(681,"諾斯弗德農場",[[description="我們正在為激流堡而戰，然而我們卻逐漸落入下風。我們、巨魔以及辛迪加分別控制著這座城市的一部分，現在我們這三方勢力陷入了整日互相征戰卻毫無突破的僵局。$B$B然而，當敵人們力量開始逐漸增強的時候，我們卻在慢慢地變弱。$B$B我們需要南海鎮的援助，但是辛迪加控制了我們和南海鎮之間的領地，因此那邊的補給很難運到這裡來。$B$B到辛迪加在諾斯弗德農場的基地去幹掉他們，也許這樣做能讓我們補給線上的壓力大大減輕，然後才能有更多的物資平安運抵這裡。",objectives={"殺掉6個辛迪加雇傭兵和10個辛迪加路霸，然後回到避難谷地去向尼艾絲隊長覆命。"}]])
R(682,"激流堡徽章",[[description="我們的民兵分隊正在和控制著激流堡的辛迪加成員激戰。為了刺激他們那群烏合之眾與我們作戰，辛迪加的頭目們使出了重金懸賞的手段，只要有人能殺死我們的民兵，並從他們身上繳獲激流堡徽章，辛迪加都會給予獎勵。$B$B我們必須奪回那些徽章——決不能讓劊子手們用我們的戰士的性命來換取金錢！$B$B到激流堡城內的辛迪加控制區去殺掉那些歹徒，取回我們的徽章。",objectives={"把激流堡徽章交給位於避難谷地的尼艾絲隊長。"}]])
R(683,"薩拉·巴魯的請求",[[description="$n，我對你有個小小的請求。$b$b這張字條是我寫給我們鐵爐堡的偉大統治者麥格尼·銅鬚國王的。對於你這種曾為聯盟英勇作戰的$r來說，這實在是個小任務。$b$b以我現在這種悲傷的樣子去覲見國王陛下可能無法符合我的目的，我相信你應該可以理解。",objectives={"把薩拉·巴魯的字條交給鐵爐堡的國王麥格尼·銅鬚。"}]])
R(684,"通緝：瑪雷茲·考爾",[[description="重金懸賞瑪雷茲·考爾的項上人頭。這個獸人是辛迪加組織的高級顧問和技工，人們最後一次看見她是在激流堡內的辛迪加控制區。$B$B賞金請到尼艾絲隊長處領取。$B$B請注意：瑪雷茲是一個強大而狡猾的術士，她和惡魔有著非常密切的聯繫。追殺她時務必非常小心。",objectives={"把瑪雷茲的頭顱交給避難谷地的尼艾絲隊長。"}]])
R(685,"通緝：奧圖和法庫雷斯特",[[description="激流堡民兵團重金懸賞法庫雷斯特公爵和他的保鏢奧圖的頭顱。法庫雷斯特是辛迪加在阿拉希地區的主要領導者，他的死將使該組織在這一地區的活動陷入癱瘓。$B$B他的保鏢奧圖不是我們的戰略目標，但他生性兇殘，已經殺死了許多激流堡的士兵。$B$B賞金請到尼艾絲隊長處領取。",objectives={"把法庫雷斯特和奧圖的頭顱交給避難谷地的尼艾絲隊長。"}]])
R(686,"國王的禮物",[[description="當你在和那些龍喉氏族的獸人作戰時，我們又獲得更多有關他們的作戰計畫情報。$B$B首先是一個壞消息，納克羅什正在大量地建造投石車，計畫一舉攻陷米奈希爾！還有一個好消息，經過在丹奧加茲一帶的艱苦奮戰，我們已經把他們的援軍徹底擋了回去！$B$B現在你所要做的就是毀掉那些投石車，它們目前仍被停放在龍喉氏族的營地裡。$B$B拿著，帶上這些火絨。你得先在營地裡殺出一條血路，找到那些投石車，然後再用這些火絨燒了它們。$B$B完成這一切之後，就去找納克羅什，把他給幹掉。我們必須徹底地將這些龍喉氏族的獸人消滅掉！",objectives={"國王麥格尼·銅鬚讓你去和大石匠瑪布勒斯坦談話。"}]])
R(687,"迷失者塞爾杜林",[[description="迷失者塞爾杜林曾經是我們暮光之錘的一員。但是有一天他突然精神失常，摒棄了我們的信條，背叛了我們的信仰。在背離我們之前，他還偷走了密斯賴爾卷軸！我們沒能抓到他，但有傳言說他就躲藏在荒蕪之地中，整日胡言亂語，已經完全瘋掉了。$B$B如果你要將公主帶回來的話，就必須找到卷軸，而要找到卷軸，你就必須找到塞爾杜林。",objectives={"找到迷失者塞爾杜林。"}]])
R(688,"密斯萊爾的盟友",[[description="<Myzrael speaks.>$B$BFree!  I AM FREE!  I am free to gather strength, hidden from my captors.  For if they faced me now they would surely overpower and again imprison me.$B$BBut in time I will confront the giants, and they will regret their wardship of me!$B$BYou are a noble ally, $N.  I will need your help again in time.  When I am ready, I will need you to summon me to the surface$B$BSpeak with Zaruk in Hammerfall.  He knows how I can be summoned.",objectives={"Speak with Zaruk in Hammerfall."}]])
R(689,"國王的禮物",[[description="我們的國王要建一座紀念碑向一個叫蘇利·巴魯的士兵致敬？你是說那個可憐的士兵是在薩多爾大橋的悲劇中死的？$b$b唉，艾澤拉斯還會有和平嗎？$b$b不管怎樣，國王下達的任務就是第一要務。我要用最好的石頭來建這座紀念碑，你到希爾斯布萊德的丘陵洞穴為我找一些奧特蘭克花崗岩來吧。",objectives={"鐵爐堡的大石匠瑪布勒斯坦要5塊奧特蘭克花崗岩。"}]])
R(690,"馬林的要求",[[description="你好，$N。我看出你是個渴望冒險的$c，現在我有項任務需要你的幫助。$B$B我原來的主人，大法師特雷萊恩，不久從位於阿拉希高地的激流堡裡逃了出來。他讓我到那裡去幫他取回一些臨走時落下的物品。$B$B激流堡現在已經陷入了重圍之中，他在努力保衛阿拉索之塔，但是現在看來情況越來越危險了。我的人已經到了阿拉希高地，但他們需要更多的支援。你有興趣去幫忙嗎？",objectives={"找到位於阿拉希高地上的避難谷地中的斯奎爾圖。"}]])
R(691,"證明實力",[[description="$N，別怕斯奎爾圖。他是因為事情太多才變得這麼暴躁。在我們等他完成偵察任務的時候，為什麼不做些更有意義的事情呢？馬林派我到這裡來為他收集一些試劑，對於如何收集這些物品，我感到很困惑。不過現在你來了，我想我的問題也解決了。$B$B我需要這些東西：枯木食人妖的獠牙，枯木食人妖的醫藥包和一把暗影獵手的小刀。$B$B你能幫我找到這些嗎？枯木食人妖一般都在阿拉希高地的東南一帶出沒。",objectives={"幫避難谷地中的學徒克里汀收集10個枯木食人妖的獠牙，4個枯木食人妖的醫藥包和1把暗影獵手的小刀。"}]])
R(692,"遺失的卷軸碎片",[[description="密……密斯賴爾卷軸？！你要那東西幹什麼？它強大的魔法力量可以把密斯賴爾召喚到地面上來，那時候我們就有大麻煩了！$B$B也許……也許已經太遲了，也許她已經自由了。密斯賴爾可能正在為報復我們而聚集力量。如果是這樣，那你就必須掌握著這至關重要的卷軸！$B$B……太糟了，它被毀掉了。憤怒的元素生物偷走了卷軸，並將它撕成了碎片。現在它們又在為這些碎片爭鬥不休。$B$B如果你能搜集那些碎片的話，也許我們還有希望將它修復成原來的樣子……",objectives={"把破損的卷軸碎片、弄皺的卷軸碎片和燒焦的卷軸碎片帶給迷失者塞爾杜林。"}]])
R(693,"特雷萊恩的符咒魔杖",[[description="你好啊，$N，很抱歉我以前對你那麼凶……我可以斷定特雷萊恩的第一件寶物的所在：它在石拳大廳的考格雷什手裡。順便說一句，他已經可以使用冰爆術來教訓不聽話的手下，看來離他完全掌握魔杖力量的日子也已經不遠了。$B$B石拳大廳就在這裡的南邊，薩多爾大橋的東邊。從那個巨魔手裡把那根魔杖拿回來吧。$B$B在你回來之前，我要想想我們要怎樣解決激流堡的問題。",objectives={"幫避難谷地的斯奎爾圖找到特雷萊恩的符咒魔杖，並把它帶回來。"}]])
R(694,"特雷萊恩的防禦",[[description="休息好了嗎？$B$B我們的下一步計畫和激流堡的阿拉索之塔周圍的巨魔有關。我們必須首先開啟這座塔的防禦系統，當然，前提是你能活著到達存放那些物品的地方。為此，首先我們需要一些石拳薩滿經常攜帶著的寶石。他們把寶石從塔裡帶了出來，但他們沒有什麼機會佔有這些寶石了。$B$B從他們那裡弄一塊寶石，把它送去給克里汀——他能夠給寶石附魔，這樣一來，寶石就可以當鑰匙用了。",objectives={"找到一塊碧藍瑪瑙石，把它交給避難谷地處的學徒克里汀。"}]])
R(695,"學徒的魔法",[[description="Here you are, $N. The gem only needs to be pressed against one of the pedestals near the base of the tower to activate its defenses. Use it when you're ready to enter the tower and find Trelane's remaining items. $B$BGood luck to you. I'll be awaiting your return here at the camp. Oh, and speak to Skuerto before you leave. He'll give you the rest of the details you'll need.",objectives={"Speak to Skuerto."}]])
R(696,"進攻高塔",[[description="Here's what your lookin' for: Trelane's phylactery, Trelane's orb, an' Trelane's ember agate.$B$BAll three should be in chests within the tower an' you shouldn't have a problem opening the chests on your own; you just have to be careful of the ogres.$B$BThe tower's defenses won't take care of 'em on their own; you'll need to have your weapons at the ready. Those ogres find out you're there and stealing from 'em, an' they'll be sure to put the hurt on you.$B$BBe careful, an' good luck.",objectives={"Find Trelane's Phylactery, Trelane's Orb, and Trelane's Ember Agate, and return them to Skuerto at Refuge Pointe."}]])
R(697,"馬林的要求",[[description="Take this letter back to Stormwind and let Malin know that Kryten an' I'll be home soon. He'll reward you well for helping us here, $N, of that I've no doubt.$B$BTravel safely.",objectives={"Take the Sealed Letter to Archmage Malin in the Mage Quarter of Stormwind."}]])
R(698,"缺乏補給",[[description="I'm working on getting some supplies together for our outpost near the beach to the east--Tok'kar does what he can, but between shifts of guard duty and cooking for his soldiers there's not much time left in the day.$B$BThey do enjoy cooking up some sawtooth meat when they can, but I haven't had time to get them another shipment. Would you mind helping them out?$B$BThe young sawtooths aren't as tasty as the older ones, so stay clear of those; give them a year or two to get to full size.",objectives={"Bring 8 Unprepared Sawtooth Flanks to Tok'Kar in Swamp of Sorrows."}]])
R(699,"缺乏補給",[[description="With the threat of murlocs along the coast, we're stationed out here to protect--or warn if the force is too large--of any coming threats to Stonard. It doesn't give us much time for relaxation, and we could use some more help if you're able.$B$BThe sawtooth snappers' claws make for fine weapons when properly prepared. Bring me some of their claws and I'll see you're rewarded with one of our weapons in thanks for the fresh meat and the good company.",objectives={"Bring 6 Sawtooth Snapper Claws to Tok'Kar in the Swamp of Sorrows."}]])
R(700,"國王的禮物",[[description="啊，羅德隆的石頭真不賴，可惜那兒已經變成一片廢墟了。$b$b紀念碑完成了！我想國王陛下一定會滿意的。$b$b如果你願意的話，請替我去告訴國王陛下，紀念碑已經完成了。",objectives={"向鐵爐堡的國王麥格尼·銅鬚彙報。"}]])
R(701,"迅猛龍的狡詐",[[description="只要借助一些特別的物品，我就能創造出一件注入了迅猛龍的狡詐力量的東西！這樣就應該能讓戈莫爾瞭解到我們新的能量，並重新找回潛藏著的勇士的力量！$b$b我需要迅猛龍的心臟來完成這件物品和法書。",objectives={"從高地獵獸龍身上獲取12顆迅猛龍的心臟，把它們交給托爾甘。"}]])
R(702,"迅猛龍的狡詐",[[description="Take this orb and use its energy to give Gor'mul the essence of the raptor. Surely this will invigorate his spirit and give him new purpose in life. With him returned to normal, we can explain to him the current state of the Horde, and we will have a great warrior's assistance in our unceasing battles.",objectives={"Give Tor'gan's Orb to Gor'mul."}]])
R(703,"燒烤禿鷹翅膀",[[description="哦，當然，燒烤禿鷹翅膀是我的最愛！醬汁濃郁，肉香撲鼻，香味能把數公里外饑餓的野獸都給吸引過來！$B$B我有能做一頓美味佳餚的一切原料，呃……還差點禿鷲翅膀！$B$B如果你想嘗嘗我的手藝，就去幫我弄些禿鷲翅膀來。儘量多弄點，沒准我一高興就把烹飪方法一併教給你！",objectives={"給里格弗茲帶去4只禿鷲的翅膀。"}]])
R(704,"阿戈莫德的命運",[[description="The last report I received from Agmond is troubling, more so now that he's dead!  He mentioned that his diggers uncovered \"ancient urns\" at the dig site outside Uldaman.  I fear that the urns he found at that site incited the troggs, just as did the idols I found here.$B$BI need you to get those urns for our studies.  Go to the Uldaman site, gather the urns, then return to me.",objectives={"Bring 4 Carved Stone Urns to Prospector Ironband in Loch Modan."}]])
R(705,"潛水采珍珠",[[description="荒蕪之地是一個無比荒涼的地方，是兇殘的捕食者和食腐動物的樂園。這裡的一切都令人感到恐慌，尤其是對於我這樣的小個子哥布林來說。為了生存，我不得不機靈些！$B$B我知道閃光彈的製作方法，也常用它來嚇走野獸。不過，作為原料之一的藍珍珠粉快要用完了。你能不能幫我找些藍珍珠回來？當然我會給你足夠的報酬。$B$B呵呵，這個東西並不是那麼好找的，恐怕你得走不少的路了。我所需要的藍珍珠可以在暗礁海的牡蠣身上找到。$B$B對，就是位於荊棘谷的那個暗礁海。",objectives={"收集9枚藍珍珠，把它們交給荒蕪之地的里格弗茲。"}]])
R(706,"黑龍之火",[[description="作為費拉諾·鋼趾的學徒，我從他那裡學會了賦予武器強力魔法的特殊技能。我最後一次聽到他的消息時，他正和從羅德隆過來的狩獵小隊合夥工作。$b$b我不能告訴你關於這種技術的太多細節，但可以告訴你必須要用黑龍血來完成這個附魔過程， 而且一定要是從黑色幼龍那仍在跳動的心臟中湧出的血液。我現在除了等待鐵爐堡的消息以外無事可做，所以如果你能從萊瑟羅峽谷幫我帶一顆黑色幼龍之心回來，我就向你展示一下我的技術！",objectives={"為西格魯·鐵斧拿到一顆黑色幼龍之心。"}]])
R(707,"鐵環挖掘場需要妳！",[[description="$N。洛克莫丹的勘察員基恩薩·鐵環從他的挖掘場給我送來報告，說是需要為我們的另一項挖掘計畫外出搜集一些情報。$B$B我就知道這麼多了，如果你願意活動一下筋骨，就去和基恩薩·鐵環談談吧。",objectives={"和洛克莫丹鐵環挖掘場的勘察員基恩薩·鐵環談話。"}]])
R(708,"黑盒子",[[description="這個黑色金屬箱的表面已經被嚴重破壞，似乎在酸液中浸泡過——它一定在那隻巨型禿鷲的肚子裡待了很長的時間。$B$B翻轉過箱子之後，你發現箱底印著一個標記，標記下是一行字：$B$B「19號坦克 - 鐵爐堡攻城坦克旅」",objectives={"把這個黑盒子帶到鐵爐堡的軍事大廳去。"}]])
R(709,"化解災難",[[description="天哪……天哪！厄運就要降臨了。它已經朝我而來了！厄運就要降臨了！$B$B不，我不能說……不能說出他們的名字，否則會被他們聽到的！但是，如果我們……如果我們對他們有更多瞭解的話……也許我們就可以知道如何擊敗他們！$B$B也許……$B$B到奧達曼去。不！我說過！你必須找到……找到雷烏納石板……對，找到它！別讓我再提到那個名字！$B$B它深藏在那裡，就在一個古代的箱子裡……這個箱子甚至比矮人族群的年代還要久遠……",objectives={"把雷烏納石板帶給迷失者塞爾杜林。"}]])
R(710,"研究石元素",[[description="在荒蕪之地，我停下了所有手頭的事情來專注於我的最新項目：元素禁錮鐐銬。$B$B這些鐐銬一旦完成，就可以讓法師們在更廣的範圍內召集更加強大的元素生物。首先，我需要些小石頭碎塊，來檢驗我最新的攻擊性咒語和小發明。$B$B你可以從西面那裡的次級石元素身上收集到這些碎片，能給我弄一些來嗎？",objectives={"收集10塊小石頭碎塊，把它們交給荒蕪之地的魯特維爾·沃拉圖斯。"}]])
R(711,"研究石元素",[[description="$N, you've already proven more able than all my apprentices combined.$B$BThe next parts I need require a little more strength. Large stone slabs can be found on rock elementals if you're careful enough. Their bodies are stronger and larger, and therefore more prone to having pieces large enough for my tests. You can find them further west of here or southeast along the mountains' edges.$B$BTake your time; I'll need a while to test these smaller pieces you brought me.",objectives={"Bring 3 Large Stone Slabs to Lotwil Veriatus in the Badlands."}]])
R(712,"研究石元素",[[description="$N, there's one more part I need from the elementals here in the Badlands: the bracers of rock binding from the greater rock elementals. By my calculations, those bracers should be enough to gauge the strength of my own shackles.$B$BMy attempts at scrying the greater rock elementals showed a group of them southwest of here, near some ogres if I recall.$B$BBring me 5 of their bracers just so I have extras. Servo's notorious for misplacing my reagents and research.",objectives={"Bring 5 Bracers of Rock Binding to Lotwil Veriatus in the Badlands."}]])
R(713,"至關重要的冷卻劑",[[description="讓我來告訴你一些有關冰霜之油的事情吧：沒有別的什麼東西能夠像它一樣防止發動機或者齒輪過熱。$B$B它的冷卻性能和潤滑效果無與倫比。不僅如此，它還有助於保存附著在魔法物品上的魔力。$B$B我需要一小瓶冰霜之油以加強鐐銬的魔力，好讓它們足夠強大，不然我可沒法阻止那些被召喚來的「朋友們」對我們大開殺戒。$B$B我在奧特蘭克有一個名叫布洛金的哥布林朋友，他能教你製取冰霜之油的方法。",objectives={"找到冰霜之油，把它交給荒蕪之地的魯特維爾·沃拉圖斯。"}]])
R(714,"發條式什麽什麽儀",[[description="$N, you've done your job well beyond all standards.$B$B<Lotwil's obviously distracted by his work.>$B$BIf we ever meet in Kharanos, feel free to come apply for work.$B$BWhoops! Quick, grab the... yes, that. Thanks.$B$BNow I just need one more thing. It's a small part, but rather crucial, I'm afraid: a gyrochronatom.$B$BIf you could just go grab one and bring it to me, I should be ready to complete this.",objectives={"Bring a Gyrochronatom to Lotwil Veriatus in the Badlands."}]])
R(715,"盧希恩的藥水",[[description="我想你為魯特維爾找的那些東西會不會給我們帶來什麼麻煩，$N。另一方面，你已經在幫助魯特維爾神聖的科學研究的過程中體現了超凡的才能，那麼幫幫我如何？$B$B我需要一瓶隱形藥水和一瓶治療藥水。如果他的進展一切順利，這兩件東西都必須及時到位。$B$B作為報酬，我會給你這個配方，它是我向魯特維爾求學時，在魯特維爾長期以來在荒蕪之地的研究成果的基礎上開發出來的。",objectives={"為荒蕪之地的盧希恩·槍穗找到一瓶隱形藥水和一瓶治療藥水。"}]])
R(716,"有備無患",[[description="I know how cheap Lotwil can be, $N, so let me make you something for all your troubles. Maybe it'll even help protect you from the coming atrocity that is Lotwil's newest invention.$B$BI've been working with all the extra stones you collected for him, and I can make some nice bracers that you might want to use. They're enchanted, of course.$B$BI'll just need patterned bronze bracers crafted by a blacksmith so I can complete the bracers I'm making for you.",objectives={"Bring some Patterned Bronze Bracers to Lucien Tosselwrench in the Badlands."}]])
R(717,"大地的震顫",[[description="顯然，我們不能保證黑龍布萊克拉席和赫瑪圖斯仍能被囚禁在萊瑟羅峽谷裡。大批黑龍盤踞在那裡的現狀以及巨魔試圖偷走大地印章的事實說明後面將會有更可怕的事情發生。$b$b黑龍的監獄由三塊符石維持著，只有使用大地印章才能得到它們，而那些符石就是打破封印的關鍵。$b$b$n……我們要確保那些黑龍的夢想永遠無法成真。",objectives={"用大地印章啟動鑽石柱、瑪瑙石柱和紫水晶石柱並拿到三顆符石。$b$b把符石放在大地封印上，釋放黑龍布萊克拉席和赫瑪圖斯。$b$b殺了這兩條黑龍，把布萊克拉席的鎖鏈、赫瑪圖斯的鎖鏈和大地印章交給加瑞克。"}]])
R(718,"饑腸轆轆",[[description="在匆忙撤出奧達曼挖掘場的途中，我們不得不丟棄了很多補給物資，那些考什營地裡的巨魔像兀鷲看見了腐爛的屍體一樣瘋狂地掠奪我們扔掉的物資，呃，那些傢伙聞起來也和曬了好幾天的屍體沒什麼區別……$b$b不管怎麼說，他們搶走了我們裝著武器的馬車，而且現在……現在的狀況實在是只能用窘迫兩個字來形容了——我們現在幾乎什麼吃的都找不到了。$b$b就連醃菜也要吃光了，你看……能不能幫我們弄點什麼吃的來？",objectives={"幫西格魯·鐵斧找回補給箱。"}]])
R(719,"矮人的工具",[[description="你好，$c。千萬要小心四周。這裡到處都是黑鐵矮人，似乎都是屬於暗爐部族的。$B$B他們剛剛襲擊了我們的挖掘場……殺死了那裡幾乎所有的人，包括我的老闆鐵趾格雷茲，只有我僥倖逃了出來。$B$B挖掘場在這裡的北面，我想找回我們的一些物資，尤其是我的好運鋤。$B$B你能幫幫我嗎？如果找不到其他的，至少幫我找回我的鋤頭吧。",objectives={"找到雷杜爾的好運鋤，把它交給鐵趾挖掘場南邊的勘察員雷杜爾。"}]])
R(720,"壹線希望",[[description="<在地圖上有一行用粉筆潦草寫下的文字。>$B$B「雷杜爾，$B他們把我帶到了奧達曼，請速來救援。$B——鐵趾」",objectives={"找到勘察員雷杜爾，告訴他鐵趾格雷茲還活著。"}]])
R(721,"壹線希望",[[description="$N, can ye find him? Can you find Hammertoe in Uldaman?$B$BIf those dirty Shadowforge are holdin' him hostage to figure out what he knows about the titan excavations, then all of Ironforge could be in huge trouble.$B$BFor a long time now those Dark Irons have been lookin' for magics to make more powerful golems. Hammertoe was doin' the same, of course, but only to stop them.$B$BThey're probably keepin' him alive until they learn what he knows.Ye've got to hurry if you're gonna save him!",objectives={"Find Hammertoe Grez in Uldaman."}]])
R(722,"鐵趾的護符",[[description="Ye're brave... <cough>... to come into Uldaman fer me, $c.$B$BIf ye're really here to help... ol' Hammertoe, then... <cough>... you'll need to find... me amulet.$B$BDeepshadow's got it... Magregan Deepshadow. He's 'round here... in the ruins fer sure. That amulet'll lead 'em... <cough>...  right to the scrolls if he ain't stopped. It's up to you, $N. Please... get that amulet.$B$BThe scrolls will surely help the Dark Irons create even more powerful golems. I just know it. I can feel it in me bones.",objectives={"Find Hammertoe's Amulet and return it to him in Uldaman."}]])
R(723,"鐵趾的遺願",[[description="<Hammertoe holds his wounds and takes a moment to regain his composure before speaking again.>$B$BFind Ryedol, $N. Bring 'im me amulet. <cough cough> He'll... <cough> figure out what to do. He knows I was seeking the origins of our people, and he... <cough>... knows it was also my mission to stop the Shadowforge clan. They must not be allowed to find the scrolls... <cough>",objectives={"Take Hammertoe's Amulet to Prospector Ryedol in the Badlands."}]])
R(724,"鐵趾的遺願",[[description="Okay, okay... who would know what to do?$B$BHistorian Karnik! That's it!$B$BHe's in Ironforge. He'll be able to help. He and Hammertoe were workin' together to find the lost artifacts in Uldaman.$B$BGuess the Shadowforge found out the two of them knew more than they were lettin' on.$B$BTell Karnik what's happened to Hammertoe and give him the amulet--he'll tell you what needs to be done next.",objectives={"Take Hammertoe's Amulet to Historian Karnik in Ironforge."}]])
R(725,"亡者的警告",[[description="$N, run and find Advisor Belgrum as quickly as you can. Tell him what you've witnessed and ask him how he wants us to proceed. This note will explain more to him.$B$BIn the meantime, I will take the time to speak to Hammertoe's spirit. Maybe he knows something that will help us put a stop to those Shadowforge cretins' activities in the Badlands. We can only pray.",objectives={"Find Advisor Belgrum and give him his note."}]])
R(726,"亡者的警告",[[description="<Advisor Belgrum reaches the end of the note, and his eyes widen for a moment.>$B$BOch, these are evil tidings.$B$B$N, please return to Historian Karnik and tell him on the king's authority to act on this information swiftly and decisively. He must halt the Shadowforge's activities in the Badlands.",objectives={"Speak to Historian Karnik."}]])
R(727,"遠赴鐵爐堡",[[description="The Tablet tells much.  But not enough!  Not nearly enough!$B$BThere is a book, a digest that Yagyin wrote in ages past.  The ... people I fled ... they keep this book in many places.  And their most learned study it.  It holds vast knowledge.  Knowledge to protect us!$B$BGo to Gerrig Bonegrip.  He is in a shop in Ironforge, in the Forlorn Cavern.  Show him this sigil and he'll think you one of them.  Ask him for Yagyin's Digest ... and bring it to me!",objectives={"Give the Sigil of the Hammer to Gerrig Bonegrip in the Forlorn Cavern of Ironforge."}]])
R(728,"遠赴幽暗城",[[description="The tablet tells much.  But not enough!  Not nearly enough!$B$BThere is a book, a digest that Yagyin wrote in ages past.  The... people I fled from... they keep this book in many places.  And their most learned study it.  It holds vast knowledge.  Knowledge to protect us!$B$BGo to Keeper Bel'dugur in the Undercity of Lordaeron.  Show him this sigil and he'll think you one of them.  Ask him for Yagin's Digest...and bring it to me!",objectives={"Bring the Sigil of the Hammer to Keeper Bel'dugur in the Undercity."}]])
R(729,"健忘的勘察員",[[description="首席考古學家杜瑟·灰鬚派我在偉大的勘察員雷姆塔維爾的指導下進行工作，這對我來說是無上的榮譽。在鐵爐堡學院時，每個人都知道雷姆塔維爾有許多偉大的發現。$b$b不過這位偉大的勘察員實在是……嗯……有些健忘……他常常對周圍的一切都渾然不覺。$b$b我們剛剛發現了一座大型的古代城鎮，但是突然間，可怕的傀儡從地下蜂擁而出，佔據了那裡。不過雷姆塔維爾似乎還沒有發現這一點，我跑回奧伯丁就是為了找人去救他。$b$b請到南邊去一趟，看看偉大勘察員是否還一切安好！",objectives={"到南邊去一趟，看看勘察員雷姆塔維爾現在處境如何。"}]])
R(730,"黑海岸的麻煩事",[[description="How nice it is to see a $c interested in the great archeological wonders of our world.$b$bOftentimes our work is dismissed as mere hobby by our friends in the Alliance. But what many fail to realize is that recent discoveries in Khaz Modan have proven that a great and powerful force threatens all of Azeroth, from Lordaeron to Kalimdor.$b$bI am most worried about my crew that I sent to Darkshore. They haven't sent word in weeks.$b$bTravel to Auberdine and look for a clue as to their whereabouts.",objectives={"Travel to Auberdine and look for signs of the dwarven excavation team."}]])
R(731,"健忘的勘察員",[[description="So then, Hollee... oh that's right, you are not Hollee. Where's Hollee?$b$bBah, that's beside the point. We must find that stone brush... I mean the mysterious fossil! We must find that fossil. The Explorers' League in Darnassus will want some indication as to what I've been doing.$b$bLet me know when you are ready and we will hunt down that brush.... I mean fossil! We shall find something in writing to satisfy the League.$b$bSo are you ready yet?",objectives={"Protect Prospector Remtravel as he searches for the mysterious fossil, then return to Archaeologist Hollee in Auberdine."}]])
R(732,"大地的震顫",[[description="我聽西格魯說，你在過去幾天幫了他的大忙。現在我也需要你的幫助。我的主人，肯瑞托的大法師克拉蘇斯派我來結束萊瑟羅峽谷的混亂局面。$b$b我不能透露這次任務的確切性質以及我要完成的使命，但是這個任務真的非常重要。$b$b有一夥四處遊蕩的巨魔偷走了一件名叫大地印章的東西，我必須要把它拿回來。如果你能幫我找到它，我就讓你知道更多的消息。",objectives={"幫加瑞克取回大地印章。"}]])
R(733,"搜集行動",[[description="It's going to be tough going here if I can't manage to scrounge up some materials to construct some defenses and other necessities. I've noticed that the ogres in the area seem to be well equipped with scrap metal. Maybe the stories of siege engines in the Badlands weren't so far off after all...$b$bAnyways, the Prospector's been getting worried about the state of our little camp, so I'd like to get working soon if I can.$b$bThe main ogre camp is at Dustbelch Grotto, a good trek to the west of here.",objectives={"Get 7 pieces of Scrap Metal for Sigrun."}]])
R(734,"不祥的感覺",[[description="太好啦，太好啦。$B$B<魯特維爾看了你一會兒，又去擺弄他的鐐銬了>$B$B去找盧希恩吧，$N。跟他說我需要一個5號齒輪。你能把它拿來給我嗎？",objectives={"和荒蕪之地的盧希恩·槍穗談話。"}]])
R(735,"星，手，心",[[description="雅格因的筆記？你要它幹什麼？沒關係，我不該問這個。$B$B我會幫你的，因為我這裡還有一本。我們得互相幫助，對不對？這樣我們才能各自獲利。$B$B我需要三件寶物，把它們給我拿來，我就給你那本筆記。$B$B我不會說出它們的名字，因為可能有人正在偷聽，不過我可以把這幾個名字寫下來。",objectives={"找齊葛利·硬骨的便箋上列出的東西，然後把它們交給鐵爐堡的葛利·硬骨。"}]])
R(736,"星，手，心",[[description="You need Yagyin's Digest?  Your plan, then, is to gather another flock?  Of course it is...and of course I will help you, $gbrother:sister;.$B$BBut you must help me too.$B$BI require three items of power.  Bring me these and the digest will be yours.$B$BI cannot utter the names of these items, but I will write them down.$B$BGet me the items on this list.  If you can do that, then you are truly worthy of opening your own chapter of our order.",objectives={"Bring the items on Bel'dugur's Note to Keeper Bel'dugur in the Undercity."}]])
R(737,"禁斷的知識",[[description="$n，我這裡有你想要的筆記，我想不需要我再提醒你要保管好它了吧？特別是絕對不要讓它落入敵人之手。$B$B這本書裡記錄了很多真相……$B$B……可以毀滅你的真相。",objectives={"把雅格因的筆記交給塞爾杜林。"}]])
R(738,"尋找阿戈莫德",[[description="勘察員阿戈莫德曾是荒蕪之地的挖掘場負責人，就是西南邊的那座挖掘場。我說「曾是」，是因為……嗯，最近幾週我都沒有得到他的任何消息。請你幫我找到阿戈莫德並拿到他的報告。$B$B我最後一次得到的消息是：阿戈莫德在荒蕪之地最南邊的挖掘場——那是苦痛堡壘附近的一個不起眼的小地方。你先去那裡找找看吧。",objectives={"找到阿戈莫德。"}]])
R(739,"莫達洛克",[[description="Agmond's tracks lead from the west.  It is easy to tell from the bloody smears across rock and sand that the dwarf crawled some distance.$B$BAnd here he died.$B$BUpon close inspection, the word \"Murdaloc\" is roughly scrawled in a patch of Badlands sandstone.$B$BScrawled next to Agmond's dead hand.",objectives={"Slay Agmond's killer, Murdaloc.$B$BSlay 12 Stonevault Bonesnappers.$B$BReport to Prospector Ironband in Loch Modan."}]])
R(741,"健忘的勘察員",[[description="So the prospector wants to send the mysterious fossil to the Explorers' League in Darnassus? I don't feel right leaving Darkshore without him.$b$bHere, $n, deliver the mysterious fossil to Chief Archaeologist Greywhisker in Darnassus.",objectives={"Take the mysterious fossil to Chief Archaeologist Greywhisker in Darnassus."}]])
R(742,"灰谷狩獵",[[description="Attention, young adventurers!  The wilds of Ashenvale await you!$B$BThe Horde has established a strong presence in the lands north of the Barrens.  Our two outposts - Splintertree Post and the Zoram Strand Outpost - strive to bring glory to the Horde!  Those who would prove themselves should seek out guidance there.  Of note: Senani Thunderheart in Splintertree Post, directly north of the Barrens, seeks adventurers willing to take part in a great hunt of Ashenvale!",objectives={"Speak with Senani Thunderheart at Splintertree Post, Ashenvale."}]])
R(743,"風怒鷹身人",[[description="謝謝你抽時間來和我談話，$N。我是盧爾，既是一個戰士，也是一個導師。$B$B如果你想在莫高雷之外經歷更多冒險的話，現在正是讓你接受更多考驗的時候了。$B$B如果你想測試自己的能力，就去東南方找風怒鷹身人作戰吧。他們駐紮在山邊遠離大路的地方。$B$B鷹身人是我們的天敵，對你來說，和他們戰鬥會是個不錯的考驗。",objectives={"給血蹄村的盧爾·鷹爪帶回8隻風怒鷹身人的爪子。"}]])
R(744,"準備典禮",[[description="$N，我的兄弟很快就要去面見血蹄酋長了，我要為他做一個頭飾，這對我來說是一種榮耀。$B$B在我處理這些皮革的時候，你能不能幫我一個忙？我沒有時間去收集足夠的羽毛，不知道你能否幫助我去收集一些呢？$B$B你應該可以在雷霆崖北面和西北面的鷹身人身上找到尺寸合適的羽毛。我需要6片碧藍色的和6片古銅色的羽毛來完成我的頭飾。",objectives={"收集6根碧藍色的羽毛和6根古銅色的羽毛，把它們交給雷霆崖的伊恩·鷹爪。"}]])
R(745,"土地之爭",[[description="這片土地上有很多紛爭，$N。我希望你不會像我一樣經歷那麼多的戰爭，不過我還是希望你去做一件事，讓你可以瞭解到，一個看似不值一提的小小威脅如果不加制止的話，會對我們的領土帶來多大的危害。$B$B白鬃豺狼人已經在西邊的一個洞穴中和血蹄村的南邊紮了營。我們曾試圖和他們交流，卻被他們無理地拒絕了，而且他們還大肆屠殺莫高雷的野生動物。$B$B現在語言已經不能解決問題了，我們必須有所行動。",objectives={"殺死10個白鬃製革工、8個白鬃剝皮工和5個白鬃偷獵者，然後回到血蹄村向貝恩·血蹄覆命。"}]])
R(746,"矮人的挖掘場",[[description="西北部有些矮人正在準備修建一座挖掘場。他們認為地下埋藏著某些秘密，事實也的確如此，不過挖掘和污染大地並不是獲得這些秘密的正確途徑。$B$B收集矮人的挖掘工具，把它們全都毀掉，然後把這些被損壞的工具帶給我。$B$B要毀掉這些工具的話，你必須得找到一塊鐵砧才行。在雷霆崖就有一處鐵匠鋪，不過任何鐵砧——包括矮人營地裡的——都可以用來毀掉工具。",objectives={"收集5個勘察員的鋤頭。$B$B在鐵匠鋪砸碎這些勘察員的鋤頭。$B$B把5件損壞的工具交給血蹄村的貝恩·血蹄。"}]])
R(747,"開始狩獵",[[description="歡迎來到納拉其營地，$n。你來到這裡的消息很快就傳遍了部族。或許很快有一天你會被迎去雷霆崖上的大城市裡，但首先，你必須先向我們證明你的能力。$b$b我們這些生活在紅雲臺地上的牛頭人無疑對自己優秀的狩獵技術最為自豪，當然，牛頭人只為生存需要和競技而狩獵。我們庫存的肉已經不多了，另外我們還需要羽毛來做衣服。現在去獵殺附近的平原陸行鳥來給村莊提供補給吧，同時你也可以借此證明自己的能力。",objectives={"納拉其營地的格盧爾·鷹風要求你帶給他7片平原陸行鳥的羽毛和7塊平原陸行鳥肉。"}]])
R(748,"毒水",[[description="那些哥布林和他們的爪牙污染了我們神聖的水井！我們必須制止他們！$B$B要想淨化所有的水井，我得先製造出相應的淨化圖騰，然後你把圖騰拿到水井那兒去完成淨化的儀式。$B$B首先，我們給冰蹄之井製作一個淨化圖騰，這需要大地的幫助。去獵捕一些草原狼和成年平原陸行鳥，把它們的爪子帶回來給我，它們就在西南方活動。",objectives={"收集6隻草原狼的爪子和4隻平原陸行鳥的爪子，把它們交給血蹄村的莫爾·雷角。"}]])
R(749,"被破壞的貨車",[[description="幾天前，我們在石牛湖北岸發現了有一個被重兵保護著的風險投資公司的馬車。我們在先前的戰鬥裡已經失去了兩個同伴，所以我們就把怒氣傾瀉在這輛馬車身上，速戰速決地把它給摧毀了。$b$b我們沒去管他們的儲物箱，滿以為一把火就可以把這些東西和馬車一起燒成灰。不過有人在那輛熊熊燃燒的貨車附近看見了風險投資公司的搶救人員，那些箱子可能沒被燒掉。$b$b也許你可以去那輛貨車旁，看看箱子裡面到底是什麼。",objectives={"摩林·雲行者要你去查看被破壞的貨車附近的儲備箱裡有什麼東西。"}]])
R(750,"繼續狩獵",[[description="善於狩獵的牛頭人從不僅僅將他的獵物看作戰利品，這些生活在平原上的野獸對我們的生存有著極為重要的意義。如果你能帶回一些珍貴的山獅皮的話，就會令部族裡的長老們對你刮目相看。你可以在南邊的山區找到它們。$b$b我們的孩子需要衣服，部族裡的帳篷也需要維修了。",objectives={"納拉其營地的格盧爾·鷹風要求你帶給他10張山獅皮。"}]])
R(751,"被破壞的貨車",[[description="撬開蓋子之後，你發現了堆的滿滿的礦石，這又一次證明了風險投資公司確實在莫高雷地區有採礦活動。在礦石的最上面有一捆文件。$b$b你可以依稀聽見東部丘陵的頂部傳來叮叮噹噹的聲音，還可以看見從一大堆營火上升起的濃煙。",objectives={"把風險投資公司文件交給血蹄村附近的摩林·雲行者。"}]])
R(752,"壹件瑣事",[[description="我們部族的所有成員都過著完美和諧的生活，我們一起勞作，一起生活。$b$b部族中的每個成員都對其他人負有義務，並且我們總是將這些義務放在首位。現在我需要你幫我做一件麻煩的事情。$b$b我的母親今天早上去納拉其東南方的水井中取水，她已經去了很久了。你能不能替我去看看？部族裡的事務讓我實在抽不開身。",objectives={"鷹風酋長要求你去納拉其營地東南方的水井處尋找他的母親。"}]])
R(753,"壹件瑣事",[[description="我這一生也算是經歷了不少磨難，走了不少路，現在我這一把老骨頭也沒什麼力氣啦。我仍然在為部族盡力，但有些時候，我還真感覺有些力不從心。$b$b不過，你這$c似乎是正想找點什麼事情做做呀。正好，讓我來看看你的體力如何吧。把水井旁的這個水罐交給我兒子，他就在納拉其營地裡。$b$b記住，即使是最瑣碎的小事，只要你做得夠好，也能獲得長老們的首肯。",objectives={"在井邊拿一隻水罐。$b$b把它帶給納拉其營地裡的鷹風酋長。"}]])
R(754,"凈化冰蹄之井",[[description="我已經做好了可以淨化冰蹄之井的圖騰。現在你就把它拿到那兒去完成淨化儀式。冰蹄之井就在東南邊，有許多哥布林把守著那裡！$B$B這不是個簡單的任務，不過如果我們想要重新使用那裡的水，就必須得這麼做。$B$B祝你好運，$N。",objectives={"用冰蹄之井淨化圖騰為冰蹄之井完成淨化，然後回來見莫爾·雷角。"}]])
R(755,"大地之母儀祭",[[description="你願意為納拉其的牛頭人做這樣瑣碎的小事，同時又渴望學習新的知識，這足以說明你有著高貴的品質，$n。我相信總有一天你會成為一位在雷霆崖赫赫有名的$c。$b$b不過在那之前，你必須首先完成大地之母儀祭，這個偉大的傳統共由三個不同的試煉組成。$b$b第一個試煉是力量之儀祭。去找灰舌先知，告訴他是鷹風酋長派你去的。$b$b翻過納拉其營地正南方的山后，你就可以找到他的居所了。",objectives={"找到居住在納拉其營地正南方山中的灰舌先知。"}]])
R(756,"雷角圖騰",[[description="要製作雷角之井淨化圖騰，你必須先去收集莫高雷平原上的肉食動物的爪子。去捕獵草原捕食者和平原獅，然後把它們的爪子帶回來見我。$B$B它們就在這裡的東邊和西邊活動。",objectives={"收集6個草原捕食者的爪子和6個平原獅的爪子，把它們帶給莫爾·雷角。"}]])
R(757,"力量儀祭",[[description="大地之母儀祭對於每一個想要在雷霆崖得到尊重的年輕牛頭人來說都是非常重要的。$b$b但在那之前，你必須先通過力量儀祭的試煉。在這個試煉中，你必須通過殺死部族的敵人來證明你的勇猛。$b$b生活在東邊的刺刃峽谷中的刺背野豬人侵佔了我們部族不少的土地，他們偷襲我們的狩獵小隊，還在晚上到村子裡來偷東西。$b$b殺死他們，展示出你的英勇無畏吧。拿著它們的腰帶去見納拉其營地的酋長，他將證明你通過了試煉。",objectives={"殺掉刺刃峽谷的刺背野豬人並帶回12條刺背腰帶，把它們交給納拉其營地的鷹風酋長。"}]])
R(758,"凈化雷角之井",[[description="圖騰已經準備好了，$N。這一次還是由你來完成淨化儀式。$B$B到村莊北面的雷角之井去，用雷角之井淨化圖騰完成淨化儀式，然後再回來找我。$B$B願大地之靈指引你。",objectives={"在雷角之井使用雷角之井淨化圖騰，然後回來見莫爾。"}]])
R(759,"蠻鬃圖騰",[[description="There is but one water well left to cleanse, named after the Wildmane clan.  For this well to be pure, the land must offer the teeth of a fierce predator, the prairie wolf alpha.  Find the alphas to the north, then return to me when your hunt is finished.$B$BAlphas often wander around the base of our mighty city, Thunder Bluff.",objectives={"Bring 8 Prairie Alpha Teeth to Mull Thunderhorn in Bloodhoof Village."}]])
R(760,"凈化蠻鬃之井",[[description="Your cleansing of the Winterhoof and Thunderhorn wells is spoken among the spirits, young $N.  The Wildmane Totem is made, and your last task lies ahead.$B$BThe Wildmane Water Well lies north of Thunder Bluff.  Perform the ritual!  Heal the land of the goblins' poisons!  Let clean water flow once again!",objectives={"Use the Wildmane Cleansing Totem at the Wildmane Water Well, then return to Mull Thunderhorn."}]])
R(761,"獵捕猛鷲",[[description="猛鷲是一種狡猾無比、很難獵捕的鳥。收集猛鷲的羽毛可以證明一個獵手的智慧和決心。$B$B如果你想接受這個任務，就去平原上獵捕猛鷲吧。$B$B把它們的羽毛帶給我，為你的部族贏得榮譽。$B$B猛鷲在莫高雷的任何地方都能找到，不過要發現它們，你得有銳利的眼睛；要捕捉它們，你得有靈活的手腳。",objectives={"收集8根猛鷲的羽毛，把它們帶給血蹄村的哈肯·風之圖騰。"}]])
R(762,"邪惡的使者",[[description="拉格納羅斯派因弗努斯大使到苦痛堡壘去監督暗爐矮人在奧達曼挖掘神器的工作。$B$B我們的同胞已經遭受了慘重的傷亡，然而這樣的情況仍然在繼續。我不願去猜測他們會找到多少強大的神器並用它們來對付鐵爐堡。$B$B我們的目的很簡單，$c。回到荒蕪之地去，幹掉因弗努斯大使。在除掉了這個威脅之後，把你完成任務的證據交給顧問貝爾格拉姆。$B$B現在馬上出發吧。",objectives={"殺死苦痛堡壘中的因弗努斯大使，把證明他已死亡的信物交給鐵爐堡的顧問貝爾格拉姆。"}]])
R(763,"大地之母儀祭",[[description="要想繼續大地之母儀式，你必須先通過兩個小試煉。現在也正好是你去積累積累經驗的時候了，$n。$b$b到血蹄村去找那裡的酋長，凱恩之子貝恩·血蹄吧。你可以在那兒繼續你的冒險歷程並得到雷霆崖的長老們的承認。$b$b把這個圖騰帶給貝恩。他會讀懂我刻在上面的符號，並幫助你繼續修行。$b$b順著這條從納拉其營地通向外面的路快點出發吧，千萬別迷路了。",objectives={"順著離開納拉其營地的路將鷹風圖騰帶給血蹄村的貝恩·血蹄。"}]])
R(764,"風險投資公司",[[description="This explains the buildup of Venture Co. employees and equipment we've seen in Mulgore. Those goblins... their company is expanding too quickly for their own good. It's how they say, show a goblin something, and you can hear the scales in the background.$b$bGreedy little things, they are. Unfortunately for their business enterprise, we tauren cannot allow them to conduct their operations in our lands. Go to their mine northeast of the ravaged caravan and send them a message.",objectives={"Kill 14 Venture Co. Workers and 6 Venture Co. Supervisors for Morin Cloudstalker at Bloodhoof Village."}]])
R(765,"菲茲普羅克主管",[[description="According to the documents you salvaged from the caravan, the Venture Co. created many plans to attempt to drive us from our lands here, so that they could have free reign to plunder our lands.$b$bThe depths that they would sink to accomplish their goals disgusts and appalls me. I want the mastermind behind their plans killed. His name is Supervisor Fizsprocket, you will find him at the Venture Co. mine east of the ravaged caravan. Bring me his clipboard, we shall see if we find out anything useful.",objectives={"Kill Supervisor Fizsprocket and return his clipboard to Morin Cloudstalker at Bloodhoof Village."}]])
R(766,"馬茲拉納其",[[description="我祖父曾講述過他和一隻叫馬茲拉納其的陸行鳥戰鬥的故事，說起過它那邪惡的紅眼睛，剃刀般鋒利的爪子，只要被它咬一口，你就會身中劇毒。$b$b在我穿越平原的時候，正巧遭遇了它，肩膀被它咬了一口。它比我祖父所說的還可怕！我需要一些東西來幫我解毒：一顆狼心，獅子的腿骨，平原陸行鳥的鱗片和猛鷲的胃。$b$b快點，我快要不行了。",objectives={"收集草原狼的心臟、平原獅的腿骨、平原陸行鳥的鱗片和猛鷲的胃各一份，把它們交給血蹄村的茂爾·祈雨。"}]])
R(767,"幻象儀祭",[[description="作為大地之母儀祭之一的幻象儀祭可以指引你最終贏得雷霆崖長老們的尊重。$b$b我們早已認識到，土地就是我們最神聖的生命之本。如果你準備好要進行幻象儀祭的話，就得去和村裡的精神領袖札爾曼·雙月談話。",objectives={"和血蹄村的札爾曼·雙月談話。"}]])
R(768,"收集皮革",[[description="你好，年輕的$r。我從你的眼中看到了你重回原野捕獵的渴望。希望你能為你的部族帶來榮耀！$B$B我擅於利用各種獸皮來為雷霆崖的居民製作護甲和衣物。$B$B如果你能幫我搞到一些獸皮的話，那我就可以用它們來為你製作一些你需要的東西。",objectives={"收集12塊輕皮，把它們交給雷霆崖的維爾倫·陸行者。"}]])
R(769,"科多獸皮包",[[description="莫高雷的科多獸強壯而兇猛，它們的這些特質備受我們尊敬。如果你善於皮革加工，而且希望獲得製作科多獸皮包的知識，那就給我弄點材料來吧。$B$B弄些材料來，我就會把我的手藝傳授給你。",objectives={"帶去4塊輕皮和4條粗線給雷霆崖的維爾倫·陸行者。"}]])
R(770,"惡魔之傷",[[description="鬼嚎那粗糙的毛皮上還留著一個可怕的傷口，是在它與燃燒軍團的戰鬥中留下的。$B$B也許你應該把鬼嚎的死訊告訴血蹄村裡的什麼人……",objectives={"去打聽打聽誰聽說過鬼嚎。"}]])
R(771,"幻象儀祭",[[description="要想通過幻象儀祭，你必須先找到製作先知之水的試劑。$b$b我需要一些水井石，你可以在莫高雷一帶的水井附近找到它們。另外，你還得在這周圍的大樹下面找到一些琥珀顆粒。$b$b這兩種東西都具有強大的元素力量，把它們結合起來，用部族之火點燃之後，你可以看到一個幻象。追隨它，它就會引領你進入這個神聖使命的下一個階段。",objectives={"收集2塊水井石和2個琥珀顆粒，把它們帶給血蹄村的札爾曼·雙月。"}]])
R(772,"幻象儀祭",[[description="現在，我把神聖的先知之水交給你。$b$b準備好了之後，就去部族之火旁把水喝下，然後稍等片刻，一個幻象就會出現在你的眼前。$b$b你必須立刻決定是否要追隨這個幻象……",objectives={"在血蹄村的部族之火前將先知之水喝下，當幻象出現之後跟隨它。"}]])
R(773,"智慧儀祭",[[description="要讓雷霆崖的資深長者接受你，你就必須再完成大地之母儀祭的下一個階段：智慧儀祭。$b$b你已經通過了幻象儀祭，赤色石的先祖之魂會祝福你的，只有那些喝過先知之水的人才能得到這種祝福。$b$b向雷霆崖的東面去，到赤色石尋找先祖之魂吧。",objectives={"到雷霆崖東邊的赤色石去和先祖之魂談話。"}]])
R(774,"<UNUSED>")
R(775,"雷霆崖之旅",[[description="You will now be revered within our great city. Any $r worthy of completing the Rites of the Earthmother earns that honor.$b$bFor your final quest, seek out our noble leader, Cairne Bloodhoof, who dwells atop the highest mesa in Thunder Bluff.",objectives={"Speak with Cairne Bloodhoof in Thunder Bluff."}]])
R(776,"大地之母儀祭",[[description="You have passed the Rites of the Earthmother and earned your place in Thunder Bluff.$b$bBut in order to maintain the spot that you strived so hard to achieve, you must continue to prove your worth to your people.$b$bWe are hunters, $n. Down below in Mulgore there is a mighty kodo named Arra'chea. Show me your skills in the ways of tracking and hunting by bringing me the Horn of Arra'chea.",objectives={"Cairne Bloodhoof in Thunder Bluff wants you to bring him the Horn of Arra'chea."}]])
R(777,"不祥的感覺",[[description="好吧，拿去吧。$B$B我現在要去找個掩體……$B$B你要不要一起來？",objectives={"把5號齒輪交給魯特維爾·沃拉圖斯。"}]])
R(778,"不祥的感覺",[[description="哈哈！完成啦！鐐銬完成啦！$B$B記住這個時刻，盧希恩,記住這個時刻，阿布！你準備好了嗎？你將親眼看見煉金術、工程學和魔法的完美結合。$B$B我將召集一個強大的元素生物。今天，對於我們來說，是具有里程碑意義的一天！",objectives={"擊敗法姆雷托守護者，並將魯特維爾的元素禁錮鐐銬交還給魯特維爾。"}]])
R(779,"大地封印")
R(780,"鬥豬",[[description="生活在東邊的刺刃峽谷中的鬥豬已經侵佔了我們部族的狩獵場。正在與我們交戰的刺背野豬人把這些野豬訓練成了兇暴而富有攻擊性的生物。$b$b去把這些可惡的傢伙殺掉，再帶些豬頭和肋排回來，我們可以燉肉給孩子們吃。",objectives={"納拉其營地的格盧爾·鷹風要求你去幹掉鬥豬，並帶給他8塊鬥豬頭和8塊鬥豬肋排。"}]])
R(781,"納拉其營地的危機",[[description="在仔細查看了地圖之後，你意識到刺背野豬人的酋長正計畫著對納拉其營地展開進一步攻擊。$b$b鷹風酋長必須馬上得知這個消息。",objectives={"將刺背野豬人的進攻計畫交給納拉其營地的鷹風酋長。"}]])
R(782,"破碎的聯盟",[[description="From the Horde's alliance with the dragon Deathwing during the Second War, we know that two of his lieutenants, Blacklash and Hematus, were imprisoned within Lethlor Ravine far to the east. We must silence our depraved allies of old to restore honor to the Horde!$B$BWe hired Tho'grun and his band of ogre mercenaries to help us obtain the Sign of the Earth, a key needed to unlock the drakes' prison. Tho'grun betrayed us though, overwhelming us and taking it for himself. Go to Camp Boff and take it back!",objectives={"Kill Boss Tho'grun and bring the Sign of the Earth to Gorn in Kargath."}]])
R(783,"身邊的危機",[[description="我希望你已經整裝待發了，年輕的$c。北郡需要你的幫助！$B$B我不是說讓你去種田什麼的。$B$B暴風城的衛兵們很努力地維持著這裡的和平，但我們人手短缺，更多的危險還在不斷迫近。我們正在召募願意出力保衛家園和聯盟的人。$B$B如果你也是應召而來的話，請和我的上級長官—治安官瑪克布萊德談話。他就在我身後的這座修道院裡。",objectives={"與治安官瑪克布萊德談話。"}]])
R(784,"背信棄義的人類",[[description="庫爾提拉斯的人類曾在普勞德摩爾將軍的率領下大舉進攻杜洛塔，徹底破壞了在共同抵抗阿克蒙德和他的惡魔大軍時由酋長和珍娜·普勞德摩爾定下的互不侵犯協議。$b$b我們擊退了人類的進攻，並攻下了提拉加德城堡。但最近，由本尼迪克上尉率領的後備軍又重新佔領了提拉加德城堡，對我們的家園構成了新的威脅，這些人類從不遵守外交協議。$b$b到南方的提拉加德城堡去消滅那些人類侵略者，證明你的勇氣和榮譽。",objectives={"殺死10個庫爾提拉斯水手和8個庫爾提拉斯水兵，再把本尼迪克上尉幹掉，然後回剃刀嶺向加索克復命。"}]])
R(785,"A Strategic Alliance",[[description="Thrall is a most wise and noble leader. His tenacity on the battlefield is matched only by his diplomatic tact.$b$bThe Darkspear Trolls have proven to be invaluable allies to orckind. Out of loyalty and honor we have sworn a pact of protection with them.$b$bThe Warchief has sent orders to make sure our Darkspear friends in Sen'jin Village are not under any direct threat. One of their most trusted scouts, Lar Prowltusk is keeping a close watch on their western flank.$b$bSeek out Lar and assist as needed.",objectives={"Seek out Lar Prowltusk on the western flank of Sen'jin Village."}]])
R(786,"科卡爾半人馬的進攻",[[description="小聲點，$c。科卡爾半人馬就在西邊科卡爾峭壁的山脊上。$b$b昨天晚上，我潛入了他們的村莊，發現這些骯髒的野獸準備同時向杜洛塔的食人妖和獸人發動三波攻勢。$b$b我們決不能讓他們的入侵計畫得逞！你可以召集一些兵力，潛入科卡爾峭壁並粉碎他們的進攻計畫。$b$b他們已經把進攻計畫分別交給了三個首領，準備由他們率領三股部隊同時行動。",objectives={"在森金村外面的拉爾·獵齒要求你粉碎科卡爾峭壁內的三份進攻計畫。"}]])
R(787,"新的部落",[[description="向你致意，$c。我是伊崔格，奉索爾酋長的命令在此負責招募新兵。$b$b部落已經不再是從前的那個部落了。我曾經離開過部落，在那段時間裡，我受到燃燒軍團的蠱惑而迷失了自我。在被放逐後，我被一群人類抓去當了俘虜，但最終被我們偉大的酋長救了出來。在酋長那拯救部落的遠大志向的指引下，在薩滿的教誨之下，我回來了。$b$b高內克會給你進一步的指示。",objectives={"向大獸穴裡的高內克報到。"}]])
R(788,"小試身手",[[description="第一項任務將在力量方面對你進行考驗。我本來可以把你派去貧瘠之地獵殺科多獸，不過呢，照實說，你活著比死了對我們來說更有用。$b$b我相信你更合適和那些雜斑野豬鬥一鬥，往北邊走就可以找到它們。",objectives={"殺掉10隻雜斑野豬，然後向大獸穴裡的高內克報告。"}]])
R(789,"工蠍的尾巴",[[description="無論是強大的戰士還是笨拙的新手，都有可能會倒在蠍尾上的毒針之下。在這裡的西北方有大量蠍子在活動，給我帶10條蠍尾回來，以此來證明你的戰鬥能力吧。$b$b事實上，它們尾巴上的毒針正是製作解毒劑的重要材料，解毒劑便是從毒針中提取的。我們需要長期備有大量的解毒劑，以防止像你這樣的新手被蠍毒所害……$b$b但我肯定你是不會需要這種玩意的，對吧？",objectives={"帶10根工蠍的尾巴給大獸穴中的高內克。"}]])
R(790,"薩科斯",[[description="$C！我差點就神不知鬼不覺地死在這鬼地方了！我在谷裡捕獵蠍子的時候，突然看到一隻看起來特別兇惡的蠍子。當時我就決定以它為獵物，打算在它那碩大的鉗子鉗住我的腿以前，先重重地給它來上那麼一下子。$b$b但我忘記了它還有根毒刺，毒刺猛紮了下來，一下子就刺進我的胸口。拜託，你一定得替我報仇！只有這樣才能留存我的名譽！我是在南邊的高地上碰上它的。",objectives={"殺死薩科斯並將它的爪子帶回去交給哈納祖。"}]])
R(791,"新的背包",[[description="我太老了，已經沒法上戰場拼殺了。所以我開始用別的途徑為部落出力，實現我的價值。$b$b我在這裡監視周圍的情況，我們的力量越來越強大，我吹起號角的機會也越來越少。$b$b為了打發時間，我經常給那些保衛家園的年輕戰士們做些有用的東西。$b$b我可以給你做一個用來放置財物的包袱，但是你得先給我找些帆布腳料來，人類和半人馬經常使用這種布料。",objectives={"剃刀嶺瞭望塔中的弗恩·凝眉想要8塊帆布腳料。"}]])
R(792,"邪靈劣魔",[[description="我相信你會在試煉谷學到很多東西，年輕的$c。$B$B我本是被派到這處谷地裡來指引和教育你們的，但我卻在這裡發現了一些不潔之物……$B$B一群自稱為火刃氏族的獸人潛入了試煉谷，他們躲進了東北方的一處洞穴裡，而他們的邪靈劣魔則肆虐著周邊的一大片地區。$B$B作為你對抗火刃氏族的第一個任務，我命令你消滅這些劣魔。盡可能地多殺一些，如果殺完了它們之後你還活著的話，就回來向我覆命。",objectives={"殺死12隻邪靈劣魔，然後向大獸穴外的祖雷薩覆命。"}]])
R(793,"破碎的聯盟",[[description="The Seal of the Earth is held by three runestones, held in the Pillars of Diamond, Opal, and Amethyst in Lethlor Ravine. Using the Sign of the Earth, you will be able to remove the runestones and unlock the Seal of the Earth.$b$bBe wary though, $n, the black drakes Blacklash and Hematus are not to be trifled with. See them dead and return their bindings to me.$B$BTo reach the ravine, travel to the far eastern part of the Badlands.  Be careful though, for the ravine is home to countless drakes.",objectives={"Use the Sign of the Earth to activate the Pillars of Diamond, Opal, and Amethyst and obtain the Runestones.$b$bPlace the runestones in the Seal of the Earth to free Blacklash and Hematus.$b$bSlay them and return Blacklash's Bindings, the Chains of Hematus, and the Sign of the Earth to Gorn."}]])
R(794,"火刃獎章",[[description="我通過預言術發現在火刃集會所的深處藏有一件蘊涵著強大力量的物品，它被一些猛獸和黑暗的魔法守衛著。$B$B那件物品叫作火刃獎章，你的下一個任務就是找到它，把它從集會所裡偷出來。$B$B不過你可得小心，因為獎章的所有者可能是一個火刃部落中的強者，他也許要比你以前對付過的那些傢伙要強上許多倍。$B$B現在就出發吧，$N，那個洞穴就在這裡的西北方。",objectives={"給大獸穴外的祖雷薩帶回火刃獎章。"}]])
R(795,"大地封印")
R(796,"<UNUSED>")
R(797,"<UNUSED>")
R(798,"<UNUSED>")
R(799,"<UNUSED>")
R(800,"<UNUSED>")
R(801,"<UNUSED>")
R(802,"<UNUSED>")
R(803,"<UNUSED>")
R(804,"薩科斯",[[description="看見你為我這麼一個素不相識的可憐傢伙做了這麼多事情，我突然又堅強了起來。我絕不能就這麼輕易地死在這種地方！我得堅持下去！$b$b可現在我還是不能自己回到大獸穴去。$n，請你再幫個忙，回大獸穴向高內克報告一下我現在的情況。",objectives={"將哈納祖目前的狀況告訴大獸穴內的高內克。"}]])
R(805,"去森金村報到",[[description="你在這山谷中的針對火刃氏族的試煉……如今就算是完成了。但我希望你能去向其他人報告一下你的發現。$B$B到森金村去找加德林大師吧。先從山谷的東側出去，在岔路口轉向右一直走到底就能抵達森金村了。$B$B我們必須把火刃氏族的勢力出現在試煉谷的事告訴加德林大師。$B$B去吧，$N，動作要快。恐怕我們在火刃集會所中找到的東西只是更可怕的威脅的預兆而已……",objectives={"與森金村的加德林大師談話。"}]])
R(806,"黑暗風暴",[[description="$N，我有個不妙的消息。對火刃氏族的調查表明，杜洛塔境內還有不少這個氏族的勢力。這是我們絕對不能允許的！在他們站穩腳跟、滋生邪惡之前，我們必須把他們消滅掉。$B$B有個名叫費索·暗雷的哥布林術士就居住在西北部的雷霆山裡，他和他的那群爪牙就在那裡製造混亂。$B$B去幹掉他，再把他的爪子帶回來給我！",objectives={"把費索的爪子帶給剃刀嶺的奧戈尼爾·魂痕。"}]])
R(808,"明希納的顱骨",[[description="我在夢中聽到了我兄弟明希納的呼喚。$B$B回音群島上的術士札拉贊恩抓走了他，折磨著他，最後殘忍地害死了他。$B$B但即使是死亡也沒能讓我的兄弟得到安寧，因為札拉贊恩用邪惡的魔法把明希納的靈魂困在了他的顱骨中。我在夢中看見…我兄弟的顱骨和其他人的顱骨一起被堆在回音群島中最大的那座島上的法陣中。只要他的頭骨還在那兒，他的靈魂就無法得到自由。$B$B請你幫助他吧，$N。找到那個邪惡的法陣，把明希納的顱骨帶回來給我，讓他的靈魂獲得自由吧！",objectives={"到回音群島上去，將島上法陣中的明希納的顱骨帶回來，交給森金村的加德林大師。"}]])
R(809,"雅克塞羅斯",[[description="Since the last great war when the Burning Legion was defeated, I have searched for sources of demonic corruption in orc society.  The collar you brought me confirms my fears.$B$BIt belongs to the Burning Blade, a cult that rallies around an item of demonic power.  It is called the Demon Seed, and it resides in the Barrens atop Dreadmist Peak.  It must be destroyed!$B$BGo to Far Watch Post, on the border of the Barrens to the west, and speak with my assistant, Ak'Zeloth.  He will direct you further.",objectives={"Speak with Ak'Zeloth in the Barrens."}]])
R(810,"<UNUSED>",[[description="You would do well to learn how dangerous this land can be, $c.$B$BThe wildlife here can teach us such things... if we are wise and observant.$B$BThe scorpids are a perfect example of survival in Durotar. If you are to survive, it would be wise to take on some of their characteristics as your own. Their hardened carapaces can protect you from the harshness of the sun, or even a deadly weapon.$B$BBring me 6 Small Scorpid Carapaces from the Clattering Scorpids, $N, and I shall see about rewarding you justly.",objectives={"Bring 6 Small Scorpid Carapaces to Kor'ghan in Sen'jin Village."}]])
R(811,"<UNUSED>",[[description="One of the other traits of the scorpids is their fierce loyalty. They will protect one another if they are in danger--you've probably already seen this behavior in your first scorpid hunt.$B$BYou would do well to heed that lesson and adapt it for yourself: we are stronger as one; we are weak when we are divided into many.$B$BBring me 8 Large Scorpid Carapaces from the Armored Scorpids and I shall reward you for learning this wisdom.",objectives={"Bring 8 Large Scorpid Carapaces to Kor'ghan in Sen'jin Village."}]])
R(812,"救命如救火",[[description="$N……你來得真是時候，快救救我……$B$B我在毒尾蠍戰鬥的時候一不小心被蟄傷了，毒液正在不斷侵蝕我的血液。看樣子…我最多再撐一個小時就得玩完了，我想請你幫個忙…$B$B奧格瑪的考格漢知道怎麼做解毒劑，快去找他…$N，我…我支持不了多久了……",objectives={"找到毒尾蠍的解毒劑，把它交給杜洛塔西北邊境的林納格。"}]])
R(813,"尋找解毒劑",[[description="林納格不隨身帶著解毒劑就去抓毒尾蠍是很不明智的行為，不過現在說這些也於事無補。$B$B趕快到奧格瑪城的城門外，在那一帶的毒尾蠍身上給我找4個毒囊回來，這樣我才能給他做解毒劑。$B$B動作快點，$N。我們自己的同胞命在旦夕！",objectives={"收集4個毒尾蠍的毒囊，把它們交給奧格瑪的考格漢。"}]])
R(814,"<UNUSED>",[[description="Cook and clean--that's all I do!$B$BYou want to eat, you get me some more meat! I don't have all day to hunt and prepare food for all these louses. You got to learn to pull your own weight around here if you wanna be treated equal.$B$BGet me some Chunks of Boar Meat if you want to make yourself useful... or you don't want to starve to death.",objectives={"Bring 10 Chunks of Boar Meat to Cook Torka in Razor Hill."}]])
R(815,"恐龍蛋大餐",[[description="啊呀！我差點忘了還得做早飯！$B$B$N，快去給我找點鞭尾龍的蛋來，至少得要三個蛋才夠明天做飯用。$B$B血爪鞭尾龍非常兇猛，而且會拼命地保護自己的蛋。有時它們會把蛋深深地埋在地下讓你找不到，不過在森金村東南方的回音群島上，這些鞭尾龍的蛋滿地都是。",objectives={"收集3個鞭尾龍的蛋，並把它們帶給剃刀嶺的廚師托爾卡。"}]])
R(816,"丟失的孩子",[[description="$N，請幫幫我吧！我的兒子克魯恩幾天前到西邊的怒水河畔捕獵鱷魚，卻一直沒有回來，我現在覺得不妙了。$B$B儘管他十分強壯，但他的固執和自尊常常讓自己陷入麻煩。我警告過他，鱷魚是強大而兇猛的動物，可他一聽就火了，掉頭就走。$B$B如果你找不到他，至少也請給我帶來一些關於他的消息，不管是好的還是壞的……就算把怒水河畔每隻鱷魚的肚子剖開也要找到點什麼。",objectives={"把關於克魯恩的消息告訴剃刀嶺西北部農場中的米莎·托克倫。"}]])
R(817,"生活所需的虎皮",[[description="我們的獸皮大多取自生活在杜洛塔地區的老虎身上，$N。我們捕獵這些野獸的原因很多，比如毯子、護甲，還有帳篷什麼的；同樣，還有許多原因讓我們允許它們繼續繁衍生息。$B$B但是現在，我們有必要再殺掉一些老虎了。我們的人數在增加，而庫存的獸皮也已經開始供不應求了，因此我需要更多獸皮來為他們製作各種生活用品。$B$B給我找四張杜洛塔猛虎的毛皮來，我會給你一些獎賞的。",objectives={"收集四張杜洛塔虎皮，並把它們交給森金村的維爾林·長牙。"}]])
R(818,"沃納爾大師",[[description="雖然我的視力不斷衰退，但我還是可以看得足夠清楚。我曾經可以很輕易地施放強力的魔法，而現在我更多時候必須依靠煉金術的幫助才行。不過我不收學徒，因為我從來沒有看到過任何夠格的食人妖或獸人。$B$B你是合適的人選嗎？當然，你當然是……你當然以為自己合適。$B$B我需要一點東西，你能幫我拿來嗎？$B$B我要一些龍蝦人的眼睛和幾瓶蟹膠，你可以在杜洛塔的海蟹或龍蝦人身上找到這些東西，找齊了之後再來見我。",objectives={"把4個龍蝦人的眼睛和8小瓶蟹膠帶到森金村，交給沃納爾大師。"}]])
R(819,"老陳的空酒桶",[[description="張貼在酒桶一角的紙條上寫著：「老陳 - $B$B祝汝精神得提升，祝汝精神永提升。」",objectives={"找到對老陳的空酒桶有所瞭解的人。"}]])
R(821,"老陳的空酒桶",[[description="Would you like a taste of Chen's namesake? Ahh, the stormstout is a mighty brew. Chen taught the recipe to my mentor, and my mentor passed it on to me. I'll need you to get me a few things, but I can tell you this: the kick is worth it.$B$BBring me 5 savannah lion tusks from any savannah lion, 5 plainstrider kidneys from any plainstrider, and 1 thunder lizard horn from any species of thunder lizard. That should do the trick nicely.$B$BYou can find these ingredients throughout the Barrens.",objectives={"Bring 5 Savannah Lion Tusks, 5 Plainstrider Kidneys, and 1 Thunder Lizard Horn to Brewmaster Drohn in Ratchet."}]])
R(822,"老陳的空酒桶",[[description="雷霆佳釀的味道不錯吧？$B$B我從老陳那裡還學到了另一種釀酒術，你有興趣嗎？釀造這種酒不需要花太多的時間，如果你願意冒險弄到些原料就成了。$B$B幫我弄五個雷鱗蜥蜴的閃電腺、一個巨型雷鷹的唾液腺和一個居住在貧瘠之地上的科多獸的肝臟來。$B$B我說過，這種酒很正點，就是我和你提到過的穴居怪麥酒。",objectives={"收集5個閃電腺、1個雷鷹的唾液腺和1個科多獸的肝臟，把它們交給棘齒城裡的釀酒師德羅恩。"}]])
R(823,"向奧戈尼爾報告",[[description="我們森金村這邊還有許多棘手的問題要解決，非常感謝你的幫助。但是你帶來的消息說明火刃氏族也許對所有人來說都是個大麻煩。$B$B剃刀嶺那裡有一處獸人營地，奧戈尼爾·魂痕就在那裡負責監視火刃氏族那一類的邪惡勢力。去跟他談一談，跟他說說我們目前的情況，還有你從試煉谷得到的消息，他肯定會大吃一驚的。$B$B剃刀嶺就在這裡的北邊。",objectives={"和剃刀嶺的奧戈尼爾·魂痕談話。"}]])
R(824,"陶土議會的耶努薩克雷",[[description="The Earthen Ring is a shamanistic group dedicated to studying and preserving the elements.  They have forgotten more about crazy old gods, ancient legends and lore than most scholars will ever know.$B$BLucky for you, I know someone in the Earthen Ring here in Ashenvale.  Head over to Zoram'gar Outpost on the coast of the Zoram Strand; show Je'neu Sancrea what you found.  If anyone can figure out that globe's significance, it'd be him.",objectives={"Bring the Befouled Water Globe to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale."}]])
R(825,"海底沈船",[[description="我得到消息說普勞德摩爾艦隊的殘骸仍在杜洛塔的近海，就在提拉加德城堡的東邊。$b$b與人類結盟的地精是一群粗俗的小東西，但是他們掌握著先進的機械技術。我們必須對任何潛在的敵人都瞭若指掌，同時我們的族人也可以從這些新知識中受益。$b$b$n，潛到那些沉船中，給我拿來聯盟使用的工具。",objectives={"剃刀嶺的加索克要你從海岸邊的艦隊殘骸中打撈出3件地精的工具。"}]])
R(826,"紮拉贊恩",[[description="巫醫札拉贊恩就住在東邊的回音群島上，那些島嶼曾經是我們的家園。$B$B札拉贊恩從那裡不斷派出他的爪牙來到這邊的大陸上，用妖術控制我們的同胞，將他們也變成札拉贊恩的傀儡。$B$B我們必須阻止他。$B$B打敗札拉贊恩和他的爪牙——那些曾經是我們的朋友和親人的暗矛食人妖。把札拉贊恩的頭給我帶回來，作為你已經斬殺了這個惡魔的證明。",objectives={"打敗札拉贊恩。$B$B殺死8個巫毒食人妖和8個妖術食人妖。$B$B把札拉贊恩的頭顱帶給加德林大師。"}]])
R(827,"骷髏石",[[description="$N.  The Burning Blade has infested the cave east of Orgrimmar known as Skull Rock.  Inside that cave they perform vile rituals, and burn their own flesh with Searing Collars.$B$BBy wearing these collars, I believe the cultists attune themselves to demonic power.  But to confirm this, I must have a collection of the collars to study.$B$BGo to Skull Rock and gather Searing Collars from the cultists you find there.  Bring them to me, and I will uncover their secrets.",objectives={"Gather Searing Collars from the cultists in Skull Rock.$B$BBring them to Margoz at his camp."}]])
R(828,"瑪高茲",[[description="One of our Shamans, Margoz, knows more of the Burning Blade's corruption.  He speaks of a cave called Skull Rock in the mountains - just outside Orgrimmar! - that shelters a large band of Burning Blade cultists.$B$BBefore you go to Skull Rock speak with Margoz.  He is wise and his council is valued.$B$BHe is camped to the northeast, between the coast and Drygulch Ravine.$B$BFollow his advice, but whatever Margoz says, $N, I still want you to crush those cultists!",objectives={"Speak with Margoz."}]])
R(829,"尼爾魯·火刃",[[description="The Searing Collars you brought me are powerful, demonic implements.  Divining their origin is, I'm afraid, beyond my skills as a shaman.  We will need a warlock to study them.$B$BTake a searing collar to Neeru Fireblade.  Although he is a skilled warlock, he professes to use his powers to thwart demons, and claims his research in the occult is benign.  Be that true or false, we may need his aid against the demonic cult in Durotar.$B$BYou may find Neeru in Orgrimmar in the Cleft of Shadow.",objectives={"Bring an Example Collar to Neeru Fireblade in Orgrimmar."}]])
R(830,"將軍的命令",[[description="你打開了陳舊褪色的信封，發現了一份看起來很正式的文件，上面蓋著普勞德摩爾將軍的徽記。$b$b這封信看起來很重要，剃刀嶺的指揮官加索克應該會對它感興趣。",objectives={"把普勞德摩爾將軍的命令帶給剃刀嶺的加索克。"}]])
R(831,"將軍的命令",[[description="人類是不可信的。我們和他們並肩作戰、疲憊不堪，但我們很明白，總有一天這幫傢伙會背叛我們。$b$b普勞德摩爾將軍死了，但這並沒有終止他的計畫，這個混蛋在他玩完之前就把一切都安排好了。$b$b本尼迪克上尉不會是最後一個威脅，天知道什麼時候普勞德摩爾的人會又一次從我們的海岸上登陸。我們要儘快讓奧格瑪的納茲格雷爾得知這些資訊！快去吧，你應該能在索爾的大廳裡找到他。",objectives={"把普勞德摩爾將軍的命令交給奧格瑪城中的納茲格雷爾，他就在索爾的大廳裡。"}]])
R(832,"燃影之眼",[[description="<你感受到飾物中傳來一個神秘的聲音>$B$B加祖茲？$B$B加祖茲...快回答！$B$B我們已經聽說你在骷髏石的發現。你必須立刻發動攻擊！$B$B加祖茲，我命令你趕快回答！否則我就把你的位置告訴尼爾魯·火刃，他會用最殘忍的手段來對付你。$B$B別對尼爾魯測試你的技能...$B$B...加祖茲，你在嗎...？",objectives={"把這顆燃影之眼帶給尼爾魯·火刃。"}]])
R(833,"神聖的墓地",[[description="赤色石是我們牛頭人最神聖的墓地，只有最勇敢的牛頭人才能得到在這裡安息的殊榮。這是給予那些幫助保衛雷霆崖和為部族的利益而付出生命的偉大戰士的無上榮譽。$b$b不過這段時間以來，有種邪惡的威脅正在接近我們的神聖領土。有一群刺背干涉者正在破壞我們的墓地，我的年紀太大了，無力把他們趕走。$b$b你一定要把他們驅逐出去，$n。",objectives={"博學者諾拉·暴雨圖騰要你在赤色石殺掉8個刺背干涉者。"}]])
R(834,"沙漠之風",[[description="我叫雷茲拉克，是加茲魯維的手下。他派我來這裡跟杜洛塔的獸人作生意……除了那些商隊以外，一切都進行得很順利，商隊的安全根本沒法保證！你知道嗎，這給我添了不少麻煩！$b$b上次發出的一批貨物——還說肯定能平安送達呢——結果被一票鷹身人從半道上給劫了去……它們好像是從那什麼烈風峽谷來的……$b$b反正，拿不到那批貨我就死定了！幫幫忙吧……沿著大峽谷向南走，你就會看到直接切入山壁東西兩面的溝壑。",objectives={"為奧格瑪城外的雷茲拉克取回5個裝滿貨物的袋子。"}]])
R(835,"保衛商路",[[description="Gazlowe told me once, \"Rezlak. There's one thing you need to know in life, and that's if you want something done well, do it yourself.\"$b$bI can't deal with losing all our caravans, so I'm just going to take matters into my own hands. Drygulch Ravine lies through the eastern part of Razorwind Canyon. If we kill all the harpies there, the routes will be safe.$b$bOf course, there was one other thing that Gazlowe taught me, and that's \"You can get anything done for a price.\" So, going to help me out, $n?",objectives={"Kill 12 Dustwind Savages and 8 Dustwind Storm Witches for Rezlak near Drygulch Ravine."}]])
R(836,"拯救OOX-09/HL！",[[description="The gnome's voice crackles once again from the robot:$B$B\"I need to move OOX-09/HL to an open, safe place so it can begin a lengthy take-off procedure.  It has built-in cloaking, but I need time on my end to make it operational again.  Escort the robot from its current location to, let's say, the shoreline beyond Overlook Cliff!  That should be a perfect place, and long enough, to get things online!\"$B$B\"Escort it safely to the shore, and then come talk to me in Booty Bay!  Oglethorpe Obnoticus - out!\"",objectives={"Escort OOX-09/HL to the shoreline beyond Overlook Cliff, then report to Oglethorpe Obnoticus in Booty Bay."}]])
R(837,"野豬人的進犯",[[description="我們剛來這裡的時候，鋼鬃野豬人已經佔據了大片的土地，讓我們頭疼不已。經過不斷的努力，我們已經將絕大部分的野豬人都驅逐出去，不過在某些地區還殘留著防衛良好的野豬人。$b$b但是，這種情況已經持續太久了，我們要保護自己，我們絕不能允許鋼鬃野豬人佔據我們的領土。野豬人的營地就在西邊，只要找到荊棘就可以找到牠們。今天，我們把他們趕出杜落塔，明天，我們就能把他們趕出整個卡林多。",objectives={"替剃刀嶺的加索克殺掉4個鋼鬃野豬人，4個鋼鬃斥候，4個鋼鬃傳令兵和4個鋼鬃衛兵。"}]])
R(838,"通靈學院",[[description="通靈學院坐落於凱爾達隆島，這所學校是天譴軍團的一座堡壘。我們的敵人就聚居在那裡，而且他們確實在鑽研讓力量增強的方法。有一扇堅固大門封住了唯一的入口，如果沒有一把合適的鑰匙，那我們無論如何都無法深入其內。$B$B一直以來，藥劑師迪瑟斯都負責與通靈學院有相關的事務，他應該知道如何才能獲得那把關鍵的鑰匙。你應該向我證明你確實有存在的價值，現在我賦予你這項任務，去跟迪瑟斯談談關於這件事的詳細情況吧。",objectives={"與西瘟疫之地亡靈壁壘的藥劑師迪瑟斯談話。"}]])
R(839,"<UNUSED>")
R(840,"部落的新兵",[[description="嗯，你看起來很強壯。$B$B是這樣的，我的好朋友卡加爾正在為貧瘠之地招募新兵。我知道你想為部落做點有用的事，這次你的機會來了。$B$B把這封募兵信交給卡加爾，看看他會不會簽字。",objectives={"沿著剃刀嶺西部的小路一直前進，過橋之後就可以進入貧瘠之地。$B$B在橋對面的獸人前哨找到卡加爾·戰痕，將你的募兵信交給他。"}]])
R(841,"另壹個能量源？",[[description="Let me guess - you didn't get whatever world-ending, nefarious deed you were doing done in time.  No wait, better still... you dropped it in the sand!  Well, whatever the reason, I do have additional power sources I will sell to you.  This time, however, it will cost you ten, YES TEN Wastewander Water Pouches!$B$BTimes are tough all around, $n, and power sources don't grow on trees!  Hrm, but what if they did.  Maybe we could MAKE a power source tree...",objectives={"Bring 10 Wastewander Water Pouches to Chief Engineer Bilgewhizzle in Gadgetzan in exchange for another power source."}]])
R(842,"十字路口征兵",[[description="把這份簽好的募兵函拿到十字路口去。$B$B那裡由瑟格拉·黑棘掌管，她是個噁心的薩滿，總喜歡在吩咐你去做正事之前跟你胡說一通，把你搞得頭暈腦脹。索爾覺得她是個人才，但我可不這麼想。$B$B小子，接下來的事情你就得自己決定了……",objectives={"從卡加爾的前哨站往西走。$B$B在T字路口左轉，然後朝南走。$B$B在十字路口的道路交匯處找尋瑟格拉·黑棘。"}]])
R(843,"加恩的報復",[[description="In solitude I wander these roads.$b$bThe dwarves of Bael Modan show no respect for my land. Horrendous blasts drive holes deep into the ground as noisy machines rip apart the hills. Lands which once served as home and provider to my tribe are now riddled with destructive dwarves.$b$bAttempts at reaching a diplomatic resolution have failed. Now is the time for decisive action.$b$bDrive the dwarves from the Bael Modan excavation by force and bring to me the journal of their leader, Prospector Khazgorm.",objectives={"Gann Stonespire wants you to kill 15 Bael'dun Excavators and 5 Bael'dun Foremen.$b$bBring Khazgorm's Journal to Gann Stonespire."}]])
R(844,"平原陸行鳥的威脅",[[description="你的第一個任務是非常簡單的。$B$B東邊的平原陸行鳥總是對我們的食物補給心懷鬼胎，它們已經成了十字路口的一大禍害。$B$B殺掉那些平原陸行鳥，把它們的鳥喙給我帶回來。",objectives={"收集7個陸行鳥的喙，把它們交給十字路口的瑟格拉·黑棘。"}]])
R(845,"斑馬的威脅",[[description="The zhevra, although not the fiercest beast in the Barrens, are a shade tougher than the plainstriders.  Don't worry -- we'll send you against bigger prey in good time, but for now your teeth could use a little more cutting.$B$BHunt the zhevra to the north and south, and collect their hooves.  Bring them to me and perhaps we'll next send you against something tougher.",objectives={"Slay Zhevra Runners to collect 4 Zhevra Hooves for Sergra Darkthorn in the Crossroads."}]])
R(846,"加恩的報復",[[description="It is clear the prospector depended on explosives and those noisy vehicles to rip the ground apart. We can expect a new foreman to take over soon.$b$bI want to give the dwarves a taste of their own medicine. According to these plans if we combine nitroglycerin with wood pulp and sodium nitrate we can create an explosive charge. The rifleman, soldiers and officers in the Keep are known to have the supplies.$b$bCollect these items and bring them to me. I will fashion a charge that the dwarves won't forget!",objectives={"Gann Stonespire wants you to bring him 6 vials of Nitroglycerin, 6 bundles of Wood Pulp, and 6 samples of Sodium Nitrate."}]])
R(847,"迅猛龍的狡詐",[[description="This... this power.... Is this the power of the shamans that Tor'gan tried to show me? I must say, it is interesting. Tell Tor'gan that he has convinced me... for the time being. I will listen to what he has to say.",objectives={"Speak with Tor'gan."}]])
R(848,"菌類孢子",[[description="The oases of the Barrens hide a mystery.  Life energy flows from their waters, invigorating the plants and beasts that drink it.$B$BInvigorating, and altering.$B$BThere is a mushroom that grows near these oases.  Its spores hold properties that we, the apothecaries of Lordaeron, find useful.$B$BBring me these spores and you will earn our gratitude.",objectives={"Bring 4 Fungal Spores to Apothecary Helbrim at the Crossroads."}]])
R(849,"加恩的報復",[[description="Following Khazgorm's plans it should be no problem to fashion an explosive charge$b$bAh, there we go.$b$bNow, $n, I am going to entrust you with a special task. Take this explosive stick and use it to blow up the flying machine at Bael Modan.$b$bNot only is the flying machine a key part of the site's infrastructure it also serves as a weapon of war. More importantly it is an icon of power and an insult to the memory of my tribe.$b$bMake me proud by completing this heroic task and you shall be rewarded.",objectives={"Destroy the flying machine at Bael Modan and return to Gann Stonespire."}]])
R(850,"科卡爾首領",[[description="半人馬的問題困擾著牛頭人已經很多年了，最近，貧瘠之地的科卡爾半人馬開始形成真正的威脅。通常他們散居在這片土地上，不過他們當中已經產生了新的首領，並把一盤散沙的半人馬集結在一起。$B$B為了保護我們的家園，必須要除掉這新的半人馬領袖。$B$B幫我把巴拉克·科多班恩的頭顱帶回來，他在北方的遺忘之池附近紮營。$B$B除掉他，然後再回到我這裡。",objectives={"把巴拉克的頭顱交給西十字路口的雷戈薩·死門。"}]])
R(851,"狂熱的維羅戈",[[description="The centaur Verog the Dervish wanders the Barrens, and will be difficult to find.  But he is based at the centaur command tent at the Stagnant Oasis to the southeast.  It may be possible to draw him to you.$B$BTravel to the Stagnant Oasis to the southeast and attack centaur near the command tent.  It will be dangerous, but if you can kill enough centaur then they should raise an alarm.  And Verog will come.$B$BBring me his head and I will place it with Barak Kodobane's.",objectives={"Bring Verog's Head to Regthar Deathgate, west of the Crossroads."}]])
R(852,"赫茲魯爾·血印",[[description="赫茲盧爾·血印是貧瘠之地的科卡爾半人馬的首領。他兇猛、殘忍，詭計多端。消滅他就可以瓦解半人馬部落，從而極大地削弱他們對我們的威脅。$B$B去殺了他。就像對付巴拉克和維羅戈那樣，帶回赫茲盧爾的頭顱。$B$B他和他的手下駐紮就在西南方的甜水綠洲一帶。",objectives={"把赫茲盧爾的頭顱交給十字路口的雷戈薩·死門。"}]])
R(853,"藥劑師紮瑪",[[description="I have rendered the spores you gave me into an emulsion.  I must now send it to my associate, Apothecary Zamah.  If you were to carry this to her, she can offer you something from our stores of alchemical goods.$B$BShe is in the Pools of Vision, a cave beneath the shamans of Thunder Bluff.  The path to this cave is well hidden, but you may find it on the Spirit Rise bluff.$B$BDo hurry.  This emulsion will maintain its potency for only a short time, and must be resealed and processed before then.",objectives={"Bring the Rendered Spores to Apothecary Zamah in Thunder Bluff, before the time limit is up."}]])
R(854,"十字路口之旅",[[description="I have foreseen your arrival, young $c. Though perhaps you are not so young anymore.$B$BI think that it is time for you to move deeper into this land. I can sense that you are destined for great things.$B$BIt is the Crossroads that you must seek out, for our lives with the orcs have become intertwined and they need assistance. Continue down this road towards the east and follow it north to the Crossroads. Find Thork within its walls, he has the Earthmother's blessing.",objectives={"Speak with Thork at the Crossroads in the Barrens."}]])
R(855,"半人馬護腕",[[description="在與科卡爾半人馬的戰鬥中，你已經證明了自己。不過，他們仍然是個威脅。這些半人馬的首領的死對我們來說是非常好的消息，不過你必須繼續削減他們軍隊的人數。$B$B為此我會交給你一項賞金任務。$B$B到科卡爾半人馬的領地去，幹掉他們的士兵，收集他們的半人馬護腕。當你能帶回足夠多的護腕的時候，部落會獎賞你的。",objectives={"收集15個半人馬護腕，把他們交給十字路口的雷戈薩·死門。"}]])
R(856,"<UNUSED>",[[description="Though you have reached the Barrens, your journey is not complete. You must continue on to the Crossroads, where you are needed most.$B$BFollow the road as you were, and turn left where the path gives you the choice. Follow it North until you see the walls of the Crossroads.$B$BJust before you enter, you should see the Ancestral Sage, he will have words of wisdom for you.",objectives={"Continue down the road from Camp Taurajo.$B$BTurn left at the T intersection and continue North.$B$BFollow the path to the Ancestral Sage outside the Crossroads."}]])
R(857,"眾月之淚",[[description="The power was mine! In my very hands! And I want it back! Back I say!$b$bThose dirty excavators uncovered it... so beautiful it was. Deemed the Tear of the Moons, it was the first great discovery we made at Bael Modan.$b$bIt should have been mine! Mine I say!$b$bGeneral Twinbraid grew jealous of the power it gave me. He locked it away in the Keep. Called it cursed, he did! The fool!$b$bOthers wanted it and they had to be stopped! That bastard Twinbraid drove me off.$b$bNow I want it back. Back I say!",objectives={"Feegly the Exiled wants you to retrieve for him the Tear of the Moons."}]])
R(858,"打火鑰匙",[[description="I don't suppose Sputtervalve sent you? I'm in a bind here. I hopped in without realizing that I need a key to unlock the shredder's movement column. One of the other shredder operators asked me if everything was okay, and I panicked! Instead of telling him that I was missing my key, I told him there was some sort of mechanical problem.$b$bWe need to get out of here on the double! Go up to the control room at the top of the derrick, the supervisor should have a key for this shredder.$b$bHelp me out here!",objectives={"Get the Ignition Key and bring it to Wizzlecrank."}]])
R(860,"瑟格拉·黑棘",[[description="If you wish to walk the hunter's path, then your journey leads to the Barrens.  Its beasts are strong-willed and fierce.  You will learn much by hunting there, and your spirit will grow.$B$BSpeak with Sergra Darkthorn.  She will be your first guide in the Barrens.$B$BSergra is at the Crossroads.  To reach her, travel east from Bloodhoof Village into the Barrens, then north as the road forks.  And have care as you travel--the Barrens holds great danger for the unprepared and unwary.",objectives={"Speak with Sergra Darkthorn at the Crossroads."}]])
R(861,"獵人之道",[[description="我看得出來你渴望探索。我也曾經渴望到處漫遊……$B$B漫遊和狩獵。狩獵是牛頭人最高的榮譽。$B$B如果你真想走獵人這條路的話，梅勒．石蹄可以給你一些指引，他就在雷霆崖的獵人高地上。$B$B要向他展示你的能力和決心，你就必須把莫高雷一帶的平原徘徊者的爪子帶去給他。平原徘徊者非常兇猛、狡猾－－對於一個想要成為獵人的年輕$c來說是最合適的獵物。",objectives={"收集4隻平原徘徊者的爪子給雷霆崖的梅勒·石蹄。"}]])
R(862,"掘地鼠燉肉",[[description="像你樣一個$c在貧瘠之地肯定會餓得前心貼後背，你看我，我就已經餓了整整一天了。$b$b我跟你說吧，我可以為你做一道大餐，不過得要先弄一些掘地鼠來。$b$b那些可惡的巴爾莫丹矮人幾乎把這裡的掘地鼠都給吃光了！你到南邊的巴爾莫丹去給我帶一些掘地鼠回來吧。$b$b如果你連這都搞不定的話，就不要再自稱是經驗豐富的冒險家了！",objectives={"給十字路口的格拉布弄到8隻掘地鼠。"}]])
R(863,"逃跑",[[description="I suppose I'll learn as we go... Couldn't be too hard. Just some buttons here, and a lever or two... Well, are you ready to go?",objectives={"Protect Wizzlecrank and the stolen goblin shredder on the way to Sputtervalve in Ratchet."}]])
R(864,"向藥劑師金格回報",[[description="\"Here you go, the power source is safely removed and the data is preserved.  Well, safe journeys and all that.  Hope the nefarious science experiment worked out for you and all.\"$B$BThe goblin turns away from you to attend to the demands of the Gadgetzan Water Company.  You secure the sealed testing kit for the journey back to the Undercity.  Apothecary Zinge waits for you and the sealed field testing kit there.",objectives={"Bring the Sealed Field Testing Kit to Apothecary Zinge in the Undercity."}]])
R(865,"迅猛龍角",[[description="貧瘠之地的迅猛龍比其他地區的迅猛龍更加聰明狡猾。我想它們的智慧就來自它們的角！如果是這樣的話，我可以將它們的角磨成粉末，製成「智慧飲料」。然後就能賣掉大賺一筆！！！$B$B我想你應該能幫我。從赤鱗鐮爪龍身上弄一些完整的迅猛龍角來。它們就在貧瘠之地的南部以及靠近梣谷森林邊界的貧瘠之地北部閒晃。",objectives={"從赤鱗鐮爪龍身上收集5根完整的迅猛龍角，把它們交給棘齒城的米希瑞克斯。"}]])
R(866,"根須樣本",[[description="The herbs of the Barrens are not quite like herbs in other lands.  Their properties are mostly the same, but the oasis water here alters the plants; they are just slightly different.$B$BI want to study those differences... to see if they're exploitable!$B$BIf you are skilled in herbalism, then gather root samples off the herbs you find in the Barrens.  Bring back these samples so that I may compare them with herbs from other regions.",objectives={"Bring 8 Root Samples to Mebok Mizzyrix in Ratchet."}]])
R(867,"鷹身強盜",[[description="這些該死的鷹身人長期以來不停地攻擊和掠奪我們的補給商隊。現在該是我們割斷她們喉嚨，削減她們數量的時候了。$B$B我一直在她們的巢穴附近細心觀察，已經確定了誰是她們的領導者。我們應該先以削弱她們的作戰力量為目標，這樣才能徹底擊敗她們。$B$B慢慢來，先去幹掉那些在西北方出沒的巫翼鷹身人和巫翼遊蕩者，然後幫我帶８隻巫翼鷹身人的爪子回來吧。這應該是一個不錯的開始……",objectives={"收集8隻巫翼鷹身人的爪子。$B$B把它們交給十字路口的達索克·快刀。"}]])
R(868,"蠍卵",[[description="嘿，$N，奧格瑪城裡的主人派我到十字路口來觀察這片土地並記錄這裡所發生的一切。$B$B我的目標之一是在巨人曠野南方出現的昆蟲狀生物。我們對這種生物知之甚少，所以我把它作為我的主要研究課題，希望能發現點什麼。它們似乎有超出一般生物的智慧。$B$B拿著這個掘地鏟，從土丘裡收集一些它們的卵。不過你要當心，這些生物一旦收到同伴的警報，就會立刻蜂擁而至。",objectives={"把12枚異種蠍卵和掘地爪交給十字路口的科蘭。"}]])
R(869,"偷錢的迅猛龍",[[description="Not long ago, a shipment of silver was stolen from our guard tower.  It was meant as payroll to the Crossroads' guards, and we want that silver back.$B$BThe strange thing is... we caught one of the thieves on the night of the theft.  And... it was a raptor!  Unbelievable!$B$BI don't know what raptors would want with silver.  But I don't care -- I want the raptors dead so they won't steal from us again!$B$BHunt raptors in the Barrens.  Collect for me their heads!",objectives={"Bring 12 Raptor Heads to Gazrog at the Crossroads."}]])
R(870,"遺忘之池",[[description="很久以前，貧瘠之地曾是個鬱鬱蔥蔥、生機盎然的地方。但是戰爭與災難接二連三地降臨在這片土地上，最後就剩下了這一片乾燥荒蕪的不毛之地。事實就是這樣，真讓我傷心。$B$B不過，在過去的幾年裡，貧瘠之地出現了新的綠洲，生機又在這片土地上重現。我們德魯伊感覺到了在很深的地下有一股試圖衝出地面的力量。$B$B我們必須找到這股力量的源泉，請到十字路口西北邊的遺忘之池去一趟，在那裡的湖水中搜尋力量的源泉，然後回到這裡來。",objectives={"向圖加·符文圖騰報告你的發現。"}]])
R(871,"野豬人的襲擊",[[description="All the quilboars are our enemies, $N. Some just prove to be more of a nuisance than others.$B$BThe Razormane tribe has been attacking our supply lines from Durotar, causing us no end of annoyance. I have scouts seeking the leader of these raids, but until then, any losses you can inflict on the filthy pig men would aid us.$B$BStart in the northeast towards Durotar. You can always tell their dens from the huge thorny vines that come up from the earth. Seek them out, and slay them.",objectives={"Of the Razormane tribe, kill 8 Water Seekers, 8 Thornweavers and 3 Hunters, and then return to Thork in the Crossroads."}]])
R(872,"野豬人的頭目",[[description="One of my scouts witnessed an attack on a caravan from Durotar, $N. The culprits are indeed the Razormane tribe of quilboars. One of the quilboars in particular is leading the raids: Kreenig Snarlsnout. He was seen northeast of here, just south of the road from Durotar. If the threat is to be ended, then Kreenig must die.$B$BTo be sure the attacks cease, though, I say we add insult to their injury. Kill Kreenig along with more of their tribe, and return to me when you have his tusk.",objectives={"Kill 8 Razormane Geomancers, 8 Razormane Defenders, and Kreenig Snarlsnout.$B$BThen bring Kreenig Snarlsnout's Tusk to Thork at the Crossroads."}]])
R(873,"依沙瓦克",[[description="偉大的依沙瓦克是這片水域的主宰，牠力大無窮、威武強悍。海岸上的人類都怕牠，因為已經有太多的人類被牠殺死。$B$B但我不怕牠，我很感激牠的存在，牠對我來說是一次很有價值的挑戰，一個值得尊敬的獵物。$B$B如果你準備好了，就到海裡去尋找海中的巨獸依沙瓦克吧。$B$B牠的靈魂深埋在牠的心臟之中，聽著牠跳動的聲音，你就能瞭解自己的命運。",objectives={"把依沙瓦克的心臟交給瑪倫·星眼。"}]])
R(874,"瑪倫·星眼",[[description="You have hunted the beasts of the Barrens.  Your spirit is strong.  But a hunter must always be prepared.  A true hunter can stalk prey down any path.  Mountains and swamps will not sway $ghim:her;.$B$BNot even the sea.$B$BFind my sister, Mahren.  She hunts the great water beasts along the coast.  She will be your teacher in their ways.$B$BBut be wary in your search for her, for the Barrens' coast is held by humans.",objectives={"Speak with Mahren Skyseer."}]])
R(875,"鷹身人首領",[[description="Hahaha, $n. Back for more? Good, I like to hear that.$B$BThis time I want you to assassinate some of the harpy lieutenants in the Dry Hills. Only Witchwing Slayers can be lieutenants, and you can tell them apart by the rings they carry. They are a nasty bunch, but they lead some of the underlings in that area. Taking out 6 of them will be a decisive strike against their matriarchy.$B$BMake sure they die painfully, $n. We want those harpy wenches to know the idiocy of picking fights with the Horde.",objectives={"Collect 6 Harpy Lieutenant Rings from Witchwing Slayers and return them to Darsok Swiftdagger at the Crossroads."}]])
R(876,"塞瑞娜·血羽",[[description="你在上次與鷹身人首領的戰鬥中表現得十分出色，所以我希望由你來幫我做最後一件事。$B$B塞瑞娜·血羽是很久前被雷克薩殺死的鷹身人族長的妹妹。顯然，這些針對部落商隊的襲擊是她對我們採取的報復行為。$B$B你的任務就是割開她的喉嚨，把她的頭顱帶給我。我將會把她的頭顱掛在下一次發出的商隊的車頂上……讓那些鷹身人好好看看跟部落作對的下場。",objectives={"殺掉塞瑞娜·血羽，把她的頭顱交給十字路口的達索克·快刀。"}]])
R(877,"死水綠洲",[[description="Like the one you found at the Forgotten Pools, there may be fissures at the other oases in the Barrens.  If so, then perhaps the fissures are the oases' source of life.$B$BWe must test this.$B$BHere, take these seeds.  They are dead and infertile, but take them to the Stagnant Oasis to the southeast.  If there is a fissure there, then place the seeds within it...and observe.",objectives={"Return to Tonga at The Crossroads, after investigating the Stagnant Oasis."}]])
R(878,"野豬人的內戰",[[description="你必須殺了我的敵人。<豬哼聲>你必須幫助碎牙，幫助鋼鬃野豬人。我們的部族都非常依賴自己的精神領袖——他們可以召喚大地的力量，<豬哼聲>使他們讓野豬人的部族變得強大……<豬哼聲>$B$B如果你想要知道是誰頻繁對部落<豬哼聲>發動襲擊，那你就應該幫助碎牙！你去殺了刺背野豬人的精神領袖，削弱他們，這樣鋼鬃野豬人就可以打敗他們，統治貧瘠之地了！",objectives={"殺掉6個刺背尋水者、12個刺背織棘者和12個刺背地卜師，然後到陶拉祖營地的碎牙那裡覆命。"}]])
R(879,"內奸",[[description="Three of my tribe came out of the Kraul to lead the raids against the Horde, $r. <snort> They are ruthless and cunning, and if you defeat them, then your Crossroads and even most of the Barrens will learn peace... <snort> at least from the Razormane tribe. <snort>$B$BNak, Kuz, and Lok Orcbane are the ones you seek. They are far to the south  of the Barrens. One is a spell caster, another a tracker, and their leader, the one called Orcbane, <snort> a warrior. Kill them, $r, like they have killed me.",objectives={"Kill Nak, Kuz, and Lok Orcbane and bring their skulls to Mangletooth at Camp Taurajo in the Barrens."}]])
R(880,"變異的生物",[[description="Your findings are incredible, $N.  These oases hold properties that must come from an outside source.  Or perhaps an inside one.$B$BI want to know how these fissures are affecting the beasts who drink from the oases' water.$B$BHunt oasis snapjaws at the Lushwater and Stagnant Oases.  Bring me their shells so I may examine them.",objectives={"Bring 8 Altered Snapjaw Shells to Tonga Runetotem at the Crossroads."}]])
R(881,"埃其亞基",[[description="白霧，也就是我們所說的埃其亞基，是草原獅的首領。它在捕食獵物時悄無聲息地行動，就像大地上浮起的一層薄薄的白霧。它的每次出擊都是一擊斃命，它的獵物甚至來不及恐懼和痛苦就已魂飛魄散。$B$B你會體會到的，因為我要讓你去獵殺埃其亞基。它的巢穴就在十字路口的東北邊，在那些巨大的科多獸骨附近。$B$B去吧，當你走到它的巢穴附近時，就吹響這個號角，它正在等著你呢。",objectives={"把埃其亞基的皮交給十字路口的瑟格拉·黑棘。"}]])
R(882,"伊沙姆哈爾",[[description="伊沙姆哈爾是貧瘠之地最兇猛殘忍的赤鱗龍，它狩獵並不是為了健身或是食物，而是因為狩獵是它最大的愛好，伊沙姆哈爾天生就是個殺手。$B$B$N，你會瞭解到它的天性的，因為你很快就要動身去追蹤這條赤鱗龍了。$B$B開始這次獵殺行動吧。先去殺死一隻它最喜歡捕獵的動物——斑馬，然後把斑馬肉掛在棘齒城西北邊的枯樹上。當伊沙姆哈爾聞到肉味的時候，它就會出現的。$B$B那時，你可要做好準備。",objectives={"把伊沙姆哈爾的牙齒交給陶拉祖營地的喬恩。"}]])
R(883,"拉克塔曼尼",[[description="拉克塔曼尼的蹄子是科多獸力量的象徵。",objectives={"把拉克塔曼尼的蹄子交給陶拉祖營地的喬恩。"}]])
R(884,"奧瓦坦卡",[[description="只要一被觸及，奧瓦坦卡的尾刺就會閃爍起火花。",objectives={"把奧瓦坦卡的尾刺交給陶拉祖營地的喬恩。"}]])
R(885,"瓦希塔帕恩",[[description="僅僅是輕輕觸碰一下瓦希塔帕恩的羽毛，你都會感到相當刺痛。",objectives={"把瓦希塔帕恩的羽毛交給陶拉祖營地的喬恩·星眼。"}]])
R(886,"貧瘠之地的綠洲",[[description="雷霆崖的德魯伊們感到有一股奇怪的力量正在滲入莫高雷東邊的貧瘠之地。$B$B圖加·符文圖騰已經被派去查找這股力量的來源了，但是我們擔心他可能需要更多的幫助。$B$B到貧瘠之地去和圖加談談吧，他應該就在十字路口。從血蹄村一直往東走就可以進入貧瘠之地，在路口向北轉，然後繼續往北走，很快就到十字路口了。$B$B記得一直在路上走，$N，貧瘠之地是一塊非常危險的土地。",objectives={"和十字路口的圖加·符文圖騰談話。"}]])
R(887,"南海海盜",[[description="我當然希望格雷茲里克中將能夠保護我們在這片海域上來來往往的商船。貿易巨頭們向商船艦隊裡砸了這麼多的金子進來，而這些海盜卻在胡作非為，襲擊我的船隻，還偷走了我的貨物！$b$b我聽說南海海盜就在南方的海岸邊紮營，他們可以說是我的眼中釘肉中刺，假如格雷茲里克搞不定他們，也許你能幫我除掉他們。",objectives={"幫棘齒城的加茲魯維殺死12個南海歹徒和6個南海炮兵。"}]])
R(888,"被竊的貨物",[[description="我希望取回所有丟失的貨物，但我想那不太可能。不過，有些貨物是我必須要取回的！$b$b正如你所見的，我的天文臺馬上就要建好了，現在只差兩塊鏡片中較小的一塊。第一塊已由杜洛塔的商隊運到，第二塊運上了船，但現在還沒有到。對了，我還沒有收到藏寶海灣的崔斯里克給我發來的靴子！$b$b到海盜營地去一趟，看看能不能找到這些貨物吧。",objectives={"幫棘齒城的加茲魯維取回一箱靴子以及一塊望遠鏡片。"}]])
R(889,"風之魂")
R(890,"丟失的貨物",[[description="I've been waiting forever for my last shipment of goods from Booty Bay! I'm pretty sure that it must have been stolen by the Freebooters, but just to make sure, will you go down to the dockside and ask Dizzywig if my goods were already put into my warehouse without my knowledge?$b$bHere, take my ledger down to Dizzywig and have him double check my inventory records against his logs.",objectives={"Bring Gazlowe's Ledger to Wharfmaster Dizzywig."}]])
R(891,"北方城堡的火炮",[[description="我又有一艘船被北方城堡裡的那些狂熱的人類給擊沉了！$b$b到了該和那幫混蛋算帳的時候了。他們的偏執讓他們變成了一群瘋子。為了取樂，這些不計後果的呆瓜向每一個進入他們視野的目標開火。$b$b從這裡向南走，沿著商旅海岸就可以抵達北方城堡，幹掉他們的人，然後把他們士兵的徽章給我拿回來作為證明。為了我心愛的艦隊，你必須殺了法莫斯隊長和她那些瘋狂的炮兵！",objectives={"棘齒城中的沙羅薩斯船長要你收集10枚塞拉摩徽章並幹掉法莫斯隊長、炮兵維桑恩和炮兵斯密瑟。"}]])
R(892,"丟失的貨物",[[description="Everything looks square from my records, $n. Go on back and tell Gazlowe he's out of luck. I wouldn't be surprised if it was the pirates that nabbed his goodies.$b$bNothing else I can do for him. Oh... though you could tell him that I've got some things from Undermine for him, when he has the time to come pick them up.",objectives={"Return Gazlowe's Ledger to Gazlowe in Ratchet."}]])
R(893,"野豬人的武器",[[description="The Razormane quilboars to the south, beyond the Field of Giants, have no skilled blacksmiths from what I am told, but they've apparently started to develop sturdier weapons. I'd like to get my hands on a few different types to learn their techniques if possible.$B$BIf you wish to help bring honor to the Horde, then bring me examples of their weapons. Find me a dagger from their stalkers, a wand from their seers, and a shield from their warfrenzy. That should do nicely!",objectives={"Bring a Razormane Backstabber, a Charred Razormane Wand and a Razormane War Shield to Tatternack Steelforge at Camp Taurajo in the Barrens."}]])
R(894,"什麽什麽平衡器",[[description="風險投資公司最近在北邊設立了小型的研究設備，就在淤泥沼澤的西南部。我對他們在做的東西並不瞭解，只知道他們正在試驗一種名叫「主動式負載平衡器」的裝備。$b$b那個主動式負載平衡器到底是什麼東西呢？不管它是什麼，我都想研究研究它，所以我需要找個人來幫我把它弄到手。$b$b我手裡有控制系統操作手冊的副本，你應該知道該怎麼把那什麼平衡器卸下來。",objectives={"在風險投資公司研究基地裡找到控制台。"}]])
R(895,"通緝：巴隆·朗紹爾",[[description="通緝令！$b$b巴隆·朗紹爾，破浪號的船長$b$b吉爾尼斯的朗紹爾船長統領南海海盜橫行海上，現因海盜罪名指控被通緝。領取獎賞者必須提供足以證明自己殺掉了巴隆·郎紹爾的證據！$b$b——加茲魯維",objectives={"把巴隆·朗紹爾的頭顱交給棘齒城的加茲魯維。"}]])
R(896,"礦工的寶貝",[[description="作為像棘齒城這麼繁忙的碼頭的管理者，我始終關注著每一條有利可圖的消息。我知道這裡與藏寶海灣的所有物品和貨幣的交易情況。$b$b最近我聽到了一些消息，是關於風險投資公司在淤泥沼澤東北的石礦坑的。有個礦工挖出了一枚足有拳頭大小的翡翠石。我知道有一些買主肯掏錢買那麼大的一塊寶石，如果你幫我搞到那塊寶石的話，那麼我願意和你五五分成，你看怎麼樣？",objectives={"從風險投資公司的某個監督或者執行者那裡奪取貓眼翡翠，然後把它交給棘齒城的碼頭管理員迪茲維格。"}]])
R(897,"收割者",[[description="這種奇特的昆蟲狀生物看起來仿佛不是貧瘠之地的生物，而更像是個天外來物。",objectives={"把收割者的頭顱交給喬恩·星眼。"}]])
R(898,"逃離監牢",[[description="Finally! Someone to rescue me!$b$bI can't believe you got past the guards. These zealots from Theramore are out of their minds. They sank our ship and imprisoned me, the only survivor. I was called an enemy and threat to the Alliance.$b$bMe! A threat to their great sham of an Alliance? I was a deckhand on a moonshine transport between Ratchet and Booty Bay.$b$bEnough talk. Help me get back to Ratchet will you? Let me know when you're ready and we'll make our break.",objectives={"Safely escort Gilthares Firebough back to Captain Brightsun in Ratchet."}]])
R(899,"復仇的怒火",[[description="我的全家都被刺背野豬人殺害了，$c。也許你能體會這種失去親人的傷痛，也許你不能……每天我都等在這裡，從日出到日落，尋找這些罪無可赦的惡魔。$B$B從那天起，除了關在那邊的俘虜之外，我見一個野豬人就殺一個。但這依然遠遠無法平息我復仇的欲望。$B$B我想你這個$c能夠幫助我。$B$B去殺掉那些野豬人，能殺多少就殺多少。帶回它們的獠牙，讓我們一起為它們的死亡而慶賀吧。",objectives={"收集60根刺背野豬人的獠牙，把它們交給十字路口的曼寇里克。"}]])
R(900,"什麽什麽平衡器",[[description="The three control valves are currently opened. The various readings on the control panel lead you to presume that they must be shut off before the apparatus can be shut off.",objectives={"Close off the Fuel Control Valve, the Regulator Valve and the Main Control Valve then use the control console again."}]])
R(901,"什麽什麽平衡器",[[description="With the apparatus deactivated, the control panel can be opened up and the samophlange removed from the console. With everything else in place, all that is left is to acquire the key to unlock the console.",objectives={"Get the Console Key from Tinkerer Sniggles to use on the control console."}]])
R(902,"什麽什麽平衡器",[[description="揭開控制台的蓋子之後，你看見了密密麻麻纏繞在一起的電線、管子和其他各種奇形怪狀的機械裝備——其中大多數看起來沒有什麼實際用途。你把它們撥向一邊，在控制台的最裡邊找到了主動式負載平衡器。一隻機械臂把它從機架上拽了出來。",objectives={"把主動式負載平衡器交給棘齒城的斯布特瓦夫。"}]])
R(903,"草原上的徘徊者",[[description="Now it's time to go after something that really bites.  The prowlers of the Barrens are a tough breed.  Tough, resourceful, sly... and deadly.  You'll find them among the tall grasses.  You'll find many to the southwest of the Crossroads.$B$BBe wary as you hunt them, $n, or you may find yourself no longer the predator, but instead the prey.",objectives={"Collect 7 Prowler Claws from Savannah Prowlers for Sergra Darkthorn in the Crossroads."}]])
R(904,"<UNUSED>")
R(905,"狂暴的鐮爪龍",[[description="$n，你要做的下一步事情是打敗你的獵物，並找到它們的巢穴。$B$B去獵殺南邊的赤鱗迅猛龍，然後拿走它們戴著的羽毛。把羽毛放在死水綠洲西南邊的赤鐮龍巢穴裡，讓它們知道你無所畏懼！",objectives={"殺死赤鱗迅猛龍並收集它們的羽毛，把這些羽毛放在3個赤鱗鐮爪龍的巢穴裡，然後返回十字路口的瑟格拉·黑棘那裡。"}]])
R(906,"內奸",[[description="Take Lok's head to Thork in the Crossroads, $r. <snort> He should know what has happened to my tribe without any words--ha, not that he would believe Mangletooth helped in <snort> such things. But I am sure he'll reward you for carrying out such a great deed. <snort>$B$BI will continue to bless you with Agamaggan's power for as long as I remain in this cage, $r. Until then, farewell.",objectives={"Bring Lok's Skull to Thork at the Crossroads in the Barrens."}]])
R(907,"被激怒的雷霆蜥蜴",[[description="Now, $N, you must face the great thunder lizards.  So large are the beasts, the ground rumbles as they stomp across the plains.  Take care as you fight them, for one false step and you may find yourself beneath their feet.$B$BYou will find the thunder lizards in the southern Barrens.  They are known as Stormsnouts, Stormhides and Thunderheads.  Return to me after you have bested them.",objectives={"Bring 3 Thunder Lizard Blood to Jorn Skyseer at Camp Taurajo."}]])
R(908,"废墟之间",[[description="暮光之锤已经进入了黑暗深渊中的月光神殿废墟里去了，他们的目标肯定是要强迫元素生物来对付我们。如果我们不及早采取对策的话，这个地区就将永远被他们控制。到黑暗深渊去找到废墟中的深渊之石，它应该在靠近水边的地方。深渊之石里面是深渊之核——那里面记载了所有元素生物的历史。如果我拥有了它，我和大地之环就能阻止他们了！ ",objectives={"把深渊之核交给灰谷佐拉姆加前哨站里的耶努萨克雷。 "}]])
R(909,"阿奎尼斯男爵",[[description="The defeated water elemental has left behind a strange water globe.  You surmise that the object somehow fed the beast energy.  Inside the globe, a putrid-looking form of water sloshes about.  The globe itself seems impervious to any sort of physical force.$B$BIf anyone can make any sense of this item, it would be Je'neu Sancrea of the Earthen Ring.  He is located at the Horde's Zoram'gar Outpost in Ashenvale.",objectives={"Bring the Strange Water Globe to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale."}]])
R(910,"降帆靠港",[[description="I have heard tales of the mighty ships that sail between Ratchet and Booty Bay!  That would be so cool to sail on the ocean and fight in many great sea battles.  Maybe I will be a mighty Horde sailor when I grow up!  Yeah!$B$BWould you take me to see the Ratchet docks, please?  I promise I won't get into the water or cause any trouble - I just want to see the big boats and smell the salty sea water!  Yeah!",objectives={"Take your ward to the docks of Ratchet in the Barrens."}]])
R(911,"前線之門",[[description="They say that Ashenvale is the new frontier, and that the Mor'shan Rampart in the Barrens is the gateway to it.  That would be so cool to be a pioneer, carving everything you need out of the untamed wilds!  They say that this is where the Horde and Alliance will clash the most in the future, and I want to be there $N!$B$BWould you take me to the Mor'shan Rampart so I can see what the frontier looks like, please?  I wanna see where the Horde is driving out those smelly night elves!",objectives={"Take your ward to the Mor'shan Rampart in the northern part of the Barrens, just before entering Ashenvale."}]])
R(912,"Stonesplinter Trogg Disguise")
R(913,"雷鷹的嘶鳴",[[description="The thunderhawk, $N, is a fierce beast.  It is time for you to face them.  You must find where it roams, and bring me its wings as proof of your successful hunt.$B$BDo this, and your time with me will near its end.",objectives={"Find and slay a Thunderhawk, return its wings to Jorn Skyseer at Camp Taurajo."}]])
R(914,"尖牙德魯伊",[[description="The druids in the Wailing Caverns, the Druids of the Fang, are an aberration.  They were part of an order of noble druids whose plan was to heal the Barrens, but now seek to remake that land to match their own, twisted dreams.$B$BThe Druids of the Fang have four leaders, and each possesses a dream gem.  Even now their faces haunt me!  Defeat the leaders and bring me their gems, and the Barrens may again know peace.$B$BGo, $N.  You will find them lurking deep within the Wailing Caverns.",objectives={"Bring the Gems of Cobrahn, Anacondra, Pythas and Serpentis to Nara Wildmane in Thunder Bluff."}]])
R(915,"草莓冰淇淋",[[description="ICE CREAM!  Oh please please please could you get me some ice cream?!  Strawberry is my favorite flavor, and there's no better strawberry ice cream in the world than Tigule and Foror's Strawberry Ice Cream!  It's my favorite ice cream in the whole wide world!$B$BI had it once a long time ago when I was at the Shimmering Flats race track, but I heard that they might be selling them in town now!  Please?  Pretty please?  With Tigule and Foror's Strawberry Ice Cream on top??!?!",objectives={"Get some Strawberry Ice Cream for your ward.  The lad seems to prefer Tigule and Foror's brand ice cream."}]])
R(916,"樹林蜘蛛的毒囊",[[description="我是為了觀察居住在影絲洞的樹林蜘蛛才來到幽影谷的。這些森林蜘蛛是另一種體型更小的蜘蛛的近親；我相信世界之樹在它們身上產生某些特殊的影響，我需要一些樣本來研究它們以證實這一點。$B$B首先，我需要一些它們的毒液，幫我從這些蜘蛛身上收集一些樹林蜘蛛的毒囊吧，它們就在北方的影絲洞一帶活動。有了毒囊，我就可以研究一下這種毒與它們的近親體內的劇毒有何相似之處。",objectives={"給奧達希爾的基爾沙蘭·風行者帶回10個樹林蜘蛛的毒囊。"}]])
R(917,"樹林蜘蛛的卵",[[description="現在我已經有蜘蛛的毒液了，我還需要一些活體樣本來進行研究。不幸的是，抓一隻活的巨型蜘蛛對你來說也許太困難了，年輕的$c。而且，我也沒辦法處理一隻巨型蜘蛛！$B$B但是如果你能找到一枚還未孵化的蜘蛛卵，然後從卵裡提取樣本，應該會容易多了，而且我也能處理卵中未孵化的蜘蛛。$B$B在影絲洞的深處一定有蜘蛛的巢穴。拜託了，幫我到那裡去找一枚蜘蛛卵吧。",objectives={"帶1枚樹林蜘蛛的卵回來給奧達希爾的基爾莎蘭。"}]])
R(918,"林精的種子",[[description="泰達希爾的林精是代表自然的元素生物，它們以某種方式反映了我們這裡的自然生態的情況。$B$B所以看到林精變得如此憤怒真讓人感到擔憂。$B$B我相信這與土壤有關。我一直在用不同的方法種植植物，可以用林精的種子來試驗一下。我請求你，能在奧拉密斯湖周圍的林精那兒收集一些種子給我嗎？",objectives={"給奧拉密斯湖邊的德納蘭帶去8粒林精的種子。"}]])
R(919,"林精的新芽",[[description="小林精在奧拉密斯湖周圍和湧泉湖以西迅速成長。我害怕它們會的數量會多到無法控制——我們應該在它們惹出亂子之前把它們從土地上清除。$B$B你在湖邊行走的時候，如果看到任何林精的新芽長出來，就順便除掉它。讓我們的土地免受污染！",objectives={"給奧拉密斯湖邊的德納蘭帶去12個林精的新芽。"}]])
R(920,"特納隆的召喚",[[description="你叫$n，沒錯吧？我聽說特納隆大人正在找你。你可以在奧達希爾樹冠的最頂層找到他。$b$b雖然我們的生命近乎無限，可你最好別讓他等得太久。",objectives={"與奧達希爾頂部的特納隆·雷拳交談。"}]])
R(921,"大地之冠",[[description="是該出發去追尋並探索你的自己的命運了，$n。但是在你走出我們美麗的森林之前，你應該首先好好瞭解我們近代的歷史。$b$b自海加爾山戰役之後，我們的族人改變了許多。因為消耗了全部的力量來擊敗阿克蒙德並趕走燃燒軍團，諾達希爾再度被暗淡的陰影籠罩……$b$b有一個你必須去完成的任務，到奧達希爾北邊的月井裡裝一瓶水，然後把它拿回來給我。",objectives={"裝滿水晶瓶並將其帶回給奧達希爾頂部的特納隆·雷拳。"}]])
R(922,"雷利亞·綠樹",[[description="$N，你能給我的朋友雷利亞·綠樹帶去一粒種子嗎？他是個住在達納蘇斯的德魯伊，我們上次談話時，他對我的林精研究工作很感興趣。他有自己的想法，如果有粒可以用來作試驗的種子的話，他一定會非常感激的。$B$B謝謝你，$N。你幫了我一個大忙。希望有一天你能看到我的勞動成果。",objectives={"給達納蘇斯的雷利亞·綠樹帶去一粒林精的種子。"}]])
R(923,"青苔之瘤",[[description="一種邪惡的力量正在森林中滋生。我們到處尋找邪惡之源，但當我們找到的時候……為了泰達希爾的安全，我們必須消滅掉那些已經無法挽救的林精。生長在泰達希爾北部的湧泉湖的林精所受的污染最為嚴重，你必須消滅它們！$B$B消滅在那裡發現的林精，收集生長在它們身上的青苔之瘤，然後把那些瘤交給我，讓我燒掉它們。",objectives={"收集5個青苔之瘤，然後把它們交給達納蘇斯的雷利亞·綠樹。"}]])
R(924,"惡魔之種",[[description="The Demon Seed is a powerful tool for the Burning Legion. It rests in a cave on Dreadmist Peak, above a demonic altar of fire.$B$BI have prepared power stones that when placed near the Seed will disrupt its connection to the Legion.$B$BTake a stone from the table and bring it to the altar of fire atop Dreadmist Peak. Travel west, then north when the road forks. The Peak will be to your left. The safest climb to the top is on its northern face.$B$BAnd hurry--the stone's power will consume itself in time.",objectives={"Grab a Flawed Power Stone.  Bring it to the Altar of Fire before the stone expires, then return to Ak'Zeloth."}]])
R(925,"凱恩的蹄印",[[description="They say that Cairne Bloodhoof is one of the greatest heroes the Horde has ever seen.  When I grow up, I wanna be a hero of the Horde too!$B$BDo you know Cairne, $N?  Could you do me a favor, please?  Could you get his hoofprint for me?  I dunno how to ask him, and he'd probably be too busy for someone like me... but you!  You're an adventurer just like he is!  I bet he'd give you his hoofprint easy!$B$BPlease?",objectives={"Travel to Thunder Bluff to see about getting Cairne Bloodhoof's hoofprint for your ward."}]])
R(926,"有瑕疵的能量石")
R(927,"布滿苔蘚的心臟",[[description="惡臭的黑苔獸的心臟上長滿了又黑又油膩的苔蘚。事實上，如果它沒有那緩慢而有節奏的心跳，也許你根本就看不出這是顆心臟來。$B$B也許德納蘭會想要研究一下這顆心臟。",objectives={"將佈滿苔蘚的心臟交給奧拉密斯湖畔的德納蘭。"}]])
R(928,"大地之冠",[[description="關於月井和泰達希爾的點點滴滴實在是太多了，我無法一一告知給你，這需要你自己去探索。科瑞薩斯·月怒正在等著你。我已經把你所帶回來的水倒入了這個容器中，把它送到科瑞薩斯那裡去吧。$b$b出發吧，科瑞薩斯就在多蘭納爾的月井旁。你只需要沿著奧達希爾南邊的小路走出幽影谷，沿著鵝卵石鋪成的小路一直走，然後向西轉就行了。$b$b注意，你要一直沿著路走，$n。最近路旁的森林裡出現了許多危險的野獸。",objectives={"將裝著半瓶水的瓶子交給多蘭納爾的科瑞薩斯·月怒。"}]])
R(929,"大地之冠",[[description="首先，讓我告訴你必須要完成的任務的其他一些細節。達納蘇斯的德魯伊需要使用泰達希爾的月井的水，所以月井的水需要不斷地補充。使用這種特製的瓶子，你可以收集起月井之水。$b$b帶著這個瓶子去東邊的星風村，裝滿村外的月井裡的水，再帶回來給我。你完成任務之後，我將繼續講述台納隆的故事……",objectives={"用月井的水裝滿翡翠瓶，然後把它交給多蘭納爾的科瑞薩斯·月怒。"}]])
R(930,"發光的水果",[[description="一顆又大又圓的果實掛在葉下。$B$B你覺得德納蘭一定會想要研究一下這東西。",objectives={"把這顆發光的水果交給奧拉密斯湖的德納蘭。"}]])
R(931,"發光的樹葉",[[description="植物上的葉子泛著微弱的光，產生了一種不斷變化的光暈。$B$B你覺得德納蘭可能會想要研究這種東西。",objectives={"給奧拉密斯湖畔的德納蘭帶去1片發光的樹葉。"}]])
R(932,"扭曲的仇恨",[[description="$n，你必須提高警惕，我們不能對這件事袖手旁觀。薩特就夠我們頭疼的了，而眼前的這件事更是火燒眉毛。$B$B有個名叫邁雷納斯的惡棍就住在附近的地獄石洞穴裡，他在那兒聚集了一大批驍勇的戰士為自己賣命，他的心如無月的夜晚一般黑暗，他目前正在密謀著一些極端邪惡的勾當。$B$B到這裡北邊的洞穴去找他，帶他的頭來見我。",objectives={"殺掉邁雷納斯，帶他的頭去見多蘭納爾的塔隆凱·捷根。"}]])
R(933,"大地之冠",[[description="在達納蘇斯城門的東南方還有一口月井，就在亞里斯瑞恩之池的岸邊。由於瘤骨熊怪的數量無節制地增長，以及他們對於這個地區的瘋狂攻擊，哨兵們根本無法有效地控制這一地區。$b$b在尋找月井的時候小心點，一定要時刻握緊你的武器。",objectives={"用月井的水裝滿紅玉瓶，然後把它交給多蘭納爾的科瑞薩斯·月怒。"}]])
R(934,"大地之冠",[[description="All was not well with Teldrassil, however. Staghelm's carefully made plans for the new World Tree had borne out as he had hoped, but there was one small problem, a problem to which many of the troubles on Teldrassil may be attributed.$b$bHowever, I will not get into that yet. You must visit the last moonwell, to the northwest in the Oracle Glade. Under the boughs of the Oracle Tree lies the first and most powerful of our wells. Retrieve a phial of its water and return to me.",objectives={"Fill the Amethyst Phial and bring it back to Corithras Moonrage in Dolanaar."}]])
R(935,"大地之冠",[[description="沒有生命守縛者雅立史卓莎和時間之王諾茲多姆的祝福，泰達希爾的成長就很難一帆風順。我不斷收到有奇怪的猛獸出現的報告，而瘋狂的熊怪也開始不斷地襲擊路人。$b$b我只能希望大德魯伊們能儘快找到解決的方法。我會將把你帶來的所有月井水都灌入這個瓶中，然後讓你把它帶到達納蘇斯去。$b$b把這只瓶子交給范達爾·鹿盔，你可以在德魯伊之林裡找到他。",objectives={"將裝滿月井水的瓶子帶給在達納蘇斯的大德魯伊范達爾·鹿盔。"}]])
R(936,"協助大德魯伊",[[description="打擾一下，$c，如果可能的話，我想佔用你一點時間。$B$B雷霆崖的塞納里奧議會希望能找到像你這樣經驗豐富的冒險家來幫助他們進行一項重要的研究項目。雖然我不知道詳細的情況，但是我可以告訴你，正是哈繆爾·符文圖騰親自負責這項研究。$B$B要是你感興趣的話，請直接去雷霆崖的長者高地找他談談。",objectives={"與雷霆崖的大德魯伊哈繆爾·符文圖騰談話。"}]])
R(937,"神諭林地",[[description="我和一個哨兵小組被派到這裡來保護神諭之樹免受鷹身人的威脅。它們已經在沼澤周圍建造了很多巢穴，我們正在試著把它們趕回去。$b$b神諭之樹曾派信差到達納蘇斯去通報這一情況，但一群鷹身人在中途殺死了那個信差。$b$b如果你認為你能勝任這項任務的話，就到它們的巢穴裡去，殺死它們，把它們的腰帶拿回來作為證明。",objectives={"收集6條血羽腰帶，把它們交給神諭林地裡的哨兵阿瑞尼亞·碎雲。"}]])
R(938,"密斯特",[[description="這隻獵豹的毛皮是很特別的暗灰色，與四周的森林幾乎融為一體。她靜靜地躺在地上，你發現她傷得很重，背部和腹部都有很深的傷口。$b$b她抬起頭盯著你，藍色的雙眼閃著智慧的光芒。她似乎希望跟隨你。",objectives={"護送密斯特去神諭之樹附近的月井旁找哨兵阿瑞尼亞·碎雲。"}]])
R(939,"薩瓦裏克長笛",[[description="You study the simple wooden flute you picked up after defeating Xavaric.$B$BThe knotted wood feels solid, but it seems as if the spirals and patterns in the surface begin to spin and move as you turn it over in your hands. Suddenly, you feel a sense of dread...$B$BYou shake your head, sure that your mind is playing tricks on you.$B$BIt's possible that other satyrs carry clues as to what you have found. Bring your findings to the druid, Eridan Bluewind, that lives in southern Felwood.",objectives={"Bring the Flute of Xavaric and 5 Jadefire Felbind samples to Eridan Bluewind in southern Felwood."}]])
R(940,"泰達希爾",[[description="The forest whispers of your feats of valor, $n. As I felt the harpies forced from their nests, a greater calm spread across the forest, its creatures once again feeling safe. I have feared sending another messenger to the Arch Druid, but I know that you will see my message safely to him.$b$bDeliver this to him and know that the forest will see you safely along its paths to the forest of stone.",objectives={"Deliver the Oracle Tree's report to Arch Druid Fandral Staghelm in Darnassus."}]])
R(941,"培養心臟",[[description="I have removed that foul moss from the heart, but it remains tainted...$B$BTry placing the heart in my planter.  It is filled with a nutritive soil that may cleanse and heal the heart.",objectives={"Plant the Tainted Heart in Denalan's Planter."}]])
R(942,"健忘的勘察員",[[description="This fossil bears a striking resemblance to one I once saw in Ironforge. An archaeologist by the name of Flagongut brought it to our annual Explorers' League conference. He believed the fossil had a power which could be unlocked somehow.$b$bLast I heard Flagongut had holed up in the Deepwater Tavern in Menethil Harbor, awaiting escort to the Whelgar Excavation Site. Seek him out and show him Remtravel's fossil. Perhaps he can reveal the secrets of the past.$b$bThe ship to Menethil departs from Auberdine.",objectives={"Take the mysterious fossil to Archaeologist Flagongut in Menethil Harbor."}]])
R(943,"健忘的勘察員",[[description="嗯，我在那裡會議之後把原始樣品交給了勘察員維爾。最近，我在洛克莫丹發現了雷魯之石，我認為它就是解開神秘化石的鑰匙。$b$b當我準備趕往維爾加挖掘場的時候，遭到了迅猛龍的攻擊，雷魯之石也給弄丟了。$b$b我不知道是哪只迅猛龍吞掉了這塊石頭，但如果你能找回它，我應該就可以釋放這些化石中的魔力了。當然，我們也需要最初從維爾加挖掘場取回的那枚化石。",objectives={"米奈希爾港的考古學家弗拉岡特要你把雷魯之石帶給他。"}]])
R(944,"主宰之劍",[[description="It is strange that the naga are here, in Darkshore.  But stranger still...are the Twilight's Hammer.  That cult worships the old, old lords of the earth.  Lords defeated long ago.$B$BThe Master's Glaive, to the south, is a place where such an old lord fell.$B$BGo there and look for more Twilight's Hammer cultists.$B$BTake this phial of scrying.  Use it to create a scrying bowl after searching the Master's Glaive.  Then speak to me through the bowl.",objectives={"Gather information, then use the Phial of Scrying to create a Scrying Bowl.  Use the bowl to speak with Onu."}]])
R(945,"護送瑟瑞露尼",[[description="Help!$B$BI was wandering around the Master's Glaive, and these dirty cultists surrounded me.  Lucky I'm good at hiding!!$B$BCan you help me out of here?  And I need to send word to my sister Therysil that I'm all right.  She's in Ashenvale to the south, at the Shrine of Aessina.",objectives={"Help Therylune escape, then tell Therysil at the Shrine of Aessina that her sister is safe."}]])
R(946,"<UNUSED>")
R(947,"洞中的蘑菇",[[description="我正在研製一種藥劑，需要一種生長在特定洞穴裡的稀有蘑菇才能配製。這個洞穴位於壁泉河瀑布的後面，在東邊稍稍偏北的地方。$B$B我本來準備自己去，不過古樹之林建議我不要靠近那個地方。我們尊貴的盟友覺得那個洞穴是黑海岸新出現的邪惡勢力的藏身之處。$B$B$N，請你幫我收集那些蘑菇。與此同時，請察看一下那處洞穴以便確認古樹所擔心的事情。",objectives={"收集5個粗柄蘑菇和1個毒帽蘑菇，把它們交給奧伯丁的巴瑞薩斯·月影。"}]])
R(948,"安努",[[description="Onu, an Ancient of Lore at the Grove of the Ancients, knows of your journey to Cliffwater Falls and wishes to speak with you.  The grove lies to the south, nestled near the mountains.$B$BThe Ancients are patient and wise, $N.  But if Onu seeks your counsel concerning what you saw in the falls, then I fear it is urgent.",objectives={"Speak with Onu at the Grove of the Ancients."}]])
R(949,"暮光之錘的營地",[[description="The Twilight's Hammer's purpose at the Master's Glaive is not known.  But it must be dark.$B$BSearch through their camp at the Glaive... Search for some thing that may teach us their intentions.$B$BFor we must learn their intentions before a plan is made.",objectives={"Find a clue in the Twilight's Hammer camp at the Master's Glaive."}]])
R(950,"向安努回復",[[description="Peering into the Twilight Tome is maddening.  Text begins to swim and dance after only a moment's glance, and once beautiful scrollwork twists into grotesque shapes.$B$BTearing away one page of insane scribbles is all that is possible before a swoon overtakes you.",objectives={"Bring Onu the recovered Insane Scribbles."}]])
R(951,"瑪塞斯特拉遺物",[[description="你在主宰之劍找到的那頁書來自於一本古籍……一本精靈撰寫的古籍。但它已經被暮光之錘詛咒和玷污了，看來暮光之錘的信徒是希望用古代精靈的魔法將他們古老的主人重新召回我們的世界。$B$B到東北邊的瑪塞斯特拉廢墟去看看，找到那些古代的聖物。如果我能研究一下它們的話，也許能搞清楚暮光之錘打算如何使用那些精靈的魔法。",objectives={"收集6個黑暗深淵聖物，把它們交給古樹之林的安努。"}]])
R(952,"古樹之林",[[description="如果你有時間為神諭之樹跑跑腿的話，我想讓你幫我送一封信到黑海岸的古樹之林去。$b$b你大概只有乘角鷹獸才能到黑海岸，不過我相信你絕對可以完成這個任務。把這個交給知識古樹安努，他正等著我的消息，就像我曾焦急地等待來自神諭林地的消息一樣。",objectives={"把范達爾的信交給黑海岸古樹之林裡的安努。"}]])
R(953,"亞米薩蘭的毀滅",[[description="到東邊去就可以發現亞米薩蘭廢墟。現在，那些未曾安息的夜精靈貴族的亡靈如同生前一般盤踞在那裡，那裡也曾經是艾薩拉的僕人練習他們強大魔法的地方。$b$b我在奉命探索那片廢墟的時候偶然發現有兩塊巨大的石碑，上面是潦草寫下的亞米薩蘭的故事，還有這座城市被毀滅的歷史。在我閱讀碑上的刻文的時候,突然有亡靈出現和我說話，嚇得我趕緊逃了回來。$b$b如果你夠膽量的話就去一趟那片廢墟，替我破譯一下石碑上的刻文。",objectives={"研究刻有亞米薩蘭的故事及其被毀經過的石碑，然後回到黑海岸的哨兵坦莎·月刃那裡。"}]])
R(954,"巴莎蘭",[[description="有一群惡魔的爪牙在東部的巴莎蘭遺跡裡到處橫行。佔據了那裡的劣魔和薩特瘋狂地汲取著該區的魔法能量，致使牠們的魔力不斷地迅速膨脹。$b$b但是，我注意到那裡有一處牠們始終無法接近的神殿。就在遺跡西側的小峭壁上，彌漫著奇特的藍光……一定有什麼原因使得惡魔不願靠近那裡。$b$b我希望你去調查一下。",objectives={"到巴莎蘭廢墟尋找奇怪藍光的源頭。"}]])
R(955,"巴莎蘭",[[description="If I were to relate the story of my life, I have no doubt it would surpass the limits of your patience. Let us say that mine has been a long and painful life, and this spectral form is perhaps the worst torment of all.$b$bI am held here by the means of magic. Though my words may seem disingenuous, I assure you I would be grateful beyond words if you would help me find the means of my imprisonment. A seal binds me, and by examining the earpieces of the sprites and grells, I may find a trace of it.",objectives={"Acquire 8 Grell Earrings for Asterion in Bashal'Aran."}]])
R(956,"巴莎蘭",[[description="If the grells have come into close contact with the seal that binds my eternal prison, I suspect I know the cause. No doubt the seal has come into the possession of the satyr that lead them.$b$bI feel strongly that this must be true, $n. One of the satyr must surely possess it. If you can obtain it, you would bring me so close to passing the bars of my prison that tears would come to my eyes.",objectives={"Obtain the Ancient Moonstone Seal and bring it to Asterion in Bashal'Aran."}]])
R(957,"巴莎蘭",[[description="It was the craft of one of the most powerful of the Highborne that created the seal that formed my prison. In Ameth'Aran, the ruins to the south that are twin to these, persists even today an ancient flame, blue in color. In this flame this seal could be destroyed.$b$bBe wary in the ruins, $n...",objectives={"Destroy the Ancient Moonstone Seal at the ancient flame in Ameth'Aran, then return to Asterion in Bashal'Aran."}]])
R(958,"上層精靈的工具",[[description="$C，我有一項任務交給你。$b$b你去過亞米薩蘭廢墟嗎？如果還沒有，你可以在通向南方的大路東側找找看。亞米薩蘭廢墟曾經是眾多夜精靈貴族的家園，而如今那裡卻成為他們濫用魔法的見證。$b$b據哨兵的報告，那些貴族的亡靈依然在使用古代的魔法武器進行抵抗。我們必須獲得那些聖物，只有這樣我們才有可能真正摧毀那些亡靈。",objectives={"幫奧伯丁的桑迪斯·織風取回7個高等精靈的聖物。"}]])
R(959,"港口的麻煩",[[description="啊呀！$b$b你也看到了，最近有點倒霉！早間從藏寶海灣過來了一支大型的運貨船隊，我是說大型的！我從沒有見過那麼多的箱子。我想加快點速度，所以卸貨卸得稍微快了點。$b$b結果呢，還沒等我弄清楚是怎麼回事兒，我看到那個可惡的傢伙——瘋狂的馬格利什——手拿一瓶99年波爾多陳釀跑了出來。我一路追他到了哀嚎洞穴，但是我可不想進到那個可怕的地方去。$b$b嗯……你夠不夠膽量去把他給我找出來？",objectives={"棘齒城的起重機操作員比戈弗茲讓你從瘋狂的馬格利什那兒取回一瓶99年波爾多陳釀，瘋狂的馬格利什就藏在哀嚎洞穴裡。"}]])
R(960,"正在冥想的安努")
R(961,"正在冥想的安努")
R(962,"毒蛇花",[[description="幽暗城的皇家藥劑師學會派我來這兒完成一個特殊的任務，$n。我想你會願意幫助我的，因為黑暗女王領導下的被遺忘者將會通過我的任務得到進一步的加強。$b$b近來我在研究一種罕見的植物，它的名字叫毒蛇花，我相信這種藥草有著巨大的能量。$b$b不幸的是，它只生長在哀嚎洞穴的最深處，那是貧瘠之地最危險的洞穴之一。",objectives={"為雷霆崖的藥劑師札瑪收集10朵毒蛇花。"}]])
R(963,"永誌不渝",[[description="永恆之井的戰鬥結束以後，亞米薩蘭被毀滅了，全城的夜精靈都成為了這座城市的陪葬，其中就有我的至愛安娜雅。$b$b我也沒有想到，在那次災難過去了數千年之後，對安娜雅的回憶依然縈繞在我的夢中。有一次，當我恍恍惚惚地在黑海岸的森林裡遊蕩的時候，我發現自己正置身於亞米薩蘭的廢墟之中……我居然看見了我的至愛——她那飽受折磨的亡魂。$b$b她必須得到自由，但我沒有勇氣去做，因為讓她得到自由，就必須先摧毀她的亡靈。",objectives={"釋放安娜雅·晨路的靈魂，把她的墜飾交給奧伯丁的塞瑞利恩·白爪。"}]])
R(964,"骸骨碎片",[[description="通靈學院大門的鑰匙名叫骷髏鑰匙，它一定是由某具骸骨製造而成——事實上是若干具骸骨——並在適當的模具中使用最堅硬的金屬進行加固。天生就能打開通靈學院大門的人擁有一種特殊的力量，這種力量能讓鑰匙發揮作用。$B$B重要的事情要優先處理掉，$N。我們需要一些骸骨碎片來製造鑰匙。安多哈爾內的骸骨應該符合我們的要求，但是安多哈爾城外的那些骸骨也許同樣有效。",objectives={"將15塊骸骨碎片交給西瘟疫之地亡靈壁壘的藥劑師迪瑟斯。"}]])
R(965,"奧薩拉克斯之塔",[[description="Hail, young $r. I am Elissa Starbreeze, and it is my charge to protect Auberdine from harm.$b$bTo this end, I sent Balthule Shadowstrike to observe the strange happenings around the Tower of Althalaxx to the northeast.$b$bIt is past time that he should have returned. I worry that he has encountered some unforeseen danger in the forest. I would be most appreciative if you would find him and see that he is doing well.",objectives={"Find Balthule Shadowstrike near the Tower of Althalaxx in Darkshore."}]])
R(966,"奧薩拉克斯之塔",[[description="A group of warlocks has taken up residence around and inside the tower. I would have returned to Auberdine to report to Elissa earlier, but I was afraid that I might miss something while I was away.$b$bDelgren suspected such a company might be gathering at the tower, but did not know why.$b$bA few scraps of parchment that the warlocks carry have found their way to my hands, but I need more to complete the puzzle. I warn you not to venture into the tower, however, the warlocks there are much more powerful!",objectives={"Collect 4 Worn Parchments for Balthule Shadowstrike near the Tower of Althalaxx."}]])
R(967,"奧薩拉克斯之塔",[[description="My master, Delgren the Purifier, is a paladin who has graciously offered his assistance in defending our forests from the forces of the demons and undead. He has taught me much about the Holy Light and the art of battle.$b$bDelgren must know of the cult's operations immediately.$b$bYou will find him far south of here at Maestra's Post in Ashenvale Forest. Be swift, I fear the Dark Strand's threat grows with each passing hour.",objectives={"Deliver Balthule's letter to Delgren the Purifier in Ashenvale Forest."}]])
R(968,"深淵之神",[[description="Although terribly worn and scratched, the title of this book can still be read upon its cover:$B$BThe Powers Below$B$BInside the book is a listing of unpronounceable names with foreboding titles, methods of worship, and preferred sacrifices...many of which include living, humanoid creatures.$B$BOn the inside cover of the book are the words: \"Bonegrip's Runes and Dooms, The Forlorn Cavern, Ironforge.  Proprietor: Gerrig Bonegrip.\"$B$BIf Bonegrip sells books like this, perhaps he'll buy this one back.",objectives={"Bring the Book: The Powers Below to Gerrig Bonegrip in the Forlorn Cavern, Ironforge."}]])
R(969,"祝妳好運",[[description="啊，我一看見你就知道——你想要一個幸運符咒。瑪艾里無所不知！$B$B在冬泉谷的南部有一道峽谷，那裡的巨人身上有時候帶有一種具有強大能量的冰塊，當然你也可以自己從峽谷中收集冰塊碎片。$B$B帶給我十片霜槌碎片回來，然後我的幸運符咒就是你的了。",objectives={"收集10塊霜槌碎片，把它們交給永望鎮的巫醫瑪艾里。"}]])
R(970,"奧薩拉克斯之塔",[[description="巴蘇爾的這封信裡的消息真是可怕。這個暗灘教派對我們而言始終是一個很大的威脅，必須儘快清除才行。我和東北方的奧迪拉蘭城中的暗灘教派打過交道，他們中的一個人持有一枚靈魂寶石，其中蘊藏著有關這個教派的魔法的秘密。$b$b把它交給我，我應該有辦法從中找出一些資訊來。",objectives={"搜集一枚發光的靈魂寶石，並把它交給邁斯特拉崗哨的淨化者德爾葛蘭。"}]])
R(971,"深淵中的知識",[[description="你也許知道，我喜歡收集各種知識：古老的知識，有用的知識，可以打開神秘通路的知識，可以喚醒沉睡之人的知識。$B$B據說有本古老的書卷叫做洛迦里斯手稿，它被藏在黑海岸的黑暗深淵底部。那裡是往日死去的精靈安息的地方。那些精靈在他們的城市被毀滅之前都有著廣博的知識。$B$B到黑暗深淵去找手稿吧，我不會忘記你為我做的事，即使到世界毀滅的那一天……",objectives={"把洛迦里斯手稿帶給鐵爐堡的葛利·硬骨。"}]])
R(972,"水之靈契")
R(973,"奧薩拉克斯之塔",[[description="伊克魯德·瑪格蘇爾，沒錯，我瞭解他。他可是一個強大的獸人術士，就住在火痕神殿裡，那是一個位於梣谷西南的極端邪惡的地方。$b$b至今他並沒有給我們造成太大的麻煩，而我也沒工夫去對付他，不過現在看起來……他的死期到了。",objectives={"把伊克魯德·瑪格蘇爾之書交給邁斯特拉崗哨的淨化者德爾葛蘭。"}]])
R(974,"究根問底",[[description="對我來說，這裡的溫泉簡直就是個不解之謎，這些熱量究竟是哪裡來的？$B$B這些水池離火羽山那麼近，我真的想知道火山和溫泉之間到底有沒有關係。我製作了一個測溫計來讀取火山的溫度，我想要找到溫度最高的地方。它是按照我獨創的計量單位進行測量的！$B$B拿著這個溫度計，當你經過某個炎熱的地方，就順便讀取一下那裡的溫度！",objectives={"安戈洛環形山的克拉蘭克要你去找到火羽山中溫度最高的地方。$B$B當你找到一個看起來很熱的地方時，就右鍵點擊溫度計來測量當地的溫度。不斷嘗試，直到你找到溫度最高的地方。"}]])
R(975,"瑪艾裏的容器",[[description="Now, before I give ya dis charm, I better explain how ta use it.$B$BIf you carry da charm with ya, you'll find dat certain items will drop from creatures ya fight. If you don't have da charm with you, you won't find them. Understand?$B$BYou'll know these special items by the name -- they be called E'ko. If you find any of these items, just bring dem to ol' Mau'ari, and she help ya out.$B$BWait here while I fix your charm.",objectives={"Speak to Witch Doctor Mau'ari again in a moment to receive the lucky charm."}]])
R(976,"奧伯丁的補給品",[[description="Delgren has asked me to deliver messages and supplies to Sentinel Starbreeze in Auberdine, but I am loathe to leave on my own. Dangerous foes operate in the forest, and I do not wish to risk letting these supplies and information fall into the wrong hands.$b$bIf you and others could act as my guards, I could leave now. With your protection, I have no doubt that we can see these goods safely to Auberdine.",objectives={"Speak with Delgren the Purifier at Maestra's Post after seeing Feero safely through Ashenvale Forest."}]])
R(977,"雪怪計劃！",[[description="Now that I have what I need to cover the mechanical moving parts, I only need one other thing. Well, actually two. Two horns!$B$BThe ice thistle patriarchs and matriarchs have the largest horns, so of course, those are the ones I want. That type of yeti inhabits a cave to the southeast. There are plenty of them there; you shouldn't have any problem finding them.$B$BRemember, I only want the best looking ones -- no beat up or broken horns, please!",objectives={"Collect 2 Pristine Yeti Horns for Umi Rumplesnicker in Everlook."}]])
R(978,"月光羽毛",[[description="Wildkin feathers from the Hinterlands appear to contain traces of magical qualities. These powers... they don't seem to be wielded by the creatures, it's more like they are simply inherent to the species -- part of their very essence.$B$BDuring my studies, I heard that a large population of wildkin inhabit the snowy lands of Winterspring. Could these creatures have the same powers? Please help me find an answer, $N. Go to Winterspring and gather feathers that have dropped to the ground, then return to me.",objectives={"Collect 10 Moontouched Feathers from Winterspring, then return to Erelas Ambersky in Rut'theran Village."}]])
R(979,"蘭莎爾拉",[[description="嗯，嗯，這些羽毛上附著的魔法似乎與我以前見到過的很類似……雖然我並不能確定我們會發現什麼，但我想你必須繼續追查下去，$n。$B$B我的一位同事最近到冬泉谷去觀察當地梟獸的生態了，你為什麼不去找她談一談，看看她有些什麼發現呢？",objectives={"在冬泉谷找到蘭莎爾拉。"}]])
R(980,"新的泉水",[[description="Now, I've heard about other hot springs in a place called Winterspring, far to the north of here. The strange thing is, there are no volcanoes anywhere near them. Interesting, I know.$B$BWell, if you want to find out more, you should head to Winterspring and speak to a friend of mine. Her name is Donova Snowden, and she is currently staying by the hot springs there.$B$BThanks again for helping me with my thermometer! See you later!",objectives={"Travel to Winterspring and speak with Donova Snowden."}]])
R(981,"奧薩拉克斯之塔",[[description="你應該為你所作出的貢獻而得到獎勵。回到德爾葛蘭那裡，告訴他埃瑟里克斯·納拉辛已經死在你的手下，暗灘教派也已經被打得一敗塗地，潰不成軍。",objectives={"和邁斯特拉崗哨的淨化者德爾葛蘭談話。"}]])
R(982,"深不可測的海洋",[[description="從我們現在所在位置沿著海岸一直往北可以看到兩艘沉船——銀色清晨號和迷霧之紗號。這兩艘船在穿越茫茫大海，最終將要達到奧伯丁的時候遇到了那些可惡的魚人，它們現在只能躺在海底作為那些惡棍的戰利品了。$B$B這兩艘船的船長都沒有能倖免於難，他們的日誌以及其他有價值的東西還鎖在船裡的箱子中。我希望你能幫我找到這些東西，這對於那些生還的船員也是頗有意義的。",objectives={"找到銀色清晨號的保險箱和迷霧之紗號的保險箱，把它們交給奧伯丁的高爾博多·鋼手。你可以在村莊北部遇難的船隻裡找到這兩隻箱子。"}]])
R(983,"傳聲盒827號",[[description="嘿！看看我這劃時代的最新發明：傳聲盒！通過它，你可以和很遠的人進行交談！$B$B也許你已經見過它們了，嗯，就是那些上面有操縱杆的盒子。不過傳聲盒有一個毛病，就是它們需要經常性的維護。$B$B而且每一個盒子的問題都不一樣，不過我在這個問題上做得就很巧妙！你看，我把每一個盒子都放在那些能給它提供最合適的修理零件的生物附近。現在傳聲盒827號出了點故障，它就在奧伯丁的南邊，需要6隻蟹腿來進行修理。我會獎賞你的……",objectives={"收集6隻蟹腿，把它們放進傳聲盒827號。"}]])
R(984,"熊怪的威脅",[[description="Some of my brethren were rescued from a corrupt furbolg in Teldrassil, and I've vowed to stop any more atrocities before more of our kind are injured... or worse.$B$BI have seen a couple hints of corruption in Darkshore already, but I have yet to find any widespread signs. I think it would be logical if the investigation continued with the furbolgs. Would you find one of their camps, and return to me if you see any signs of corruption?",objectives={"Find a corrupt furbolg camp in Darkshore and return to Terenthis in Auberdine."}]])
R(985,"熊怪的威脅",[[description="You've already proven adept at scouting our enemy, $N. Do you have what it takes to fight them as well?$B$BNot all adventurers prefer straightforward combat to the art of stealth and evasion.$B$BIf you think you're up for the task, then the furbolg camp south of Auberdine is currently the biggest threat to our people. You'll find some of the Blackwood tribe there. Kill 8 pathfinders and 5 windtalkers, and return to me here.",objectives={"Kill 8 Blackwood Pathfinders and 5 Windtalkers and return to Terenthis in Auberdine."}]])
R(986,"丟失的主人",[[description="$N, your skills have already helped me in my endeavor. Could I impose on you again to help Grimclaw and his master Volcor? In addition, I can craft you a magical cloak that will allow you to walk unhindered by Darkshore's creatures while you look for him.$B$BTo create the cloak, I'll need five fine moonstalker pelts from a moonstalker sire or matriarch to have enough material. The cats can be found near Wildbend River to the south, or even farther south near Ashenvale.",objectives={"Find 5 Fine Moonstalker Pelts and return them to Terenthis in Auberdine."}]])
R(987,"<UNUSED>")
R(990,"灰谷之旅",[[description="$N, my mistress, Raene Wolfrunner, awaits you in the city of Astranaar within Ashenvale. With your help, perhaps we can at least ease some of the corruption that's taken hold there.$B$BHead south from here and stay close to the road--you'll find your way there without issue if you follow those directions.",objectives={"Find Raene Wolfrunner in Ashenvale."}]])
R(991,"萊恩的凈化",[[description="$N，我有一個老朋友也正為梣谷的哨兵部隊提供援助，不過他還沒有回來。$B$B他正在尋找一件東西，一件他認為可以延緩熊怪對我們的同胞發起進攻的物品，由一個早已死掉的邪惡巫師製造的魔棒。$B$B在他離開這兒以前，他曾說過要去尋找一塊寶石，這塊寶石能幫他找到那根魔棒。$B$B他提到這塊寶石很可能就藏在法拉希姆湖的神殿中，那座神殿就坐落在西邊的山腳下。在寶石被人取走之前，它一直都放在那裡。$B$B請去找到我的朋友，$N。",objectives={"在梣谷找到泰洛尼斯。"}]])
R(992,"加基森水業公司",[[description="如果你感興趣的話，我們現在正在為加基森水業公司招聘兼職初級勘探員。$B$B那些遊牧民不斷地侵佔我們的水井，這迫使我們不得不去勘探更多的水源！沙漠中到處都可能有水的存在，但是只有聰明人才能找到它們。$B$B拿著這個瓶子，到流沙崗哨旁的水池那裡幫我採集一些水樣回來。那個水池旁邊有些食人妖在看守著，小心點，完成任務之後儘快把水樣送到我這裡來。",objectives={"用未使用的尋水器在流沙崗哨旁邊的池中採集水樣。一旦你收集到水樣，就儘快將其交給加基森的高級勘探員菲茲杜瑟。"}]])
R(993,"丟失的主人",[[description="$N，斗篷做好了。你現在可以去尋找沃科爾，我希望時間還來得及。$B$B斗篷上的魔法被啟動之後持續不了多久間，也許就只有五分鐘左右的時間。你可以自行決定什麼時候使用它，不過我建議你在找到銳爪以後再用。$B$B如果銳爪告訴我的消息是真的，那麼你應該可以在南邊的某個洞穴中找到他的主人。銳爪會在路邊等你，看見它以後向它揮手打個招呼（使用/wave指令），然後它就會將它的主人所在的位置告訴你。",objectives={"找到沃科爾。"}]])
R(994,"殺出重圍",[[description="All right, $N, force it is. Let's get out of here as soon as you're ready. We'll fight our way down to the road--Grimclaw should still be there. Once there, we can part ways.$B$BTerenthis will want to hear your version of the story immediately, so head to Auberdine after we make it out of here.",objectives={"Protect Volcor until you reach the road, then speak to Terenthis in Auberdine."}]])
R(995,"偷偷溜走",[[description="All right then... if you're sure, we'll sneak out of here. Let us leave when you're ready.$B$BRemember, after you've escaped, meet Terenthis back in Auberdine. I'll head there on my own since I'll probably be moving faster than you.",objectives={"Escape the Furbolg cave and meet Terenthis in Auberdine."}]])
R(996,"被腐化的迎風花")
R(997,"德納蘭的泥土",[[description="你在往南方旅行嗎？你要去奧拉密斯湖嗎？如果是這樣的話，我有個任務想請你幫忙……$B$B我的同伴德納蘭在湖的東岸有個營地，他在那兒對泰達希爾的植被進行研究和試驗。他想要一包達納蘇斯的稀土，但送貨的在路上耽擱了，我這兩天才剛剛收到稀土。$B$B你能把這包稀土帶給他嗎？",objectives={"把稀土交給奧拉密斯湖畔的德納蘭。"}]])
R(998,"被腐化的迎風花")
R(999,"When Dreams Turn to Nightmares")
R(1000,"新的邊疆",[[description="Attention, heroes!$B$BThe Cenarion Circle seeks able bodied individuals to assist them in exploring the vast new frontiers of Kalimdor!  A forbidden wasteland of unimaginable dangers lies far to the west of Tanaris and Gadgetzan, and the Circle needs willing and honorable proxies to act in their stead.$B$BAll interested individuals should seek audience with the Cenarion Circle.  Speak with the Arch Druid Hamuul Runetotem on the Elder's Rise of Thunder Bluff for more information!",objectives={"Speak with Arch Druid Hamuul Runetotem on the Elder Rise of Thunder Bluff about the Cenarion Circle's call to explore the frontiers of Kalimdor."}]])
R(1001,"傳聲盒411號",[[description="A tiny voice crackles from deep within the machine.$B$B\"Wizbang here! The next Buzzbox is north of Auberdine, on the beach$B$BSo, that Buzzbox is number 411 and it needs 3 Thresher Eyes for its repairs. They're just off the coast! The darkshore threshers... *Hic*... Sorry about that...$B$BJust like last time, when you give the Buzzbox the goods, it'll spit out your reward. *Hic*... What? No, I'm fine!\"",objectives={"Collect 3 Thresher Eyes from Darkshore Threshers in the deep sea near Buzzbox 411."}]])
R(1002,"傳聲盒323號",[[description="The Buzzbox gives a burst of static as you hear Wizbang begin to speak.$B$B\"The next Buzzbox is number 323. Ish north of Auberdine but... where's the ale? Wha? Oh, ish on the road sho ya shouldn't have trouble finding it near the bridge.\"$B$BWizbang mumbles something incoherent before you hear a loud gulping sound.$B$B\"Thish one needs Moonstalker Fangs... 6 of 'em.\"",objectives={"Collect 6 Moonstalker Fangs and place them in Buzzbox 323."}]])
R(1003,"傳聲盒525號",[[description="Over the boiling noises and dripping sounds coming from the machine, you hear Wizbang's wavering voice call out.$B$B\"Nexsht onesh far south down the road. Shouldn't be hard to find... jusht off to the shide... near a fensh. I think I hid it in shum bushesh... Bushessh. Hehehe... Yesh, Buzzbox 525 takes grizzled scalps from thoshe grizzled thistle bears. Boy thash a mouthful. Grizzshled... Hehehe...\"$B$BYou hear more gulping sounds as the machine cuts out. Then, suddenly, it bursts back to life.$B$B\"4!\"",objectives={"Collect 4 Grizzled Scalps from Grizzled Thistle Bears to the south of Auberdine and place them in Buzzbox 525."}]])
R(1004,"新的邊疆",[[description="Attention, heroes!$B$BThe Cenarion Circle seeks able bodied individuals to assist them in exploring the vast new frontiers of Kalimdor!  A forbidden wasteland of unimaginable dangers lies far to the west of Tanaris and Gadgetzan, and the Circle needs willing and honorable proxies to act in their stead.$B$BAll interested individuals should seek audience with the Cenarion Circle.  Speak with the Arch Druid Hamuul Runetotem on the Elder's Rise of Thunder Bluff for more information!",objectives={"Speak with Arch Druid Hamuul Runetotem on the Elder Rise of Thunder Bluff about the Cenarion Circle's call to explore the frontiers of Kalimdor."}]])
R(1005,"What Lurks Beyond")
R(1006,"What Lies Beyond")
R(1007,"遠古雕像",[[description="I would charge you with a task, $N.$B$BI was on my small vessel, skimming over the submerged ruins of Zoram, when naga attacked me, surging from the water and tearing at me with their claws!  I fled, carrying what supplies I could to make this meager camp.$B$BBut when I reached the shore and ran... my prized possession was lost.$B$BPlease, $N, find the site of my ambush, along the coast to the north, and search for an ancient statuette.  It is the reason I have braved the dangers of the Zoram Strand.",objectives={"Bring the Ancient Statuette to Talen, in his camp near the Zoram Strand."}]])
R(1008,"佐拉姆海岸",[[description="在我們的西北海岸，也就是左拉姆海岸一帶，潛伏著一股邪惡的勢力。$B$B左拉姆海岸是已經被毀滅的左拉姆城殘存的部分，左拉姆主城在大爆炸中被摧毀，沉到了海底，這些很久以前發生的事情已經快要被夜精靈忘卻了。$B$B現在，納迦又回來了。至於他們為什麼會回來，誰也不知道。但是這些並不重要，我們必須殺了這些魔鬼，把他們送回地獄！$B$B完成任務之後，就立刻回來向我報告。",objectives={"收集20顆怒尾納迦的頭顱，把它們交給阿斯特蘭納的辛德瑞爾。"}]])
R(1009,"盧澤爾",[[description="除非你能找到可以打開雕像上的那只鎖的鑰匙，否則雕像的秘密將永遠無法解開。$B$B那把鑰匙其實是一枚戒指——左拉姆之戒。在這座城市被很久以前那場大爆炸所掀起的波濤淹沒之前，左拉姆之戒曾經屬於這座城市的統治者。$B$B這枚戒指已經丟失很多年了，不過納迦最近找到了它。$B$B他們的領導者盧澤爾就住在左拉姆北部邊緣的一個小島上。請幫我取回這枚戒指吧，$N。",objectives={"找到左拉姆之戒，把它交給左拉姆海岸邊的塔爾倫。"}]])
R(1010,"巴斯蘭的頭發",[[description="There is a plant that once grew in the old ruins of Bathran's Haunt to the north.  The plant was called Bathran's Hair and was known to cure ailments of the spirit.$B$BThere is a sick child in the village, and I believe it is more than just a physical illness.  Will you go to Bathran's Haunt and search it for Bathran's Hair?  I may need it to properly treat the child.$B$BBathran's Haunt lies north of Maestra's Post and just south of the border to Darkshore.",objectives={"Bring 5 Bathran's Hair to Orendil Broadleaf in Ashenvale."}]])
R(1011,"被遺忘者的病菌",[[description="The Forsaken, the undead arm of the Horde, have crept into Ashenvale, lurking at our ruins and our barrows.  We believe their goal is to spread disease amongst the lands of the night elves.  We must confirm this!$B$BThe Forsaken have a camp south of here, near the Dor'Danil Barrow Den, where they create poisons and diseases and place them in bottles.  Fight your way into that camp and steal a bottle of disease.  Return with such a bottle.  I will test it and find its purpose.",objectives={"Bring a Bottle of Disease to Kayneth Stillwind in Forest Song."}]])
R(1012,"瘋狂的德魯伊",[[description="在我和被遺忘者的毒物抗爭的時候，曾經在恍惚之中產生了一段幻覺，我看到朵丹尼爾獸穴中的德魯伊被亡靈下毒害死了！他們現在是遊蕩的幽靈，他們的靈魂離開了身體，並且變得越來越瘋狂。$B$B為了讓德魯伊的靈魂早日安息，你必須進入朵丹尼爾墓穴，殺死那些昔日的德魯伊領袖：坦尼爾·黑木、尤希爾·喚月和瑪沃裡斯·裂雲。$B$B趕快去吧。",objectives={"殺死這些德魯伊：坦尼爾·黑木、尤希爾·喚月和瑪沃裡斯·裂雲，然後向林歌神殿的凱尼斯·靜風覆命。"}]])
R(1013,"烏爾之書",[[description="$N，在影牙城堡裡有一本書，烏爾之書，對我的收藏而言可說是極有價值的。烏爾在天譴軍團到來之前曾是達拉然裡一位偉大的法師，他對其他世界的研究對……被遺忘者中的某些團體……很有價值。$B$B到影牙城堡裡找到這本書，把它帶給我，我會向黑暗女王彙報你的貢獻。",objectives={"把烏爾之書拿給幽暗城煉金區裡的看守者貝爾杜加。"}]])
R(1014,"除掉阿魯高",[[description="現在我已經對整個詛咒有了一個全面的瞭解，並開始著手研究如何補救了。$b$b但阿魯高依然好好地住在影牙城堡中。在幹掉阿魯高之前，我們還不能宣稱銀松森林已經是黑暗女士的地盤。$b$b但是，我得去搞明白怎樣才能根除他的魔法影響，$n。所以我只能把除掉阿魯高的任務交給你了。$b$b到影牙城堡去，永遠地結束阿魯高的骯髒法術。把他的頭給我帶來！影牙城堡去，永遠地結束阿魯高的骯髒法術。把他的頭給我帶來！",objectives={"殺死阿魯高，把他的頭帶給瑟伯切爾的達拉爾·道恩維沃爾。"}]])
R(1015,"新的邊疆",[[description="注意了，英雄們！$B$B塞納里奧議會正在招募精銳的成員來幫助他們探索卡林多大陸！在塔納利斯沙漠跟加基森的西邊隱藏著一個難以想像的危險禁地，議會希望有人能光榮地接下這個任務，去探索那個地方。$B$B所有對此感興趣的聯盟成員，都應該去向塞納里奧議會報到。去和達納蘇斯的大德魯伊范達爾·鹿盔談談吧！",objectives={"與達納蘇斯塞納里奧區的大德魯伊范達爾·鹿盔談談關於議會號召聯盟成員探索卡林多大陸的事情。"}]])
R(1016,"元素護腕",[[description="Take this divining scroll--it can determine the creator of these elementals. But you will need something from them to use as a reagent to focus scroll's magic--their bracers should do nicely.$B$BA few intact bracers from the creatures should be enough. The other bracers will be useless for our purposes, but they may be worth something to a merchant if you wish to sell them. Once you have the intact bracers attempt to use the scroll. Return to me with the results and we shall proceed from there.",objectives={"Collect 5 Intact Elemental Bracers and use the Divining Scroll on them. Afterwards, bring the Divined Scroll to Sentinel Velene Starstrike at the Silverwind Refuge."}]])
R(1017,"召喚者",[[description="There's only one undead mage in the Barrens capable of defiling this many water elementals. He's also the only one foolish enough to try. Sarilus Foulborne is probably sitting at the top of Dreadmist Peak, laughing at me.$B$B$n, you must go into enemy territory and destroy this miscreant. I have had enough of his idiocy and we must show him what happens to those who annoy the Sentinels.$B$BDestroy him and bring me his head. Be wary though, the Horde may be watching for you.",objectives={"Slay Sarilus Foulborne and bring his head to Sentinel Velene Starstrike in Silverwind Refuge."}]])
end f(R) end
do local function f(R)
R(1018,"新的邊疆",[[description="Attention, heroes!$B$BThe Cenarion Circle seeks able bodied individuals to assist them in exploring the vast new frontiers of Kalimdor!  A forbidden wasteland of unimaginable dangers lies far to the west of Tanaris and Gadgetzan, and the Circle needs willing and honorable proxies to act in their stead.$B$BAll interested individuals should seek audience with the Cenarion Circle.  Speak with the Arch Druid Hamuul Runetotem on the Elder's Rise of Thunder Bluff for more information!",objectives={"Speak with Arch Druid Hamuul Runetotem on the Elder Rise of Thunder Bluff about the Cenarion Circle's call to explore the frontiers of Kalimdor."}]])
R(1019,"新的邊疆",[[description="Attention, heroes!$B$BThe Cenarion Circle seeks able bodied individuals to assist them in exploring the vast new frontiers of Kalimdor!  A forbidden wasteland of unimaginable dangers lies far to the west of Tanaris and Gadgetzan, and the Circle needs willing and honorable proxies to act in their stead.$B$BAll interested individuals should seek audience with the Cenarion Circle.  Speak with the Arch Druid in Darnassus, Fandral Staghelm, for more information!",objectives={"Speak with Arch Druid Fandral Staghelm at the Cenarion Enclave of Darnassus about the Cenarion Circle's call to explore the frontiers of Kalimdor."}]])
R(1020,"奧雷迪爾的藥劑",[[description="$N, I have created a cure that I believe will help the afflicted child.  Take it to Astranaar and give it to the child's parent, Pelturas Whitemoon.$B$BTo reach Astranaar, follow the road south, then east.",objectives={"Bring Orendil's Cure to Pelturas Whitemoon in Astranaar."}]])
R(1021,"身陷危險的樹妖！",[[description="聽著，我不知道你是誰，但我需要你的幫助。我的姐妹們去從薩特那裡取回塞納留斯的樹枝，她們說會很快回來，可是已經過去兩天了！$B$B$n，你得趕快去找到我的姐妹們，她們到去東北邊的薩維亞去尋找一個夜精靈的廢墟了。我的腦海裡是一片空白，不知道該幹什麼了……去找到安妮莉亞吧，她是這次搜尋行動的首領。",objectives={"到薩維亞去找到安妮莉亞。"}]])
R(1022,"狼嚎谷",[[description="儘管我們投入了大量的物資和人力想要將剩餘的惡魔趕出北方的費伍德森林，但是看來似乎並沒有什麼效果。我們只能把大部分的惡魔禦於梣谷之外。$b$b在北方的費伍德森林附近，有一群神秘的狼人佔據了麥爾莎迪絲神殿的廢墟。他們令人心顫的嗥叫使得那個地區得了個「狼嚎谷」的名字。保存在神殿中的麥爾莎迪絲之書也許能讓我們知道這些狼人出現在這裡的原因。",objectives={"到狼嚎谷去，研究一下麥爾莎迪絲之書，然後向艾森娜神殿的哨兵梅麗瑞亞·霜影覆命。"}]])
R(1023,"萊恩的凈化",[[description="在檢查泰洛尼斯的遺物時，你發現了一本完好無損的日記。$B$B你收起日記之後就離開了泰洛尼斯的屍體。$B$B接下來你唯一要做的事情就是找到泰洛尼斯一直在尋找的那顆寶石。萊恩曾經提到過寶石就在這個地區，也許在魚人的手裡……",objectives={"找到發光的寶石，連同泰洛尼斯的日記一起交給阿斯特蘭納的萊恩·狼行者。"}]])
R(1024,"萊恩的凈化",[[description="你得自己去進行研究，但是從泰洛尼斯的記錄來看，你下一階段的工作將是去尋找達圖爾所造的魔棒的其他部分。我建議你從伊瑞斯湖東部的月井開始。如果你準備好了，就沿著這條路越過環繞著伊瑞斯湖的群山，然後向北走。$B$B一個名叫莎爾蒂恩的林精會在那裡為你提供嚮導。記得帶上寶石，如果莎爾蒂恩願意幫你重造魔棒，她肯定會需要這塊寶石的。",objectives={"在東北方的月井旁找到莎爾蒂恩。"}]])
R(1025,"先發制人",[[description="在你出發去月井之前，如果你願意測試一下自己能力的話，我還有另外一項可以造福梣谷的任務交給你。$B$B沿著這條路一直向東走，在靠近法弗倫河的地方有一些熊怪頻頻攻擊過路的旅客。他們扭曲的靈魂只有靠著恐懼才能得到撫慰，他們瘋狂的心智只有在啜飲無辜者的鮮血時才能得到滿足。$B$B幫助哨兵部隊守護我們的領地，讓那些熊怪知道血債是要血還的。$B$B我相信他們的營地應該在這條路的南邊……多加小心。",objectives={"殺掉汙林族的1個汙林守衛者、2個汙林巨熊、10個汙林薩滿和12個汙林戰士，然後回去找阿斯特蘭納的萊恩·狼行者。"}]])
R(1026,"萊恩的凈化",[[description="情況越來越糟糕了。$B$B萊恩的猜測是對的，我很瞭解達圖爾的發明以及這個地區的樹人——至少我曾經瞭解。樹人們現在開始墮落了，他們的靈魂變得扭曲。$B$B如果你想要找到魔棒的下一塊碎片的話，就必須先找到一把木製鑰匙，用它來打開鎖住這塊碎片的箱子。$B$B這把木製鑰匙就在東北方的費伍德森林附近的一個樹人手裡。得到了鑰匙之後，你就可以順著這條路向西走，在靠近費伍德森林的邊界地區尋找一小塊林間空地……箱子就藏在那裡的某個地方。",objectives={"找到木製鑰匙和一段達圖爾的魔棒，然後回到月井的莎爾蒂恩那裡。"}]])
R(1027,"萊恩的凈化",[[description="魔棒的最後一段是由朵丹尼爾的德魯伊保管的，但是我不清楚他們把它藏到了什麼地方。很抱歉，恐怕我只能幫你這麼多了。$B$B我所能告訴你的就是：順著這條通向貧瘠之地的路一直走下去，這群德魯伊隱居在路的東邊，可是他們也沒法幫助你，因為他們最近被殺死了……那是一段我不願再回憶的過去。$B$B如果你找到了最後一段魔棒，就把它帶回來交給我，我會幫你修復魔棒的。",objectives={"找到達圖爾的魔棒的最後一段，然後回到月井旁的莎爾蒂恩那裡。"}]])
R(1028,"萊恩的凈化",[[description="這是完整的魔棒，$N。修復它並不難……難的是找到神殿，並再次賦予它能量。$B$B對於像你這樣已經完成了這麼多艱鉅工作的人來說，只要稍加留意和努力，這個任務也不會太難。$B$B從這兒向東南方走——那裡人跡罕至，所以要多加小心——路上記得留意正北方。神殿就隱藏在圍繞著那片林地的山巒中。$B$B到了那兒之後，把魔棒放在神殿中……剩下的就交給魔法去完成吧，祝你好運。",objectives={"找到隱藏的神殿並給達圖爾的魔棒重新注入魔力。"}]])
R(1029,"萊恩的凈化",[[description="我建議你去找萊恩，告訴她魔棒的魔力已經復原了。我想她會告訴你下一步該做什麼的。$B$B祝你好運，$N。",objectives={"回到阿斯特蘭納的萊恩·狼行者那裡。"}]])
R(1030,"萊恩的凈化",[[description="唉，我不能完全肯定地說他下一步想要做什麼。$B$B如果他關於魔棒的說法是真的，那麼這根魔棒就可以將你變成另一種形態——我也不知道會變成哪一種形態。$B$B也許他本想利用魔棒的力量更加靠近那些墮落的熊怪，可是假如他不當心的話，就連沒有墮落的熊怪也會殺了他。 在變形之後，達圖爾得找到一個沒有受到魔苔影響的熊怪談談。",objectives={"找到一個尚未墮落的熊怪，利用達圖爾的變形魔棒的能力與其交談。"}]])
R(1031,"塞納留斯的樹枝",[[description="Anilia puts her hands on your shoulders and draws you close. Gasping, she points towards the arch to the north, before her eyes close and her last wheezing breath leaves her body. \"He has taken it... Geltharis...\" You know in your heart that Anilia's dying wish is to see the Branch of Cenarius back in dryad hands.",objectives={"Kill Geltharis and return the Branch of Cenarius to Illiyana at the Shrine of Aessina."}]])
R(1032,"獵殺薩特！",[[description="我不敢相信安妮莉亞居然離我而去了……我們以前天天都在森林裡一起遊玩。我感覺很……難過。$B$B也許有一個辦法可以讓我感覺好一點。請你去殺了那些從我身邊奪走安妮莉亞的薩特！請你把它們的角拿給我作為證明，我會永遠感謝你的。",objectives={"收集16支薩特的角，把它們交給艾森娜神殿的伊莉亞娜。"}]])
R(1033,"月神之淚",[[description="我曾把挽救蕾拉的生命的希望寄託於奧雷迪爾的醫術上，可讓我擔心的是，那只能延緩疾病在我孩子體內的蔓延而不能讓她徹底痊癒。我們一定要找到更有效的藥物！感謝奧雷迪爾，他告訴我如果第一種治療方法不能起作用的話，還有下一步的治療方法。$B$B有一種名叫月神之淚的特殊的石頭，只有在阿斯特蘭納東部的伊瑞斯湖中心的小島上才能找到它。奧雷迪爾說這塊石頭能治療一切疾病……求求你，$N，幫我找來月神之淚，祈求它能結束我孩子的痛苦。",objectives={"找到月神之淚，把它交給阿斯特蘭納的皮爾圖拉斯·懷特姆恩。"}]])
R(1034,"星塵廢墟",[[description="月神之淚減輕了我女兒的一些病痛，感謝伊露恩，她發惡夢的次數也大大減少了。可是……她仍發著高燒。$B$B奧雷迪爾告訴我，在南方的星塵廢墟中可以找到一種結晶的星塵，或許它能緩解蕾拉的高燒。請你幫我收集一些星塵吧。$B$B願艾露尼保佑你速去速回。伊露恩保佑你速去速回。",objectives={"收集5份星塵，把它們交給梣谷的皮爾圖拉斯·懷特姆恩。"}]])
R(1035,"墜星湖",[[description="蕾拉的高燒退了，但她還是很虛弱。我想她很難靠自己的力量康復。我想要借助月亮石的魔力才能讓她痊癒。$B$B過去我們常在東南部的墜星湖搜集月亮石……但是食苔沼澤獸來了之後就不行了。$B$B這群野獸的領袖是一個沼澤獸智者，它收集所有從天上掉下來的月亮石並把它們藏起來。現在，你得從沼澤獸智者那裡拿到一枚月亮石。$B$B要達到此一目的，恐怕你必須先殺了那個沼澤獸智者。",objectives={"從沼澤獸智者那裡取回一枚隕落的月亮石，並把它帶給阿斯特蘭納的皮爾圖拉斯·懷特姆恩。"}]])
R(1036,"嘿，水手！",[[description="$N... yeah, I've heard of you.  I've heard that you're no friend of Booty Bay - just like us Bloodsail Buccaneers.  Fleet Master Firallon is looking for hale and hearty $g men : women; just like you for a special mission.$B$BIf you're interested, head on out to the Crimson Veil and speak with him below decks.  She's anchored off the Wild Coast east of here, next to the Riptide and the Damsel's Luck.",objectives={"Speak with Fleet Master Firallon aboard the Crimson Vale off the coast of Stranglethorn Vale."}]])
R(1037,"維琳德·星歌",[[description="維琳德·星歌是我在梣谷森林的前任指揮官。起初，她似乎將費伍德森林的一切都調理得井井有條，然而她對於森林的影響卻變得越來越小。終於有一天，她突然消失了。$b$b我被派來接替她的工作。不過恐怕我對於這位女祭司瞭解得並不使很多。也許哨兵部隊的指揮官塞恩提爾·刃紋會知道更多有關她失蹤的細節。$b$b當然，她也知道這件事情的重要性。",objectives={"在達納蘇斯的公正之廳與塞恩提爾·刃紋談話。"}]])
R(1038,"維琳德的日記",[[description="你是由麥爾薩迪斯之書中得知這一切的？我認為你應該去檢查一下她的所有物品，雖然那樣做可能不太妥當。用這把鑰匙可以打開她放在哨兵小屋裡的儲物箱。她把平時的工作都記錄了下來，因此你從她的日記中應該可以瞭解到很多事情。$b$b我應該告訴你，哨兵們認為她是因為某些特殊的原因而離開的，她隨時都有可能再回來。女祭司過去做過很多讓我們對她倍加信賴的事情。",objectives={"在維琳德的箱子裡搜尋她的日記，把日記連同鑰匙一起交給達納蘇斯的塞恩提爾·刃紋。"}]])
R(1039,"貧瘠之地的港口",[[description="棘齒城是貧瘠之地唯一的港口。最有可能發生的情況是，維琳德在棘齒城登上了一條駛往艾澤拉斯的黑水灣的商船。我們和管理港口的那些哥布林交往有限，不過碼頭的管理者應該有來來往往的乘客的資訊。$b$b順著這條路往東南方走，過了梣谷就進入貧瘠之地了。你要當心，$n，部落一方的戰士一直在那片土地上巡邏。不過，在港口地區你應該是安全的。",objectives={"和棘齒城的碼頭管理員迪茲維格談話。"}]])
R(1040,"藏寶海灣的航道",[[description="啊，終於找到了。她是很久以前經過這裡的，你看……$b$b維琳德，乘黑色魚鷹號去往藏寶海灣。其他的沒什麼要說的了，我想那艘船應該是安全抵達目的地了。$b$b我沒有什麼可以幫你的啦，不過她問過一些關於在那片陸上旅行的事情，我向她提到了拉茲戈特，一個藏寶海灣的商隊成員。沒准維琳德會去找他當導遊什麼的。$b$b現在出發吧，我沒時間再陪你了。",objectives={"坐船去藏寶海灣，和旅行者拉茲戈特談話。"}]])
R(1041,"商隊通路",[[description="若我說的不對請不要見怪，我應該記得沒錯，畢竟不是每天都會發生這樣的事兒的。$b$b我記得你要找的那個維林德。那是不久前發生的事，要知道，不是每天都會有一位元漂亮的夜精靈女祭司會願意搭著我這輛破爛的大蓬車旅行的，不過，我的車用來代步的確很不錯，不是麼？$b$b我們在向北去的路上分手了，她往夜色鎮去了。那裡的書記員應該有所有的出入記錄，或許從那裡你能知道些對你有用的東西。$b$b在叢林裡你最好多加小心，即使是在安全的時節，那兒仍然是個危險的地方。",objectives={"與夜色鎮的書記員達爾塔談話。"}]])
R(1042,"卡爾文家族",[[description="不，夜色鎮沒有關於這個維琳德·星歌的任何記錄……不過如果你不介意的話，我想說，我很難想像一個夜精靈的女祭司會在旅店裡過夜，你懂我的意思嗎？$b$b不過我聽說過你提到的這些狼人。就在前幾天，卡洛爾還提著幾個狼人的頭到鎮上來。卡洛爾是為卡爾文家族效力的，這個家族專門對付惡魔、亡靈和各種雜七雜八的怪物。你去和喬納森談談吧，他是卡爾文家族的首領。",objectives={"去和夜色鎮的喬納森·卡爾文談談。"}]])
R(1043,"月神的鐮刀",[[description="你的故事聽上去不像是假的……我不能完全理解你的動機，不過如果你想要除掉暮色森林的狼人，我就不需要瞭解這些。$b$b在南方有一座礦山，很多狼人在那裡出沒……天知道他們是從哪裡冒出來的，不過據我們所知，他們最早就是在那裡出現的。$b$b去忙你的吧，不過如果你有什麼重要消息，請一定要告訴我。我們需要所有能幫我們對抗邪惡的資訊。",objectives={"去找關於月神鐮刀的消息，然後回到夜色鎮見喬納森·卡爾文。"}]])
R(1044,"回復珊蒂斯",[[description="不要擔心，我們會解決狼人的問題，也一定可以遏制這些由你朋友引到森林裡來的邪惡勢力。對於你的朋友，我也沒有什麼敵意。各種詭異的事情越來越多了，$n，黑暗的勢力不會停止它的腳步。$b$b我就不耽擱你了，可能還有其他人想要知道你在暮色森林的礦山裡發現了什麼。",objectives={"回到達納蘇斯去見塞恩提爾·刃紋。"}]])
R(1045,"萊恩的凈化",[[description="夜精靈是個歷史悠久的種族，但是他們的傲慢毀滅了他們的世界。現在，這樣的傲慢也毀掉了我們的生活，一切都失控了……$B$B我把許多災難歸咎於那些精靈們，但是我們也應該為自己的行為承擔責任。即使在墮落之前，我們也具有非常邪惡的一面。$B$B蘭恩·血牙就是這種邪惡面的體現。對權力的渴望，無盡的物欲……現在的墮落只會讓他更加強大。我的心中燃燒著對這些精靈的怒火，但我對他們的後代並無惡意，我們也必須管教好自己的兒女，讓他們不再重蹈我們的覆轍……",objectives={"殺死蘭恩·血牙和4個血牙保鏢，再回到密斯特拉湖附近的克羅格那裡。"}]])
R(1046,"萊恩的凈化",[[description="回到你自己的部族去吧，讓他們知道你在這裡取得的勝利。$B$B向他們展示你的戰利品，並享受勝利的榮耀吧……",objectives={"把蘭恩·血牙的顱骨和達圖爾的變形魔棒交給阿斯特蘭納的萊恩·狼行者。"}]])
R(1047,"新的邊疆",[[description="Attention, heroes!$B$BThe Cenarion Circle seeks able bodied individuals to assist them in exploring the vast new frontiers of Kalimdor!  A forbidden wasteland of unimaginable dangers lies far to the west of Tanaris and Gadgetzan, and the Circle needs willing and honorable proxies to act in their stead.$B$BAll interested individuals should seek audience with the Cenarion Circle.  Speak with the Arch Druid in Darnassus, Fandral Staghelm, for more information!",objectives={"Speak with Arch Druid Fandral Staghelm at the Cenarion Enclave of Darnassus about the Cenarion Circle's call to explore the frontiers of Kalimdor."}]])
R(1048,"深入血色修道院",[[description="Whilst the Dark Lady tends to the pressing issue of the Lich King's advance to the north, I am seeing to it that matters closer to home are being taken care of accordingly.$b$bNo doubt, the human pests who call themselves the Scarlet Crusade are proving to be the sharpest thorn in our side domestically. Tirisfal Glades is literally crawling with the little red ants.$b$bTravel to the Monastery, $c, and lay waste to High Inquisitor Whitemane and her top lieutenants.",objectives={"Kill High Inquisitor Whitemane, Scarlet Commander Mograine, Herod, the Scarlet Champion and Houndmaster Loksey and then report back to Varimathras in the Undercity."}]])
R(1049,"墮落者綱要",[[description="The Earthen Ring had pure intentions towards our plagued brethren. But who is to know the motivations of those whispering in the ears of the Elder Council?$b$bThe Forsaken whom we have allied with have a history wrought with deceit. Too hasty was our pact. Perhaps Cairne would have been wise to heed the warnings from Orgrimmar.$b$bDeep within the Scarlet Monastery lies the Compendium of the Fallen, guarded by crazed human zealots. Their method is forged from insanity but their research might prove useful.",objectives={"Retrieve the Compendium of the Fallen from the Monastery in Tirisfal Glades and return to Sage Truthseeker in Thunder Bluff."}]])
R(1050,"泰坦神話",[[description="未來是已經命中註定了的！我們的命運就像雨點落入大海一樣無可改變。$b$b不過研究過去也許可以讓我們預見未來，並提前做好一些準備。$b$b在災難降臨在羅德隆之前，提里斯法林地中有一處藏有許多書籍的地方——老修道院的圖書館，據說有一本《泰坦神話》就收藏在哪裡。$b$b把它給我拿回來，也許我們可以一起揭開過去的秘密。",objectives={"從修道院拿回《泰坦神話》，把它交給鐵爐堡的圖書館員麥伊·蒼塵。"}]])
R(1051,"沃瑞爾的復仇",[[description="Even though my will is free, I can serve the Dark Lady no more. I feel my time on Azeroth has come to an end. My life force is shattered.$b$bInterrogator Vishas did this to me! Tortured me for weeks! Took my wedding ring and gave it to his wife. The bastard!$b$bRevenge... I want revenge!$b$bThe pompous fool bragged about his precious wife, Nancy, who lived along Lake Lordamere. Track the wench down, slay her and return my wedding ring to my wife, Monika in Tarren Mill.$b$bHeed my last wishes....",objectives={"Return Vorrel Sengutz's wedding ring to Monika Sengutz in Tarren Mill."}]])
R(1052,"血色之路",[[description="我們血色十字軍擁有著從壁爐谷到提里斯法林地一線的許多要塞。這些要塞構築了保護羅德隆大陸的主要防線，我們為此感到十分自豪。$b$b你在南艾澤拉斯對抗亡靈的行動已經證明了你的價值。但真正的威脅仍然來自正在羅德隆北部蔓延的瘟疫。$b$b到一處叫做南海鎮的城鎮去，在那裡找到一個名叫萊雷恩的十字軍戰士，把這封由我親自密封的表彰信交給他，他將會護送你前往充滿榮耀的血色修道院。",objectives={"將安東修士的表彰信帶給南海鎮的虔誠的萊雷恩。"}]])
R(1053,"以聖光之名",[[description="我曾懷著榮耀、忠誠、自豪的心情加入了血色十字軍。我曾堅信他們有著將艾澤拉斯的所有亡靈生物都消滅乾淨的崇高理想。$b$b但自從我在提里斯法林地的修道院裡待了一陣之後，我意識到他們現在已經幾近瘋狂了。他們認為除了那些穿著十字軍制服的人之外的所有人都已經感染了瘟疫，而任何被懷疑感染上瘟疫的無辜者都要遭到他們無情的拷打。$b$b以聖光的名義，血色十字軍必須被剷除掉。你，$n，必須消滅這個瘋狂的組織。",objectives={"殺死大檢察官懷特邁恩，血色十字軍指揮官莫格萊尼，十字軍的勇士赫洛德和馴犬者洛克希並向南海鎮的萊雷恩覆命。"}]])
R(1054,"解除威脅",[[description="從阿斯特蘭納出發，一直向北走，你能看到許多薊皮熊怪。我的偵察兵向我報告說，熊怪的數量在最近幾個月裡成倍地增加。如果它們的數量變得足夠多的話，就可能會直接向阿斯特蘭納發起攻擊。$B$B你能殺掉多少熊怪就殺多少，但你要把他們酋長的顱骨給我帶回來作為證明……$B$B我會留在阿斯特蘭納等你的消息，願伊露恩與你同在。",objectives={"把達爾·血爪的顱骨交給阿斯特蘭納的萊恩·狼行者。"}]])
R(1055,"萊恩的凈化",[[description="完整的魔棒就在你的手中，莎爾蒂恩正在靜候佳音。",objectives={"回到月井旁的莎爾蒂恩那裡。"}]])
R(1056,"石爪峰之旅",[[description="森林之魂告訴我，你是個勇敢無畏而且樂於旅行的$c。$b$b在南方離密斯特拉湖不遠的地方，有一條名叫石爪峰小徑的隧道，沿著這條隧道走，你會到達石爪山脈中的一個名叫狂風峭壁的地方。到了那兒以後，穿越西南方的峭壁湖，然後向北爬上陡峭的斜坡，就可以到達石爪峰了。$b$b看守者奧巴格姆在那裡等著你。聽從他的吩咐，$n。$b$b這次旅程會很危險。",objectives={"拜訪石爪峰的看守者奧巴格姆。"}]])
R(1057,"奪回焦炭谷",[[description="As a protector of the forest spirits you can undoubtedly guess why I am alarmed.$b$bYou have traveled through these mountains to reach this peak. Surely you have seen the travesty which has befallen the land. Greed has led to the destruction of these sacred hills.$b$bThe Charred Vale to the south was set afire by the greedy mechanized army of industrialists. Worse yet, the Bloodfuries that have encroached on the land refuse us passage in to begin regrowth.$b$bDrive the wretched harpies out, $n!",objectives={"Keeper Albagorm on Stonetalon Peak wants you to slay 7 Bloodfury Harpies, 7 Bloodfury Ambushers, 7 Bloodfury Slayers and 7 Bloodfury Roguefeathers."}]])
R(1058,"金吉爾的森林魔法",[[description="我實在是太興奮了！$b$b籠子裡的三個小精靈！但我們該對我們這些整天都要抱著樹的小朋友們做些什麼呢？有了！讓他們嘗嘗那個……他們是怎麼叫它來著……「森林魔法」的滋味吧！$b$b我首先需要一些苔蘚分泌出來的石爪苔液，然後你再從那些兇悍的夜行虎身上給我搞點鬍鬚來。啊，對了，還要許多的巨角鹿眼珠子。還有還有，差點忘記了，還要一塊靈龍的鱗片！$b$b這些東西都能在石爪峰上找到，動作快點，$n，我要準備施展這森林魔法了！",objectives={"瑪拉卡金的巫醫金吉爾需要5瓶石爪苔液、5根夜行虎鬚、30顆巨角鹿的眼球和1塊靈龍的鱗片。"}]])
R(1059,"奪回焦炭谷",[[description="The Bloodfuries have been subdued. But they will regroup soon enough if action is not taken.$b$bFar south of the Barrens lies a land known as Thousand Needles. If you travel west in Thousand Needles until you reach the lush forest's edge of Feralas, you will find a druid named Falfindel Waywarder.$b$bThis great and wise druid is capable of calling forth great forest spirits which can aid in the reclamation of the Charred Vale.$b$bSend word of our need! Seek him out at once!",objectives={"Travel to Falfindel Waywarder on the border of Thousand Needles and Feralas."}]])
R(1060,"寫給金吉爾的信",[[description="You've done so well for me, $n. You're a regular lucky rabbit's foot and there's something I want you to see.$B$BThe harpies are not from around the Barrens. They come from a place called Stonetalon, far to the northwest of here. Though it is probably a dangerous place for you, I need this letter delivered to an old friend of mine who lives there, a witch doctor by the name of Jin'Zil.$B$BHe'll be happy to know that Serena Bloodfeather is dead, and I think you'll find Stonetalon an interesting place.",objectives={"Deliver Darsok's letter to Jin'Zil within his cave in Malaka'Jin, in Stonetalon."}]])
R(1061,"石爪之靈",[[description="哥布林們在石爪山地區燒殺劫掠，山靈們已經被徹底地激怒了。土地正在哭泣，而那些可以聽到這種哭泣的人……正在聆聽著這聲音……$B$B希雷斯·碎石是部落裡的一位前途無量的薩滿，她已經被派去了石爪山。她報告說那裡到處都是哥布林的伐木站，並向我們請求支援。$B$B到石爪山去和她會合吧，你只需要沿著貧瘠之地的十字路口西邊的道路一直前進即可，她的營地就在巨木谷裡。",objectives={"找到石爪山的希雷斯·碎石並和她談話。"}]])
R(1062,"地精侵略者",[[description="The goblin-run Venture Company moved into the Stonetalon Mountains, chopping down trees and burning huge stretches of forest.  The spirits of this place are nearly blind with pain and rage.  We must stop the Venture Company!$B$BHead northwest, beyond the Greatwood Vale and into the Windshear Crag.  You will find the goblins and their servants at work -- show them the Horde will not allow the exploitation of Stonetalon.  Show them in the language they best understand...$B$BViolence.",objectives={"Kill 15 Venture Co. Loggers, then return to Seereth Stonebreak on the border of Stonetalon and the Barrens."}]])
R(1063,"長者",[[description="為了徹底平息石爪山的山靈，我們必須與牛頭人長老們商討商討。$B$B我記不清他們那麼多首領的名字，但我知道其中肯定有一個名叫瑪加薩的。我聽說她已經很老了，但漫長的歲月賜予了她無窮的知識。如果說有哪位牛頭人能夠提供精神力量的幫助的話，那一定就是她了。$B$B瑪加薩就居住在牛頭人部族的首都城市雷霆崖中的長者高地上，也就是城市西北部的那座高地。去與瑪加薩談談，告訴她石爪山這邊發生的事情。",objectives={"與雷霆崖的瑪加薩談話。"}]])
R(1064,"被遺忘者的援助",[[description="The tauren have a bond with the land, and it pains me to hear of Stonetalon's plight.  But I fear that to heal the land, we must first remove the disease upon it.$B$BIs it not fortunate, then, that the Forsaken are allied with us?  They know much of disease.  I believe they can aid us, and by doing so they will strengthen the trust between our people.$B$BSpeak with Apothecary Zamah.  She is a scholar and an emissary of the Forsaken.  You will find her in the Pools of Vision below the Spirit Rise.",objectives={"Speak with Apothecary Zamah in the Pools of Vision in Thunder Bluff."}]])
R(1065,"塔倫米爾之旅",[[description="為了把風險投資公司趕出石爪山，我們就必須採取極端的措施。極端，但不流血。$B$B我的一個同事可能有我們需要的工具，他叫林度恩，就住在希爾斯布萊德丘陵的塔倫米爾鎮，那地方在遙遠的羅德隆。$B$B要去希爾斯布萊德的話，就要先乘飛艇到我們的首都幽暗城，然後往北到提里斯法林地，再往西南進入銀松森林，最後再轉向東南，才能到希爾斯布萊德丘陵。$B$B找到林度恩，把這封信帶給他，裡面詳細敘述了我們需要什麼樣的幫助。",objectives={"把札瑪的便箋帶給塔倫米爾的林度恩。"}]])
R(1066,"無辜者之血",[[description="I will create a toxin to bleed the violence from the Venture Company, rendering them weak and docile.  That should fix the Horde's problem in Stonetalon, yes?$B$BBut to create the toxin, I will need the blood of innocents, a difficult ingredient to obtain.$B$BFortunately the Syndicate, a group of human brigands in this area, employ shadow mages... and those mages collect innocent blood for their own, unsavory purposes.$B$BYou can find the Syndicate shadow mages in Durnholde Keep to the southeast.",objectives={"Bring 5 Vials of Innocent Blood to Apothecary Lydon in Tarren Mill."}]])
R(1067,"返回雷霆崖",[[description="Here is the toxin.  If you use it against the Venture Company it should produce favorable, perhaps even contagious, results.  I must say, it is quite exciting to see my work applied in the field!$B$BBut before using it, take it to Apothecary Zamah.  She must create a delivery method for the toxin to maximize its effect.",objectives={"Bring Lydon's Toxin to Apothecary Zamah in Thunder Bluff."}]])
R(1068,"伐木機",[[description="There is a relation to the spiritual magic of shamans and the natural magic of druids.  This is why we shamans can hear the plea of the spirits of Stonetalon.  Many of their whisperings are lost to me, but one message, one vision, is clear...$B$BI saw a vision of two man-shaped machines in Windshear Crag, northwest of Greatwood Vale, felling trees with impossible speed.  These metal beasts must be stopped!$B$BIn my vision, the machines were marked with strange symbols:$B$BXT:4 and XT:9.",objectives={"Kill the shredders XT:4 and XT:9, then return to Seereth Stonebreak at the border of the Stonetalon Mountains and the Barrens."}]])
R(1069,"深苔蜘蛛的卵",[[description="煎蜘蛛卵是藏寶海灣的時尚菜肴。問題是……藏寶海灣的蜘蛛卵已經斷貨了。$B$B我發誓這絕對是個賺錢的好機會！$B$B在狂風峭壁——就是石爪山的西北地方——那裡有一種深苔蜘蛛，如果你能幫我弄來一些深苔蜘蛛的卵的話，我一定會付給你一大筆錢！$B$B這些蜘蛛最喜歡在樹蔭下爬行……但可惡的風險投資公司砍掉了它們賴以生存的大樹！$B$B不過，你還是到狂風峭壁去找找深苔蜘蛛吧，它們的卵在有樹的地方還是很多的。",objectives={"收集15顆深苔蜘蛛的卵，把它們交給棘齒城的麥伯克·米希瑞克斯。"}]])
R(1070,"守衛石爪山",[[description="你好，$N。$B$B你看起來真像是個喜歡旅行的$r啊。你有沒有去過石爪山？現在那個地方被風險投資公司和其他一些夜精靈的敵人給佔據了。$B$B最近，哨兵萊恩·狼行者派我的朋友凱拉·影矛到那裡去進行調查，但至今我還沒收到她的任何消息。更讓我擔心的是，聯盟還派了一名地精法師跟著她……這真是麻煩。$B$B你能找到她，然後把她的近況彙報給我嗎？",objectives={"找到位於石爪山脈狂風峭壁旁的山谷中的凱拉·影矛。"}]])
R(1071,"侏儒學者",[[description="You see, $N, I'm a member of the Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences, and it's my goal... nay, my DUTY! to show the night elves that a blend of magic, mixtures, and mechanisms can help save their forests.$B$BBut it's a hard fought war, and the goblins reproduce like rabbits it seems. I haven't even had time to build my newest inventions!$B$BI need some time to plan and organize. But to do that, I need your help keeping the goblins at bay in Windshear Crag to the east...",objectives={"Kill 10 Venture Co. Loggers, and 10 Venture Co. Deforesters and return to Gaxim Rustfizzle in Stonetalon."}]])
R(1072,"老同事",[[description="The device I'm thinking about is my most advanced version to date. But we'll need a special potion if it's to work. I'm thinking we might as well get the good stuff since this mission could be your last.$B$BAnd for that, we're going to need some potent explosives: Nitromirglyceronium.$B$BThe only person who can make NG-5 is an old friend of mine: Lomac Gearstrip. Look for him in Tinker Town.$B$BYou talk him into making us some NG-5, I'll get to work on placement for my devices.",objectives={"Speak to Lomac Gearstrip in Ironforge."}]])
R(1073,"失職+藥劑=快樂",[[description="Hahaha... you need Nitromirglyceronium to stop goblins from destroying a forest?!$B$BI don't care if you know Gaxim or not... I'll give you the stuff just to see you or them explode into itty bitty pieces.$B$BThere's a problem though: I'm all out.$B$BBut I'll tell you what, you bring me the correct potions, and I'll make some up for you right away.$B$BThe least you can do is prove you've got some skill as an alchemist before I just give you a sample of my greatest creation.",objectives={"Bring 4 Minor Mana Potions and 2 Elixirs of Fortitude to Lomac Gearstrip in Ironforge."}]])
R(1074,"失職+藥劑=快樂",[[description="Here you go, stranger. Take heed with it though... it's volatile stuff.$B$BIf you're really a friend of Gaxim's, then tell him I say hello. If you're not, then have fun blowin' yerself up.",objectives={"Bring the Nitromirglyceronium back to Gaxim Rustfizzle in Stonetalon."}]])
R(1075,"馬倫的卷軸",[[description="Okay, now for the remote detonation part of my plan... oh, I haven't explained that yet, have I?$B$BOkay, so the short of it is this: with a little magic, I can make it so the explosives go off while you're not around. I'm putting together a device that'll allow you to push just one button and have the NG-5 explode when you're ready.$B$BBut I need a spell from a friend in Stormwind--Collin Mauren is his name. You can find him in the mage quarter there. He's human, so he shouldn't be hard to miss.",objectives={"Find Collin Mauren in Stormwind."}]])
R(1076,"西部荒野中的惡魔",[[description="Ah, I think I have it. A messaging spell... I believe that's the effect he's looking for.$B$BI'll have to create a scroll with the spell impressed upon it. To do that I'll need debris from a dust devil.$B$BWhile I gather the rest of the components, why don't you head to Westfall and find one of the foul creatures? They are dangerous, but I'm sure it's nothing you can't handle if you're willing to subject yourself to one of Gaxim's experiments.$B$BI'll be here when you return.",objectives={"Bring Dust Devil Debris to Collin Mauren in Stormwind."}]])
R(1077,"給加克希姆的特快專遞",[[description="Here you are, $N. This should do nicely.$B$BPlease give my regards to Gaxim when next you see him. I look forward to hearing about this adventure when it sees its completion.$B$BFare well.",objectives={"Bring the Scroll of Messaging to Gaxim Rustfizzle in Stonetalon."}]])
R(1078,"完鱗歸瑪倫",[[description="旅行者們一直在問我有關石爪山的事情，看來那裡已經成為一個公認的最佳冒險場所了——當然前提是你沒有在尋找雙足飛龍、元素生物，也沒有跟風險投資公司扯上關係。$B$B在石爪山脈深處的焦炭谷中還居住著一群披著厚重鱗片的蜥蜴。把那些鱗片磨成灰就是我施放一些法術所必需的原料。$B$B如果這些蜥蜴還活著的話，你能不能幫我搞一些它們的鱗片來？$B$B注意點時間，不用太著急，而且我會付給你不錯的酬勞。",objectives={"給暴風城的科林·瑪倫帶回8片水晶鱗片。"}]])
R(1079,"隱秘行動：A",[[description="This is it, $N. Pay close attention. The devices are done, and ready to be used.$B$BTake these pages--they'll explain more about the detonators and explosives, and where you should place them.$B$BRemember, the success of your mission doesn't depend on how much destruction you cause. Plan Alpha's success depends on you bringing back the Venture Co.'s engineering plans from inside the lumber mill south of Cragpool Lake.",objectives={"Retrieve the Venture Co.'s Engineering Plans from the lumber mill in Windshear Crag."}]])
R(1080,"隱秘行動：B",[[description="Plan Beta's just like Plan Alpha, $N.$B$BWe cause a distraction and then steal their precious letters.$B$BThe key is to get their letters... remember that.$B$BThe pages I gave you already will tell you where to plant the explosives. Just get back here alive and with those letters....",objectives={"Retrieve the Venture Co. Letters from Windshear Mine at the east end of Windshear Crag."}]])
R(1081,"泰蘭德的接待",[[description="$N, I am sure Tyrande Whisperwind herself would like to thank you for taking part in this mission.$B$BIt may not appear so on the surface, but what you've helped start could very well strengthen our foothold in the Stonetalon Mountains.$B$BIf you consider yourself our ally against these atrocities, go see Tyrande in the Temple of the Moon in Darnassus.",objectives={"Find Tyrande Whisperwind in Darnassus."}]])
R(1082,"向塞恩希爾報告",[[description="$N, you have done a great deed by lending a hand here.$B$BThe Sentinels of Ashenvale will reward you well if you informed them that Gaxim and I are alive. Tell them we are well on our way to stopping the Venture Co. and healing the lands.$B$BFind Tara Thenysil in Astranaar; she will be pleased to see you've returned with good news.",objectives={"Return to Sentinel Thenysil in Ashenvale."}]])
R(1083,"怒靈",[[description="I'm unsure what the Venture Co. did to the Vale, but it's obvious they were overpowered by the creatures there.$B$BThey set the forest aflame, and used their inventions of destruction to decimate as much of the Vale as possible.$B$BBut in their ignorance they also released something else: burning spirits, elementals of flame, stone and rage.$B$BThe land has no chance to see Elune's smile while these creatures roam free.$B$BBring me their smoldering embers to show you've reduced their numbers.",objectives={"Bring 8 Smoldering Embers from any of the fire elementals in the Charred Vale to Kaela Shadowspear in Stonetalon."}]])
R(1084,"受傷的古樹",[[description="It seems obvious to me that the protectors of the Vale--the treants--had something to do with the Venture Co. being driven back. Unfortunately, even those once great guardians have now become corrupt.$B$BGaxim thinks their corruption is somehow linked to the weapons the goblins used during their retreat.$B$BI told him I'd collect a sample from a wounded treant and allow him to study it in order to figure out if that's true.$B$BBring me some of the shrapnel so the gnome can tell me more...",objectives={"Bring a piece of Corroded Shrapnel to Kaela Shadowspear in Stonetalon."}]])
R(1085,"守衛石爪山",[[description="The situation here in Stonetalon is obviously grave for a night elf and gnome to be working together.$B$BThe Venture Co. has devastated these lands and I've spent most of my time putting an end to the destruction.$B$BDo not judge Gaxim prematurely; he understands the need for us to work together.$B$BIf you wish to aid us, then start by speaking to Gaxim.$B$BI'm sorry I cannot send you back to Tara with good news yet. Perhaps soon.",objectives={"Speak to Gaxim."}]])
R(1086,"地精空港",[[description="The toxin is ready.  All that remains is its delivery.  You, $N, must make that delivery.$B$BThe Venture Company must have a means of sending messages and light cargo between its headquarters and its operations in Stonetalon.  It is likely a small sky port -- not big enough for a zeppelin, but perhaps for a flying machine.  You must search the areas in Stonetalon under control of the Venture Company and find this sky port, if it exists.  If you find it, then place the toxin there.$B$BPlace it, and run.",objectives={"Bring the Toxic Fogger to the Venture Co. sky port, then return to Apothecary Zamah."}]])
R(1087,"塞納留斯的遺產",[[description="你根本無法想像到我是多麼地憎惡這片污濁的土地。石爪峰那裡有一小撮可憐兮兮的塞納留斯族類和夜精靈的德魯伊們聚集起來，妄圖徹底抑制住魔法的傳播……甚至還妄想著奪回他們深深眷戀著的極南之地的森林。$b$b儘管我很樂意回到加德納爾去享受傳授魔法的快樂，但在我的工作完成之前，主人恐怕是不會讓我回去的。$b$b我確信你和我一樣，對夜精靈一族及他們盟友都沒有任何好感。所以，請幫助我吧，這樣一來，我們都能得到令自己滿意的結果。",objectives={"為石爪峰附近的布萊林·火拳殺死4名塞納留斯的兒子，4名塞納留斯的女兒以及4名塞納里奧植物學家。"}]])
R(1088,"奧達努斯",[[description="他們自以為能夠阻止魔法的傳播，但他們無疑大錯特錯了！他們自以為能藏得住奧達努斯，但我一定要他死！$b$b魔法賦予了我真知……沒錯，我能看到他。一處岔路……就在梣谷森林中的一棵巨樹的頂部。這棵巨樹的名字叫作……瑞恩伍德。它是森林之神最初的幾位子嗣之一。當初，在我找到奧達努斯之前，他就從石爪峰離開了，但現在，他的生命即將結束！$b$b把他的頭帶回來給我，我將送給你一件強力的魔法物品作為禮物。",objectives={"將奧達努斯的頭顱帶給石爪峰的布萊林·火拳。"}]])
R(1089,"大獸穴",[[description="The druids built the Talon Den on Stonetalon Peak, where they keep many powerful items.$b$bThey devised a complex scheme to keep them from falling into the wrong hands.$b$bLuckily, I managed to... extract some details from one of them.$b$bHidden in a small lantern at the entrance of the Den, you will find the Gatekeeper's Key--with it you will be able to open caches around the Den. The items from these caches will allow you to open their hoard, located in one of the central areas.",objectives={"Travel to the Den on Stonetalon Peak. Using the Gatekeeper's Key, obtain the druids' hidden items. Use these items to open the Talon Den Hoard. "}]])
R(1090,"格雷蘇的要求",[[description="You know, I was once the second most important person here at this site. That all changed when Gerenzo took over. Fired my boss, Ziz Fizziks, and sent me down to work in the mines. Ziz told me to stay here and gather information, though. His new boss will pay us well if we can find out what Gerenzo's plans are.$b$bAnyways, what I do know is that Gerenzo has ordered large amounts of this gold-green ore to be mined. I can get you a sample to bring to Ziz, but you'll have to watch for patrols while I get it.",objectives={"Get the mysterious ore from Piznik after he finishes mining it."}]])
R(1091,"向凱拉回報",[[description="$N, take these letters to Kaela. I'm sure she'll want to know about this. Or at least the Sentinels will.$B$BMake sure you tell her how successful we were and how we couldn't have done it without a little bit of magic.",objectives={"Bring the Venture Co. Letters to Kaela Shadowspear."}]])
R(1092,"格雷蘇的要求",[[description="I guess I'd better think about getting out of here, also. It won't take long for word of what happened here to spread to the higher ups, and I'm sure they wouldn't take too kindly to meeting me again.$b$bI'll sneak out and meet with Ziz. Hopefully, he'll be able to find me a new job!$b$bI'll try and clean up this mess a little, but you should take the ore sample to Ziz right away. He told me that he'd set up camp somewhere on the western side of Windshear Crag. Good luck.",objectives={"Deliver the Unidentified Ore to Ziz Fizziks in the Stonetalon Mountains."}]])
R(1093,"超級收割機6000",[[description="風險投資公司到底在搞什麼鬼啊，嗯？他們到底在想些什麼呀？哥布林的公司裡竟然雇傭了一個地精！$b$b好在斯布特瓦夫是個識貨的傢伙，知道我是個天才，他在我被公司炒了以後馬上就雇傭了我！$b$b據說公司正在製造一種新型的大型伐木機，斯布要把我這東西的設計書偷來給他。不過格雷蘇——那個滿手是血的地精——他一看見我就想把我給幹掉……或許你能替我去把設計書給偷來？你應該可以在他們的操作員身上找到它。",objectives={"為石爪山的菲茲克斯偷來超級收割機6000型的設計圖。"}]])
R(1094,"新的指示",[[description="This envelope has all the information I was able to snatch as they booted me out the door... Venture Company internal documents, some manuals, technical things... Oh, and of course the Super Reaper 6000 blueprints.$b$bSputtervalve has taken up residence at Ratchet in the Barrens. Shouldn't have much trouble finding him, he's a little green fellow.",objectives={"Deliver the Sealed Envelope to Sputtervalve in the Barrens."}]])
R(1095,"新的指示",[[description="The matter of this gnome that has been hired by the Venture Company has caused a bit of a stir in Undermine. The trade princes do not approve of Razdunk's consorting with this Gerenzo.$b$bRiddlevox has asked me to take care of the problem, and I'm sure he was instructed to do so by one or more of the trade princes. Of course, the Director didn't tell me that. Let's just say I have a hunch.$b$bWhatever the case, Gerenzo must be removed, and it would be a fitting test to have Fizziks take care of him.",objectives={"Bring the new orders to Ziz Fizziks in the Stonetalon Mountains."}]])
R(1096,"格雷蘇",[[description="我只見過格雷蘇一次，但我得告訴你，那傢伙一眼看起來就知道他不好對付。他的一部分身體似乎已經殘廢了，於是他給自己裝上了一些金屬部件和裝備，這樣他的部分肢體就機械化了。$b$b格雷蘇就在西北方峭壁湖的湖岸邊上監視著整個地區的工作進展。我想我是沒辦法去那裡了……但你看起來也許有能力對付他。$b$b如果你能為我幹掉他的話，我會付給你不錯的酬勞的。",objectives={"將格雷蘇的機械臂帶給石爪山脈的菲茲克斯。"}]])
R(1097,"艾爾默的任務",[[description="暴風城裡有位名叫格瑞曼德·艾爾默的矮人鑄劍師，他需要有人幫忙送一份東西。據我所知，他是把一個包裹送到他在北方的故鄉去。$B$B你看起來很強壯，所以如果你有興趣做這份跑腿工作的話，就去找格瑞曼德吧。我們這兒的確很需要你，但我們也得加強與矮人盟友們的聯繫。$B$B你可以在暴風城矮人區的武器店裡找到格瑞曼德·艾爾默。",objectives={"與格瑞曼德·艾爾默談話。"}]])
R(1098,"影牙城堡裏的亡靈哨兵",[[description="In preparation for an assault on Shadowfang, two deathstalkers were sent to the keep to gather intelligence.  It has been many days and they have not returned, but we must receive their report if we're to have any hope of a successful attack!$B$BSo here is your task, $N.  Go to Shadowfang Keep to the south and find the Deathstalkers Adamant and Vincent.  Find them, and if they require aid then give it.$B$BThis mission is as dangerous as is it critical, $N.  Do not fail.",objectives={"Find the Deathstalker Adamant and Deathstalker Vincent."}]])
R(1099,"Goblins Win!")
R(1100,"亨裏格的日記",[[description="你慢慢打開亨里格·獨眉的這本破舊的日記……",objectives={"閱讀亨里格·獨眉的日記。"}]])
R(1101,"卡爾加·刺肋",[[description="可憐的赫爾拉斯！還有這個矮人……長眉。他是多麼的勇敢啊。$b$b我們不能讓他們的英勇白白犧牲。我們必須阻止這個老太婆……卡爾加·刺肋……。$b$b當然，深入剃刀沼澤是很危險的，但現在沒有時間給達納蘇斯送信了。$n，組織一支隊伍去消滅那個老太婆。$b$b把卡爾加·刺肋的大獎章帶回來給我作為殺死她的證明。",objectives={"把卡爾加·刺肋的大獎章帶給薩蘭納爾的法芬德爾。"}]])
R(1102,"奧爾德的報復",[[description="Cairne is a noble leader for uniting our people here on Thunder Bluff.$b$bBut I cannot forgive those who drove us from our ancestral lands as easily as some. My people inhabited the southern Barrens for decades. The land was holy to us. But we were driven off by numerous foes.$b$bA vengeful fate awaits the crone, Charlga Razorflank, who musters a foul army from within Razorfen Kraul.$b$bBring me Razorflank's heart and I can die in peace, $n.",objectives={"Bring Razorflank's Heart to Auld Stonespire in Thunder Bluff."}]])
R(1103,"水之召喚",[[description="Greetin's, $g brotha:sista;! Have you too come to purify the waters here and prove your understandin' to Islen?$B$BI've just defeated the corrupt water spirit meself, and I'm just 'bout to put da bracers and remaining drops o' water on the brazier.$B$BWhat's dat? Ahhh. Tiev understan' all too well when somethin' goes wrong. Well, Tiev can help you plenty if you be needin' to see the pure water spirit again.$B$BBring me a water sapta from Islen as proof that you be ready, an' I'll wait to turn in me parts.",objectives={"Bring a Water Sapta to Tiev Mordune in Silverpine Forest if you failed to speak to the Minor Manifestation of Water."}]])
R(1104,"含鹽的蠍毒",[[description="我有很多關於改進火箭車的計畫！很多很多！我必須一一嘗試！！！$B$B我在研究一種新燃料，一種燃燒起來非常非常熱的燃料！！但是我還沒有將配方製作到盡善盡美，我想我知道還缺什麼東西……$B$B在閃光平原上遊蕩的蠍子體內有一種含有很多鹽分的毒液，這種毒液非常特別！那正是我想要的！$B$B帶些毒液給我，相信我——有了這些毒液，我們的賽車就可以快到飛起！！",objectives={"為閃光平原的菲茲爾·銅栓帶去6份含鹽的蠍毒。"}]])
R(1105,"硬化龜殼",[[description="我的兄弟正在為他的火箭車研究一種新燃料。他很聰明，真的是太聰明了……我想他設計的新燃料一定非常強悍，強到甚至可以蝕穿車子的底盤！$B$B為了防止這種情況的出現，我得應該強化一下燃料箱。$B$B這片平原上的烏龜有很硬的殼，我想用它們來製造火箭車的新燃料箱，這樣就可以裝載我兄弟的新燃料了。$B$B你看起來很可靠，願意去給我弄一些這樣的殼嗎？",objectives={"收集9塊硬化龜殼，把它們交給閃光平原的維茲爾·銅栓。"}]])
R(1106,"流放者馬特克",[[description="我正在研製一種新的引擎，它可以讓車子開得非常快！快到足以飛起來！我只要再做出能承受非常非常重的壓力活塞就好了，我之前所有的試做都失敗了，因為我做不出夠堅固的活塞！$B$B但是有人可能知道怎麼解決這個問題。$B$B他的名字叫做流放者馬特克，是個偉大的鐵匠，他比任何人都更加瞭解金屬的特性。把這封信交給他，我知道他能幫我！$B$B但他在很遠很遠的地方，在艾澤拉斯大陸上的荒蕪之地，和一個哥布林同住在一個營地裡！$B$B去找他吧！",objectives={"把菲茲爾·銅栓的信帶給荒蕪之地的流放者馬特克。"}]])
R(1107,"堅硬的尾鰭",[[description="我們的火箭車是平原上速度最快的！不過有點太快了……我擔心高速行駛中的摩擦力會把它給撕開！$B$B為以防萬一，我要配製一種合成劑來給車子的轉動部件塗上。它必須堅固、耐衝擊、能抵抗鹽分的侵蝕，並且不易老化。$B$B你聽說過暗礁海嗎，$N？它就在荊棘谷地區的海岸邊。鹽鱗魚人在那一帶活動，它們的尾鰭正是我所需要的重要原料！",objectives={"給閃光平原上的瑞茲爾·銅栓帶去10片堅硬的尾鰭。"}]])
R(1108,"精鐵碎片",[[description="我大老遠地跑到這兒來並不是為了躲開什麼人。$N，如果你有足夠的勇氣，那麼荒蕪之地的礦藏絕對可以讓你大發橫財。$B$B有一種被稱作精鐵的礦石，據說它具有很強的耐壓和耐熱性，這也許會對菲茲爾的車有所幫助。$B$B但是我們需要進一步地確定。去幫我找些精鐵的樣品來測試它的特性吧。$B$B真正的精鐵礦石深藏在奧達曼，但荒蕪之地的石窟穴居人身上常常帶著一些礦石碎片，給我找一些這種礦石碎片來。",objectives={"收集10塊精鐵碎片，把它們交給荒蕪之地的流放者馬特克。"}]])
R(1109,"蝙蝠的糞便",[[description="As you can see, $n, we're up to some very.... interesting experiments at the Royal Apothecary Society.$b$bAs the Master here, it is my job to oversee the most ambitious of our alchemical attempts. So much work and so little time!$b$bYou look well traveled for a $c. Perhaps you can aid me.$b$bI'm in need of a rare substance. It's foul material; it comes from a rare species of bats only found in the muck-hole known as Razorfen Kraul. Bring to me the guano from the Kraul Bats so we can begin our work...",objectives={"Bring 1 pile of Kraul Guano to Master Apothecary Faranell in the Undercity."}]])
R(1110,"火箭車零件",[[description="咳咳，所有的賽車跑起來都像飛一樣，出一些小事故也就不足為奇了。如果你在閃光平原四周轉轉的話，就會看到過去撞車事故的遺物——火箭車的碎片散落得到處都是！$B$B這些零件對地精和哥布林來說非常值錢，它們一直都想為它們的賽車裝上更多的設備。$B$B所以你可以去給我搜集這些零件，我會給你巨額報酬的。",objectives={"收集30個火箭車零件，把它們交給閃光平原的克拉維爾·濃須。"}]])
R(1111,"碼頭管理員迪茲維格",[[description="滿足人們的需要就是我的工作，現在那邊的地精弟兄們需要一些零件。一星期前那些零件就已經運到棘齒城了，但我一直都沒有時間去取貨。$B$B所以……你願意替我跑一趟嗎？到棘齒城去，將這張零件訂單交給碼頭管理員迪茲維格——他很可能就在碼頭上忙活。$B$B我的朋友，這些工作的報酬可是非常誘人的哦……",objectives={"把克拉維爾的零件訂單交給棘齒城的碼頭管理員迪茲維格。"}]])
R(1112,"給克拉維爾的零件",[[description="這是克拉維爾要的貨，$N。你把貨交給他的時候記得轉告他……如果他想要訂更多特別的貨，就必須先把錢付清！",objectives={"把克拉維爾的零件交給閃光平原的克拉維爾·濃鬚。"}]])
R(1113,"狂熱之心",[[description="Why do I need a rare type of guano, you might ask. Well, for this experiment I want to see what effect two diametrically opposed chemical substances can have on each other, especially when both are combined with an ever-toxic agent to ensure the most... ghastly results.$b$bIn the northeastern peaks of Tirisfal Glades lies the Scarlet Monastery. There the crazed disciples of the Scarlet Crusade congregate. Slay them and bring me their zealous hearts.$b$bOur concoction will be most wicked!",objectives={"Master Apothecary Faranell in the Undercity wants 20 Hearts of Zeal."}]])
R(1114,"侏儒的貨物",[[description="既然手續齊備，那你就把這些零件帶給菲茲爾·銅栓吧。他已經等這些東西很久了—我相信他不會在意我從他那些零件中拿了點小東西……$B$B當然我也不會和他提這件事情，這對於他來說只是個不值錢的小東西而已。$B$B相信我。",objectives={"把精密的賽車零件交給閃光平原的菲茲爾·銅栓。"}]])
R(1115,"車手的傳聞",[[description="既然我們已經為地精服務過了，那麼也該幫幫哥布林一把！$B$B我聽說哥布林的賽車手，就是名叫納茲·斯迪波爾的那個，他並不是一直都用這個名字。我想知道他為什麼改名字，這其中是否隱藏著一個秘密，還有……我不知道他是否很看重這個秘密。$B$B如果說有人知道真相的話，那肯定是在荊棘谷南端的藏寶海灣裡的克拉茲克。去找克拉茲克談談，問問他關於那個哥布林駕駛員的事情。$B$B如果你從他那兒得到有用的資訊的話，我們也許能從中掙一大筆錢。",objectives={"和藏寶海灣的克拉茲克談話。"}]])
R(1116,"夢境之塵",[[description="你打聽到的有關納茲的消息真是幫了我一個大忙，$N，確實幫了我一個大忙。既然你已經特意大老遠地從閃光平原趕來……那麼你是否願意再多走些路呢？$B$B在我想辦法打聽相關資訊的時候，你何不去幫我收集一些東西呢？$B$B嗯……怎麼樣？幫我找一些夢境之塵吧，你可以在悲傷沼澤的幼龍和龍族的身上找到夢境之塵。我很喜歡在鼻煙袋裡放一點夢境之塵！$B$B給我弄些夢境之塵來，$N，我會用你需要的資訊和你進行交換。",objectives={"為藏寶海灣的克拉茲克收集10份夢境之塵。"}]])
R(1117,"地精的謠言",[[description="I had to use some of my favors, and gave away a rare bottle of elven wine, and did some heavy deducing myself!  But I found the information you seek.$B$BHere, I wrote a letter with some very interesting bits on our friend, Nazz Steamboil.  Do with it what you will -- it's too dangerous for me to use.$B$BJust don't tell anyone where you got it!",objectives={"Bring the Goblin Rumors to Kravel Koalbeard in the Shimmering Flats."}]])
R(1118,"返回藏寶海灣",[[description="$N，你是個值得信賴的$c，既能把任務做好，過程中又能守口如瓶。$B$B我在醞釀一個新的計畫。這個計畫非常危險，但只要成功，我們就能大賺一筆！我想你正是做這件事的最佳人選。$B$B首先，你必須回去藏寶海灣一趟。我很抱歉，好心的$N，我知道上一個任務才把你派到那兒去，但是這次，你得去和克蘭克·菲茲巴布談談。$B$B把這封信帶給他，如果他需要幫助，盡你所能去幫他。你的努力會得到應有的回報的。",objectives={"把克拉維爾的計畫書交給藏寶海灣的克蘭克·菲茲巴布。"}]])
R(1119,"贊吉爾的藥劑和蠢人酒",[[description="I figured out how to use Zanzil's mixture with stout to make a powerful libation.  A Fool's Stout.  I think it'll be just what Kravel needs, but try it out and let me know how it works.$B$BAnd $N, don't keep this stuff too long without using it.  Zanzil's mixture has a weird effect on the stout's yeast, kicking it into high gear.  So it won't stay fresh forever.",objectives={"Bring the Fool's Stout back to Kravel in the Shimmering Flats."}]])
R(1120,"灌醉侏儒",[[description="We need to try the Fool's Stout on one of the pit crews.  If you want to try it on the gnomes, then here -- take the stout and give it to the gnome pit boss.$B$BAnd don't wait too long.  This stout will go bad eventually.",objectives={"Bring the Fool's Stout to the Gnome Pit Boss."}]])
R(1121,"灌醉地精",[[description="We need to try the Fool's Stout on one of the pit crews.  If you want to try it on the goblins, then here -- take the stout and give it to the goblin pit boss.$B$BAnd don't wait too long.  This stout will go bad eventually.",objectives={"Bring the Fool's Stout to the Goblin Pit Boss."}]])
R(1122,"向菲茲巴布報告",[[description="That Fool's Stout worked great!  I placed a bet on the next race, and... let's hope the crew you got drunk did a number on their car!$B$BThere's only one more task for you -- take this note back to Crank Fizzlebub in Booty Bay.  He'll want to know of the successful test.$B$BAnd hopefully we can get more of that Fool's Stout for future races!",objectives={"Bring the Fool's Stout report to Crank Fizzlebub in Booty Bay."}]])
R(1123,"拉比恩·薩圖納",[[description="For this task, Keeper Remulos' majordomo in Moonglade - Rabine Saturna - seeks aid in exploring the vast wastelands far to the west of Tanaris and Un'Goro.  He is located in Nighthaven, the main village of Moonglade.$B$BI want to impart on you the importance of your presence.  There are growing tensions between the night elves of Darnassus and the Cenarion Circle in Moonglade.  Look beyond racial boundaries and tap into the wisdom of your ancestors in dealings with the Circle there, $N.  Good luck.",objectives={"Speak with Rabine Saturna in the village of Nighthaven, Moonglade.  Moonglade lies between Felwood and Winterspring, accessible through a path out of Timbermaw Hold."}]])
R(1124,"廢土",[[description="在安戈洛環形山以西，穿過西北部的山脊，是一片荒蕪的土地——希利蘇斯。很少有人知道，夜精靈曾在那裡與一個邪惡而詭異的種族進行過一場惡戰。邪惡最終被封印了，但是我懷疑它們正在蠢蠢欲動，想要讓恐懼捲土重來……$B$B去尋找我們派往希利蘇斯的一名使者，萊耶·星擊。他就在勇士之墓，那兒是在戰爭中犧牲的勇士們安息的地方。把這封信交給他，他就會信任你。",objectives={"在希利蘇斯的勇士之墓附近找萊耶·星擊談談，把拉比恩的信交給他。"}]])
R(1125,"南風村的靈魂",[[description="在我們的西南方有個悲慘的地方——南風村的遺跡。我們就從那裡開始吧，$N。$B$B根據我所掌握的情報，那座村莊曾經是夜精靈在希利蘇斯的基地。很久以前異種蠍群攻陷那裡，並將其夷為一片廢墟。我簡直不敢去想像南風村被蟲群吞沒的恐怖景象……$B$B那些飽受痛苦的德魯伊和哨兵的亡魂在那座遺跡中漫無目標地遊蕩。探索那個地區，並釋放那些悲慘的靈魂。",objectives={"在南風村釋放8個被折磨的德魯伊和8個被折磨的哨兵的靈魂，然後向希利蘇斯勇士之墓的萊耶·星擊覆命。"}]])
R(1126,"塔中之巢",[[description="我們必須找到南風村的異種蠍巢穴，而我知道有一個方法可以找到它。以我的經驗來看，它們對於周圍的環境很敏感，這也就解釋了為什麼它們會在聽到靈魂的死亡嚎叫之後發起攻擊。$B$B塔里的異種蠍群最為強大——就是那座有很多飛蟲圍繞著的塔。爬上那座塔，然後騷擾蟲巢。向我彙報你所發現的東西！如果你找到了什麼有價值的東西，就把它帶回來給我。",objectives={"爬上南風村的塔，找尋啟動異種蠍群的方法。把任何你認為不尋常的東西交給希利蘇斯勇士之墓的萊耶·星擊。"}]])
R(1127,"蠢人酒",[[description="So you want some Fool's Stout, eh?  Thinking of heading back to the races...?$B$BAll right, bring me more of Zanzil's mixture and I'll make some more stout for you.",objectives={"Bring 12 of Zanzil's Mixture to Crank Fizzlebub in Booty Bay."}]])
R(1130,"梅洛的關註",[[description="$N，梅洛·石蹄已經聽說了你的作為，並為你的將來做了打算。$B$B如果你願意的話，去雷霆崖和他談談，他就在獵人高地上。",objectives={"和雷霆崖的梅洛·石蹄交談。"}]])
R(1131,"鋼齒土狼",[[description="有時我們為了食物而狩獵，有時我們為了榮耀而狩獵，而有時我們為了得到大地之母的教誨而狩獵。$B$B但是這次我讓你去捕獵的卻是一個例外中的例外，我要你去殺死一個不被大地之母所祝福的生物。$B$B這個名叫鋼齒土狼的生物游走於貧瘠之地南面的千針石林，它是個殘暴的統治者，牠率領著其他的土狼，給原本平靜的獸群帶來恐懼和無謂的傷亡。$B$B找到鋼齒土狼，$N，找到牠並打敗牠。",objectives={"把鋼齒土狼的肋骨交給雷霆崖的梅勒。"}]])
R(1132,"菲歐拉·長耳",[[description="哦，又來到了海上！感受著清風溫柔的吻，讓海浪拍打著我的身體，這讓我不禁想起我那可敬的母親。$B$B好心的$c，希望我能有像你一樣的好運，因為我一眼就看出你會做出一番轟轟烈烈的事業！$B$B我應該把卡林多的故事講給每個人聽，卡林多是一片充滿機遇的土地！如果你願意去海的那邊試試運氣，就乘著船去那迷人的塞拉摩港吧，到那裡去和我的精靈同伴菲歐拉·長耳談一談。$B$B她將指引你開始卡林多的冒險之旅！",objectives={"和塞拉摩的菲歐拉·長耳談話。"}]])
R(1133,"通往阿斯特蘭納的旅途",[[description="如果你剛從米奈希爾港坐船過來，那麼你應該先到阿斯特蘭納去。我確信像你這樣熱心的聯盟成員會在這裡有一番作為的。和辛德瑞爾·速火談一談，盡可能地幫助他吧。$B$B對了，你不必提起我，因為辛德瑞爾根本不認識我……",objectives={"到阿斯特蘭納去和辛德瑞爾·速火談談。"}]])
R(1134,"石爪山的雙足飛龍",[[description="儘管我們還沒有跟部落全面開戰，但是這來之不易的和平卻已經處於崩潰的邊緣了，最近他們愈加頻繁地展開針對我方的秘密行動。$B$B我們安插在塞拉摩的密探向我們報告說，在石爪峰南面的暗色湖一帶有許多巨翼雙足飛龍在活動，而獸人正在該地收集它們的毒液，然後獸人的刺客就會使用這些毒液來悄無聲息地對聯盟發動致命的突襲！$B$B如果他所說的都是真的，那麼我們就必須阻止他們，$N。我們必須切斷他們的毒液來源！",objectives={"收集12個巨翼雙足飛龍的毒囊，並把它們交給阿斯特蘭納的辛德瑞爾·速火。"}]])
R(1135,"風巢雙足飛龍的毒囊",[[description="你也許知道，獸人們通常會馴化雙足飛龍以供騎乘之用。但很少有人知道，從某種角度來說，雙足飛龍的毒液比它們本身更有價值。如果你不介意狩獵雙足飛龍的話，那麼……我有一項工作交給你。$B$B在我們東邊的千針林裡有一個叫風巢的地方，生活在那裡的雙足飛龍的毒液不但毒性非常強烈，而且價值極高。",objectives={"收集10個風巢雙足飛龍的毒囊，把它們帶給塞拉摩的菲歐拉·長耳。"}]])
R(1136,"霜喉雪人",[[description="$N, it is now time for you to travel to far-off lands.  You are ready.$B$BYou now hunt Frostmaw, a yeti in the Alterac Mountains.  He is elusive, his white coat blending into the snows of his mountain home.  He rarely shows himself.$B$BBut I will show you how to entice a creature such as he.  Here, take this scroll.  On it I have written how Frostmaw may be lured.$B$BNow go, $N.  Your journey is long and many challenges lay waiting.  When you return with Frostmaw's mane, only then is your task complete.",objectives={"Bring Frostmaw's Mane to Melor Stonehoof in Thunder Bluff."}]])
R(1137,"回復菲茲爾",[[description="精鐵有驚人的抗熱性！我肯定它對菲茲爾要製造的活塞有所幫助，但他需要真正的精鐵礦石，而不僅僅是一些小碎片。$B$B完美的礦石只能從荒蕪之地北部邊境的奧達曼挖掘場深處采到，只有那裡才是精鐵礦真正的產地。$B$B請代我向菲茲爾·銅栓致意，並把我對你說的話告訴他。$B$B路上小心，$N。我相信我們會再次見面的。一旦菲茲爾知道有精鐵這樣一種東西，他一定會讓你幫他去奧達曼採集那些礦石的！",objectives={"和閃光平原的菲茲爾·銅栓談話。"}]])
R(1138,"海中的水果",[[description="我愛螃蟹，螃蟹就好像是海中的水果！你可以把它烤了吃、煮了吃、燉了吃、炸了吃、炒了吃、煎了吃；你可以把螃蟹做成螃蟹沙拉、螃蟹湯、螃蟹燉肉、黑胡椒螃蟹、檸檬汁燉螃蟹、清蒸螃蟹和鐵爐堡特級螃蟹——這就是螃蟹存在的意義！$B$B我現在要留在這裡釣魚，所以沒有辦法自己去找到上好的螃蟹肉。你可以從暗礁蟹和硬殼潮行蟹身上得到品質上乘的螃蟹肉，然後把它們烤了吃、煮了吃……",objectives={"收集6塊優質蟹肉，把它們交給奧伯丁的古博·布拉普。"}]])
R(1139,"意誌石板",[[description="通過切斷暗爐部族與黑石塔的聯繫，我們已經成功減緩了他們的行動。不過，鐵趾的遺願仍未完成，他不能就這麼白白死去。他的夢想是要找到意志石板，那是一塊注入了魔法能量的石頭碎片。利用這種魔法，泰坦賦予那些由他們創造出來的物體以鮮活的生命，甚至將思想和意志賜予這些生命。$B$B我們必須趕在暗爐部族之前找到意志石板。$B$B返回奧達曼去找到石板，然後立刻回到這裡。",objectives={"找到意志石板，把它們交給鐵爐堡的顧問貝爾格拉姆。"}]])
R(1140,"奧薩拉克斯之塔",[[description="獸人們寫起字來比小孩子的塗鴉好不到哪裡去。當我決定去學習他們的語言時，我的許多部下都曾經取笑過我，但我想這樣做還是有助於進一步瞭解我們的敵人。$b$b從伊克魯德的亂七八糟的文字中，我們可以知道埃瑟里克斯仍掌握著兩顆靈魂寶石，它們分別被放在梣谷東北部的夜道谷和薩提納爾，這兩個地方都是被薩特控制的地區。$b$b小心點，$n，面對那些被薩特之血浸透了地面的神殿，即使是像你這樣經驗豐富的$c也會心神不寧的。",objectives={"在夜道谷和薩提納爾找到被禁錮的高等精靈的靈魂，釋放他們，然後回到邁斯特拉崗哨的淨化者德爾葛蘭那裡。"}]])
R(1141,"釣魚世家",[[description="I love fishing.  The Blump family is known for fishing.  My name is Gubber Blump; I fish.$B$BThere's a kind of fish I like to catch around these parts called Darkshore grouper.  I used to go out on a boat to fish for grouper, but no boats have been going out since them mean ol' murlocs moved in.  I bet they been eating up all the grouper too.$B$BSay, you wanna help me catch Darkshore grouper?  I'd give you a bona fide Blump Family Fishing Pole if you did!  It's a real good pole to catch fish with.",objectives={"Catch 6 Darkshore Grouper for Gubber Blump in Auberdine."}]])
R(1142,"臨終遺言",[[description="I have not long to live... so... so... weak.$b$b...the b-b-brave dwarf, Lonebrow, has been sent to w-w-warn Falfindel...$b$bBut before I... d-d-die...$b$b...my wife, Treshala... her pendant of bonding to me... stolen... by one of the f-f-foul aggressors...$b$bFind it p-p-please... and return it to Treshala in Darnassus...$b$b...along with w-w-word of my lonely... death.",objectives={"Find and return Treshala's Pendant to Treshala Fallowbrook in Darnassus."}]])
R(1143,"奧薩拉克斯之塔",[[description="我知道了。如果你所說的是真的，那麼我們必須馬上發起進攻。我認為埃瑟里克斯就住在塔上。不過你要當心，在他的周圍有很多強大的術士，比你以前所見到過的任何術士都還要可怕。",objectives={"殺掉埃瑟里克斯·納拉辛，把他的項上人頭交給奧薩拉克斯之塔附近的巴蘇爾·影擊。"}]])
R(1144,"進口商威利克斯",[[description="At last, help has arrived!$b$bYou have no clue how long I've been held prisoner here. I can't remember the last time I saw the outside of this place.$b$bYou see, I am an entrepreneur. Always out for a copper, as they say. I caught wind that Mebok Mizzyrix was paying well for Redleaf Tuber from this here pig pen. I figured it would be an easy in, easy out kind of affair. As you can see, I was a bit wrong!$b$bAnyway, if you'd be so kind as to help me get out of here, I'll make it worth your while.",objectives={"Escort Willix the Importer out of Razorfen Kraul."}]])
R(1145,"瘋狂的蟲群",[[description="Many travelers who've come through the Crossroads helped me gather eggs from the Field of Giants, and many of them have tales of how deadly the creatures are. I've heard enough to consider them insects a much larger threat than my masters first thought.$B$BI need a courier to travel to Orgrimmar to meet Belgrom Rockmaul. It be no simple matter, and someone who would take the task seriously should go.$B$BBelgrom usually be found outside the warriors' guild house.",objectives={"Deliver Korran's Sealed Note to Belgrom Rockmaul in Orgrimmar."}]])
R(1146,"瘋狂的蟲群",[[description="So, Korran has come to a similar conclusion about these insects--they seem to be a larger threat than we assumed.$B$BA few days ago a hunter returned to me from Thousand Needles nearly dead. He was with a raiding party sent to drive a dwarven excavation team out of the Shimmering Flats. During the attack, more of these insects erupted from a cave in the dig site and nearly killed the party.$B$BThey were led by Moktar Krin, and they've taken refuge on the border of the Shimmering Flats. Bring him this note.",objectives={"Deliver Belgrom's Sealed Note to Moktar Krin in Thousand Needles."}]])
R(1147,"瘋狂的蟲群",[[description="Hmm. Seems Belgrom thinks those monsters are a threat. He wants them pushed back into whatever depths they crawled up out of.$B$BI guess killing the dwarves sent by the Explorers' League wasn't enough--now I have to send a half-dead war party into another battle. We won't be able to do it ourselves; not while we're in this condition. The dig site's to the south of here. There shouldn't be anymore dwarves to deal with. Feel up to wielding a blade or staff and doing your part to aid us?",objectives={"Kill 5 Silithid Searchers, 5 Silithid Hive Drones, and 5 Silithid Invaders and return to Moktar Krin in Thousand Needles."}]])
R(1148,"蟲群的樣本",[[description="You inspect the carapace carefully. As you turn it over in your hands you realize that the chitinous plating is interlaced in such a way that makes it incredibly strong. It's unlike anything you've ever seen. You inspect the rest of the corpse further and realize that these creatures are very powerful and highly evolved.$B$BLooking down at the carapace again, you think that Korran would enjoy studying more of these creatures. It could help him figure out what these creatures are, and where they come from.",objectives={"Bring 1 Silithid Heart, 5 Silithid Talons, and 3 Intact Silithid Carapaces, to Korran at the Crossroads."}]])
R(1149,"信仰的試煉",[[description="So, you have sought me out, or perhaps destiny brings you to me? No matter. You are here now, and so your journey will begin anew.$B$BMany facets make up a being: the spirit, the body, the mind. Some of these can be measured by a culture's traditions. Others we can only hope exist within ourselves. If you agree, I shall test some of the facets within you.$B$BIf you pass, then you shall become stronger. If you fail, then you will realize the vastness of the Nether.$B$BThe first is a Test of Faith.",objectives={"If you have faith, leap from the planks overlooking Thousand Needles."}]])
R(1150,"耐力的試煉",[[description="我很高興看到你的勇氣依然不減。既然你的信念已經不可動搖，那麼現在就讓我們來對你的體能進行試煉吧。$B$B首先是耐力的試煉。到亂風崗西邊的飛羽洞穴去一趟，進入那些鷹身人的巢穴最深處，毀掉它們的糧食儲備。那樣肯定會讓它們勃然大怒，如果你能夠在鷹身人的圍攻之中生存足夠長的時間，那麼格林卡·血嘯就會親自出來對付你——殺了她，把她的爪子帶給我，以此來證明你完成了試煉。",objectives={"把格林卡的爪子交給千針石林的多恩·平原行者。"}]])
R(1151,"力量的試煉",[[description="During the time of the Old Gods, elementals inhabited much of this world. They worshipped the Old Gods, and the Gods, through their power, kept the elementals bound to this world. When the Old Gods were banished, the elementals faded from our world and now only return at the bidding of powerful mages.$B$BThere are exceptions though. Some elementals were powerful enough to remain here on their own. One such elemental is Rok'Alim.$B$BTo test your strength, find Rok'Alim in Thousand Needles and slay him.",objectives={"Bring Fragments of Rok'Alim to Dorn Plainstalker in Thousand Needles."}]])
R(1152,"知識試煉",[[description="Your time with me is just about finished. I am knowledgeable, but the Test of Lore is not mine to give. There are lessons to be learned and places to visit that others claim domain over.$B$BIf you are prepared, then seek out Braug Dimspirit--he is a shaman of great wisdom. He will test you further, so heed his words, $N.$B$BWhen you are ready, find the tunnel that connects the Stonetalon Mountains with Ashenvale: Braug dwells near there. And be careful, $N, the night elves may wish to impede your test.",objectives={"Find Braug Dimspirit near the entrance to Talondeep Path in Stonetalon Mountains."}]])
R(1153,"新的礦石樣本",[[description="$C, you have done well in helping me in the past. The warchief is pleased thus far with what I've accomplished, and asks me to continue with renewed determination. My honor dictates that I give you proper recognition to the warchief for all you have done, but first I would ask you for your help again.$B$BTravelers recently came from the south from a place called Thousand Needles. There they killed a kobold who had an unusual ore sample, but they would not sell it. I want a sample of that ore to examine.",objectives={"Find an Unrefined Ore Sample on a Gravelsnout Digger or Surveyor and bring it to Tatternack Steelforge at Camp Taurajo in the Barrens."}]])
R(1154,"知識試煉",[[description="You have passed Dorn's tests, and now you seek to pass your next trial. Very good. But up until now, your challenges have been childish. It is easy to test your body--your mind is another matter completely.$B$BI shall explain it simply: find the book I name, study it, and answer my question about its contents.$B$BWhat book, you must be asking? The Legacy of the Aspects. It can be found at the bottom of Dor'danil in southern Ashenvale, protected by the dead druids and their slayers.",objectives={"Find the Legacy of the Aspects and return it to Braug Dimspirit near the entrance to Talondeep Path in Stonetalon Mountains."}]])
R(1155,"<NYI> <TXT> bug crystal side quest",[[description="x",objectives={"x"}]])
R(1156,"<NYI> <TXT> speak to alchemist pestlezugg",[[description="x",objectives={"x"}]])
R(1157,"<NYI> <TXT> pestlezugg needs items")
R(1158,"<NYI> <TXT> speak to rabine saturna",[[description="x",objectives={"x"}]])
R(1159,"知識試煉",[[description="Well done, $N. You have passed the first portion of the Test of Lore, but there is still another question to be answered. But that question is not mine to ask.$B$BSeek out Parqual Fintallas in Lordaeron City. He was a great historian for the humans before the Plague overtook him. Now he continues to seek enlightenment, but of a different nature.$B$BHe will have another requirement of you before he asks you anything, but you have done masterfully thus far--I'm sure you will overcome his obstacle.",objectives={"Find Parqual Fintallas in Undercity."}]])
R(1160,"知識試煉",[[description="I will tell you what you must seek, and I will even ask you my question, but not because you wish to prove yourself. Knowledge is far more important than strength. Even as others seem to pass you by in ability, your knowledge of the world will be more valuable.$B$BGo to the Monastery in the north of Tirisfal Glades. In the library there, a book called Beginnings of the Undead Threat resides. It was used by the now-corrupt paladins there to train them to fight my kind.$B$BBring it to me.",objectives={"Find The Beginnings of the Undead Threat, and return it to Parqual Fintallas in Undercity."}]])
R(1161,"<NYI> <TXT> gossip shade of ambermoon",[[description="x",objectives={"x"}]])
R(1162,"<NYI> <TXT> speak to hamuul runetotem",[[description="x",objectives={"x"}]])
R(1163,"<NYI> <TXT> speak to tyrande whisperwind",[[description="x",objectives={"x"}]])
R(1164,"科娜塔壹家",[[description="賤人！豬頭！科娜塔竟然還活著！我在這裡受苦受難，她居然全家和睦健康，人丁興旺的。我被她拋棄了！$B$B我已經沒有家了，他們都被瘟疫帶走了。我的財產也都在戰爭中被搶光燒光了。這些也就算了，然而就是她和她的那些野種們，竟然厚著臉皮趁我不在的時候偷走了我家最後一件值錢的東西。$B$B我倒是不再關心那些被偷的東西了。現在我要的是他們的人頭！$B$B到阿拉希高地去，避難谷地的東北方有一個達比雷農場，去那裡把他們都給我殺光啊！",objectives={"將科娜塔、法迪爾和馬塞爾的頭顱交給幽暗城的吉納維·卡隆。"}]])
R(1166,"莫格穆洛克的任務",[[description="Bow before Overlord Mok'Morokk!$b$bRexxar make me mighty leader of Stonemaul Clan!$b$bMe good leader. Me keep clan safe.$b$bBig dragons come and make fire at old home. Me smart ogre. Find new home for clan here.$b$bLeave old home so fast, me forget stuff. Tiny $r, go get my things. Go south and find my yummy grog, my snuff and my strongbox. Me like you after you do that. You look in Den of Flame and Stonemaul Ruins... they be there, me sure!",objectives={"Overlord Mok'Morokk in Brackenwall Village wants you to retrieve his grog, snuff and strongbox in Dustwallow Swamp."}]])
R(1167,"奧薩拉克斯之塔",[[description="在你正面對抗埃瑟里克斯之前，最好先向巴蘇爾請教請教。毫無疑問，他一直都在警惕地觀察著那座塔，應該會有一些新消息。",objectives={"去和奧薩拉克斯之塔附近的巴蘇爾·影擊談話。"}]])
R(1168,"黑龍軍團",[[description="Mok'Morokk was made Overlord by Rexxar. He care more for power than he care for ogres.$b$bBlack dragons kill many ogre. Kill Tharg's wife. Mok'Morokk tell us to run. Make us come here.$b$bOgre should fight. Ogres not good at running. Mok'Morokk care only about Mok'Morokk.$b$bMe call Stonemaul Ruins home. Me like it in the south. This place not home.$b$bHelp ogres fight army of the black dragon. Me want revenge. Me want to go home.",objectives={"Tharg in Brackenwall Village wants you to kill 15 Firemane Scouts, 10 Firemane Ash Tails, and 5 Firemane Guards."}]])
R(1169,"群龍之首",[[description="Whilst that craven fool, Mok'Morokk, wallows in power and Tharg wrestles the demons of sorrow and vengeance and vies for leadership of the clan, I seem to be the only one concerned with identifying the source of aggression on our old home.$b$bWhy the puzzled stare, $n? Expecting me to speak like an uncouth ruffian merely because I am an ogre?$b$bNow back to business, bring to me the hearts and tongues from the whelps and hatchlings. I shall trace the root of this evil...",objectives={"Draz'Zilb in Brackenwall Village would like you to bring him 15 Searing Tongues and 15 Searing Hearts."}]])
R(1170,"奧妮克希亞的血脈",[[description="Stonemaul Village was invaded by the brood of Onyxia. But why would the daughter of the black dragonlord, Deathwing, descend upon our lands?$b$bThis is most troubling. Surely, Onyxia was driven here for a purpose beyond laying siege to a small band of ogres.$b$bNotify Mok'Morokk at once! Action must be taken.",objectives={"Speak with Overlord Mok'Morokk in Brackenwall Village."}]])
R(1171,"奧妮克希亞的血脈",[[description="You leave me alone now. Go tell Draz'Zilb we stay here. No black dragon here.",objectives={"Speak with Draz'Zilb in Brackenwall Village."}]])
R(1172,"奧妮克希亞的血脈",[[description="Onyxia's brood has been scattered across the Dragonmurk. It is imperative that no more whelps be permitted to hatch.$b$bMake haste to Wyrmbog in the south of Dustwallow Marsh. Surely, she has made her lair there. Track down the evil dragon's eggs and destroy them.$b$bWe will never reclaim Stonemaul Village if the surrounding area remains a breeding ground.$b$bAs for Mok'Morokk... I have other plans for the sod.",objectives={"Draz'Zilb in Brackenwall Village wants you to destroy 5 Eggs of Onyxia."}]])
R(1173,"挑戰莫格穆洛克",[[description="You dare challenge Overlord Mok'Morokk?$b$bHaw!$b$bMe crush tiny $r!$b$bYou tell me when ready for good beating.",objectives={"Defeat Mok'Morokk and report the news to Draz'Zilb in Brackenwall Village."}]])
R(1174,"Gnomes Win!")
R(1175,"安全隱患",[[description="自從哥布林的紅雷賽車和一隻大蜥蜴撞了個滿懷之後，科魯克萊德就雇了我去看守賽道。我不知道平原上的這些動物都是吃什麼的，居然長得這麼大，但我們必須多加小心，免得它們在比賽時突然跑進賽道裡。$b$b我跟你說啊，如果你想打點零工的話，那就去把這些蜥蜴趕走吧。",objectives={"為閃光平原的賽道管理員澤爾林殺死10條鹽石蜥蜴、10條鹽石水晶蜥蜴和6條鹽石凝視者。"}]])
R(1176,"減輕負重",[[description="說到賽車，每一點都很重要！不論是動力輸出的調整，壓力線圈的鬆緊，或者是對於整部機車重量的控制，每一項都很關鍵，所以你必須考慮所有的東西。$b$b我們用禿鷲的骨頭對賽車進行了改造，這樣就提供了力量與重量的完美平衡，真棒。更棒的是，我們可以很容易地得到更多的禿鷲骨頭，因為這一帶到處都是禿鷲。$b$b去幫我找一些禿鷲骨頭來，我會給你個好價錢的。",objectives={"給閃光平原的普茲克找10根空心禿鷲骨。"}]])
R(1177,"餓！",[[description="泥漿大巨魔。$b$b我餓了。$b$b去抓點魚來。給泥漿一些吃的。$b$b你要不就餵飽泥漿，否則泥漿就會吃你。",objectives={"塵泥沼澤北部的馬德克拉什要你去抓12條泥鰭小魚。"}]])
R(1178,"地精贊助商",[[description="不管在哪裡，我們的賽車隊都是哥布林的驕傲。你會對那些以各種方式為車隊貢獻自己力量的人感到吃驚的。$b$b你認識加茲魯維嗎？他為我們從全世界尋找賽車零件，有一次他甚至為我們找來了一台完整的賽車！$b$b幾星期前，他說他要送給我們一套新的燃油調節器，但至今還沒有到貨。他一向說話算數……你能去棘齒城幫我問問嗎？我原本並不是特別心急，但是地精正在趕上我們的步伐！",objectives={"和棘齒城的加茲魯維談話。"}]])
R(1179,"防撞頭盔",[[description="You ever heard of the Shimmering Flats?  It's a stretch of salt flats way over in Kalimdor, just south of the Thousand Needles canyon.  It's a great place for racing because, well, it's so flat!$B$BA couple of gnome brothers are out there, friends of mine, trying out their new rocket car, and from what I hear it's fast!  Heh, so fast that their pilots keep crashing.  Giving themselves concussions.$B$BSo they asked me for some Siege Engine helmets, but I have duties here.  I can't make the trip!$B$BCan you?",objectives={"Bring the crate of crash helmets to Wizzle Brassbolts in the Shimmering Flats."}]])
R(1180,"地精贊助商",[[description="回到關於你為何來這裡的話題上。我的確向普茲克保證過會幫他運一台新的調節器，但我現在還沒有收到這台機器。藏寶海灣的里維加茲說他已經把東西裝船運了過來，也許是在運輸過程當中出了什麼差錯。$b$b如果是那樣的話，我們就無能為力了。現在我只知道它已經從藏寶海灣運了出來。$b$b去找碼頭管理員羅茲基爾吧，他應該能幫你查一查出貨記錄。",objectives={"和藏寶海灣的碼頭管理員羅茲基爾談話。"}]])
R(1181,"地精贊助商",[[description="恐怕我也只能幫你這些了，$n。如果你還想瞭解更多事情的話，就直接去找大財主里維加茲本人吧。還有誰能比里維加茲對他自己的生意更瞭解呢？$b$b你到港口那邊的小酒館頂樓的房間裡就能找到他了。",objectives={"與藏寶海灣的大財主里維加茲談話。"}]])
R(1182,"地精贊助商",[[description="瞧，納菲瑞提湖(北荊棘谷)那邊的地精風險投資公司的伐木機上都裝備了最新型號的燃料調節器。我覺得，普茲克要是能拿到調節器的詳細設計圖，一定可以善加利用它。不幸的是，那邊的工頭比我預計的要精明得多。$b$b不過你看起來應該有能力去拿到那張設計圖。據我所知，他把那些東西都鎖在了屋子裡。",objectives={"將燃料調節器的藍圖交給藏寶海灣的大財主里維加茲。"}]])
R(1183,"地精贊助商",[[description="你現在就趕快出發吧。替我向普茲克問好，順便告訴他，如果他需要什麼東西，就儘管跟我說。我期待著他能馬上打破記錄！",objectives={"把燃料調節器的藍圖帶給閃光平原的普茲克。"}]])
R(1184,"蟲群的消息",[[description="Head back to Belgrom in Orgrimmar and tell him Moktar be doing his bidding well out in the Thousand Needles. Tell him also, that me studies progress, and I hope to be havin' learned more soon. That should please him greatly.",objectives={"Return to Belgrom Rockmaul in Orgrimmar."}]])
R(1185,"殼中的東西…")
R(1186,"第十八個駕駛員",[[description="我要開始著手將這個新的燃油調節器裝到賽車上去了，如果你想要幫助車隊的話，就去和拉澤瑞克談談吧。他是我們的駕駛員——更確切地說，是第18個駕駛員——他想為這些賽車做一個小小的修改。$b$b他經常有些奇思妙想，所以請不要太吃驚了。",objectives={"和閃光平原的拉澤瑞克談話。"}]])
R(1187,"拉澤瑞克的調整",[[description="我知道，普茲克是個偉大的機械師，但是他不敢加大油門趕超別人。但我不像他那麼膽小。$b$b在普茲克賽車的設計完成後，我花了點時間做了一些小小的修改。把控制器鬆一鬆，改造某些結構，增加更多的潤滑劑，諸如此類。$b$b我從加基森的史瑞夫那裡訂了一個爆鹽增壓器，但是那運貨的飛艇卻一頭栽進了塵泥沼澤！$n，幫我去把東西取回來吧！",objectives={"為閃光平原的拉澤瑞克取回爆鹽增壓器。"}]])
R(1188,"安全第壹",[[description="But wait, what's this? Shreev left the safety on. That will limit the amount of power I can draw from the booster at any time. I told him I wanted it off! This is no good.$b$bYou have to take this to the Gadgetzan Gizmorium in the Tanaris Desert and have Shreev remove this.",objectives={"Bring the Seaforium Booster to Shreev in Gadgetzan."}]])
R(1189,"安全第壹",[[description="There, I did what Razzeric wanted. Just tell him to be careful when he sets this off. If he makes the slightest mistake, he won't be moving forward, he'll just be a burnt spot on the track.$b$bWould be a shame, too, if that happened. Who knows if our nineteenth driver would be any good?",objectives={"Return the Modified Seaforium Booster to Razzeric on the Shimmering Flats."}]])
R(1190,"跟上節奏",[[description="The Brassbolts brothers have discovered a new building material, that's the only explanation that makes sense. Their cars have been operating faster than before, but their designs, and all the other data we've gathered from their runs is identical.$b$bWhat we do know, is that Rizzle Brassbolts has been focused on the plans for this new discovery almost constantly.$b$bZamek can create a diversion for you, so that you can steal those plans from them.",objectives={"Have Zamek create a diversion, then steal Rizzle's plans for Pozzik on the Shimmering Flats."}]])
R(1191,"紮米克的困擾")
R(1192,"精鐵礦石")
R(1193,"破碎的陷阱")
R(1194,"瑞茲爾的圖表",[[description="Rizzle's schematics describe the process of the refinement of indurium ore. From his scrawls, it is apparent that indurium ore is being obtained from the dwarven excavation site of Uldaman in the Badlands.$b$bMuch of the other notes relate to the heat resistant properties.$b$bUsed as a paperweight for the plans is a hunk of what appears to be unrefined indurium ore.",objectives={"Bring the Sample of Indurium Ore to Pozzik on the Shimmering Flats."}]])
R(1195,"神聖之火",[[description="The Galak centaur in the Thousand Needles are protecting an artifact from the time of the centaurs' creation.$b$bWe would like to retrieve it, but we require a phial of water from one of the night elves' moonwells.$b$bTo collect the water, you will first need to obtain one of the phials carried by the dryads near the Raynewood Retreat in the heart of Ashenvale Forest. There is a moonwell near the western bank of the Falfarren River, south of the main road, where you can fill the phial.",objectives={"Return a Filled Etched Phial to Zangen Stonehoof in Thunder Bluff."}]])
R(1196,"神聖之火",[[description="把這裝滿水的蝕刻瓶給亂風崗的勞恩·峭壁行者帶去吧。你可以搭乘貧瘠之地南部邊境的升降梯去千針石林。",objectives={"把裝滿水的蝕刻瓶交給亂風崗的勞恩·峭壁行者。"}]])
R(1197,"神聖之火",[[description="Using the water you brought, you will be able to temporarily douse the flame that holds the centaur relic. It will not work permanently, however, so you will have to be quick about it.$b$bYou will find Splithoof Crag, the centaurs' stronghold, to the north of here. The flame is kept in Splithoof Hold, a heavily guarded part of the crag.$b$bBe careful, though, the Galak centaur have great numbers here, and will be rather reluctant to surrender something so dear to them.",objectives={"Retrieve the Cloven Hoof for Rau Cliffrunner at the Freewind Post."}]])
R(1198,"尋找塞爾瑞德",[[description="Many rumors circulate these days about the union of the Twilight's Hammer and the naga in Blackfathom Deeps on the coasts of Ashenvale.$b$bMy role here with the Argent Dawn is to collect as much information as I can, so we know when and where help is needed.$b$bIt has been weeks now since I sent a scout to check on the activity at Blackfathom Deeps. Argent Guard Thaelrid has not yet reported back.$b$bMy other scouts are preoccupied with pressing matters.$b$bSeek out and aid Thaelrid for me, $n.",objectives={"Seek out Argent Guard Thaelrid in Blackfathom Deeps."}]])
R(1199,"暮光之錘的末日",[[description="Empowered by the ancient rites of the chaotic Old Gods the members of the Twilight's Hammer strive to bring about the return of their dark patrons and spread death and terror across the world.$b$bWe believe that the Twilight's Hammer has allied with the naga and are amassing in Blackfathom Deeps on the coast of Ashenvale.$b$bWhatever evil plan brews in the depths of the old temple must be thwarted.$b$bWage war on the Hammer and bring back proof of your deeds. Your efforts will be rewarded handsomely.",objectives={"Bring 10 Twilight Pendants to Argent Guard Manados in Darnassus."}]])
R(1200,"黑暗深淵中的惡魔",[[description="Strength has left me. Your help is needed!$b$bLong ago this site was a great temple of Elune. But misfortune led to ruin when the corruption of an Old God seeped up from beneath the earth and tainted the sacred Moon Well.$b$bAku'Mai, servant of the Old God, rose from the waters.$b$bThe Twilight's Hammer cultists have allied with the naga to occupy these grounds. The cultists, led by Kelris, sacrifice innocents to Aku'Mai for power.$b$bSlay Kelris and bring his head to Selgorm in Darnassus, $N, please.",objectives={"Bring the head of Twilight Lord Kelris to Dawnwatcher Selgorm in Darnassus."}]])
R(1201,"塞拉摩間諜",[[description="部落和聯盟正處於某種令人不安的休戰期。兩大陣營之間的小規模的衝突和暗殺活動時有發生，而我們的職責就是確保部落始終佔據上風！$B$B現在正是行動的時候。$B$B聯盟派了一些間諜駐紮在蕨牆村的東部，他們監視著村子，把我們的動向報給告塞拉摩，決不能讓他們繼續下去。$B$B去追蹤那些間諜，把他們幹掉。讓他們的頭兒知道我們決不會允許他們的間諜在我們面前晃來晃去！",objectives={"殺掉9個塞拉摩間諜，然後回到蕨牆村去見納澤爾·血矛。"}]])
R(1202,"塞拉摩碼頭",[[description="$N, two of our spies were sent to steal documents from a ship at the Theramore docks.  They gained the papers but were discovered, and were forced to throw the documents into the sea.$B$BOne spy later escaped, but was unable to recover the prize.  He reported his failure to me, and I now charge the task to you.$B$BThe documents are in a footlocker, in the waters somewhere beneath the Theramore docks.  Find those documents, $N, and bring them to me.",objectives={"Bring the Captain's Documents to Nazeer Bloodpike in Brackenwall Village."}]])
R(1203,"加爾的劍",[[description="我要切點東西，呃……我不能告訴你我要切什麼，不過……反正我需要把劍。一種真正的劍……$B$B有人叫它月光鋸劍。我叫它快劍。$B$B你能幫我嗎？也許鎮上就有賣，或者你也可以去找個鐵匠特別打造一把。$B$B不過，不要等到明天再去找。我要切的東西可不能放太久……",objectives={"給塵泥沼澤的加爾帶把月光劍。"}]])
R(1204,"泥石龜蟹湯",[[description="我正在研究一道叫作「泥石龜蟹湯」的菜，現在我還需要一些原料……唉，我覺得我真是不適合在塵泥沼澤裡長途跋涉！$B$B那麼，$N，你能幫我去打獵嗎？首先，我需要泥石龜的舌頭，這些海龜經常在海岸附近出沒。$B$B不過我要的還不是一般的舌頭！聽說有些泥石龜的舌頭是分叉的……$B$B他們說那樣的舌頭吃起來味道特別好，而且我也很喜歡給我的菜裡加點特別的風味……",objectives={"給塞拉摩的摩根·斯特恩收集8個分叉的泥石龜舌。"}]])
R(1205,"死沼巨鱷",[[description="Deadmire is an ancient crocolisk in Dustwallow marsh.  And it is his time to die.$B$BOld bones grind as he pulls his huge body through the swamp, and although he still moves with the strength and speed of youth, his aging body tortures the great spirit within it, a spirit whose flame will not waver.$B$BYet now he lives in constant, maddening pain.  You must end the life of this noble creature, $N.  You must lead Deadmire to peace.",objectives={"Bring Deadmire's Tooth to Melor in Thunder Bluff."}]])
R(1206,"加爾和蜘蛛眼",[[description="眼睛汁是種很好喝的飲料，可惜很多生物都只有兩隻眼睛。$B$B不過蜘蛛有很多眼睛，很多很多。其中特別好喝的是暗霧蛛眼汁，鹹鹹的很順口！……$B$B暗霧蜘蛛就在西邊的暗霧洞穴裡活動。你說這些蜘蛛的名字是來自這個洞的名字呢，還是有什麼別的說法？",objectives={"收集40顆完好的暗霧蜘蛛的眼睛，把它們交給水光莊園的「沼澤之眼」加爾。"}]])
R(1218,"舒心草",[[description="我喜歡燒菜，沼澤地裡特產的美食，比如油炸綠青蛙腿之類的。$B$B不過要燒菜，我得要有足夠的舒心草調味料，然後我就可以做出一鍋燉肉，好好地飽餐一頓，還能剩一些給你。$B$B你喜歡燉肉嗎？",objectives={"帶三份舒心草調味料給塵泥沼澤的「沼澤之眼」加爾。"}]])
R(1219,"獸人的報告",[[description="撥開鬆軟的泥土，你看到一隻斷掉的獸人的手，手裡抓著一根用骨頭製成的管子，裡面塞著一張粘滿泥土的羊皮紙。$B$B羊皮紙上的文字都是獸人的文字……這看起來很重要。",objectives={"把間諜的報告交給塞拉摩的某個上尉。"}]])
R(1220,"維米斯隊長",[[description="Captain Vimes should see the orc report you found, $N.  He knows the orcish language better than most.  And he should know that there are Horde spies near Theramore!$B$BThe captain is in the barracks, on the northeastern side of Theramore Isle.",objectives={"Bring the Spy's Report to Captain Garran Vimes."}]])
R(1221,"藍葉薯",[[description="Blueleaf tubers are a delicacy around the world!  But they're rare, very rare.  The only place to find them is here in the Barrens, deep in the earth, in Razorfen Kraul.$B$BAnd even then, they're impossible to find unless you know just where to look!  That's why I've trained these snufflenose gophers to find them for me.  They have great noses and can smell a tuber from fifty paces away.$B$BIt won't be easy, but if you get me some tubers I'll pay you handsomely.",objectives={"Grab a Crate with Holes.$BGrab a Snufflenose Command Stick.$BGrab and read the Snufflenose Owner's Manual.$B$BIn Razorfen Kraul, use the Crate with Holes to summon a Snufflenose Gopher, and use the Command Stick on the gopher to make it search for Tubers.$B$BBring 6 Blueleaf Tubers, the Snufflenose Command Stick and the Crate with Holes to Mebok Mizzyrix in Ratchet."}]])
R(1222,"伊格納茲的逃亡",[[description="太好了，總算碰到一個不想吃我的人了！$B$B我正愁沒人來幫我對付這兒的怪物哪，$g兄弟:小姐;，你看來挺合適的。$B$B那個叫摩根·斯特恩的廚子正在研究一套新食譜，他要我來這兒採集一點睡菜葉，那傢伙可能覺得睡菜葉挺好吃的吧！$B$B總之，就在我找睡菜的時候……我發現我被包圍了！你能幫我從這兒逃出去順便在我找睡菜的時候替我斷後嗎？",objectives={"護送伊格納茲，然後和塞拉摩的摩根·斯特恩談話。"}]])
R(1238,"遺失的報告",[[description="Sifting through the loose dirt, the severed hand of an orc is found.  And clutched in the hand is a bone-carved tube.  And in the tube is a dirt-stained parchment.$B$BThe parchment is a report made by an orc who spent weeks spying on the city of Theramore.$B$BAfter scanning the parchment, it is clear that it must be brought to the orc spymaster in Brackenwall Village.",objectives={"Bring the Spy's Report to Nazeer Bloodpike in Brackenwall Village."}]])
R(1239,"被斬下的頭顱",[[description="Vigorous digging reveals the head of a male orc, raggedly severed at the neck.  His lips are frozen in a snarl, and its dark eyes stare defiantly.",objectives={"Bring the Defiant Orc Head to Nazeer Bloodpike in Brackenwall Village."}]])
R(1240,"巨魔巫醫",[[description="We must know the events surrounding Marg's death!  And the only way to do that, $N, is through the witch-magic of trolls.$B$BBring Marg's head to Kin'weelay in Stranglethorn Vale, at the Grom'gol Base Camp.$B$BKin'weelay is the most powerful witchdoctor of the Darkspear trolls.  If anyone can speak to Marg Nighteye's spirit, it is he.",objectives={"Take the Defiant Orc Head to Kin'weelay in the Grom'gol Base Camp in Stranglethorn Vale."}]])
R(1241,"失蹤的使節",[[description="Recently a diplomat was sent to Theramore to meet with Jaina Proudmoore. That diplomat never arrived.$B$BI believe the Defias are involved in this plot, but I'm not sure how. The diplomat's disappearance still eludes public attention, but it can't remain that way for long.$B$BAgents of the king are already scouring the city for clues, but I have my own contacts I would like involved.$B$BIn the Valley of Heroes is an old friend of mine named Jorgen. Find him, give him this note, and follow his instructions.",objectives={"Find Jorgen in Stormwind City."}]])
R(1242,"失蹤的使節",[[description="Take this here note to Elling Trias. Don't say nothin' else to him. Just be polite and wait for him to respond. And don't worry, he will.$B$BI'm gonna only impress this on ya once more, $N: treat this matter seriously, and keep your yapper shut.$B$BYa can find Trias at his cheese shop, Trias' Cheese, in the Trade District. Good luck.",objectives={"Delivery Jorgen's Sealed Note to Elling Trias in Stormwind City."}]])
R(1243,"失蹤的使節",[[description="Jorgen, you ol' sonuva.... So, that's how it's going to be, huh?$B$BAll right, I can deal with that. I hope he finds the Twisting Nether that much sooner!$B$BHere's what's gonna happen, $N. I'll start using my contacts here, but you're doing most of the footwork so I save some coin.$B$BHead to Darkshire in Duskwood and find Watcher Backus--he usually patrols the north road right outside of town. Just tell him you're looking into any Defias activity for me and he'll help you out with any information he can.",objectives={"Give the Sealed Note to Watcher Backus in Duskwood."}]])
R(1244,"失蹤的使節",[[description="迪菲亞兄弟會的活動？好吧，他們總是不斷在活動。就算他們按兵不動，我們也仍然視之為威脅。$B$B但現在我認為，最近事情變得有點奇怪。大概是在兩三週前吧，他們的許多密探都在腐草農場附近頻繁出沒。由此看來那裡一定是發生了什麼重要的事情。$B$B你為什麼不先去那裡調查一下，並把你調查到的結果拿給我看看？$B$B那座農場就在由西部荒野進入暮色森林的大路南邊。",objectives={"找到迪菲亞記事本，把它帶回來給暮色森林的守夜人巴庫斯。"}]])
R(1245,"失蹤的使節",[[description="哎呀，如果這只是個用來干擾你的視線的幌子，那他們也未免搞得太複雜了，我也不太清楚這東西到底是什麼。把它交給提亞斯吧——他一定能弄明白其中的意義。千萬小心，別讓任何人把它搶走。我們都知道，這事可比我的命還重要，甚至比他的命還要重要。$B$B最後，拜託你一件事，$N，別對任何人說起我幫助過你。我的上司如果知道我對這件事有所瞭解而又沒有向他們彙報的話，沒准會絞死我的。",objectives={"將迪菲亞記事本帶給暴風城的伊林·提亞斯。"}]])
R(1246,"失蹤的使節",[[description="對了，就是他，現在我想起來了…達舍爾…達舍爾…什麼來著……他的名字是什麼來著？拳！達舍爾·石拳。圈內人都叫他拳—或許是因為他喜歡製造事端的緣故吧。$B$B你通常可以在舊城區裡見到他—在舊城區中心練拳。去和他談一談，如果有必要的話，你不妨威脅威脅他，甚至用點暴力手段，有時得那樣才能讓他說點真話出來。別猶豫！要是真像這份東西上所寫的那樣，他應該已經深陷其中，不會那麼輕易就告訴你什麼有用的資訊。",objectives={"與暴風城舊城區裡的達舍爾·石拳談話。"}]])
R(1247,"失蹤的使節",[[description="原來如此……唔……我對腐草農場那邊的會議略知一二，我記得是幾週前組織的，但我沒有去參加那個會議。我只參加了A計畫的那部分，但A計畫失敗了……那些該死的冒險者。$B$B我們的線人說，那個執行B計畫的小子來自米奈希爾，他的外號叫乾柴。對於他們的後備計畫我就知道這麼多了。",objectives={"與暴風城的伊林·提亞斯談話。"}]])
R(1248,"失蹤的使節",[[description="我有一個隱居在米奈希爾港的線人。他已經退休了，不過如果你告訴他你是為我工作的話，他應該會很願意幫助你的。他名叫米克哈爾，在幾年前離開暴風城的時候，他提到過自己要去旅店工作。$B$B和他談談，想辦法找到這個乾柴，再打聽一下有沒有關於使節被綁架的消息。我們現在得弄清楚他被帶到了什麼地方去，或者至少弄清楚他是誰。這份摘要裡沒有提到綁架行動完成以後的事。",objectives={"與濕地的米克哈爾談話。"}]])
R(1249,"失蹤的使節",[[description="你說是伊林派你來的？好吧，現在我要拿出十倍的熱情來招待你。想要什麼儘管說，我會竭盡全力來幫助你的。$B$B嗯，你說乾柴？似乎是沒聽說過的名字，但我一定會注意他的。$B$B別抬頭看，$N，出口旁邊的那傢伙正往我們這邊看呢。這傢伙似乎有點太專心地聽我們的對話了，你明白我的意思嗎？如果我是你，我就會趁他溜走之前好好教訓教訓他。",objectives={"在塔伯克·賈恩逃跑前制服他，然後回米奈希爾港旅店去找米克哈爾。"}]])
R(1250,"失蹤的使節",[[description="迪菲亞兄弟會出的價錢還沒高到讓我把我的命也給賠上。他們抓走了國王。對，沒錯，正是暴風城的國王，他可不是什麼簡單的外交使節。他當時正在前往塞拉摩與珍娜·普勞德摩爾會面的路上—這顯然是件大事，當然也是個大秘密。但這裡面可不是只有迪菲亞兄弟會牽扯進來，他們也是為別人效力的。我想只有他們自己知道誰是他們的雇主。$B$B我的份內事就是趁國王的船還在港口裡的時候，和他們在船上的內應碰頭，那傢伙叫亨德爾。我就知道這麼多了，我發誓！",objectives={"與濕地的米克哈爾談話。"}]])
R(1251,"黑色盾牌",[[description="An iron shield, blackened by the fire that raged through the inn, is affixed to the crumbling chimney, one of the few remaining parts of the structure that once made up the Shady Rest Inn.$b$bThe shield can be removed from the brick of the chimney.",objectives={"Bring the Blackened Iron Shield to Krog in Brackenwall Village."}]])
R(1252,"帕瓦爾·雷瑟上尉",[[description="地上閃過的一道光芒把你的視線引到碎石的下方。你撥開了碎石，發現灰塵下有一枚白色的徽章，表面上印有金色的船錨，那是塞拉摩的標記。$b$b錨的下方刻著「帕瓦爾·雷瑟上尉」的字樣。",objectives={"把雷瑟的徽章拿給塞拉摩的蓋蘭·維米斯隊長。"}]])
R(1253,"黑色盾牌",[[description="有一面被大火燻黑的鐵盾牌和倒塌的煙囪連在一起，這根煙囪是樹蔭旅店燒毀之後留下的殘磚斷瓦中的一部份。$b$b這面鐵盾可以從煙囪的磚上拿下來。",objectives={"把被燻黑的鐵盾交給塞拉摩的蓋蘭·維米斯隊長。"}]])
R(1258,"還有螃蟹！",[[description="我的新食譜裡還需要一種大螃蟹帶殼的腳，不過塵泥沼澤這兒的汙殼螃蟹可不行！恐怕唯一合適的螃蟹離這兒很遠，在悲傷沼澤裡。$B$B螃蟹腳的殼是構成這道菜外觀的一大要素，所以我必須要新鮮而且沒有任何疤痕的蟹腳。一隻成熟螃蟹大概只有一隻或兩隻這樣的腳，而我需要大量的螃蟹腳來研究我的食譜。B$B那麼，$N……你願意跑一趟嗎？",objectives={"收集12隻新鮮的螃蟹腳給塞拉摩的摩根·斯特恩。"}]])
R(1259,"帕瓦爾·雷瑟上尉",[[description="我不認識這個帕瓦爾·雷瑟上尉，你最好還是去問問泰索蘭副官。他負責管理塞拉摩所有守衛的資料，從個人資料到他們的裝備。$b$b他可以查查這些資料，然後告訴你這個雷瑟到底是誰。",objectives={"從塞拉摩的泰索蘭副官那兒找出更多關於雷瑟的消息。"}]])
R(1260,"摩根·斯特恩",[[description="我正在為餐館開發新的菜單，這份新菜單裡都是本地特產的菜色，以「海灣」為主題。我想，藍色隱士旅店的客人一定會很喜歡這個的！$B$B我讓我侄子摩根到塞拉摩去收集當地的食譜了，那地方就在塵泥沼澤的邊界地帶。我得知道他到目前為止找到了那些東西。$B$B去塞拉摩的路很長，起碼對我來說是太長了。不過我打賭像你這樣一個年輕的$c對這種長途旅行一定會欣然前往的，對吧？",objectives={"和塞拉摩的摩根·斯特恩談話。"}]])
R(1261,"瑪爾格的囑托",[[description="Cursed muckshell!  You can't kill Marg!  Ah, but I am dead.  So it must have slain me...$B$BBut my mission!  My mission!  You, $N, must complete it.$B$BWhile near Theramore, I spied a group of Alliance soldiers camped on the beach.  And one soldier wore a pendant... a pendant laden with more gems than any soldier could afford!$B$BThat night I snuck into their camp and stole the pendant, but on my return to base a muckshell crab-man killed me!$B$B$N, you must find that muckshell and recover the pendant!",objectives={"Bring the Jeweled Pendant to Nazeer in Brackenwall Village."}]])
R(1262,"向佐爾報告",[[description="It is strange that the pendant Marg stole was in the hands of common soldiers.  Perhaps its owner was in disguise, or perhaps the soldiers themselves stole it!$B$BRegardless of which is true, this is a noble's pendant and we must discover its true owner if we are to unravel its mystery.$B$BTake the pendant to Zor Lonetree in Orgrimmar.  He is well schooled in Alliance politics, and will know if this pendant has a history among the nobles of Stormwind.",objectives={"Bring the Jeweled Pendant to Zor Lonetree in Orgrimmar."}]])
R(1263,"The Burning Inn <CHANGE TO GOSSIP>")
R(1264,"失蹤的使節",[[description="每個月初，庫爾提拉斯的水兵們都會領取薪水，然後離開塞拉摩到別的地方去遊玩。大部分人會到這裡來找女人，喝酒，尋歡作樂一番。他們當中有一些人整天都會泡在酒館裡，我敢肯定亨德爾也是其中之一。$B$B只要那傢伙現在還留在塞拉摩的話，那麼當地的指揮官薩莫爾就能幫你找到他。雖然他只對普勞德摩爾家族效忠，但如果你說出伊林的名字，他也會幫助你的……應該會的。",objectives={"找到塵泥沼澤的指揮官薩莫爾。"}]])
R(1265,"失蹤的使節",[[description="亨德爾？是的，我知道這個人。不過你找我的士兵有什麼事呢？$B$B伊林派你來找他？嗯，好吧，我不喜歡這種感覺。如果你的事情不麻煩，伊林是不會讓你先來找我的。我理解你可能沒辦法告訴我詳情，但請明白這一點：我有責任保護好這片土地。如果你是來製造麻煩的話，最好先讓我知道你想幹嘛。$B$B我相信，亨德爾就駐守在塞拉摩外的第一座哨塔上。自己小心點！",objectives={"在警戒崗哨中搜索亨德爾下士的消息。"}]])
R(1266,"失蹤的使節",[[description="亨德爾下士就在這裡的西邊，他現在正在執行保護那些輪休的塞拉摩密探們的任務。密探們正在那邊監視著部落的前哨基地—蕨牆村，當然也時刻留心著其他任何有可能威脅到我們的東西。$B$B你應該很容易就能找到他，沿著道路搜索每一個帳篷就行了。$B$B我現在還有另一件事要處理，但我應該很快就可以趕上你，如果你有任何問題，你都可以在普勞德摩爾女士所在的塔裡找到我。",objectives={"找到塵泥沼澤中的亨德爾下士。"}]])
R(1267,"失蹤的使節",[[objectives={"與塵泥沼澤的珍娜·普勞德摩爾談話。"}]])
R(1268,"可疑的蹄印",[[description="Rows of hoofprints lead away from the still-smoking skeleton of the Shady Rest Inn. There are at least a few visible impressions, with more rows of prints almost imperceptible in the soft mud of the marsh.",objectives={"Report about the suspicious prints at the Shady Rest Inn to Krog in Brackenwall Village."}]])
R(1269,"帕瓦爾·雷瑟上尉",[[description="A glint of light on the ground catches your eye from underneath the rubble. Brushing debris and ash caked onto the object reveals the insignia of a gold anchor on white, enameled on the surface: the sign of Theramore.$b$bUnderneath the anchor is embossed the name \"Lieutenant Paval Reethe\".",objectives={"Bring Reethe's Badge to Krog in Brackenwall Village."}]])
R(1270,"伊格納茲的逃亡",[[description="Great, finally something that doesn't want to eat me!!$B$BI need help handling the critters around here, and you fit the mold, $gbuddy:lady;.$B$BA goblin from Ratchet named Mebok Mizzyrix needs some bogbean leaves for a potion, or something... I honestly don't care why -- his money was good and I know this swamp, so here I am.$B$BToo bad I got myself surrounded before I found the bogbean!  Can you help me out of here, and watch my back as I look for Mebok's plant?",objectives={"Escort \"Stinky\" Ignatz, then speak with Mebok Mizzyrix in Ratchet."}]])
R(1271,"盛筵")
R(1273,"盤問雷瑟",[[description="It took a long time, but I found Reethe. He hide good for a human.$b$bOgron worried that he might be crazy after so much time in swamp. You come with me for we go get answers from him.",objectives={"Go with Ogron to speak with Reethe, then return to Krog in Brackenwall Village."}]])
R(1274,"失蹤的使節",[[description="Excuse me, $g sir : madam;. Bishop DeLavey asked me to approach adventurers that might be able to help him with a delicate matter.$B$BIf you could quietly head to Stormwind Keep and speak to him at your earliest convenience, I'm sure he would appreciate your help. Again, please be discreet. It is a matter of some importance.",objectives={"Find Bishop DeLavey in Stormwind Keep."}]])
R(1275,"研究墮落",[[description="愚蠢的血精靈們已經徹底陷入了對魔法的狂熱之中了，難道他們沒有見到卡林多大陸上的薩特與納迦們身上發生了些什麼嗎？$b$b我總覺得血精靈們也將會踏上這樣一條不歸之路，但是艾澤拉斯已經無法再承受多一種被魔法扭曲了心智的怪物了。$b$b我希望能夠研究一下薩特和納迦的腦幹組織，這樣也許就能瞭解那些精靈們的命運將會走向何方。在梣谷海岸邊的黑暗深淵中有許多薩特和納迦，你去那裡找一找吧。$b$b這將會是一段漫長的旅程，一路小心，$n。",objectives={"奧伯丁的戈沙拉·夜語需要8塊墮落者的腦幹。"}]])
R(1276,"黑色盾牌",[[description="Ah, I remember now! Mosarn is a well-respected blacksmith in Thunder Bluff. I knew I had heard his name somewhere, before.$b$bIn thanks, the Earthen Ring awarded me with a set of armor crafted by Mosarn. Very good work.$b$bPerhaps he can tell you more about the shield he crafted.$b$bIt's not much of a lead, but since we didn't get anything useful out of Reethe, it's all we have.",objectives={"Show the Blackened Iron Shield to Mosarn in Thunder Bluff."}]])
R(1277,"<nyi> <TXT> The Centaur Hoofprints",[[description="Kagoro has revealed that the centaur hoofprints belong to some chumps in Mauradon.",objectives={"Beat down."}]])
R(1278,"<nyi> <TXT> The Grim Totem Clan")
R(1279,"<nyi> <TXT>The Centaur Hoofprints",[[description="Finish one of the three."]])
R(1280,"<nyi> <TXT>The Centaur Hoofprints")
R(1281,"Jim's Song <CHANGE TO GOSSIP>")
R(1282,"微笑的吉姆",[[description="我對吉姆的事很遺憾……他以前不是那樣的。他曾在沼澤地開了個旅店，那是個很不錯的地方。$b$b我真不想談這個。你想談的話就去找維米斯隊長吧。",objectives={"與塞拉摩的蓋蘭·維米斯隊長談話。"}]])
R(1283,"Fire at the Shady Rest <CHANGE TO GOSSIP>")
R(1284,"可疑的蹄印",[[description="幾排蹄印從樹蔭旅店那仍然冒著煙的廢墟中延伸出來。大部分蹄印都埋在沼澤地的鬆軟泥土裡而沒法辨認，不過至少有一小部分是可以分辨出來的。",objectives={"把樹蔭旅店的可疑蹄印報告給塞拉摩的蓋蘭·維米斯隊長。"}]])
R(1285,"戴林的下屬",[[description="雷東……雷德帕斯……啊，找到了！帕瓦爾·雷瑟上尉。$b$b他和大部分跟隨普勞德摩爾女士橫渡大海的徵募兵一起加入了塞拉摩守衛軍。16歲時加入庫爾提拉斯海軍，戰績出色，屢獲提升……$b$b已列入失蹤名單。",objectives={"把雷瑟的資料報告給塞拉摩的蓋蘭·維米斯隊長。"}]])
R(1286,"背叛者",[[description="在沼澤地裡立足確實是非常艱難的，但是通過不懈的努力，最後我們終於在這一帶守住了幾座防守哨塔。$b$b我收到的最新消息和偵察報告說一群背叛者佔據了我們在在旅店的西南方的一座廢棄哨塔。$b$b這群背叛者的首領叫加科因，去看看能不能從他身上找到什麼消息。$b$b小心點，$n。他可是個難對付的傢伙。",objectives={"從巴魯斯·加科因及塵泥沼澤的背叛者那裡打探消息。"}]])
R(1287,"背叛者",[[description="雷瑟？那個懦夫？$b$b我們把他趕出營地了，因為他堅持要去劫掠蕨牆村巨魔的補給物資。我們人數不夠，沒辦法跟那群沒有腦筋的畜生鬥。$b$b他不止一次做出過分的事，所以我們只好讓他自生自滅。$b$b現在，我幫了你的忙……那麼，你是不是也幫幫我們，忘記你曾經不小心碰到我們？",objectives={"和塞拉摩的蓋蘭·維米斯隊長談談關於雷瑟的事。"}]])
R(1288,"Vimes's Report",[[description="You've done some good work, $n, best I've seen from an amateur.$b$bLady Proudmoore asked that I keep her apprised of this delicate situation, and I haven't spoken to her for some time now.$b$bI was going to deliver my report to her later, but it seems more fitting that you should be the one to speak with her about it. You can probably answer her questions better than I could.",objectives={"Bring Vimes's Report to Lady Jaina Proudmoore in Theramore."}]])
R(1289,"Vimes's Report",[[description="Well. judging from Captain Vimes's report. you've been a huge help to his investigation. and for that I thank you.$B$BI can put my mind more at ease knowing that the matter is in such capable hands. If you would. I would request that you return to Captain Vimes and help him in getting to the bottom of this mystery.",objectives={"Return to Captain Garran Vimes in Theramore."}]])
R(1293,"<nyi> <TXT> Centaur Hoofprints")
R(1294,"<nyi> <TXT>Centaur Sympathies")
R(1295,"<nyi> <TXT> Course of Action")
R(1296,"<nyi> <TXT> Course of Action")
R(1297,"<nyi> <TXT> Course of Action")
R(1299,"<nyi> <TXT> Thrall's Dirty Work")
R(1300,"<nyi> <TXT> Lorn Grim Totem")
R(1301,"詹姆斯·海厄爾",[[description="在藍色隱士旅店工作之前，我曾在一個頂尖的廚師兼旅店老闆手下學藝，他的名字是詹姆士·海爾。我今天能有這樣的成就都得歸功於他。$b$b不知道他現在如何，他和他的兄弟文森到米奈希爾港的一家旅店去工作了，不過最近我一直沒聽到他的消息。$b$b你要是碰巧要到米奈希爾去的話，能不能幫我問候他一下？",objectives={"和米奈希爾港的文森·海爾談話。"}]])
R(1302,"詹姆斯·海厄爾",[[description="我的兄弟詹姆士跟隨珍娜女士到塞拉摩去了。我最後一次聽到他的消息是說他們在那兒打完了仗，詹姆士還在那裡的某個地方開了個旅店。不管他現在在哪兒，我想他的生意肯定很紅火，他是個很棒的廚師。$b$b啊，說起來我已經有一陣子沒聽到他的消息了——旅店的生意太忙了——不過塞拉摩的書記員應該可以幫你找到他。",objectives={"和塞拉摩的書記員倫德瑞談話。"}]])
R(1318,"戈多克食人魔的事務",[[description="Now you da king, so maybe you get prized Gordok artifact back from creepy elf who calls himself Prince!  Da king before you failed, just like all da other kings since Tortheldrin - da creepy elf - stole it from old timey Gordok king!$B$BArtifact is called da Gauntlet of Gordok Might.  Old timey stories say only da one true king da Gordok can get it back.  Old timey story also say creepy elf is still around here - you find it and it will become mighty gauntlet you wear forever!  Yar, I show you!",objectives={"Find the Gauntlet of Gordok Might and return it to Captain Kromcrush in Dire Maul.$B$BAccording to Kromcrush, the \"old timey story\" says that Tortheldrin - a \"creepy\" elf who called himself a prince - stole it from one of the Gordok kings."}]])
R(1319,"黑色盾牌",[[description="我很抱歉幫不了忙，$n，不過可以給你介紹個能幫忙的人。卡茲·雙鏈是我們最好的鐵匠，他就在鐵匠鋪給人打鐵器。$b$b把盾牌拿給他，看看他能告訴你什麼。",objectives={"把被燻黑的鐵盾牌拿給塞拉摩的卡茲·雙鏈看一看。"}]])
R(1320,"黑色盾牌",[[description="啊，我差點沒注意到這個……背面的皮帶一定是被燒掉了，不過看起來這條皮帶是給某個身材高大的傢伙用的。我猜是個牛頭人。$b$b我就只能告訴你這些了，告訴維米斯隊長，很抱歉我幫不上別的什麼忙了。",objectives={"與塞拉摩的蓋蘭·維米斯隊長談話。"}]])
R(1321,"黑色盾牌",[[description="Hmm... I don't see anything out of the ordinary with this shield. We should have Do'gol, the blacksmith, take a look at it, and see if he can tell us more about it, but I wouldn't hold out hope...",objectives={"Show the Blackened Iron Shield to Do'gol in Brackenwall Village."}]])
R(1322,"黑色盾牌",[[description="Hmmm, there's writing right here on the rim of the shield, but it's hard to read from all the burned stuff.$b$bI need acid to make it clear. Venom from the Darkfang spiders in the marsh would do good. Get me some of their sacs and I can clean this up.",objectives={"Acquire 6 Acidic Venom Sacs for Do'gol in Brackenwall Village."}]])
R(1323,"黑色盾牌",[[description="Oh, I think I might have dropped too much acid onto the shield. Let me just rub a little...$b$bHm, kind of hard to read, but it looks like the name Mosarn. Never heard of him. Maybe Krog knows. Krog knows many people.",objectives={"Talk with Krog in Brackenwall Village."}]])
R(1324,"失蹤的使節",[[description="什麼？！你到這裡來就是為了指控我和迪菲亞兄弟會有勾結？！我無法容許你這麼侮辱我！看來我非得好好教訓教訓你才行。",objectives={"擊敗塵泥沼澤的亨德爾下士。"}]])
R(1338,"卡爾·雷矛的訂單",[[description="有一個名叫弗倫·長鬚的矮人鑄甲匠，我很欣賞他做的東西，那手藝簡直是無人能敵。我需要一面新盾牌，而且一定要他親手做出來的盾牌！$B$B問題是……弗倫住在遙遠的南方，在暴風城的矮人區裡。他竟然住在人類的領地裡！我沒法想像他怎麼會住在離鐵爐堡這麼遠的地方，那幫人類一定出了足夠收買國王的大價錢把他給留在那兒！$B$B如果你正好要去那裡旅行一趟，又想順便掙點錢的話，能不能去弗倫那兒讓他給我做一面盾牌？",objectives={"把卡爾·雷矛的訂單交給暴風城的弗倫·長鬚。"}]])
R(1339,"巡山人卡爾·雷矛的任務",[[description="我聽說巡山人卡爾·雷矛正在找一個為他跑腿的人。一個可以為了他而去做趟小旅行的人。如何？你是適合的人選嗎？$B$B如果你願意的話，就去北邊的哨塔找他吧。",objectives={"和巡山人卡爾·雷矛談話。"}]])
R(1358,"給赫布瑞姆的樣本",[[description="A colleague in Kalimdor, Apothecary Helbrim, is researching the effects of Lordaeron toxins on the beasts of Kalimdor.  He would be very interested in a sample of the wolf hearts Renferrel sent me.$B$BHelbrim is stationed in the Barrens, in a village known as the Crossroads.  To reach him, you must travel via zeppelin to the orc capital of Orgrimmar, then travel south, by foot, to Durotar.  Head west into the Barrens, and you will soon reach the Crossroads.",objectives={"Bring the Wolf Heart Sample to Apothecary Helbrim in the Barrens."}]])
R(1359,"給金格的貨物",[[description="The wolf hearts you acquired possess a quality unseen in similar specimens.  There is a toxicity to them that should be deadly to the very wolves in which the hearts beat!$B$BIt's quite incredible, and we must study it further.  I kept a few samples of the hearts acquired.  Take them to my colleague, Apothecary Zinge.  You will find her in our headquarters in the Undercity.",objectives={"Bring the Wolf Heart Samples to Apothecary Zinge in the Undercity."}]])
R(1360,"失而復得",[[description="我本來有個不錯的工作，就是在荒蕪之地的奧達曼挖掘場幹活……直到那些該死的穴居人出現之後。我驚顯地逃了出來，而且還什麼也沒來得及拿。在一片慌亂之中，我弄丟了我最重要的財產。我那箱子很難撬開是沒錯，不過你知道嗎，那裡滿地都是穴居人！$B$B你去幫我拿回箱子來，我就好好謝你！那個寫著我名字的箱子就在北部大廳的盡頭，你得一路殺進去才行。",objectives={"到奧達曼的北部大廳去找到克羅姆·粗臂的箱子，從裡面拿出他的寶貴財產，然後回到鐵爐堡把東西交給他。"}]])
R(1361,"雷戈薩·死門",[[description="A warrior of the Horde, Regthar Deathgate, is recruiting agents for a mission into the land of Desolace.  Speak with him if you wish to volunteer.  He is stationed in the Barrens, in a series of bunkers west of the Crossroads.$B$BAnd sharpen your weapons.  Desolace is a place torn by war.",objectives={"Speak with Regthar Deathgate."}]])
R(1362,"淒涼之地的科卡爾部族",[[description="The Kolkar centaur live in Desolace, and their forces have spread into the Barrens.  This is a known fact and we have Horde agents dealing with them here.$B$BBut as long as the centaur are strong in Desolace, they will always pose a threat.  It is time we rid ourselves of that threat.$B$BSpeak with Felgur Twocuts at Ghost Walker Post in Desolace.  He was sent to gather intelligence on the centaur.  He will know how to best deal with the Kolkar of Desolace.",objectives={"Speak with Felgur Twocuts at Ghost Walker Post in Desolace."}]])
R(1363,"馬森的請求",[[description="作為魔法和科學學院圖書館的管理員，我的職責是保證所有的魔法書和卷軸隨時在庫。如果這些充滿魔法能量的文字落在邪惡的人手裡，天知道會發生多可怕的事情！$b$b啊，我突然想起來……我的助手迪利斯上禮拜犯下了一個可怕的錯誤。他在圖書館裡確實是個好幫手，但他一走出暴風城就幾乎寸步難行。你能幫我把老迪利斯給找回來嗎？",objectives={"與暴風城裡的助手迪利斯談話。"}]])
R(1364,"馬森的請求",[[description="馬森大人的指示再簡單不過了：將這篇重要的文章遞交給守望堡的看守者馬哈爾巴。$b$b但我從來沒有去過詛咒之地！這段路程太可怕了！$b$b我在悲傷沼澤那邊迷了路，被一大群像是植物一樣的沼澤生物給包圍了。它們在我身邊徘徊著，似乎是想要攻擊我，所以我就飛也似的逃了回來……結果我在慌亂中把文章給弄丟了。我敢肯定是有只怪物把它給撿跑了。$b$b你能幫我找回文章並把它送給馬哈爾巴嗎？",objectives={"奪回《卡德加的空間收斂研究筆記》，將它送給守望堡的看守者馬哈爾巴。"}]])
R(1365,"戴茲帕可汗",[[description="科卡爾並不是淒涼之地唯一的半人馬部族。許多半人馬部族都遊弋在這片乾燥的平原上，他們相互殘殺，紛爭不斷。他們的窩裡鬥對我們來說不是件壞事，因為半人馬強壯而且殘忍，如果這些半人馬聯合起來對付我們的話，那將是極其可怕的力量。$B$B在他們聯合起來之前，我們必須將他們各個擊破。$B$B你的第一個任務是讓科卡爾部族出現內亂，只要幹掉他們的首領戴茲帕可汗就可以了。$B$B科卡爾村就在東北方。去吧，祝你好運。",objectives={"把戴茲帕可汗的頭顱交給淒涼之地的費古爾·雙刃。"}]])
R(1366,"懸賞半人馬",[[description="既然你已經震懾了半人馬部族，那麼現在該是血洗他們的時候了。在淒涼之地獵殺半人馬吧，我不在乎你獵殺哪一個部族，只管收集半人馬耳朵就是了。$B$B減少他們的數量就等於削弱他們的野心，並打消他們不斷擴張的念頭。$B$B祝你狩獵愉快，$N。",objectives={"收集15個半人馬的耳朵，把它們交給淒涼之地的費古爾·雙刃。"}]])
R(1367,"瑪格拉姆部族",[[description="要擊敗半人馬，我們就必須利用牠們的仇恨天性來對付他們。我們先跟其中一支半人馬部族結盟，再透過牠們學習如何打敗其他的半人馬族。$B$B如果你選擇和瑪格拉姆族結盟，那麼就去殺掉他們的敵人—吉爾吉斯族。這會使你獲得瑪格拉姆族的尊重。當你得到足夠的尊重之後，就可以去見瑪格拉姆族的首領瓦魯格，他就在淒涼之地東南部的瑪格拉姆村外。",objectives={"和瑪格拉姆族建立良好的關係，然後和瓦魯格談話。"}]])
R(1368,"吉爾吉斯部族",[[description="要擊敗半人馬，我們就必須利用牠們的仇恨天性來對付牠們。我們先跟其中一支半人馬部族結盟，再透過他們學習如何打敗其他的半人馬族。$B$B如果你準備和吉爾吉斯族結盟，那麼就去攻擊他們最憎恨的對手—瑪格拉姆族。在你獲得了吉爾吉斯族的尊重以後，就可以去見他們的薩滿，智者烏泰克，他就住在淒涼之地西南的吉爾吉斯村外面。",objectives={"和吉爾吉斯族建立良好的關係，然後和智者烏泰克談話。"}]])
R(1369,"破碎之淚",[[description="The Gelkis think our centaur mother, Theradras, protects us.  They are stupid.  No one protects the centaur.  The Magram do not need protection!  We are the strongest!$B$BShow the Gelkis they are stupid.  Go to the cave in their village.  They hoard crystals in that cave, the tears of Theradras.  Destroy the tears and bring me the broken pieces!",objectives={"Maintain your reputation with the Magram, and bring 3 Broken Tears to Warug in the Magram Village."}]])
R(1370,"偷取物資",[[description="When we are not at war, we hunt for meat.  Meat gives us strength, and full bellies fight harder than empty ones.$B$BIt is the same with the Magram.  They store extra meat so they may fight longer between hunts.  If you raid their village to the east and take their stores of meat, then their strength will fail.",objectives={"Bring 6 bags of Crudely Dried Meat to Uthek the Wise in the Gelkis Village."}]])
R(1371,"瓦魯格的玩具",[[description="Long ago, a little gnome came to Desolace.  He had horses and a cart, and the cart held strange things.  Funny things.  Things that burned different colors.  Things that moved and weren't alive.  I killed the little gnome, but before that... he made me laugh.$B$BI kept my favorite thing from his cart.  It was a human made of wood and it waved at me until I hit it and broke it.$B$BI want a new one.  Get me a new one!",objectives={"Maintain your reputation with the Magram, and bring an Advanced Target Dummy to Warug in the Magram Village in Desolace."}]])
R(1372,"真言藥水",[[description="Our expeditionary force was sent at Varimathras's behest to survey lower Azeroth.$b$bWhile out scouting I noticed a human Infiltrator spying on Beggar's Haunt. Before I could apprehend him, some of our orcish... brethren... captured him and took him to Stonard, their stronghold in Swamp of Sorrows.$b$bI want to... help... our orcish allies. They did not see our camp here but nonetheless I want to lend a hand.$b$bWork with Faustin here to develop a... truth serum for our friend in Stonard.",objectives={"Speak with Apothecary Faustin at Beggar's Haunt."}]])
R(1373,"盎格庫爾",[[description="You have more to prove, and your next task will take you far, so for now the Gelkis will fight the Magram without you.$B$BThe earth whispers many secrets to those who listen.  One secret I hear is of a red crystal.  It is called draenethyst, and it is new to our earth.  It comes from a place where mountains fly, and where demons rule.$B$BBring me a shard of draenethyst, and it will make my magic strong!  The shard is in a place called the Swamp of Sorrows, held by the lost one Ongeku.",objectives={"Maintain your reputation with the Gelkis, and bring a Draenethyst Shard to Uthek the Wise in the Gelkis Village in Desolace."}]])
R(1374,"傑恩可汗",[[description="The earth speaks to me, and it says that the Magram grow weak.  Now it is time to kill their Khan!$B$BBring me the head of the Magram Khan, Jehn!",objectives={"Bring the Khan Jehn's Head to Uthek the Wise in the Gelkis Village in Desolace."}]])
R(1375,"沙卡可汗",[[description="You help the Magram, and I like you.  Now, kill the Khan of the Gelkis!  He is Khan Shaka, and I want his head!  I want to stare at his head and laugh at him!",objectives={"Maintain your reputation with the Magram, and bring the Head of Khan Shaka to Warug in the Magram Village in Desolace."}]])
R(1380,"赫魯薩可汗",[[description="$N, you helped us against the Magram.  Now, help us beat the Maraudine!  Kill the head of their clan, Khan Hratha!$B$BTo face him, blow the Maraudine War Horn.  It is atop a high bluff in the Valley of Spears.$B$BBut to blow the horn, you must gain a warhorn mouthpiece.  These are rare, carried only by trusted Maraudine centaur.$B$BAfter the horn is blown, centaur will come.  Kill them until Hratha appears.$B$BKhan Hratha holds the piece of... a key.  Bring it to me...",objectives={"Maintain your reputation with the Gelkis, and bring the Maraudine Key Fragment to Uthek the Wise in the Gelkis Village."}]])
R(1381,"赫魯薩可汗",[[description="The Gelkis Khan is dead, and now the Maraudine will fall!  Kill the Maraudine Khan, Hratha!$B$BTo face him, blow the horn on the high bluff in the Valley of Spears.  But to blow the horn, you need a mouthpiece.  To get a mouthpiece, kill Maraudine centaur.  Keep killing until you find a mouthpiece.  Then blow the horn.$B$BDo this and Maraudine centaur will come to the tower.  Kill them until Khan Hratha appears.  Hratha holds the piece of a key.  Give this piece to me...",objectives={"Maintain your Magram reputation, and bring the Maraudine Key Fragment to Warug in the Magram Village in Desolace."}]])
R(1382,"奇怪的聯盟",[[description="我們的確很幸運，半人馬氏族之間正在同室操戈。如果他們擰成一股繩，那將會是一股無法阻擋的力量。沒錯，我們很幸運，所以我們應該緊緊抓住現在的這種優勢。$B$B眾多半人馬部族中的一支——吉爾吉斯，正在與瑪格拉姆部族激烈地戰鬥。我希望在我們進攻瑪格拉姆的同時，吉爾吉斯部族也能同時發動攻擊。$B$B去和智者烏泰克談談吧，他就在淒涼之地西南的吉爾吉斯營地外面。也許我們可以通過他來和吉爾吉斯結成聯盟，同時對瑪格拉姆發起致命的攻擊！",objectives={"和吉爾吉斯部族建立良好的關係，然後和智者烏泰克談話。"}]])
R(1383,"真言藥水",[[description="I have just the right serum in mind. It will deal with the truth in precisely the way the truth should be dealt with.$b$bFor this concoction I will need several Shadow Panther hearts from the Swamp. I also require the enchanted fungus off of the Mire Lord who resides there. I am sure one as able as you, $n, can persuade him to part with some.$b$bNow the hard part will be locating a Deepstrider tumor from far-off Desolace. Very rarely the giants there become ill and a tumor forms.$b$bNow, off you go!",objectives={"Apothecary Faustin at Beggar's Haunt needs 5 Shadow Panther Hearts, Mire Lord Fungus and a Deep Strider Tumor."}]])
R(1384,"突襲科卡爾",[[description="The Kolkar centaurs think their magic is strong.  They do not know magic!  They would not know magic if it bit them!$B$BYou will show them their magic is weak.  Go to the Kolkar  to the northeast and kill them.  Take their charms.  Bring me the charms and I will throw them in the fire and laugh!",objectives={"Maintain your reputation with the Gelkis, and bring 10 Crude Charms to Uthek the Wise in the Gelkis Village in Desolace."}]])
R(1385,"野蠻外交",[[description="淒涼之地是一片殺戮場。半人馬部族之間互相殘殺，我們擔心最後的勝利者會不斷擴張領土，並最終威脅到我們的要塞。我們決不能允許這種情況出現。$B$B我們必須學會如何打敗半人馬部族，為了打敗他們……我們就必須和諸多半人馬部族中的一支結盟。瑪格拉姆部族與吉爾吉斯部族正在互相征伐，如果你去攻打吉爾吉斯部族，那麼瑪格拉姆部族就會視你為盟友。$B$B想辦法得到瑪格拉姆部族的信任，然後去和瓦魯格談談，他就在淒涼之地東南的瑪格拉姆村裡。",objectives={"和瑪格拉姆部族建立良好的關係，然後和瓦魯格談話。"}]])
R(1386,"突襲科卡爾部族",[[description="The Kolkar think they are strong, but we laugh at them!  We laugh and we kill them!  You kill them too.  Show me you can kill Kolkar like we do. Head north and slay them all!",objectives={"Maintain your reputation with the Magram. Kill 12 Kolkar Centaurs, 12 Kolkar Scouts and 6 Kolkar Maulers, then return to Warug in the Magram Village in Desolace."}]])
R(1387,"懸賞半人馬",[[description="半人馬是由多個部族組成的，每個部族都有各自的領袖和綱領，但是所有的半人馬部族有一點是相同的：殘忍。$B$B如果我們想要尋求和平，就必須先消滅這些半人馬。我給你的任務就是消滅他們。$B$B在淒涼之地獵殺半人馬，割下他們的耳朵。盡可能地多帶些半人馬的耳朵回來給我。$B$B為了聯盟，請一定要這麼做，$N，只有這樣，我們才能向和平更邁進一步。",objectives={"收集15個半人馬耳朵給尼耶爾前哨站的麥爾金斯下士。"}]])
R(1388,"真言藥水",[[description="Everything is proceeding according to plan, $n. I want you to give this truth serum to Deathstalker Zraedus and he'll show you how to administer it.... properly.$b$bHaha!",objectives={"Give Faustin's Truth Serum to Deathstalker Zraedus at Beggar's Haunt."}]])
R(1389,"德萊尼水晶",[[description="農田避難所裡的那些失落者和我們是同族，但他們已經是瘋狂的怪物了……在我們來到艾澤拉斯的那段殘酷的征途把他們活活逼瘋了！他們現在就住在東邊的農田避難所裡，任何在附近徘徊的人都有可能被他們抓住或殺掉……$B$B他們還偷走了我們的聖物——德萊尼水晶。$B$B我們沒有足夠的力量進入農田避難所去奪回那些被他們扔在小屋和營火附近的水晶，但是失去了那些水晶……我們就會迷失自己的方向。",objectives={"給悲傷沼澤避難營地裡的瑪格圖爾帶去6塊德萊尼水晶。"}]])
R(1390,"Oops, We Killed Them Again.",[[description="Missing text",objectives={"Missing text"}]])
R(1391,"真言藥水",[[description="We need to operate with a certain amount of discretion. After all, it's not like you're going to waltz in there and convince the fool to drink Faustin's concoction here, right?$b$bBut if there's one thing those humans cannot deny it's the booze. I'll take Faustin's serum and mix it into this ale. I guarantee the poor sap will show no reluctance when it comes to chug-a-lugging a brew.$b$bMake haste to Stonard in the Swamp of Sorrows, $n. And keep our little mission nice and quiet...",objectives={"Take Zraedus's Brew to Infiltrator Marksen in Stonard."}]])
R(1392,"木棒諾博魯",[[description="避難營裡的的德萊尼人已經被諾博魯虐待了好幾個月了，他的棒子對於這些失落者來說是一種殘忍和暴力的象徵。",objectives={"把諾博魯的木棒交給悲傷沼澤中的避難營領導人。"}]])
R(1393,"加林的逃亡",[[description="請救救我！這些東西想要吃掉我！$B$B幫我離開這兒，我就給你一筆巨大的財富！那筆財富就在斯通納德北部沼澤的營地中，但是被鎖在一個只有我知道怎麼打開箱子的保險箱裡。$B$B如果你幫我逃走，我就告訴你怎麼拿到那筆財富！",objectives={"護送加林逃出困境，然後去開啟他放在傷心沼澤營地裡的保險箱。"}]])
R(1394,"通過試煉",[[description="You have done well, $N. You have passed my test, and the tests before mine. Return to Dorn in Thousand Needles. He will sense the change within you, and see that your mind, body and spirit are strong enough that you should be rewarded for your efforts.$B$BStay true to the balance you've shown throughout these trials, $N. Dorn will test you again in the future if you do.",objectives={"Speak to Dorn Plainstalker in Thousand Needles."}]])
R(1395,"守望堡的物資",[[description="這一箱能量石要送去位於詛咒之地的守望堡。它們無法長久保持魔法的效力，因此我們恐怕不能等到下一支商隊出發時才讓他們帶去了。$B$B你必須帶著它們，去守望堡，而且動作一定要快。$B$B把它們交給城堡裡的軍需官朗格茲。想到達那裡的話，你必須向東穿越逆風小徑，再向東穿越悲傷沼澤，然後向南穿越詛咒之地。$B$B小心點，$N。你要連續穿越好幾個危險地帶，但是絕對不能失敗。",objectives={"在能量石的效力消失以前，把它們交給守望堡的軍需官朗格茲。"}]])
R(1396,"逼近的野獸",[[description="我的商隊本來是要去東海岸的，但我們還沒到達目的地之前，就遭到了巨魔的攻擊，他們殺死了護衛，而且搶走了貨物。$B$B只有我一個人逃過了襲擊。我發誓要保護好那些剩下的貨物，但這一帶的野獸太多了。拜託，不要讓那群野獸侵入我們的營地！",objectives={"殺死8隻小鋸齒鱷魚、10隻沼澤紡絲蛛和10隻沼澤虎，然後向悲傷沼澤的衛兵比格斯報告。"}]])
R(1398,"曬幹的流木",[[description="我對你實在是感激不盡，$N。你有一顆充滿榮耀的心。現在，我想我仍需要謙卑地請您幫我完成另一個任務。$B$B如果我還想到守望堡去的話，就一定得修好這輛馬車。因此……我需要一些木材，我要的是結實的幹木，而不是從那些沼澤中的樹上砍下的像海綿一樣鬆軟的木頭。$B$B$N，請到東邊的海灘上去找些已經被太陽曬乾的流木，把它們給我拿來。",objectives={"給悲傷沼澤的衛兵比格斯帶回8塊曬乾的流木。"}]])
R(1418,"尼卡·血痕",[[description="可怕的荒蕪之地就在聯盟所控制的洛克莫丹地區南方，因此斯通納德與荒蕪之地中的卡加斯前哨站之間的交流經常被切斷。$B$B去證明你自己的實力吧，$N。到荒蕪之地去，與尼卡·血痕談一談，她是卡加斯前哨站的偵察隊長。跟她談話後把她的報告拿回來給我。",objectives={"和尼卡·血痕談話。"}]])
R(1419,"捕獵山狗",[[description="$c，你在荒蕪之地呆了很長時間嗎？你感覺到那裡的炎熱了嗎？你是否跟那些在塵土飛揚的平原上到處遊蕩的野獸打過交道？如果還沒有的話，現在是時候了。$B$B峭壁山狗是一種讓人頭疼的猛獸，這些強壯而兇猛的傢伙總喜歡潛入卡加斯，偷走我們的食物補給。幫我們的前哨基地解決掉這些小偷吧！$B$B捕殺這些峭壁山狗，把它們的顎骨拿來見我。帶給我足夠多的顎骨，那樣也許我才會相信你真的瞭解荒蕪之地。",objectives={"帶30塊山狗的顎骨去見卡加斯的尼卡·血痕。"}]])
R(1420,"向赫格拉姆報到",[[description="我剛寫了一份報告要交給斯通納德的赫格拉姆，請你幫我帶去給他。$B$B如果你覺得自已是個好手，那就別在途中迷路了，也別讓這份報告落到敵人的手中。",objectives={"把尼卡的報告帶去給斯通納德的赫格拉姆。"}]])
R(1421,"丟失的貨物",[[description="巨魔攻過來的時候我被打昏了。在我昏倒前，我看到有輛馬車被拖到北邊的巨魔村落。$B$B那輛車上有一箱非常貴重的原料，一箱對守望堡的巫師研究來說非常重要的原料。找到箱子並把原料拿回來。$N。把原料帶回來給我。",objectives={"找到商隊被劫去巨魔村落的箱子，把原料帶回來給衛兵比格斯。"}]])
R(1422,"海中的威脅",[[description="While I begin work on your weapon, why don't you talk to Katar? He mentioned needing help with patrols along the beach, and I'd rather see you keep your wits and weapons prepared instead of getting drunk with some of the other louses I share this camp with.",objectives={"Speak to Katar in the Swamp of Sorrows."}]])
R(1423,"遺失的補給品",[[description="這只木桶小小的，但是非常堅固。木板的接縫處和桶蓋邊上都用一種味道刺鼻的黃色封蠟封了起來。桶底的標籤上印著兩行大字：$B$B軍需官朗格茲$B$B守望堡",objectives={"把遺失的補給物資交給軍需官朗格茲。"}]])
R(1424,"淚水之池",[[description="The Warchief sent us to investigate strange happenings at The Temple of Atal'Hakkar.$b$bThe Atal'ai trolls are a tribe of dark casters, known for practicing forbidden magic. You can imagine how astonished we were when we arrived here to discover the temple had been sunk.$b$bThe green dragons now guard the site, claiming to be protectors of Azeroth.$b$bWe need to discover what happened. Explore around the Pool of Tears and gather Atal'ai artifacts. From those I can begin to piece together this puzzle.",objectives={"Fel'zerul in Stonard wants you to gather 10 Atal'ai Artifacts."}]])
R(1425,"運送貨物",[[description="$N，在我修車的時候，我另外還有一件工作要交給你。$B$B我已經把從巨魔那裡搶救回來的最重要的幾件貨物都放在了包裹裡，你把它們都帶到守望堡裡去吧。這座城堡就在詛咒之地北方的丘陵地帶中，時刻監視著黑暗之門裡的動靜。$B$B你只要順著這條路一直向東走，在第一個岔路口向南進入死亡之地，然後再在第二個岔路口向左轉，就可以到達守望堡了。記住，要一直順著路走，$N，多加小心。",objectives={"把貨物帶給守望堡的軍需官朗格爾斯。"}]])
R(1426,"海中的威脅",[[description="I have no love for the sea, nor any creature I've seen come from its depths. It is a powerful but blind mistress; callous and brutal. It would bring me great pleasure to slay the fish men by the hundreds if it were within my power. But I garner some pleasure from watching their deaths at the hands of any who do the Horde's will.$B$BWhich brings us to you, $c. How many can you slay? Would you test yourself against their most powerful kind?",objectives={"Kill 10 Marsh Murlocs, 10 Marsh Inkspewer, and 10 Marsh Flesheater, then return to Katar in the Swamp of Sorrows."}]])
R(1427,"海中的威脅",[[description="Before you take rest, speak to Tok'Kar again. While you were gone I believe he finished a few weapons. For your help here, he would offer one of them to you. You would do well to test its strength against the fish men when you are ready... but only to please me further.",objectives={"Speak with Tok'Kar in the Swamp of Sorrows."}]])
R(1428,"海中的威脅",[[description="It pleases me to see your hatred for the fish men grows with mine.$B$BFind more of their kind along the beach, and when you've had your fill of combat, return to me. We shall speak then of a reward for your diligence.",objectives={"Kill 10 Marsh Inkspewers, 10 Marsh Flesheaters, and 10 Marsh Oracles, then return to Katar in the Swamp of Sorrows."}]])
R(1429,"阿塔萊流放者",[[description="While you were braving the dangers of the Pool of Tears, one of my scouts returned with a scroll written in blood on dried flesh. It seems to be a judicial sentence against a priest of the Atal'ai tribe.$b$bThis priest was sentenced to a fate worse than death amongst the Atal'ai.$b$bHe was exiled to live far north in the Hinterlands, with the Witherbark trolls.$b$bI will bundle these artifacts. You are to seek out the exile and discover their true use. Return to me once your journey is complete.",objectives={"Bring the Bundle of Atal'ai Artifacts to the Atal'ai Exile in the Hinterlands."}]])
R(1430,"新鮮的螃蟹腿",[[description="There's a high demand for the succulent taste of crawler meat among my customers; especially the meat from the monstrous crawlers.$B$BIf you plan on heading to the coast, then I could easily make it worth your while to bring me back some of their legs to have transported back to Orgrimmar.$B$BThe coast is to the east from here, and you should have no problem finding the creatures scurrying along the beaches and under the sea.",objectives={"Bring 10 Monstrous Crawler Legs to Dar in the Swamp of Sorrows."}]])
R(1431,"聯盟關系",[[description="Be still, $c, and allow me to share with you something important to our people, but far from obvious.$B$BWe are a proud race, and the war with the humans tried even Thrall's great patience. You see, our Warchief is wise and prudent, and he continues to put his people first. Ultimately, he is a diplomat, and in his time with the humans he learned much of their ways.$B$BIf the tale I've started piques your interest, then find Keldran near the western exit of the city. His hovel is there.",objectives={"Speak to Keldran in Orgrimmar."}]])
R(1432,"聯盟關系",[[description="As the Alliance progresses deeper and deeper into Kalimdor, incorrect conclusions may be drawn about the Horde making pacts with the Burning Legion. The Warchief cannot allow that to happen. And with his blessing, I am taking control of overseeing them removed.$B$BI have agents in the area of Desolace at the Ghost Walker Post north of the great Kodo Graveyard. Head south of the Charred Vale in the Stonetalon Mountains and you shall come across it. When you arrive, seek out Takata Steelblade.",objectives={"Speak to Takata Steelblade in Desolace."}]])
R(1433,"聯盟關系",[[description="The Burning Blade have many agendas, but know that they are evil to their core, their spirits corrupted, and their destruction is the only way to thwart their objectives.$B$BKeldran sent Maurin with me because of his knowledge of the Blade and their warlock ways.$B$BHe has control of our plots against the Blade while I deal with the other demonic threats here in Desolace.$B$BSpeak to him, and he will guide you in his designs.",objectives={"Speak to Maurin Bonesplitter in Desolace."}]])
R(1434,"薩特的威脅",[[description="惡魔是絕對不會憑空就出現的——他們需要一些空隙使邪惡得以立足。$B$B這空隙或許會產生自孱弱的精神，或許是對權力的無謂欲望，或許是對復仇的渴求，或許是要求最終審判的控訴。當我們被痛苦所困擾時，邪惡就會利用我們——例如薩特這樣的邪惡力量。$B$B火刃氏族與它們之間顯然有很緊密的聯繫，因此索爾認為他們必須被清剿乾淨。到東北方向去尋找的它們的蹤影，在將他們驅趕出這一帶後回來向我報告。",objectives={"殺死7隻怨怒盜賊、7隻怨怒魔僕、7隻怨怒背叛者和7隻怨怒喚魔者，然後向淒涼之地的塔卡塔·鋼刃覆命。"}]])
R(1435,"靈魂的燃燒",[[description="對那些為了某些自私的理由而背叛了自己首領的卑劣生物們而言，死亡是他們最合適的歸宿。但對於那些將自己的全部身心奉獻給黑暗的傢伙們來說，死亡還遠遠不夠。$B$B拿著這塊寶石，當你附近有火刃氏族的爪牙死去時，就啟動寶石上面的魔法。這個法術會拯救墮落的靈魂，將它們拉出黑暗的深淵，灌注到寶石裡。$B$B在這些寶石中灌入了靈魂之後，把它們帶回來交給我，我會妥善處置它們。$B$B現在就出發吧，多加小心。",objectives={"將15塊燃燒寶石轉變為灌入靈魂的燃燒寶石，然後把它們交給淒涼之地的莫林·碎骨者。"}]])
R(1436,"聯盟關系",[[description="形勢很順利，$N。如果我們能繼續保持目前的推進勢態的話，或許酋長會允許我們在換季之前回到久別的家園。$B$B回到科爾丹那裡去，告訴他我們都幹了些什麼。我敢打賭他一定會為你在這兒的功績而獎勵你。他的事業對他來說很重要，並且如果酋長也會對他的成就表示敬意的話，他一定會非常自豪。",objectives={"與奧格瑪的科爾丹談話。"}]])
R(1437,"瓦拉裏爾的搜尋",[[description="你好，$n，我是瓦拉里爾。我到這裡是來尋找達納蘇斯商業世家——瑪雷姆家族的兩個失蹤的孩子。這個家族的族長已做好了最壞的打算，不過我還是要盡一切可能找到他的孩子。我已經開始了搜尋泰拉尼斯和黛琳達的工作，但願一切順利。$B$B我最近得知的線索是，幾週前他們已經越過了石爪山。$B$B如果你發現了他們的蹤跡，就請立刻通知我。",objectives={"去淒涼之地尋找泰拉尼斯·瑪雷姆和黛琳達·瑪雷姆的馬車。"}]])
R(1438,"瓦拉裏爾的搜尋",[[description="找到泰拉尼斯和黛琳達，然後帶著你的發現回來見我。從這座城堡開始進行搜尋吧，我會立刻和達納蘇斯的上級聯繫，讓他們知道這裡的情況。$B$B對了，$N，還有一件事情一定會讓你影響深刻。我的上級最關心的並不是泰拉尼斯以及他在這裡的活動。對他們來說，更重要的是黛琳達能否安全地回來。泰拉尼斯……在他回來之前必須要接受評估。",objectives={"去淒涼之地找到黛琳達·瑪雷姆。"}]])
R(1439,"尋找泰拉尼斯",[[description="獸人殺掉了我們所有的護衛和僕從，然後把我們帶到了這裡。天啊，那真是太可怕了！我以為他們肯定也會殺了我們，不過顯然它們有別的計畫。$B$B泰拉尼斯試圖和他們交涉，我想他試圖用對祕法的瞭解來博得他們的好感……我不知道他為什麼要那麼做。$B$B沒有找到哥哥的下落，我就不離開這裡。找到他，然後再回來救我吧。",objectives={"去淒涼之地找到泰拉尼斯·瑪雷姆。"}]])
R(1440,"回復瓦拉裏爾",[[description="怎麼樣，你準備好了嗎？我感謝你的幫助，如果時間不是太緊的話，請在此時此刻就接受我對你的感謝：感謝你對我和我的家族所做的一切。如果你準備好了，我們就趕快動身離開吧。",objectives={"護送黛琳達·瑪雷姆離開雷斧堡壘，然後回到淒涼之地的瓦拉里爾·屠魔者那裡。"}]])
R(1441,"<UNUSED>")
R(1442,"尋找科爾寶石",[[description="Greetings, $N. What can I do for one who follows a holy path?$B$BAh, yes, Stilwell, the blacksmith... from long ago. I remember him well, though, I have not heard his name in some time.$B$BHe never struck me as an impudent man, so I can only assume his desire for a Kor gem is noble.$B$BIf you truly wish for one of the gems, then you must head to the northwest of Ashenvale. You will find Blackfathom Deeps there within some ancient ruins. The naga who still use the gems are down below. Do not go alone, $c.",objectives={"Bring a Kor Gem to Thundris Windweaver in Darkshore."}]])
R(1444,"向費澤魯爾復命",[[description="Jammal'an the Prophet sentenced me to exile from The Temple of Atal'Hakkar. I once felt the high priest was a worthy leader.$b$bHis unyielding faith in his prophecy will bring about the destruction of the Atal'ai. If it hasn't already.$b$bWhen I expressed my concerns, I was labeled an infidel and ousted from the temple.$b$bThose artifacts you brought to me are harmless. But if Jammal'an has found the proper fetish enchantment for the summoning ritual, the world lies in great peril....",objectives={"Return to Fel'Zerul in Stonard."}]])
R(1445,"阿塔哈卡神廟",[[description="So he spoke of Jammal'an's prophecy?$b$bThe Atal'ai spiritual leader believes once Hakkar returns to Azeroth from the Nether, the god will grant the Atal'ai tribe immortality.$b$bFoolish trickery to bring about a premature doomsday if you ask me.$b$bBut you say the exile spoke of enchanted fetishes? This concerns me greatly. If these are in fact the key to the Atal'ai ritual which caused this mess, we must understand their intrinsic powers.$b$bVenture into the Temple, and seize the fetishes!",objectives={"Collect 20 Fetishes of Hakkar and bring them to Fel'Zerul in Stonard."}]])
R(1446,"預言者迦瑪蘭",[[description="我的枯木同伴們通常對家裡附近的陌生人都不太友善。$b$b我？我已經沒有家了。我被我悲傷沼澤的阿塔萊族的同胞流放到這裡。$b$b我們的精神領袖迦瑪蘭曾有過一個「預言」，他聲稱召喚哈卡能帶給阿塔萊族永恆的生命。$b$b但是我覺得有些不對勁的地方，如果這個預言僅僅是為了操縱我們，那我們該怎麼辦？$b$b我要為他們流放我的舉動復仇，給我把迦瑪蘭的頭帶回來，也許這樣我的同胞就可以重獲自由。",objectives={"辛特蘭的阿塔萊流放者想要迦瑪蘭的頭。"}]])
R(1447,"失蹤的使節",[[description="是啊，你顯然不是來到暴風城中最聰明的$c，但你有可能成為那些永遠無法離開的大笨蛋之一！$B$B你見過我的」朋友」了嗎？",objectives={"擊敗暴風城的達舍爾·石拳。"}]])
R(1448,"調查神廟",[[description="我年輕的時候，也是像你這樣活力充沛，有一股衝勁的。$b$b但現在我老了，也不能像當初那樣在這片大陸上到處冒險了。啊，真是懷念那段日子啊！$b$b但我過去的冒險生涯中卻裡還有一個未解之迷。在我的最後一次任務中，探險者協會派我去調查阿塔哈卡神廟，據說那座廟宇就在悲傷沼澤裡。$b$b但當時我卻感到害怕，只是坐在獅鷲獸上飛過了這片地方，自然，我並沒有找到神廟。$b$b你願意滿足一個老矮人最後的願望嗎？或許你走路過去的話就可以找到神廟……",objectives={"暴風城的布羅哈恩·鐵桶要求你去找到阿塔哈卡神廟。"}]])
R(1449,"去辛特蘭的旅程",[[description="As I mentioned earlier, I attempted to scout the temple on my own from the air. Well, I wasn't exactly alone.$b$bI traveled to the renowned gryphon aviary at Aerie Peak in The Hinterlands. There I enlisted the aid of one of their finest pilots. The pilot fell off his mount, down into the swamp...$b$bIn my old age the poor fellow's name eludes me. The master of the aviary would remember, no doubt.$b$bJourney there and seek out Falstad Wildhammer.$b$bWe need to find out what happened to that pilot.",objectives={"Speak with High Thane Falstad Wildhammer at Aerie Peak in the Hinterlands."}]])
R(1450,"獅鷲管理員",[[description="So you're a glorified errand $g boy:girl; for some old Explorers' League geezer, eh?$b$bWell you listen to me, $c. I don't know who your old buddy was flying around with down in Azeroth. Do I look like Gryphon Master Talonaxe to you? Do I?$b$bIf you're so interested in the flight assignments why don't you ask the gryphon master? If I catch you idling around here for much longer, I'm going to put you to some real work.$b$bNow get a move on.",objectives={"Speak with Gryphon Master Talonaxe inside the Aerie Peak Aviary."}]])
R(1451,"拉普索迪·鐵鏟",[[description="Rhapsody took quite a liking to the booze. Now don't get me wrong -- all of us dwarves up here at the aviary love a good ale when the time is right.$b$bBut ol' Shindigger took to the liquor like a gryphon takes to the skies. And a damned shame it was, too. No one could fly like Rhapsody.$b$bFirst sign of trouble was when he came stumbling back from that mission with your buddy, Brohann. All went down hill quickly after that. Had to let him go.$b$bLast I heard, he's set up a brew camp to the east of here...",objectives={"Seek out Rhapsody Shindigger in The Hinterlands."}]])
R(1452,"拉普索迪的卡利姆多雞尾酒",[[description="嗝兒！$b$b你是那瘋子加蠢蛋布羅哈恩派來的啊？我們倒是一起經歷過一次大……大冒險……嗝兒！$b$b如果你想要知道我那時候掉進沼澤裡的時候看到了什麼，行，不過我得先喝上一杯好的。要知道那底下可不是什麼美景……嗝兒！$b$b要不這麼著吧……如果你給我弄些原料來配製卡林多雞尾酒，我就告訴你。$b$b至於原材料，先去塔納利斯搞點大鵬的砂囊……然後，然後……我看看……再去菲拉斯弄點格羅多克猩猩和鐵鬃熊的肝臟來……$b$b這便是唯一能打開我的話匣子的東西，美味的卡林多雞尾酒呀！",objectives={"辛特蘭的拉普索迪·鐵鏟要求你帶給他10塊大鵬的砂囊、10塊格羅多克猩猩的肝臟和10塊鐵鬃熊的肝臟。"}]])
R(1453,"尋物公司的業務",[[description="我有些工作得要你去淒涼之地一趟，$N。那裡是個非常兇險的地方，滿地都是半人馬和其他討厭的東西。不過如果你想找一份為期一星期的充實工作，就去那兒找克雷迪格·安戈爾，並告訴他是我叫你去的。$B$B你可以在尼耶爾前哨站找到他，那是淒涼之地北部山區裡的一個小營地。當你從石爪山進入淒涼之地的時候就向東轉。尼耶爾前哨站不好找，路上要多留心看看。",objectives={"和淒涼之地的克雷迪格·安戈爾談話。"}]])
R(1454,"卡尼托的海難",[[description="我的第一筆訂單來自法師卡尼托，他是暴風城裡的一個貴族。他的船似乎在淒涼之地西北邊的海岸附近受到了海巨人的襲擊，他和僕人們試著想把最值錢的一個箱子帶上岸，然而海巨人成群結隊地發起攻擊，所以他不得不放棄了這個想法，把自己和僕人傳送到安全的地方。$B$B他希望我們能幫忙找到那個箱子及箱子內的物品，並且把它送到暴風城。",objectives={"在淒涼之地找到卡尼托的箱子。"}]])
R(1455,"卡尼托的海難",[[description="你仔細考慮著到底是什麼東西撬開了箱子，同時觀察著箱子四周和頂部的又長又深的痕跡。顯然，這並不像是某個人或是某個海巨人幹的，而且這些撬痕似乎也不是匕首或者是利劍留下的。$B$B打開箱子檢查了一番之後，你發現它是空的。$B$B找不到一點頭緒，於是你關上箱子準備離開。克雷迪格一定會很失望。",objectives={"回到淒涼之地的克雷迪格·安戈爾那裡。"}]])
R(1456,"卡尼托的海難",[[description="真有趣。$B$B其實，我們也不是一點希望都沒有。$B$B在那個海岸更靠北的大海深處，有一片夜精靈的廢墟。一個納迦部落把那裡當成了他們的家，他們管那地方叫什麼來著……滑刺……不，是滑刃部族！我想我們可以去那裡碰碰運氣。$B$B如果有什麼人能夠深入到那麼遠的南部，那他們一定非常強大。如果你要去找卡尼托的東西，那麼就準備對付更加強大的納迦——滑刃潮行者或者滑刃海巫吧。",objectives={"找到卡尼托的背包，把它交給淒涼之地的克雷迪格·安戈爾。"}]])
R(1457,"卡尼托的背包",[[description="Take Karnitol's things back to Roetten in Ironforge and he'll pay you for a job well done.$B$BHaha, if you're not careful, he's gonna be so pleased with ya that he'll ask you to join us full time.$B$BAgain, great job, $N.$B$BBe careful on your way back, and don't take too much time--Karnitol's not the most of patient of men, but he's very generous nonetheless.",objectives={"Bring Karnitol's Satchel to Roetten Stonehammer in Ironforge."}]])
R(1458,"尋物公司的委托",[[description="我到這裡來的一個主要任務就是幫萊弗維奇收集材料，萊弗維奇是卡拉諾斯城中的一個地精法師。羅頓總覺得這件事對我們來說輕而易舉，卻對我們這裡人手短缺的現狀視而不見。$B$B他列出的清單上的前幾件物品應該很容易找到，如果你幫我找到它們的話，就可以獲得豐厚的報酬。$B$B首先你得從東邊的怨怒薩特身上弄一些角和爪子回來，然後我們再來尋找清單上列出的其他物品。",objectives={"收集10隻怨怒薩特的爪子和10根怨怒薩特的角，把它們交給淒涼之地的克雷迪格·安戈爾。"}]])
R(1459,"尋物公司的委托",[[description="萊弗維奇貨單上的下一條……我看看……哦，在這裡。$B$B非常簡單，而且說明也寫得非常清楚。他需要荒土蠍的毒液和科多獸的毛皮。清單上寫得很清楚：這兩件東西分別來自兩個特定的物種：毒液來自於荒土鞭尾蠍，而毛皮則來自老邁的科多獸，注意，既不是瀕死的科多獸也不是遠古科多獸。$B$B法師……他們總是要一些稀奇古怪的東西……",objectives={"收集7瓶鞭尾蠍的毒液和3塊老邁科多獸的毛皮，把它們交給淒涼之地的克雷迪格·安戈爾。"}]])
R(1460,"<UNUSED>")
R(1461,"<UNUSED>")
R(1462,"大地靈契",[[objectives={"Speak to Seer Ravenfeather for another Earth Sapta."}]])
R(1463,"大地靈契",[[objectives={"Speak to Canaga Earthcaller for another Earth Sapta."}]])
R(1464,"火焰靈契",[[objectives={"Speak to Telf Joolam for another Fire Sapta."}]])
R(1465,"瓦拉裏爾的搜尋",[[description="當你繼續搜尋馬車時，你發現除了墜子外，還有一串足印一直向南方延伸過去。在遠方有一座巨大的城堡上空煙霧繚繞，那煙霧來自於城堡哨塔上的烽火，而不是房屋的燃燒。你的直覺告訴你：如果瑪雷姆兄妹還活著，那他們一定就在那裡。$B$B你想尼耶爾前哨站的瓦拉里爾應該不只要看看你找到的墜子，還得知道南邊有人活動的消息。",objectives={"將瑪雷姆墜子帶回去給淒涼之地的瓦拉里爾·屠魔者。"}]])
R(1466,"尋物公司的委托",[[description="這是物品列表上的最後一些東西了，我不會撒謊，撒謊可不是件光彩的事情。恐怕你得花更多的時間去尋找這些……$B$B我已經說了這麼多了，言歸正傳。萊弗維奇的要求是：從噬法魔犬，法師獵手或者靈能獵犬那裡收集15個大腦；從地獄魔女、地獄巫女或地獄修女那裡收集15對魔女之翼；還有……從末日看守隊長或者末日看守領主那裡收集15瓶末日看守之血。$B$B是不是很簡單啊？呵呵……如果你不想接這項任務的話，我也能理解。",objectives={"收集10個地獄犬的腦子、10對魔女之翼和10瓶末日看守之血，把它們交給淒涼之地的克雷迪格·安戈爾。"}]])
R(1467,"尋物公司的委托",[[description="要想得到報酬，你就得去一趟鐵爐堡，親自和羅頓談談。他會非常樂意收到萊弗維奇的包裹的。把這個交給他，然後你應該就能收到報酬了。$B$B別擔心，我回去以後會替你美言幾句的，我應該不會在淒涼之地待太久的。",objectives={"把萊弗維奇的包裹交給鐵爐堡的羅頓·石錘。"}]])
R(1468,"兒童周",[[description="You're willing to help us here at the orphanage?  Bless you, friend; your aid during Children's Week will be invaluable.$B$BTake this whistle.  You will only be able to use it for a short amount of time - typically not longer than Children's Week itself.  When you use it, you will be able to talk with the child you've agreed to look after.  Using it again will dismiss the child.$B$BBy all means $N - use the whistle and meet your ward!  I'm sure the child will be most eager to meet you.",objectives={"Use the Human Orphan Whistle to talk with the child you will be looking after during Children's Week."}]])
R(1469,"拉普索迪的故事",[[description="Before the flight, I drank me a whole keg of stout. Hiccup!$b$bAnd what a flight it was. Zipping around with Brohann following me. Didn't see no temple though. Hiccup!$b$bWell, didn't see no temple till I got a little too tipsy and fell off my mount. I plunged right into the water and was sucked down. Found myself surrounded by a bunch of creepy trolls. Sure swam out of there fast! Even made off with this troll souvenir. Here, take it to Brohann and let him know his temple is down there, indeed. Hiccup!",objectives={"Bring the Atal'ai Tablet Fragment to Brohann Caskbelly in Stormwind."}]])
R(1470,"控制小鬼",[[description="Greetings, child. I can see that you are still young in the ways of the warlock, power still eluding your grasp. I can sense your eagerness to learn.$b$bAnd you will learn.$b$bThere is no strength in ignorance. Knowledge is our greatest power. Through its application, we can control the chaotic magics and beings of the void, bending them to our will.$b$bI will show you how to bind a servant to your will, but first you must bring me three skulls of the rattlecage skeletons near the abandoned smithy.",objectives={"Bring Venya Marthand 3 Rattlecage Skulls."}]])
R(1471,"誓縛",[[description="Surely you have seen the circle of summoning below us? Only there will you be able to draw forth an unbound voidwalker.$b$bUsing these runes, you will be able to draw it forth, and then you must dominate it through strength of arms and magic.$b$bWhen it is subdued, it will be indentured to you. Come to me then, and I will elucidate the spell of summoning, so that it may serve you to whatever end you wish.",objectives={"Using the Runes of Summoning, summon and subdue a voidwalker, then return the Runes of Summoning to Carendin Halgar in the Magic Quarter of the Undercity."}]])
R(1472,"噬魂者",[[description="A succubus is a devourer of souls, destroyer of hearts, tempter of men. A creature of profound evil and of singular mind.$b$bIt cannot be brought into our world without a stimulus.$b$bThus we use its own strength against it. With the hearts of good men, pure men, loving men, the succubus will be unable to resist, and will cross into our world. Then you can dominate it, and make it your own.$b$bSpeak with my assistant, Godrick Farsan, within the Temple. He will help you find your bait.",objectives={"Speak with Godrick Farsan in the Temple of the Damned."}]])
R(1473,"虛空中的生物",[[description="It seems the consensus that you are ready to learn to summon a voidwalker.$b$bA being created of the chaos that lies beyond, if you summon one but cannot control it, you will be torn asunder.$b$bThe first voidwalker was summoned by Egalin, and in his grimoire is the process explained.$b$bUnfortunately, it was stolen from us by an agent of the Scarlet Crusade who has it secreted away in his base at a tower to the west. Bring it to me, and I will impart the knowledge to you.",objectives={"Recover Egalin's Grimoire and bring it to Carendin Halgar in the Temple of the Damned."}]])
R(1474,"誓縛",[[description="Using these hearts, cast a spell at the summoning circle to open a doorway for the succubus to come through. Your powers are greater now, and you will need all of them to defeat the succubus. $b$bBeware its charms, $n, many a strong mind has been bound to its will. When overcome, the succubus will be returned to the void, and I will teach you the spell to summon it forth at your command.",objectives={"Using the Pure Hearts, summon and subdue a succubus, then return the Pure Hearts to Carendin Halgar in the Magic Quarter of the Undercity."}]])
R(1475,"進入阿塔哈卡神廟",[[description="根據傳說，阿塔哈卡神廟是供奉著古代神祗「靈魂掠奪者阿塔哈卡」的神聖祭壇，有一個名叫阿塔萊的食人妖部族世世代代守護著這座廟宇，據說從來也沒人能進到廟中去一窺究竟。$b$b潛到淚水之池底部並從廟中取出古代的神器是件很困難的事，但這卻正是我要你去做的，$n。$b$b幫我收集一些完整的阿塔萊石板，把它們帶回來給我，這樣一來我就能以英雄的身份回到探險者協會去了。我會和你一起分享這份榮耀。",objectives={"為暴風城的布羅哈恩·鐵桶收集10塊阿塔萊石板。"}]])
R(1476,"純潔者之心",[[description="Men of honor and goodness? Does such a man exist?$b$bIt took much research, but through bits of overheard stories, I managed to find two men that should do.$b$bThe first is Dalin Forgewright, who has dedicated himself to the care of the Lordaeron refugees, whom are refused by their kin at the Greymane Wall.$b$bThe other is Comar Villard, a man who remains faithful to his lost love, wandering the Wetlands for a sign of his wife.$b$bDeliver their hearts to Carendin. But first, let me show you your quarry.",objectives={"Bring the hearts of Dalin Forgewright and Comar Villard to Carendin Halgar in the Temple of the Damned."}]])
R(1477,"重要的補給",[[description="法師們正在詛咒之地的守望堡裡進行研究，這項重要的研究關係到我們對黑暗之門的瞭解。他們需要持續的補給，然而我們到守望堡的補給線非常脆弱。$B$B你必須提供幫助以保證補給物資安全抵達守望堡。到夜色鎮去找守衛隊長索里加爾，按他的指示去做。這次任務要求你進入敵方區域，準備出發吧，$N。",objectives={"和守衛隊長索里加爾談話。"}]])
R(1478,"哈加爾的召喚",[[description="Ah, $n! I just received word from Carendin Halgar that he would like to see you for further training.$b$bYou should be proud of yourself, $n. It's not every day that Master Halgar personally sees fit to instruct a young warlock.$b$bYou'll be able to find him in the Magic Quarter of the Undercity, near the Temple of the Damned.",objectives={"Speak with Carendin Halgar in the Undercity."}]])
R(1479,"永恒之樹",[[description="I've heard stories about how the night elves have their bank in a tree - one that looks like a bear!  That's so cool!  Night elves are neat how they like nature and stuff, but bears are just totally awesome!$B$BWould you take me to see the bear-tree in Darnassus, please?  There's a boat that will take us close to there, and it shouldn't take very long.  Please, please, please!",objectives={"Take the orphan to the bank of Darnassus.  The bank itself is hollowed out of a tree known as the Bough of the Eternals."}]])
R(1480,"墮落者",[[description="這塊被裁下來的皮革聞起來有股腐臭味,而且看起來乾燥而易碎的東西卻是異常地柔軟。$B$B在攤開它之後，你可以清楚地看見其中一面上有著用某種語言寫成的紅色標記文字。在皮革的底端有一個十分清晰的符號，你認為這是個簽名。$B$B也許莫林能告訴你些什麼？",objectives={"把這塊惡魔之皮拿給淒涼之地的莫林·碎骨看看。"}]])
R(1481,"墮落者",[[description="我相信我可以在具備適當材料的情況下找到這個魔王。$B$B如果他真的如我預期的一樣強大，那我就需要一些從非常危險的生物身上才能收集到的物品。既然你是為酋長做事的，那麼我想你應該會接受我交付給你的任務吧。$B$B首先，我需要破壞他的反偵測結界。去找一塊薩特的頭皮來給我，不過並不是任何薩特的頭皮都可以的，只有怨怒巡影者的頭皮才能用。$B$B從淒涼之地東北部的古代遺跡附近開始找起吧。",objectives={"帶一張巡影者的頭皮回來給淒涼之地的莫林·碎骨者。"}]])
R(1482,"墮落者",[[description="An oracle crystal would do nicely. They are crafted by the naga for their oracles to use.$B$BNorthwest of here, along the coast, is a vast coral reef that the naga have taken as their home when this close to the shore. You can find their oracles there. The Slitherblade are deadly and will not react kindly to your intrusions, so be careful and make haste.$B$BWhen you return, we shall see about finding this demon lord Azrethoc.",objectives={"Bring an Oracle Crystal to Maurin Bonesplitter in Desolace."}]])
R(1483,"菲茲克斯",[[description="風險投資公司偷走了許多最有天分的哥布林創意，不過我們不時地會偷一些回來。$b$b不久以前，風險投資公司在石爪山的分支機搆居然雇傭了格雷蘇——一個地精！他們的另一個工程師菲茲克斯只有靠邊站了。他懇求我幫他在工匠協會找份工作，我交給他一些任務，不過他或許會需要幫助。$b$b也許你能幫他一把？菲茲克斯現在就住在狂風峭壁的西部。",objectives={"和狂風峭壁的菲茲克斯談話。"}]])
R(1484,"墮落者",[[description="This creature is far more dangerous than I had anticipated.  No doubt Takata questions my abilities to take on such a creature, and it would insult his honor if he were not informed about what just happened.$B$BSpeak to the swordsman, tell him you are willing to slay the demon if he would allow it, but do not press too hard. It is better if he thinks it his own idea.",objectives={"Speak to Takata Steelblade in Desolace."}]])
R(1485,"邪靈劣魔",[[description="在我們之前來的術士，在這裡得到的只有部落對他們的不信任，雖然我們現在得到了一些容忍，但是仍然不受喜愛。$b$b但這種情況並沒有讓術士們更加團結在一起，相反的，有很多人選擇了隱居的生活，獨自研究著他們的魔法。我不會去引導你選擇其中的任何一條道路，只會幫助你變得更加成熟。$b$b在我教導你召喚的方法之前，先帶六顆東北方山洞裡的邪靈劣魔的腦袋回來給我。",objectives={"帶6顆邪靈劣魔的頭顱回來給魯贊。"}]])
R(1486,"變異皮革",[[description="As Naralex descended deeper into his nightmare, a strange breed of beasts arose from beneath the Barrens into the Wailing Caverns.$b$bThese deviate creatures have strange, otherworldly properties. While evil in nature, it is my opinion that some good can come from their existence here in Kalimdor. I believe their hides will be of particular use in the ways of leatherworking.$b$bIf you feel up to the task, venture into the caves below and retrieve some deviate hides.",objectives={"Nalpak in the Wailing Caverns wants 20 Deviate Hides."}]])
R(1487,"清除變異者",[[description="Naralex had a noble goal.$b$bOur great leader aspired to enter the Emerald Dream and help regrow these harsh lands back into the lush forest it once was. But something went terribly wrong.$b$bNaralex's dream turned into a nightmare and corrupt creatures began to inhabit the caverns.$b$bWhile some Disciples of Naralex seek to awake our master, my concern is with ridding these caves of the evil beasts.$b$bBrave the caverns, $n, and eradicate the deviate spawn.",objectives={"Ebru in the Wailing Caverns wants you to kill 7 Deviate Ravagers, 7 Deviate Vipers, 7 Deviate Shamblers and 7 Deviate Dreadfangs."}]])
R(1488,"墮落者",[[description="Although I have no knowledge of this Lord Azrethoc, I agree with Maurin, he must be stopped; especially if he is attempting to gain influence over the Burning Blade to further his goals.$B$BYou have already shown you wish to aid the Warchief, and I would trust you to gather a party to slay the demon lord and his warlock servant.$B$BWhen you are ready, head directly south,  and return to me when the threat has been ended.",objectives={"Slay Lord Azrethoc and Jugkar Grim'rod and return to Takata Steelblade in Desolace."}]])
R(1489,"哈繆爾·符文圖騰",[[description="你帶來的獸皮有一種奇怪的斑點，一種我從來沒有見過的斑點。我確信綠洲裡的水是造成這些斑點的原因，我甚至能夠感受到它們給這片土地帶來的混亂，這片土地現在死氣沉沉的，就好像是長眠不醒了一樣。$B$B哀嚎洞穴一定就是這一切問題的源頭。但是，在你去那裡調查以前，先去找德魯伊長老哈繆爾·符文圖騰談談吧。我托人給他捎了信，把關於在貧瘠之地所發生的一切都轉告給他了。這位博學的長者應該能給你很多忠告。$B$B他就在雷霆崖的長者高地上。",objectives={"和哈繆爾·符文圖騰談話。"}]])
R(1490,"納拉·蠻鬃",[[description="I entered the land of dreams, and dreamed of a cult of druids who dwell in the Wailing Caverns.  I saw that their goals were once noble, but they have lost their way.  They are now servants of the taint seeping through the Barrens.$B$BI am old and my strength fails.  I could not long dwell in that dreaming place and know little more of the tainted druids.  But Nara is young and her spirit is fierce.  She remained in the dreaming when I fled.$B$BSpeak with Nara.  She is in the tent, over yonder.",objectives={"Speak with Nara Wildmane."}]])
R(1491,"智慧飲料",[[description="好吧，這些角似乎不太有用。不過沒關係——萬事開頭難嘛！我想我已經找到另一種原料，可以讓我製造出更好的智慧飲料！$B$B有一種叫做哀嚎香精的物質，我想這種東西就是造成貧瘠之地出現各種奇特動植物的原因。幫我找到這種物質，我要把它加入我的飲料裡試試看！$B$B我聽說這種物質可以在西邊的哀嚎洞穴裡的那些怪物身上找到，去獵捕這種生物，幫我收集哀嚎香精吧。",objectives={"收集6份哀嚎香精，把它們交給棘齒城的麥伯克·米希瑞克斯。"}]])
R(1492,"碼頭管理員迪茲維格",[[description="I have need to send a crate of potions, reagents and other items to my associates in the Old World. Little time I have to actually see them to the dock at Ratchet, and the last caravan has already left.$b$bIf you could, please take this to Wharfmaster Dizzywig. He will ensure that it is placed on the next boat to Blackwater Cove.",objectives={"Bring the Secure Crate to Wharfmaster Dizzywig in Ratchet."}]])
R(1498,"防禦之道",[[description="As a warrior, one of our most crucial tasks is... protection.  We are the shield of the Horde, and we keep our weaker brethren safe.  If you are to join in our ranks, then you must prove your mettle to me.$B$BGo to Thunder Ridge in Durotar, where live the lightning hides and thunder lizards.  Hunt the beasts!  Show me you are tougher than they!  Brave their assaults and bring me a stack of their singed scales as proof.$B$BDo this, and then I will teach you.",objectives={"Bring 5 Singed Scales to Uzzek at Far Watch Post in the Barrens."}]])
R(1499,"邪靈劣魔",[[description="祖雷薩正在找你這樣的新手，讓他們到當初你獵殺邪靈劣魔的那個地方旁邊的洞穴裡去，削減那裡的生物數量。$b$b我想你可以在幫助她的過程中學到很多東西。記得跟她說，你是去幫忙解決小鬼問題的，她肯定會準備一份獎勵給你。",objectives={"與祖雷薩談話。"}]])
R(1500,"Waking Naralex")
R(1501,"虛空中的生物",[[description="So few warlocks remain... We risk much, but the risks are warranted. You must quickly reach maturity in your ability if you are to be of use to the Horde and to the Warchief.$b$bIt is time that you learned a new summoning spell.$b$bFirst, you must recover the Tablet of Verga, which was stolen by warlocks of the Burning Blade and is now kept at their lair in Skull Rock to the east of the city. With the tablet, I will show you the runes necessary to summoning a voidwalker.",objectives={"Retrieve the Tablet of Verga for Gan'rul Bloodeye in Orgrimmar."}]])
R(1502,"索恩格瑞姆·火眼",[[description="It is vital that a warrior's weapon is one of quality.  And if there is an orc who can craft quality weapons, then that orc is Thun'grim Firegaze.  He is a hermit who dwells atop the hills east of the Crossroads.$B$BIf you seek a weapon, warrior, then you should seek Thun'grim.  To find him, first travel to the Crossroads to the west, then strike east into the hills.  His camp is high on a hilltop.",objectives={"Speak with Thun'grim Firegaze in the Barrens."}]])
R(1503,"鍛造好的鋼錠",[[description="I will give you a weapon, $N, but first you must aid me.  The Razormanes to the northwest came into my camp a few nights past.  They would not meet me in combat, but they know my eyes are bad--a few distracted me with snorts while others stole from me!  The cowards!$B$BThey took an iron chest, and within it were some forged steel bars.  If you can recover them then I will give you the weapon you seek.$B$BSearch for the iron box within the quilboar camps, and return with the forged steel bars.",objectives={"Bring the Forged Steel Bars to Thun'grim Firegaze in the Barrens."}]])
R(1504,"誓縛",[[description="Now, observe the Tablet of Verga, for it contains the glyphs you will need for the summoning. Take them to the circle in Neeru Fireblade's tent on the other side of the cavern. There you will be able to call for the voidwalker.$b$bYou must defeat it using whatever physical and magical means you have at your disposal. When this is completed, return to me with the glyphs of summoning and I will demonstrate how you may bind the creature to your will.",objectives={"Using the Glyphs of Summoning, summon and subdue a voidwalker, then return the Glyphs of Summoning to Gan'rul Bloodeye in Orgrimmar."}]])
R(1505,"老兵猶塞克",[[description="The Horde honors its warriors because their strength is unquestioned.  But the truly great warriors are great students as well.$B$BSeek out Uzzek.  He is a veteran of many battles and now instructs young warriors in the ways of combat.  You will find him south of Far Watch Post, the orc garrison on the border of the Barrens and Durotar to the east.",objectives={"Speak with Uzzek at Far Watch Post."}]])
R(1506,"甘魯爾的召喚",[[description="You there. $n, right?$b$bI hope your schedule isn't busy, because Gan'rul wants to see you right away. You'll find him with the senior warlocks in the Cleft of Shadow.$b$bBased on my past dealings with Gan'rul, your summons is either a very good thing or a very bad thing.",objectives={"Speak with Gan'rul Bloodeye in Orgrimmar."}]])
R(1507,"噬魂者",[[description="The time has come for you to learn more of the summoning magics. You will learn to summon a succubus, a creature of incredible mental powers. It can lull those of weak minds into its servitude--but have no fear! I feel certain that you will be equal to the challenge.$b$bA succubus can only be summoned when baited with an item that represents great devotion and love. I leave it to you to find such an object.$b$bA suggestion? Speak with Cazul... There seems to be little the ancient warlock does not know.",objectives={"Speak with Cazul in the Cleft of Shadow."}]])
R(1508,"盲眼卡祖爾",[[description="Hmm... But, of course, that is not why you have come to speak with me.$b$bIf Gan'rul has sent you to me, it must be that you are to summon a succubus, and need an object to use for enticement.$b$bHmm... If you trust a blind man to lead you, $n, then listen. In the bluffs of Orgrimmar, west of the wind rider tower, lives Zankaja. She waits for the return of her mate.$b$bGo to her.",objectives={"Speak with Zankaja in Orgrimmar."}]])
R(1509,"多格蘭的消息",[[description="My mate, Dogran, was recently sent to the Crossroads for duty. It was a promotion, and he was very proud.$b$bI was sad, of course, but I didn't let him know that. And worried, too. The Barrens is a more dangerous place than Orgrimmar, and I feared the worst.$b$bNow it's been a week after he should have returned, and I have received no word from him...$b$bPerhaps you could go to the Crossroads and see if they have any news? He worked with Gazrog, who should still be stationed there.",objectives={"Speak with Gazrog at the Crossroads."}]])
R(1510,"多格蘭的消息",[[description="他是在陶拉祖營地被抓住的。我們當時正在和那裡的野豬人交戰，他帶了一小隊步兵去進攻野豬人的一處營地，但他在那場戰鬥裡受了重傷。其他戰士殺出重圍，然後想要回去救他，但多格蘭的情況很糟糕，他的傷口已經潰爛了，所以他們覺得要是不能先把他治好再帶出來的話，他可能就會因為傷筋動骨而死掉。$b$b所以他們和這裡聯絡了一下，希望能從石爪山的瑪拉卡金那裡的食人妖手裡討些傷藥來。我們已經派人去找食人妖們了，但他們至今還沒有回覆我們。",objectives={"找到瑪拉卡金的肯茲格拉並和他談話。"}]])
R(1511,"肯茲格拉的傷藥",[[description="I figured there might be another coming to get the draught, so I prepared it anyways.$b$bHere you go, $n. Mind you, you should only give half of it to him! That will give him enough strength to move without bleeding himself dry. Wait a night, then give him the other half.$b$bAnyways, you'll want to bring this to Logmar at Camp Taurajo. From what the first one told me, he should have an idea where this Dogran is.",objectives={"Bring Ken'zigla's Draught to Grunt Logmar at Camp Taurajo."}]])
R(1512,"愛的禮物",[[description="Zankaja is young and beautiful. To be chained to an invalid... I will not allow her to suffer that injustice.$b$bLeave me, $n. And thank you. I may end my life in glorious battle, instead of a lifeless husk.$b$bAnd please, I would ask you not to tell my mate of this... I do not want guilt on her conscience.",objectives={"Bring the Dirt-caked Pendant to Gan'rul Bloodeye in Orgrimmar."}]])
R(1513,"誓縛",[[description="Take this to the summoning circle in Neeru's tent, $n. Summon forth a foul succubus, then show it your mastery. I believe in the strength of your magic. As always, though, be wary, for pride and overconfidence has overcome many a promising warlock.$b$bWhen you have defeated it, return the pendant to me so that I might deliver the news to Zankaja.",objectives={"Using Dogran's Pendant, summon and subdue a succubus, then return Dogran's Pendant to Gan'rul Bloodeye in Orgrimmar."}]])
R(1514,"被腐化的迎風花")
R(1515,"多格蘭之囚",[[description="You've made it this far, so if you want to see this through to the end, I won't stop you. I can't spare you any additional manpower though, you'll be on your own.$b$bDogran is being held in a quilboar camp to the north of here. Look for a group of two huts. He'll be heavily guarded--that is, if they haven't killed him yet, or he hasn't succumbed to his wounds.$b$bGood luck.",objectives={"Bring Ken'zigla's Draught to Dogran in the Barrens."}]])
R(1516,"大地的召喚",[[description="是時候了，年輕的$c。你的肉體已經足夠強壯，而你的精神也已如大地一般堅韌。你選擇了遵循薩滿之道，這代表著你擁有無可置疑的睿智。$B$b讓大地來指引你的命運，讓它成為你的一部分吧。但你必須自己去面對大地的力量，如果你已經準備妥當，你就會看見一些只有薩滿才能理解的事物。$B$B去北邊去搜尋那些地獄捕獵者，給我帶一對它們的蹄子回來，然後我們再來好談談你的未來。",objectives={"帶2隻地獄捕獵者的蹄子給試煉谷的坎納甘·地鳴。"}]])
R(1517,"大地的召喚",[[description="A sapta is a drink created to bind our spirits to the elements. Fused with magic, the potion will allow the strong willed to see the elements as no one else can. Your spirit will be connected to the element the sapta was created for, and only a select few shaman know the recipe.$B$BThe sapta is always drunk in a holy place, and never anywhere else--remember that.$B$BSeek out Spirit Rock southwest of here--it is found at the end of the Hidden Path. Drink your sapta there, and... well, you shall see.",objectives={"Find Spirit Rock and drink the Earth Sapta."}]])
R(1518,"大地的召喚",[[description="Take this rough quartz from me and bring it to Canaga Earthcaller as proof of our meeting. He will craft a totem for you, and this pebble will be the heart of it. As small as it may seem, you will come to find that size does not matter, and that even the smallest of things can outlast many others.$B$BBe patient, $N. Remain strong. And seek wisdom. This is what earth asks of you. In the end, you shall become one with the earth--respect it as it shall respect you.",objectives={"Bring the Rough Quartz to Canaga Earthcaller in the Valley of Trials."}]])
R(1519,"大地的召喚",[[description="是時候了，年輕的$c。你的身體已經夠強壯，你的精神如大地一般堅韌，這正是你已經成熟的標誌。$B$B大地引領並教導著我們的族人，以後你也將得到它的指引。但在那之前，你必須先通過試煉。在你完成了試煉之後，就會看到那些只有我們才能看到的東西。$B$B往東邊去，找到刺背野豬人的薩滿，把他們在儀式中使用的藥膏拿回來一些。在你得到了足夠的藥膏之後再回來向我覆命。",objectives={"給納拉其營地的鴉羽先知帶回2份儀式藥膏。"}]])
R(1520,"大地的召喚",[[description="A sapta is a drink created to bind our spirits to the elements. Fused with magic, the potion will allow the open minded to see the elements as no one has seen them before. Your spirit will forever be tied to the element the sapta was created for, and only a select few of our kind know the secrets of its creation.$B$BThe sapta is always imbibed in a holy place, and never anywhere else.$B$BSeek out the shaman shrine to the east of here and drink of the sapta.",objectives={"Find Kodo Rock and drink the Earth Sapta."}]])
R(1521,"大地的召喚",[[description="Take this rough quartz from me and bring it to Seer Ravenfeather as proof of our meeting. She will craft a totem for you, and this pebble will be the heart of it. As small as it may seem, you will come to find that size does not matter, and that even the smallest of things can outlast mountains.$B$BBe patient, $N. Remain strong. And seek wisdom. This is what earth asks of you. In the end, you shall become one with the earth--respect it as it shall respect you.",objectives={"Bring the Rough Quartz to Seer Ravenfeather in Camp Narache."}]])
R(1522,"火焰的召喚",[[description="Fire be witcha, mon. I see you be strong in da ways of earth already, an' me tinkin' you be ready to talk to Kranal.$B$BKranal live north of da Crossroads in da Barrens. He be strong in da ways of da elements and can teach ya da ways of fire... if you tink you be ready.$B$BHe be easy ta find, just don' go too far--ya go too far an' ya find yerself in da elves' lands.",objectives={"Find Kranal Fiss in the Barrens."}]])
R(1523,"火焰的召喚",[[description="Long has it been since you were last tested, $N. You have shown patience thus far in your studies, but the time has come for you to learn more. The time has come for you to learn about destruction... and chaos. The element of fire is yours for the understanding, if you're prepared to pay for it.$B$BSeek out Kranal Fiss in the Barrens. He lives in a small dwelling north of the Crossroads, but be mindful, if you've reached the night elf lands, you've gone too far.",objectives={"Find Kranal Fiss in the Barrens."}]])
R(1524,"火焰的召喚",[[description="You are powerful enough to wield the totem of fire, but that does not mean you are ready.$B$BAlong the Southfury River in Durotar, before the Great Sea, lies a hidden trail to one of the highest peaks in the land. Find your way to the top and you shall find one of our holy shrines watched over by Telf Joolam--the Shrine of the Dormant Flame.$B$BTake this torch to him--it marks that you attempt to tame fire. Return it to me aflame by the brazier at the shrine and I will see you are given the totem of fire.",objectives={"Bring the Torch of the Dormant Flame to Telf Joolam in Durotar."}]])
R(1525,"火焰的召喚",[[description="But you did not come here for a history lesson, did you? You came for the Eternal Flame and fire totem.$B$BThe first step is to create a sapta and bind you to the flame.$B$BI can create the fire sapta for you if you bring me two items. The first is fire tar, a simple item usually carried by Razormane spellcasters in eastern Barrens.$B$BThe second item will be more dangerous: a reagent pouch from one of the cultists of the Burning Blade. You can find them in a cave above the ravines northeast of Razor Hill.",objectives={"Bring 1 Fire Tar and 1 Reagent Pouch to Telf Joolam in Durotar."}]])
R(1526,"火焰的召喚",[[description="The fire sapta is finished. The time has come for you to face the flame. Use the sapta at the shrine and head to the top of the mountain to face the manifestation there. He will not attack until you are ready, but he will realize you are able to see him.$B$BStrike him down swiftly, $N, for he shall only grow in power the longer you take to slay him. Once he is defeated, place his glowing embers within the brazier and light the torch.",objectives={"Defeat the Minor Manifestation of Fire, and place the Glowing Ember in the brazier atop the Shrine of Eternal Flame."}]])
R(1527,"火焰的召喚",[[description="Torch firmly in hand, you turn away from the brazier and look out over Durotar. You feel an excitement tugging at your spirit as the wind picks up and forces the flame to dance violently.$B$BYou start off down the path back to the Barrens in search of Kranal Fiss.",objectives={"Bring the Torch of Eternal Flame to Kranal Fiss in the Barrens."}]])
R(1528,"水之召喚",[[description="Water be in ya future, mon. I see you be strong in da ways of fire already, an' me tinkin' you be ready to talk to Islen.$B$BIslen live along the coast of da Barrens. If ya head south along the Southfury River, ya canna miss her--look fer da big shark! She be strong in da ways of da elements and can teach ya da ways of water... if you tink you be ready.$B$BShe be easy ta find, just don' go too far south--she be jus' beyond Ratchet.",objectives={"Find Islen Waterseer in the Barrens."}]])
R(1529,"水之召喚",[[description="Long has it been since you were last tested, $N. You have shown patience thus far in your studies, but the time has come for you to learn more. The time has come for you to learn about the purity of water.$B$BSeek out Islen Waterseer in the Barrens. She is along the eastern coast, south of the Southfury River and Ratchet. You will find her there at her fishing hut. Good luck to you, $N.",objectives={"Find Islen Waterseer in the Barrens."}]])
R(1530,"水之召喚",[[description="If there is one lesson you must learn of water, it is this: water means rebirth.$B$BIts power flows, erodes, and makes clean all manner of things. You will find its ability to heal and replenish incomparable, but only when it is pure.$B$BWhen you understand that water, when polluted, can devastate all that it touches, you will appreciate how vital a resource it is.$B$BIf you wish the water sapta, find Brine deep in Southern Barrens. Her home is continually molested by the quilboar there.",objectives={"Find Brine in Southern Barrens."}]])
R(1531,"空氣的召喚",[[description="You be makin' headway now, mon. Your be ready to prove yerself worthy of the air totem, but first, ya must fin' Prate Cloudseer in Thousand Needles. She be willin' ta tell ya how to get yer air totem if ya treat her wit enough respect.$B$BHead south through the Barrens, and after ya reach Thousand Needles, head east. You'll find her hiddin' in a hole wit' her boyfriend--haha, don' tell her I be dissin' her none--she not take it too kindly.",objectives={"Find Prate Cloudseer in Thousand Needles."}]])
R(1532,"空氣的召喚",[[description="The winds of Kalimdor rush to meet you and you shall be counted among some of our most powerful $g brothers:sisters;. I am proud to see you have come this far and have such a promising future.$B$BThe element of air is a difficult one to control, but I have faith that your skills will overcome any obstacles that are placed in front of you.$B$BHead to the very south of the Barrens, and enter Thousand Needles. It is there, far to the east, that you will find Prate Cloudseer. She will teach you more.",objectives={"Find Prate Cloudseer in Thousand Needles."}]])
R(1534,"水之召喚",[[description="Take this waterskin and head deep into the lush forest the night elves call Ashenvale. It is to the far north of the Barrens.$B$BOnce you've entered the forest, travel west. Along the mountains that separate Stonetalon and Ashenvale, and beyond Lake Mystral, you will find a holy place: the Ruins of Stardust. At the center of the lake you will find a small fountain.$B$BBring me a sample of the fountain's water. It will be the final component you'll need before I send you back to Islen.",objectives={"Fill the Empty Blue Waterskin at the Ruins of Stardust in Ashenvale and return to Brine in the Barrens."}]])
R(1535,"水之召喚",[[description="To find understanding and gain the sapta from me, you must seek out only the purest forms of water. As you fetch the samples for me, take note of your surroundings. Be aware of the creatures that rely on the water, that protect it. See how it affects forests and deserts. Witness how the very substance that sustains life will force creatures to take lives.$B$BWe shall start with a simple task: down below my hut there is a pond of the precious liquid. Fill this skin with it and return to me.",objectives={"Fill the Empty Brown Waterskin at the watering hole below Brine's hut and return it to her in the Barrens."}]])
R(1536,"水之召喚",[[description="Long ago I followed some companions into the Hillsbrad Foothills. We defended ourselves from some tenacious humans who make their home there and we found ourselves in a small town the Forsaken had taken over: Tarren Mill.$B$BIt was there I found a most peculiar thing: in the center of town was a small well of fresh spring water. I'm not sure the plagued citizens of the town even realize its value--it's a small holy vestige in an unhallowed sea.$B$BBring me a sample of that water in this waterskin.",objectives={"Fill the Empty Red Waterskin at the well in Tarren Mill and return to Brine in the Barrens."}]])
R(1558,"巨石水壩",[[description="Ironforge is where all the dwarves and gnomes live.  Near there is a place called Loch Modan, and the dwarves built a HUGE dam there.  They say it's one of the biggest things anyone's ever made.  Wow!$B$BCould you take me to Loch Modan and see the dam there, please?  I think it is the Stone... um... Stonewrench Dam?  Stonewrought?  It's big - that's for sure.  I'd like to look out over the big waterfall.  I promise I won't lean over too far!",objectives={"Take the orphan to the Stonewrought Dam in Loch Modan.  You should take him to the middle of the dam so he can see out over the giant waterfall."}]])
R(1559,"閃光彈的制法")
R(1560,"圖加的任務",[[description="我走丟了！$b$b我的妻子托爾塔讓我出來找晚餐，我一定是迷了路！$b$b你能行行好帶我回到托爾塔身邊嗎？她正在熱砂港南部等我。",objectives={"把圖加帶回到他的妻子托爾塔身邊。"}]])
R(1578,"前線的補給",[[description="The mountaineers of Loch Modan are fighting troggs, and having a busy time of it!  They need constant supplies of new armor and weapons if we're ever to get a handle on those troggs.$B$BThat's why my colleague Thorvald is there, trying to keep the mountaineers in good gear.  So if you were to make some copper axes and copper chain belts and bring them to Thorvald, he would be obliged.  He might even share his knowledge with you.$B$BThorvald is in Loch Modan's southern guard tower.",objectives={"Bring 6 Copper Axes and 6 Copper Chain Belts to Thorvald in the southern guard tower of Loch Modan"}]])
R(1579,"小齒輪",[[description="I came to Auberdine because of the quiet.  I want to invent my inventions where it's quiet, because after a night of drinking I don't like all the noise of Ironforge!$B$BSo I took a ship to Auberdine and had a little too much to drink on the way.  I dropped my box of gaffer jacks overboard!  I need my gaffer jacks!$B$BI don't know exactly where I dropped them, but if you fish for them in the ocean you might get lucky...",objectives={"Bring 8 Gaffer Jacks to Wizbang Cranktoggle in Auberdine."}]])
R(1580,"導電器",[[description="We know you're lucky, but... just how lucky are you, $N?$B$BOne night I was wandering the roads of Darkshore.  I was looking for a good river or lake to try my new self-propelled, exploding duck decoy and I think I was a little tipsy... because I passed out and awoke hours later in Auberdine.  My hair was singed and my bag of electropellers was gone!  I must have dropped them in the water!$B$BI need those electropellers!  Maybe you can fish them out of some lake or stream in Darkshore...",objectives={"Bring 12 Electropellers to Wizbang Cranktoggle in Auberdine."}]])
R(1581,"刃葉的藥劑",[[description="Our herb and alchemy shop is booming, but my husband spends so much time mixing potions that we never have time for each other.$B$BCan you help us?$B$BIf you can bring me a supply of pre-made elixirs, then I would be happy to trade with you.  I have some rare herbs that you might find useful.",objectives={"Bring 6 Elixirs of Lion's Strength and 2 Elixirs of Minor Defense to Syral Bladeleaf in Dolanaar."}]])
R(1582,"月光外衣",[[description="We in Darnassus, especially we craftsman, are quite busy.  Young adventurers are eager to test themselves in the wilderness, and are in constant need of supplies.$B$BIf you can help me fill my orders of leather goods, then perhaps I can teach you an advanced leatherworking technique.",objectives={"Bring 1 Embossed Leather Glove, 5 Embossed Leather Boots and 5 Embossed Leather Cloaks to Lotherias in Darnassus."}]])
R(1598,"失竊的典籍",[[description="嘿，說你啊！你叫$n，沒錯吧？$b$b我希望你確實想要成為一名術士，如果你不能執著於自己的信念的話，那你就可能會徹底迷失自我。$b$b我會指引你，但我要先確定你是否具有資格。$b$b不久前有一個在修道院中修行的學徒逃了出去，加入了迪菲亞兄弟會。為什麼我會對這個如此介意呢？是這樣的，他偷走了一些重要的典籍。$b$b其中有一本正好還是我很想要的，書名叫《虛空靈能》。你去把它偷回來給我，盜賊們應該把這些書藏在他們農場中的帳篷裡了。",objectives={"為杜希拉·拉薩雷找回《虛空靈能》。"}]])
R(1599,"開端",[[description="You must be the new warlock everyone's been whispering about. Must be someone's taken a liking to you if they've asked me to take time away from my research to start your training.$b$bDon't worry, I won't hold it against you.$b$bThe simplest of the summoning spells you will learn is that of the imp. Before I impart this to you, however, you must prove that you have the necessary magical and physical ability.$b$bBring me three feather charms from the frostmane novices from the cave to the southwest.",objectives={"Bring 3 Feather Charms to Alamar Grimm in Anvilmar."}]])
R(1618,"赤脊山的補給",[[description="We dwarves aren't the only ones fighting.  Our human allies have their hands full too!$B$BRedridge is under periodic attack from blackrock orcs, and their supply of equipment is always low.  If you were to help them out, I'm sure their resident blacksmith, Verner Osgood, would teach you a trick or two.",objectives={"Tormus Deepforge  wants you to bring 4 Runed Copper Belts and 4 Heavy Copper Mauls to Verner Osgood in Redridge."}]])
R(1638,"戰士的訓練",[[description="You've shown yourself to be a competent warrior, $N.  But you're still young and have a lot to learn.$B$BSpeak with Harry Burlguard--he's usually in the Pig and Whistle tavern, in the Old Town of Stormwind.  Harry is an old veteran and a good teacher.  He can show you a few moves that'll keep you breathing longer.",objectives={"Speak with Harry Burlguard."}]])
R(1639,"醉鬼巴特萊比",[[description="Yeah, I can teach you.  But first I wanna see what moves you have already.$B$BSee that drunk over there at the end of the bar?  Bartleby?  I want you to get his mug.$B$BHah, and if you know Bartleby then you know he won't just give it to you.",objectives={"Speak with Bartleby."}]])
R(1640,"擊敗巴特萊比",[[description="You want what??  You're crazy!$B$BThe only way you'll get this mug is if you pry it from my cold, dead fingers...",objectives={"Beat Bartleby, then talk to him."}]])
R(1641,"聖潔之書")
R(1642,"聖潔之書",[[description="無論在什麼時候，聖騎士都必須嚴格地遵循聖光之道，因為它是我們力量的源泉。對我們聖騎士來說，為了追求聖潔而苦修並不意味著我們是為了神格而努力—我們的目標是要在各方面都努力完善。$B$B雖然和邪惡鬥爭是眼前的當務之急，但是你必須牢記，只有無私地幫助他人才會讓你和艾澤拉斯的人民真正有所區別。同情、耐心、勇敢—這些品德對聖騎士而言，和戰鬥中所表現出來的力量一樣重要。$B$B記住這點，永遠不要忘記。",objectives={"與暴風城的達索瑞恩·拉爾談話。"}]])
R(1643,"聖潔之書",[[description="你接下來的任務，$N，就是要在暴風城裡找到一個需要幫助的人，一個心靈純潔動機單純的人。也許是某個樂於幫助別人的人，也許是某個需要指引的人。不管怎樣，這個人必須心地高尚，而且需要你的幫助。$B$B完成這件事之後回來這裡，那時我們再來討論關於你的修行之道，以及成為光之聖騎士的意義。",objectives={"到暴風城的貿易區找尋斯蒂芬妮·特納。"}]])
R(1644,"聖潔之書",[[description="願聖光護佑那些孩子，他們大多因為幾年前那次天譴軍團的襲擊而失去了家庭。$B$B我丈夫約翰為我收集給孩子們做衣服褲子的布料，不過我沒時間做，因為我得成天忙著照顧他們的飲食起居。$B$B什麼？你願意幫忙？讚美聖光，也感謝你，好心的$N。$B$B如果你能給我找點亞麻布來的話,我就能給孩子做衣服了，那可真是幫了我的大忙。",objectives={"給暴風城的斯蒂芬妮·特納收集10塊亞麻布。"}]])
R(1645,"聖潔之書")
R(1646,"聖潔之書",[[description="In all things, a paladin must reflect the Light which supplements our strength. To strive to be divine for one of our kind does not mean we strive for godhood--we strive to be good in all actions.$B$BAlthough called upon to smite evil in these harsh times, you must always remember that it's aiding others that will truly set you apart from the citizens of Azeroth. Compassion, patience, bravery--these things mean as much to a paladin as strength in battle.$B$BKnow this well, and never forget it.",objectives={"Speak to Tiza Battleforge in Ironforge."}]])
R(1647,"聖潔之書",[[description="Your task then, $N, is to find someone here in Ironforge that is in need of aid. Someone who is pure of heart and motive. Perhaps someone helping others. Perhaps someone in need of a guide. Regardless, the person must have noble intent and be relying on your kindness.$B$BDo this, and return to me when you are finished. Then, we shall discuss more of your path and what it means to be a paladin of the Light. I will remain here in the temple for your return. Other paladins will need my guidance also.",objectives={"Search the outer ring of Ironforge for John Turner."}]])
R(1648,"聖潔之書",[[description="My wife and I run an orphanage in Stormwind, mostly for children who have lost parents due to the attacks by the Scourge in the last decade. I come to Ironforge every month or so to see about collecting more supplies from the citizens here, and talk to the various groups to see if they can do anything to help.$B$BThis trip's been agonizingly slow, and not very productive.$B$BIf I could just get some more linen for my wife to make some clothes, I could finally send a shipment home.",objectives={"Bring 10 Linen Cloth to John Turner in Ironforge."}]])
R(1649,"勇氣之書",[[description="Valor, and all the virtues that go along with it, are like rare minerals: you must cherish them when you find them because of their value, but you must also take time to harvest them... refine them. When mixed together properly, a strong alloy is formed, sometimes unbreakable by even the most powerful blows.$B$BThis strength, your faith, your bravery, must be tested. You must learn to never lose faith and realize that with the power of the Light, you can overcome things that most others cannot.",objectives={"Speak to Duthorian Rall in Stormwind."}]])
R(1650,"勇氣之書",[[description="很好！你對此表現出來的毫不猶豫可以清晰地佐證：你已經準備好了，並渴望著進行試煉。那麼，去吧。$B$B在西部荒野的長灘最南端的盡頭，有一處臨海而建的小屋。屋裡住著一對名叫斯迪威爾的夫婦。丈夫喬丹·斯迪威爾是一位技藝精湛的鐵匠，他暫時去鐵爐堡會見他的矮人朋友們了。於是他那無依無靠的妻子達芙妮目前一個人在家裡待著。$B$B根據線報，迪菲亞兄弟會幾乎已經完全控制了那片地區，勢單力薄的達芙妮或許需要一位元勇士的保護。去吧。",objectives={"在西部荒野找到達芙妮·斯迪威爾。"}]])
R(1651,"勇氣之書",[[description="我敢打賭，他們馬上就要再殺過來了，你最好有所準備。$B$B我在屋裡放了一把槍，我會用它來幫你的，不過可別太指望我了，最終你還是得靠自己。$B$B我不知道他們來了多少人，但我敢肯定會比先前來的要多。$B$B祈禱聖光保佑你和我吧，因為……你聽到腳步聲了嗎？他們來了！$B$B準備戰鬥！",objectives={"在迪菲亞兄弟會進攻時保護達芙妮·斯迪威爾的安全。$B$B如果你想成功的話，你和達芙妮都不能死在他們的劍下。"}]])
R(1652,"勇氣之書",[[description="拜託你，請回到達索瑞恩那裡，轉告訴他我現在已經安全了，我一定要好好感謝你和教會。$B$B他會派人給正在鐵爐堡的喬丹帶份口信，讓他不要擔心我。啊，我是多麼想念他呀……我都等不及想見他了。",objectives={"與暴風城的達索瑞恩·拉爾談話。"}]])
R(1653,"正義試煉",[[description="事實上，我想喬丹本人會非常感謝你的。我正準備找人給他送個信，讓他知道他的妻子目前很安全，我想你就是個合適的人選。$B$B喬丹原本可以成為一名為聖光而戰的聖騎士，不過後來為了繼承他父親的手藝走上了另一條路——他對我們的生活方式非常熟悉，也是我們最忠實的朋友。$B$B他應該還在鐵爐堡，白天的時候，喬丹喜歡在室外工作，比如在山裡呼吸新鮮的空氣。",objectives={"去和鐵爐堡的喬丹·斯迪威爾談話。"}]])
R(1654,"正義試煉",[[description="如果你願意接受獎賞的話，我會給你獎賞的。請不要誤會，我的慷慨取決於你能給我多少幫助，不過這樣的同盟關係對你我都有好處。$B$B我可以為你製作一把配得上你的成就的武器，一把象徵著聖騎士的精神和聖光的武器，不過首先，你要給我找到製作這把武器所需的材料。我已經列出了所需的材料，現在得有一個勇敢能幹的人去找到它們。你願意去完成這個任務嗎，$n？",objectives={"按照喬丹的武器材料單上的說明去尋找一些白石橡木、精煉礦石、喬丹的鐵錘和一塊科爾寶石，然後回到鐵爐堡去見喬丹·斯迪威爾。"}]])
R(1655,"白洛爾的礦石",[[description="Ach, ya startled me, $G man:woman;! Can't ya see I was lost in thought?$B$BWhat's that? Jordan's shipment... fer Ironforge. Ahhh, yeah, I know whatcha speak of. Mo'grosh ogres... dat's who took me ol' friend's ore shipment. Caravan was headin' here from the Wetlands and was ambushed. The guard who survived their attack just passed away a few days ago--healer couldn't get to 'em fast enough.$B$BIf you want the shipment, you'll have to head northeast across the Loch. It's got to be there somewhere.",objectives={"Bring Jordan's Ore Shipment to Bailor Stonehand in Loch Modan."}]])
R(1656,"未完的任務",[[description="拜託，$N，求求你了，幫我一個忙吧！我正在完成我的力量儀祭，但父親又要求我將這些皮毛送到血蹄村的旅店。$B$B我實在分不開身去同時完成儀祭和父親交付給我的任務。你……能不能替我跑一趟？$B$B在長途旅行之後，旅店可是個休息的好地方。我敢說你到了那裡之後也會同意的。",objectives={"將一捆毛皮帶給血蹄村的旅店老闆考烏斯。"}]])
R(1657,"臭氣熏天的南海鎮",[[description="Celebrate Hallow's End in style... by bringing grief to our enemies in Southshore!$B$BTake one of these specially crafted stink bombs.  It is filled with an odiferous funk that no human - or any weak-willed beast for that matter - can stand to smell.  You'll need to throw it right in the heart of Southshore for it to do its job, so be prepared for a fight against the Alliance!$B$BWhen you've completed this task... this tribute to our liberation, return to me!",objectives={"Toss three Forsaken Stink Bombs into the heart of Southshore in Hillsbrad, and return to Darkcaller Yanka at the Wickerman Festival in Tirisfal Glade."}]])
R(1658,"稻草人的節日",[[description="I need brave individuals to head up to Tirisfal Glade and check out the Wickerman Festival.  I'm not going to lie - heading up there will be dangerous.  The guards at the festival will be exceptionally vicious.  Still, we need to know how big the festival is this year, and how much trouble the Forsaken are going to cause us during Hallow's End.$B$BIf you're up for it, head to Tirisfal and scout out the festival.  Return to me with the information, and I'll make sure you're well compensated.",objectives={"Locate the Forsaken's Wickerman Festival in Tirisfal Glade.  Return to Sergeant Hartman in Southshore once you've done so."}]])
R(1659,"<UNUSED>")
R(1660,"<UNUSED>")
R(1661,"高貴之書",[[description="I greet you once again, $N. I am more proud to call you $g brother:sister; than ever before--your dedication is a tribute to us all.$B$BThe time has come for me to bestow a great gift upon you. But know this, for now I give you this freely, but later, when time permits, this will be a much greater challenge to all paladins who choose to undertake my quest.$B$BSpeak to me again and I shall grant you a great boon.",objectives={"Speak to Duthorian Rall in Stormwind."}]])
R(1665,"巴特萊比的酒杯",[[description="Ok, here's my mug.  Wait!  Let me finish what's in it first... there we go.",objectives={"Bring Bartleby's Mug to Burlguard"}]])
R(1666,"治安官哈迦德",[[description="You've learned a few moves, but you could still use a decent weapon.  I bet if you spoke with Marshal Haggard he could help you.$B$BMarshal Haggard lives in a manor in Elwynn Forest, at the Eastvale Lumber Camp.  He's retired now but he collected a lot of gear during his career.$B$BLet him know I sent you, and with luck he'll have a spare weapon to offer.",objectives={"Speak with Marshal Haggard."}]])
R(1667,"蛀牙傑克",[[description="Burlguard sent you, did he?  Yes, I have spare weapons around here, but first I have a task for you...$B$BA while ago a Defias villain Dead-tooth Jack tricked me.  It was dark and he was wearing a Stormwind tabard and I thought he was Marshal Dughan.  He said he needed my old Stormwind Marshal's badge and I gave it to him... and then he laughed and ran off before I could catch him!$B$BGet back my badge!  Dead-tooth Jack probably has it stowed in his camp to the south.",objectives={"Retrieve Haggard's Badge from Dead-tooth Jack's camp, and return to Marshal Haggard."}]])
R(1678,"維吉雷克",[[description="If you want to rise in the ranks of the warriors, then you better be tough.  I can teach you new moves but before that, prove to me you can handle yourself against real foes.$B$BVejrek is the toughest troll you'll find in these parts, and he's who you have to beat.  He has a hut in the foothills just south of Frostmane Hold$B$BBring me Vejrek's head and I'll know you have mettle.",objectives={"Bring Vejrek's Head to Muren Stormpike in Ironforge."}]])
R(1679,"穆倫·雷矛",[[description="Hello, warrior!  You show a lot of promise, but you still need to learn some tricks and Muren Stormpike is just the dwarf to teach you.$B$BYou can find Muren at the Hall of Arms in the Military Ward of Ironforge.  Talk to him when you're ready to learn what it is to be a warrior.",objectives={"Speak with Muren Stormpike."}]])
R(1680,"托姆斯·深爐",[[description="Now that you've learned some moves, it's time to get you a decent weapon.  Speak with Tormus Deepforge.  He can make you a weapon I'm sure you'll like.$B$BYou'll find Tormus here in Ironforge, at the Great Forge.",objectives={"Speak with Tormus Deepforge."}]])
R(1681,"鐵環營地",[[description="My mentor, Sturgy Ironband, had a compound south of Helm's Bed Lake in eastern Dun Morogh.  There he taught blacksmithing and he was the best.$B$BBut one day, one of his students brought him a load of strange ore.  Master Ironband called it umbral ore and was eager to work with it, but soon after it arrived... a band of Dark Iron dwarves attacked his compound.  They killed everyone!$B$BEnter Ironband's compound, $N, and avenge my master's death.  And bring me the load of umbral ore that caused it.",objectives={"Bring a load of Umbral Ore to Tormus Deepforge in Ironforge."}]])
R(1682,"灰鐵武器")
R(1683,"沃魯斯·邪蹄",[[description="Before I can teach you, you must show me your resolve.$B$BThe satyr Vorlus Vilehoof has found one of our remote moonwells, southeast of the Ban'ethil Barrow Den.  He now splashes within it, defiling its pure waters with his filth.$B$BFind Vorlus at the moonwell and destroy him.  Bring me his horn as proof and I will begin your advanced training as a warrior.$B$BThe path to the moonwell is hidden well, $N, but stay focused and alert and you will find it.",objectives={"Bring the Horn of Vorlus to Elanaria in Darnassus."}]])
R(1684,"艾蘭娜瑞",[[description="Greetings, warrior.  Your skill grows, but there is more to your profession than you may believe.  To further progress, you must soon find a teacher.$B$BThe warrior Elanaria dwells in Darnassus, at the Warrior's Terrace.  She can instruct you.",objectives={"Speak with Elanaria."}]])
R(1685,"加科因的召喚",[[description="Isn't that how it always works? Was looking for you all day and couldn't find you, now when I'm not expecting it, you come and walk right up to me.$b$bI've wasted enough time trying to find you, so I won't delay you any longer. Master Gakin's summoned you for additional training. Seems to me you should seek him out as soon as possible.$b$bYou'll find him in the basement of the Slaughtered Lamb tavern. By the way, you might want to keep that particular location quiet. Don't want word spreading about it.",objectives={"Report to Gakin the Darkbinder in the Mage Quarter of Stormwind."}]])
R(1686,"艾魯拉的陰影",[[description="You have learned much, $N.  Now we will craft you a weapon.  A warrior's weapon.$B$BTo do this, you must travel to Darkshore.$B$BLong ago a ship crashed upon the rocks near the Auberdine lighthouse, scattering many crates of elunite ore along the ocean floor.$B$BFirst, you must defeat the elunite's guardian, the Shade of Elura.  Once the ship's captain, she cursed herself to roam the deeps and protect her shipment for all time.  Defeat her, gain her medallion, and gather the crates of lost Elunite.",objectives={"Bring 8 loads of Elunite Ore and the Medallion of Elura to Elanaria in Darnassus."}]])
R(1687,"幽靈燈塔",[[description="Sometimes late at night, our matrons at the orphanage will tell us spooky stories.  Those RULE!  There's one about a ghost that haunts a lighthouse in Westfall.  They say he was a pirate captain who had his ship taken from him by other pirates.  Wow!$B$BCould you please take me to the lighthouse in Westfall?  I wanna see if the ghost of that captain is there!  I promise to stay close to you; I won't run off or anything!",objectives={"Take the orphan to see the lighthouse off the coast of Westfall."}]])
R(1688,"蘇倫娜·凱爾東",[[description="I had a student named Surena Caledon. She stood where you stand now, eager to learn of warlock magic, and possessing no small bit of talent. More than that she was young and pleasing to the eye. Had I seen it then, the traitorous trollop!$b$bThe thieving wench ran off with one of the Defias, Erlan Drudgemoor. While her loss is of little importance, I gifted her a bloodstone choker that I must have.$b$bHer life means nothing to me now. You will find her at the Brackwell Pumpkin Patch. Retrieve what is mine.",objectives={"Retrieve Surena's Choker for Gakin the Darkbinder in Stormwind."}]])
R(1689,"誓縛",[[description="By retrieving my choker and besting Surena, you've proven that you're at least as capable as she was.$b$bWith that said, I can tell you're direly in need of training. You can manage the flows of magic, yes, but being a warlock is much more than that.$b$bI will show you how to command a voidwalker, but before I can, you must call one forth at a summoning circle and subdue it using whatever weapons--physical and magical--you have at your disposal. Use the magic of this choker at the summoning circle below.",objectives={"Using the Bloodstone Choker, summon and subdue a voidwalker, then return the Bloodstone Choker to Gakin the Darkbinder in Stormwind."}]])
R(1690,"廢土的公正",[[description="你！是你出馬幫助加基森水業公司的時候了！$B$B那些廢土遊牧民幾乎佔據了塔納利斯沙漠上所有的水井！如果得不到這些水井的控制權，那我們的水源供應很快就會出現問題。如果你想幫助我們的話，就去解決那些該死的遊牧民吧！$B$B從這裡往東走，去幹掉10個廢土竊賊和10個廢土強盜，然後立即向我報告。你一定要為我們這些人……呃……哥布林們伸張正義啊，不管怎麼樣，快點行動吧！",objectives={"去加基森的東面殺掉10個廢土竊賊和10個廢土強盜，然後向總工程師比格維茲覆命。"}]])
R(1691,"廢土的公正",[[description="現在我們需要你去對付那些更強大的廢土遊牧民。到現在為止你都表現得相當出色，但是如果我們想要奪回水井的話，那麼就必須要幹掉更多的遊牧民！$B$B這次，我要你去殺死他們的遊蕩者和刺客，還有暗法師。你可以在這裡的東南面找到這些傢伙。$B$B說實話，他們都很棘手。但是請你一定要幫忙，我們要取回屬於自己的東西！",objectives={"殺死10個廢土暗法師、8個廢土遊蕩者和6個廢土刺客，然後向加基森的總工程師比格維茲報告。"}]])
R(1692,"鐵匠瑪希爾",[[description="I have placed the elunite you gathered into a case.  Take it to the blacksmith Mathiel, and he will craft for you an elunite weapon.$B$BMathiel is to the south, on the other side of this building.",objectives={"Bring the Case of Elunite to Smith Mathiel. "}]])
R(1693,"月神武器")
R(1698,"猶魯斯·麥酒",[[description="Yorus Barleybrew has issued a challenge to all able warriors of the Alliance.  He waits at the Lakeshire Inn, in Redridge, and pledges a grand reward to anyone able to pass his trial.",objectives={"Speak with Yorus Barleybrew."}]])
R(1699,"往返瑞斯班洞穴",[[description="I call my challenge the Rethban Gauntlet.  To pass the trial, all you must do is enter the Rethban Caverns, to the first fork, then return here.  Easy!  Except there are a few wrinkles...$B$BYou have to return within an hour.$B$BThere are whole heaps of Redridge Gnolls in the way.$B$BBefore you start, you have to take a swig of my family's signature drink: Barleybrew Scalder!$B$BSo what do you say?  The Rethban Caverns are in the foothills north of Lakeshire.  Are you ready to run the Rethban Gauntlet?",objectives={"Enter the Rethban Caverns, reach the first fork, and return to Yorus Barleybrew within the time allowed.$B$BYou must not die and release your spirit."}]])
R(1700,"格瑞曼德·艾爾默",[[description="I made a copy of my notes on the techniques I learned while making your armor, and I need them sent to Grimand Elmore.  He's here in the Dwarven District, in the weapon shop.$B$BAnd duck when you give these to him.  He's fiercely proud of his skills, and won't like the idea of learning something from me...",objectives={"Bring Furen's Notes to Grimand Elmore."}]])
R(1701,"弗倫的鎧甲",[[description="我已經給了你一面精緻的盾牌，不過我們的合作決不會就此結束。我知道如何鑄造異常堅固的鎧甲，但是鑄造起來並不容易，我需要一些稀有的材料，只要你願意跑跑腿，我保證會為你打造一件。$B$B你覺得怎麼樣，$N？如果你願意接受挑戰的話，我會給你一份列表，上面記載著我需要的材料和到可以找到這些材料的地點。",objectives={"收集必需的材料，將它們交給暴風城的弗倫·長鬚。"}]])
R(1702,"鑄盾師",[[description="You really showed what you were made of when you ran the Rethban Gauntlet, $N.  And I'm true to my word.  I'll get you the reward I promised...$B$BExcept it's in Stormwind.$B$BTalk to my friend, Furen Longbeard, in the Dwarven District of Stormwind.  He's the best shieldsmith you'll ever meet, and he owes me a big favor.$B$BHere, take Furen this cask of Barleybrew Scalder and ask him for a shield.  He'll give you a nice one.",objectives={"Bring the Cask of Scalder to Furen Longbeard."}]])
R(1703,"瑪希爾",[[description="I made a copy of my notes on the techniques I learned while making your armor, and need them sent to the blacksmith Mathiel.  He lives in Darnassus which is quite a long way off, but I'm sure he'll be very grateful to learn what I've learned.",objectives={"Bring Furen's Notes to Mathiel."}]])
R(1704,"科羅莫特·鋼尺",[[description="I made a copy of my notes on the techniques I learned while making your armor, and need someone to take them to Klockmort Spannerspan.  He's a gnomish blacksmith in Ironforge and when he learns what I've learned... I bet he'll pull off his own beard in excitement.",objectives={"Bring Furen's Notes to Klockmort Spannerspan."}]])
R(1705,"燃燒之血",[[description="I hate to admit that Furen might have really found something.  But to be sure I'll need to try his techniques on a new piece of armor.  If you help me with the materials, $N, then you can have the armor.$B$BTo make this armor, I need samples of burning blood and a burning rock.$B$BThe only place I know to get them is Duskwood.  The Nightbane worgen based in the Roland's Doom mine have burning blood, and their leader Gutspill will have the rock.$B$BMay fortune grant you speed, $N.",objectives={"Bring 20 vials of Burning Blood and 1 Burning Rock to Grimand Elmore in Stormwind."}]])
R(1706,"格瑞曼德的鎧甲")
R(1707,"收集水袋",[[description="你好啊$n - 我叫魯葛蘭克，如果你想要找些事情做，我們這裡現在就有一件重要的工作給你！唷呼！$B$B沒有什麼能比幫我帶回一些廢土水袋來更能令我這個老傢伙開心的了。那可都是我們的水——就是那些流浪者把它們偷走了！你每給我帶回五個廢土水袋來，加基森水業公司就會獎勵給你一個正式的醫療包裹。更重要的是，你正在幫助加基森自助！",objectives={"收集5個廢土水袋，把它們交給加基森的魯葛蘭克。"}]])
R(1708,"鐵珊瑚",[[description="I want to try Furen Longbeard's new techniques on my own piece of armor.  And because you helped Furen and he helped me, you're welcome to the armor after I make it!$B$BTo finish the piece, I need a special coral, searing coral.  It grows in only one place--along the coast south of Menethil Harbor in the Wetlands.$B$BBring me enough searing coral and I'll get right to work on the armor.  And hurry, $N.  I'm so eager to get started it's making my toes twist!",objectives={"Bring 20 loads of Searing Coral to Klockmort Spannerspan in Ironforge."}]])
R(1709,"科羅莫特的成果")
R(1710,"曬焦的蛋殼",[[description="My colleague, Furen Longbeard, made a discovery which I am eager to test.  I wish to try it on a new armor that I am researching, for I believe Furen's techniques will produce superior results.$B$BWill you help me?  If you gather what I need to make the armor, then I will make an extra piece for you.$B$BI need the sunscorched egg shells of the Highperch Wyverns who dwell at Highperch, in Thousand Needles.  Search for the shells below their nests, and return to me when you have a sufficient amount.",objectives={"Bring 20 Sunscorched Shells to Mathiel in Darnassus."}]])
R(1711,"瑪希爾的鎧甲")
R(1712,"塞克隆尼亞",[[description="我幾十年來都在關注著這個地方。我關注著，希望有一天能看到強大的塞克隆尼亞被人擊敗。但迄今為止，我還沒有找到一個能打敗風之王的勇士。$B$B也許你就是那個勇士。$B$B證明給我看吧，給我找來召喚塞克隆尼亞所需的東西，這樣你就能證明自己是一個偉大的勇士。也許你能打敗他並奪得他的旋風之心。$B$B這樣的話，我將把這顆心的力量注入一把武器裡，供你在今後的冒險旅程中使用。$B$B這張羊皮紙上寫著我需要的東西。",objectives={"把巴斯拉的羊皮紙上列出的東西交給奧特蘭克的捕風者巴斯拉。"}]])
R(1713,"召喚",[[description="我已經準備好儀式要召喚塞克隆尼亞了。當他被召喚出來時，你必須打敗他，然後得到他的旋風之心。我將用它來把塞克隆尼亞的力量注入到一件武器中。$B$B$N，你準備好面對風之王了嗎？",objectives={"將旋風之心帶給捕風者巴斯拉。"}]])
R(1714,"流放精華")
R(1715,"已宰的羔羊",[[description="Hmph. Times past, all warlocks in Khaz Modan were trained under the auspices of the masters of Gnomeregan, but now that we've all been forced to relocate into this rat's hole in Ironforge, and Magni's decided to keep a careful watch on us, we're forced to send our novices to Stormwind for training.$b$bLuckily, Gakin's no slouch, so you'll still learn what you need to know, but it burns my blood!$b$bAnyways, you'll find Gakin in the basement of the Slaughtered Lamb in Stormwind.",objectives={"Report to Gakin the Darkbinder in the Mage Quarter of Stormwind."}]])
R(1716,"噬魂者",[[description="魅魔是靈魂的吞噬者，心靈的毀滅者，思想的控制者。她腦中永遠只有邪惡的念頭。$b$b這就是你現在要學會召喚並控制的生物，但在沒有誘餌的情況下，你是無法將她引入到我們的世界中來的。$b$b以一件象徵愛的事物作為誘餌，魅魔才會回應你的召喚。在這之後，你只有戰勝她才能將她變為你的工具。$b$b但是找到象徵著愛的東西可不容易，你最好和先知塔卡爾談談。他就住在卡林多大陸的貧瘠之地，靠近陶拉祖營地的地方。",objectives={"與貧瘠之地的先知塔卡爾交談。"}]])
R(1717,"加科因的召喚",[[description="$n! Didn't expect to see you around these parts, but I was instructed to keep an eye out for you.$b$bIt's past time you got some more training, so you should stop in to see Gakin the next time you're in Stormwind. He'll be waiting for you.",objectives={"Report to Gakin the Darkbinder in the Mage Quarter of Stormwind."}]])
R(1718,"島民",[[description="作為一名戰士，你的名聲越傳越響，$N。現在是時候讓你和其他戰士比試一下，看看你真正的實力了。$B$B在貧瘠之地的海岸附近有一座名叫勇士島的小島，就在棘齒城的南部，強大的戰士們時常在那裡聚會。$B$B他們在那裡相聚，然後互相切磋。$B$B去和勇士島的首席戰士克蘭諾克·馬克雷德談談吧。如果他認為你夠格的話，就會指引你在勇士的道路上更進一步的。",objectives={"和克蘭諾克·馬克雷德談話。"}]])
R(1719,"格鬥考驗",[[description="如果你想從我這兒學到什麼，你必須首先通過格鬥考驗。對於我們勇士島上的自認為勇猛而又躍躍欲試的戰士們來說，這是他們必須通過的挑戰，如果你能通過這個考驗，那麼你就證明了自己的價值。$B$B要開始接受考驗的話，就走到那邊人群中的鬥陣中央。圖維琪·弗拉海德會知道你已經準備好了，然後他就會派出挑戰者來對你進行考驗。$B$B在戰勝了所有挑戰者之後，他會叫出比格維爾。殺了比格維爾，在限定的時間內回到我這裡來覆命。",objectives={"殺掉比格維爾，然後向勇士島的克蘭諾克·馬克雷德回覆。"}]])
R(1738,"同心樹",[[description="In preparation for your coming, I used my sight to look over the world and through the mists of time. I have found what it is you seek.$b$bIn the War of the Ancients, two lovers fell together in battle. Where they took their last breaths, a tree known as the heartswood grew, a symbol of their undying love.$b$bThat should be enough to tempt a succubus. You will find it in the ruins of Ordil'Aran in the northwestern part of the forest of Ashenvale.",objectives={"Retrieve the Heartswood from Ashenvale and bring it to Gakin the Darkbinder in the Mage Quarter of Stormwind."}]])
R(1739,"誓縛",[[description="Using the heartswood core, you will be able to cast a spell at the summoning circle in the crypt below to open a portal for the succubus to pass through.$b$bBe careful, $n, succubi have overrun even the strongest of minds.$b$bOnce you have bested and returned it to the void, return to me and I will show you how to call and control it.",objectives={"Using the Heartswood Core, summon and subdue a succubus, then return the Heartswood Core to Gakin the Darkbinder in the Slaughtered Lamb."}]])
R(1740,"索蘭魯克寶珠",[[description="When demons of the Legion fall out of favor, their spirits are imprisoned within orbs and distributed to their mages and warlocks.$b$bMany were carried by their servants in Azeroth. Even fragmented, they still possess the powers of the demons trapped inside.$b$bThe orb of Soran'ruk was broken into two pieces, one was further broken to be used by the acolytes of the Twilight's Hammer in Blackfathom Deeps. The other, larger piece, was possessed by a wizard in Shadowfang Keep. Find them and I can reform it.",objectives={"Find 3 Soran'ruk Fragments and 1 Large Soran'ruk Fragment and return them to Doan Karhan in the Barrens."}]])
R(1758,"陰謀之書",[[description="It will take more than a simple summoning circle to bring forth a felhunter for you to challenge.$b$bMy three acolytes and I will assist in creating the magic circles. You require a copy of the Tome of the Cabal, which has been lost to us for some time. It was written by the first group of warlocks to summon a felhunter unaided.$b$bPerhaps Krom Stoutarm can help you with this. An itinerant warlock these days, he spends his days hoarding ancient texts and skulking about the library in Ironforge.",objectives={"Speak with Krom Stoutarm in Ironforge."}]])
R(1778,"聖潔之書",[[description="I'm going to see about making plans to return home soon. Hopefully, Stephanie is doing well back in Stormwind. I can't wait to see her again. Till next we meet, $c.",objectives={"Speak to Tiza Battleforge in Ironforge."}]])
R(1779,"聖潔之書",[[description="I want you to take this, $N. It is called the Symbol of Life.$B$BYou've proven charitable and patient, and now I want you to prove just how adept you've become in both combat, and power.$B$BMy husband Muiredon returned recently from an encounter with some Dark Iron dwarves, and he barely escaped with his life--he's over there having his wounds healed by one of our priests.$B$BTake the Symbol and speak to him. If you can help him, then we will speak again soon. May the Light shine upon you.",objectives={"Take the Symbol of Life and speak to Muiredon Battleforge in Ironforge."}]])
R(1780,"聖潔之書",[[description="我今天就把這些拿給孩子們。你要多加小心，好心的$n。城裡已經很難看到像你這樣樂於助人的$G紳士:女士;了，不過你已經證明了聖騎士決不會拒絕幫助那些陷入困境的人。$B$B請多保重。",objectives={"與暴風城的達索瑞恩·拉爾談話。"}]])
R(1781,"聖潔之書",[[description="拿著這個，$N。這是生命符記。$B$B你已經證明了自己的仁慈和耐心，現在讓我們看看你是否有能力掌握光明之道的一項最偉大的能力。$B$B我的朋友傑生最近剛從艾爾文森林的英雄崗哨回來，他在那裡遭遇了迪菲亞盜賊，差點就沒命了。現在他正在聖壇邊上接受牧師的治療。$B$B把這個符記帶給他，和他談談。如果你幫得了他，我們很快就能再見面了。願你永享聖光的榮耀。",objectives={"把生命符記帶給暴風城的傑生·坦諾姆。"}]])
R(1782,"弗倫的鎧甲")
R(1783,"聖潔之書",[[description="We was spyin' on some of the Dark Iron dwarves that've bunkered down south of Helm's Bed Lake. We knew they was up to no good, so Narm an' me thought we'd take a closer look--got ta see their leader given orders to some o' his men.$B$BNarm an' me took the chance to kill a few of 'em, but they proved tougher than we thought, an' more of 'em got the jump on us. Narm tol' me to run an' get support, so 'ere I am.$B$BNarm needs help, an' I'll not rest till he gets it.$B$BC'n ya help, $N?",objectives={"Take the Symbol of Life and resurrect Narm Faulk in Dun Morogh."}]])
R(1784,"聖潔之書",[[description="Before I fell in battle, Muiredon and I had almost defeated one of the Dark Iron spies near that small house. We witnessed their captain passing orders to them, and sought to kill him and take the orders.$B$BSome of the council in Ironforge do not yet believe the presence of Dark Iron dwarves exists in Dun Morogh. By attaining one of those scripts, we'll not only have proof of their movements, but possibly an idea of what they're planning.$B$BGet one of those scripts and take it back to Muiredon, $N.",objectives={"Retrieve a Dark Iron Script from the Dark Iron dwarves near Helm's Bed, and return to Muiredon Battleforge in Ironforge."}]])
R(1785,"聖潔之書",[[description="I c'n see me wife's o'er there beamin' wit pride already. Ya better get yer tuchus o'er there pronto. I be thinkin' she'd have some words wit ya.$B$BLight be witcha, mighty $c. I'll be lookin' fer ya on the battlefield against the Scourge and dem Dark Irons when the time comes.",objectives={"Speak to Tiza Battleforge in Ironforge."}]])
R(1786,"聖潔之書",[[description="亨茲和我去了英雄崗哨，那地方就在艾爾文森林東北的石碑湖中央的一座小島上。我們聽說迪菲亞盜賊在邊境一帶搞間諜活動，就受命去找到證據交給國王的顧問。$B$B我們看見兩個人在鬼鬼祟祟地閱讀什麼文件，就向他們發起了突襲。這時突然出現了很多法師將我們團團包圍。$B$B亨茲為我拖住了他們，讓我先逃脫了……這個傻瓜，他為什麼要那麼做……$B$B我的兄弟亨茲，他的屍體現在還躺在那裡。你能幫助我們嗎，$N？",objectives={"把生命符記帶到艾爾文森林的英烈碑去，復活亨茲·法奧克。"}]])
R(1787,"聖潔之書",[[description="我們以後再來談生命符記的事情吧，現在最重要的是把那份迪菲亞盜賊閱讀過的文件拿回來。如果能得手的話，我們就能證明迪菲亞盜賊混入艾爾文森林了，甚至還有可能瞭解到他們的計畫是什麼。$B$B你覺得你有能力把這些文件從這座小島上的迪菲亞盜賊手裡拿過來嗎？$B$B如果你拿到文件的話，就把它交給傑生，順便告訴他我現在沒事了。",objectives={"從石碑湖小島上的迪菲亞巫師手中拿到迪菲亞手稿，把它交給暴風城的傑生·坦諾姆。"}]])
R(1788,"聖潔之書",[[description="在達索瑞恩看過這份文件之後，我會把它交給國王的顧問，不過你現在應該去和達索瑞恩談談。他一定會表揚你的！$B$B再次感謝你，$N。我希望我們還能見面。有你這樣的朋友絕對是我的驕傲與榮幸。",objectives={"與暴風城的達索瑞恩·拉爾談話。"}]])
R(1789,"生命符記")
R(1790,"生命符記")
R(1791,"捕風者",[[description="現在既然你已經學會了狂暴姿態，就應該去弄一把稱手的武器。$B$B去和捕風者巴斯拉談談吧，他是住在奧特蘭克山脈和西瘟疫之地之間一個食人妖隱士。他是製造武器的行家，也是一個強大的薩滿。$B$B去找到巴斯拉，沿著塔倫米爾東側的河流一直向北——巴斯拉的營地就在這條河東岸的廢墟旁。",objectives={"和捕風者巴斯拉談話。"}]])
R(1792,"旋風武器")
R(1793,"勇氣之書")
R(1794,"勇氣之書")
R(1795,"誓縛",[[description="If you're are sufficiently prepared, then we should begin. Let me explain the process to you.$b$bI will begin by creating the basic summoning circle. When that is finished, my acolytes will use the rods of channeling to create the greater circle.$b$bOnce that is done, read the incantation from the Tome of the Cabal, and the felhunter will be pulled forth. Be careful, $n. A felhunter is a powerful foe, and I'd like to see you keep your head on your shoulders.",objectives={"Using the Tome of the Cabal, summon and subdue a felhunter, then return the Tome of the Cabal to Strahad Farsan in Ratchet."}]])
R(1796,"魔化金線血袍",[[description="我要幫你製作的第一件裝備就是長袍，你要負責為我收集若干材料，然後我會把它們組合到一起。這樣你就將擁有有首件能使你變得更加強大的裝備。$B$B首先，你必須給我拿來一件祕法之袍。你可以去找個裁縫幫忙製作，也可以從其他冒險者手中購買——當然如果你能自己製作的話就更好了。但是無論如何，你要先把祕法之袍交給我，然後我們才能開始。",objectives={"將奧法之袍交給貧瘠之地的梅納拉·沃倫德。"}]])
R(1798,"尋找斯坦哈德",[[description="是該教你召喚地獄獵犬的時候了，$n。但我現在手裡沒有教你這個法術所必需的材料，所以你得去找另外一個人來教你，也就是斯坦哈德·法爾杉，他是我們我們的另一個成員。$b$b他就住在在哥布林港口城市棘齒城附近。在你到達之前，我會通知他你要過去的。",objectives={"與貧瘠之地的斯坦哈德·法爾杉談話。"}]])
R(1799,"寶珠碎片",[[description="很好，那麼我們開始吧。$B$B首先，你必須到裡面去跟我的助手們談談，然後決定自己要走哪條路——他們會給你更詳細的解釋。$B$B然後，你必須到淒涼之地的瑪諾洛克集會所去，從那裡的某個術士身上找到一顆地獄火珠。你要淨化這顆寶珠，隱居在塵泥沼澤南部的一個名叫塔貝薩的法師會幫你完成淨化。她肯定會幫助你，因為我們曾有共同的過去。$B$B我再強調一次，這些任務沒完成之前，你就別回來見我。",objectives={"在棘齒城外的塔里與梅納拉的侍僧們談話，選擇自己修行的方式。$B$B然後給塵泥沼澤的塔貝薩帶去一顆地獄火珠。"}]])
R(1800,"羅德隆的王座廳",[[description="The orphan matrons at my home tell mighty stories of battle and lore at night if we are good and do our chores.  One story was about how Lordaeron fell, and about how the evil Arthas took his own father's life to become ruler.$B$BHe had no honor, $N!  When I grow up and become a mighty Horde warrior, my blade will be guided by honor - never evil!$B$BWould you take me to see the throne room, please?  It is just before where you would go down into the Undercity.",objectives={"Take your ward to the old Lordaeron Throne Room that lies just before descending into the Undercity."}]])
R(1801,"陰謀之書",[[description="It will take more than a simple summoning circle to bring forth a felhunter for you to challenge.$b$bMy three acolytes and I will assist in creating the magic circles. You require a copy of the Tome of the Cabal, which has been lost to us for some time. It was written by the first group of warlocks to summon a felhunter unaided.$b$bPerhaps Jorah Annison can help you with this. He's employed as a cartographer in the Undercity these days, but still knows more of ancient texts than any I know.",objectives={"Speak with Jorah Annison in the Undercity."}]])
R(1802,"陰謀之書",[[description="它是丟了，不過我知道一些可以幫你找到它的線索。$b$b這本書的複製品只有一本，而且它也已經被損壞了，很大一部分的書頁全都被撕了下來，現在聽說它們落入了千針石林的半人馬手裡。$b$b其餘的部分在南海鎮的西岸丟失了，原本這些書頁是要用船送往米奈希爾港的，不過卻從來也沒能送到。$b$b你看，我告訴了你這麼多消息，好歹你也得在找回東西以後拿來給我看看吧？",objectives={"為鐵爐堡的克羅姆·粗臂找回發黴的書籍和破損的手稿。"}]])
R(1803,"陰謀之書",[[description="Ah! I see that you are a warlock of similar tastes to mine. Indeed, acquiring the Tome of the Cabal is a worthy aspiration. Did you know that it was once held within the walls of Lordaeron? It was vandalized though, almost half its pages removed. Who would commit such a heinous act?$b$bThat half is lost, though rumor says that it fell into the hands of the centaur of the Thousand Needles.$b$bThe rest of the text was to be transferred to Ironforge, but was lost in transit on the coast west of Southshore.",objectives={"Retrieve the Moldy Tome and Tattered Manuscript for Jorah Annison in the Undercity."}]])
R(1804,"陰謀之書",[[description="Well, ah, it's hard to let it go. But you found it, and you have more important things to do with it, of course. Just, please, be sure to mention to Strahad that I wanted a copy.$b$bWhile you were out, he sent a message for you. He wanted me to tell you that for his acolytes to assist with the summoning, you'll have to acquire three rods of channeling.$b$bHe might not know where to find them, but I do! They were last used by the orcs of the Dragonmaw clan in the Wetlands. I'd check their spellcasters!",objectives={"Bring the Reconstructed Tome and 3 Rods of Channeling to Strahad Farsan in Ratchet."}]])
R(1805,"陰謀之書",[[description="This is one of the most interesting texts I have perused in the last few years. The selection here is sparse--mostly books on geography--and I have already read them all. I should hope that Strahad would send me a copy of this tome when he has the chance.$b$bSpeaking of him, he sent word to me while you were away. For your task, you must obtain three rods of channeling.$b$bFor allowing me to look at this text, I will share a secret: You can find the rods on orcs of the Dragonmaw Clan in the Wetlands.",objectives={"Bring the Reconstructed Tome and 3 Rods of Channeling to Strahad Farsan in Ratchet."}]])
R(1806,"正義試煉",[[description="Why don't we go over to the forge and get started on this? I've been preparing for your arrival for some time, so it shouldn't take long at all.$B$BWhen we're done, you'll be far more prepared to defend the Light than you have been, this much I swear.$B$BI'll be somewhat honest, $N, seeing the results of your exploits makes me somewhat envious. But knowing that I can contribute to your adventures in my own significant way does bring me some joy.",objectives={"Wait for Jordan Stilwell to finish forging a weapon for you."}]])
R(1818,"迪林格爾",[[description="I was told Deathguard Dillinger has a job for someone like you.  If you're willing to show your value to the Dark Lady's forces, then report to Dillinger immediately.$B$BDeathguard Dillinger's post is on the west end of Brill, near the graveyard.",objectives={"Speak with Deathguard Dillinger in Brill."}]])
R(1819,"切割者奧拉格",[[description="When the Scourge swept through Tirisfal Glades, we captured one to study.  He had a free mind, and called himself Ulag the Cleaver.  But, although his will was free, he was still enthralled by the Lich King.$B$BWe hoped to find a way to break the king's control over Ulag, but we failed.  Now, finally, it is time to free him.  $B$BFree him, and kill him.$B$BActivate the skull stone trigger near the mausoleum to the north.  This will lift the magical seal that binds him.$B$BThen... be ready, $N.",objectives={"Kill Ulag the Cleaver, then speak with Deathguard Dillinger."}]])
R(1820,"庫勒曼",[[description="You have proven your value to the Dark Lady, now perhaps you can prove yourself to one of her subjects.$B$BColeman Farthing awaits a warrior who is willing to be his instrument of revenge against the Forsaken's enemies.$B$BYou will find him in the Gallow's End Tavern in eastern Brill.",objectives={"Speak with Coleman Farthing."}]])
R(1821,"阿加曼德家傳武器",[[description="The Agamand family were my employers in life, and they were the cause of my death!  It is fitting that the Agamands are now mindless minions of the Lich King.$B$BNow I would have their last vestiges of honor.  Go into their family crypt and rob them of their family heirlooms: a sword, an axe, a dagger and a mace.  Bring them to me!$B$BThe Agamand family crypt is at the north end of the Agamand mills, protected by lurking scourge and dead Agamands.",objectives={"Bring Coleman Farthing the Agamand Family Axe, the Agamand Family Sword, the Agamand Family Mace and the Agamand Family dagger."}]])
R(1822,"祖傳武器")
R(1823,"和魯迦交談",[[description="You are a warrior of skill and growing renown.  Perhaps you are ready for Ruga Ragetotem's trial?  If so, then find Ruga in Camp Taurajo in the Barrens.$B$BHe awaits those warriors who answer his call.",objectives={"Speak with Ruga Ragetotem."}]])
R(1824,"巨人曠野的試煉",[[description="To pass this trial, you must travel south to the Field of Giants.  There you will find a host of crawling, insect creatures.  They are new to the Barrens and I do not like what they herald.$B$BBring me their still-twitching antennae, and waste no time, $N, for harvested antennae will not twitch for long.  Bring me the antennae in the time allowed, and you will pass the trial.",objectives={"Bring 5 twitching antennae to Ruga Ragetotem at Camp Taurajo"}]])
R(1825,"和索恩格瑞姆交談",[[description="Thun'grim Firegaze, an orc blacksmith of renown, has heard of your continued deeds of valor in service of the Horde.  He would like to fashion for you a suit of armor, and bids you speak with him immediately.$B$BThun'grim is camped east of the Crossroads in the Barrens.",objectives={"Speak with Thun'grim Firegaze in the Barrens."}]])
R(1838,"野蠻護甲",[[description="I have heard tales of your strength and valor, and wish to make for you a suit of armor, a companion to aid you as tales of your great deeds grow.$B$BBut the fashioning of this armor will be a quest unto itself, $N.  I will need your help, and the help of other smiths of the Horde.$B$BHere, take this scroll.  I spent many nights, struggling with near-blind eyes, writing that which I need for the armor.  Bring me the items on this scroll and I will create for you the first piece of the suit.",objectives={"Bring to Thun'grim Firegaze 15 Smoky Iron Ingots, 10 Powdered Azurite, 10 Iron Bars and a Vial of Phlogiston."}]])
R(1839,"尤拉萊克和野蠻護手",[[description="The troll smith Ula'elek will craft for you the brutal gauntlets.  He dwells in Durotar, in Sen'jin Village with his Darkspear brethren, and he awaits your coming.",objectives={"Speak with Ula'elek in Durotar."}]])
R(1840,"奧姆·石蹄和野蠻頭盔",[[description="Orm Stonehoof is respected greatly for his skill.  He will make for you the brutal helm.$B$BSeek him out in Thunder Bluff, near the pool by the city's great, central totem.",objectives={"Speak with Orm Stonehoof in Thunder Bluff."}]])
R(1841,"維羅拉·奈特雷和野蠻腿甲",[[description="It is said that, before her death, Velora Nitely was one of the finest armorsmiths in Lordaeron.  Death, it seems, has not decreased her talents.  Speak with Velora--she will make your brutal legguards.$B$BVelora plies her trade in the Undercity of Lordaeron, in the trade quarter.",objectives={"Speak with Velora Nitely in the Undercity."}]])
R(1842,"薩特之蹄",[[description="I can make you a pair of brutal gauntlets, and great magic will they hold.  But first, you must collect this magic and bring it to me.$B$BThe satyrs dwell in northeastern Ashenvale because of the forest's power.  They feed off its purity, leeching and corrupting.  You can tell which satyrs have drawn the most of Ashenvale's magic by their swollen, uncloven hooves.$B$BThese hooves hold great power.  I will need them for your gauntlets' crafting.",objectives={"Bring 7 Uncloven Satyr Hooves to Ula'elek at Sen'jin Village in Durotar"}]])
R(1843,"野蠻護手")
R(1844,"奇美拉之角",[[description="I will make you the helm, but you must show me you are worthy of it.$B$BNestled in the northwestern reaches of the Stonetalon Mountains there lies the Charred Vale.  It was once a verdant place, but is now defiled and ashen, and what creatures remain there are mad with pain and despair.$B$BThat place is where I send you, $N.$B$BYou must go to the Charred Vale and find a chimaera matriarch.  Slay her, free her of her misery.  Bring me her galvanized horn as proof, and I shall make for you the helm. ",objectives={"Bring a Galvanized Horn to Orm Stonehoof in Thunder Bluff."}]])
R(1845,"野蠻頭盔")
R(1846,"龍喉脛骨",[[description="To make the brutal leg guards, I need a brace of sturdy shinbones.  The Dragonmaw orcs of the Wetlands have nice, thick shinbones.  I'll need theirs.$B$BBut they must be sturdy.  Be sure to test the shinbones as you collect them.  If you can break them with your bare hands, then they won't be sturdy enough to work with.",objectives={"Bring 8 Sturdy Dragonmaw Shinbones to Velora Nitely in the Undercity."}]])
R(1847,"野蠻腿甲")
R(1848,"野蠻鎖甲")
R(1858,"碎手氏族",[[description="I'll leave it to you to get Tazan's satchel open, and return to me with its contents. The locking mechanism is complex, so it would probably be easiest if you obtained the key.$b$bAs you didn't find it on Tazan's body, I can only assume that he left the key in the care of another... Ah, yes, that's right. He had an assistant named Gamon. A drunkard, you'll most likely find him at the tavern. Perhaps you could quietly relieve him of the key.",objectives={"Steal Tazan's key, then use it to open his Satchel and deliver its contents to Therzok in the Cleft of Shadow in Orgrimmar."}]])
R(1859,"瑟祖克",[[description="Lower your voice, $n. Yeah, I know your name. Was told to keep an eye out for an orc by your description.$b$bFrom what we've heard about you, you can handle yourself in combat, and aren't opposed to a little sneakery from time to time.$b$bAm I right?$b$bAnyways, you should go see Therzok in Orgrimmar. He's got an offer for you to hear.",objectives={"Speak with Therzok in the Cleft of Shadow in Orgrimmar."}]])
R(1860,"和詹妮亞交談",[[description="We mages have a task that needs doing.  One that is vital to the safety of Stormwind and Elwynn forest.$B$BJennea Cannon has the details.  She studies in the wizard's sanctum, in the mage district of Stormwind.  You should make your way to her with haste.",objectives={"Speak with Jennea Cannon in Stormwind."}]])
R(1861,"明鏡湖",[[description="This world has been victim to massive mystic struggles, which tore magic currents from once stable channels.  We struggle to determine the effects these changes have caused, and some of us fear the worst!$B$BBut I will reveal more of this later.  Right now, we need you to gather information.$B$BHere, take this flask.  Go to the base of the waterfall at Mirror Lake, southwest of the Stormwind gates, and retrieve a sample of the water there.  Return it to me so that I might test it for magical taints.",objectives={"Bring a Mirror Lake sample to Jennea Cannon in Stormwind."}]])
R(1878,"收集水袋")
R(1879,"和彬克交談",[[description="$N!  Bink, my gnome colleague in Ironforge, sends word.  She has a task that needs doing and won't rely on anyone but a mage to do it!  Are you that mage, $N?$B$BIf so, then speak with Bink.  She spends her time in the Hall of Mysteries in the Mystic Ward of Ironforge.",objectives={"Speak with Bink in Ironforge."}]])
R(1880,"法師文檔存儲器",[[description="We mages do more than just waggle our fingers and make pretty sparks!  We control magic, the base fabric of our world!  And that takes great care, and resolve.  And knowledge... so much knowledge!$B$BOne of my devices, the mage-tastic gizmonitor, collects and stores that knowledge in huge amounts!  But it's lost!  When we fled our home of Gnomeregan, I left it in a chest in one of our huts outside the city, and now the place is crawling with leper gnomes!$B$BPlease, $N, retrieve my gizmonitor!",objectives={"Bring Bink her Mage-tastic Gizmonitor."}]])
R(1881,"安娜斯塔西婭",[[description="$N, Anastasia Hartwell has a task for someone of your talents.  Speak with her in the Magic Quarter of the Undercity, and prepare yourself for your first task for the mages of the Forsaken.",objectives={"Speak with Anastasia Hartwell."}]])
R(1882,"巴尼爾農場",[[description="The Plaguelands to the east are an aberration.  Devised by the Lich King, they spread their magic into the soil, corrupting and killing all that live.  Although there is a certain charm to the destructive forces of the plague, we, the mages of the Forsaken, believe it is unruly and must be curtailed.$B$BBut first, we must measure how far it has spread into Tirisfal.  Go to the Balnir Farmstead in eastern Tirisfal.  In the garden are flowers--snapdragons.  Gather these and return.",objectives={"Bring Balnir Snapdragons to Anastasia Hartwell in the Mage Quarter of the Undercity."}]])
R(1883,"安蘇瓦",[[description="Un'thuwa, tribal mage of Sen'jin Village, detects a disturbance in the magic currents of Durotar and asks for aid.  Speak with Un'thuwa and do what you can to help him.$B$BDo this, and in time further secrets will be revealed to you.",objectives={"Speak with Un'thuwa."}]])
R(1884,"魂能骨堆",[[description="The warlock Zalazane of the Echo Isles has disrupted the normal flow of magic in Durotar.  He does this through tainted fetishes, ju-ju heaps, which he has placed among his huts on the main Echo Isle.$B$BThese heaps corrupt our wildlife and give power to the warlocks and infernal creatures that lurk in the land's dark corners.$B$BYou must destroy the ju-ju heaps, $N, before the flow of magic is forever altered.",objectives={"Destroy 4 Ju-Ju Heaps, then return to Un'thuwa in Sen'jin Village."}]])
R(1885,"米奈特·卡加德",[[description="$n? Not quite what I was expecting, considering Carkad himself has taken an interest to you. Looks can be deceiving though, right?$b$bEither way, you should go see him as soon as possible. You wouldn't want to know what happened to the last few that chose to ignore his summons.",objectives={"Speak with Mennet Carkad in the Rogues' Quarter of the Undercity."}]])
R(1886,"亡靈哨兵",[[description="If you wish to join the Deathstalkers, Lord Varimathras' elite guard, you will have to prove your worth.$b$bI will not lie to you, $n, this task could mean your death.$b$bI have some things that need attending to. I require the personal effects of Astor Hadren, a messenger who travels between Silverpine and the Undercity. I will leave the method of procurement to your discretion.$b$bIt will be better for you if you know less of the nature of this business. Succeed and I shall tell you more.",objectives={"Get Astor's Letter of Introduction and return it to Mennet Carkad in the Rogues' Quarter."}]])
R(1898,"亡靈哨兵",[[description="The letter of introduction should be enough to convince Andron that you are the messenger he's been waiting for. I've met Andron before, he doesn't quite have the mental capacity to be that suspicious.$b$bLord Varimathras suspects that Andron has been providing aid to some other group. He wishes to know what organization this is and requires proof of it.$b$bI want you to speak with Andron, and obtain this information. You'll find him at his shop near the Apothecarium.",objectives={"Speak with Andron Gant in the Undercity."}]])
R(1899,"亡靈哨兵",[[description="You'll find the ledger with the information your employers seek on the bookshelf behind me. Deliver it with my regards, and tell them that I would prefer it if they sent you, if they find enough value that they should wish to continue our arrangement.",objectives={"Bring Astor's Ledger to Mennet Carkad in the Rogues' Quarter of Undercity."}]])
R(1918,"被汙染的水元素",[[description="The slain elemental has produced an intensely glowing globe of water.  The contents of the globe are, at best, disgusting.  It would be safe to assume that whatever has befouled the water of Mystral Lake is most likely present in the water of the globe.$B$BIt's not exactly common knowledge who might be interested in such a find; perhaps the person who originally sent you out to the lake, Mastok Wrilehiss at Splintertree Post, might have an idea.",objectives={"Bring the Befouled Water Globe to Mastok Wrilehiss at Splintertree Post, Ashenvale."}]])
R(1919,"向詹妮亞報告",[[description="Your knowledge of the craft grows, young $N.  Are you now ready to begin your true lessons?  Are you ready to take your place in the secret war we wage?$B$BIf so, then speak with Jennea Cannon, in the wizard's sanctum in the mage district of Stormwind.  She has a task for you which will open your first window into the invisible world.",objectives={"Speak with Jennea Cannon in Stormwind."}]])
R(1920,"調查藍色隱士",[[description="A disturbance has been reported at the Blue Recluse tavern in the Mage Quarter.  Strange, invisible creatures now wander the tavern, and I fear a mana rift has formed there.$B$BI want you to investigate the tavern and capture those creatures.  Use the cantation of manifestation in the tavern to make the creatures visible, subdue them then use a containment coffer to capture them.  When you have enough, return to me with your filled coffers, your empty coffers and the cantation.",objectives={"Obtain a Cantation of Manifestation and a Chest of Containment coffers from behind Jennea Cannon.  Bring 3 Filled Containment Coffers to Jennea at the Wizard's Sanctum."}]])
R(1921,"收集原料",[[description="You have served your fellow mages well, and now it is time to don your wizard's robe.  Wynne Larson can make your robe, but you must bring her the needed materials  $B$BThe robe will be made of linen which is easy to find, but you must also gain charged rift gems, and the only known location of the gems is in the Silver Stream Mine of Loch Modan, left in crates by the dwarven miners' league.$B$BGather the linen and the gems and bring them to Wynne Larson at the Larson Clothiers in the Mage District.",objectives={"Bring 10 Linen and the 6 Charged Rift Gems to Wynne Larson in Stormwind."}]])
R(1938,"烏爾的暗影魔法研究論文",[[description="Long ago, three mages studied in this tower until one fell to the dark arts.  He was urged to turn away from that evil magic, but he could not resist.  And so he was banished.$B$BThe fallen mage's new domain is the tower of Ilgalar in Redridge, and he took with him a powerful book--Ur's Treatise on Shadow Magic.$B$BWe, the mages of Stormwind, would have that book returned.  Enter the tower of Ilgalar, find the tome in his library, and bring it to me.",objectives={"Bring Ur's Treatise on Shadow Magic to High Sorcerer Andromath in Stormwind."}]])
R(1939,"高階巫師安多瑪斯",[[description="High Sorcerer Andromath wishes to speak with you, $N.  He is at the top of the wizard's sanctum, in the mage's district of Stormwind.$B$BIt would be wise to speak with him, for Andromath is one of the most powerful mages not locked away in Dalaran.  Council with him is high council indeed.",objectives={"Speak with High Sorcerer Andromath."}]])
R(1940,"新鮮的蜘蛛絲",[[description="Your service has been unwavering, $N.  I think, perhaps, it is time you had a finer garment, one more suiting your station as an adept mage.  If you gather the needed materials, then we will arrange the robe made.$B$BYou must enter Duskwood and hunt carrion recluse spiders.  Extract their silk, but only the finest, most pristine silk will do.  When you have enough, take it to Wynne Larson, here in the mage district at the Larson Clothiers.  She will craft your robe.",objectives={"Bring 8 Pristine Spider Silk to Wynne Larson in Stormwind."}]])
R(1941,"法紋長袍")
R(1942,"星結之衣")
R(1943,"巨魔法師迪諾",[[description="The troll mage Deino has need of your assistance, $N.  She resides in Orgrimmar, in the Darkbriar Lodge.",objectives={"Speak with Deino."}]])
R(1944,"克薩維亞之水",[[description="The fabled city of Xavian lies nestled deep within eastern Ashenvale, and tales of its ancient knowledge are well known among the learned.  It is said that the waters of Xavian hold vast magical powers.$B$BI would have a sample of those waters, from their source.$B$BTake this flask and go to Xavian.  Gather water from the bottom of its highest waterfall, and return to me.  And use care as you move through that ancient city--satyrs now hold the ruins and do not like mages prying into their affairs.",objectives={"Bring the Xavian Water Sample to Deino in Orgrimmar."}]])
R(1945,"歡笑的姐妹",[[description="For your services, I have arranged for the creation of your new robes, provided you can gather the needed materials...$B$BFor these robes, you must return to Ashenvale for the locks of hair from laughing sisters--dryads who gather near the Raynewood Retreat.$B$BWhen you have their hair, bring it to Kil'hala, a troll tailor at the Crossroads in the Barrens.  He will be expecting you, and will fashion your robes.",objectives={"Bring 12 Laughing Sister's Hairs to Kil'hala at the Crossroads."}]])
R(1946,"虛靈長袍")
R(1947,"沼澤之旅",[[description="現在，是讓你得到自己的法師魔杖的時候了。首先，你得去和住在塵泥沼澤的人類隱者塔貝薩談一談。你可以在沼澤深處找到她的小室，那地方就在塞拉摩的西邊，石槌廢墟的北邊。$B$B去和她談談，她的知識非常淵博。",objectives={"和塔貝薩談話。"}]])
R(1948,"強大的物品",[[description="The building of a mage's wand is not easy.  Rare substances are required, and a vessel must be made that can store great quantities of magical energy.  You must gather these things and bring them to me.$B$BI have written onto this parchment that which you need, and instructions on how to get it.  Bring me exactly what is on this list, and follow my written directions to the letter, for if you do not then when we make your wand things might go... badly.",objectives={"Bring 1 Jade and the Bolt Charged Bramble to Tabetha in Dustwallow Marsh."}]])
R(1949,"隱藏的秘密",[[description="To make your wand, there are key passages in a certain book that I must read.  The book is called Rituals of Power, written by the Magus Tirth.$B$BI do not have a copy of his book, and none of the world's great libraries possess it.  So you must speak with Tirth and gain it from him.$B$BGood luck.  Tirth used to be a great mage and scholar, but now he spends his time at the gnome and goblin races in the Shimmering Flats, drinking and gambling.",objectives={"Speak with Magus Tirth in the Shimmering Flats."}]])
R(1950,"解封咒語",[[description="I can help you with the book, but first you have to help me!$B$BThe tome you seek is in my magically locked strongbox.  To open it a special phrase must be uttered, and I can't remember the phrase!  Normally my assistant helps me remember these things but he's nowhere to be found.$B$BIf you want my book, then find my apprentice!  Ask around the race track--if you're lucky then someone has seen him.  Either drag him back here, or at least get my magic phrase from him so we can open my box!",objectives={"Find the phrase to Tirth's strongbox, then return to Tirth."}]])
R(1951,"能量儀祭",[[description="嗯……我想起來了，我的書已經沒有了！你要知道，我欠了一屁股的債，不得不把最後一冊《能量儀祭》賣掉來還債，我把它賣給了一個牧師……$B$B他是血色十字軍的成員。他一定把那本書帶到了他們的根據地——提里斯法林地裡的血色修道院圖書館去了！$B$B如果你想要那本書的話，就得去一趟修道院。很抱歉給你帶來這麼多麻煩，這些天我已經有些頭昏腦漲了……",objectives={"將《能量儀祭》交給塵泥沼澤的塔貝薩。"}]])
R(1952,"法師的魔杖",[[description="I'll go make the wands now.",objectives={"Speak with Tabetha after her ritual."}]])
R(1953,"返回沼澤",[[description="$N，是時候讓你去和塔貝薩談談了……這位塵泥沼澤裡的隱士將指導你如何鑄造強大的法師物品。$B$B塔貝薩就隱居在塵泥沼澤的深處，塞拉摩的西邊。",objectives={"和塔貝薩談話。"}]])
R(1954,"地獄火寶珠",[[description="The first step is to acquire an orb with power.  The warlocks of the Burning Blade have nice, high quality orbs... it's too bad they've bound demons into them!  But we can fix that, yes we can.$B$BGo to Desolace and snatch an infernal orb from a Burning Blade summoner.  You'll find summoners at the Mannoroc Coven.$B$BWhen you have the orb, return to me.",objectives={"Bring an Infernal Orb to Tabetha in Dustwallow Marsh."}]])
R(1955,"驅除魔鬼",[[description="Now that we have a summoner's orb, we must exorcise the demon within it.  I can do that.  That's the easy part.$B$BYou're the one who has the hard job.  You're the one who has to kill the demon once it's out.$B$BAnd you'll have to be quick.  If you take too long then he'll jump back in the orb and we'll have to start over!$B$BSo get yourself ready.  Prepare your strongest spells and keep your potions handy, and go get a friend if you have one.  Because this isn't going to be pretty.",objectives={"Kill the Demon of the Orb, then speak with Tabetha."}]])
R(1956,"奧達曼的能量源",[[description="既然惡魔已經被消滅了，接下來我們就得去找一個能量源。不幸的是，最合適的能量源往往非常古老而且極難獲得。有的時候，命運就喜歡這樣捉弄你，難道不是嗎？$B$B所以，為了得到能量源，你必須到奧達曼去打敗那裡的黑曜石守衛。他體型巨大而且很難對付，但是你可以從他身上得到我們所需要的能量源！$B$B祝你好運，$N。如果你運氣不好的話，那麼……很高興認識你。",objectives={"找到一個黑曜石能量源，將其交給塵泥沼澤的塔貝薩。"}]])
R(1957,"法力怒靈",[[description="We are almost finished, but this last step is the most perilous, $N.$B$BI have the empty summoner's orb and am ready to empower it.  We will do this by harnessing the energy of a mana rift.  I'll cast a spell that will temporarily open a rift, from which creatures, mana surges, will pour out.  You must defeat the mana surges and their power will be released, which I will then collect.$B$BKill enough mana surges before the rift closes and I will place all their collected energy in your orb.",objectives={"Kill 12 Mana Surges in the allowed time limit."}]])
R(1958,"蒼穹之力")
R(1959,"向安娜斯塔西婭報告",[[description="幽暗城的法師們注意到城裡出現了一股魔法波動並傳了話給部落的法師進行調查。$B$B安娜斯塔西婭·哈特威爾會告訴你更多的詳細內容。去幽暗城的魔法區和她談談吧。",objectives={"和安娜斯塔西婭·哈特威爾談話。"}]])
R(1960,"調查煉金店",[[description="Algernon's alchemist shop in the Apothecarium is the locus of a strange disturbance.  Invisible creatures, made solely of magic, wander the shop--there must be a reason, and we must find it!$B$BInvestigate the disturbance and capture those creatures.  Take a chest of coffers and a scroll from behind me.  Use the scroll at the shop to make the creatures visible, subdue them with your spells, then throw down a coffer to capture them.  Return with the filled coffers, the empty coffers and the cantation.",objectives={"Obtain a Cantation of Manifestation and a Chest of Containment Coffers from behind Anastasia Hartwell.  Bring 3 Filled Containment Coffers, the Chest of Containment Coffers and the Cantation of Manifestation to Anastasia in the Undercity."}]])
R(1961,"收集原料",[[description="It is time for you to don your first mage's robes, $N.  They are a sign of your station, and a testament to your worth.$B$BTo gain the robes, you must gather the mana gems from the Dalaran mages of Silverpine.  Their beliefs are similar to ours and so killing them is somewhat distasteful, but if they lack the strength to resist us, then they do not deserve their lives.$B$BBring the gems and a supply of linen to Josef Gregorian at the Magic Quarter's tailor shop.",objectives={"Bring 10 Linen and 6 Dalaran Mana Gems to Josef Gregorian."}]])
R(1962,"魔焰長袍")
R(1963,"碎手氏族",[[description="The Warchief is too subtle in his methods. He is cautious to unleash the might of the Horde. Once we were stronger, mighty conquerors all. That pride we must regain, and the Shattered Hand will do so.$b$bWe build strength from the shadows and strike at the exposed, secretly laying our enemies low. A task you must complete for me, to prove your worth.$b$bThe troll Tazan trades with the pirates near Ratchet. He has information I must have. Kill him and bring me his satchel.",objectives={"Kill Tazan and bring his Satchel to Therzok in the Cleft of Shadow in Orgrimmar."}]])
R(1978,"亡靈哨兵",[[description="The Syndicate? I would never have suspected. It seems the lords of Alterac have fallen far in the years since their betrayal.$b$bLord Varimathras will be pleased to learn of this, and as you were so instrumental in this discovery, it would be fitting if you were the one to deliver it to him.$b$bAh, and how could I forget?$b$bWelcome to the Deathstalkers.",objectives={"Deliver Andron's Ledger to Varimathras in the Hall of the Dark Lady in the Undercity."}]])
R(1998,"芬維克·薩托斯",[[description="Lord Varimathras has just sent me a missive about a threat to the Forsaken that must be immediately removed. His name is Fenwick Thatros, one whom Lord Varimathras believes is a leader of the undead that have taken root in Silverpine Forest.$b$bYour name came to mind immediately, $n. I have faith enough in your abilities that you will carry out this mission flawlessly.$b$bThe latest reports from the Deathstalkers in Silverpine indicate that Thatros can be found near the decrepit dock on Lordamere.",objectives={"Kill Fenwick Thatros and bring his head back to Mennet Carkad in the Rogues' Quarter of the Undercity."}]])
R(1999,"交易工具",[[description="The wizards of the Kirin Tor at Ambermill have stored away important documents pertaining to the current state of Dalaran. This we know from the admissions of one of our prisoners. Lord Varimathras has placed the duty of recovering them in the hands of the Deathstalkers.$b$bThis task falls to you, $n. You will need some equipment, however, and the knowledge of lockpicking. Speak with Estelle Gendry, our outfitter, and ask her for a set of tools before you set out.",objectives={"Find the Dalaran Status Report and return it to Mennet Carkad in the Rogues' Quarter of the Undercity."}]])
R(2038,"賓格斯的補給品",[[description="好像在洛克湖墜機還不夠倒楣似的，湖心小島上的穴居人還襲擊了我，搶走了我的工具和氣壓炸彈。沒有旋翼機沒有炸藥，我什麼都做不了！$B$B去幫我找回工具和氣壓炸彈，$N。為了諾姆瑞根！",objectives={"找回賓格斯的裝備：$B$賓格斯的氣壓炸彈、賓格斯的扳手、賓格斯的榔頭和賓格斯的螺絲起子。"}]])
R(2039,"尋找賓格斯",[[description="我們和賓格斯失去了聯繫！他被派去偵察諾姆瑞根，不過已經有足足一個星期沒回來報告了。這傢伙應該是失蹤了。$B$B最後有人看到他時，他正在洛克湖上空飛行。你可以去那一帶調查一下，$N。",objectives={"去洛克莫丹尋找賓格斯·布拉斯場海默。"}]])
R(2040,"地底突襲",[[description="諾姆瑞根已經被那群卑鄙懦弱的穴居人們完全佔據了！情況很緊急，或許你能幫上我們的忙，$N。$B$B在死亡礦坑深處有一台功能強大的哥布林伐木機，找到這台伐木機並帶回它的能源供應機件。有了這台伐木機的能源供應機件，我們就能給高速鑽孔挖掘機供應足夠的能量，用它來鑽透這裡與諾姆瑞根之間的岩石。鑽開一條路，給他們來一次地精式的突襲！",objectives={"從死亡礦坑中帶回小型高能發動機，將其帶給暴風城矮人區中的沉默的舒尼。"}]])
R(2041,"沈默的舒尼",[[description="也許……也許你能幫我們攻打諾姆瑞根。$B$B你可以到暴風城去找秘密攻擊部隊的指揮官，沉默的舒尼。舒尼需要有人幫他找一些東西。$B$B你可以在暴風城的矮人區中找到她。$B$B祝你好運，$N。",objectives={"去暴風城和舒尼談話。"}]])
R(2078,"基爾卡克的報復",[[description="旱鴨子，你得幫忙找到我的大副。$B$B帶上這把鑰匙，把它插入我的大副身上的鑰匙孔裡，然後把他給我帶回來。$B$B那些魚人們馬上就要吃不了兜著走了，因為我的大副就要回來啦！",objectives={"找到基爾卡克的大副——機械打手4100型，把他帶到基爾卡克那裡。"}]])
R(2098,"基爾卡克的鑰匙",[[description="A pirate's life ain't an easy one, landlubber. It ain't all about plunderin' and booze! Alas, me ship be sunk just off shore thanks to them pesky Threshadons.$B$BWhat I be needin' is me first mate back in workin' order!$B$BWhen I washed up'n shore, the key for me first mate broke on the rocks and was pilfered by the beasties of Darkshore. Out of the corner of me eyes I saw some of them Ragin' Crawlers, Ferocious Foreststrider, and murloc rummaging through the wreckage....",objectives={"Find and return the three pieces of Gelkak's Key to Gelkak Gyromast."}]])
R(2118,"瘟疫蔓延",[[description="A sickness spreads across the Darkshore, gripping the minds and bodies of all it touches.$B$BThe Thistle Bears have been hit the hardest by this plague. The once noble beasts are now an instrument of destruction - rabid and frenzied. I may have a cure for this ailment.$B$BTake this trap to the forest and lay it on the ground. Any Rabid Thistle Bear that crosses the light shall become docile for a short time. Once the bear is docile, it shall follow you. Lead it back here, $N.",objectives={"Capture a living Rabid Thistle Bear and bring it back to Tharnariun.$B$BShould you fail to capture a Rabid Thistle Bear and lose your trap, return to Tharnariun Treetender and request another trap."}]])
R(2138,"清除疫病",[[description="As I had feared, the cure does not work.$B$BIt saddens me greatly to order the death of any of nature's beasts, but the sick and tainted thistle bears must be put down.$B$BReturn to the forest and destroy 20 rabid thistle bears, $N. It will most certainly not put a stop to the plague but it will slow down the damage the animals are doing to our forest and its inhabitants for a short time.",objectives={"Cleanse the forest of 20 Rabid Thistle Bears and return to Tharnariun Treetender in Darkshore."}]])
R(2139,"薩納瑞恩的希望",[[description="The survival of our people and lands comes at unfortunate costs, $N.$B$BYou have spilled the blood of nature's servants; many sick animals you have felled. The people of Auberdine are indebted to you, for the forest's pain is eased - even if only for a moment.$B$BI have one final task for you, but be warned, you will have to kill again. It is my hope that this will be the last time I call upon you, $N.$B$BIn a cave to the northeast, near Bashal'Aran, resides the Den Mother. Slay her.",objectives={"Find and kill the Den Mother."}]])
R(2158,"休息和放松",[[description="每個冒險家在疲憊的時候都需要休息——而休息和放鬆的最佳去處就是獅王之傲旅店！$B$B我的好朋友法雷是那裡的旅店老闆。告訴他是我介紹你去的，也許他還會給你些特別優惠呢。$B$B如果你要去獅王之傲旅店的，沿著大路往南走就沒錯了！",objectives={"和獅王之傲旅店的旅店老闆法雷談話。"}]])
R(2159,"多蘭納爾的貨物",[[description="你好，年輕的$c。你能幫我一個忙嗎？我有一包藥草必須送到多蘭納爾去，但是現在我還要忙於處理幽影谷德魯伊的事情，所以走不開。$B$B你能幫我把這包藥帶去嗎？把它送到多蘭納爾旅店的老闆凱達米爾那裡，那座旅店就在南方的路邊上。",objectives={"把藥草送到旅店老闆凱達米爾手中。"}]])
R(2160,"塔諾克的補給品",[[description="嘿！我一看就知道你是個精力充沛的冒險家。如果你要繼續前進的話，能不能幫我帶個包裹到卡拉諾斯的旅館去？$b$b你應該已經計畫在那個旅店裡稍作休息了，對吧？我敢說只要你到了旅店，就肯定會想在那裡歇一下腳。$b$b無論如何，請把這包裹帶給旅館主人的助手塔諾克·霜錘。我自己是沒法活著穿越那危險的通道了，巡山人衛隊還得過些天才會經過這兒，所以我只能靠你了。",objectives={"給卡拉諾斯的塔諾克·霜錘帶去一箱旅店補給品。"}]])
R(2161,"苦工的重擔",[[description="對不起，你能幫幫我嗎？$B$B我這兒有一車食物，一路上我遭遇了蠍子、蜘蛛，還有其他更可怕的東西！我把這些食物送到了試煉谷，因為我覺得他們可能會需要這個，同時我又很樂意幫助他們。$B$B但是他們居然根本就不需要食物！現在我還得把這些東西帶回剃刀嶺，可是我害怕路上的那些野獸……$B$B你能不能幫我送回去呢？我只是個苦工，可你是個大英雄，你一定什麼都不怕！$B$B請把東西交給剃刀嶺旅館的老闆格羅斯克。",objectives={"把烏克爾的貨物帶給剃刀嶺的旅館主人格羅斯克。"}]])
R(2178,"燉陸行鳥",[[description="你聞到撲鼻的香氣了嗎？那可是用我的秘方精心烹製的、新鮮出爐的燉陸行鳥，口感超絕，美味無比！$B$B你對我的食譜很感興趣吧？$B$B在我告訴你食譜之前，你得證明你能對付那些動物。$B$B我可並不是要求你簡單地跑出去馴服一隻陸行鳥，然後騎回來見我。你得去捕殺一些陸行鳥，把它們那些多汁的肉脯帶回來給我。只有這樣我才會把燉陸行鳥的秘方教給你。",objectives={"給急彎河的奧蘭達利亞·夜歌帶回5塊陸行鳥肉。"}]])
R(2198,"破碎的項鏈",[[description="你找到了一條破碎的項鏈，但是破舊不堪的外表並不能掩飾它高超的製作工藝。項鏈已經破碎，原本應該鑲在項鏈上的三塊寶石不見了。在項鏈的內側印有鐵爐堡的徽記，旁邊還刻著三個小字：「TdK」。$B$B如果你想要瞭解這條項鏈背後的故事，你就必須找到它的主人。也許那個徽記和小字就是線索……",objectives={"找到破碎的項鏈的來源，從而瞭解其潛在的價值。"}]])
R(2199,"昂貴的知識",[[description="我在鐵爐堡可是鼎鼎有名的珠寶匠！好吧，我承認那是以前的我……因為一個競爭對手的污蔑讓我變成現在這個樣子！名聲不好在這行裡就根本混不下去。結果，你看，我現在就變得窮困潦倒。$B$B現在，我要你給我搞五塊銀錠來，這樣我才能完成我手頭上的這份訂單——看來這是我唯一的一份訂單了。$B$B你給我五塊銀錠之後，我就會回答你所有關於這條項鏈的問題。",objectives={"給鐵爐堡的塔瓦斯德·基瑟爾帶去五塊銀錠。"}]])
R(2200,"回到奧達曼",[[description="我的一個邪惡的競爭對手居然污蔑我，說是我製作的項鏈詛咒了那個聖騎士！顯然沒有人願意買被詛咒的東西。$B$B不如我們來做筆交易吧：如果你能幫我找回寶石，我就能重新把它鑲到項鏈上，然後只要你幫我宣傳這條項鏈並沒有受到詛咒，幫我恢復名譽的話，我就將把這條項鏈送給你！$B$B我建議你從奧達曼開始搜集線索，或許那個聖騎士的屍體就在下面，畢竟他是最後一個擁有它的人！當你找到寶石之後就使用這個東西，它可以讓你隨時和我進行聯繫。",objectives={"去奧達曼尋找塔瓦斯的魔法項鏈，被殺的聖騎士是最後一個拿著它的人。"}]])
R(2201,"尋找寶石",[[description="The paladin's journal has provided perhaps the only clues that Uldaman will yield as to the location of the necklace's gems.  If the paladin's scribing remains accurate, then the Shadowforge dwarves and the troggs that vie for control of the dig site will need to be dealt with.$B$BArmed with this knowledge, the search for the gems begins in earnest.  When all the gems have been acquired, Talvash in Ironforge should be notified via the Phial of Scrying as per his instructions.",objectives={"Find the ruby, sapphire, and topaz that are scattered throughout Uldaman.  Once acquired, contact Talvash del Kissel remotely by using the Phial of Scrying he previously gave you.$B$BFrom the journal, you know...$B* The ruby has been stashed in a barricaded Shadowforge area.$B* The topaz has been hidden in an urn in one of the Trogg areas, near some Alliance dwarves.$B$B* The sapphire has been claimed by Grimlok, the trogg leader."}]])
R(2202,"奧達曼的蘑菇",[[description="I've heard about a newly discovered plant called the magenta fungus caps.  They grow in clusters, deep in the Uldaman dig site; they may be elsewhere, but for now that's the only place I know they're at.  I want to study their potential use in alchemy, and that's where you come in.$B$BFind the magenta cap clusters and bring me a dozen caps.  Be warned, the clusters may spew out poison spores if jostled.$B$BDo this for me, and I'll whip up a batch of one of my famous restorative elixirs for you!",objectives={"Bring 12 Magenta Fungus Caps to Jarkal Mossmeld in Kargath."}]])
R(2203,"荒蕪之地的試劑 II",[[description="You have been most helpful to me, $c.  I would reward you with the very recipe for the brew I gave you earlier... but I would ask of you a task that is quite dangerous.  Hear my request.$B$BThis lockbox contains three empty thaumaturgy vessels; they are imbued with an attunement aura that will drain the blood of a scorched guardian dragon.  Using one on the beast will anger it greatly, so be warned.  Once you have all three filled, bring them to me.$B$BDo this, and the recipe will be yours.",objectives={"Use the empty thaumaturgy vessels on scorched guardian dragons found in the Badlands.  Once you have them filled, bring them to Jarkal Mossmeld in Kargath."}]])
R(2204,"修復項鏈",[[description="You are going to need to find some \"oomph\" for the necklace, and Uldaman is probably the best place for it, actually.  I guess there are a lot of constructs running around in there, yeah?  Well, take out the biggest, baddest construct in that place and grab its power source!  I am pretty sure I can fuse that source into the necklace.$B$BWithout that power source, fixing the necklace will be impossible.  Come back to me here to Ironforge when you have it, and we'll get it all fixed up for you!",objectives={"Obtain a power source from the most powerful construct you can find in Uldaman, and deliver it to Talvash del Kissel in Ironforge."}]])
R(2205,"軍情七處",[[description="The badge? Oh, it's nothing, fish - nothing you could handle anyhow. By the looks of you, I'd say Mathias is likely to mistake you for the cheese delivery $g boy:girl; instead of a proper rogue. Regardless, I've been assigned a job and I've made a promise to deliver on that job.$B$BSpeaking of which, deliver this package to Mathias and he may give you a small task or two.$B$BGet cracking. ",objectives={"Deliver Keryn Sylvius's package to Master Mathias Shaw at the Stormwind Barracks."}]])
R(2206,"連偷帶搶",[[description="Our operatives in the field are reporting heavy Defias activity south of Goldshire. The reports indicate that the Defias have taken over Jerod's Landing and are now using it as a way to smuggle large quantities of contraband from Redridge to Westfall.$B$BI need you to infiltrate the dock house and get me that shipping schedule, $N. You will probably find it buried deep in the pockets of the Dockmaster.$B$B...and $N, should you be discovered, SI:7 will disavow all knowledge of your existence.",objectives={"Find the Defias Dockmaster and recover the Shipping Schedule for Master Mathias Shaw."}]])
R(2218,"救贖之路",[[description="Another lost soul looking for guidance, eh? I suppose you want to find a purpose - your purpose. I've seen it a thousand times, another hero looking for work.$B$BWell, today's your lucky day, friend. Hogral's got the cure for your ailment.$B$BHere's what you do: Take this road here up to Ironforge and make your way to the Forlorn Cavern. Once there, locate the thieves' guild and speak with Hulfdan Blackbeard. He'll put you on the road to salvation.",objectives={"Speak with Hulfdan Blackbeard in Ironforge."}]])
R(2238,"國王的財寶",[[description="Ye see, the King be strip mining the quarry fer ore and gems. More riches than any one dwarf should see in ten lifetimes.$B$BThe Hidden Circle has values, $N. We value valuables. Can ye understand?$B$BNow we feels the King should be sharing some of that booty, but we don't want ol' 'Stinkbeard' to know he's sharin' - if ye catch me drift.$B$BWe needs ye to speak with Onin MacHammar over by Gnomeregan and bring back a report. The crafty dwarf has hidden hisself amongst the lepers. Be careful.",objectives={"Find Onin MacHammar by Gnomeregan."}]])
R(2239,"奧寧的報告",[[description="The Quarry? Yap, I see those monstrous armored steam tanks come by this post near every day.$B$BMy contacts to the east tell me that the tank starts off at Ironforge, makes a pickup at the Gol'Bolar Quarry, stops over at Kharanos to refuel and then for some blasted reason, it takes the long way around past Gnomeregan, before reaching Ironforge to drop off the shipment.$B$BIt's all in the report, $r. Take it back to Hulfdan so he can plan the next step.",objectives={"Take Onin's Report back to Hulfdan in Ironforge."}]])
R(2240,"密室",[[description="Now for the task at hand.$B$BThere is a secret chamber, the Chamber of Khaz'mul, that must be explored.  The problem is that the chamber's behind a huge, locked door!  It's a lucky thing I know how to open it.$B$BI've described everything in my journal, here on the table.  My band and I are stuck here for now... so you, $N, must find the chamber of Khaz'mul for us!$B$BRead my journal, explore the chamber, then report to Prospector Stormpike at the Explorers' League in Ironforge.",objectives={"Read Baelog's Journal, explore the hidden chamber, then report to Prospector Stormpike."}]])
R(2241,"詹諾克的花",[[description="They say I'm 'lovestruck,' whatever that means.$B$BSure, I spend my every waking moment thinking about Syurna. Sure, my home is full of paintings and drawings of Syurna. Sure, I often go days without eating, sleeping, or drinking, while I lament about the love we could have had. Is that so wrong?$B$BNow she won't see me! ME! I've tried sending her messages but she won't even talk to another person unless they are a rogue.$B$BCould you deliver this flower to her? Don't forget to tell her it's from Jannok.",objectives={"Take Jannok's Rose to Syurna in Darnassus."}]])
R(2242,"命運的召喚",[[description="We believe there is one being that may be able to help us understand what is happening to the forests of Teldrassil. Unfortunately, getting the creature to cooperate has proven disastrous.$B$BHe hides on a branch at the outskirts of the Oracle Glade. All who have so far approached the satyr, whether through force or diplomacy, have met with doom. Perhaps stealth is the answer, $N.$B$BFind what Sethir the Ancient carries in his packs and report back to me.",objectives={"Find Sethir the Ancient and bring back any clues that you may discover to Syurna."}]])
R(2258,"荒蕪之地的試劑",[[description="$N, I could use your aid if you're up for it.  I am an alchemist of some note, and I seek your aid in acquiring some reagents found out in the Badlands.$B$BI need the following items to replenish my stocks: five buzzard gizzards, ten crag coyote fangs, and five rock elemental shards.  Obviously, you can get them off of the beasties themselves; if you're not the fighting type, then find friends who are.$B$BAcquire these items for me, you'll get some coin out of the deal.  Watcha wanna do?",objectives={"Bring 5 Buzzard Gizzards, 10 Crag Coyote Fangs, and  5 Rock Elemental Shards to Jarkal Mossmeld in Kargath, Badlands."}]])
R(2259,"艾瑞安·影語",[[description="Do not worry, $N, I am not sending you to see Syurna. Erion requires your presence at the Cenarion Enclave. Make haste!",objectives={"Contact Erion Shadewhisper in Darnassus."}]])
R(2260,"艾瑞安的命令",[[description="Word of your deeds has spread far and wide, $N. So far, in fact, that Stormwind Intelligence has asked for you by name.$B$BThe journey is taxing and not without peril, but an opportunity to train under SI:7 should not be taken lightly.$B$BA new world awaits you, $N. Make your way to Old Town in Stormwind and speak with Renzik \"The Shiv\" at SI:7 headquarters.",objectives={"Travel to Stormwind City and seek council with Renzik \"The Shiv.\""}]])
R(2278,"白金圓盤",[[description="財寶室的中間是四塊巨大的白金圓盤，每塊圓盤上都刻滿了各種各樣的未知文字和圖案。你的手觸摸這些圓盤的時候，你感到了一絲震動。就在你接觸圓盤的一瞬間，一個巨大的石頭守衛者的形象出現在了你的面前。$B$B「你好。我是知識的守衛者。土靈的創造者所留下的一切有關這個種族的知識都已經存儲在了這張諾甘農圓盤上了。」$B$B你發掘到了迄今為止這個世界上最寶貴的知識財富！",objectives={"和石頭守護者交談，從他那裡瞭解更多古代的知識。一旦你瞭解到了所有的內容之後就啟動諾甘農圓盤。"}]])
R(2279,"白金圓盤",[[description="Touching the Discs of Norgannon once again makes your hand tingle.  This time, however, a strange grinding noise is heard from inside the discs.$B$BYour backpack suddenly becomes heavier than it was before.  Inside, you discover a miniature version of the discs!$B$BNo doubt, an item of this sort would be invaluable for someone interested in the ancient history of Azeroth.  The Explorers' League in Ironforge is such a group, known throughout the Alliance; perhaps they can make good use of it.",objectives={"Take the miniature version of the Discs of Norgannon to the Explorers' League in Ironforge."}]])
R(2280,"白金圓盤",[[description="Touching the Discs of Norgannon once again makes your hand tingle.  This time, however, a strange grinding noise is heard from inside the discs.$B$BYour backpack suddenly becomes heavier than it was before.  Inside, you discover a miniature version of the discs!$B$BNo doubt, an item of this sort would be invaluable for someone interested in the ancient history of Azeroth.  The sages of Thunder Bluff are such historians, known throughout the Horde; perhaps they can make good use of it.",objectives={"Take the miniature version of the Discs of Norgannon to the one of the sages in Thunder Bluff."}]])
R(2281,"赤脊山的聯絡員",[[description="Sending you out in the field now would be suicide. Renzik doesn't need another dead rogue on his hands. Don't fret, though, $N - Renzik is going to get you up to speed.$B$BMake your way to the Redridge Mountains and speak with an associate of SI:7 named Lucius. You will find him hanging around the docks of Lakeshire with the other shady good-for-nothings.",objectives={"Venture forth to Lakeshire in the Redridge Mountains and speak with Lucius."}]])
R(2282,"奧瑟爾伐木場",[[description="多年以來，我們都在這裡對盜賊進行訓練！畢竟不是每一個盜賊都能像老盧修斯那樣機靈和優雅的。$B$B沿著這條路向前走，一直到奧瑟爾伐木場去。我在那裡放了一隻裝著重要物品的箱子。去把箱子裡的東西給我拿來，我就給你頒發偷竊技能認證書！",objectives={"打開盧修斯的箱子，拿到偷竊技能證明物，然後把它歸還給湖畔鎮的盧修斯。"}]])
R(2283,"搜尋項鏈",[[description="We've got work for you, that is if you've got the guts to do it!$B$BDeep in the Badlands is the Uldaman dig site.  We've heard a tale about some idiot paladin who died there recently.  Why we even care is that he had a very valuable necklace on him.  It's supposedly got three large gems: a ruby, a sapphire, and a topaz.$B$BThe shot: we want it, and we're payin' TOP SILVER to get it.  It may be damaged, but that's neither here nor there; we'll fix whatever scratches are on it.",objectives={"Look for a valuable necklace within the Uldaman dig site and bring it back to Dran Droffers in Orgrimmar.  The necklace may be damaged."}]])
R(2284,"搜尋項鏈，再來壹次",[[description="As sure as Malton is a dummy, those gems are still in Uldaman somewhere.  You're going to have to go back there and look for them.$B$BLike I said before, if the information we have is correct then there's a ruby, a sapphire, and a topaz that go with the necklace.  Find them and put them in the necklace.$B$BAs to where the gems are, who knows?  Maybe you'll get lucky and find the corpse of the Paladin.  If he's not been stripped clean already, then maybe he's got them on him still.",objectives={"Find a clue as to the gems' whereabouts in the depths of Uldaman."}]])
R(2298,"國王的搜查",[[description="So there we were, about to start plottin' out phase III when a couple o' Magni's blockheads come bargin' in here talkin' bout some kind o' heist and arresting some o' the Hidden Circle.$B$BWell nobody puts the iron on old Blackbeard! The argumentations got heavy and thick and somehow yer name weres blurted out!$B$BMe advice? Take the first Gryphon out o' Ironforge and get to Stormwind. Get yerself to Old Town and once there, talk to an old friend o' mine named Renzik \"The Shiv.\"",objectives={"Travel to Stormwind and seek out Renzik \"The Shiv.\""}]])
R(2299,"去找霍夫丹！",[[description="Where have you been, $N? Hulfdan's been looking all over the place for you. We thought the king may have put you in irons.$B$BGet to Ironforge as soon as possible and speak with Hulfdan!",objectives={"Travel to Ironforge and speak with Hulfdan Blackbeard."}]])
R(2300,"軍情七處",[[description="Renzik was looking for you, fish.$B$BI wouldn't keep Mathias's second in command waiting if I were you.",objectives={"Travel to Stormwind and seek out Renzik \"The Shiv.\""}]])
R(2318,"翻譯日記",[[description="At an impasse of sorts, you know that you will need the book translated into a language you can understand.  There certainly are a number of people in the world who could do it; the closest location that might have someone who could, however, is the Kargath outpost in the Badlands.  Perhaps that is a good place to start.",objectives={"Find someone who can translate the paladin's journal.  The closest location that might have someone is Kargath, in the Badlands."}]])
R(2338,"翻譯日記",[[description="Droffers and Son Salvage aren't smart enough to restore the magic in the necklace, but I am.  All I want to do is study the necklace so I can learn to make them myself.  To do that, I will need your necklace.  Let me borrow it, and in exchange for the time I get to study it I will translate the journal for you.  While you are searching for the gems, I should have enough time to learn what I need to.$B$BIt's a simple deal, and no one else will be the wiser.  Whatcha wanna do?",objectives={"Let Jarkal borrow the necklace.  In exchange, he will translate the journal for you."}]])
R(2339,"尋找寶貝",[[description="Here is the journal, translated for you to read on your own.  The crux of it says dwarves hid the ruby, the troggs hid the topaz, and a trogg named Grimlok has the sapphire.$B$BLook - you're going to need a power source to make the necklace work again.  Dran Droffers doesn't know this.  To find one, here's what I'd do: go as deep as you can in Uldaman and kill whatever construct there is the strongest.  No doubt whatever that is would have it.$B$BWhen you have everything collected, come back here!",objectives={"Recover all three gems and a power source for the necklace from Uldaman, and then bring them to Jarkal Mossmeld in Kargath.  Jarkal believes a power source might be found on the strongest construct present in Uldaman.$B$BFrom the journal, you know...$B* The ruby has been stashed in a barricaded Shadowforge area.$B* The topaz has been hidden in an urn in one of the Trogg areas, near some Alliance dwarves.$B* The sapphire has been claimed by Grimlok, the trogg leader."}]])
R(2340,"交付寶石",[[description="Any necklace setting and gem will work, so long as they are the same material.  This power source, however, is what will bring the magic back to the necklace... I hope.$B$BI'll gladly supply the gems needed for your version of the necklace, so long as the power source actually works.$B$BHead to Orgrimmar and keep your end of the bargain with Droffers and Son Salvage.  Just keep your mouth shut about our deal, and when you get back I might have a wonderful surprise for you.",objectives={"Deliver the Necklace and Gem Salvage to Dran Droffers in Orgrimmar."}]])
R(2341,"項鏈任務的終結",[[description="As Dran and Malton Droffers begin to squabble over their new salvage, half of the deal is now complete.  A trip to the Badlands is now in order to finish things up, as Jarkal Mossmeld in Kargath might have a special reward waiting for you there.",objectives={"Visit Jarkal Mossmeld in Kargath to see if he was successful."}]])
R(2342,"尋找寶物",[[description="Sweeping the bat pens with this broom is not befitting a Garrett!  I've earned a little coin from this accursed job, and I'm willing to spend it on you to better my station.$B$BThe Garrett family weapon of choice is locked away in our chest in the South Common Hall of Uldaman from when we Garretts toiled there as diggers.  Without it, I will be stuck here forever - literally - sweeping up after these infernal bats.$B$BReclaim my family's treasure and bring it to me!  Help me restore my birthright!",objectives={"Get Patrick Garrett's family treasure from their family chest in the South Common Hall of Uldaman, and bring it to him in the Undercity."}]])
R(2358,"奈茲拉之角",[[description="Many years ago, the Horns of Nez'ra were stolen from Ravenholdt manor. Across continents and oceans I have searched, only to discover that these insignificant beasts have had it in their possession all along.$B$BSlay every Blackrock orc you cross until the Horns of Nez'ra are recovered. Should you recover the horns, find me in Lakeshire.$B$BDo this for me and your name shall be known to Ravenholdt, $N.",objectives={"Return the Horns of Nez'ra to Arantir's Shadow in Lakeshire."}]])
R(2359,"克拉文之塔",[[description="I've been staking out this tower for weeks, $N. Recently a major shipment came through from Duskwood, and along with it came those guards.$B$BWhat are they? Your guess is as good as mine. I can tell you one thing - they aren't human.$B$BAnyhow, the shipment had a chest - which is what I assume those abominations are guarding. The zombie with the spikes holds a key we'll need.$B$BGet that key, get in the tower, and uncover whatever is in that chest. Take your findings back to Mathias.",objectives={"Steal the Defias Tower Key, break into the Defias Tower and uncover the contents of the Duskwood Chest. Take whatever information you find back to Mathias Shaw in Stormwind. Read Kearnen's Journal to gain insight about the tower."}]])
R(2360,"馬迪亞斯和迪菲亞潛行者",[[description="Not a moment too soon, $N. SI:7 reconnaissance is reporting unusually heavy Defias activity in Westfall.$B$BIt would seem that the Defias have taken over an abandoned Alliance watch tower southeast of Sentinel Hill and are using it as a base of operations to smuggle in goods from the Redridge supply route.$B$BGet to Westfall and contact Agent Kearnen for your debriefing. You will find her hidden near the tower.$B$B...and $N, should you be discovered, SI:7 will disavow all knowledge of your existence. ",objectives={"Travel to Westfall and find Agent Kearnen for your debriefing."}]])
R(2361,"修復項鏈")
R(2378,"尋找碎手氏族",[[description="You have served the Deathstalkers well, $N, but perhaps it is time for you to venture outward. While you have shown aptitude in the ways of stealth and deception, you still require much training.$B$BThe Deathstalkers have allies within the Shattered Hand. Seek out those that would assist us - find Shenthul in Orgrimmar.",objectives={"Journey to Orgrimmar and speak with Shenthul at the Cleft of Shadow."}]])
R(2379,"贊杜沙",[[description="Your determination alone is not enough to overcome the obstacles that lay ahead of us.$B$BSpeak with Zando'zan to begin your training as an operative of the Shattered Hand.$B$BIt is only when you have mastered the practices of stealth and thievery that you may take the next step towards your destiny.",objectives={"Speak with Zando'zan at the Cleft of Shadow."}]])
R(2380,"向奧格瑞瑪進發！",[[description="A master of stealth and deception you are not, however, all of that can and will change. You've obviously impressed those in charge with your meager skills, as the great Shenthul has asked for you by name.$B$BTake the road north of here to Orgrimmar and speak with Shenthul in the Cleft of Shadow.",objectives={"Speak with Shenthul at the Cleft of Shadow in Orgrimmar."}]])
R(2381,"搶劫海盜",[[description="I don't mean to scare you, $N, but the last five thieves I sent to steal the southsea treasure came back to me in pieces.$B$BSouth along the coast you'll find Tide Razor, the southsea freebooter's ship. Nestled in the hold is the payoff - the southsea treasure. On the second level of that ship is the pirate's den, a place where they train all of their thieves.$B$BBoard that ship, steal the treasure, and bring it back to me. Use the pirate's den if you need to practice your thievery, but be careful!",objectives={"Bring the Southsea Treasure back to Wrenix the Wretched in Ratchet. Do not forget to get an E.C.A.C. and Thieves' Tools from Wrenix's Gizmotronic Apparatus. You will need both of these items to complete your mission.$B$BShould you be attacked by any unusually hostile parrots, use your E.C.A.C.!"}]])
R(2382,"棘齒城的維尼克斯",[[description="Zando'zan has seen it! Yes, the day comes! Thrall's death... the dagger in his back, poison seeping through to his every vein... Zando'zan has said too much.$B$B$N! Zando'zan has a task for $N! $N must travel to Ratchet, east of the Crossroads, and speak with Wrenix the Wretched. Go!",objectives={"Travel to Ratchet and speak with Wrenix the Wretched."}]])
R(2383,"簡易羊皮紙",[[description="Ah, while you were gone a parchment came for you, $N.$B$BRead it when you have time. If I'm not mistaken, it came from the warrior trainer Frang. He would have words with you when you're ready. You'll find him outside the Den, taking cover in the shade.",objectives={"Read the Simple Parchment and speak to Frang in the Valley of Trials."}]])
R(2398,"失蹤的矮人",[[description="奧達曼挖掘場從前並不是現在這樣一團糟的。我們鐵爐堡的矮人曾經控制了這個區域，但是……當穴居怪來了之後，一切都變了。它們的數量太多了，連我們矮人也擋不住它們！$B$B事實上，因為它們非常突然地發起了攻擊，所以我擔心我們有些人被困在了挖掘場裡面。$B$B我的朋友巴爾洛戈帶了一個矮人小隊進入了挖掘場深處，就在穴居怪發起攻擊之前。如果他和他的同伴們還活著的話，我希望你能找到他們。",objectives={"在奧達曼找到巴爾洛戈。"}]])
R(2399,"發芽的樹葉")
R(2418,"能量石",[[description="不久之前，我和暗爐矮人發生過一些插曲。他們把我帶到了苦痛堡壘，讓我對兩種來自於奧達曼的奇怪石頭進行研究。我發現這兩種石頭如果經過正確的處理，就會變成相當理想的能量源。能在那個廢舊的挖掘場裡發現這樣的東西讓我感到十分驚奇！$B$B總之，在我告訴他們這個秘密之後，那幫該死的傢伙就把我踢出了苦痛堡壘，然後自己在奧達曼挖掘更多的石頭。$B$B我自己也要那些石頭！幫我帶那兩種石頭來，我會給你豐厚的報酬的！",objectives={"給荒蕪之地的里格弗茲帶去8塊德提亞姆能量石和8塊安納洛姆能量石。"}]])
R(2438,"翡翠攝夢符",[[description="班奈希爾獸穴的德魯伊守護者蓋洛拉斯·塔文斯倫曾經給了我一個翡翠攝夢符。這種強大的護符可以吸取翡翠夢境的能量，給拿著它的人帶來好運。$B$B不過，我把它放在星風村的衣櫃裡了，沒辦法把它取回來……星風村原本是個寧靜的小村子，但現在那裡受到了熊怪的侵襲。$B$B你能不能幫我拿回攝夢符，$c？",objectives={"將翡翠攝夢符交給多蘭納爾的塔隆凱·捷根。"}]])
R(2439,"白金圓盤",[[description="This object is an incredible find.  The ancient Titans, or the Creators as these discs refer to them as, are the link to our enchanted creation, if the lore stored in here is correct!  We'll need to invest as much research time into this as possible.$B$BAs for you, heroic $c, take this voucher to Dinita Stonemantle at the vault.  It grants you what I think is a fitting for such a tremendous find!$B$BReturn to me directly when you are ready; there is much more to do for the Explorers' League!",objectives={"Take your reward voucher to Dinita Stonemantle in the Vault of Ironforge."}]])
R(2440,"白金圓盤",[[description="I shall focus my energies on these discs; they will reveal their true workings to me in due time.$B$BAs for you $N, I will now reward you for your diligence in bringing this to my attention.  Take this voucher to Bena Winterhoof, the alchemy trainer for Thunder Bluff.  She will give you a special item I believe you will find appealing, and she will supply you with a choice of potions from my personal stock.$B$BReturn to me soon, as I sense there is much more at hand for us to do regarding this find.",objectives={"Take the reward voucher to Bena Winterhoof in Thunder Bluff."}]])
R(2458,"臥底密探",[[description="The Venture Company... Perhaps you have heard of them?$B$BFor one year we have worked on planting an agent deep within their ranks. Through much hard work and careful planning, we succeeded.$B$BRecently we received word that the Venture Co. are planning something on a grand scale. Go north of the Sludge Fen to the Venture Co. tower and contact our undercover agent, Taskmaster Fizzule.$B$BWhen you find the tower, use this flare gun, then approach Fizzule and show him the salute of the Shattered Hand.",objectives={"Travel to the Venture Co. Tower, north of the Sludge Fen and contact the Shattered Hand's covert operative, Taskmaster Fizzule.$B$BWhen the tower is in sight, use the Flare Gun to signal your arrival to Taskmaster Fizzule. Fire off TWO flares, then approach Taskmaster Fizzule and perform the Shattered /Salute.$B$BThese actions must be performed in the correct order, as Fizzule will attack and terminate any person he does not recognize."}]])
R(2459,"噬夢者菲羅斯塔",[[description="翡翠……不見了！我的攝夢符被毀了！$B$B星風村北部有一群瘤背秘法師。我接到報告說他們的領袖——噬夢者菲羅斯塔的脖子上戴著一根在夜間會發出綠光的項鏈。我覺得就是它偷走了我的翡翠……它決不會想到那顆翡翠對它毫無用處。$B$B去找到丟失的寶石，$N。另外，你在那兒活動的時候，別忘了順便清除一些墮落的秘法師。",objectives={"多蘭納爾的塔隆凱·捷根要你殺掉7個瘤背秘法師，並找到遺失的珠寶。"}]])
R(2460,"碎手軍禮",[[description="As a rogue of the Shattered Hand, it is imperative that you learn the Shattered Salute. It is the only way to truly identify another member of the Hand.$B$BWatch, learn, repeat.",objectives={"Perform the Shattered Salute on Shenthul."}]])
R(2478,"基本不可能的任務",[[description="你必須從工頭希里克斯身上偷出塔樓的鑰匙，$N。拿到鑰匙之後，就把它收好——你也許用得到它。$B$B記住，毒藥已經讓塔樓裡的所有人都變得虛弱不堪。盡你所能給那些傢伙製造混亂和破壞，把他們全都殺了——不要手下留情！$B$B等裡面所有人都躺在血泊中之後，你就可以去打開加里維克斯的箱子，然後拿走贊吉爾的改良藥劑。把加里維克斯的腦袋和藥劑一起交給奧格瑪的申蘇爾。",objectives={"從工頭希里克斯那裡偷出希里克斯的塔樓鑰匙，進入塔樓，然後殺掉兩個變異風險投資公司工人、兩個風險投資公司巡邏員、兩個風險投資公司看守。$B$B殺掉大工頭普茲克·加里維克斯，取了他的首級，然後打開加里維克斯的箱子，拿走贊吉爾的改良藥劑。將藥劑和加里維克斯的頭顱交給奧格瑪的申蘇爾，等候進一步的指示。"}]])
R(2479,"希諾特的幫助",[[description="Take a sample of the mixture to Serge Hinott in Tarren Mill.$B$BIf anyone can cure you, it's Serge. Live long enough and Serge will show you the ways of poison creation and use.",objectives={"Travel to Tarren Mill in Hillsbrad Foothills and deliver the Sample of Zanzil's Mixture to Serge Hinott.$B$BTo get to Tarren Mill, take the Zeppelin to the Undercity and follow the road south through Silverpine and towards Hillsbrad. Follow the signs!"}]])
R(2480,"希諾特的幫助",[[description="I have never seen such wondrous results from a poison! Zanzil you say? Never heard of him, however, I must commend him on the creation of this concoction.$B$BSo, I am to cure you of this and then teach you how to make use of the poison?$B$BGive me a few moments to examine the toxin, $N.",objectives={"Wait for Serge Hinott to complete the cure."}]])
R(2498,"向德納蘭回報",[[description="我剛接到消息，奧拉密斯湖畔的德納蘭可能已經發現了讓林精長出那些毒瘤的原因。你去和他談談吧，告訴他是我派你去的。$B$B動作快點，$N，他需要我們的幫助。",objectives={"雷利亞·綠樹要你和奧拉密斯湖的德納蘭談一談。"}]])
R(2499,"奧肯斯古爾",[[description="在湖南岸的山洞裡有一個名叫奧肯斯古爾的林精，它正在使居住在奧拉密斯湖周圍的所有生物變得墮落。$B$B我不敢離那裡太近，不過即使從遠處看去，我也能看得很清楚：奧肯斯古爾已經被一顆我所見過的最大的腫瘤所毒害了……那個腫瘤簡直可以被稱作龐然大物。$B$B$N，你已經幫了我許多忙，不過我還要請你做一件事。殺掉奧肯斯古爾，拿到它身上的腫瘤，讓這個墮落之源永遠從我的家園消失。",objectives={"奧拉密斯湖的德納蘭要你去拿到奧肯斯古爾身上的巨大的瘤。"}]])
R(2500,"荒蕪之地的材料",[[description="$C，我需要你的幫助。我是個小有名氣的煉金師，我需要你去荒蕪之地幫我找一些原材料。$B$B我需要這些東西補充我的庫存：五個禿鷲的胃囊、十顆峭壁山狗的牙齒和五塊岩石元素碎片。當然你可以從這些動物身上拿到這些東西，不過如果你不擅長打仗的話，可以找些擅長的朋友。$B$B找到這些東西給我，作為交換你可以得到一些錢幣。$B$B好吧，你覺得怎麼樣？",objectives={"從荒蕪之地拿到加克所需的材料，然後回到塞爾薩瑪去見他。"}]])
R(2501,"荒蕪之地的材料 II",[[description="You have been most helpful to me, $N.  I would like to reward you with the very recipe for the brew I gave you earlier, but I must ask of you a favor that is quite dangerous.$B$BThis lockbox contains three empty thaumaturgy vessels; they are imbued with an attunement aura that will drain the blood of a scorched guardian dragon.  Using one on the beast will anger it greatly, so be careful.  Once you have all three filled, bring them to me.$B$BDo this, and the recipe will be yours.",objectives={"Use the empty thaumaturgy vessels on scorched guardian dragons found in the Badlands.  Once you have them filled, bring them to Ghak Healtouch in Thelsamar."}]])
R(2518,"月神的淚水",[[description="薩絲拉曾經受到月神的寵愛，這只優雅而純潔的蜘蛛在月光下的迷霧中編織著銀線，用以收集銀色的露水，並將這種有治療功效的露水存放在這個大殿裡。$B$B不過最近薩絲拉卻突然變得瘋狂起來，她的後代也受到了威脅。$B$B找到薩絲拉，$N，結束她的痛苦。她住在泰達希爾的北部邊界。找到她的銀色絲囊，把它們交給我。",objectives={"達納蘇斯月神殿的女祭司艾茉拉讓你把薩絲拉的銀色絲囊交給她。"}]])
R(2519,"月神殿",[[description="森林裡有一個曾經強大無比的生物現在急需幫助，$c。$B$B現在你有一項艱難的任務必須完成。$B$B請你去找女祭司艾茉拉，她會向你解釋具體的問題。她就在這裡東南方的月神殿裡。",objectives={"艾奎恩妮讓你和月神殿的女祭司艾茉拉談話。"}]])
R(2520,"薩絲拉的祭品",[[description="Now you must finish the task to which you have been appointed. Take the spinnerets and offer Lady Sathrah's sacrifice to Elune; lay the great spider to rest.$B$BInside this temple, find the central fountain. There is where you may leave the sacrifice.  The holy waters will purify and cleanse the corruption that drove Sathrah mad.$B$BWhen you have completed this, return to me.",objectives={"Priestess A'moora wants you to place Lady Sathrah's silvery spinnerets at the fountain inside the temple, and then return to her."}]])
R(2521,"為庫米沙效力",[[description="$R，你的小腦袋能理解一顆無暇的德萊尼水晶球有多麼珍稀嗎？無數德萊尼人終其一生就想要尋找一塊這樣的水晶，可是卻屢遭失敗，一直沒能達到願望。$B$B你現在就站在庫米沙面前，你知道庫米沙想要什麼，而且你還願意幫助我？很好，$r……在你探索者個區域的過程中，只要找到一顆無暇的德萊尼水晶球，就把它帶回來給我，我會以你永遠都無法想像的財富回報你。",objectives={"在你探索詛咒之地的旅程中，如果碰巧發現了無暇的德萊尼水晶球，就把它交給收藏家庫米沙。$B$B你要知道，這種寶石是整個艾澤拉斯最珍稀的水晶。詛咒之地上的任何一種生物都有可能帶著一顆無暇的德萊尼水晶球。$B$B每找到一顆，你都會得到相應的酬勞。"}]])
R(2522,"庫米沙的努力",[[description="Even though the portal conjuration was a failure, I remain hopeful that my next attempt will be successful.$B$BThe hope of the Draenei is as fervent as your greed for trinkets, $r. Go back out into these cursed lands and recover another flawless draenethyst sphere.$B$BOf course, the choice to take on this task is completely left to you *grin*.",objectives={"Find and return a Flawless Draenethyst Sphere to Kum'isha the Collector."}]])
R(2523,"被腐化的輕歌花")
R(2541,"沈睡的德魯伊",[[description="這裡的瘤背薩滿找到了一種可以在德魯伊休眠時將他的靈魂和肉體分離的方法。熊怪就這樣驅使著我的肉身，利用我去襲擊那些對班奈希爾獸穴進行偵查的人。現在我沉睡在翡翠夢境裡，無法阻止他們。$B$B你一定要幫幫我。瘤背薩滿用一種特殊的符咒來完成這種儀式，我希望能研究一下這種符咒。$n，全靠你了。",objectives={"將一個薩滿巫毒符咒交給班奈希爾獸穴的奧本·怒爪。"}]])
R(2561,"利爪德魯伊",[[description="After examining this charm, $N, I see now what must be done. Please take it, and do as I ask.$B$BYou are to explore the deepest areas of the Ban'ethil Barrow Den. There, you will find my soulless body... Although I regret what I am about to tell you, I see no other way to free myself from the control of the Gnarlpine.$B$BIn order for me to escape them, you must kill my physical form.  Once that is done, use the voodoo charm on my fallen body. After you have completed this task, please return to me.",objectives={"Oben Rageclaw wants you to kill his soulless body, and then use the Voodoo Charm."}]])
R(2581,"彎牙土狼的顎骨",[[description="眾所周知，土狼的顎骨具有強大的力量，不過它能折斷三英寸厚的瑟銀條嗎？不可能，決不可能，可是我卻親眼看到了這種事情。$B$B到詛咒之地去給我弄三個彎牙土狼的顎骨回來，路上順便打一些野豬和蠍子，因為我還需要兩片詛咒之地的野豬肺和一個厚甲蠍螯。",objectives={"收集3個彎牙土狼的顎骨、2片詛咒之地的野豬肺和1個厚甲蠍螯，把它們交給血法師德拉吉亞。"}]])
R(2582,"遠古之怒",[[description="啊，$N，歡迎回來。你好像非常喜歡從土狼的顎骨中提煉出來的藥劑所帶給你的感覺。但是你要小心，雖然它可以使你擁有泰坦一般的力量，不過它對你的精神和智力也具有長期的負面作用。$B$B我跟你說了這麼多之後，你還想要更多這種藥劑嗎？如果你還要的話，就給我弄三個彎牙土狼的顎骨、兩片詛咒之地的野豬肺和一個厚甲蠍螯來。",objectives={"收集3個彎牙土狼的顎骨、2片詛咒之地的野豬肺和1個厚甲蠍螯，把它們交給血法師德拉吉亞。"}]])
R(2583,"野豬的活力",[[description="這片不毛之地上生活著兩種野豬：灰鬃野豬和地獄野豬。$B$B看來這些野獸的耐力十足，這讓它們幾乎可以不受任何傷害，因此其他動物都無法與之抗衡。$B$B我們要做進一步的研究，$N。你給我弄三片詛咒之地的野豬肺、兩個厚甲蠍螯和一顆石化蜥蜴的大腦來，我就可以從中提煉出一種超強的藥劑。而你就將成為我的第一個實驗對象！",objectives={"收集3片詛咒之地的野豬肺、2個厚甲蠍螯和1顆石化蜥蜴的大腦，把它們交給血法師德拉吉亞。"}]])
R(2584,"野豬之魂",[[description="When I first administered the elixir, $N, I could tell that one or two applications would not satiate your appetite. Even now, I can see the hunger in your eyes. The concoction has addictive properties of which, seemingly, the most strong of will cannot resist.$B$BSo be it! Should you require more of the lung juice cocktail, venture back into the wasteland and find for me three blasted boar lungs, two scorpok pincers, and one basilisk brain.",objectives={"Bring three Blasted Boar Lungs, two Scorpok Pincers, and one Basilisk Brain to Bloodmage Drazial."}]])
R(2585,"決定性的打擊",[[description="你見過它們作戰嗎，$N？我是說那些蠍子。你有沒有見過他們優美、敏捷的動作？有沒有看到過它們那迅捷的攻擊？$B$B如果我們能將它們的敏捷性分離出來並製成藥劑，那我們就發達了……我的意思是……那將是我們對科學的一大貢獻！$B$B幫幫我吧，$N，我可以送給你一份實驗樣品。$N我需要三個厚甲蠍螯，兩個禿鷲的砂囊和一片詛咒之地的野豬肺。",objectives={"收集3個厚甲蠍螯、2個禿鷲的砂囊和1片詛咒之地的野豬肺，把它們血法師德拉吉亞。"}]])
R(2586,"厚甲蠍鹽",[[description="你還活著！這真是個好消息。我猜你回來是想要更多的厚甲蠍鹽吧？$B$B很好，$N，那麼，你再回到詛咒之地去，幫我弄三個厚甲蠍螯、兩個禿鷲的砂囊和一片詛咒之地的野豬肺回來吧。",objectives={"收集3個厚甲蠍螯、2個禿鷲的砂囊和1片詛咒之地的野豬肺，把它們血法師德拉吉亞。"}]])
R(2601,"石化蜥蜴的大腦",[[description="這塊荒地上到處都是紅石蜥蜴，$N。這些蜥蜴的族群比這裡的其他任何生物都要興旺。$B$B我曾經在遠處觀察過它們的捕獵和其他日常活動——這些野獸表現出了某種思考過程，它們的智商甚至比某些人型生物還要高。$B$B我得研究一下他們的腦子！$B$B給我找十顆蜥蜴的大腦來，$N。還有，你必須再找兩個禿鷲的砂囊，否則我就無法完成藥物的配製。",objectives={"收集10顆石化蜥蜴的大腦和2個禿鷲的砂囊，把它們交給血法師萊諾雷。"}]])
R(2602,"清晰的思想",[[description="Your focused concentration has dwindled so soon? More research must be done!$B$BOh yes, the price remains the same, $N. Venture forth into the blasted lands and return to me with ten brains from the redstone and two vulture gizzards.",objectives={"Bring ten Basilisk Brains and two Vulture Gizzards to Bloodmage Lynnore."}]])
R(2603,"禿鷲的活力",[[description="死亡在這片被詛咒的土地上長出了翅膀，$c。我曾親眼目睹那些禿鷲將探險者的屍體狼吞虎嚥地吃掉——有時它們甚至會吃下攜帶著致命疾病的屍體。它們身體內部的系統竟然能夠抵禦席捲了這片土地的瘟疫，這的確令我感到十分驚奇。$B$B請幫助我進行研究，$N！我需要禿鷲的砂囊，還需要兩塊彎牙土狼的顎骨作為原料。$B$B我會和你五五分成的。",objectives={"收集10個禿鷲的砂囊和2塊彎牙土狼的顎骨，把它們交給血法師萊諾雷。"}]])
R(2604,"精神矍鑠",[[description="我看到你體內的火焰已經漸漸熄滅，那就是說，藥效只持續了一個小時？$B$B如果你還需要更多砂囊口香糖，就給我弄更多的砂囊來。在詛咒之地中收集十個砂囊和兩塊齶骨之後再回來。",objectives={"收集10個禿鷲的砂囊和2塊彎牙土狼的顎骨，把它們交給血法師萊諾雷。"}]])
R(2605,"口渴的地精",[[description="住在大沙漠裡真是活受罪！我都要被烤乾了。$B$B不過我有個主意。聽說有一種被稱作露水收集者的生物就在西南方活動……它們有一種特殊腺體，可以用來儲藏水分。$B$B如果能得到這種腺體，我就可以暢飲一頓，至少滋潤滋潤我的嘴唇！你能幫幫我嗎，$N？$B$B找到有一大片仙人掌的地方，$N，露水收集者常在那裡出沒。",objectives={"找到1個飽滿的露水腺，把它交給加基森的馬林·諾格弗格。"}]])
R(2606,"好味道",[[description="Blech! This stuff tastes terrible! So much for that idea...$B$BWait, what's that? Oh, I know, I know, you think I shouldn't give up on this stuff. Well, okay then.$B$BUhhhh, I have an idea! Brilliant! Take this dew to my friend Sprinkle -- she's an excellent chef. Tell her what we're up to here and that we want to make it go down a little easier.$B$BI mean, if it's going to taste that bad, it at least should have some kick to it... And I'm just not feeling it... ",objectives={"Marin Noggenfogger wants you to speak with Sprinkle in Gadgetzan."}]])
R(2607,"贊吉爾之觸",[[description="It appears as if you've brought back more information than even I expected. This certainly is a strange turn of events, $N.$B$BA cure? Hrm... Go down to the cellar and speak with Doc Mixilpixil - he may be able to help.",objectives={"Speak with Doc Mixilpixil in the cellar of the Barracks."}]])
R(2608,"贊吉爾之觸",[[description="Oh my, you look like death. Correction - I've seen death, you look worse than death. You, $g sir:miss;, would be what death coughed up at his last physical.$B$BHah! You hear that Noarm? Write that one down!$B$B*Cough* Hrm yes, in order for me to help you, I'll need to draw some blood. Don't worry, it only hurts the first few... fifty times or so... /lay down when you're ready for the treatment, $N.",objectives={"/Lay down to be examined by Doc Mixilpixil. How can he find the cure if he can't find the cause?"}]])
R(2609,"贊吉爾之觸",[[description="我們達成了共識，$N，你得的是「伊提斯綜合症」。$B$B幸運的是，我這裡有醫治伊提斯綜合症的藥方。$B$B我需要些東西：一束普通野花、一隻鉛瓶，一根青銅管，最後還要一卷淡綠色絲線。奧·艾瑪在「最好的線團」那家店裡給我留了一卷這樣的線，就在運河區沿岸。$B$B趕緊出發吧，$N，記住在你的病痊癒之前不要接觸任何人。哦，還有，蒙特高莫醫生說uA該洗個澡了——他說的，不是我說的。",objectives={"給道克·米希匹克斯帶去一束普通野花、一隻鉛瓶，一根青銅管，最後還要一卷淡綠色絲線。伊提斯綜合症可不會不治而愈，年輕的$g先生:小姐;。"}]])
R(2621,"悔恨的戰士",[[description="Regret. It is all I have now. One bad decision resulting in several horrible outcomes. If only I had waited for those orders. Maybe they would have detailed the horrors that awaited us in those cursed lands! Maybe they were to redirect us to another detail? Ultimately, it was my fault. All of it was my fault.$B$BSo here I stand, awaiting orders. I must know. I must have those orders.$B$BDispatch Commander Ruag resides in Stonard. Find him and find out what became of the orders.",objectives={"Speak to Dispatch Commander Ruag in Stonard."}]])
R(2622,"丟失的命令",[[description="The orders? What could you possibly want with the orders?$B$BWhat are you implying, $N? Of course I relayed those orders! The soldiers I sent the orders with were ambushed and brutally beaten by murlocs. Only one survived, if you can call that surviving. He can hardly speak, cannot walk, and must be fed through a tube. If you want to know what happened to those orders, speak with Bengor. I'm sure he is around here somewhere... and, $N, be mindful of what you stick your nose into - it may get bitten off.",objectives={"Speak to Bengor."}]])
R(2623,"沼澤空談者",[[description="Orders were given by the dispatch commander. We took... took orders. On way to Blasted Lands, ambushed.$B$BMurlocs... Many murlocs... One named Swamp Talker. Took orders from my hands as spear thrust into my skull. East... cave....$B$B<Bengor passes out.>",objectives={"Retrieve the Warchief's Orders and return them to the Fallen Hero of the Horde."}]])
R(2641,"斯普琳科的秘密佐料",[[description="在我還小的時侯，我姐姐包攬了所有燒飯的活，那簡直是糟透了！她做的有些東西簡直讓我無法忍受——直到我發現了一種被我稱作「秘密佐料」的東西，只要加上一點……嘖嘖！味道好極了！$B$B你問那是什麼東西？嗯，是一種被稱作紫色水生菇的蘑菇。如果你要我把這個嘗起來像拖把一樣的東西變成可以下嚥的食品，那麼我建議你去一趟辛特蘭，到那裡去找一個小湖泊。$B$B哦，記住了，紫色水生菇只有在水下才能找到。",objectives={"加基森的斯普琳科要你去給她找到一顆紫色水生菇。"}]])
R(2661,"給馬林的粉末",[[description="Here's the Violet Powder, $N. Take it to Marin and tell him he owes me a favor!",objectives={"Sprinkle wants to you take the Violet Powder to Marin Noggenfogger in Gadgetzan."}]])
R(2662,"諾格弗格藥劑",[[description="Now, to mix this powder in with the dew.$B$BCome back and talk to me in a minute... after I have perfected the fabulous Noggenfogger Elixir!",objectives={"Marin Noggenfogger wants you to speak to him again after he creates his elixir."}]])
R(2681,"禁錮我們的石頭",[[description="It will take more than you alone to overcome the forces of Razelikh and his subordinates.$B$BGather a suitable group of adventurers and free my men of their eternal torture! Eighteen stones you must shatter.$B$BFight hard and die with honor, $N.",objectives={"Free nine Servants of Razelikh, three Servants of Sevine, three Servants of Allistarj, and three Servants of Grol. Return to the Fallen Hero when your task is complete. You must remain within close proximity of the stones or the process will fail."}]])
R(2701,"古代英雄",[[description="Please, take from this a relic of old. We no longer have a use for the item.$B$BMay it serve you well in your fight against the legion.",objectives={"Open the chest and claim your reward."}]])
R(2702,"古代英雄",[[description="You have honored me with your nobility and heroism, $N.$B$BYou have also honored them...",objectives={"Speak to Corporal Thund Splithoof."}]])
R(2721,"基利斯",[[description="As one chapter of your adventure closes, another one begins, $N.$B$BOne of my men is still unaccounted for, lost somewhere in the Blasted Lands. I am talking about Lieutenant Kirith, of course.$B$BAs I had mentioned earlier, we were both imprisoned and tortured by Allistarj, but poor Kirith, his strength of will faltered. I could hear the experiments from my cage; the tortured screams rang through the halls of the cave. That was the last I saw or heard of Kirith.",objectives={"Find out what became of Lieutenant Kirith."}]])
R(2741,"超級測蛋器")
R(2742,"林吉被困住了！",[[description="Hey $r!$B$BRin'ji lost axe and was captured! Please, help Rin'ji escape. Me know that $r like you don't like Rin'ji's kind, but Rin'ji begs! Must get out of here!$B$BGot something for nice $r if $Ghe helps Rin'ji out of here:she helps Rin'ji out of here;...$B$BRin'ji is hiding something secret at the Overlook Cliffs.",objectives={"Escort Rin'ji out of the Quel'Danil Lodge, then find his hidden secret at the Overlook Cliffs to the east."}]])
R(2743,"黑暗籠罩",[[description="Let us not mince words, $r; my time here is limited.$B$BYou must destroy the triad of power which protects the demon lord, Razelikh. Doing so will not be as simple a task as freeing a damned soul.$B$B<Kirith grins.>$B$BYou see, each of Razelikh's underlings wears a third of an amulet of Razelikh's creation around their neck. The very same amulet you will need in order to summon the arch demon.$B$BReturn to Trebor and tell him what is required to summon Razelikh. He will be able to instruct you further.",objectives={"Return to the Fallen Hero of the Horde with your findings."}]])
R(2744,"惡魔獵手",[[description="The triad is protected by Razelikh.$B$BIn exchange for their servitude, Razelikh granted each of them nearly unlimited power within the Blasted Lands. The amulet pieces are each attuned to the lifeforce of their owner, granting them immortality. As long as they remain within the Blasted Lands, they cannot be slain, their life spans extended until the end of days.$B$BThere is one who may be able to assist you further, $N. Travel to Azshara and find the demon hunter, Loramus Thalipedes. Search the islands.",objectives={"Speak with Loramus Thalipedes in Azshara."}]])
R(2745,"潛入城堡",[[description="Hmm, an interesting tale, and not one to be taken lightly. Yeah, I can help you, but what you need to do is divvy out a form of justice that's not... legal, if you're to see this through to the end.$B$BLescovar and Marzon need to be dealt with, and swiftly. Do you think you're capable of such a thing?$B$BYou decide. If so, then make haste to the castle and find an old friend of mine, a gnome named Tyrion. He's been watching Lescovar now for a couple weeks. He should be able to help you end this.",objectives={"Speak to Tyrion in Stormwind Castle."}]])
R(2746,"必備物品",[[description="Trias wants the timetable pushed up some, huh? Okay, we can do that, but I'm not ready. And know this, I'm doing the hard part, but you're the one that's going to get $g his:her; hands dirty, understand? Good.$B$BOkay, I'll need you to get me a few things before I can put my plan into effect. I got the perfect disguise that'll get Spybot past those guards.$B$BBring me some silk and a couple apples. The silk's up to you, but Clara's little farm right outside the city has the perfect sized apples.",objectives={"Bring 3 Silk Cloth and 2 of Clara's Fresh Apples to Tyrion in Stormwind."}]])
R(2747,"特別的蛋")
R(2748,"優良的蛋")
R(2749,"普通的蛋")
R(2750,"壞掉的蛋")
R(2751,"野人裝甲",[[description="Twenty generations of Omosh have held this hammer, $N. A hundred thousand tons of metal we have molded. Tragically, it all ends at Orokk, failure of the Omosh: Without kin and incapable of producing offspring.$B$BI cannot let the secret recipes of Omosh die with me! Someone must continue the legacy, Omosh or not!$B$BProve to Orokk you are capable, $N. Bring for Orokk the following: Two patterned bronze bracers, two bronze greatswords, and two sharp claws. Bring them for Orokk and we shall continue.",objectives={"Bring two Patterned Bronze Bracers, two Bronze Greatswords, and two Sharp Claws to Orokk Omosh in Orgrimmar."}]])
R(2752,"鐵肩鎧",[[description="Orokk sees the eagerness in your eyes, $N. Like a sponge you soak in the wisdom of the Omosh.$B$BThree lessons I shall teach!$B$BReturn to the anvil, soak in the heat of the forge, create for Orokk four bronze battleaxes and four bronze warhammers. Only then will you learn of the iron pauldron.",objectives={"Bring four Bronze Battleaxes and four Bronze Warhammers to Orokk Omosh in Orgrimmar."}]])
R(2753,"踩在腳下",[[description="Only two more lessons Orokk will teach, $N. Your muscles ache, I know, but continue on for the Omosh!$B$BBring to Orokk four green iron helms, four green iron bracers, and two green iron leggings - for this you learn and your enemies suffer!",objectives={"Bring four Green Iron Helms, four Green Iron Bracers, and two Green Iron Leggings to Orokk Omosh in Orgrimmar."}]])
R(2754,"瘋狂之角",[[description="The final lesson Orokk teaches you, $N. To the sacred anvil and forge you return! Bring for Orokk two solid iron mauls, two silvered bronze boots, and two silvered bronze gauntlets.$B$BSee the fear in their eyes as you approach!",objectives={"Bring two Solid Iron Mauls, two Silvered Bronze Boots, and two Silvered Bronze Gauntlets to Orokk Omosh in Orgrimmar."}]])
R(2755,"沃姆什的喜悅",[[description="Orokk is not crying, $N. Soot is in eye.$B$B<Orokk wipes a tear away.>$B$BThere is one last Omosh family secret Orokk will teach you. Orokk will die happy, thanks to $N.$B$BLearn Omosh dance of joy and then you learn fist of iron!",objectives={"Watch and learn the Omosh Dance of Joy."}]])
R(2756,"古老的技藝",[[description="In the time of legends, Aturk would crush the skulls of his enemies and grind the bone into a fine powder for use in filament. Long gone are those days, $r. The Warchief calls for peace among the clans. Old enemies are now only watched with weary eyes!$B$BUnbelievable, I know, but such is the will of Thrall.$B$BEnough lamenting! You are here to learn, and learn you will! Bring me four steel breastplates and four steel helms and you will gain a taste of war!",objectives={"Bring four Steel Breastplates and four Steel Plate Helms to Aturk the Anvil in Orgrimmar."}]])
R(2757,"藏寶海灣之旅！",[[description="Listen, kid, you're not gonna learn anything hanging around here.$B$BI know a guy who knows a guy. He hangs around the smithy in Booty Bay. If you show him this insignia, he'll tell you all about mithril.$B$BSo whadd'ya say? Leave this kid stuff to the babies in diapers, $N -- it's time to move on.$B$BIf you're interested, his name's McGavan. Show him this trinket and he'll recognize your commitment.",objectives={"Speak with McGavan in Booty Bay."}]])
R(2758,"鍛造的本源",[[description="當我像你這麼大的時候，我在一個名叫加爾文的矮人門下學習了護甲鍛造的技術。在他離開這裡前往藏寶海灣之前，曾讓我向他許諾，要幫助訓練所有決心在鍛造這門技藝上有所成就的人—所以這麼多年來我一直在這麼做。$B$B現在是時候讓你學點新東西了。給我打造六套金鱗護腕，你就會知道鍛造的起源是什麼了，$N。",objectives={"將6副金鱗護腕交給暴風城的巨錘漢克。"}]])
R(2759,"尋找加爾文",[[description="雖然加爾文很多年前就離開了藏寶海灣，但鎮子裡還有一個祕銀會的成員，希望能找到另一個值得加爾文親自授業的鐵匠。$B$B把這個徽章交給藏寶海灣的馬克迦文。$B$B我相信，如果你能見到加爾文的話，他一定會非常器重你的！",objectives={"與藏寶海灣的馬克迦文談話。"}]])
R(2760,"秘銀會",[[description="我們招募的人幾乎沒有能平安抵達藏寶海灣的，$N。即使是意志最堅定的鐵匠也難以抵擋這枚徽章的光芒，他們難免會產生私吞的貪念。他們都是傻瓜，因為與你即將得到的巨大財富相比，這枚徽章只是滄海一粟而已！$B$B去找到加爾文，把徽章交給他。他住在這裡的北面，就在祖爾格拉布和莫什奧格巨魔山之間的地方。",objectives={"和荊棘谷的加爾文談話。"}]])
R(2761,"鐵匠必修課",[[description="Many blacksmiths believe that mining and smithing are separate, independent jobs; but can there be blacksmithing without mining? Ah ha -- it is an impossibility! The accomplished blacksmith must also be an accomplished miner.$B$BShow Galvan that you are capable, $N. Bring me forty bars of iron and forty bars of mithril. For this, Galvan will teach you the ways of the ornate mithril pants!",objectives={"Bring forty Mithril Bars and forty Iron Bars to Galvan the Ancient in Stranglethorn."}]])
R(2762,"白花花的銀子",[[description="It is said that truesilver is stronger and more durable than mithril. Galvan does not disagree with this assessment of the minerals, but contrary to its name, truesilver is not true! Mithril is a far nobler mineral! HAH! Regardless, for this lesson you will need to find the great silver deceiver, $N.$B$BBring me forty bars of mithril and five bars of truesilver. In exchange, you will be taught the secret of ornate mithril gloves and more importantly, learn that truesilver is a liar!",objectives={"Bring forty Mithril Bars and five Truesilver Bars to Galvan the Ancient in Stranglethorn."}]])
R(2763,"灌魔工藝",[[description="The harvesting of precious gems is of utmost importance to our craft, $N. Few gems are more precious than the citrine. The magical properties we imbue into our goods are amplified greatly by the presence of citrine.$B$BFor this lesson, we will fortify forty bars of mithril with four citrines. The result will be a better understanding of magical gemology and the knowledge to create ornate mithril shoulders.",objectives={"Bring forty Mithril Bars and four Citrines to Galvan the Ancient in Stranglethorn."}]])
R(2764,"加爾文的得意門生",[[description="If you are ready to conclude your training with Galvan, you should journey to Gadgetzan.$B$BThere, you will find my finest pupil: Trenton Lighthammer. He has much to teach you in the ways of ornate mithril. Otherwise, remain here and learn!$B$BOh, Gadgetzan is in Tanaris, of course!",objectives={"Speak with Trenton Lighthammer in Gadgetzan."}]])
R(2765,"鍛造專家!",[[description="When you first came to me, I knew that you would turn out to be one of my finest pupils! It was without hesitancy that you gave up a trinket of some power to McGavan. You did this only so that you could meet me. Such blind faith and devotion to the craft should be rewarded.$B$BYou have attained expertise over blacksmithing, $N. Reap the rewards!",objectives={"Claim your reward from Galvan the Ancient!"}]])
R(2766,"尋找OOX-22/FE！",[[description="你發現了一個奇怪的蛋形金屬物體。隨便撥弄了幾下之後，它居然自動打開了，變成了一個看來是由地精製造的機器裝置！一個奇怪的聲音從這個蛋形機器裝置中傳了出來。$B$B「我的名字叫奧格索普，我的母體機器人不見了！如果你能幫我找到它，我就會獎勵你的！請把這個定向器帶到那個母體機器人那裡。別擔心，我現在已經檢測到了它的所在地！它現在就位於深痕谷中的一個山洞裡！」",objectives={"把定位器帶到深痕谷附近山洞中的奧格索普的導航機器人旁邊。"}]])
R(2767,"拯救OOX-22/FE！",[[description="那個地精的聲音再次從那個機器人中傳了出來：$B$B「我需要你幫忙把OOX-22/FE移動到一個安全的開闊地，這樣它才可以啟動起飛程式。它自帶隱形系統，但是我需要一點時間來遠端啟動這個系統。請你把這個機器人從現在的位置護送到被遺忘的海岸去！那裡是個非常理想的起飛點，有足夠的空間作為機器人起飛的跑道！」$B$B「將它護送到那裡，然後再到藏寶海灣來找我！奧格索普·奧布諾提斯——完畢！」",objectives={"將OOX-22/FE護送到被遺忘的海岸上的碼頭，然後向藏寶海灣的奧格索普·奧布諾提斯報告。"}]])
R(2768,"探水棒",[[description="布萊中士偷了我的東西！他說只是借一下，但那混蛋卻偷了我寶貴的探水棒！沒有這根棒子，我就不知道該在哪裡打井找水！$B$B去找到布萊，把我的探水棒拿回來！我聽說他帶著一幫惡名遠揚的冒險者去了西邊的祖爾法拉克古城尋寶，你肯定可以在那裡找到他。$B$B但願那裡的食人妖已經把他幹掉了，因為如果你必須打敗他才能拿回探水棒的話，那必將是一場惡仗。",objectives={"把探水棒交給加基森的首席工程師沙克斯·比格維茲。"}]])
R(2769,"銅栓兄弟",[[description="你有沒有遇見銅栓兄弟？他們在卡林多的閃光平原上與哥布林賽車，而且他們通常都會獲得勝利，這並不奇怪——哥布林的賽車輪胎總是爆掉，他們幾乎從來都沒有完成過比賽！$B$B但即使是這樣，銅栓兄弟也還是在尋找新的方法使他們的車速更快，維茲爾跟我說過，他的下一個實驗需要一種很稀有的原料。$B$B或許他需要別人的幫助來獲取這種原料，你去和他談談就知道了。",objectives={"和閃光平原的維茲爾·銅栓談話。"}]])
R(2770,"加茲瑞拉",[[description="在塔納利斯沙漠的食人妖古城祖爾法拉克深處，有一個神聖的池塘。食人妖可以從那個池塘裡召喚一頭巨大的野獸——加茲瑞拉！它兇猛異常，甚至連它的鱗片都會因為巨大的能量而發出聲響。我要用它的能量來給我的賽車增加動力！$B$B把加茲瑞拉的鱗片給我弄來！$B$B不過，召喚加茲瑞拉的方法是食人妖的秘密。如果你想要面對加茲瑞拉的話，首先就要從食人妖那裡弄到召喚它的方法。",objectives={"把加茲瑞拉的鱗片交給閃光平原的維茲爾·銅栓。"}]])
R(2771,"罩帽和護肩",[[description="It seems as if master had this planned from the start. I was not taught to create the items which you learned to create and you were not taught the items which I learned to create.$B$BThe master is wise, $N. We shall teach each other!$B$BShow me how to make a mithril coif and ornate mithril shoulders and I shall show you how to create an ornate mithril helm.",objectives={"Bring two Mithril Coifs and one Ornate Mithril Shoulder to Trenton Lighthammer."}]])
R(2772,"世界在妳腳下",[[description="At last year's All-Valley Blacksmithing Championship, all those who watched saw my leg get swept from under me by a cowardly dog from the Venture Co. Foundry. What they didn't know, however, was the reason I was able to continue and ultimately win the tournament: That's right, ornate mithril boots!$B$BI will need to learn how to craft ornate mithril pants for this year's tournament, however, as a Venture Co. shredder is an entrant! Teach me the way of the pants and learn the way of the boot!",objectives={"Bring two Heavy Mithril Boots and one Ornate Mithril Pants to Trenton Lighthammer."}]])
R(2773,"秘銀小子",[[description="Around these parts I am known as the Mithril Kid. I supply ornate mithril to adventurers from around the world.$B$B<Trenton whispers.>$B$BLittle do they know that I do not know the technique to fashion ornate mithril gloves. Shhhh! This will be our little secret.$B$BTeach me the technique to create ornate mithril gloves, $N, and in exchange, I will show you the resultant of the culmination of my training under Galvan: the ornate mithril breastplate.",objectives={"Bring two Heavy Mithril Breastplates and one Ornate Mithril Gloves to Trenton Lighthammer."}]])
R(2781,"通緝：卡利夫·斯科比斯汀",[[description="通緝：卡利夫·斯科比斯汀！$B$塔納利斯的加基森水力公司願支付高價懸賞廢墟歹徒首領卡利夫·斯科比斯汀的項上人頭。他的罪行包括：$B$B1. 殺害加基森水力公司的雇員！$B2. 偷竊加基森水力公司的資源！$B3. 搶劫加基森水力公司的財產！$B$B將卡利夫·斯科比斯汀的死亡證明交給首席工程師沙克斯·比格維茲，我們將立刻兌現你的獎賞！",objectives={"將卡利夫·斯科比斯汀的頭顱交給加基森的首席工程師沙克斯·比格維茲。"}]])
R(2782,"林吉的秘密",[[description="The tablet is covered with Witherbark troll markings. Rin'ji's secret truly is a mystery... $B$BIt's possible that you might have something quite valuable on your hands here. On the other hand, quite the opposite is also possible. A Witherbark troll in distress would probably do anything to find his way out of trouble...",objectives={"Oran Snakewrithe, a well known scholar on matters concerning the Witherbark trolls, may be able to decipher the tablet. She is known to reside within the Magic Quarter of the Undercity."}]])
R(2783,"爭論",[[description="我們在和錯的敵人進行戰鬥，$N。$B$B這片土地上真正強大的力量正在不斷增強，而我們卻還在和獸人為了這片焦土進行無謂的爭鬥。$B$B我們難道要繼續和部落爭鬥，直到有一天讓燃燒軍團把我們都踏扁嗎？這實在是一種愚蠢的行為。$B$B$N，拋開你的偏見，和部落英雄的靈魂談談吧。他知道詛咒之地真正的秘密。",objectives={"與詛咒之地和悲傷沼澤交界處的部落英雄的靈魂談話。"}]])
R(2784,"失落的榮耀",[[description="Hear my story, $r.",objectives={"Listen to the Fallen Hero of the Horde tell his story."}]])
R(2801,"悲傷的故事",[[description="Before we may continue, you must hear my story.",objectives={"Listen to the Fallen Hero of the Horde tell his story."}]])
R(2821,"質量的保證",[[description="我對於皮革製作的哲學是要做就做最好——沒有商量餘地。任何說品質不要緊的人都是想要把丹莫洛的那些水貨賣給你！$B$B在尋求高品質材料的過程中，我接觸到了厚重的雪人皮。雪人是菲拉斯土生土長的一種生物，大多在深痕谷活動。我需要一些它們的皮，如果你給我十張的話，我可以讓你在我的皮貨中選一件。如果你覺得聽起來還算公平，那我們就成交了吧。",objectives={"給羽月要塞的普拉特·馬克格魯比帶去10張厚重的雪人皮。"}]])
R(2822,"質量的保證",[[description="I take pride in my leather work, and I feel it shows; quality should never be compromised.  Anyone who says that quality doesn't matter would also have you believe that the earth does not keep secrets!$B$BIn my latest pursuit of high-quality materials, I have discovered thick yeti hides.  Yetis are native to Feralas, often found west of here in Feral Scar Vale.  I'll give you a choice of one of my leather goods for a stack of ten.  If that is agreeable to you, then we are set!",objectives={"Bring 10 Thick Yeti Hides to Jangdor Swiftstrider in Camp Mojache."}]])
R(2841,"設備之戰",[[description="地精的技術——兩年前它最普遍的用途是被當作笑話，但是時代確實變了，現在他們建造的新型鑽探設備比我們所有伐木機加起來都要精密。我需要它的設計圖，$N！$B$B不幸的是，這些設計圖被鎖在麥克尼爾·瑟瑪普拉格身邊的一隻保險箱裡了。更糟的是，保險箱的密碼只有麥克尼爾·瑟瑪普拉格一人知道。$B$B盡你所能得到那個密碼，$N。把設計圖給我帶回來！",objectives={"從諾姆瑞根拿到鑽探設備藍圖和麥克尼爾的保險箱密碼，把它們交給奧格瑪的諾格。"}]])
R(2842,"主工程師斯庫提",[[description="As soon as we got word from Kernobee about the new gnomish rig, Scooty and I began work on the Transpolyporter 6000: The fastest and most reliable way to Gnomeregan.$B$BIt's finally ready for passengers to board, $N. If you want to give it a try, go to Booty Bay and talk with Scooty at the wind rider roost. To get to Booty Bay, take the boat from Ratchet.$B$BOf course, you could always try and make the run to Gnomeregan through the dwarf infested mountains of Dun Morogh!",objectives={"Speak with Scooty in Booty Bay."}]])
R(2843,"出發！諾莫瑞根！",[[description="As long as you have the transponder in your possession, all you need to do is step on the pad and you'll be teleported to Gnomeregan.$B$BYou may experience some unusual side effects, but none of those should be permanent... anymore.$B$BI almost forgot the most important part - getting back. When you're ready to come back, just step on the transpolyporter pad in Gnomeregan!$B$BNow to calibrate the transponder to your size and weight.",objectives={"Wait for Scooty to calibrate the Goblin Transponder."}]])
R(2844,"大保姆",[[description="都是我不好，$N。我本應細心照顧我的小朋友，沙恩。但是不知道為什麼，她離開了我。我並不十分清楚發生了什麼事，真的，但我最後一次看到她的時候，我們正在穿越這裡北面的廢墟。$B$B一切都很正常，但我轉過身一看……她就不見了。$B$B現在我不知道該怎麼辦了。你有辦法嗎，$N？我很擔心。$B$B嘿，你幫我去找沙恩怎麼樣？你看起來應該比我跑得快一些。",objectives={"尋找走丟了的精靈小姑娘。"}]])
R(2845,"迷路的沙恩",[[description="Do you think you could help me find my way back to my friend, Rockbiter? He was supposed to be watching me... But I do have a tendency to wander off now and then. There are just so many things to see, and I get so distracted.$B$BThere is one thing that will always work to get my attention, though.$B$BInside this chest, you'll find a bell that is very precious to me. I just love the sound of it. You have my word, if I wander off, all you have to do is ring it and I'll come running back.",objectives={"Pick up Shay's Bell from the chest.$B$BEscort Shay Leafrunner to Rockbiter's camp."}]])
R(2846,"深淵皇冠",[[description="很久以前我曾經擁有一件美麗的珍寶，深淵皇冠。它不僅美麗——而且它對於知道怎麼使用它的人來說更是一件擁有巨大力量的寶貝。$B$B所以當水占師維蕾薩聽說皇冠的事情之後，她就發誓要得到它。維蕾薩派人在我外出的時候到我家來偷走了皇冠，這些卑鄙的小偷！$B$B我要取回我的皇冠！到位於塔納利斯沙漠中的食人妖城市祖爾法拉克去，把皇冠從她手上搶回來。把它還給我，你會得到報酬的。",objectives={"將深淵皇冠交給塵泥沼澤的塔貝薩。"}]])
R(2847,"蠻皮護甲",[[description="$n, you're becoming quite skilled as a leatherworker!  I know some patterns you might be interested in... Wild Leather armor!  Wild Leather taps into the potent and chaotic properties of wildvines, found in areas of lush vegetation and on some of the creatures there.  The armor made using it is second to none for people of your skill, guaranteed.$B$BI'll teach this to you, but you'll be working for me for a while.  The first cost is simply ten pieces of thick leather.  After this, we'll talk specifics.",objectives={"Bring 10 Thick Leather to Pratt McGrubben in Feathermoon Stronghold."}]])
R(2848,"蠻皮護肩",[[description="Wild Leather shoulders support the wearer's frame extremely well, offering top notch protection of the upper arms and the shoulders themselves.  As with all Wild Leather armor, a potent but random benefit is applied to the item as the wildvine is stitched in.$B$BFor this pattern, I will require six thick armor kits and a wildvine.  That shouldn't be too tall of an order for you to fill.",objectives={"Bring 6 Thick Armor Kits and a Wildvine to Pratt McGrubben in Feathermoon Stronghold."}]])
R(2849,"蠻皮外衣",[[description="Wild Leather vests are the staple of any Wild Leather armor set.  The frame of the vest blends with the wildvine to produce a product that offers maximum protection of the torso while allowing for the potent magic to work its way through the garment.$B$BFor this pattern, I will require two Turtle Scale breastplates, two sets of Turtle Scale gloves, and a wildvine.  It's a tall order, but one you should have little difficulty in filling for me.",objectives={"Bring 2 Turtle Scale Breastplates, 2 Turtle Scale Gloves, and a Wildvine to Pratt McGrubben in Feathermoon Stronghold."}]])
R(2850,"蠻皮頭盔",[[description="A Wild Leather helmet offers the wearer superior protection to the vital areas of the head without a sacrifice in comfort.  As with all Wild Leather armor, the integrated wildvine yields a powerful but random enhancement to the frame of the helm.  Leather wearers will definitely want this piece!$B$BFor this pattern, I will need two Nightscape tunics, two Nightscape headbands, and a wildvine.  Complete this order and the pattern will be yours!",objectives={"Bring 2 Nightscape Tunics, 2 Nightscape Headbands, and a Wildvine to Pratt McGrubben in Feathermoon Stronghold."}]])
R(2851,"蠻皮戰靴",[[description="You've learned quite a bit now, $n; still, there is more for you to learn.  Next are Wild Leather boots, the cornerstone of any set.$B$BThese boots are crafted to cradle the foot in comfort while bracing it against the hazards of adventuring.  The soft soles are a blessing to those seeking quiet movement in footwear.$B$BFor this pattern, I need an order of two Nightscape pants and two Nightscape boots filled.  I also will require two wildvines... not just one.  When you have all this, let me know.",objectives={"Bring 2 Nightscape Pants, 2 Nightscape Boots, and 2 Wildvines to Pratt McGrubben in Feathermoon Stronghold."}]])
R(2852,"蠻皮護腿",[[description="With the basics down, you are ready to master more complex fare, $n.  Wild Leather leggings are some of the sturdiest and powerful leather gear around.  The waist, thighs, calves, and the vitals - all are given tremendous protection.  Coupled with the enhancement that the wildvine provides, adventurers who own it will thank you each time they see you.$B$BFor this pattern, I need an order of two Turtle Scale helms, two Turtle Scale bracers, and two wildvines filled.",objectives={"Bring 2 Turtle Scale Helms, 2 Turtle Scale Bracers, and 2 Wildvines to Pratt McGrubben in Feathermoon Stronghold."}]])
R(2853,"蠻皮護甲大師",[[description="Well $n, you are the definition of diligence.  There is one pattern left for Wild Leather armor; you've mastered the others.  I won't require you to toil needlessly for the pattern.  You've earned it outright, and then some... but I cannot give it to you myself.  My teacher, the one who brought me into the craft, is the one who must reward you.$B$BTake this letter to Telonis; he teaches leatherworking in Darnassus.  Show him the letter, and let him acknowledge you as an equal, as I do.",objectives={"Give Pratt's Letter to Telonis, the master leatherworker of Darnassus."}]])
R(2854,"蠻皮護甲",[[description="$n, your skill as a leatherworker precedes you.  I possess leatherworking lore you would be wise to acquire... Wild Leather armor!  Wild Leather taps into the potent and chaotic properties of wildvines, found in areas of lush vegetation and on some of the creatures there.  Armor made using it is second to none for a crafter of your skill, guaranteed.$B$BI'll teach you, but you'll be working for me for a while.  The first cost is simply ten pieces of thick leather.  After this, we'll talk specifics.",objectives={"Bring 10 Thick Leather to Jangdor Swiftstrider in Camp Mojache."}]])
R(2855,"蠻皮護肩",[[description="Wild Leather shoulders support a wearer's frame extremely well, offering superior protection of the upper arms as well as the shoulders.  As with all Wild Leather armor, a random yet very potent enhancement is imbued within the item as the wildvine is stitched in.$B$BFor this pattern, I will require six thick armor kits and a wildvine.  That shouldn't be too tall of an order for you to fill.",objectives={"Bring 6 Thick Armor Kits and a Wildvine to Jangdor Swiftstrider in Camp Mojache."}]])
R(2856,"蠻皮外衣",[[description="Wild Leather vests are the staple of any Wild Leather armor set.  The frame of the vest and the wildvine weave within it produces a product that offers maximum protection of the torso while allowing for potent magic to work its way through the garment.$B$BFor this pattern, I will require two Turtle Scale breastplates, two sets of Turtle Scale gloves, and a wildvine.  This is not an easy lesson, but it is one you certainly have the skill to complete.",objectives={"Bring 2 Turtle Scale Breastplates, 2 Turtle Scale Gloves, and a Wildvine to Jangdor Swiftstrider in Camp Mojache."}]])
R(2857,"蠻皮頭盔",[[description="A Wild Leather helmet offers the wearer superior protection to the vital areas of the head without a sacrifice in comfort.  As with all Wild Leather armor, the integrated wildvine yields a powerful but random magic imbuement to the helm's frame.  Leather wearers will definitely want this piece!$B$BFor this pattern, I will need two Nightscape tunics, 2 Nightscape headbands, and a wildvine.  Complete this lesson and the pattern will be yours!",objectives={"Bring 2 Nightscape Tunics, 2 Nightscape Headbands, and a Wildvine to Jangdor Swiftstrider in Camp Mojache."}]])
R(2858,"蠻皮戰靴",[[description="Your knowledge of Wild Leather armor grows, $n; still, there is more for you to learn.$B$BWild Leather boots are the cornerstone of any set.  Such boots are crafted to cradle the foot in comfort while bracing it against the hazards of adventuring.  The soft soles are a blessing to those seeking quiet movement in footwear.$B$BFor this pattern, I need two Nightscape pants and two Nightscape boots crafted.  I also will require two wildvines... not just one.  When you have these items, we will proceed.",objectives={"Bring 2 Nightscape Pants, 2 Nightscape Boots, and 2 Wildvines to Jangdor Swiftstrider in Camp Mojache."}]])
R(2859,"蠻皮護腿",[[description="You are ready to master more complex lessons, $n.  Wild Leather leggings are some of the sturdiest and powerful leather gear around.  The waist, thighs, calves, and the vitals - all are given tremendous protection.  Coupled with the enhancement that the wildvine provides, adventurers who own it will thank you each time they see you.$B$BFor you to gain this pattern, I need two Turtle Scale helms, two Turtle Scale bracers, and two wildvines.",objectives={"Bring 2 Turtle Scale Helms, 2 Turtle Scale Bracers, and 2 Wildvines to Jangdor Swiftstrider in Camp Mojache."}]])
R(2860,"蠻皮護甲大師",[[description="$n, you have learned all I am able to teach you.  There is, however, one remaining pattern for Wild Leather armor.  I will not require you to toil needlessly for this; you've earned it outright, and then some.  This pattern, however, is one that I cannot freely share with you.$B$BMy teacher, the one who brought me into the craft, is the one who must reward you.  Take this note to Una; she teaches leatherworking in Thunder Bluff.  Show her the letter, and let her acknowledge you as an equal, as I do.",objectives={"Give Jangdor's Letter to Una, the master leatherworker of Thunder Bluff."}]])
R(2861,"塔貝薩的任務",[[description="據說有個名叫塔貝薩的法師想要某個祖爾法拉克食人妖的命。如果你去找塔貝薩的話，她會讓你知道詳情的。$B$B別忘了帶幾個夥伴，$N。如果塔貝薩真的讓你去祖爾法拉克的話，你最好不要獨自前往。$B$B塔貝薩的小屋就在塵泥沼澤裡，準確地說，是在塞拉摩的西邊，石槌廢墟的北邊。",objectives={"與塵泥沼澤的塔貝薩談話。"}]])
R(2862,"與豺狼人開戰",[[description="The gnolls... they are more than a nuisance.  They are a constant threat to the existence of this very camp!  It is irrelevant whether they are indigenous to Feralas or not; if we do not strengthen our resolve against them, we will find ourselves driven out of the entire region.$B$BThe gnoll attacks against the camp have become more fevered as of late.  We need your aid in thinning their numbers; bring to me ten of their manes, and I will reward you handsomely for your effort.$B$BGo!",objectives={"Bring 10 Woodpaw Gnoll Manes to Hadoken Swiftstrider in Camp Mojache."}]])
R(2863,"突然襲擊",[[description="The plan is for various leaders of the gnolls - Alphas as they call themselves - to be taken down within rapid succession.  If we're able to execute this sort of swift and precise devastation against them, it would cause chaos in their ranks.  Perhaps it would also drive a message through their thick flea-bitten heads that we can and will destroy them!$B$BI want you to be the messenger of my will; eliminate five of their Alphas within one hour for this to work $N, or we'll remain at this impasse!",objectives={"Kill 5 Woodpaw Alphas and return to Hadoken Swiftstrider within one hour."}]])
R(2864,"特蘭雷克",[[description="我的兄弟特蘭雷克現在顯然處於困境中。幾個星期之前他曾經向我承諾會給我一批聖甲蟲的殼，但是至今為止我還沒有收到。他是我的兄弟，所以我可不想派人去加基森砸他的場子。$B$B你能幫我去問問特蘭雷克到底是怎麼回事嗎？在我真的發飆之前他最好快點把貨給我送來。$B$B加基森就在卡林多大陸上的塔納利斯沙漠北部。",objectives={"與加基森的特蘭雷克談話。"}]])
R(2865,"聖甲蟲的殼",[[description="塔納利斯這裡的聖甲蟲的殼都很硬！硬得足可以給好多東西當建築材料，好多東西！$B$B事實上，因為那些殼都太有用了……聖甲蟲已經被獵殺得近乎滅絕了！$B$B我知道哪裡有更多的聖甲蟲，如果你保證會給我弄些殼來，我就告訴你它們在哪裡。你保證嗎？$B$B好吧，祖爾法拉克裡面有許多聖甲蟲，我想食人妖們並不因為想要那些殼而獵殺它們。$B$B但你可以！到祖爾法拉克去給我弄些完好無損的殼回來！",objectives={"帶5個完整的聖甲蟲殼給加基森的特蘭雷克。"}]])
R(2866,"索蘭薩爾廢墟",[[description="在我們的南邊就是索蘭薩爾廢墟，那個地區的歷史相當悠久。我們探索過那個遺跡，沒有發現什麼特別值得注意的東西，所以我們就離開了。$B$B最近，憎世納迦佔據了那片遺跡，而且他們的數量已經多到了讓我們不得不警惕的程度。一開始我們認為那些納迦是準備對我們發起攻擊，雖然這種可能性現在依然存在，但我們覺得他們可能是有什麼別的目的。$B$B現在就到那片廢墟去查看一番吧，祝你好運，$n。",objectives={"探索索蘭薩爾廢墟，並調查納迦在那個地區的情況。"}]])
R(2867,"返回羽月要塞",[[description="在索蘭薩爾廢墟的心臟地帶發現了奇怪的瞭望台之後，你覺得應該馬上回到羽月要塞去向珊蒂斯·羽月彙報這個發現。",objectives={"向羽月要塞的珊蒂斯·羽月彙報你的發現。"}]])
R(2868,"<TXT> The Shriveled Heart",[[description="Turn this badboy into some troll tomb in the Sunken Temple, and get something cool!"]])
R(2869,"憎世納迦之戰",[[description="我們認為，無論納迦想要幹什麼，他們最終的目的無非是完全佔據這座島嶼，由此我們制定了相應的行動計畫。我們要儘早採取攻擊行動來消除這種威脅，否則就可能全盤皆輸。$B$B給我帶來十塊完整的憎世納迦的鱗片——你應該知道如何獲得這東西。這樣一來，納迦在薩爾多島上的力量就被大大削弱了，這對我們是非常有利的。",objectives={"收集10塊憎世納迦的鱗片，把它們交給羽月要塞的拉托尼庫斯·月矛。"}]])
R(2870,"擊敗沙爾紮魯",[[description="$n，新的偵查報告讓我們對納迦部隊的組成有了一個更清晰的概念。納迦的皇室成員在他們的部隊中具有最高的權威性。$B$B皇室成員中的沙爾札魯是個極端殘酷的納迦，偵查報告表明最近他在南部的遺跡中發現了一塊奇怪的古代聖物，那個地方就在恐怖之島那裡。$B$B你的任務就是結束他，然後把那塊聖物給我帶回來進行研究。",objectives={"消滅沙爾札魯，然後把神秘聖物交給羽月要塞的拉托尼庫斯·月矛。"}]])
R(2871,"遞送遺物",[[description="如果你能幫我將這個東西送給我的妻子維斯提亞，那我會非常感激的。她不僅是我們這裡的女祭司，也會是你所見過的最博學的學者之一。我即使抓破頭皮也搞不清楚這個東西到底是什麼，可我的妻子不同，如果世界上有人能知道這東西是什麼，那無疑就是她了……我們也迫切地需要知道真相！$B$B拜託了，$n。",objectives={"將神秘聖物交給羽月要塞的維斯提亞·月矛。"}]])
R(2872,"斯杜雷的債務",[[description="我的老朋友欠我一瓶特殊的朗姆酒。他在塔納利斯沙漠的熱砂港裡經營著一家酒吧，他向我保證說，那裡的朗姆酒絕對比藏寶海灣的任何酒都要香醇，還說如果我喝了他的酒不滿意的話，那他就會雙倍奉還他欠我的錢！$B$B好吧，我想他現在已經不像他上次說這話的時候那麼自信了，他害怕給我嘗他的朗姆酒了。但是我還是想繼續這個賭注，那麼你就替我去和他談談吧……",objectives={"與熱砂港的斯杜雷談話。"}]])
R(2873,"斯杜雷的貨物",[[description="我欠藏寶海灣的「海狼」馬克基雷一些朗姆酒，那是打賭輸的，但我現在一瓶朗姆酒都沒有了！科爾戈船長偷了我最後一船貨，他把它們藏在南邊的那個戒備森嚴的海盜鎮裡。$B$B如果你能找到我的那批朗姆酒並把它們給我拿回來的話，那我就可以向馬克基雷證明，藏寶海灣的那些酒跟我的朗姆酒比起來只能被稱作垃圾！",objectives={"將斯杜雷的貨物交給加基森的斯杜雷。"}]])
R(2874,"給馬克基雷的貨物",[[description="Thanks again for your help, $N.  Here's a bottle of Steamwheedle bilge rum.  Take it to MacKinley and he can finally put to rest his crazy beliefs about Booty Bay booze.",objectives={"Bring Stoley's Bottle to \"Sea Wolf\" MacKinley in Booty Bay."}]])
R(2875,"通緝：安德雷·費爾比德",[[description="可惡的海盜安德雷·費爾比德因對熱砂港和加基森所犯的罪行正被通緝。$B$B根據政府討論所發佈的決議，任何閱讀這則通緝令的人，有權在逮捕安德雷和他的同黨過程中採取可能致其死亡的手段。$B$B進一步的決議裁定，如在審訊期間，安德雷死了或病了，他的人頭可以作為代替品，將它交給安全主管吉羅姆·比格維茲仍可使這份通緝令生效。",objectives={"將安德雷的頭顱交給熱砂港的安全主管吉羅姆·比格維茲。"}]])
R(2876,"船運時刻表",[[description="這卷軸上面記載著熱砂港和藏寶灣之間的船運時刻表，包括過去和未來計畫中的船運批次和船名，一些船的旅程旁有個大大的紅叉記號，剩下的旁邊有類似「華麗的戰利品」和「堅固的戰艦」之類的字樣。$B$B熱砂港那裡的人一定非常想看看這個文件。",objectives={"把船運時刻表交給熱砂港的某個官員。"}]])
R(2877,"清理隱匿石",[[description="比起那些鐵爐堡的兄弟們來，我們蠻錘部族對於過去曾發生過的事情有著更加深刻的記憶。如果你想在這裡交朋友的話，那麼你就要證明給我們看！$B$B部落的蠻子們從隱匿石一帶撤了出去，現在那裡滿地都是淤泥怪。我們想要佔領那個地區，不過首先我們要找些人來幫我們清理一下惱人的淤泥怪。$B$B這就是你要做的事情了！到那邊去幹掉十個綠色淤泥怪和十個玉石軟泥怪，然後回到這裡來向我報告。快出發吧!",objectives={"殺掉10個綠色淤泥怪和10個玉石軟泥怪，然後回到鷹巢山向弗拉加爾報告。"}]])
R(2878,"被腐化的輕歌花")
R(2879,"艾奎尼克斯法杖",[[description="This stave might be the Stave of Equinex! The Stave of Equinex is actually a key, used to unlock the Equinex Monolith in the Ruins of Ravenwind, on the mainland west of the Dream Bough.$B$BFind the four flames that still burn in those ruins: Samha, Imbel, Byltan, and Lahassa. Retrieve their essence and then while standing by the Equinex Monolith, use the essences to energize the stave. If this is truly is the Stave of Equinex, you will be able to unlock the Monolith and gather a sacred artifact from it.",objectives={"Energize Troyas' Stave and find the Equinex Monolith."}]])
R(2880,"巨魔部族項鏈",[[description="直接說吧，$c——我們不屬於聯盟！蠻錘部族是獨立的，我們依靠自己所做的事情來證明自己的價值，不像那些只會說廢話的傢伙一樣，用閒聊來掩飾自己什麼都不想做的態度！$B$B如果你要和我們作朋友，那麼首先向我們證明你的價值！那些遍佈辛特蘭的食人妖有時會帶著他們部族的項鏈。給我帶五條項鏈過來作為友好的證明吧！",objectives={"給鷹巢山的弗拉加爾帶去5條食人妖部族項鏈。"}]])
R(2881,"巨魔部族項鏈")
R(2882,"科爾戈的黃金",[[description="這張地圖上畫著一條對著南方的海灘，圖下方用優雅的字體寫著……$B$B$B熱砂港南邊$B家的南邊$B找到骨頭，旗子和旗杆$B如果你夠膽，就去挖挖看$B挖挖看啊，科爾戈的金子閃亮亮！$B開箱需鑰匙，鑰匙你會看見$B你面對的要用血來做交換。",objectives={"找到科爾戈的黃金！"}]])
R(2902,"調查木爪嶺",[[description="Gnolls aren't the sharpest tools in the shed, but they will no doubt have some sort of documented strategy on their recent activity.  If we were to find those plans, then we'd have a clearer idea of what is making them so worked up.$B$BI want you to head back to the Woodpaw and find anything that might resemble their battle plans.  They have to have something; their attacks have been too coordinated to be done without them.  Find them, and return to me when you have them.",objectives={"Find the gnoll battle plans somewhere in the gnoll camps to the south of Camp Mojache."}]])
R(2903,"作戰計劃",[[description="With the battle plans of the gnolls discovered, all that now remains is to bring the plans back to Hadoken Swiftstrider in Camp Mojache.  Perhaps he or someone there can make further sense of what the gnolls are up to.",objectives={"Bring the Woodpaw Battle Plans to Hadoken Swiftstrider in Camp Mojache."}]])
R(2904,"壹團混亂",[[description="<克努比呻吟著。>發……發生什麼事了？$B$B我只記得自己被一群黑鐵矮人抓住，他們揍了我一頓，把我跟這些醜陋的穴居人扔在一塊兒。$B$B快救我出去，$N！$B$B我有個計畫：把我帶到出口；如果我們能活著走出去的話，你就到藏寶海灣去，告訴斯庫提我去了棘齒城，然後警告廷克維斯，黑鐵矮人準備製造超強的鑽探設備。$B$B讓我們開始吧！",objectives={"將克努比護送到發條小徑的出口，然後向藏寶海灣的斯庫提彙報。"}]])
R(2922,"拯救尖端機器人！",[[description="當我們摯愛的諾姆瑞根城淪陷時，我可憐的發明——尖端機器人——受到了某種致命的打擊。它原本包含了很多精巧的設計，並且儲存了大量的資訊，憑藉這些，它無數次地幫助了我和我的同事，但現在它的正電子腦被極化，變成了負電子腦……尖端機器人的行為已經變得完全異常了。它像個瘋子似的在諾姆瑞根裡咆哮！$B$B也許我們仍然可以挽救它，如果你能找回尖端機器人的記憶體核心並把它交給我，那麼我就能找到故障的原因，然後把我可憐的尖端機器人修好。$B$B",objectives={"將尖端機器人的記憶體核心交給鐵爐堡的工匠大師歐沃斯巴克。"}]])
R(2923,"工匠大師歐沃斯巴克",[[description="工匠大師歐沃斯巴克正在為他發明的尖端機器人的命運感到沮喪。我記得尖端機器人對地精來說是一種很友好的輔助工具，但歐沃斯巴克告訴我，它出了故障。$B$B我很難過，不過如果運氣不錯的話，也許他還可以修好尖端機器人！$B$B去跟鐵爐堡地精區的工匠大師歐沃斯巴克談談吧，看到有你這樣的$c想要幫助他，他會很高興的。",objectives={"與鐵爐堡的工匠大師歐沃斯巴克談話。"}]])
R(2924,"基礎模組",[[description="有一種通用型的機械部件——基礎模組——對於諾姆瑞根的技師和鐵匠來說都非常重要，不過在我們大舉逃出諾姆瑞根的時候，誰也沒想起要把這些東西帶上！我手頭上的工作需要大量這種部件。$B$B請去諾姆瑞根給我拿一些基礎模組回來，它們就裝在城市深處的機械儲存櫃裡。$B$B謝謝你，$N，請儘快出發吧！",objectives={"收集12個基礎模組，把它們交給鐵爐堡的科勞莫特·鋼尺。"}]])
R(2925,"幫助科勞莫特",[[description="A gnome friend, Klockmort Spannerspan, sent word to me from Ironforge.  He tells me he needs help on a dangerous, but essential, mission into Gnomeregan, the once great gnome city now contaminated and filled with mad gnomes and their devices.$B$BI must stay here, but my heart aches to help my friend.  If you can go in my stead, then I would be much indebted to you.$B$BYou may find Klockmort in Tinkertown, in Ironforge.",objectives={"Speak with Klockmort Spannerspan in Ironforge."}]])
R(2926,"諾恩",[[description="事故後，諾恩想的說的都離不開兩個主題：如何將石齶怪趕出諾姆瑞根，以及如何為席捲諾姆瑞根的瘟疫找到治療的方法。$B$B幸運的是，拉茲和我已經快要研究出一種治療方法了——要不然就是一種很強勁的朗姆酒的配方。我們要試過才知道！當然，為了檢驗我們的理論是否成立，我們需要一些東西，準確地說，是諾姆瑞根城裡那些石齶怪身上的輻射塵。用這個小瓶子裝一些泛著綠光的輻射塵，然後把它帶回來！",objectives={"用空鉛瓶對著輻射入侵者或者輻射搶劫者，從它們身上收集放射塵。瓶子裝滿之後，把它交給卡拉諾斯的奧齊·電環。"}]])
R(2927,"災難之後",[[description="你不會認為我生來就是個禿子吧？事實不是這樣的，$g先生:女士;！諾姆瑞根的放射性外洩導致我悲劇性的脫髮。在那之前，我有著整個艾澤拉斯世界獨一無二的地精式飛機頭！$B$B<諾恩一邊說一邊揮舞著拳頭>$B$B那些該死的穴居怪——他們都該死！！$B$B或許現在還不晚，$N。我們也許仍然可以挽回局勢——我說的是這座城市！去跟卡拉諾斯的奧齊·電環談談吧，他和他夥伴拉茲正在想辦法。",objectives={"與卡拉諾斯的奧齊·電環談話。"}]])
R(2928,"陀螺式挖掘機",[[description="太糟糕了，$N。我們沒有足夠的零件讓我們的陀螺式挖掘機部隊進入丹莫洛。$B$B我們需要的是零件，$N，更多的零件。說到尋找零件，難道還有比諾姆瑞根更好的地方嗎？我聽說那裡的機器人像牧區的牛似的到處遊蕩。$B$B我要你做的就是到諾姆瑞根去，把這些機器人拆開，拿出它們的內部裝置。給我弄兩打來就夠了。",objectives={"收集24副機械內膽，把它們交給暴風城的舒尼。"}]])
R(2929,"大叛徒",[[description="我以前曾經非常信任麥克尼爾，我從未想過他會背叛我和所有地精同胞。他為什麼要背叛我們？為了權力？為了金錢？這些東西只要加以時日他都可以擁有。現在我們背井離鄉，那個瘋子掌握了政權，成了個什麼都沒有的國王……$B$B我們要奪回諾姆瑞根，$N。在奪回自己的城市之前，我們決不停止努力。如果你想加入我們，就先去完成一個簡單的任務：殺了那個叛徒，麥克尼爾·瑟瑪普拉格。",objectives={"到諾姆瑞根去殺掉麥克尼爾·瑟瑪普拉格。完成任務之後向大工匠梅卡托克報告。"}]])
R(2930,"搶救數據",[[description="在逃離諾姆瑞根的時候，我們留下了太多的資料！非常重要的資料！$B$B我需要一張彩色穿孔卡片，你可以從諾姆瑞根城裡的矩陣式打孔電腦3005-D型裡找到這種卡片。不過糟糕的是，要得到它的話，你就必須先接近低級安全終端，也就是A型，B型和C型電腦，然後用不同的穿孔卡片開啟它們，從白色的卡片開始……而且我們把所有的穿孔卡片都留在城裡了。$B$B這真是一場災難！你能幫忙嗎？",objectives={"將彩色穿孔卡片交給鐵爐堡的大機械師卡斯派普。"}]])
R(2931,"卡斯派普的任務",[[description="鐵爐堡的大機械師卡斯派普正在徵集冒險者！他正在組織一個冒險小隊，要到諾姆瑞根去執行一項極度機密和重要的資料收集任務。$B$B卡斯派普也許不是煉金術、魔法和工程學協會的一員，不過他也算是個很聰明的地精，如果是他認為這是件很重要的事情，那麼根據我的計算，這件事有百分之八十四的可能性是確實很重要的！$B$B這個可能性可不小！",objectives={"與鐵爐堡的大機械師卡斯派普談話。"}]])
R(2932,"可怕的消息",[[description="The Witherbark trolls were once allies to the Horde, but they betrayed Thrall... and that must be punished!$B$BHere, take my pike and go to the Hinterlands, far to the north.  You will find it northeast of Tarren Mill, a village held by our allies, the Forsaken.$B$BWhen you enter the Hinterlands, hunt Witherbark trolls.  Gather their skulls and drive my pike into the ground at one of their smaller villages, Hiri'watha or Zun'watha.$B$BShow them their vile actions are of consequence!",objectives={"Gather Witherbark Skulls and place on Nimboya's Pike.  Place Nimboya's Laden Pike at one of the Witherbark Villages in the Hinterlands, then return to Nimboya in Stranglethorn."}]])
R(2933,"毒液瓶",[[description="These bottles hold a vile, green venom.$B$BConsidering the number of bottles in this village, the Witherbarks must deem it very important.  Perhaps an apothecary in nearby Tarren Mill would like a sample.",objectives={"Bring a Venom Bottle to an apothecary in Tarren Mill."}]])
R(2934,"完好無損的毒囊",[[description="我必須要有一個你帶來的那種毒液的新鮮樣本才能進行研究。生產毒液的蜘蛛一定生活在辛特蘭一帶——獵捕這些蜘蛛，直到你找到一個完好無損的毒囊，把它給我帶來。食人妖們的沙德拉洛城附近有許多蜘蛛，到那裡去找找吧。$B$B別耽擱了，毒囊一定要非常新鮮才行。",objectives={"將完好無損的毒囊交給塔倫米爾的藥劑師林度恩。"}]])
R(2935,"請教加德林大師",[[description="The venom from the broodguards wasn't as potent as the venom you brought originally.  It must have come from a different spider.$B$BI want a fresh sample of that venom.  To find out where it came from, you must consult with a troll who knows the Witherbark well--Master Gadrin in Sen'jin Village.  Travel to Durotar and speak with Gadrin.  With luck, he'll know where the Witherbarks get their venom.",objectives={"Speak with Master Gadrin in Sen'jin Village."}]])
R(2936,"蜘蛛之神",[[description="The Witherbarks worship a spider god, and from her they collect their most potent venom.  So if you want the venom, then you must summon their god!$B$BTo do that, you must know her true name, and that name is on a tablet buried in Tanaris, in the troll city of Zul'Farrak, in a tomb guarded by Theka the Martyr.$B$BDefeat Theka and find and read his tablet to discover the spider god's name.  When you know it, return to me.",objectives={"Read from the Tablet of Theka to learn the name of the Witherbark spider god, then return to Master Gadrin."}]])
R(2937,"召喚沙德拉",[[description="Take his parchment, and read it at the altar of Shadra'Alor, deep within the witherbark realm in the Hinterlands.  This will summon Shadra the spider god.",objectives={"Defeat Shadra at the altar of Shadra'Alor, then bring her venom to Apothecary Lydon in Tarren Mill."}]])
R(2938,"送往幽暗城的毒藥",[[description="The venom you gathered from the Witherbark's spider god is quite a find!  I've been able to kill nearly two dozen rabbits with just a drop of the stuff.  Granted, some of those rabbits were very young and small enough to fit in the palm of one's hand so I'm certain their resistance to toxins was low, but it can't be denied that this poison is powerful!$B$BI'd like a sample sent to my superior, Apothecary Faranell in the Apothecarium of the Undercity.  I am positive he would want to test this himself.",objectives={"Bring Faranell's Parcel to Master Apothecary Faranell in the Undercity."}]])
R(2939,"尋找知識",[[description="雖然菲拉斯的廢墟很危險，但是它們講述了許多曾經發生的事情。$B$B幾天前我在南邊的碎石堆裡搜索的時候，發現了一個看起來像是根普通法杖的東西。但是，我總覺得事情並不是那麼簡單。安吉拉斯和我在這裡鑽研書籍已經很久了，不過我們沒發現什麼和它相關的資訊。$B$B我在達納蘇斯有一個同事，她能告訴我這是什麼東西，$N。你為什麼不去跟她談談呢？也許她能幫助我們？",objectives={"與魯瑟蘭村的達蕾恩·輕風談話。"}]])
R(2940,"菲拉斯的歷史",[[description="看起來這本書很久沒有人打開過了。它的封面破舊而且書頁發黃，但檢查後你會發現這正是特洛亞斯要找的那本書。$B$B你把它撿了起來，但你卻突然意識到，也許應該在借閱之前得到物主的允許。",objectives={"如果你想借達蕾恩·輕風的書，要先得到她的允許。"}]])
R(2941,"海龜照片",[[description="我一生中研究了許多課題，最近我迷上了遍佈辛特蘭海灘地區的鉗嘴龜。我特別想看到一隻名叫加莫里塔的大型鉗嘴龜，本來呢，我想要自己去一趟，但繁重的研究工作讓我不得不留在這裡。如果能搞到一張它的畫像就好了。$B$B把這封信交給塔納利斯的克格爾·曲藤。她為我發明了一種可以快速抓取圖像的裝置，我想她把那個東西叫做「快照」……",objectives={"把信交給塔納利斯的克格爾·曲藤。"}]])
R(2942,"晨光石",[[description="The moment the artifact is removed from the Monolith, you feel the energy in the Stave of Equinex begin to fade.",objectives={"Return the Sparkling Stone and the Stave of Equinex to Troyas Moonbreeze in Feathermoon Stronghold. "}]])
R(2943,"向特洛亞斯回復",[[description="Here it is, $N. Please, take care of my book.$B$BNow, hurry along. I'm sure Troyas is eager for your return.",objectives={"Deliver the book to Troyas Moonbreeze in Feathermoon Stronghold."}]])
R(2944,"超級攝影器FX",[[description="先來看看我的發明吧，$N。你所要做的只是將它對準任何一個你想要拍攝的物品，然後按下這個按鈕。$B$B你說的辛特蘭的生物是什麼？加莫里塔？好吧，祝你好運，希望你能找到它。我堅信達蕾恩會對你給她的照片很滿意的。$B$B不說那麼多了，這是給你的超級攝影器。玩得開心點！",objectives={"用超級攝影器FX給加莫里塔拍張照片，然後把它交給魯瑟蘭村的達蕾恩·輕風。"}]])
R(2945,"臟兮兮的戒指",[[description="你在一個黑鐵矮人的屍體上發現了一枚戒指。但要辨認戒指的細節卻很困難，泥土和堅硬的污垢將它整個包裹了起來，你根本沒法戴上它。你覺得它是用某種珍貴的金屬製成的，似乎還鑲著寶石。$B$B如果你想好好看看這枚戒指的話，就得找些東西把戒指表面的污垢清理掉。",objectives={"想方法把髒兮兮的戒指弄乾淨。"}]])
R(2946,"拭目以待",[[description="We want you to take the miniature discs you found to the sealed gates of Uldum.  We... we aren't sure what will happen when you do this.$B$BThis sounds risky, sure, we acknowledge that.  It might, however, do nothing.  You might need to use the discs on something.  Perhaps the doors unlock when you have the discs in your possession.  Be open to try anything, and be ready for anything to happen.$B$BWhen you've found out what happens, return to Ironforge.  We'll have a lot to analyze when you're done!",objectives={"Bring the miniature platinum discs to the gates of Uldum in Tanaris and look for clues as to the connection between the two."}]])
R(2947,"戒指歸來",[[description="Opening the box produced by the Sparklematic 5200 reveals what you had suspected - a shiny ring!  Wearing the ring, you feel magic power surge through you body.$B$BInside the band is a small but nonetheless discernable imprint of the seal of Ironforge.  Next to that, three small initials are engraved: \"TdK\".  This may signify either the initials of the previous owner, or perhaps the initials of the ring's crafter.  Keep the ring... or return it to this person.  Decisions, decisions...",objectives={"You may either keep the ring, or you may find the person responsible for the imprint and engravings on the inside of the band."}]])
R(2948,"侏儒的手藝",[[description="Listen $n, that ring is yours, sure... but I can make you a better one!  That design, like I said, is really simple.  I am a lot more skilled now, and for the mere fee of thirty silver coins I'll spruce it up for you!  Well, a little more than thirty, actually...$B$BI'm in a tight spot right now; all my material stock is all dried up.  If you bring me a bar of silver and a moss agate, I'll add a silver and agate lattice to the ring that will give it a little more pizzazz!$B$BTrust me!",objectives={"Bring the Brilliant Gold Ring, a Silver Bar, a Moss Agate, and 30 silver coins to Talvash del Kissel in Ironforge."}]])
R(2949,"戒指歸來",[[description="Opening the box produced by the Sparklematic 5200 reveals a shiny ring!  Donning the ring, you feel magic power surge through your body.$B$BInside the band is a small but nonetheless discernable imprint of the seal of Orgrimmar.  Engraved letters are next to it, but only the first three stand out even after cleaning: \"NOG...\"$B$BThis may signify either the initials of the previous owner, or perhaps the initials of the ring's crafter.  Keep the ring... or find \"NOG\" - decisions, decisions...",objectives={"You may either keep the ring, or you may find the person responsible for the imprint and engravings on the inside of the band."}]])
R(2950,"諾格的手藝",[[description="No, no, no - I'm not all of the sudden saying that the ring is mine.  I normally don't do this, but your information about the Dark Irons was very useful.  I'll improve your ring for you, better than whomever made this simple little thing could have ever done.  Probably some gnome...$B$BIf you bring me a bar of silver, a moss agate, and thirty silver coins for my trouble, I'll add a silver and agate lattice to the ring that will strengthen the magic inside of it.  Interested?",objectives={"Bring the Brilliant Gold Ring, a Silver Bar, a Moss Agate, and 30 silver coins to Nogg in Orgrimmar."}]])
R(2951,"超級清潔器5200型！",[[description="This contraption stands out amongst the gnomes holding out against the madness outside the room.  A small plaque on the device reads \"The Sparklematic 5200\", followed by some text:$B$B\"Grime and residue ruining your sparklies?  The Sparklematic 5200 puts the shine back in shine-tastic!  Insert the item you wish to clean and deposit three silver coins in the coin slot.  Give the Sparklematic 5200 a moment for operation, and voila!  Your valuables will emerge clean and shiny!\"",objectives={"Insert a Grime-Encrusted Item into the Sparklematic 5200, and be sure to have three silver coins to start the machine."}]])
R(2952,"超級清潔器5200型！")
R(2953,"再次使用超級清潔器")
R(2954,"石頭衛士",[[description="\"Salutations - I am a guardian of entry.  Unless you have the Plates of Uldum already integrated with your disc set, I will not allow for entry into the Uldum compound.\"$B$BThe appearance of the Stone Watcher of Norgannon must be the reaction that was hoped for in sending you out to the Tanaris desert with the platinum discs.  As instructed, you will need to find out what the story behind the Stone Watcher is before continuing on.",objectives={"Learn the purpose of the Stone Watcher of Norgannon, and then interact with the Uldum Pedestal in the Tanaris desert."}]])
R(2962,"更多的輻射塵！",[[description="你的樣本不僅數量不夠，而且純度也不夠。$B$B我們需要更多的輻射塵。很顯然，穴居怪身上的輻射劑量根本無法滿足我們的需要。你必須重返諾姆瑞根，直接從輻射源頭取回一些輻射塵。我指的是那些受到輻射的泥漿怪、潛伏者和水元素。小心一點，收集這種輻射塵並不容易。也許你得試好幾次才能找到一個合適的樣本。",objectives={"到諾姆瑞根去收集高強度輻射塵。要多加小心，這種輻射塵非常不穩定，很快就會分解。$B$B奧齊要求你在任務完成後把沉重的鉛瓶也交給他。"}]])
R(2963,"奧丹姆的線索",[[description="你好，很高興再一次見到你，$n！你在奧達曼的發現使探險者協會興奮不已。協會一直都在努力揭開你所發現的那張白金圓盤的秘密。你來的正是時候，我可以和你分享一下我們的最新進展！$B$B史學家卡尼克發現了一些很重要的線索，可能有助於找到塔納利斯沙漠中的守衛之谷的起源。他想和你談談，越快越好！",objectives={"與鐵爐堡探險者大廳中的史學家卡尼克談話。"}]])
R(2964,"進壹步的任務",[[description="Well $n... we seem to be at a temporary dead end here.  We know what we need - the Plates of Uldum - but we have no idea where they might be.  We'll need to do quite a bit of research on this to come up with a solid plan of attack.  I have a couple ideas where to start looking; I have high hopes that soon, we'll be asking you to head out and recover them.$B$BThe High Explorer needs to be informed on this, $n; no doubt, he also wants to thank you personally for once again aiding the League.",objectives={"Speak with High Explorer Magellas in Ironforge."}]])
R(2965,"奧丹姆的線索",[[description="Ah, $n, it is fortuitous that you have come to me again.  Your revelations at the Uldaman dig site have certainly given us sages much discuss.  I was doing just that with one of the druids, Nara Wildmane, when it dawned on me that her past adventuring experiences may have some great importance as to the next step we need to take.$B$BI would like for you to speak with her concerning her travels to the Valley of the Watchers in the Tanaris desert.  She waits for you on the Elder Rise.",objectives={"Speak with Nara Wildmane on the Elder Rise in Thunder Bluff."}]])
R(2966,"拭目以待",[[description="Sage Truthseeker and I would like you to take the miniature discs you found to the sealed gates of Uldum.  We... we aren't sure what will happen when you do this.$B$BThis sounds risky, sure, we acknowledge that.  It might, however, do nothing.  You might need to use the discs on something.  Perhaps the doors unlock when you have the discs in your possession.  Be open to try anything, and be ready for anything to happen.$B$BLearn what you can, then return to me. We will have much to discuss.",objectives={"Bring the miniature platinum discs to the gates of Uldum in Tanaris and look for clues as to the connection between the two."}]])
R(2967,"返回雷霆崖",[[description="You access the pedestal again; the platinum discs suddenly appear once more in your backpack.$B$BWith the knowledge of the stone watcher learned and the discs returned to your possession, the time has come to return to Thunder Bluff and inform the Nara Wildmane of your discovery.",objectives={"Speak with Nara Wildmane in Thunder Bluff."}]])
R(2968,"進壹步的任務",[[description="Well $n... we seem to be at an unfortunate impasse.  We know what we need - the Plates of Uldum - but we have no idea where they might be.  We will research this, and then devise a solid plan of attack.  I have a couple ideas where to start looking; I have high hopes that soon, we'll be asking you to rejoin our efforts to discover the truth.$B$BSage Truthseeker needs to be informed on this, $n; no doubt, he also wants to thank you personally for once again heeding the call.",objectives={"Speak with Sage Truthseeker in Thunder Bluff."}]])
R(2969,"精靈龍的自由",[[description="可惡的恐怖圖騰部族正在捕捉精靈龍，$N。耶爾卡和我不知道他們打算對這些精靈龍做什麼，但那總不會是什麼好事。$B$B我們還沒有強悍到可以殺進營地去解救那些精靈龍，但也許有了你的幫助……如果你能找到一些得力的幫手的話，就從籠中釋放那些精靈龍吧，另外你要保證它們都活著逃出去。我也會幫你的。耶爾卡會留在這裡繼續戒備。",objectives={"從恐怖圖騰營地的圍欄裡釋放被俘獲的小精龍。至少6個小精龍和辛達爾·月紋必須活著。$B$B如果6分鐘之內你還沒能達成這個目標，辛達爾就會決定撤退，任務也會隨即失敗。"}]])
R(2970,"菲拉斯的正義",[[description="As she's already told you, Kindal and I will now take the fight to the Grimtotem. Together, we should still be able to pick off some of the tauren without much threat to ourselves, but we'd love some help if you're willing and able.$B$BYou've seen the camp below us, but there are more to the east. Using your own tactics, deal as much damage to the tauren as you can. We can all meet back here after they've felt the sting of Kindal's arrows and your own weapons.",objectives={"Kill 12 Grimtotem Naturalists, 10 Grimtotem Raiders, and 6 Grimtotem Shamans before returning to Jer'kai Moonweaver in Feralas."}]])
R(2971,"<UNUSED>",[[description="[PH] Description",objectives={"[PH] Log Description"}]])
R(2972,"菲拉斯的正義",[[description="Out here in the wilderness, Kindal and I have meager means to reward your help, but we don't want you to feel unappreciated. Take my signet ring. If you ever find yourself in the boughs of Teldrassil, go to the Temple of the Moon in the heart of Darnassus. There you will find my High Priestess Tyrande Whisperwind. The ring will let her know that we are well and give credit to your story.$B$BWe both thank you, $N.",objectives={"Take Jer'kai's Signet Ring to High Priestess Tyrande Whisperwind in Darnassus."}]])
R(2973,"新鬥篷的光輝",[[description="Well met, $c. I've traveled with my companions down to the Feralas on a mission for our Orgrimmar masters.$B$BMy life-mate Korrin finds great pleasure in new clothing, so I aim to make her a new cloak adorned with the gossamer wings of faerie dragons. Would you be able to help me? Sprite darters with gorgeous wings I want are west of Camp Mojache.",objectives={"Bring 10 Iridescent Sprite Darter Wings to Krueg Skullsplitter in Camp Mojache."}]])
R(2974,"可怕的發現",[[description="什麼？！你在這一地區碰到牛頭人了？你開玩笑吧！他們長什麼樣？！$B$B恐怖圖騰氏族！你看到他們了？貝爾戈洛姆對他們這種生物很有興趣……甚至出重金懸賞他們。$B$B你必須得回去，$c。回去給我帶些他們的角回來……如果可以的話，盡可能多弄一些。你可別低估了恐怖圖騰氏族，回去殺了他們，讓菲拉斯的河流被他們的鮮血染紅。",objectives={"收集20支恐怖圖騰之角，把它們交給千針石林的克魯伊格·劈顱。"}]])
R(2975,"菲拉斯的食人魔",[[description="戈杜尼巨魔在這一地區的影響已經不容忽視了。$N，你可以清楚地看到這一點，他們的存在污染了這片土地。在他們進一步擴張之前，我們一定要把他們趕回去。$B$B沿著河向北走，你會找到他們的前哨營地。去殺掉他們，$N。我們必須告訴這些巨魔：他們在這裡不受歡迎。",objectives={"莫沙徹營地的洛卡·奧赫要你殺掉10個戈杜尼巨魔、10個戈杜尼巨魔法師和5個戈杜尼蠻兵。"}]])
R(2976,"可怕的發現",[[description="什麼？！$B$B啊，我確實提到過獎賞，對嗎？好吧，我知道了$B$B你完成了任務，我覺得你應該得到最高的獎賞。把這些角拿去，我會幫你把它們放到箱子裡。到榮譽谷去找貝爾戈洛姆·石槌，向他彙報你所見的一切，他會表彰你的。$B$B祝你一路平安，$c，再次感謝你。",objectives={"將一箱恐怖圖騰之角交給奧格瑪的貝爾戈洛姆·石槌。"}]])
R(2977,"返回鐵爐堡",[[description="You access the pedestal again; the platinum discs suddenly appear once more in your backpack.$B$BWith the knowledge of the stone watcher learned and the discs returned to your possession, the time has come to return to Ironforge and inform the Explorers' League of your discovery.",objectives={"Speak with Historian Karnik in Ironforge."}]])
R(2978,"戈杜尼卷軸",[[description="你撿起了這個沾滿泥土的卷軸，發現上面寫著某種集會或儀式的內容。洛卡·奧赫應該會對這個卷軸以及它對戈杜尼巨魔的意義感興趣。",objectives={"將戈杜尼卷軸交給莫沙徹營地的洛克·奧漢。"}]])
R(2979,"黑暗儀式",[[description="這些好像是某種黑暗儀式的計畫，$N。根據我所瞭解的情況，這種儀式是由戈杜尼巨魔中的大法師進行的。$B$B從某個戈杜尼大法師身上給我弄一顆寶珠來。$B$B法師的寶珠蘊含了巨大的力量，它可以幫我們搞清楚更多關於這種儀式的細節。",objectives={"莫沙徹營地的洛卡·奧赫希望你找到一顆戈杜尼之寶珠。"}]])
R(2980,"菲拉斯的食人魔",[[description="現在你已經證明了自己是一個真正的勇士，我相信你具備足夠的勇氣繼續完成下一個任務。$B$B到這裡西南邊的高原荒野去，在那塊原本屬於夜精靈的土地上還殘存著一些被遺棄和毀壞的建築物。搜索那些廢墟，當你看到枯萎的樹木和滿目瘡痍的大地時，你就會看到那些戈杜尼巨魔。把他們都幹掉。$B$B這些巨魔比你曾面對的任何敵人都要強大，$N。你一定要小心行事。",objectives={"莫沙徹營地的洛卡·奧赫要你去殺掉十個戈杜尼薩滿、10個戈杜尼術士和5個戈杜尼虐待者。"}]])
R(2981,"菲拉斯的危機",[[description="Feralas is an ideal location for an accomplished $c to prove $Ghimself:herself;. A tribe of ogres called the Gordunni are the dominant military force there, and their numbers are growing. They must be stopped before they threaten our presence in Feralas.$B$BA warrior I know of named Rok Orhan resides at Camp Mojache in Feralas; go to her. She will tell you more of the situation when you arrive.",objectives={"Belgrom Rockmaul wants you to speak with Rok Orhan in Camp Mojache."}]])
R(2982,"高原荒野",[[description="雖然菲拉斯森林的廢墟中隱藏著巨大的危險，但特洛亞斯和我一直以來都在調查這個地區。$B$B最近特洛亞斯老是獨自一人去高原荒野，這很讓我擔心。戈杜尼巨魔已經佔領了那裡，他們不會對任何進入他們領地的冒險者手下留情的。$B$B我希望你能到菲拉斯南部去一趟，消滅一些巨魔。讓我的特洛亞斯安全一點，我會十分感激你的。",objectives={"安吉拉斯·月風要求你殺死8個戈杜尼術士、8個戈杜尼薩滿和8個戈杜尼蠻兵。"}]])
R(2983,"火焰的召喚",[[description="It's been some time since you were tested last, $N. You've been patient thus far in your studies, but it's time for you to learn about greater powers... it's time you learn real power. The element of fire is yours if you're prepared to pay for it.$B$BSeek out Kranal Fiss in the Barrens. He lives in a small dwelling north of the Crossroads, but be mindful, if you've reached the blasted night elf lands, you've gone way too far.",objectives={"Find Kranal Fiss in the Barrens."}]])
R(2984,"火焰的召喚",[[description="Long has it been since you were last tested, $N. You have shown patience thus far in your studies, but the time has come for you to learn more. The time has come for you to learn about destruction... and chaos. The element of fire is yours for the understanding, if you're prepared to pay for it.$B$BSeek out Kranal Fiss in the Barrens. He lives in a small dwelling north of the Crossroads, but be mindful, if you've reached the night elf lands, you've gone too far.",objectives={"Find Kranal Fiss in the Barrens."}]])
R(2985,"水之召喚",[[description="You look ready for your next test, $N. You've been patient in your studies, but the time has come for you to learn more. The time has come for you to learn about the purity of water.$B$BSeek out Islen Waterseer in the Barrens. She is along the eastern coast, south of the Southfury River and Ratchet. You will find her there at her fishing hut. Good luck to you, $N.",objectives={"Find Islen Waterseer in the Barrens."}]])
R(2986,"水之召喚",[[description="Long has it been since you were last tested, $N. You have shown patience thus far in your studies, but the time has come for you to learn more. The time has come for you to learn about the purity of water.$B$BSeek out Islen Waterseer in the Barrens. She is along the eastern coast, south of the Southfury River and Ratchet. You will find her there at her fishing hut. Good luck to you, $N.",objectives={"Find Islen Waterseer in the Barrens."}]])
R(2987,"戈杜尼鈷礦石",[[description="我剛剛到達菲拉斯時，曾聽說這裡的戈杜尼巨魔有一些有趣的礦石。天知道巨魔用礦石來幹什麼，但他們確實在很小心地保護那種東西！他們有意隱藏這些礦石，以免我們接觸到它。$B$B如果你願意的話，我會把我的鏟子給你。到北面的戈杜尼前哨站去，給我挖些戈杜尼鈷礦回來。注意找那些泛著藍光的礦石，然後就挖！",objectives={"莫沙徹營地的奧爾文·吉茲米克需要12塊戈杜尼鈷礦石的樣本。"}]])
R(2988,"枯木巨魔的牢籠",[[description="我們最強大的獅鷲獸的兒子失蹤了！幾天前，沙普比克和塔的父母外出打獵時失蹤了，我們認為是食人妖抓走了它。$B$B你必須幫幫我們！到枯木食人妖的兩個村子裡去搜一搜那裡的籠子，看看沙普比克是不是被關在裡面。",objectives={"檢查兩個枯木食人妖村落裡的籠子，然後向獅鷲獸管理員沙拉克·鷹斧回覆。"}]])
R(2989,"祖爾祭壇",[[description="沙普比克沒有和枯木食人妖在一起，那麼或許是邪枝食人妖帶走了他……到邪枝食人妖控制地區的西部邊緣去，在那裡的祖爾祭壇上找一找吧。",objectives={"檢查祖爾祭壇的頂部，然後向獅鷲獸管理員沙拉克·鷹斧報告。"}]])
R(2990,"薩迪斯·格希德",[[description="Take this feather to Thadius Grimshade, the diviner.  He left Aerie Peak years ago to pursue darker knowledge, but in his heart he is still a Wildhammer!$B$BAnd perhaps his talents can help us find Sharpbeak.$B$BThis feather was taken from the nest where the gryphon child sleeps.  If you give it to Thadius then, with luck, he can use his divining magics to find Sharpbeak.$B$BGood luck, $N.  You will find Thadius in the Blasted Lands, in the mage tower of Nethergarde Keep.",objectives={"Bring Sharpbeak's Feather to Thadius Grimshade in the Blasted Lands."}]])
R(2991,"耐克魯姆的徽章",[[description="我會幫你找出那頭獅鷲獸的下落，但你得先為我做點事情。食人妖城市祖爾法拉克裡面有一個名叫耐克魯姆的食人妖，他擁有一枚徽章，我很想研究一下那東西。把徽章交給我，我就幫你找到沙普比克。$B$B祖爾法拉克在無盡之海西邊的塔納利斯沙漠中。",objectives={"將耐克魯姆的徽章交給詛咒之地的薩迪斯·格希德。"}]])
R(2992,"占蔔",[[description="Give me room while I perform a ritual of divination.  I will find the connection between the feather you brought me and its owner, and follow that connection to Sharpbeak himself.$B$BThat is... I will if all goes according to plan.  If it does not, then... you better close your eyes.",objectives={"Wait until Grimshade performs the ritual of divination."}]])
R(2993,"返回辛特蘭",[[description="Sharpbeak is held in a cage, high on a cliff at the top of Jintha'Alor in the Hinterlands.  The key to this cage is possessed by the high priestess of the Vilebranch trolls, Vile Priestess Hexx.$B$BThere.  I have done my part.  I bid you fortune on your quest, $N.",objectives={"Speak with Gryphon Master Talonaxe."}]])
R(2994,"拯救沙普比克",[[description="We must save Sharpbeak!$B$BFight your way to the top of Jintha'Alor in the heart of Vilebranch territory, gain the key to Sharpbeak's cage from the vile Priestess Hexx, and then find and save Sharpbeak!",objectives={"Fight to the top of Jintha'Alor, kill Vile Priestess Hexx for the key to Sharpbeak's cage, and save Sharpbeak."}]])
R(2995,"聯絡中心",[[description="The Quel'Danil Lodge is a center of communication for the high elves of the Hinterlands. Their ambassadors are working to establish relationships with other races, with whom they share their knowledge of the Witherbark trolls that inhabit the area in the southern Hinterlands. All of the documents regarding the communications are kept at the lodge.$B$BWe don't need the Highvale building alliances with others, $N.$B$BDestroy the Highvale documents.  We need to burn their lines of communication... literally.",objectives={"Oran Snakewrithe in Undercity wants you to travel to the Hinterlands and burn the Highvale Records, Highvale Report, and Highvale Notes."}]])
R(2996,"尋找斯坦哈德",[[description="I have taught you skills in the past, but the time has come for another to teach you. He is in Ratchet, and his name is Strahad. He is human, but do not let that fool you into thinking he is weak. He is powerful even though he may be small. He can teach you about more powerful summonings--I feel you are ready. Go to him now. He is in Ratchet... above the port town next to his tower.",objectives={"Speak to Strahad Farsan in Ratchet."}]])
R(2997,"聖潔之書",[[description="Hello, $N. I know you're busy helping out the people of Dun Morogh, but when you have the time, you should make your way up to Ironforge to speak to one of our most respected ilk: Tiza Battleforge. She's the one the younger paladins go to when it's time they learn more about the Light and what's expected of ya.$B$BYou can find her upstairs in the Hall of Mysteries. If you've never been there, it's in the Mystic Ward. Good luck to ya, $N.",objectives={"Speak to Tiza Battleforge in Ironforge."}]])
R(2998,"聖潔之書",[[description="你好，我的$G兄弟:姐妹;。我們這裡最有影響力的聖騎士——達索瑞恩·拉爾最近談起過你。我聽他說過你應該去找他接受試煉了……我也從他那裡聽說過你的出色表現。$B$B如果我是你，而且我有時間的話，我就會去暴風城和他聊聊的。我很肯定他會待在光明大教堂裡——他一般都待在那裡。",objectives={"與暴風城的達索瑞恩·拉爾談話。"}]])
R(2999,"聖潔之書",[[description="Hello, $N. I know you're busy helping out the people of Dun Morogh, but when you have the time, you should go upstairs and speak to one of our most respected ilk: Tiza Battleforge. She's the one the younger paladins go to when it's time they learn more about the Light and what's expected of ya.",objectives={"Speak to Tiza Battleforge in Ironforge"}]])
R(3000,"聖潔之書",[[description="Hello, $N. I know you're busy helping out the people of Azeroth, but when you have the time, you should return to Ironforge and speak to one of the most respected paladins of your home: Tiza Battleforge. She's the one the younger dwarven paladins go to when it is time they learn more about the Light and what's expected of all of us.$B$BYou can find her upstairs in the Hall of Mysteries which is located in the Mystic Ward.",objectives={"Speak to Tiza Battleforge in Ironforge."}]])
R(3001,"尋找斯坦哈德",[[description="I have taught you skills in the past, but the time has come for another to teach you. He is in Ratchet, and his name is Strahad. He is human, but do not let that fool you into thinking he is weak, nor is he your enemy... at least for now. He is powerful and should be respected. He can teach you about greater summonings, summonings I feel you are prepared for. Go to him now.$B$BYou can find him in Ratchet... above the port town next to the tower there.",objectives={"Find Strahad Farsan in Ratchet."}]])
R(3002,"戈杜尼寶珠",[[description="Although I know my enemy well, I am a warrior, $N. I cannot begin to tell you what this orb is capable of.$B$BI know of a mage in Orgrimmar that will be able to tell us more about the orb. Take it to him. ",objectives={"Bring the Gordunni Orb to Uthel'nay in the Darkbriar Lodge in Orgrimmar."}]])
R(3022,"小心運送",[[description="$N，顯然你很想幫我進行崇高的事業。嗯，當然，你可以為我做一些事情！$B$B請把這箱蛋送給艾瑞拉斯·琥珀。他是一個很重視這些蛋的德魯伊，而且一直在幫助孵化這些蛋，以及訓練幼小的角鷹獸。你可以在泰達希爾南邊的一個名叫魯瑟蘭村的村莊裡找到他。",objectives={"把仔細包裝過的箱子交給魯瑟蘭村的艾瑞拉斯·琥珀。"}]])
R(3042,"巨魔調和劑",[[description="祖爾法拉克的沙怒食人妖用砂石製造食人妖調和劑，我可以用它來加強我鑄造的東西！有眼光的行家會出高價購買經過這樣處理的裝備，所以，如果你能給我提供足夠的調和劑，那我一定會重重獎賞你的。$B$B祖爾法拉克在加基森的西北邊。祝你好運。",objectives={"收集20瓶食人妖調和劑，把它們交給加基森的特倫頓·輕錘。"}]])
R(3062,"黑暗之心",[[description="Edana Hatetalon is the queen of the Northspring harpies that reside in the ruins to the west. She is pure evil; I have heard that her heart is one of crystal. She is void of any emotion aside from the hate she feels towards all others. You must face Edana and bring me back her dark heart.$B$BI have heard of a horn that harpies carry -- blowing it by the Hatetalon stones, in the northern part of the ruins, will summon the queen.$B$BImagine her surprise when it is not her kin calling her, but her death.",objectives={"Talo Thornhoof in Camp Mojache wants Edana Hatetalon's Dark Heart."}]])
R(3063,"對鷹身人的復仇",[[description="In my day, I was a seasoned hunter. There wasn't any creature around that I feared. Until...$B$BI was out in the forest, sharpening my blade after a tough battle, when I was ambushed. Harpies surrounded me, and I barely managed to drag myself to safety.$B$BEven now, I can still hear their cries echoing...$B$BI was never the same after that. But the hate boils inside of me -- I must get even, after all these years.$B$BThe Northspring harpies can be found to the west of here. $N, get my revenge. ",objectives={"Talo Thornhoof wants you to kill 4 Northspring Harpies, 4 Northspring Roguefeathers, 4 Northspring Windcallers, and 4 Northspring Slayers."}]])
R(3064,"<NYI> <TXT> Pirate Hats",[[description="I need pirate hats for my shop.  Get me lots!",objectives={"Bring 20 Untorn Pirate Hats to Yorba Screwspigot."}]])
R(3065,"普通石板",[[description="Ah, while you were gone a parchment came for you, $N.$B$BRead it when you have time. If I'm not mistaken, it came from the warrior trainer Frang. He would have words with you when you're ready. You'll find him outside the Den, taking cover in the shade.",objectives={"Read the Simple Tablet and speak to Frang in the Valley of Trials."}]])
R(3082,"風蝕石板",[[description="Ah, while you were gone a tablet came for you, $N.$B$BRead it when you have time. If I'm not mistaken, it came from the hunter trainer Jen'shan. She would have words with you when you're ready.",objectives={"Speak to Jen'shan in the Valley of Trials."}]])
R(3083,"密文石板",[[description="Ah, while you were gone a tablet came for you, $N.$B$BRead it when you have time. If I'm not mistaken, it came from the rogue trainer Rwag. He would have words with you when you're ready.",objectives={"Read the Encrypted Tablet and speak to Rwag in the Valley of Trials."}]])
R(3084,"符文石板",[[description="Ah, while you were gone a tablet came for you, $N.$B$BRead it when you have time. If I'm not mistaken, it came from the shaman trainer Shikrik. She would have words with you when you're ready.",objectives={"Speak to Shikrik in the Valley of Trials."}]])
R(3085,"神聖石板",[[description="Ah, while you were gone a tablet came for you, $N.$B$BRead it when you have time. If I'm not mistaken, it came from the priest trainer Ken'jai. He would have words with you when you're ready.",objectives={"Read the Hallowed Tablet and speak to Ken'jai outside the Den in the Valley of Trials."}]])
R(3086,"雕文石板",[[description="啊，剛剛你不在的時候，有人送來了這塊石板，$N。$B$B如果你有時間的話，還是看看這上面說些什麼的好。如果我沒搞錯的話，這塊石板是法師訓練師邁安寫的，她有事找你。",objectives={"閱讀雕文石板，然後和試煉谷裡大獸穴入口附近的邁安談話。"}]])
R(3087,"風蝕羊皮紙",[[description="Ah, while you were gone a parchment came for you, $N.$B$BRead it when you have time. If I'm not mistaken, it came from the hunter trainer Jen'shan. She would have words with you when you're ready.",objectives={"Read the Etched Parchment and speak to Jen'shan in the Valley of Trials."}]])
R(3088,"密文羊皮紙",[[description="Ah, while you were gone a parchment came for you, $N.$B$BRead it when you have time. If I'm not mistaken, it came from the rogue trainer Rwag. He would have words with you when you're ready.",objectives={"Read the Encrypted Parchment and speak to Rwag in the Valley of Trials."}]])
R(3089,"符文羊皮紙",[[description="Ah, while you were gone a parchment came for you, $N.$B$BRead it when you have time. If I'm not mistaken, it came from the shaman trainer Shikrik. She would have words with you when you're ready.",objectives={"Read the Rune-Inscribed Parchment and speak to Shikrik in the Valley of Trials."}]])
R(3090,"被汙染的羊皮紙",[[description="啊，剛剛你不在的時候，有人送來了這張羊皮紙，$N。$B$B一般來說我是不會去招惹術士的，但是如果你有時間的話，還是看看這上面說些什麼的好。如果我沒搞錯的話，這張羊皮紙是術士訓練師納托克寫的，他有事找你。",objectives={"閱讀被污染的羊皮紙，然後到試煉谷的大獸穴裡去和納托克談話。"}]])
R(3091,"簡易便箋",[[description="Just a moment ago a messenger was looking for you, $N. I believe she was sent by the warrior trainer Harutt. If this note is from Harutt, I wouldn't take long in reading it's contents.",objectives={"Read the Simple Note and speak to Harutt Thunderhorn in Camp Narache."}]])
R(3092,"風化便箋",[[description="Just a moment ago a messenger was looking for you, $N. I believe she was sent by the hunter trainer Lanka. If this note is from Lanka, I wouldn't take long in reading it's contents.",objectives={"Read the Etched Note and speak to Lanka Farshot in Red Cloud Mesa."}]])
R(3093,"符文便箋",[[description="$N，剛才有一個信差來找過你。我相信她是薩滿訓練師米拉派來的。如果這張便箋的確是米拉寫的，那你得趕快看看裡頭的內容。",objectives={"閱讀符文便箋，然後與納拉其營地的米拉·晨行者談話。"}]])
R(3094,"綠色便箋",[[description="$N，剛才有一個信差來找過你。我相信她是德魯伊訓練師加爾特派來的。如果這張便箋的確是加爾特寫的，那你得趕快看看裡頭的內容。",objectives={"閱讀綠色便箋，然後與納拉其營地的加爾特·迷霧行者談話。"}]])
R(3095,"簡易卷軸",[[description="Ah, while you were off dealing with the mindless Scourge, this scroll arrived for you. I would think it's some matter of importance as it seems it bears the seal of the warrior trainer Dannal. I would take some time to read it before heading out again.",objectives={"Read the Simple Scroll and speak to Dannal Stern in Deathknell."}]])
R(3096,"密文卷軸",[[description="Ah, while you were off dealing with the mindless Scourge, this scroll arrived for you. I would think it's some matter of importance as it seems it bears the seal of the rogue trainer David Trias. I would take some time to read it before heading out again.",objectives={"Read the Encrypted Scroll and speak to David Trias in Deathknell."}]])
R(3097,"神聖卷軸",[[description="啊，剛剛你跟天譴軍團的那些行屍走肉作戰的時候，有人送來了這根卷軸。我想這應該不是什麼小事，因為卷軸上有牧師訓練師杜斯滕的印章。如果我是你的話，就會看看這上面說什麼。",objectives={"閱讀神聖卷軸，然後和喪鐘鎮教堂的黑暗牧師杜斯滕談話。"}]])
R(3098,"雕文卷軸",[[description="啊，剛剛你跟天譴軍團的那些行屍走肉作戰的時候，有人送來了這根卷軸。我想這應該不是什麼小事，因為卷軸上有法師訓練師伊莎貝拉的印章。如果我是你的話，就會看看這上面說什麼。",objectives={"閱讀雕文卷軸，然後和喪鐘鎮教堂的伊莎貝拉談話。"}]])
R(3099,"被汙染的卷軸",[[description="Ah, while you were off dealing with the mindless Scourge, this scroll arrived for you. I would think it's some matter of importance as it seems it bears the seal of the warlock trainer Maximillion. I would take some time to read it before heading out again.",objectives={"Read the Tainted Scroll and speak to Maximillion in Deathknell."}]])
R(3100,"簡要的信件",[[description="I was asked to bring this to your attention as soon as you returned from the kobold camps, $N. It appears to be a letter sealed with the insignia of Llane, our local warrior trainer. I wouldn't hesitate to read it before you go about any other business here in the Abbey.",objectives={"Read the Simple Letter and speak to Llane Beshere in Northshire Abbey."}]])
R(3101,"聖潔信件",[[description="I was asked to bring this to your attention as soon as you returned from the kobold camps, $N. It appears to be a letter sealed with the insignia of Brother Sammuel, our local paladin trainer. I wouldn't hesitate to read it before you go about any other business here in the Abbey.",objectives={"Read the Consecrated Letter and speak to Brother Sammuel in Northshire Abbey."}]])
R(3102,"密文信件",[[description="I was asked to bring this to your attention as soon as you returned from the kobold camps, $N. It appears to be a letter sealed with the insignia of Jorik, one of our local trainers. I wouldn't hesitate to read it before you go about any other business here in the Abbey.",objectives={"Read the Encrypted Letter and speak to Jorik Kerridan in the stable behind Northshire Abbey."}]])
R(3103,"神聖信件",[[description="I was asked to bring this to your attention as soon as you returned from the kobold camps, $N. It appears to be a letter sealed with the insignia of Priestess Anetta, our local priest trainer. I wouldn't hesitate to read it before you go about any other business here in the Abbey.",objectives={"Read the Hallowed Letter and speak to Priestess Anetta in Northshire Abbey."}]])
R(3104,"雕文信件",[[description="I was asked to bring this to your attention as soon as you returned from the kobold camps, $N. It appears to be a letter sealed with the insignia of Khelden, our local mage trainer. I wouldn't hesitate to read it before you go about any other business here in the Abbey.",objectives={"Read the Glyphic Letter and speak to Khelden Bremen inside Northshire Abbey."}]])
R(3105,"被汙染的信件",[[description="I was asked to bring this to your attention as soon as you returned from the kobold camps, $N. It appears to be a letter sealed with the insignia of Drusilla, one of our local trainers. I wouldn't hesitate to read it before you go about any other business here in the Abbey.",objectives={"Read the Tainted Letter and speak to Drusilla La Salle next to Northshire Abbey."}]])
R(3106,"簡易符文",[[description="While you were helping me out, this rune was given to me to pass on to you. Take some time to read it when you have a chance. I'm thinkin' it came from the warrior trainer Thran. Take a gander at it and go find him inside Anvilmar when you've a chance.",objectives={"Read the Simple Rune and speak to Thran Khorman in Coldridge Valley."}]])
R(3107,"神聖符文",[[description="While you were helping me out, this rune was given to me to pass on to you. Take some time to read it when you have a chance. I'm thinkin' it came from the paladin trainer Bromos. Take a gander at it and go find him inside Anvilmar when you've a chance.",objectives={"Read the Consecrated Rune and speak to Bromos Grummner in Coldridge Valley."}]])
R(3108,"風蝕符文",[[description="你剛才在外面忙碌的時候，有人讓我把這個符文交給你。如果你有時間的話就看一下吧，好像是獵人訓練師索加斯寫給你的，他就在安威瑪裡面。",objectives={"閱讀風蝕符文，然後與寒脊山谷的索加斯·格瑞姆森談話。"}]])
R(3109,"密文符文",[[description="While you were helping me out, this rune was given to me to pass on to you. Take some time to read it when you have a chance. I'm thinkin' it came from the rogue trainer Solm. Take a gander at it and go find him inside Anvilmar when you've a chance.",objectives={"Read the Encrypted Rune and speak to Solm Hargrin in Coldridge Valley."}]])
R(3110,"神聖符文",[[description="While you were helping me out, this rune was given to me to pass on to you. Take some time to read it when you have a chance. I'm thinkin' it came from the priest trainer Branstock. Take a gander at it and go find him inside Anvilmar when you've a chance.",objectives={"Read the Hallowed Rune and speak to Branstock Khalder in Anvilmar."}]])
R(3111,"Glyphic Rune",[[description="Long ago high elves taught us the secrets of magic along with our human allies. They preached to us about rules and how magic can make ya go mad! But don't believe it. We're not like the elves; we don't have the same weaknesses. Just keep yourself on the right path and you'll find magic is as powerful a tool as it is a weapon.$B$BWhen you're ready, come find me inside Anvilmar. I'll be waiting for ya!",objectives={"Speak to Marryk Nurribit inside Anvilmar."}]])
R(3112,"簡易備忘錄",[[description="While you were helping me out, this memorandum was given to me to pass on to you. Take some time to read it when you have a chance. I'm thinkin' it came from the warrior trainer Thran. Take a gander at it and go find him inside Anvilmar when you've a chance.",objectives={"Read the Simple Memorandum and speak to Thran Khorman in Coldridge Valley."}]])
R(3113,"密文備忘錄",[[description="While you were helping me out, this memorandum was given to me to pass on to you. Take some time to read it when you have a chance. I'm thinkin' it came from the rogue trainer Solm. Take a gander at it and go find him inside Anvilmar when you've a chance.",objectives={"Read the Encrypted Memorandum and speak to Solm Hargrin in Coldridge Valley."}]])
R(3114,"雕文備忘錄",[[description="While you were helping me out, this memorandum was given to me to pass on to you. Take some time to read it when you have a chance. I'm thinkin' it came from the mage trainer Marryk. Take a gander at it and go find him inside Anvilmar when you've a chance.",objectives={"Read the Glyphic Memorandum and speak to Marryk Nurribit inside Anvilmar above Coldridge Valley."}]])
R(3115,"被汙染的備忘錄",[[description="While you were helping me out, this memorandum was given to me to pass on to you. Take some time to read it when you have a chance. I'm thinkin' it came from the warlock trainer Alamar. Take a gander at it and go find him inside Anvilmar when you've a chance.$B$BAnd watch yerself, $N, your kind ain't too trusted 'round these parts.",objectives={"Read the Tainted Memorandum and speak to Alamar Grimm inside Anvilmar above Coldridge Valley."}]])
R(3116,"簡易符記",[[description="This sigil was given to me by a messenger from our warrior trainer, Alyissia. It seems Alyissia would have words with you when you have a moment. Read it and bring it to her afterwards.",objectives={"Read the Simple Sigil and speak to Alyissia in Shadowglen."}]])
R(3117,"風化符記",[[description="This sigil was given to me by a messenger from our hunter trainer, Ayanna. It seems Ayanna would have words with you when you have a moment. Read it and bring it to her afterwards.",objectives={"Read the Etched Sigil and speak to Ayanna Everstride at the top of Aldrassil in Shadowglen."}]])
R(3118,"密文符記",[[description="This sigil was given to me by a messenger from our rogue trainer, Frahun. It seems Frahun would have words with you when you have a moment. Read it and bring it to him afterwards.",objectives={"Read the Encrypted Sigil and speak to Frahun Shadewhisper in Shadowglen."}]])
R(3119,"神聖符記",[[description="This sigil was given to me by a messenger from our priest trainer, Shanda. It seems Shanda would have words with you when you have a moment. Read it and bring it to her afterwards.",objectives={"Read the Hallowed Sigil and speak to Shanda in Aldrassil."}]])
R(3120,"綠色符記",[[description="我們的德魯伊訓練師瑪丹特派來的信差把這塊符記交給了我，看起來瑪丹特有話要跟你說，看看符記上寫了些什麼，然後把符記給他帶去吧。",objectives={"閱讀綠色符記，然後與幽影谷中的奧達希爾頂端的瑪丹特·硬木談話。"}]])
R(3121,"奇怪的要求",[[description="Neeru Fireblade in Orgrimmar has what I need to get started here! He has mixed up a concoction that I need for my... well, you'll see.$B$BOff with you now -- to Orgrimmar. Here, take this with you. It's a shrunken head that I promised Neeru in exchange for the herbs. It's the head of some poor dwarf I ventured across in the forest. I'm sure Neeru will be pleased.$B$BYou'll find Neeru in the Cleft of Shadow.",objectives={"Take the Shrunken Head to Neeru Fireblade in Orgrimmar."}]])
R(3122,"向巫醫尤克裏回復",[[description="拿著這些草藥，$N。把它們交給巫醫尤克里。$B$B請告訴他，我對那些皺縮的頭顱很滿意。",objectives={"將尼爾魯的草藥包送給菲拉斯的巫醫尤克里。"}]])
R(3123,"測試容器",[[description="這是一個測試，對我將要進行的儀式和你的能力來說都是一個測試。拿著這個容器，$N。你可以用它將一個生物的靈魂禁錮起來。$B$B到辛特蘭去尋找一種被稱作梟獸的生物，它們曾經是夜精靈的女神伊露恩的寵物。那些墮落、頭腦簡單而又野蠻的梟獸就是你的目標，$N。殺死十頭梟獸，在它們的靈魂逃跑之前用靈魂精華容器把它們收起來。",objectives={"到辛特蘭去殺掉10頭梟獸，然後使用靈魂精華容器捕獲它們的靈魂。"}]])
R(3124,"角鷹獸靈魂精華",[[description="Since you have proven that you are both trustworthy and gifted with the ability to use the muisek vessel, I now wish you to capture another creature.$B$BHippogryphs have been loyal companions to the night elves for many years; their spirits are loyal and steadfast.$B$BYour task is to kill 10 frayfeather hippogryphs, and quickly, shrink and capture them with the vessel, so that their muisek may be preserved. You will find the hippogryphs in the High Wilderness, to the south of here. ",objectives={"Kill 10 Frayfeather Hippogryphs of any type, then use the Muisek Vessel to shrink and capture them."}]])
R(3125,"精靈龍靈魂精華",[[description="$N, next I must have you capture a creature that in appearance, may look quite fragile, yet its powerful spirit is what we are truly after. The faerie dragons that I speak of have served the night elves as their allies. We must capture one so that the horde may benefit from this strength of spirit as well.$B$BHere is the muisek, $N. Kill 8 sprite darters or sprite dragons, and capture their muisek. They may be found to the west of here.",objectives={"Kill 8 Sprite Darters or Sprite Dragons. Use the Muisek Vessel to shrink and capture the fallen Faerie Dragons."}]])
R(3126,"樹人靈魂精華",[[description="The wandering forest walkers that can be found meandering through the forest are our next target, $N. Night elves have enlisted treants as allies to fight against the horde. Their movement may be slow, but their role as protectors is undeniable.$B$BSoon we will be able to use this power for our own benefit.$B$BFind 3 wandering forest walkers; kill them, and use the muisek vessel to shrink and capture them.",objectives={"Kill 3 Wandering Forest Walkers. Use the Muisek Vessel to shrink and capture the fallen Treants."}]])
R(3127,"山嶺巨人靈魂精華",[[description="The last task I will require of you is to travel to the northwest and find the final enemy.$B$BThe mountain giants left the mountains to aid the night elves when the burning legion appeared in the world. You will know them by their massive size and the way the ground begins to shake as you travel along their rocky terrain.$B$BI am eager to harness power of that size. Kill 7 mountain giants, then use the muisek vessel to capture their powerful muisek.",objectives={"Kill 7 Land Walkers or Cliff Giants. Use the Muisek Vessel to shrink and capture the fallen Mountain Giants."}]])
R(3128,"天然材料",[[description="我需要一些特定的材料來完成我的工作……你可以把這件事情與我要給你的其他幾個任務一起完成了。$B$B我需要菲拉斯樹人身上的一段斷裂的原木，西邊的那些山嶺巨人和精靈龍身上的包殼礦石，還有從荒蕪之地的梟獸或者菲拉斯的角鷹獸身上找到的有彈性的肌腱。最後，我還需要大量的金屬碎片，這些碎片可以從我剛才提到過的這些生物身上找到。",objectives={"為莫沙徹營地的巫醫尤克里收集2根斷裂的原木、6顆包殼礦石、20片有彈性的肌腱和40塊金屬碎片。"}]])
R(3129,"靈魂武器",[[description="Imbuing the muisek into the weapons is a difficult process. Now that I have all of the required materials and the muisek of the creatures that you captured, I may begin. Please wait; I will return in a moment.",objectives={"Witch Doctor Uzer'i wants you to wait for a moment while he prepares the weapons."}]])
R(3130,"憎世納迦之戰",[[description="現在，我要讓你到我的助手拉托尼庫斯那裡去，他一直都在密切注意納迦的動向。我會對這裡的綜合形勢作出評價，然後才能夠採取行動將他們趕出這裡，但是一旦我們發起攻擊，我們的要塞就必然處於部落的直接威脅下——或者更糟，因此這並不是最佳的方案。$B$B不管怎麼樣，拉托尼庫斯正在等著你。你的表現一直很不錯，$n，希望你能繼續保持。$B$B你可以出發了。",objectives={"到羽月要塞的拉托尼庫斯·月矛那裡去報到。"}]])
R(3141,"洛拉姆斯",[[description="So you wish to battle demons? You would do well to listen to my tale. ",objectives={"Listen to Loramus Thalipedes tell his story."}]])
R(3161,"加茲瑞迪安",[[description="$N, I'm a scientist, but also a treasure hunter at heart!$B$BLong ago, when trolls used to occupy this land, they created large amounts of ornaments modeled after Gahz'rilla, a hydra they worshipped as a deity. These ornaments are carved out of an element that I call \"Gahz'ridian,\" after the hydra god.$B$BI did find some myself, but I'd like to have some more to study -- maybe you can find some?$B$BI even invented a detector that makes finding the Gahz'ridian a snap! Just put it on, and the search begins! ",objectives={"Marvon Rivetseeker in Tanaris wants you to collect 30 Gahz'ridian Ornaments."}]])
R(3181,"瑪爾戈的巨角",[[description="這根巨大的角上有許多刮痕和裂痕，還有一塊金屬物體嵌在粗糙的表面上。$B$B經過進一步的檢查，你發現這塊金屬實際上是一把斷掉的斧頭。金屬上刻著一行字：$B$B巡山人貝波蒂所有。$B$B當你試著想把斧頭拔出來的時候，它碎裂成了無數的碎片。$B$B真是糟糕！",objectives={"將瑪爾戈的巨角交給巡山人貝波蒂。"}]])
R(3182,"證明信",[[description="你指望我會相信這樣一個故事？真正的角一定會有我的斧頭崁在上面的？$B$B聽著，把這個很明顯是膺品的東西拿給鐵爐堡的索里奧斯館長。如果他能證明你的話是真的，那麼你就能收到一份證明。把那份證明拿回來給我，我就給你灼熱峽谷的鑰匙。$B$B快動身吧！",objectives={"把瑪爾戈的巨角交給鐵爐堡的索里奧斯館長。"}]])
R(3201,"館長的證明！",[[description="我真不敢相信貝波蒂居然會懷疑這支角的真實性。別說出去，我認為她純粹是嫉妒而已。我知道她很想親手殺了那隻野獸，你的「意外」讓她的美夢破滅了。$B$B所以，你需要一個證明是嗎？你對博物館做出這麼大的貢獻，這絕對不是問題。$B$B<索里奧斯館長開始填寫一張很大的文件。>$B$B好了！你可以把它拿去交給貝波蒂了。",objectives={"把索里奧斯的證明信交給巡山人貝波蒂。"}]])
R(3221,"與倫弗利爾會面",[[description="While you were out helping our deathstalkers, Apothecary Renferrel sent you a summons.  He did not give me details, but he wanted to speak with you about the wolf hearts you had given him.",objectives={"Speak with Apothecary Renferrel at the Sepulcher."}]])
R(3241,"<NYI> <TXT><redux> Dreadmist Peak",[[description="Collect the totems from Dreadmist Peak, because it's icky there now and no place for shiny clean totems.",objectives={"Bring them to Tonga Runetotem."}]])
R(3261,"喬恩·星眼",[[description="Your time with me is over, $N.  To learn more, you must go to Camp Taurajo to the south and speak with Jorn Skyseer.  He will continue your guidance.",objectives={"Speak with Jorn Skyseer at Camp Taurajo."}]])
R(3281,"被偷走的銀幣",[[description="雖然你殺了迅猛龍，但是它們偷走的那些銀幣必須要找回來！我接到報告說有大量的迅猛龍聚集在棘齒城南邊，那裡現在被稱為迅猛龍平原，它們八成是把銀幣藏在那裡了。$B$B到那個迅猛龍的天堂，去找出被偷走的銀幣，然後把銀幣送回到我這裡來。",objectives={"把被偷走的銀幣交給十字路口的加茲羅格。"}]])
R(3301,"茉拉·符文圖騰",[[description="我的族友茉拉·符文圖騰去了銀松森林，她去那裡是為了幫助我們的不死族盟友。銀松森林狀況不佳，那是一片瀕死的森林，茉拉希望通過自己的努力給銀松森林帶來新的活力。也許在貧瘠之地找到的這種奇怪的生命形式能夠對她在銀松森林的工作有所幫助。$B$B把你收集到的龜殼樣品交給她吧，茉拉一般都在瑟伯切爾待著。如果運氣夠好的話，這些貝殼可以幫她找到治癒那片瀕死之地的方法。",objectives={"和瑟伯切爾的茉拉·符文圖騰談話。"}]])
R(3321,"秘銀會的認可",[[description="You have done much for the Order, $N. The sheer dedication it takes to get this far would have turned away any ordinary person. There is no doubt in my mind, or in the mind of Galvan, that you are one of us.$B$BWhich is why I think you deserve a little reward. It is nothing really, just a trinket. You may be familiar with its properties, as I do believe it is what brought you to us in the first place.",objectives={"Wait for Trenton to finish his work."}]])
R(3341,"寒冰之王",[[description="In the Barrens lies a horrid mess of tangled vines called Razorfen Downs. While our first observations of this place revealed little threat, our recent findings are much more serious...$B$BThe quilboar of Razorfen Downs have aligned themselves with the Scourge. A Lich named Amnennar the Coldbringer rules them now, using the power of his massive consciousness to control their every move.$B$BAmnennar has a direct telepathic link to Ner'zhul; we must sever this bond, $N. An end must come to the Coldbringer.",objectives={"Andrew Brownell wants you to kill Amnennar the Coldbringer and return his skull."}]])
R(3361,"逃難者的困境",[[description="我們把石齶怪趕出了諾姆瑞根，但是那裡變得一團糟！我們的家園現在充滿了輻射，我們地精也被分散在丹莫洛的各個角落。$B$B在逃避輻射的過程中，我遺失了所有的私人物品和工具！是食人妖搶走了我的東西，他們偷走了我的箱子，我的盒子，還有我的一桶螺釘！他們搶到東西後就一溜煙跑回他們的營地去了，就在安威瑪的西南邊。$B$B我不是冒險者——你能幫我把東西找回來嗎？",objectives={"把菲利克斯的盒子、菲利克斯的箱子和菲利克斯的螺釘桶交給安威瑪的菲利克斯。"}]])
R(3362,"灌木谷",[[description="你有沒有去過灌木谷？那是個非常危險的地方，$N。$B$B那裡到處都是奇怪的野獸，我根本不會冒險去靠近它們！那些野獸應該是被叫作長瘤的灌木獸和灌木塑根者……$B$B不管怎麼樣，我想要到那個山谷裡去看看，可是有那麼多的灌木獸在山谷裡活動，我可不想去送死。但是現在你來了——如果你能清除一些灌木獸的話，也許我就能去一趟了。我想你應該能幫忙吧，$N？幫幫我，好不好？",objectives={"加基森的特蘭雷克要你殺掉8隻長瘤的灌木獸和8隻灌木塑根者。"}]])
R(3363,"被腐化的輕歌花")
R(3364,"熱酒快遞",[[description="嘿！我早就該把這美味又熱騰騰的晨曦酒送給安威瑪的德南·弗卡特，不過我得先送一杯給附近的格瑞林！我肯定沒辦法在酒變涼之前把酒送給他！$B$B你看起來動作挺快的，也許你能辦到……這杯酒只能保溫5分鐘，德南要的可不是冰鎮熱酒，所以你一定要趕快！安威瑪就在這裡的東北邊，那個在山壁上鑿出來的大洞裡。$B$B謝謝你, $N, 別忘了把我的杯子帶回來！",objectives={"在5分鐘內把熱騰騰的晨曦酒交給安威瑪的德南·弗卡特。"}]])
R(3365,"歸還酒杯",[[description="太正點了！沒有什麼別的東西能像這杯熱騰騰的晨曦酒，在這個大冬天裡溫暖你的靈魂了！$B$B拿著這個，$N——幫個忙，把這個空杯子還給諾里，現在就去。",objectives={"把諾里的杯子還給諾里·激流。"}]])
R(3366,"发光的碎片",[[description="这块碎片透出异样的绿色光芒，虽然它完全是一块固体，但是却让人感觉好像有一股烟从碎片中冒出来。你情不自禁地注视着这块水晶的深处，这时你突然觉得这其中必定包含着许多曲折的故事。也许你应该去棘齿城看看那里有没有人知道这块碎片的来历。 ",objectives={"寻找更多有关这块噩梦碎片的信息。 "}]])
R(3367,"蘇塔拉之石",[[description="<杜里奧斯痛苦地呻吟著。>$B$B我受了重傷，$r。我感覺……頭重腳輕……世界在旋轉……身體裡面在出血。$B$B我必須回到鐵爐堡，幫幫我，$N……",objectives={"幫助杜里奧斯回到鐵爐堡。"}]])
R(3368,"蘇塔拉之石",[[description="我的好兄弟：$B$B如果你讀到這封信，表示我已經不在這個世界上了。至於這封信是怎樣到你手中的，我不得而知。不過記得感謝並獎賞那個交給你這封信的人。 $B$B關於那些石頭：它們確實存在，而且在黑鐵矮人手裡。他們的領袖，黑衣拉索里克正在使用石頭的力量來禁錮我們探勘隊的伙伴。他們被帶到了大熔爐那裡。他們的心志已經被扭曲，被迫不分晝夜地工作以完成一個名叫奧比斯頓的東西。$B$B幫幫他們，我的兄弟。這是一個死掉的人最後的希望了。$B$B——杜里奧斯",objectives={"把燒焦的信件交給鐵爐堡的索里奧斯，他在探險者大廳裡。"}]])
R(3369,"在噩夢中",[[description="This shard holds great secrets; it is the pure essence of the Emerald Dream. However, what I see in this shard is not a dream; one would call this sort of a vision a nightmare.$B$BI do not wish to alarm you, $N, but I think it is best if you deliver this shard into the hands of a wise druid as soon as you can.$B$BHamuul Runetotem on Elder Rise is who you need to find. Head to Thunder Bluff. I cannot say more. ",objectives={"Bring the Nightmare Shard to Hamuul Runetotem on Elder Rise."}]])
R(3370,"在噩夢中",[[description="This shard holds great secrets; it is the pure essence of the Emerald Dream. However, what I see in this shard is not a dream; one would call this sort of a vision a nightmare.$B$BI do not wish to alarm you, $N, but I think it is best if you deliver this shard into the hands of a wise druid as soon as you can... $B$BMathrengyl Bearwalker in the Cenarion Circle is who you need to find. Head to Darnassus. I cannot say more.",objectives={"Bring the Nightmare Shard to Mathrengyl Bearwalker in Darnassus."}]])
R(3371,"矮人的正義",[[description="我的心已被悲痛腐蝕，變成了一個空虛的黑洞，$N。杜里奧斯的逝去讓我一時之間無法恢復。我必須讓他的心願得以實現——那個冷血的兇手必須得到正義的懲罰。$B$B回到灼熱峽谷去，完成他最後的心願——拯救他的同伴。",objectives={"回去灼熱峽谷，尋找到杜里奧斯的考古隊員。"}]])
R(3372,"釋放他們",[[description="釋放他們，$c。即使他們的肉體已經不存在，桑塔拉的力量也會讓他們去完成自己的使命。$B$B桑塔拉祭壇是關鍵。到這裡的西北邊去，洞穴上面的山丘上……暮光之錘守衛著一件古器。拿到它，把它放在桑塔拉祭壇上。$B$B<瀕死的考古學家倒下了。>",objectives={"到西北方去尋找到被暮光之錘守衛著的神秘古器。"}]])
R(3373,"伊蘭尼庫斯精華",[[description="As you touch the gem, a deep voice resonates in your mind.$B$B\"Mortal, heed this plea.  I am Eranikus of the Green Dragonflight, keeper of this accursed temple.  My charge to ensure that the trolls never again bring forth their abomination of a god has for now ended in failure.  As I imbue this gem with part of my essence, I sense my grip on the Dream twisting into chaos.  Please - place this gem into the essence font in my lair, and let our magic there purge the taint from my psyche so that I may rest.\"",objectives={"Place the Essence of Eranikus in the Essence Font located in this lair in the Sunken Temple."}]])
R(3374,"伊蘭尼庫斯精華",[[description="You engage the Oathstone, and Itharius speaks directly to your mind through the stone.$B$B\"By accepting the charge placed in this Oathstone, you agree to aid my cause and the cause of Ysera's Dragonflight in redeeming the corrupted soul of Eranikus.  The first sacrifice, one of many you and I will no doubt make, will be to relinquish the gem to me that has chained what free-willed part of Eranikus' psyche remains.\"$B$B\"Do this $N, and we will work together to redeem a soul worthy of redemption.\"",objectives={"Bring the Oathstone of Ysera's Dragonflight and the Chained Essence of Eranikus to Itharius in the Swamp of Sorrows.  It is there that you will make your choice to aid Ysera's Dragonflight or not."}]])
R(3375,"占蔔之瓶",[[description="Um... you need another phial of scrying?  You're kidding, right?  What did you do with the first one?!  We have a lot of work ahead of us here, $r.  Those phials don't grow on trees!  Actually, I wish they did, because I'd go there and pick one off since I don't have another one!!$B$Bin order to make you one, I need the following: a mana potion, a piece of coal, and some sweet nectar.  Don't ask why, just bring me what I ask and I'll make you a new one.",objectives={"Bring a Mana Potion, Coal, and Sweet Nectar to Talvash del Kissel in Ironforge to get a replacement for Talvash's Phial of Scrying."}]])
R(3376,"刺鬃酋長",[[description="$N，我聽說過你的名字，新來的。或許你可以幫我們一個其他人都做不到的忙。$B$B我們牛頭人在這塊土地上建立了自己的家園，但是我們也付出了代價。刺刃峽谷中有一座刺背野豬人的村莊，在他們的首領——尖牙刺鬃酋長的帶領下，一直在與我們交戰，這讓我們的生活變得非常艱難。我要你去取回尖牙刺鬃酋長的首級！$B$B你可以在東邊的峽谷中找到他們那簡陋的村莊，刺鬃酋長就在村子裡面。",objectives={"把尖牙刺鬃酋長的頭顱交給紅雲台地的衛兵維薩羅·風羽。"}]])
R(3377,"艾露恩禱言",[[description="你願意幫我的忙嗎？聽聽我的故事吧。",objectives={"聽薩麥爾講述他的故事。"}]])
R(3378,"艾露恩禱言",[[description="你願意幫我的忙嗎？你能找到伊露恩祈禱文嗎？$B$B就如我所說的，祈禱文被刻在一塊金色的石板上，那些崇拜它的惡棍中的某個一定把它占為己有。$B$B如果你能夠找回我的祈禱文，就把它交給達納蘇斯的阿斯塔利·逐星者吧。如此我才能在遭受如此多不幸之後重新恢復信心，而且更加重要的是，我的祈禱能夠有人聽見，至於我是否能被寬恕，對我來說已經不重要了。",objectives={"找到伊露恩祈禱文，然後交給達納蘇斯的阿斯塔利·逐星者。"}]])
R(3379,"暗影蛛絲",[[description="灼熱峽谷的蜘蛛可以為我們提供暗影蛛絲。如你所知，暗影蛛絲在我們的交易中有著很大的需求量。$B$B最近有一批偷獵者來到了這裡，他們隨意地屠殺蜘蛛，根本不關心他們的行為可能造成的長期影響。我給你的第一個任務非常簡單：找到他們……然後終結他們。$B$B到北邊去開始你的搜索吧。$B$B如果你需要幫助的話，就去和拉茲談談。",objectives={"殺死在灼熱峽谷遊蕩的暗影蛛絲偷獵者小隊。尼莉絲認為他們共有5名成員，你的任務就是把他們全都幹掉。"}]])
R(3380,"沈沒的神廟",[[description="There are restless spirits in this world, $N. There are spirits that have been tainted by their isolation, bound to an ancient evil...$B$BI have heard of a place that lies deep below the surface of the earth -- banished there by powers greater than I have ever seen.$B$BIf you wish to learn more of this place; the Sunken Temple, seek out a goblin named Marvon Rivetseeker. He has studied many ancient areas of the world, and was last known to have left his home in Ratchet to study the troll ruins in Tanaris.",objectives={"Find Marvon Rivetseeker in Tanaris."}]])
R(3381,"A Meeting with the Master",[[description="Ah, a young $r come to speak to Sanath. What a wonderful day! I am so honored to have you grace me with your presence. Thank you!$B$BPlease... do not be so arrogant to assume my sarcasm was a compliment. Let us get one thing straight: I don't like you. But this little conversation doesn't have anything to do with us--it has to do with my master.$B$BBring me a couple hippogryph feathers for my arrows and I'll give you leave to see him. He's asked that I send adventurers to him if they proved worthy enough.",objectives={"Bring 2 Undamaged Hippogryph Feathers to Sanath Lim-yo in Azshara if you wish to speak to his master."}]])
R(3382,"危難中的船長",[[description="We were just off the coast looking for a safe haven to make anchor. The sun hadn't been down for more than an hour when they attacked... those damned naga!$B$BI'm not sure what they were looking for, but it's clear they didn't find it--they've already come back once. A couple of my scouts are on watch at the entrance of the valley to give us fair warning when the next attack comes.$B$BI'm sorry you've come along now, $N, but it's out of my hands.$B$BAre you ready for the fight of your life?",objectives={"Defend Captain Vanessa Beltis, her crew and the Horizon Scout's passengers against the naga attack. Captain Vanessa Beltis must survive."}]])
R(3383,"<UNUSED>")
R(3384,"<UNUSED>")
R(3385,"黑市交易",[[description="他們把自己稱為黑市：他們都是些貪財如命的殺人交易者，只要有利可圖，他們什麼都會販賣！$B$B現在情況變得更加糟糕了，$N。他們在灼熱峽谷建立了一個基地。貿易首領考維克在那裡策劃著所有的行動，並且和該地區的黑鐵矮人保持著密切的關係。$B$B我們必須對這種行為進行嚴厲打擊，給他們一個嚴厲的警告。去殺掉貿易首領考維克和他的同夥科朗克。把他的商人背包拿回來給我，你的任務就算完成了。$B$B向大熔爐前進！",objectives={"殺了貿易首領考維克和他的同夥科朗克。從他的屍體上拿回商人的背包，把它交給尼莉絲。"}]])
R(3401,"<UNUSED>")
R(3402,"黑市交易",[[description="I want you to personally deliver the news of Kovic's defeat to Vizzklick in Gadgetzan. He will be so happy to hear that Kovic is dead that I'm certain he'll give you some grand reward.",objectives={"Speak with Vizzklick in Gadgetzan."}]])
R(3403,"<UNUSED>")
R(3404,"<UNUSED>")
R(3405,"<UNUSED>")
R(3421,"回程")
R(3422,"<UNUSED>")
R(3423,"<UNUSED>")
R(3424,"<UNUSED>")
R(3425,"<UNUSED>")
R(3441,"神聖的懲戒",[[description="聽聽我的故事吧，旅行者。",objectives={"聽卡拉然·溫布雷講述他的故事。"}]])
R(3442,"無瑕之焰",[[description="你做出了正確的決定，$N。$B$B我們必須對敵人的要害下手，除掉那四座哨塔。$B$B一旦這四座塔都化為灰燼，我們就可以在他們反應之前發動攻擊。$B$B你需要合適的工具來點燃防禦塔，而製作這樣的工具就需要合適的材料。$B$B給我弄四份烈焰之心和四份傀儡之油來，然後我就會給你製作出一把燃燒著無瑕之焰的火炬。$B$B在這片土地上的傀儡和元素生物身上找找吧。",objectives={"收集4份烈焰之心和4份傀儡之油，然後把這些東西交給卡拉然·溫布雷。"}]])
R(3443,"鑄造火炬桿",[[description="為了承載無瑕之焰，我們將會需要一根桿子和一個箱子，你必須先找到一根合適的桿子。$B$B大熔爐的黑鐵工頭和黑鐵奴隸販子使用強化過的瑟銀所作的武器，一種非常堅硬的合金。如果你可以為我弄到八把瑟銀匕首，我就能將它們熔解並鑄成一根桿子。",objectives={"帶8把瑟銀匕首給卡拉然·風刃。"}]])
R(3444,"石環",[[description="我曾經進入到沉沒的神廟中的那個充滿邪惡氣息的房間，那裡的惡魔會殘忍地殺死每個進入房間的冒險者……我在那些滿是泥濘的房間裡艱難前進，差點就找不到出來的路了。我只記得自己蹣跚地穿過一個圓形的房間，房間裡到處都是毒蛇塑像……$B$B最後，我發現了一塊圓石，上面印著相同的毒蛇標記，我把它打包運到棘齒城的車間去了。去把它取回來，也許我能讓你知道更多的資訊。",objectives={"到棘齒城去，從瑪爾馮·瑞文斯克的車間裡取回石環。"}]])
R(3445,"沈沒的神廟",[[description="我聽說有一個地方被埋在地底的深處，被一個我從未見過的強大力量所造成的。$B$B如果你想要對這個沉沒的神廟有更多的瞭解，就去找一個名叫瑪爾馮·瑞文斯克的哥布林吧。就像特洛亞斯和我一樣，他也探索過許多人跡罕見的地區。聽說他離開了在棘齒城的家，前往塔納利斯研究食人妖遺址去了。$B$B祝你好運，我好久都沒有他的消息了。",objectives={"到塔納利斯尋找瑪爾馮·瑞文斯克。"}]])
R(3446,"深入神廟",[[description="在神廟裡，我發現一間有著六個陽台的圓形房間，每個陽台的邊緣都有一尊毒蛇塑像。我在好奇心的驅使下，我推動了其中的一個，隨即發現這是個陷阱！我差點就在爆炸中丟了性命。我躺在台階上往下看，我注意到在房間的底部還有一尊塑像，好像是什麼神的祭壇……哈卡祭壇？似乎是這個名字。$B$B我認為這祭壇就是秘密所在—你必須把這個石環帶到沉沒神廟中的那個祭壇上去……",objectives={"在悲傷沼澤的沉沒神廟中找到哈卡祭壇。"}]])
R(3447,"雕像群的秘密",[[description="我的記憶有些模糊，但是我將盡我所能的把我所知道的都告訴你。雖然沉沒神廟中的雕像群充滿危險，但是我相信它們正是揭開一筆巨大財富的鑰匙。$B$B從主祭壇來看，我能啟動一系列的光。我認為如果你能找出這些光代表著什麼，你或許就能夠解開這房間中所隱藏的秘密。$B$B但是我要警告你，$N。神廟中有可怕的惡魔。它們很可能忠心地守護著那些有價值的事物……",objectives={"去沉沒的神廟，找出雕像群中隱藏的秘密。"}]])
R(3448,"委以重任",[[description="最近我一直在負責調查艾薩拉地區，那片美麗的土地曾經是精靈的故鄉，他們曾在此研習魔法。現在這兒變得非常危險，但是這並不能阻止我們搜尋每一寸土地來尋找我們的歷史。$B$B我的同伴泰摩爾對這樣的事情特別感興趣，因此他願意幫助我調查艾薩拉。$B$B在城裡的秘法大廳右邊有一間小房子是他的。",objectives={"跟鐵爐堡的泰摩爾談話。"}]])
R(3449,"奧術符文",[[description="秘法曾經跟月神伊露恩一樣，受到某些精靈的尊崇。他們中最厲害的法師發明了符文跟石板，記錄下秘法的規則和他們對事物的研究成果。他們把這些都公開讓所有人一起思考。$B$B我非常想要這些來自埃達拉斯廢墟的符文拓片。我將會提供工具來幫助你取得拓片，但是你可以自己決定要不要去找這些石板。凡是要小心，對埃達拉斯廢墟感興趣的可不止探險者聯盟。",objectives={"在前往艾薩拉南部半島處的小島之前，使用繪圖工具獲取貝薩瑪拉符文、辛耶爾符文、瑪寇里符文和塞爾哈符文的拓片，然後通知駕駛員希格斯·熔火去拾取這些拓片。"}]])
R(3450,"簡單的接收任務",[[description="我想把這些拓片送到我的塔裡去，但是你不必親自跑一趟，我會把它們空運到艾薩拉。$B$B希格斯·熔火欠我幾個人情，而且他馬上就會到這個地區來—因為他被派遣到海岸邊巡邏。在你離開之前，別忘了去跟他談談。他會給你一支閃光彈發射器用於發送信號。當你拿到拓片之後就到他指定的地點去發信號給他，這樣他就能把拓片安全地送到我的塔裡了。現在他應該在軍事區的機棚裡。",objectives={"與鐵爐堡的希格斯·熔火談話。"}]])
R(3451,"信號發射器",[[description="啊，是泰摩爾派你來的，是嗎？對，我還欠他人情呢。怎麼？哦，那個小惡魔，是的，我當然可以幫助他。你需要一把信號槍和一個合適的地點……就行了。$B$B在艾薩拉南部的半島附近有一座小島，我們在那裡已經有個起落台。拿著這把信號槍，在那個地方使用它，我就能看見信號，然後過去接收那個……隨便他想要什麼東西了。",objectives={"與鐵爐堡的希格斯·熔火談話，從他那獲得一支標準型信號槍。"}]])
R(3452,"烈焰之盒",[[description="我們還需要最後一部分來完成火炬。$B$B在西北方的山腳下，你可以找到暮光之錘的營地。據說他們攜帶著特殊的徽章和石像，用以表示對神明的崇敬。這些徽章和石像具有強大的魔法能力，足以製成一個魔法容器。將拉格納羅斯符記交給我，我將試著從裡面提取魔法，然後製造一個容器。",objectives={"找到一個拉格納羅斯符記，把它交給卡拉然·溫布雷。"}]])
R(3453,"懲戒火炬",[[description="給我一點時間來拼合這些碎片，然後對它進行必要的附魔。",objectives={"等待卡拉然·溫布雷完成懲戒火炬。"}]])
R(3454,"懲戒火炬",[[description="現在，火炬必須與它的擁有者建立聯結。拿起火炬，$N。",objectives={"拿起懲戒火炬。"}]])
R(3461,"向法師泰摩爾回復",[[description="泰摩爾並沒有給我什麼可以付你報酬的東西，我建議你回鐵爐堡去的時候好好跟他交流一下。我想他還在秘法區，去找他吧，他會付你報酬的。$B$B再次感謝你幫助他擺脫困境，祝你好運。$B$B哦，我不需要繪圖工具包啦，你為什麼不順便把它還給泰摩爾呢？",objectives={"到鐵爐堡去，將法師泰摩爾的繪圖工具包還給他。"}]])
R(3462,"侍衛瑪特拉克",[[description="跟我的使者——侍衛瑪特拉克談談吧,他會進一步指導你使用懲戒火炬的方法。",objectives={"與侍衛瑪特拉克談話。"}]])
R(3463,"燒掉它們！",[[description="聽好了，$N。雖然我們無法摧毀那四座哨塔，但是你可以使用懲戒火炬點燃它們，這種火焰是任何元素或力量都沒法熄滅的。$B$B在哨塔燃燒的過程中，沒有什麼部隊可以駐紮在裡面，這樣他們的第一道防線就失效了。$B$B你必須進入每一個塔樓，用懲戒火炬把它們燒掉。要小心黑鐵矮人的精英哨兵，$N。",objectives={"使用懲戒火炬點燃北部、南部、東部和西部的哨塔。"}]])
R(3481,"打開箱子…",[[description="箱子似乎上鎖了。",objectives={"打開箱子。"}]])
R(3482,"<NYI> <TXT> The Pocked Black Box",[[description="This is the horde version of the black box quest.",objectives={"Take this box to Kravel."}]])
R(3483,"信號發射器")
R(3501,"多多益善",[[description="儘管你可能找不到純淨無暇德萊尼水晶，但是在你探索這片土地的過程中，一定可以找到若干有瑕疵的德萊尼水晶碎片。$B$B庫米沙是否可以利用這些碎片返回家園，這還很難說，但是這些碎片可以為德萊尼人所用。$B$B把你發現的有瑕疵的德萊尼水晶碎片都交給我，我會給你報酬的。",objectives={"將有瑕疵的德萊尼水晶碎片交給庫米沙，你就可以得到相應的回報。"}]])
R(3502,"德萊尼的垃圾…",[[description="Well, after that display of voracious greed, I feel nauseous.$B$BRegardless, I shall not dwell too long on your material addiction.$B$BFor each imperfect draenethyst fragment you turn in, I shall reward you with more junk. My junk heap gets smaller while your junk heap gets larger. On Draenor we call this a 'win-win' situation.",objectives={"Bring Kum'isha Imperfect Draenethyst Fragments. Any form of monster in the Blasted Lands could be carrying a fragment."}]])
R(3503,"見到主人")
R(3504,"叛徒",[[description="Betraying, thieving woman! That's what I call her--that's all she'll ever be!$B$BI may have made a grave mistake, $N. I trusted a blood elf. What's worse, I trusted a woman!$B$BShe claimed Azshara would hold great riches... powerful items. I simply send some warriors with her to protect her and I would be rewarded. Well, look who's the fool--she's killed them all.$B$BI want vengeance, $N, but I can't afford to send anyone else. Find Ag'tor at Valormok, north of the Haldarr Encampment. He'll tell you more.",objectives={"Deliver the Sealed Letter to Ag'tor to Ag'tor Bloodfist in Azshara."}]])
R(3505,"叛徒",[[description="I thought as much.$B$BWe start our crusade against her workers along the southern bluffs on the northern peninsula of Azshara. Kill them with bloody rage--let them know they've betrayed the wrong allies.$B$BDo not concern yourself with her yet--she spends most of her time with her bodyguards searching Azshara. It would be prudent after you've slain her workers to find her personal camp. Scouting out where we can attack her would be wise. Perhaps there is something there we can use to provoke her.",objectives={"Kill 10 Blood Elf Reclaimers, and 10 Blood Elf Surveyors before seeking out Magus Rimtori's camp. Once you've found it, look for something that might be important to her that can be used to draw her into a fight."}]])
R(3506,"叛徒",[[description="A few more moments of thought brings a few ideas to mind, one of which brings a smile to your face: perhaps destroying the crystals would upset the blood elf responsible for the slaughter of so many orcs and the betrayal of Belgrom?$B$BYou continue to decipher more of the script and pictures and realize that one of the crystals is tied to the creator of the circle--the others are tied to something far more sinister.$B$BYou close the book and begin to decide which crystal to destroy. ",objectives={"Destroy the arcane focusing crystal tied to Magus Rimtori and then slay her. Afterwards, take the Head of Magus Rimtori to Ag'tor Bloodfist in Azshara."}]])
R(3507,"叛徒",[[description="Return to Belgrom in Orgrimmar. He will want to see her head for himself! We'll return there shortly.$B$BAh, this is indeed a good day. Thank you for your help, $N.",objectives={"Speak to Belgrom Rockmaul in Orgrimmar."}]])
R(3508,"破壞結界",[[description="You are foolhardy, $N. It is an admirable quality of your kind - to blindly enter battle when you have little to no chance of success. I will assist you, if only to see just one of Razelikh's minions fall.$B$BTo break the ward placed over Razelikh's subordinates will take time and require the acquisition of rare artifacts.$B$BBe still, I must first perform the enlightenment ritual. The information I gather will assist me in forging weapons of great power.",objectives={"Wait for Loramus to complete the enlightenment spell."}]])
R(3509,"惡魔之名",[[description="There is only one way to harm the demon lord and his minions. A weapon of power must be forged bearing his true name.$B$BWhen such a weapon is forged, the demon and all under his command are vulnerable.$B$BA lesser deity resides in Azshara: Lord Arkkoroc. You must seek him out but be warned, his minions will stop at nothing to destroy you if you are discovered.$B$BUndoubtedly, you will have to pay a price for such information. ",objectives={"Speak with Lord Arkkoroc in Azshara. Begin your search at the waters edge to find the Temple of Arkkoran."}]])
R(3510,"惡魔之名",[[description="She kills my children, mortal. She that calls herself the ruler of these oceans. A false god, nothing more. Crush her and bring back all of her heads.$B$BFor that, you will be given the name that you seek and something else of equal importance.$B$BShe roams the clutch... Hetaera she is called.$B$B<Lord Arkkoroc points to the southwest.>$B$BGo!",objectives={"Slay Hetaera and bring back Hetaera's Bloodied Head, Hetaera's Beaten Head, and Hetaera's Bruised Head to Lord Arkkoroc."}]])
R(3511,"惡魔之名",[[description="As promised, I will reveal the name of the demon lord, Razelikh the Defiler. First, however, I must prepare something of utmost importance for your journey.$B$BThe weapon you seek to create requires a temper. Give me a moment to drain the blood from these heads.$B$B<Lord Arkkoroc squeezes the heads in between his gigantic fists, draining them of their blood.>$B$BTake the temper back to Loramus along with the name of the beast: Rakh'likh.",objectives={"Take the temper back to Loramus Thalipedes."}]])
R(3512,"幫助伊蘭尼庫斯",[[description="$N，第一步，我們將設法通過寶石與伊蘭尼庫斯交談。現在他正處於半睡半死的不穩定狀態，並受到噩夢的困擾。儘管你給我的精華已經被嚴重污染，但我們還是有機會跟他溝通的。$B$B到冬泉谷東部的冰川地帶去尋找我們的盟友，靈語者阿姆布蘭希。他可以與死者進行交談——儘管伊蘭尼庫斯並沒有真正死去，但阿姆布蘭希依然會對我們有所幫助。",objectives={"到冬泉谷的東部地區去，與靈語者阿姆布蘭希談話。"}]])
R(3513,"符文卷軸",[[description="這份看起來很正式的卷軸被一條銀色絲帶緊緊地裹著。你覺得會有什麼人對此感興趣，但是這人是誰呢？$B$B在梣谷邊界以北有一處前哨站，如果卷軸上的資訊與夜精靈有關，那麼你就應該把它送到那兒去。",objectives={"將符文卷軸帶到貧瘠之地的北部警戒塔去。"}]])
R(3514,"部落的示威",[[description="This scroll is from that scheming dryad Rynthariel, Keymaster of the Talon Den on Stonetalon Peak.$B$BShe'll not be making any more contact with the messenger you looted this from, heh, but we must stand our ground here. The Horde will not tolerate her outrunners here.$B$B$N, travel to the Talon Den. Kill Rynthariel, and then put up a symbol for all to see. Take this Horde flag, $N. Put it up in the Talon Den so that they will not be so rash as to send another messenger through our territory again.",objectives={"Kill the leader of the Talon Den, Rynthariel the Keymaster."}]])
R(3515,"<UNUSED>")
R(3516,"<UNUSED>")
R(3517,"偷竊知識",[[description="I admit, $N, I've made the most of my situation in Azshara. Belgrom's punishment has had its share of benefits.$B$BBefore I left, I did some research and you would be surprised how many valuable items are lying around.$B$BI'll tell you more about my deals, and even give you a cut of the profits, if you help me gather some of them.$B$BThere are tablets throughout the Ruins of Eldarath to the east that I need. All four are named after Highborne wizards. Get them for me and we'll talk some more.",objectives={"Find the Tablet of Beth'Amara, the Tablet of Jin'yael, the Tablet of Markri, and the Tablet of Sael'hai before returning to Jediga in Azshara."}]])
R(3518,"瑪加薩的石版",[[description="The first tablet goes to a tauren female... one called Magatha. She is among the elders in Thunder Bluff, and is one of the proponents of the alliance between the tauren and the Forsaken. She, more than anyone among the elders, feels the tauren and their ways can help the Forsaken find a path back to being human.$B$BBring her the Tablet of Beth'Amara. The tablet may be the link she needs in finding a way to help the Forsaken... or so she claims.",objectives={"Bring the Tablet of Beth'Amara to Magatha in Thunder Bluff."}]])
R(3519,"需要幫助的朋友",[[description="啊啊啊……我在探索旁邊那個蜘蛛洞的時候被一隻名叫基塞伊斯的蜘蛛咬成了重傷。我知道自己中了劇毒，你必須幫幫我。$B$B請把我中毒的消息告訴迪蘭妮亞·銀光，她知道該怎麼辦。$B$B快一點……我的頭好暈……",objectives={"與幽影谷的迪蘭妮亞·銀光談話。"}]])
R(3520,"尖嘯者的靈魂",[[description="我在尋找菲拉斯的山谷尖嘯者的靈魂。它們是某個非常非常古老的神靈表親，他們的靈魂與這位神靈連在一起。$B$B帶著這把剌藤魔杖去菲拉斯。在菲拉斯南部和中心區域尋找並殺死山谷尖嘯者，剌藤魔杖在他們的屍體上揮舞。這將誘使他們的靈魂現出原形。觸碰這些靈魂以收集他們的精華。$B$B然後將我的剌藤魔杖和你收集到的靈魂精華交給我，我就會告訴你先前提到的那位古老神靈的詳細情況。",objectives={"到菲拉斯捕獲3個尖叫者的靈魂，然後回到熱砂港的葉金亞那裡。"}]])
R(3521,"埃沃隆的解藥",[[description="我們也許能幫埃沃隆的忙，我知道有種方法能解蜘蛛毒。但是我需要一些原料來製作解藥。$B$B首先是紫藍色蘑菇，它們一般生長在樹下，你也可以從南邊的劣魔身上找到它，劣魔們似乎很喜歡這種蘑菇。我還需要月牙百合花，它們只生長在水池周圍。$B$B最後一種原料也許是最難獲得的，你必須從咬傷了埃沃隆的蜘蛛身上取得樹林蜘蛛的膿液。",objectives={"在幽影谷中為迪蘭妮亞·月光收集7朵紫藍色蘑菇、4朵月牙百合花和一份樹林蜘蛛的膿液。"}]])
R(3522,"埃沃隆的解藥",[[description="解藥準備好了，$N。請你親自看著埃沃隆把它喝下去。$B$B提醒你一下，解藥的有效時間只有5分鐘。你必須及時地把解藥送給他。$B$B趕快去吧，$N。",objectives={"在5分鐘內將埃沃隆的解藥交給他。你可以從在北邊的洞穴旁找到埃沃隆。"}]])
R(3523,"剃刀高地的亡靈天災",[[description="Outstanding!  My name is Belnistrasz, and I thank you for rescuing me.  I had given myself up for dead... or worse, as a meal for these Scourge-infested vermin.  Yes - I said Scourge all right; they've brokered some sort of deal with the Quilboar here, and this nightmare is a result.$B$BListen... rather than just flee, I want to make a difference for all of our sakes.  Would you be up to helping me out to that end?  It's probably dangerous, but you seem to be the type not to worry about that too much.",objectives={"If you agree to aid Belnistrasz, speak with him again and hand the Oathstone he gave you back to him."}]])
R(3524,"擱淺的巨獸",[[description="Majestic sea creatures are known to launch themselves at the Darkshore coastline, beached there until they die. Lately, these beasts have been washing ashore in ever-increasing numbers.  I've been sent here by the Temple of the Moon to investigate, but the presence of murlocs along the water has made my research difficult.$B$BThere is a giant creature washed ashore just south of Auberdine that is ringed by the foul Greymist murlocs.  Could you go there and retrieve bones from the creature for our study?",objectives={"Recover Sea Creature Bones from the beached sea creature just south of Auberdine, and then return with it to Gwennyth Bly'Leggonde in Auberdine."}]])
R(3525,"封印神像",[[description="Near the entrance is an idol that functions as a macabre oven for the Quilboar; the beasts... they literally consume their abductees from the Barrens.  I can shut down the idol and bind them from using it again, but I need your aid in doing so.  My plan: escort me to the idol.  Once we arrive, I'll commence the ritual.  I'll barely be able to communicate with you, let alone defend myself.  Protect me while I shut down the idol.  If they take me down, then it's all over for us.$B$BAre you with me?!",objectives={"Escort Belnistrasz to the Quilboar's idol in Razorfen Downs.$B$BProtect Belnistrasz while he performs the ritual to shut down the idol."}]])
R(3526,"地精工程學",[[description="Expert engineering yields two distinct disciplines: gnome and goblin.  Clearly, goblin engineering is the choice of all brilliant engineers.  Learn to master the world through the judicious use of high explosives and fantastic gear!$B$B$N, read this manual.  If you want to learn about goblin engineering, then take it to Nixx Sprocketspring in Gadgetzan.   Remember - membership is permanent and prevents joining the other discipline, so make sure this is what you want before finishing his task.",objectives={"If you wish to learn more about Goblin Engineering, take the Manual of Engineering Disciplines to Nixx Sprocketspring in Gadgetzan."}]])
R(3527,"摩沙魯的預言",[[description="摩沙魯古老的預言中提到一個控制神靈哈卡靈魂精華的方法。這方法被寫在兩塊石板上，並被帶到加基森以西食人妖城市的祖爾法拉克。$B$B將摩沙魯石板帶來給我！$B$B第一塊石板在死去多時的食人妖殉教者塞卡手中。據說被他殺害的人受到詛咒變成了甲蟲，正在毀壞他的神殿。$B$B第二塊石板在加茲瑞拉聖池的水占師維蕾薩手中。$B$B當你得到石板後，將它們帶來給我。",objectives={"將第一塊和第二塊摩沙魯石板交給塔納利斯的葉基亞。"}]])
R(3528,"神靈哈卡",[[description="現在是獲取哈卡化身的精華的時候了。$B$B把哈卡之卵拿到悲傷沼澤的那座沉沒的神廟中，在墮落之神的聖地中使用卵的力量激怒死去的神靈。$B$B他將派出那些被稱作「嗜血者」的奴僕對付你，殺掉它們，取出它們的哈卡萊血液，然後用這些血液熄滅包含哈卡靈魂能量的不滅火焰。當你熄滅所有的火焰時，哈卡的化身就可以進入我們的世界了。$B$B打敗他，將他的精華封印在哈卡之卵中。",objectives={"將裝滿的哈卡之卵交給塔納利斯的葉基亞。"}]])
R(3529,"<UNUSED>")
R(3541,"傑斯雷蒙的石版",[[description="I have a fence in Orgrimmar. He resides in The Drag. He's difficult to nail down if you don't know where to look, but if you go looking in one of the highest buildings there you should have no problem finding him.$B$BDo me a favor though, don't go shouting to all of Kalimdor that he's there and what his business is--it'd be bad for both of us.$B$BHe'll give us more than a fair price for the Tablet of Jin'yael. I'm not sure why, but you should have seen how excited he was to hear about its whereabouts.",objectives={"Bring the Tablet of Jin'yael to Jes'rimon in Orgrimmar."}]])
R(3542,"安德隆·甘特的石版",[[description="Andron Gant is my next contact. He usually holds himself up in the Undercity... right near the Apothecarium.$B$BHe was a little more loose-lipped when it came to speaking about what he wanted the Tablet for. Apparently some of the mages of Undercity are looking to study some of the arcane spells the highborne used. They think this tablet will help them. Markri was adept at summoning creatures; especially elementals.$B$BTake the Tablet of Markri and return to me for your part of the reward.",objectives={"Bring the Tablet of Markri to Andron Gant in Undercity."}]])
R(3561,"大法師克希雷姆的石版",[[description="This final tablet goes to someone very dangerous, $N. Heed me when I tell you that I trust this person far less than anyone else I've asked you to meet with.$B$BArchmage Xylem has a tower up in the hills overlooking Azshara. He's human, but he acts like no human I've met... or killed. He exudes power, and I dare not ask him what he plans on doing with the tablet.$B$BHe came to me, but told me that his bodyguard Sanath would help me get to the tower when I was ready to meet him. Look north for Sanath.",objectives={"Bring the Tablet of Sael'hai to Archmage Xylem in Azshara."}]])
R(3562,"瑪加薩的報酬",[[description="Take this note to Jediga. Tell her the payment will be here for her when she returns. And tell her I am pleased with her work.$B$BGo swiftly, $N. Tell your master I will be awaiting her here.",objectives={"Deliver Magatha's Note to Jediga in Azshara."}]])
end f(R) end
do local function f(R)
R(3563,"傑斯雷蒙的報酬",[[description="Take this letter to Jediga. Let her know that our deal has been beneficial and I be pleased with her work.$B$BYou tell her she come back to Orgrimmar fast and Jes'rimon make sure he take good care of her.$B$BTell her that, and maybe in the future I have need of your services again, $N.",objectives={"Deliver Jes'rimon's Note to Jediga in Azshara."}]])
R(3564,"安德隆的報酬",[[description="Here... take... <hic> this to Jediga. Good luck to ya!",objectives={"Deliver Andron's Note to Jediga in Azshara."}]])
R(3565,"克希雷姆的報酬",[[description="What is it? Oh yes, your payment. Of course.$B$BTake this and be off with you. I'm sure Jediga is awaiting oh so patiently for your return.",objectives={"Deliver Xylem's Note to Jediga in Azshara."}]])
R(3566,"奧比斯頓",[[description="這……這……這是個陷阱。$B$B原諒……我。$B$B殺掉那個該死的混蛋……為我們殺掉他……為了索里奧斯。",objectives={"殺死黑衣拉索里克和奧比斯頓，帶著黑衣拉索里克的頭顱和奧比斯頓的心臟回到鐵爐堡的索里奧斯那裡。"}]])
R(3567,"登高")
R(3568,"墮落之水",[[description="See that tauren behind me--the one who looks like she's going to be ill at any moment? She was in Azshara recently. She claims she was wounded by some naga while making her way through the Ruins of Eldarath.$B$BAfter fighting off a few of them, she took a break on the beach and drank from one of the tide pools. Now she's feeling nauseous... among other things.$B$BI'd like to find out what she drank. Take this box, in it are some empty vials I labeled. Fill each at different pools and come back.",objectives={"Fill all 4 Empty Vials at the tide pools along the coast of the Ruins of Eldarath in Azshara before returning to Chemist Cuely."}]])
R(3569,"墮落之水",[[description="Give this to Thersa. Perhaps it will cure her... perhaps not. We really won't know until after she drinks it.",objectives={"Give Cuely's Elixir to Thersa Windsong in Undercity."}]])
R(3570,"墮落之水")
R(3581,"Plainsrunning",[[description="Imagine yourself racing across the plains, through forests and over mountains, the wind in your face... Traveling over unseen territory",objectives={"Speak to Saern Priderunner again to learn the Plainsrunning skill."}]])
R(3601,"我就是基姆加爾！",[[description="本人就是基姆加爾！！你知道基姆加爾對血精靈意味著什麼嗎，$N？一隻小老鼠……或者其他類似老鼠的東西，那些只會欺凌弱小的傢伙！$B$B他們雇用我來幫他們在這裡搜尋某種失落的寶物，當他們告訴我寶物的數量和願意付給我多少錢時，我就決定去做了，他們卻馬上翻臉，還想殺死我……我！$B$B所以，你看，永遠都不要相信血精靈。$B$B問題是，我的裝備還在他們手裡，我自己是拿不回來了。你能幫幫我嗎？",objectives={"搜索薩拉斯營地，尋找基姆加爾的指南針，望遠鏡，燒雞和花生，然後將它們交還給艾薩拉的基姆加爾。"}]])
R(3602,"艾薩拉水晶",[[description="The ancient cliff giants of the southern region of Azshara consume the rock and buildings of the land for sustenance. The excrement from their consumption is a highly malleable and extremely strong crystal known as Azsharite.$B$BThe formations litter the southern arc, but few are ever recovered due to the extremely violent nature of the giants.$B$BYou are to venture south and recover enough of the Azsharite for the creation of the weapon's body. My felhounds will aid in the recovery of the crystal.",objectives={"Recover twenty Crystallized Azsharite from southern Azshara. You may use the Felhound to assist you in 'sniffing' out the location of cleverly hidden deposits.$B$BReturn to Loramus when the task is complete."}]])
R(3621,"武器的鑄造",[[description="The weapons are ready to be forged. You must take the tempered azsharite to one with the ability to harness fel energy.$B$BIn Stranglethorn Vale such a blacksmith exists. Galvan the Ancient, leader of the Mithril Order, will craft the weapons to your specifications. You will find his encampment between Zul'Gurub and the Mosh'Ogg ogre mound.$B$BMay your determination and faith carry you through this ordeal. Should you fail, know that your God smiles down upon you, mortal.",objectives={"Take the Shipment to Galvan the Ancient in Stranglethorn Vale."}]])
R(3622,"<UNUSED>")
R(3625,"魔化艾薩拉水晶武器",[[description="$N, the creation of each weapon will take some time.$B$BAdditionally, you may only use the power of the Felcurse once per three minutes. Its weakening properties against Razelikh the Defiler and his minions may be variable in duration. This is why you must release the Felcurse only when the moment is right!$B$BNow give me a moment to craft your weapon, $N.",objectives={"Wait for Galvan to finish forging the weaponry."}]])
R(3626,"返回詛咒之地",[[description="The hour of redemption is near, $N. You must return to the Blasted Lands with your new-found weaponry and speak with the Fallen Hero of the Horde to receive your final objective.",objectives={"Return to the Fallen Hero of the Horde."}]])
R(3627,"收集破碎的護符",[[description="要見到污染者的話，你就必須摧毀他手下的三個頭目的力量，然後把他們身上的護符碎片收集起來。當你拿到三塊碎片之後再回到我這裡來，我會給你進一步的指示。$B$B出發吧，$N！到詛咒之地去！把戈洛爾、瑟溫妮、奧利斯塔全部除掉！",objectives={"殺掉毀滅者戈洛爾、瑟溫妮，以及大法師奧利斯塔。從他們到屍體上拿到戈洛爾的護符、瑟溫妮的護符和奧利斯塔的護符。$B$B記住使用你的魔化艾薩拉水晶武器來削弱他們，否則他們是無法被殺死的——你必須小心謹慎地使用你的武器……"}]])
R(3628,"惡魔拉瑟萊克",[[description="Razelikh's lair is atop the highest mountain in the Blasted Lands. The only way to the lair is through the use of the teleport runes near the mountain. As long as you hold the amulet, you can freely transport up to the lair. Once you reach the lair, you must conjure the beast. The amulet is your key, $N. Use it on the Altar of the Defiler.$B$BShould you defeat the Defiler, bring back his horn. It will become a symbol of hope for all that view it - proof that heroes do exist in this war torn world.",objectives={"Destroy Razelikh the Defiler and return the Severed Horn of the Defiler to the Fallen Hero of the Horde. You will also need to return the Ward of the Defiler so that the Fallen Hero can destroy it, preventing it from ever falling into the wrong hands."}]])
R(3629,"地精工程學",[[description="Expert engineering yields two distinct disciplines: gnome and goblin.  I only bother to mention goblin engineering because I'm a fair trainer.  They like to make things that blow up, and they rarely care what is in the way - even themselves.$B$B$N, read this manual.  If you want to learn how to blow yourself up, then take it to Nixx Sprocketspring in Gadgetzan.   Remember - membership is permanent and prevents joining the other discipline, so make sure this is what you want before finishing his task.",objectives={"If you wish to learn more about Goblin Engineering, take the Manual of Engineering Disciplines to Nixx Sprocketspring in Gadgetzan."}]])
R(3630,"侏儒工程學",[[description="Engineering at the expert level breaks into two disciplines: gnome and goblin.  Gnome engineering represents by far the superior of the two!  It's about the construction of wonderful gadgets and devices that make life better!$B$B$N, read this manual.  If you want to learn more on gnome engineering, then take that manual to Tinkmaster Overspark in Ironforge.   Remember - membership is permanent and prevents joining the other discipline, so make sure you are sure before finishing his task!",objectives={"If you wish to learn more about Gnome Engineering, take the Manual of Engineering Disciplines to Tinkmaster Overspark in Ironforge."}]])
R(3631,"召喚地獄戰馬",[[description="Hmph. I say you're not prepared, but that is not my decision. Strahad feels otherwise, and it is his decision to make... this time.$B$BHe wishes to speak to you, and quickly. You'll find him still above Ratchet in the Barrens, at his little tower there with his acolytes.$B$BDo not dawdle long.",objectives={"Speak to Strahad Farsan in the Barrens."}]])
R(3632,"侏儒工程學",[[description="Engineering at the expert level breaks into two disciplines: gnome and goblin.  Gnome engineering represents by far the superior of the two!  It's about the construction of wonderful gadgets and devices that make life better!$B$B$N, read this manual.  If you want to learn more on gnome engineering, then take that manual to Tinkmaster Overspark here in Ironforge.   Remember - membership is permanent and prevents joining the other discipline, so make sure you are sure before finishing his task!",objectives={"If you wish to learn more about Gnome Engineering, take the Manual of Engineering Disciplines to Tinkmaster Overspark in Ironforge."}]])
R(3633,"地精工程學",[[description="Expert engineering yields two distinct disciplines: gnome and goblin.  Clearly, goblin engineering is the choice of all brilliant engineers.  Learn to master the world through the judicious use of high explosives and fantastic gear!$B$B$N, read this manual.  If you want to learn about goblin engineering, then take it to Nixx Sprocketspring in Gadgetzan.   Remember - membership is permanent and prevents joining the other discipline, so make sure this is what you want before finishing his task.",objectives={"If you wish to learn more about Goblin Engineering, take the Manual of Engineering Disciplines to Nixx Sprocketspring in Gadgetzan."}]])
R(3634,"侏儒工程學",[[description="Engineering at the expert level breaks into two disciplines: gnome and goblin.  While I think it is a waste, you should be aware of gnome specialization.  They make items and gadgets that claim to change the world, but rarely often work.$B$B$N, read this manual.  If you wish to learn how to make metal paper weights, then take that manual to Tinkmaster Overspark in Ironforge.   Remember - membership is permanent and prevents joining the other discipline, so make sure you are sure before finishing his task!",objectives={"If you wish to learn more about Gnome Engineering, take the Manual of Engineering Disciplines to Tinkmaster Overspark in Ironforge."}]])
R(3635,"侏儒工程學",[[description="Engineering at the expert level breaks into two disciplines: gnome and goblin.  While I think it is a waste, you should be aware of gnome specialization.  They make items and gadgets that claim to change the world, but rarely work.$B$B$N, read this manual.  If you wish to learn how to make metal paper weights, then take the manual to Oglethorpe Obnoticus in Booty Bay.   Remember - membership is permanent and prevents joining the other discipline, so make sure you are sure before finishing his task.",objectives={"If you wish to learn more about Gnome Engineering, take the Manual of Engineering Disciplines to Oglethorpe Obnoticus in Booty Bay."}]])
R(3636,"與聖光同在",[[description="天譴軍團對聯盟是一個長期的威脅，我想你應該明白這一點。最近，我們偶然發現了一些罕見的東西，$N。$B$B在貧瘠之地有一片令人恐怖的灌木林稱作剃刀高地。雖然那兒曾經是野豬人的家，但是很明顯，它已經變成天譴軍團的地盤，並衍生出了更加可怕的生物……這些生物都被巫妖寒冰之王亞門納爾統治著。$B$B願聖光與你同在，$N；終結那裡的邪惡吧。",objectives={"大主教本尼迪塔斯要你去殺死剃刀高地的寒冰之王亞門納爾。"}]])
R(3637,"侏儒工程學",[[description="Engineering at the expert level breaks into two disciplines: gnome and goblin.  While I think it is a waste, you should be aware of gnome specialization.  They make items and gadgets that claim to change the world, but rarely work.$B$B$N, read this manual.  If you wish to learn how to make metal paper weights, then take the manual to Oglethorpe Obnoticus in Booty Bay.   Remember - membership is permanent and prevents joining the other discipline, so make sure you are sure before finishing his task.",objectives={"If you wish to learn more about Gnome Engineering, take the Manual of Engineering Disciplines to Oglethorpe Obnoticus in Booty Bay."}]])
R(3638,"保密協議",[[description="Goblin engineering is about practical uses for high profit and higher explosive power!  Our schemata allow us to make powerful bombs and mighty weaponry; the manual you read covered this.$B$BThe manual also covered our ages old oath of secrecy on our schemata.  Once you become a goblin engineer, that's that.  There is no access to gnome engineering at all.$B$BIf you still want to become a goblin engineer, sign this document pledging life-long secrecy and speak with me again.  Think about it carefully, $N.",objectives={"If you agree to become a Goblin Engineer, then right-click on the Pledge of Secrecy and speak once more with Nixx Sprocketspring in Gadgetzan."}]])
R(3639,"工作成果",[[description="As your mentor, I want samples of your work.  You're a skilled engineer; there is no question of this, $N.  What I hope to do though is analyze them for ways to emphasize goblin-oriented techniques in your future efforts.  I need the following: twenty big iron bombs, twenty sticks of solid dynamite, and five explosive sheep - and keep the safeties armed!$B$BSubmit these items to me and I will issue you your own Goblin Engineer Membership Card; it is required for access to all goblin engineering trainers!",objectives={"Bring 20 Big Iron Bombs, 20 Solid Dynamite, and 5 Explosive Sheep to Nixx Sprocketspring in Gadgetzan."}]])
R(3640,"保密協議",[[description="Gnome engineering is about engineering theory shaped to serve our needs!  Our schemata allow us to make devices that control the world around us; the manual you read covered this.$B$BThe manual also covered our ages old oath of secrecy on our schemata.  Once you become a gnome engineer, that's that.  There is no access to goblin engineering at all.$B$BIf you still want to become a gnome engineer, sign this document pledging life-long secrecy and speak with me again.  Think about it carefully, $N.",objectives={"If you agree to become a Gnome Engineer, then right-click on the Pledge of Secrecy and speak once more with Tinkmaster Overspark in Ironforge."}]])
R(3641,"工作成果",[[description="As your mentor, I want some samples of your work.  You're a skilled engineer; there is no question of this, $N.  What I hope to do though is to analyze your work for ways to emphasize gnome-oriented techniques in your future efforts.  I need the following samples: six mithril tubes, an accurate scope, and two advanced target dummies.$B$BSubmit these items to me and I will issue you your own Gnome Engineer Membership Card; it is required for access to all gnome engineering trainers!",objectives={"Bring 6 Mithril Tubes, an Accurate Scope, and 2 Advanced Target Dummies to Tinkmaster Overspark in Ironforge."}]])
R(3642,"保密協議",[[description="Gnome engineering is about engineering theory shaped to serve our needs!  Our schemata allow us to make devices that control the world around us; the manual you read covered this.$B$BThe manual also covered our ages old oath of secrecy on our schemata.  Once you become a gnome engineer, that's that.  There is no access to goblin engineering at all.$B$BIf you still want to become a gnome engineer, sign this document pledging life-long secrecy and speak with me again.  Think about it carefully, $N.",objectives={"If you agree to become a Gnome Engineer, then right-click on the Pledge of Secrecy and speak once more with Oglethrope Obnoticus in Booty bay."}]])
R(3643,"工作成果",[[description="As your mentor, I want some samples of your work.  You're a skilled engineer; there is no question of this, $N.  What I hope to do though is to analyze your work for ways to emphasize gnome-oriented techniques in your future efforts.  I need the following samples: six mithril tubes, an accurate scope, and two advanced target dummies.$B$BSubmit these items to me and I will issue you your own Gnome Engineer Membership Card; it is required for access to all gnome engineering trainers!",objectives={"Bring 6 Mithril Tubes, an Accurate Scope, and a 2 Advanced Target Dummies to Oglethorpe Obnoticus in Booty Bay."}]])
R(3644,"會員卡續費")
R(3645,"會員卡續費")
R(3646,"會員卡續費",[[description="我猜你想要得到該有的報酬，對吧?提醒我我的生命?。哼。把東西拿走，然後離開。"]])
R(3647,"會員卡續費")
R(3661,"月神之獸？",[[description="梟獸是難以預測的生物，$N。它們有著極端溫順的一面，如果它們重視的東西受到威脅，這些生物就會變得非常兇猛。$B$B傳說這些野獸是由伊露恩創造的，我對這種說法的真偽很感興趣。$B$B近來，我聽說辛特蘭的梟獸數量越來越多——這些兇殘、原始、野蠻的傢伙在辛特蘭的野外四處橫行。你能幫我收集一些梟獸的羽毛嗎？",objectives={"為魯瑟蘭村的艾瑞拉斯·琥珀收集15支梟獸羽毛。"}]])
R(3681,"聖潔之書",[[description="Sorry to interrupt your travels, $r, but I thought you should know that word was sent from Stormwind recently asking that paladins report there for training.$B$BIf I didn't know any better, I'd say your close to reaching a special time and it's time you started studying the Tomes.$B$BLook for Duthorian Rall in Stormwind. He usually trains paladins in the Cathedral of Light.",objectives={"Speak with Duthorian Rall in Stormwind."}]])
R(3701,"索瑞森廢墟",[[description="Venture to the smoldering ruins of Thaurissan in the Burning Steppes and gather as much information as possible.$B$BIt is said that mysterious relics litter the ruins. Perhaps you should start your search there, $N. Beware the Thaurissan guardians: Assassins that guard the ruins, keeping whatever secrets may still be buried there protected.",objectives={"Venture to the Ruins of Thaurissan in the Burning Steppes and recover information from the Thaurissan Relics. Return to Royal Historian Archesonus when you have recovered the information."}]])
R(3702,"索瑞森廢墟",[[description="Would you like to hear a brief history of the Dark Iron dwarves?",objectives={"Listen to Royal Historian Archesonus recant the history of Thaurissan."}]])
R(3721,"妳自己的OOX")
R(3741,"希拉裏的項鏈",[[description="我朋友希拉蕊的項鏈丟了，我們怎麼都找不到。我們一整天都在這兒釣魚，已經把周圍都找遍了。我認為它只可能是落到湖裡去了。我們的父母不讓我們在湖裡游泳……我媽媽說水下有一些可怕的生物，但是你好像不怕那些東西。$B$B你去幫她找到項鏈，好嗎？",objectives={"找到希拉蕊的項鏈，將其還給湖畔鎮的希拉蕊。"}]])
R(3761,"安戈洛的泥土",[[description="據說安戈洛環形山一帶的土壤非常肥沃，而且具有不可思議的魔法能量。塞納里奧議會需要大量的這種土壤以進行研究，到安戈洛去幫我們收集足夠的土壤吧。$B$B有時肥沃的土壤會成堆地聚集在地表，某些野獸也可能帶有這樣的土壤。把它們都交給格德，它就在這附近的那一堆堆泥土旁。他脾氣不錯，但是別惹惱他！",objectives={"收集20份安戈洛的泥土，把它們交給雷霆崖的格德。"}]])
R(3762,"協助大德魯伊",[[description="打擾一下，$c，如果可能的話，我想佔用你一點時間。$B$B雷霆崖的塞納里奧議會希望能找到像你這樣經驗豐富的冒險家來幫助他們進行一項重要的研究項目。雖然我不知道詳細的情況，但是我可以告訴你，正是哈繆爾·符文圖騰親自負責這項研究。$B$B要是你感興趣的話，請直接去雷霆崖的長者高地找他談談。",objectives={"與雷霆崖的大德魯伊哈繆爾·符文圖騰談話。"}]])
R(3763,"協助大德魯伊",[[description="Excuse me $c, but I'd like just a moment of your time if possible.$B$BThe Cenarion Circle in Darnassus is looking for seasoned adventurers such as yourself to lend them aid in a vital research project.  While I do not know the specifics, I can inform you that none other than Arch Druid Fandral Staghelm is spearheading this research.$B$BPlease - if you are interested, speak with him directly in the Cenarion Enclave within Darnassus proper.",objectives={"Speak with Arch Druid Fandral Staghelm in Darnassus."}]])
R(3764,"安戈洛的泥土",[[description="據說安戈洛環形山一帶的土壤非常肥沃，而且具有不可思議的魔法能量。我想要知道這事的真假，到安戈洛去幫我們收集足夠的土壤吧。$B$B你可能會認為派你去做收集任務是委屈你了，我和塞納里奧議會可不喜歡這種態度。將樣本交給耶納爾，他總躲在樹後浪費時間，你只要去找那一堆堆的泥土就是了。剩下的事情都交給他辦，別來找我。",objectives={"收集20份安戈洛的泥土，把它們交給達納蘇斯的耶納爾。"}]])
R(3765,"遙遠的旅途",[[description="暴風城——一個繁忙的中樞城市！$b$b我從遙遠的地方趕來尋求幫助。據說這座城市裡滿是勇敢的冒險者。$b$b我在達納蘇斯的兄弟戈沙拉需要幫助，他居住在海邊的小鎮奧伯丁。$b$b我們面前是一次漫長而壯麗的旅途，因此，我請求像你這樣的經驗豐富的$c給予幫助。",objectives={"到奧伯丁的戈沙拉·夜語那兒去。"}]])
R(3781,"晨光麥研究",[[description="有了這件名為常青袋的東西，我們已在來自安戈洛環形山的土壤上種植了薩倫迪斯種子。這些種子繁殖出了大片的草藥。其中一種是晨光麥，我們對這種神秘的草藥知之甚少，不過我打算揭開其中的奧秘。$B$B把這個交給樓下的瑪斯雷，他會給你一些種子，然後你就可以開始了。要是種子用完了的話，你就得從他那兒購買新的種子。",objectives={"將大德魯伊的草種購買券交給達納蘇斯城塞納里奧區的瑪斯雷·馭熊者。"}]])
R(3782,"晨光麥研究",[[description="With what we call an Evergreen Pouch, we have cultivated Tharlendris seeds in the soil from Un'Goro Crater.  These seeds have blossomed into an array of random, potent herbs.  One result is morrowgrain, a mysterious herb we know little about; I very much hope to unravel this mystery for the Circle.$B$BTake this voucher over to my daughter Bashana, and she will give you some seeds so you may assist us.  If you run out, you will need to purchase more from her.",objectives={"Take the Seed Voucher to Bashana Runetotem in Thunder Bluff."}]])
R(3783,"雪怪計劃！",[[description="My friends are always coming up with great ideas. I've never felt like I could match them... until today! I just drew up the plans for something great! If you promise not to tell, I'll let you in on the secret... $B$BI'm going to make a mechanical yeti! Not only are my friends sure to be freaked out when they see it, but when they get over that, I know they'll be impressed!$B$BI need thick yeti fur from the ice thistle yeti to start with. Will you help? You'll find them to the southeast.",objectives={"Collect 10 Thick Yeti Furs for Umi Rumplesnicker in Everlook."}]])
R(3784,"協助大德魯伊",[[description="打擾一下，$c，如果可能的話，我想佔用你一點時間。$B$B雷霆崖的塞納里奧議會希望能找到像你這樣經驗豐富的冒險家來幫助他們進行一項重要的研究項目。雖然我不知道詳細的情況，但是我可以告訴你，正是哈繆爾·符文圖騰親自負責這項研究。$B$B要是你感興趣的話，請直接去雷霆崖的長者高地找他談談。",objectives={"與雷霆崖的大德魯伊哈繆爾·符文圖騰談話。"}]])
R(3785,"晨光麥研究",[[description="這是你所需的與薩倫迪斯種子一同使用的常青袋，當然，你手中還必須有安戈洛的泥土樣本給種子做肥料。這些東西都準備好了之後就使用常青袋，剩下的就交給它了。$B$B當你種出足夠的晨光麥之後，將它們交給我就行了。請不要打擾大德魯伊，他事務繁忙，而且他也沒必要為收集晨光麥的事情操心！",objectives={"用一個常青袋、一包薩倫迪斯種子以及兩份安戈洛的泥土來嘗試種植晨光麥。$B$B將10株晨光麥交給達納蘇斯的瑪斯雷·馭熊者。"}]])
R(3786,"晨光麥研究",[[description="Here's your Evergreen Pouch that you'll need to use the Tharlendis seeds with.  You also need to have Un'Goro soil samples on hand to use as fertilizer for the seeds.  Just use the pouch when you have everything; the pouch will take care of the rest.$B$BWhen you have enough morrowgrain, bring them to me here on Elder Rise.  Please don't bother the Arch Druid; he'll be very busy with the research, as well as the multitude of concerns he has!",objectives={"Use an Evergreen Pouch with a Packet of Tharlendis Seeds and two Un'Goro Soil samples to try and cultivate samples of Morrowgrain.$B$BBring 10 Morrowgrain to Bashana Runetotem in Thunder Bluff."}]])
R(3787,"奎恩提斯的請求",[[description="Excuse me, friend...$B$BA colleague of mine would like to speak with you about the research you are doing in conjunction with the Cenarion Circle.  He is a druid by the name of Quintis Jonespyre, and he resides in Feathermoon Stronghold, Feralas.  He would like to confer with you about morrowgrain... and he very much would like for you to keep our discussion from the ears of the Arch Druid.$B$BIf you're interested, speak with him; no doubt, all will be revealed once you do.",objectives={"Speak with Quintis Jonespyre in Feathermoon Stronghold."}]])
R(3788,"奎恩提斯的請求",[[description="朋友，打擾一下……$B$B我的同伴想與你談談有關你同塞納里奧議會聯合進行的研究。他是一名德魯伊，名叫奎恩提斯，居住在菲拉斯的羽月要塞。他想就晨光麥與你交換一些意見……而且他希望我們的談話不為大德魯伊所知。$B$B如果你感興趣的話，就去跟他談談，當然，一旦你這麼做了，所有的一切便不是秘密了。",objectives={"與羽月要塞的奎恩提斯談話。"}]])
R(3789,"協助大德魯伊",[[description="打擾一下，$c，如果可能的話，我想佔用你一點時間。$B$B達納蘇斯的塞納里奧議會希望能找到像你這樣經驗豐富的冒險家來幫助他們進行一項重要的研究項目。雖然我不知道詳細的情況，但是我可以告訴你，正是伊范達爾·鹿盔親自負責這項研究。$B$B要是你感興趣的話，請直接去達納蘇斯的塞納里奧區找他談談。",objectives={"與達納蘇斯的大德魯伊范達爾·鹿盔談話。"}]])
R(3790,"協助大德魯伊",[[description="Excuse me $c, but I'd like just a moment of your time if possible.$B$BThe Cenarion Circle in Darnassus is looking for seasoned adventurers such as yourself to lend them aid in a vital research project.  While I do not know the specifics, I can inform you that none other than Arch Druid Fandral Staghelm is spearheading this research.$B$BPlease - if you are interested, speak with him directly in the Cenarion Enclave within Darnassus proper.",objectives={"Speak with Arch Druid Fandral Staghelm in Darnassus."}]])
R(3791,"晨光麥的秘密",[[description="坦白說吧，$N。我對達納蘇斯的大德魯伊以塞納里奧議會的名義、使用 議會的資源來大量生產晨光麥的原因很感興趣——不，應該說是極度關注。我是一名研究員——研究詛咒是我的專長。我聽說晨光麥在一定的條件下可以像其他草藥那樣用於進行詛咒。$B$B我想瞭解更多的情況，因此我請求你的幫助。給我帶十株晨光麥回來，我會好好報答你的。",objectives={"將10株晨光麥交給羽月要塞的奎恩提斯。"}]])
R(3792,"羽月要塞的晨光麥")
R(3801,"黑鐵的遺產",[[description="你好，$N。我是弗蘭克羅恩·鑄鐵。沒錯，正是我創造了以石頭為基礎的建築方法。在探索這個飽受戰爭創傷的世界的旅途中，你一定見過了不少由我設計建造的建築物。$B$B你也許想要知道我為什麼在這裡，以及我想要你幫我做些什麼——這些問題都很合理。$B$B我當然需要你的幫助。作為請求你幫助我的交換條件，我會給你一把鑰匙，讓你得以進入這座由我建造的……被詛咒的城市。",objectives={"如果你想要得到進入這座城市主城區的鑰匙，就去和弗蘭克羅恩·鑄鐵談話。"}]])
R(3802,"黑鐵的遺產",[[description="你可以在秩序競技場外的工匠大廳裡找到弗諾斯·達克維爾。殺掉那個卑鄙的傢伙，拿回我的鐵膽之錘。$B$B把鐵膽之錘拿到索瑞森神殿去，然後把它放在正確的地方——就是我的雕像的手裡。$B$B當你把鐵膽之錘放上去之後，我存放主宰鑰匙的那個小機關將會打開。更重要的是，鐵膽之錘將會永遠掌握在我的手中。如果有人想要拿走戰錘的話，那整座雕像和戰錘都會碎裂，永遠無法修復。",objectives={"殺掉弗諾斯·達克維爾並拿回戰錘鐵膽。把鐵膽之錘拿到索瑞森神殿去，將其放在弗蘭克羅恩·鑄鐵的雕像上。"}]])
R(3803,"達納蘇斯的晨光麥")
R(3804,"雷霆崖的晨光麥")
R(3821,"巨槌石",[[description="Sha'ni was sent to investigate reports of strange ritualistic activity coming from the Firegut ogres of the Burning Steppes over three weeks ago.$B$BGoretooth tells me that he hasn't heard from anyone in that platoon and that it's best that I move on and focus on the task at hand. Can you believe it? That's my wife!$B$BI can't leave my post, $N, but I must know what became of Sha'ni. Travel to the Burning Steppes and search for her.",objectives={"Venture forth to the Burning Steppes and find out what became of Sha'ni Proudtusk."}]])
R(3822,"克羅格魯爾",[[description="My whole platoon was captured, $N. All were slain - except me.$B$BTheir leader, Krom'Grul, wanted to save me for some sort of ritual.$B$BI was chained to this altar and brutalized by the beast. My physical being ceased functioning after an hour of this torture. The beast then ripped my wedding nose-ring off of my face and stuck it on his finger. I had never seen such savagery!$B$BFind Krom'Grul and kill him! Take my ring back to Thal'trak.$B$BAnd $N, tell him that we will meet again... in another life. ",objectives={"Recover Sha'ni's Nose-Ring from Krom'Grul and return it to Thal'trak in Kargath. Search the various caves and mines in Dreadmaul Rock."}]])
R(3823,"消滅火腹食人魔",[[description="We must strike at our enemies before they strike at us!$B$BI'll make this brief, soldier.$B$BThe Firegut ogres of the Burning Steppes are allies of the Blackrock orcs. They work closely with those vile orcs, keeping the mineral rich Dreadmaul Rock guarded and the supply lines open at all times.$B$BLeave your mark, $N. Cripple their forces and return to me when the job is done.$B$B<Oralius grabs at the air and makes a choking motion.>$B$BI WILL KILL YOU, WINKY!",objectives={"Slay 15 Firegut Ogre-Mages, 7 Firegut Ogres, and 7 Firegut Ogre Brutes, and return to Oralius when you are finished."}]])
R(3824,"蠻王戈泰什",[[description="They're reeling I tell you! Our next strike must be decisive.$B$BThe brute lord, Gor'tesh, must be slain. More importantly, his head must be returned to me so that I may prepare the third phase of our attack on the Firegut ogres.$B$BBe warned, soldier, Gor'tesh rules not from Dreadmaul Rock but from a Blackrock orc structure to the west of Dreadmaul Rock.$B$BYour orders, then, are simple. Find Gor'tesh and chop off his fat head. Return to me when the job is done.$B$BSHUT UP, WINKY!",objectives={"Find Gor'tesh, somewhere to the west of Dreadmaul Rock. Kill Gor'tesh and then take Gor'tesh's Lopped Off Head back to Oralius in Burning Steppes."}]])
R(3825,"梟首示眾",[[description="Just one last thing you must do, soldier.$B$BI've taken the liberty of putting Gor'tesh's head on a pike. Now all you have to do is take this head to the top of Dreadmaul Rock and stick it into the ground. Once you do that, watch as those cowardly ogres run for their lives! After you've had your fun, come back to me and I'll reward you for all of your hard work.$B$B<Oralius seems to be losing touch with reality.>",objectives={"Take Gor'tesh's Lopped Off Head and place it at the top of Dreadmaul Rock. Look for a soft dirt mound to plant the pike."}]])
R(3841,"領養孤兒",[[description="Oh, hello, $N. I'm so glad to see you again. How was your trip to Darnassus?$B$BWell, you'll be happy to know that we've made quite a bit of progress while you've been gone. We even saved a nest full of eggs. Unfortunately, the mother died before we got to her.$B$BSay, would you want one for a pet? They look to hatch soon, so they'll need a good $Gfather:mother;. What do you say?$B$BIf you're really interested, take one of the eggs to Quentin at the race tracks in Shimmering Flats. He'll tell you more.",objectives={"Speak to Quentin in Thousand Needles."}]])
R(3842,"即將孵化",[[description="The Moonweavers, huh? Most intriguing. I wish the sprite darters could truly appreciate what it means to have those two look after them. They are both quite capable.$B$BSo, they gave you the egg as a gift. Well, then you should be responsible for it for as long as you desire. It appears it's almost ready to hatch, but we should ensure it's healthy and no damage has been done to it.$B$BI only need two elixirs of fortitude for a small spell to protect the egg. I have the rest of the components here with me.",objectives={"Bring 2 Elixir of Fortitudes to Quentin in Thousand Needles."}]])
R(3843,"新的生命",[[description="A magnificent specimen, $N. If this creature survives gestation, then it'll be a healthy pet indeed!$B$BThere is one last thing I would suggest doing if you plan on following through with this--head to Aerie Peak in the Hinterlands. Speak to a dwarf there named Agnar Beastamer, he's a master animal handler and should be able to guide you in the final steps of incubation.$B$BBut hurry, $N, this egg is fragile and will not last long without proper care.",objectives={"Take your Fragile Sprite Darter Egg to the Hinterlands and speak to Agnar Beastamer, but hurry, you only have 1 hour to find him before the hatchling within the egg dies."}]])
R(3844,"無人知曉的秘密",[[description="一艘被毀壞的小艇擱淺在岸邊。這裡是個小池塘，為什麼會有一艘小艇擱淺在這裡就不得而知了，不過從樹上的痕跡來看，這裡的水位並不是一直不變的。$B$B也許在附近繼續搜查一下的話有可能發現更多的線索……",objectives={"在池塘附近查找與擱淺的小艇有關的線索。"}]])
R(3845,"無人知曉的秘密",[[description=" Grabbing onto it, you pull the pack back to the shore. Perhaps if you examine the items inside the pack, you might find out more about who it belongs to.$B$BThere are a few stray travelers at Marshal's Refuge. Perhaps you might find out more there.",objectives={"Examine the items inside the pack and bring them to their owner."}]])
R(3861,"咕咕嘎！",[[description="\"Cluck... cluck... cluck... BACAW!$B$BCluck... cluck... cluck.\"$B$BThe chicken looks up at you and then starts to scratch its claws into the ground. You think it is spelling out a word, but you are not sure what it is. Could it be... S-A-L-D-E-A-N? Before you can ask, the chicken turns away and goes about its business.",objectives={"Find some Special Chicken Feed and return to your befriended chicken. When you find it, /cheer at it before trying to give it the Special Chicken Feed."}]])
R(3881,"搶救物資",[[description="我不知道你是怎麼到這兒來的，但是你可真是個受歡迎的$r！我是威利德·馬紹爾，這支中立探險隊的頭兒。我們的小隊近來遭受了一連串災難，其中最為嚴重的就是我們低估了安戈洛環形山的蠻荒程度！$B$B我們在逃離位於環形山西南部和東北部的營地時落下了重要的物資。你似乎是個足夠強壯的$r——能幫助我們去取回這些物資嗎？",objectives={"將食物箱和研究設備交給安戈洛環形山的威利德·馬紹爾。"}]])
R(3882,"挖骨頭",[[description="You'd think that being chief digger for Marshal Expeditions means I like digging.  There might be worse things to do in this world... but none really leap to mind.$B$BWe were supposed to be digging in Terror Run - FANTASTIC name by the way - for dead stegodons and diemetradons.  Well, there are plenty of live ones there too!  Wil and Hol are still all about studying this death trap, so we need those dinosaur bones.  Between you and me though, bringing some from live ones will work out just as well.",objectives={"Bring 8 Dinosaur Bones to Spark Nilminer in Un'Goro Crater."}]])
R(3883,"異型的生態",[[description="Just because we've suffered a setback doesn't mean that research must stop!  We were investigating the Gorishi insects in the southern part of the crater before winding up here.  Their presence is alien to the ecology of Un'Goro, and we want to find out why.$B$BIn their hive network must be larval hatcheries.  You can identify these places by their hanging larval spawns.  Use this vial to take a sample of the hive wall near any of the hatcheries.  Bring it back to me for study, but be careful!",objectives={"Use the Scraping Vial to collect a Hive Wall Sample from one of the Gorishi hive hatcheries in Un'Goro Crater.  Look for the chambers with the hanging larval spawns.$B$BBring the Hive Wall Sample to Hol'anyee Marshal in Un'Goro Crater."}]])
R(3884,"威利德的日記",[[description="你找到了一本被撕破的日記，其中的某些部分仍然清晰可辨，目錄中有威利德·馬紹爾的署名。如果日記上面的記載沒錯的話，那麼你可以在環形山的北部地方找到威利德。根據日記中所說的，他和他的同伴們的營地被襲擊了，所以他們不得不尋找更高處的空地紮營，以避開橫行在環形山裡的兇殘野獸。",objectives={"將日記還給安戈洛環形山中的威利德·馬紹爾。"}]])
R(3885,"<NYI> <TXT> The Gadgetzan Run",[[description="Escort Me and Dadanga!",objectives={"Escort Petra and Dadanga!"}]])
R(3901,"斷骨骷髏",[[description="你已經向我們展示了你在正常情況下的潛力，$N——現在讓我們來看看你在壓力下的表現吧。$B$B斷骨骷髏是巫妖王手下的走狗，與你先前幹掉的那些殭屍相比，它們更為強韌而兇殘。去殺掉它們，再次向被遺忘者證明你的能力吧。別耽擱時間——當你完成任務後，就來找我談談。",objectives={"殺掉12個斷骨骷髏，然後回到喪鐘鎮的暗影牧師薩維斯那裡。"}]])
R(3902,"撿破爛",[[description="嘿，說你呢！要是你想實現自己的價值，那就聽好了！$B$B我們要求那些剛剛爬出墳墓的新兵前往喪鐘鎮，搜尋任何可以為我們所用的裝備，這些裝備極有可能裝在成堆的箱子裡。我們希望能立即招募到更多的新兵，因此，除非我們想讓他們赤手空拳地上陣，否則我們就得搜尋一切可用之物！$B$B開始工作吧，你這堆可悲的骨頭！對那些不努力工作的傢伙，我可是不會給予回報的。",objectives={"在喪鐘鎮及臨近地區搜尋6件破爛裝備，把它們交給亡靈衛兵薩爾坦。"}]])
R(3903,"米莉·奧斯沃斯",[[description="You've shown yourself a dependable $c, $N.  Dependable, and not afraid to get your hands dirty, eh?$B$BI have a friend, Milly Osworth, who's in some trouble.  She's over with her wagon on the other side of the abbey, near the stable.  I'm sure she could use a pair of hands like yours.",objectives={"Speak with Milly Osworth."}]])
R(3904,"米莉的葡萄",[[description="A gang of brigands, the Defias, moved into the Northshire Vineyards while I was harvesting!  I reported it to the Northshire guards and they assured me they'd take care of things, but... I'm afraid for my crop of grapes!  If the Defias don't steal them then I fear our guards will trample them when they chase away the thugs.$B$BPlease, you must help me!  I gathered most of my grapes into buckets, but I left them in the vineyards to the southeast.$B$BBring me those crates!  Save my harvest!",objectives={"Bring 8 crates of Milly's Harvest to Milly Osworth at Northshire Abbey."}]])
R(3905,"葡萄出貨單",[[description="Now that my crop is saved, take this Grape Manifest to Brother Neals.  He manages the store of food and drink in Northshire, and I'm sure he'll be delighted to hear that he has fresh grapes.$B$BYou'll find Brother Neals in the abbey, in the bell tower... where he likes to taste his wine.",objectives={"Bring the Grape Manifest to Brother Neals in Northshire Abbey."}]])
R(3906,"不和諧的烈焰",[[description="The elders have felt a disturbance amongst the elements. The Dark Iron dwarves have summoned a foul spirit into our world that threatens to plague our lands with an eternal draught. This disharmony of flame must be investigated.$B$BTravel to Blackrock Mountain, through the Chasm of Flame, into the quarry. It is there that you shall find this lord of fire: Overmaster Pyron.$B$BEnd the disruption and return to me.",objectives={"Travel to the quarry in Blackrock Mountain and slay Overmaster Pyron. Return to Thunderheart when you have completed this assignment."}]])
R(3907,"不和諧的火焰",[[description="I can taste the foulness in the air that surrounds you, $N. There is another, hidden in the depths of Blackrock, who does control this foulness.$B$BThe wind and earth cry his name: Lord Incendius... but someone... something... commands this being. He is merely an emissary.$B$BFind him and discover where his master hides. Return to me when you have collected this information.",objectives={"Enter Blackrock Depths and track down Lord Incendius. Slay him and return any source of information you may find to Thunderheart."}]])
R(3908,"無人知曉的秘密",[[description="You see, I have no idea how I ended up here. No one really knows -- it's a secret to everybody! I just can't seem to remember anything...$B$BThese items you brought to me, though... I am remembering something.$B$BMy sword. I am supposed to strengthen it somehow, but I'm really not sure why. Sorry I can't tell you more, but I just don't remember!$B$BAnyhoo, I do know where you can take it -- Donova Snowden in Winterspring. You'll find her by the hot springs. She can temper the sword by the pools there.",objectives={"Take Linken's Sword to Donova Snowden in Winterspring."}]])
R(3909,"視靈藥劑",[[description="什麼，你說什麼？林克……失憶了？$B$B哦，我明白了……他失去了自己的記憶……$B$B好吧，這是他的劍。但是它並不完整。我知道有人可以把它變得完整，但是……和他說話也許會很困難。$B$B聽著，我知道有人可以幫助你，現在我沒法把一切都給你解釋清楚，總之你一定要得到視靈藥劑。我所知道的唯一一個可以幫你的人就是格雷甘·山酒了。他行蹤不定，但是我知道他現在正在菲拉斯一帶活動。",objectives={"去菲拉斯找格雷甘·山酒。從他那裡問到獲取視靈藥劑的方法，然後向冬泉谷的多諾瓦·雪山覆命。"}]])
R(3911,"The Last Element",[[description="There is work to be had for those venturing into the depths, $N.$B$BThe Dark Irons have mastered creation of extremely powerful golems.$B$BInitial reports from our spies indicate that the dwarves use a unique power source to give their creations incomparable killing power.$B$BJust imagine what we could do with our abominations if we could get our hands on this essence of the elements! Turn that city upside down if you must, but do not return until you have found the essence! Payment will be worth the risk.",objectives={"Travel to Blackrock Depths and recover 10 Essence of the Elements. Your first inclination is to search the golems and golem makers. You remember Vivian Lagrave also muttering something about elementals."}]])
R(3912,"墓地相見",[[description="這瓶藥劑可以讓你和那些普通狀態下無法看見的生物對話……$B$B把這瓶視靈藥劑和林克的劍帶到塔納利斯去，在加基森鎮外的墓地中喝下這瓶藥劑。你也許會對它所產生的效果感到奇怪，但是不要為此擔心。$B$B在你處於「另外」一種形態的時候，一直往北走到山的旁邊，你要找的人就在那裡的石壁縫裡，他的名字叫加里楊。$B$B記住，只有你在那種形態下的時候，他才會和你對話。",objectives={"在加基森鎮外的墓地中使用視靈藥劑，然後按照多諾瓦的指示找到加里楊。"}]])
R(3913,"尋找墓碑",[[description="如果你回到墓地，$N，你會在那裡找到一塊墓碑……那不是一塊普通的墓碑，它非常顯眼。秘密就隱藏在其中。$B$B推動墓碑，然後你就可以發現那些秘密……",objectives={"復活，然後尋找加里楊讓你去找的那塊墓碑。"}]])
R(3914,"林克的劍",[[description="一陣強光閃過之後，你再次撿起了那把劍。它已經完全變成另一種樣子了！",objectives={"把林克的強化之劍交給安戈洛環形山的林克。"}]])
R(3921,"維妮·布特巴克",[[description="我想我可能已經把主動式負載平衡器給弄壞了。這可不太妙，因為我已經對安德麥的一些同伴談及它了，而且他們對此非常感興趣。我們必須想辦法修好它！$B$B把這個壞掉的主動式負載平衡器交給維妮·布特巴克，她就在貧瘠之地和梣谷之間的部落前哨站裡。她非常聰明而且好奇，如果你將主動式負載平衡器給她看的話，我敢打賭她會欣然幫你修理它。",objectives={"將損壞的主動式負載平衡器交給維妮·布特巴克。"}]])
R(3922,"高強度齒輪",[[description="I want to fix this samophlange, but to do that I'm going to need some supplies.  I ran out of seventeen-point-five gauge nugget slugs and I'm going to need a bunch of those for the work ahead.$B$BThe closest place to get them is the Sludge Fen to the east.  The Venture Company usually keeps them in their tool buckets.  Go to the Sludge Fen and look in the tool buckets you find there, then return to me when you've gathered enough nugget slugs.",objectives={"Bring 15 Nugget Slugs to Wenikee Boltbucket in the Barrens."}]])
R(3923,"雷裏·格裏斯高布",[[description="Well, that didn't work.  I put some extra gauges on the samophlange to measure its structural integrity, and they read the integrity at an all-time low.  I could add some more dials and maybe a lever or two to try and fix it, but... I think that might make things even worse.$B$BYou should take the samophlange to Rilli Greasygob.  He used to work for the Venture Company -- if anyone knows how to fix it, it's Rilli.$B$BYou can find him at Nogg's Machine Shop in Orgrimmar, in the Valley of Honor.",objectives={"Bring the Broken and Battered Samophlange to Rilli Greasygob in Orgrimmar."}]])
R(3924,"主動式負載平衡器說明書",[[description="I think I can fix the samophlange, but I'm going to need the user's manual first.  When I was in the Venture Company I had a rival, Boss Copperplug, who hoarded the secrets of the samophlange, giving out small bits of knowledge on the device to those he trusted.  I wasn't one of the trusted few...$B$BBoss Copperplug used to stay at the Boulder Lode Mine in northeastern Barrens.  Get the manual from him, and if he's given pages from it to anyone, you'll have to collect them too.",objectives={"Bring the Samophlange Manual to Rilli Greasygob in Orgrimmar."}]])
R(3941,"侏儒的援助",[[description="讓我想想……讓我想想……我來這裡肯定是為了某個很重要的事情……$B$B我有個辦法，$N。那邊的那個洞穴裡有個叫科琳的地精，我記得我剛到這裡的時候她給我留下了很好的印象。也許在我思維混亂的時候曾向她提過一些關於我的東西。$B$B為什麼你不去問問她呢？哦，不過你要小心——她對這個地區的那些水晶表現得特別瘋狂，我不知道她究竟想幹什麼！",objectives={"到馬紹爾營地那裡的山洞中去找科琳。"}]])
R(3942,"林克的記憶",[[description="哦……林克？當然，他是個有趣的傢伙，他剛到這裡的時候總是對所有奇怪的事情喃喃自語。也許他的腦袋被什麼東西敲過了。$B$B他說的一些話給我留下了較深的影響——他好像要做什麼圖騰，還說要去找一個叫什麼艾瑞丹·藍風的夜精靈……如果我沒記錯的話，她好像在費伍德森林。$B$B我不知道她是否能告訴你更多的東西，如果你想要知道什麼的話，為什麼你不去問問艾瑞丹自己呢？",objectives={"到費伍德森林去找艾瑞丹·藍風。"}]])
R(3961,"林克的冒險",[[description="真難想像林克來這裡居然是為了幫助我們除掉火焰使者……他看起來是那麼普通的一個地精，但是我確實感覺到他和別的地精有些不同，他居然對我的實驗或者小裝置一點都不感興趣！他一定擁有一顆真正的戰士之心。$B$B把圖騰交給他，看看這是否能夠幫助喚起他的記憶。",objectives={"把亞奎門塔斯的銀圖騰交給馬紹爾營地裡的林克。"}]])
R(3962,"結伴而行",[[description="$N，我終於想起來了……我來這裡是要和火焰使者作戰的。我經歷了一段漫長的旅途，原本最重要的目標就是它。$B$B但是我不再是英雄了……你才是。迄今為止你已經做了那麼多——應該由你來完成這個任務，而不是我。$B$B去找到火焰使者並打敗它吧。它守護著一個被稱作金色火焰的神器，這個神器的力量比我所見過的任何東西都要強大，如果它落在邪惡勢力的手中，那會是一件非常危險的事情。$B$B你應該找些同伴一起去完成這個任務——獨自行動是很危險的。",objectives={"到馬紹爾營地南邊的火羽山去。$B$B找到火焰使者，並使用圖騰除掉它的防護光環。在擊敗它之後從洞中取得金色火焰。"}]])
R(3981,"指揮官哥沙克",[[description="Poor Gargal... didn't even see it coming. WHAM! The arrow landed dead center on the top of his head. He was no genius before but now...$B$B<Galamav grimaces.>$B$BWhen we dislodged the arrow, we noticed a rolled up note attached to the shaft. On the note was a crudely drawn picture of an orc behind bars with the signature of Commander Gor'shak attached.$B$BIf he's still alive in the Depths, you'll have to find him.$B$BA trap you say? Well no kidding, numb hooves! That's why you're going!",objectives={"Find Commander Gor'shak in Blackrock Depths.$B$BYou recall that the crudely drawn picture of the orc included bars drawn over the portrait. Perhaps you should search for a prison of some sort."}]])
R(3982,"出了什麽事？",[[description="I was sent here under the auspices of Thrall. Do you actually think these buffoons could capture me? I allowed myself to be captured so that I could gather intelligence.$B$B<Gor'shak whispers.>$B$BThe Princess of Ironforge has been kidnapped by Emperor Thaurissan. Princess Bronzebeard is in this very city! I bet old Magni's heart almost stopped when he heard that news.$B$B<Gor'shak laughs.>$B$BShhh! Do you hear that? Guards coming! DEFEND YOURSELF!",objectives={"Defend Gor'shak."}]])
R(4001,"出了什麽事？",[[description="So far, my communication with the dwarf, Kharan, in the cell across the hall, has been limited. I have, however, managed to convince him that I, rather -we- mean him no harm.$B$BGo speak with him and gather as much information about the Princess and her captors as possible. Take that information back to the Warchief.$B$BThrall does not want the Princess harmed, but instead, has some grand plan laid out, which includes her being safely returned to Ironforge. Kharan already knows all of this... Go!",objectives={"Speak with Kharan Mighthammer and gather information about Princess Moira Bronzebeard's kidnapping. Take that information to Thrall in Orgrimmar.$B$BYou recall Gor'shak mentioning that Kharan is being held in a cell nearby."}]])
R(4002,"東部王國",[[description="You bring excellent information, $N.$B$BAs Warchief, it is my duty to do what is best for the Horde. To ensure that the generations that come after us are not forced into a hopeless existence.$B$BThe opportunity to shape our future alliances has fallen into our collective laps. A move to help the dwarves could greatly strengthen our relationships in the Eastern Kingdoms. This, then, is why you must not fail!$B$BAre you prepared?",objectives={"Speak with Thrall if you are prepared to take on the mission he has planned."}]])
R(4003,"拯救公主",[[description="This strike against the Dark Iron dwarves, if successful, will send a shockwave throughout their entire kingdom.$B$BPrincess Bronzebeard is under the control of Emperor Thaurissan. To free her, you must kill the Emperor. Be warned, your task is doubly dangerous, as Bronzebeard will attack you without question while under the control of the Emperor.$B$BDO NOT HARM HER!",objectives={"Slay Emperor Dagran Thaurissan and free Princess Moira Bronzebeard from his evil spell. "}]])
R(4004,"拯救公主？",[[description="You have slain my husband, $r! My child will be born into this world without a father.$B$B<Princess Moira points directly at you.>$B$BI assure you, this child will be the next ruler of the kingdom of Ironforge. You and your kind shall be hunted down until the end of days for this wrongful act.$B$B<You think that Princess Moira may be suffering from the residual effect of Thaurissan's spell.>$B$BLeave me be, $r. I am certain your warchief will be eager to hear the results of his meddling.",objectives={"Return to Thrall!"}]])
R(4005,"亞奎門塔斯",[[description="把所有你收集的東西和這本書都帶到塔納利斯去。到落帆海灣尋找一個石頭法陣，最東邊的半島應該就是秘密所在……$B$B當你身處石陣中的時候，誦讀阿奎爾之書，召喚出這個唯一可以將你所收集的東西轉化為足以對抗火焰使者的圖騰生物。$B$B亞奎門塔斯被人喚醒後可能會不太高興，但是你要記住，在它轉換圖騰的這段時間裡，你一定要待在石陣裡面。",objectives={"把阿奎爾之書、銀爪，還有鐵樹心帶到塔納利斯。$B$B用這本書召喚亞奎門塔斯。$B$B當你完成圖騰之後，把它帶給在馬紹爾營地的科琳。"}]])
R(4021,"人馬無雙！",[[description="The Horde commends your successes against the Kolkar, but the Kolkar themselves are maddened.  I have reports that a contingent of Kolkar has traveled to the Barrens from their home in Desolace, to seek vengeance.  My latest report was that, even now, they move against these bunkers, from the west!$B$BFace the Kolkar invaders, and end their threat in the Barrens.  Kill them until their leader, Warlord Krom'zar, appears.  Defeat him and bring me a piece of his banner as proof.$B$BWe're counting on you, $N.",objectives={"Bring a Piece of Krom'zar's Banner to Regthar Deathgate, west of the Crossroads."}]])
R(4022,"烈焰精華",[[description="那些飛龍已經注意到你在灼熱峽谷中的所作所為了。$B$B向我展示你的能力，$c。我要的是龍皮，你這個蠢貨。",objectives={"向塞勒斯·薩雷芬圖斯展示你從卡拉然·溫布雷那裡得到的黑龍皮。"}]])
R(4023,"烈焰精華",[[description="你找到那些黑龍了？那就向我證明你的價值吧，$c。",objectives={"向塞勒斯·薩雷芬圖斯證明你的價值。$B$B你感覺到塞勒斯似乎對你不屑一顧。"}]])
R(4024,"烈焰精華",[[description="我要為火焰之山中的炙熱烈焰歌唱，我要讓黑石山的熔岩瀑布貫穿我的身體。我所渴求的就是那種精華，那種炙焰的感覺。$B$B在黑石深淵住著一個純火焰鑄成的怪物：貝爾加，他是從拉格納羅斯的火焰中誕生的。殺掉貝爾加，然後從他燃燒的身體中取出他心中的烈焰。$B$B使用黑龍皮就可以安全地萃取這種烈焰。$B$B大功告成後，你會獲得獎勵的。",objectives={"到黑石深淵去殺掉貝爾加。$B$B你只知道這個巨型怪物住在黑石深淵的最深處。記住你要使用特殊的黑龍皮從貝爾加的屍體上採集烈焰精華。$B$B將你採集到的烈焰精華交給塞勒斯·薩雷芬圖斯。"}]])
R(4041,"視靈藥劑")
R(4061,"機器的崛起",[[description="The machines made themselves known to us during our initial forays into the Searing Gorge. Upon further investigation we discovered that they were being imported from Burning Steppes, possibly Blackrock Depths. That is what we need you for, $N.$B$BYour first task is to venture to the Burning Steppes and recover elemental shards from the rock automatons and lesser rock creations of the region. Once you have collected a sufficient amount, return to me and I shall determine their source of origin.",objectives={"Venture to the Burning Steppes and recover 10 Fractured Elemental Shards for Hierophant Theodora Mulvadania.$B$BYou recall Theodora mentioning the golems and elementals of that region as being a source for these shards."}]])
R(4062,"機器的崛起",[[description="G.L.A.$B$BThose are the 'initials' imprinted on the elemental shards. Below the initials are a rank marking of some sort. The machinations you destroyed in the Burning Steppes were of 'Rank IV.' I assume that this is a lowly rank.$B$BTake this shard sample to Lotwil Veriatus in the camp to the east. He is a scholar of some renown in the field of elemental sciences. He may be able to assist us in our search.",objectives={"Take the Elemental Shard Sample to Lotwil Veriatus.$B$BYou recall Theodora saying that Lotwil was stationed in a camp to the east."}]])
R(4063,"機器的崛起",[[description="This can't be Argelmach! Argelmach was killed ten years ago. How can I be sure? I was the one who killed him.$B$BHe was a despicable dwarf, hell-bent on twisting my life's work to meet his diabolical needs. It seems that the wicked always find a way to escape justice.$B$BIf this is Argelmach's handiwork then he must be destroyed. I will need samplings of his latest creations. With the proper samples, I may be able to stop this uprising. The creations guard Argelmach in Blackrock Depths.",objectives={"Find and slay Golem Lord Argelmach. Return his head to Lotwil. You will also need to collect 10 Intact Elemental Cores from the Ragereaver Golems and Warbringer Constructs protecting Argelmach. You know this because you are psychic. "}]])
R(4081,"格殺勿論：黑鐵矮人",[[description="By order of Warlord Goretooth, commander of the Kargath Expeditionary Force:$B$BAny and all of General Angerforge's forces within Blackrock Depths must be annihilated.$B$BAngerforge's men are ruthless killers, responsible for the mass murder of the 109th division of the Kargath Expeditionary Force. Heroes are warned to exercise extreme caution when confronting these brutes.$B$BAny person who destroys the first line of General Angerforge's forces in Blackrock Depths shall receive a tribute.",objectives={"Venture to Blackrock Depths and destroy the vile aggressors!$B$BWarlord Goretooth wants you to kill 15 Anvilrage Guardsmen, 10 Anvilrage Wardens and 5 Anvilrage Footmen. Return to him once your task is complete."}]])
R(4082,"格殺勿論：高階黑鐵軍官",[[description="By order of Warlord Goretooth, commander of the Kargath Expeditionary Force:$B$BHead of the K.E.F. reconnaissance division, Grandmaster Lexlort, has returned with news of the whereabouts of high ranking Dark Iron officials. Through locked gate, near the heart of the city, they train their forces to snuff out our men. Travel to Blackrock Depths and destroy them!$B$BCompletion of this mission will result in a tribute.",objectives={"Venture to Blackrock Depths and destroy the vile aggressors!$B$BWarlord Goretooth wants you to kill 10 Anvilrage Medics, 10 Anvilrage Soldiers and 10 Anvilrage Officers. Return to him once your task is complete."}]])
R(4083,"鬼魂之杯")
R(4084,"銀爪鐵心",[[description="我不知道你說的那個人是誰，$N。$B$B但是請不要擔心，如果你的朋友原本打算大老遠地來找我的話，我應該可以想像到他需要什麼。$B$B在安戈洛環形山的中心地帶有一個極端邪惡的惡魔，它以一個名叫火焰使者的元素生物的形象出現……它被一層任何人都無法驅散的光環保護著……$B$B沒有人可以驅散……除非有足夠的力量。我可以教你如何獲得這樣的力量，$N。$B$B首先按我說的去做，從費伍德森林的生物身上收集11個銀爪和1個鐵樹之心，然後回來找我。",objectives={"為費伍德森林的艾瑞丹·藍風收集11隻銀爪和1顆鐵樹之心。"}]])
R(4101,"凈化費伍德",[[description="植物給與費伍德森林以生命，然而即使是它們也遭受了腐化和墮落的痛苦。我知道淨化它們的方法，但是我不會把這種方法告訴一個我不熟識或者不能信任的$r。向我證明你真的能幫助塞納里奧議會！$B$B這裡的北面有一個鐵木山洞，那裡的曲木元素已經無法挽救了。我要你幫我從它們身上取得樹汁，這些樹汁被稱作血琥珀。有了它們，我就可以研究拯救其他生命的辦法了。",objectives={"收集15顆血琥珀，把它們交給費伍德森林的阿拉珊蒂絲·銀空。"}]])
R(4102,"凈化費伍德",[[description="Plants give life to Felwood, yet even they suffer the taint of corruption.  I know ways to cleanse them, but I cannot give out such knowledge to those I don't know or trust.  Prove to me that you will truly aid the cause of the Cenarion Circle!$B$BTo the north lie the Irontree Caverns.  The Warpwood elementals present there are now beyond hope of cleansing.  I ask you to bring me their sap - blood amber it is called - so I may study it in the hopes of saving other forms of life here.",objectives={"Bring 15 Blood Amber to Maybess Riverbreeze in Felwood."}]])
R(4103,"狩獵換藥膏")
R(4104,"采礦換藥膏")
R(4105,"采集換藥膏")
R(4106,"剝皮換藥膏")
R(4107,"分解換藥膏")
R(4108,"狩獵換藥膏")
R(4109,"采礦換藥膏")
R(4110,"采集換藥膏")
R(4111,"剝皮換藥膏")
R(4112,"分解換藥膏")
R(4113,"被腐化的輕歌花")
R(4114,"被腐化的輕歌花")
R(4115,"被腐化的迎風花")
R(4116,"被腐化的輕歌花")
R(4117,"被腐化的鞭根草")
R(4118,"被腐化的輕歌花")
R(4119,"被腐化的夜龍草")
R(4120,"墮落的力量",[[description="身為一個獵人，我總是努力學習對手的長處。知己知彼，百戰百勝，$N$B$B在梣谷北部的費伍德森林中生活的野獸們都被惡魔的能量所感染。熊和狼都已經變得瘋狂，而且我相信它們的力量也變得更加強大了。$B$B出發吧，$N。去費伍德森林面對那些野獸。如果你和我想像中的一樣強大，就去那裡鍛煉自己吧。",objectives={"菲拉斯莫沙徹營地的塔羅·刺蹄要你去費伍德森林殺掉12頭怒爪灰熊和12頭魔爪掠奪者。"}]])
R(4121,"押送囚徒",[[description="Do you truly believe that you will make it to your rendezvous point with me in custody? You actually expected to break into a heavily fortified Blackrock fortress to capture a prized asset of theirs without alerting anyone or anything to your presence?$B$BYou will be destroyed!",objectives={"Escort your prisoner, Grark Lorkrub, through Burning Steppes and through Blackrock Mountain to the Searing Gorge.$B$BYou recall Lexlort mentioning that he would have his men waiting on the other side to take Grark into custody.$B$BYou will also be required to hand over your Thorium Shackles to Lexlort."}]])
R(4122,"格拉克·洛克魯布",[[description="I tracked him across the Searing Gorge, through the mountain, and into the Burning Steppes. That traitor was caught red-handed giving the Blackrock orcs vital information about our day to day operations. I'm speaking of Grark Lorkrub.$B$BHe now sits in the Burning Steppes, safely under their protection - or so he thinks.$B$BTake these shackles, $N. Find Grark, place the shackles on him and lead him through Blackrock Mountain. Do this and a tribute is yours.",objectives={"Travel to the Burning Steppes and find Grark Lorkrub. You recall Lexlort mentioning that he was last seen in a massive Blackrock fortress.$B$BWhen you find Grark Lorkrub, use the Thorium Shackles to bind him and then lead him back through Blackrock Mountain to the Searing Gorge. Lexlort will have his men waiting on the other side to take Grark into custody."}]])
R(4123,"山脈之心",[[description="多年以來，我都在追尋一塊特殊的寶石。它的名字是山脈之心，個頭大概和你的拳頭差不多！黑鐵矮人把它鎖在他們的一個房間裡，雖然我想盡了辦法，但他們就是不賣給我。$B$B所以我只好訴諸暴力了。$B$B到黑石深淵底部的寶庫裡去，擊敗那裡的守衛，把山脈之心給我搶出來。你所要做的就是擊敗衛兵杜格瑞普，不過只有在你打開房間裡所有的保險箱之後他才會出現！$B$B祝你好運。",objectives={"把山脈之心交給燃燒平原的麥克斯沃特·尤柏格林。"}]])
R(4124,"失蹤的信使",[[description="我的同事基恩諾·火花正在尋找信差的下落，以及他身上攜帶的包裹。那個信差已經失蹤一個星期了，我們所有的搜尋行動都徒勞而返，因此現在我不得不宣佈：信差已經失蹤了。$B$B如果你有時間的話，請去跟基恩諾談談。他應該在要塞裡——也許在他自己的房間裡。",objectives={"和羽月要塞的基恩諾·火花談話。"}]])
R(4125,"失蹤的信使",[[description="拉斯卡爾這個信差出發去薩蘭納爾已經快一個星期了。他對菲拉斯瞭若指掌，自從羽月將軍率領遠征軍踏上這片土地的時候，他就和我們在一起了。我知道他這次是想要划船沿著海岸前進，然後橫穿菲拉斯的南部區域以避開部落的營地。$B$B我找不到他的船，但是也許你可以。也許那艘船被藏起來了，也許它已經沉沒了。不管怎麼樣，只要找到船，就有可能找到他的線索。如果你找到什麼東西的話，請趕快告訴我。",objectives={"找到信差的小船，你應該在菲拉斯的南部海岸線上展開搜索。"}]])
R(4126,"霍爾雷·黑須",[[description="在萬惡的霍爾雷·黑鬚的帶領下，那些黑鐵矮人偷了我們的雷霆啤酒的配方，那些混蛋！他們不配得到如此美味的佳釀！$B$B$N，我有個艱鉅的任務要交給你。去燃燒平原的黑石深淵，摧毀找到的所有裝有雷霆啤酒的桶，然後把雷霆啤酒的配方帶回來！$B$B求求你了，你一定要把配方帶回來，即使要把黑石深淵翻個底朝天你也一定要找到它。",objectives={"把遺失的雷酒秘方帶給卡拉諾斯的拉格納·雷酒。"}]])
R(4127,"船只的殘骸",[[description="你的手沿著泥漿滑過，手指碰到了一把刀柄。它看起來護理得不錯，而且肯定是曾經乘坐過這艘船的人把它給弄丟了。這可能和失蹤的信差有關。$B$B你抓住這把刀，想起羽月要塞的基恩諾·火花要你把任何能找到的線索都報告給他。然而，你有一種感覺，在水中並不是只有你一個人……",objectives={"回到羽月要塞，給基恩諾·火花看看你找到的這把被丟棄的小刀。"}]])
R(4128,"拉格納·雷酒",[[description="你好，$N。我聽說拉格納·雷酒正因為有人偷了他的酒而大發雷霆呢。他在找合適的探險者來幫忙，而且報酬豐富。$B$B如果你感興趣的話就去找拉格納談談。他在丹莫洛卡拉諾斯的雷酒釀製廠裡。",objectives={"和拉格納·雷酒談談。"}]])
R(4129,"奎恩提斯的技藝",[[description="要塞裡有一個名叫奎恩提斯的德魯伊，他有一些……非同尋常的技藝，比如心靈占卜術——通過觸摸某件物品揭示與其關聯的歷史。不要問我他是怎麼做到的，我認為那是一種我不懂也不願去弄懂的魔法。然而我確實知道兩件事：首先，那把戲的效果確實不錯；其次，他還欠著我的債。$B$B把小刀交給小樹屋裡的奎恩提斯，替我告訴他……如果他把他的本事用在那把刀子上的話，他跟我打牌時欠下的債務就一筆勾銷。",objectives={"把被丟棄的小刀交給羽月要塞的奎恩提斯。"}]])
R(4130,"心靈占蔔術",[[description="我仍然有些暈，不好意思。嗯，我看到了一些有用的圖像。$B$B拉斯卡爾從小船裡拿了兩隻皮袋子，然後上了岸；然而，他又回到了小船那裡。我看到了豺狼人……他遇到了豺狼人——那些被稱作木爪豺狼人的傢伙。他看起來很著急——看起來有些恐懼——似乎是在躲避什麼。他甚至沒有注意到身後的水元素……就是這些了。$B$B我得休息一下，對不起，$N。把我看到的東西告訴基恩諾，他需要知道這些。",objectives={"和羽月要塞的基恩諾·火花談話。"}]])
R(4131,"木爪豺狼人",[[description="拉斯卡爾也許是被我們的那些豺狼人「朋友」抓去了，雖然直覺告訴我事情並不是這樣的。但是你最好還是從它們那裡開始搜索。$B$B我希望我知道該幹什麼，我現在能說的只有「去搜索木爪豺狼人的營地，現在就出發。」我知道豺狼人會把他們搶到的東西藏起來，而且為何這些東西互相爭鬥。也許是它們搶了奎恩提斯所說的包裹。我在搜索過程中沒有去跟豺狼人作戰，不過既然奎恩提斯有這種預感，我們就必須採取行動了。",objectives={"在菲拉斯南部地區的木爪豺狼人營地裡尋找信差的下落或者信差的物品。"}]])
R(4132,"行動：殺死安格弗將軍",[[description="You have done an exemplary job, $N. It is now time to send you on your last mission.$B$BGeneral Angerforge, the Dark Iron responsible for coordinating the attacks on the 109th division of the K.E.F. and the mass slaughter of our forces must be brought to justice.$B$BThis will undoubtedly be your most grueling mission, but should you succeed, you will be richly rewarded.",objectives={"Travel to Blackrock Depths and slay General Angerforge! Return to Warlord Goretooth when the task is complete."}]])
R(4133,"薇薇安·拉格雷",[[description="Shadowmaster Vivian Lagrave is in need of your services.  She is in the Badlands, in the orcish outpost of Kargath, pursuing rumors of a certain brew made by the Dark Iron dwarves of Blackrock Depths.$B$BSpeak with Vivian.  She awaits you.",objectives={"Speak with Shadowmaster Vivian Lagrave in Kargath."}]])
R(4134,"遺失的雷酒秘方",[[description="It is rumored that the Dark Iron Hurley Blackbreath has stolen a recipe for ale.  This ale, Thunderbrew Lager, is said to infuse its imbiber with great strength and courage.  We wish to study the drink.  Perhaps, we will find other applications for its virtues... applications more in line with Forsaken objectives.$B$BDelve into Blackrock Depths, find Hurley, take from him the recipe for Thunderbrew lager and bring it to me.$B$BAnd to find him, you may have to entice him by threatening his precious ale.",objectives={"Bring the Lost Thunderbrew Recipe to Vivian Lagrave in Kargath."}]])
R(4135,"痛苦深淵",[[description="Inside the backpacks are two items: the first is a parcel of goods that was bound for Thalanaar, and the second is a note hastily penned to an unknown reader.$B$BThe note tells of discovering insidious bug-like creatures south of the gnoll camps in a place called the Writhing Deep.  The author felt the need to investigate it personally, as though it was a serious threat to all of Feralas.  The note is signed, \"Raschal of Feathermoon\".$B$BIt would seem that you have located where Raschal ultimately went.",objectives={"Now that Raschal's last known whereabouts have been discovered, continue your search for him or his remains in the Writhing Deep.  According to the note, it is located to the south of the Woodpaw gnoll camps."}]])
R(4136,"雷布裏·斯庫比格特",[[description="我的兄弟雷布里就是我們家族的恥辱，他拿走了我們所有的錢，然後揮霍一空。$B$B藏寶海灣的大財主里維加茲剛剛開始懸賞雷布里的腦袋，這對他來說可能有些糟糕，但我簡直無法形容斯庫比格特家族在得知這個消息之後有多高興了！我們的小雷布里終於有點價值了！$B$B但是現在他躲在黑石深淵的深處。請你幫忙找到他，然後把他帶到我這裡來！$B$B如果他不願意來的話，那麼也好……至少把他的頭給我提來。",objectives={"把雷布里的頭顱交給燃燒平原的尤卡·斯庫比格特。"}]])
R(4141,"穆爾金和拉瑞安",[[description="See Larion over there? It's HIS fault we're here!$B$BI told him we were going the wrong way, but would he listen? And would you believe that he's the one that won't speak to me? Well, until he changes his mind, let's have a bit of fun with him.$B$BHave you noticed the strange plant-like creatures around here? They're nothing but trouble, really, but I think if trained properly, I could get them to obey commands.$B$BFirst thing though, I'll need some samples to study. Do you think you could collect some?",objectives={"Collect 15 Bloodpetals and return to Muigin."}]])
R(4142,"造訪格雷甘",[[description="I'm not quite sure what to make of this, $N. The plants... they seem to have some minimal intelligence.$B$BI'm no expert, though. But, I do know someone that is!$B$BHead to northern Feralas, and look for a buddy of mine named Gregan Brewspewer. He's an expert on this sort of thing.$B$BI'm sure Gregan can help us out here. You'll find him out in the wilderness; he's not the type to live in a big city.",objectives={"Take a Bloodpetal to Gregan Brewspewer in Feralas."}]])
R(4143,"邪惡之霧",[[description="我跟你說實話吧，$N，在我的旅途生涯中，我從來沒有看見過這樣的植物。也許我應該去一下環形山……$B$B不管怎麼樣，我想我知道莫爾金正在找什麼東西——阿塔萊之霧。那是種恐怖的東西，而且非常難找，但是莫爾金需要這種材料來控制那些小怪獸。$B$B你應該去悲傷沼澤裡的那座沉沒的神廟，那裡的潛伏者、黑暗蟲和泥漿怪身上都有阿塔萊之霧。祝你好運，$N！",objectives={"收集5份阿塔萊之霧的樣本，然後向安戈洛環形山的莫爾金覆命。"}]])
R(4144,"血瓣花苗")
R(4145,"拉瑞安和穆爾金",[[description="看到那邊的莫爾金了嗎？就是他的錯使我們迷路了！$B$B我知道正確的路，但是他堅持說他知道一條捷徑，然後我們就到了這裡！$B$B更糟的是，現在他還不斷用他那些瘋狂的植物來煩我。我很生氣，所以我原本打算不和他說話了，但是這些該死的植物實在是太多，我沒有足夠的能力來清除它們。$B$B那麼，首先讓我們來減少這些東西的數量吧，去幫我幹掉一些血瓣花鞭笞者和血瓣花捕獸者。",objectives={"為馬紹爾營地裡的拉里安殺掉10個血瓣花鞭笞者和10個血瓣花捕獸者。"}]])
R(4146,"除草器的燃料",[[description="你運氣真不錯，$N！在瑪爾馮離開之後，我一直都在進行一些實驗，其中的一項就是研究一種專殺除草器。只要進行一些調整，它就可以幫助你輕鬆地除掉那些血瓣花。$B$B我可以給你一部這種除草器的樣品，但是你仍然得自行收集所需的燃料。你可以在沉沒的神廟找到你要的阿塔萊之霧，那裡的潛伏者、黑暗蟲和泥漿怪身上都有這種東西。",objectives={"收集5份阿塔萊之霧的樣本，然後將它們送到馬紹爾營地的拉里安那裡。"}]])
R(4147,"瑪爾馮的車間",[[description="I managed to spy on what Muigin was doing, and he's actually growing the darn things over there!$B$BI think the only solution here is to... no, not go talk to him... What are you thinking? The solution is to fight back!$B$BWe'll need the help of my friend, Marvon, who has a workshop in Ratchet.  I'm sure he'll be able to create some sort of gadget that will help us.",objectives={"Travel to Marvon Rivetseeker's workshop in Ratchet."}]])
R(4148,"血瓣花除草器")
R(4161,"卡多雷的菜譜",[[description="很久以前，夜精靈被稱作卡多雷，卡多雷的意思是「眾星之子」。瞭解這些歷史對幫助你成為一名真正的$c非常重要，$N，所以好好聆聽我告訴你的故事吧。$B$B卡多雷總是以自己和環境之間的和諧關係而感到自豪，這意味著我只向自然索取生活必需的東西，並且要給自然友善的回報。這種平衡使我們受益良多，$N。$B$B去幫我收集七條小蜘蛛腿 - 不要多，然後回來找我。",objectives={"為多蘭納爾的札瑞恩收集7條小蜘蛛腿。"}]])
R(4181,"地精工程學",[[description="Expert engineering yields two distinct disciplines: gnome and goblin.  I only bother to mention goblin engineering because I'm a fair trainer.  They like to make things that blow up, and they rarely care what is in the way - even themselves.$B$B$N, read this manual.  If you want to learn how to blow yourself up, then take it to Nixx Sprocketspring in Gadgetzan.   Remember - membership is permanent and prevents joining the other discipline, so make sure this is what you want before finishing his task.",objectives={"If you wish to learn more about Goblin Engineering, take the Manual of Engineering Disciplines to Nixx Sprocketspring in Gadgetzan."}]])
R(4182,"黑龍的威脅",[[description="Life in the Burning Steppes is rife with conflict.$B$BJust look at this place! We know very little of what happened to these buildings, but we do know that at one time, before the great explosion, this was all part of the Redridge mountain range.$B$BEnough lamenting! We have a problem, $N. You may have noticed the dragonkin below this ridge. We need assistance in pushing them back. Kill as many as you can and return to me. Succeed and perhaps we can talk of other things.",objectives={"Slay 15 Black Broodlings, 10 Black Dragonspawn, 4 Black Wyrmkin and 1 Black Drake. Return to Helendis Riverhorn when the task is complete."}]])
R(4183,"真正的主人",[[description="We had always assumed that the Blackrock orcs were a product of their savage upbringing. What we have found here, in their homeland, tells us another story.$B$BIndeed, it is bloodlust and thirst for conflict that empowers them, but the black dragonflight are the beings whom control the orcs of Blackrock. We suspect that it is the black dragonflight that fuels them with rage and hostility.$B$BTake this letter to Magistrate Solomon. He will know what must be done.$B$B<Helendis hands you a sealed letter.>",objectives={"Travel to Lakeshire and deliver Helendis Riverhorn's Letter to Magistrate Solomon. "}]])
R(4184,"真正的主人",[[description="This is grim news, $N. To discover that our mortal enemies are merely pawns of a much greater threat is disheartening. There is no possible way that Lakeshire could survive an attack from both the Blackrock orcs and the black dragonflight. Should Lakeshire fall to this menace, Darkshire would fall next, and then what? Goldshire? Stormwind itself?$B$BYou must take this information to Highlord Bolvar Fordragon in Stormwind at once! If this does not merit the aid of Stormwind, nothing will and all is lost.",objectives={"Travel to Stormwind and deliver Solomon's Plea to Highlord Bolvar Fordragon.$B$BBolvar resides in Stormwind Keep. "}]])
R(4185,"真正的主人",[[description="Solomon paints a dreary picture. Still, we cannot afford to send our thinly spread troops to the aid of Lakeshire on speculation. I will need proof of these claims before I can act.$B$BSpeak with Lady Prestor, $N. She is a learned woman and knows much of dragons and dragonkin. She may be able to shed some light on this situation.",objectives={"Speak with Highlord Bolvar Fordragon after speaking with Lady Katrana Prestor."}]])
R(4186,"真正的主人",[[description="I am going to empower you as an acting deputy of Stormwind, $N.$B$BReturn to Magistrate Solomon in Lakeshire and deliver this decree.",objectives={"Take Bolvar's Decree to Magistrate Solomon in Lakeshire."}]])
R(4201,"愛情藥水",[[description="啊，愛情的痛苦！我親愛的羅克諾特下士對我的魅力不來電，他將我無情地拒絕了！這真是令我發狂！$B$B你必須幫幫我！我們魅魔對於愛情瞭若指掌，所以我可以配製一種藥水，用它來融化包圍著羅克諾特心臟的鐵牆。不果我需要一些材料才能配置這種藥水——一種被稱作格羅姆之血的藥草，一塊從艾薩拉的懸崖巨人那裡得到的巨大銀礦，還有從安戈洛的溫泉中取得的水。你可以把水放在這個小瓶裡。$B$B$N，請幫助一個可憐的靈魂追求她的快樂吧！",objectives={"將4份格羅姆之血、10塊巨型銀礦和裝滿水的娜瑪拉之瓶交給黑石深淵的娜瑪拉小姐。"}]])
R(4221,"被腐化的迎風花")
R(4222,"被腐化的迎風花")
R(4223,"真正的主人",[[description="<Magistrate Solomon sighs.>$B$BYou must return to the Burning Steppes, $N. As a deputy of Stormwind, you will be required to report to Marshal Maxwell. Good luck.",objectives={"Speak with Marshal Maxwell in the Burning Steppes."}]])
R(4224,"真正的主人",[[description="What? You thought you were the first? How many soldiers must we lose before Stormwind acts?$B$BWe had accumulated enormous amounts of intelligence pertaining to the Blackrock menace before we lost our commanding officer, Marshal Windsor. With Marshal Windsor went all of our precious information.$B$BWhat we need is that documentation. Speak with Ragged John, $N. He was with Windsor when they were attacked by a Blackrock raiding party.  He was last seen in a cave to the north.",objectives={"Speak with Ragged John to learn of Marshal Windsor's fate and return to Marshal Maxwell when you have completed this task.$B$BYou recall Marshal Maxwell telling you to search for him in a cave to the north."}]])
R(4241,"溫德索爾元帥",[[description="So that good for nothing coward says that Windsor is alive, eh?$B$BSuit up, deputy, you are going in to find him. If Windsor is alive, you are to bring him back. If he's dead, I want proof.$B$B<Maxwell laughs.>$B$BI bet you are getting tired of hearing that, aren't you?",objectives={"Travel to Blackrock Mountain in the northwest and enter Blackrock Depths. Find out what became of Marshal Windsor.$B$BYou recall Ragged John talking about Windsor being dragged off to a prison."}]])
R(4242,"被遺棄的希望",[[description="Bolvar is a fool. I was gathering his precious 'proof' so that I could shove it down his throat.$B$BHe is a blind buffoon. Proof stands two feet away from him and he does not see.$B$BAs for my data, it's lost. Gone. Unrecoverable.$B$BShould I ever find Ironfoe and make it out of this labyrinth, my first stop will be Stormwind, to place my hammer in between that reptile's eyes.$B$BLeave me, $N.",objectives={"Give Marshal Maxwell the bad news."}]])
R(4243,"找回A-Me 01",[[description="非常不幸，我的一項最偉大的發明出了點問題。你以前見過機械松鼠，對嗎？嗯，為了接近安戈洛環形山的猿猴，我製造了一隻機械猿猴混入它們的群落——我把她稱為A-Me 01。$B$B她的水晶眼珠上附有特殊的魔法，因此我能看見她所看見的一切。不過，在她到了北邊的蘑菇石——也就是那群猿猴的巢穴裡面之後，我便與她失去了聯繫。我最後看到她的時候，猿群中有一隻雄猿正衝上前去想和她打招呼！$B$B你能幫我找到她嗎？",objectives={"在安戈洛環形山找到A-Me 01。"}]])
R(4244,"找回A-Me 01",[[description="A little further investigation shows a panel that slides open. Clearly written above some wiring is the statement, \"Replace Mithril Casing And Turn Power Off Then On.\"$B$BTaking a moment to replace the panel, you wonder if it'll be that simple to fix A-Me 01 and get her back to Karna Remtravel near Marshall's Refuge.$B$BOnly trying it will tell.",objectives={"Find a Mithril Casing and return to A-Me 01 in Un'Goro Crater."}]])
R(4245,"找回A-Me 01",[[description="Checking to see if your prepared to lead A-Me 01 back to Karna Remtravel, you flip the switch to the \"Off\" position. Glancing around once again to make sure none of the gorillas are coming, you prepare to see what happens when you flip the switch back to the \"On\" position.$B$BThis is your last chance... are you sure this is what you want to do?",objectives={"Escort A-Me 01 back to Karna Remtravel in Un'Goro Crater."}]])
R(4261,"遠古之靈",[[description="Felwood was once a peaceful and serene land... Until the legion took hold. The infernals, destruction, chaos...$B$BThe skull of Gul'dan ensured that none were spared here. All fell to the corruption.$B$BEven now, as a spirit, I still find myself trapped, bearing the suffering of this land. Help me find my way home. Please, $N, tell me you will lead an ancient spirit away from here, where I may finally rest.$B$BOnce I am free, seek out Kayneth Stillwind, a druid that resides in Forest Song, to the east.",objectives={"Escort Arei to safety, then speak with Kayneth Stillwind in Forest Song, in eastern Ashenvale."}]])
R(4262,"征服者派隆",[[description="前五個試圖進入黑石深淵的法師幾乎個個都灰頭土臉地回來了，有的情況還要更糟糕。$B$B<加琳達從地上抓了一把灰塵灑向天空。>$B$B造成這種情況的主要原因是有一個可惡的臭蟲——征服者派隆給我們帶來了很多麻煩。我們必須幹掉這個元素生物，然後才能順利地進入黑石深淵！$B$B他就守在黑石採礦場的黑石深淵入口處。",objectives={"殺掉征服者派隆，然後向加琳達覆命。$B$B加琳達告訴過你，派隆守在採礦場中，也許你應該去那裡找找。"}]])
R(4263,"伊森迪奧斯！",[[description="你確定派隆臨死之前喊出了「伊森迪奧斯」這個詞？$B$B<加琳達使勁咽了口唾沫。>$B$B傳說伊森迪奧斯是拉格納羅斯的手下！哦，我的天啊，我的天啊……我們該怎麼辦啊？$B$B你認為你能再去完成一個任務嗎？我現在手頭沒有足夠的人手了，$N！$B$B如果伊森迪奧斯不斷復活派隆的話，那我們的隊伍永遠也不要想進去了。$B$B你必須找到伊森迪奧斯，把他幹掉！",objectives={"在黑石深淵裡找到伊森迪奧斯，然後把他幹掉！"}]])
R(4264,"弄皺的便箋",[[description="The note has stains covering its surface. The text is barely legible, but you make out the following:$B$B...sweet irony...$B$B...the fall of the broken Alliance...$B$B...if it were not for General Angerforge's diligence, we may have never discovered the pattern to the encryption...$B$B...Argelmach is almost done with the decryption of Windsor's notes.$B$BOur lord will rise from the depths and crush any that remain...$B$B-Emperor Dagran Thaurissan.",objectives={"You may have just stumbled on to something that Marshal Windsor would be interested in seeing. There may be hope, after all."}]])
R(4265,"逃離蟲巢",[[description="The pod splits opens some when you touch it, revealing a night elven male who is surprisingly still alive.  He seems to be in good health, though deeply stunned.  As you help him down from the pod, he stirs to life.$B$B\"Thank Elune - you've saved me, friend! I... I'm Raschal, and I awoke paralyzed inside this pod after these bugs overwhelmed me. I could use a hand getting out of here; after that, would you let the Stronghold know that I am all right? I'll be fine - we just need to leave, and fast!\"",objectives={"Escort Raschal safely out of the Zukk'ash hive.$B$BReturn to Ginro Hearthkindle in Feathermoon Stronghold and let him know that Raschal is alive and well."}]])
R(4266,"羽月將軍的歡迎",[[description="$N, General Shandris Feathermoon would like to speak with you personally.  No doubt she wants to thank you for your service to the Stronghold, but I do know that she also wants to talk to you about the insect creatures that you and Raschal faced in southern Feralas.  The reports of those Zukk'ash insects are... frightening, to say the least.$B$BGeneral Feathermoon is waiting for you in the main compound.",objectives={"Speak with Shandris Feathermoon in Feathermoon Stronghold."}]])
R(4267,"異種蠍的崛起",[[description="I am entrusting you with a copy of the report Raschal made on the infestation of southeastern Feralas.  While the main report is being filed in Darnassus, I want you to give this copy to an associate of the Protectorate.  Her name is Gracina Spiritmight; she is a priestess who dwells in the Temple of the Moon in Darnassus.  She has broad knowledge on these kinds of creatures, and her receiving this report would benefit us all.$B$BYou're dismissed - good luck, $N; may Elune watch over us all.",objectives={"Bring Raschal's Report to Gracina Spiritmight in Darnassus."}]])
R(4281,"薩蘭納爾的貨物",[[description="你在木爪豺狼人營地裡發現的這包貨物應該是送往菲拉斯東南部的薩蘭納爾驛站的。不管那個失蹤的信差命運如何，遞送包裹的任務顯然是沒有完成。$B$B你仔細地檢查包裹，發現在外包裝上有手寫的「法芬德爾」字樣，也許這就是包裹接收人的名字。",objectives={"將未遞送的包裹交給薩蘭納爾驛站的法芬德爾。"}]])
R(4282,"壹絲希望",[[description="<Marshal Windsor shakes the note excitedly.>$B$BDo you realize what this means, $N?$B$BPerhaps all is not lost! From what I can ascertain, the information is being held by two Dark Iron dwarves: General Angerforge and the golem lord, Argelmach. I have a feeling that they won't just hand over the information if we ask nicely.$B$BI hope you are ready to battle.$B$BVenture forth and find these two villains! Destroy them and return my lost information.",objectives={"Return Marshal Windsor's Lost Information.$B$BMarshal Windsor believes that the information is being held by Golem Lord Argelmach and General Angerforge."}]])
R(4283,"五十個！",[[description="我要告訴你個小秘密，士兵。走近一些。$B$B我是這裡唯一正常的人！$B$B看看我周圍的那些傢伙！你相信他們都不正常嗎？事實上他們都不正常！他們都瘋了！瘋了！$B$B<奧拉留斯放低了聲音。>$B$B這是個秘密，不要告訴別人，只有你，我，還有我的那個軍官夥計知道。$B$B<奧拉留斯緊握拳頭。>$B$B不管怎麼樣……我在收集巨魔耳朵的同時也收集徽章，就是那些獸人身上的徽章。給我弄五十枚徽章來，現在就出發！$B$B<奧拉留斯雙手攏在嘴邊作喇叭狀。>$B$B快去拿到那些徽章！",objectives={"奧拉留斯想要50枚黑石徽章。在燃燒平原的獸人身上應該可以找到那些徽章。"}]])
R(4284,"能量水晶",[[description="我確定你一定已經注意過它們了，$N。它們到處都是！$B$B我在說什麼？這都不知道，我當然在說水晶！$B$B那些水晶……它們遍佈在整個環形山裡。大多數人都會忽視它們，但我感覺到那些水晶裡一定蘊含著特殊的力量。我一直以來都在用它們進行實驗，但似乎總是沒有什麼成果。好吧，我承認至今為止我一無所獲。$B$B這麼說吧，我這裡的水晶已經不多了——我想你也許能夠幫我收集一些水晶回來？",objectives={"收集紅色能量水晶、藍色能量水晶、黃色能量水晶和綠色能量水晶各7塊，把它們交給馬紹爾營地裡的科琳。"}]])
R(4285,"北部水晶塔",[[description="What could they be for? I can't get the thought out of my head!$B$BIt's driving me crazy --  that the rumors I have heard about the crystal pylons are all true. Call me gullible, but I'll usually believe anything people tell me.$B$BAnyway, I have heard that there is one of the crystal pylons fairly close. Somewhere in the north... Please locate it, $N. I just know they exist.",objectives={"Discover the location of the Northern Crystal Pylon in Un'Goro Crater."}]])
R(4286,"好東西",[[description="溫奇船長跟我說黑暗深淵裡的黑鐵矮人有很多好東西。對吧，溫奇？$B$B<奧拉留斯努力扮演一名海盜。>$B$BB對！$B$B明白我所說的了吧？你到那裡去，給我帶回一些好東西來。$B$B到那兒去搖你的搖錢樹吧！",objectives={"到黑石深淵去找到20個黑鐵挎包。當你完成任務之後，回到奧拉留斯那裡覆命。你認為黑石深淵裡的黑鐵矮人應該會有這些黑鐵挎包。"}]])
R(4287,"東部水晶塔",[[description="During my stay here, I have heard strange rumors about mysterious pylons existing out in the wilderness of the crater, $N. I guess that they are quite large, with crystals lining their interiors.$B$BAlthough I've never seen one, I can't help but think that the rumors are true -- and that the pylons have something to do with all the crystals we found$B$BSo why don't you help me put my curiosity to rest? Supposedly, there is one in the eastern area of the crater. Do you think you can find it?",objectives={"Discover the location of the Eastern Crystal Pylon in Un'Goro Crater."}]])
R(4288,"西部水晶塔",[[description="My experiments so far have not yielded any positive results, $N. I can't help but hope that you can find a solution by searching for one of the pylons that I have heard exist.$B$BPerhaps if we combine certain colors at them... but I get ahead of myself. Let's find them first!$B$B$N, search the western area of the crater; a pylon is said to be somewhere in that area.",objectives={"Discover the location of the Western Crystal Pylon."}]])
R(4289,"安戈洛的猩猩",[[description="這個環形山中居住著許多奇怪的生物——它們似乎比我家鄉那邊的生物更加高貴。我無法解釋這一點，但是這塊地方在呼喚大地之母。每次我看到大地之母創造的某種美麗的生物時，我都會對她肅然起敬。$B$B如果你也希望感覺到見證這偉大功績的幸福感，就向北方出發吧。你將在那兒遇到巨大的猩猩，這對$r的力量來說是一個挑戰。把它們的皮毛交給我……證明你的力量。",objectives={"將2塊安戈洛猩猩的皮、2塊安戈洛大猩猩的皮和2塊安戈洛巨猩猩的皮交給安戈洛環形山入口處的托爾瓦·尋路者。"}]])
R(4290,"拉克維的食物",[[description="Once, a long time ago, a brother of mine took some meat from one of Lar'korwi's kills. He didn't know it at the time, but Lar'korwi saw him from the forest. Lar'korwi followed my brother for days, destroying everything he touched. My brother, scared, finally decided to run from the Crater and leave Lar'korwi behind.$B$BLar'korwi killed him not far from this spot.$B$BIf you want to provoke Lar'korwi, find a fresh kill of his and take some of the meat from it.$B$BReturn to me afterwards.",objectives={"Find the carcass of Lar'korwi's freshest kill and steal a Piece of Threshadon Carcass before returning to Torwa Pathfinder in Un'Goro Crater."}]])
R(4291,"拉克維的氣味",[[description="I'm actually surprised he has not come for you yet, $N. But all is well, for I have a final plan that will bring the monster to us.$B$BBeing the dominant male gives Lar'korwi rights to breed with any female he chooses--and he chooses many of them. You'll find many ravasaur eggs to the west of here. Get close to them and you should provoke an attack by his mates. The females produce an awful smell from a gland in their heads that allow males to know they are ready to breed. Bring me two of those glands.",objectives={"Bring 2 Ravasaur Pheromone Glands to Torwa Pathfinder near the entrance to Un'Goro Crater."}]])
R(4292,"拉克維的誘餌",[[description="This will be the most difficult part because there is some complexity to the plan. To the north of here, you will find a small trail into the mountains. It was here I saw Lar'korwi last. You will know you are in the right area because of all the bones from massive creatures that once wandered nearby. Take the meat you recovered and place it there. Then, rub this mixture I created on the meat. If both lures mingled together do not bring Lar'korwi to you, then I know nothing else that will.",objectives={"Using the contents of Torwa's Pouch, summon Lar'korwi and defeat him. Then bring Lar'korwi's Head to Torwa Pathfinder near the entrance to Un'Goro Crater."}]])
R(4293,"軟泥怪的樣本…",[[description="Felwood is a forest far north of the Barrens, even farther than Ashenvale. There, slimes are found all around pools of water blessed by the touch of Fel. The Scourge decimated the area with attacks of Infernals and other demonic magics--the slimes supposedly crept up through the earth during these attacks.$B$BGather samples of Felwood slimes and we will use the testing equipment next to me to create a control group for our tests against other samples you gather.",objectives={"Gather Felwood Slime Samples from any of the slimes in Felwood. Then, using the Testing Equipment next to Chemist Fuely in Undercity, see which of your samples are the most corrupt. Bring 5 of the Corrupted Felwood Samples you find to Chemist Fuely."}]])
R(4294,"壹大堆軟泥怪",[[description="Have you heard of the Un'Goro Crater, $N? It is near the Tanaris desert, and it is a magnificent place: lush, vibrant, full of creatures and plant life.$B$BIt is there you must go. Word has reached me that the place seems completely untainted by outside hands. Explorers are just now discovering its secrets.$B$BI would like to test the slimes or oozes there. If it is true--that they are uncorrupt--then I would like to see how such creatures have evolved.",objectives={"Gather Un'Goro Slime Samples from any of the slimes in Un'Goro Crater. Then, using the Testing Equipment next to Chemist Fuely in Undercity, see which of your samples are the most pure. Bring 5 of the Pure Un'Goro Samples you find to Chemist Fuely."}]])
R(4295,"羅克諾特的麥酒")
R(4296,"七賢石板",[[description="我追尋七賢的傳說來到了燃燒平原，七賢是一群具有豐富知識和強大力量的矮人，你知道，一旦你有了這兩樣東西，那麼財富必將接踵而來。我要的就是財富！$B$B如果我們能對七賢有更多瞭解，那我們就能一起發財了。據說索瑞森廢墟裡有一塊七賢石板，上面刻有那些古代矮人所掌握的知識。找到那塊石板，把上面的碑文拓下來給我，讓我們共同揭開其中的秘密！",objectives={"把石板拓文交給燃燒平原的麥克斯沃特·尤柏格林。"}]])
R(4297,"小精龍的食物",[[description="Sprite darters are omnivores--that means they eat both meat and vegetation. If your egg here's gonna hatch, we best be prepared. Some good eats for these little guys are flanks of meat, raw and juicy, believe it or not. I was never able to find out why, but it has somethin' to do with Elune's plan for the elves... maybe they were to be protectors or somethin', I don't know.$B$BI'll take care of the egg for now, why don't you get me some good Silvermane stalker flanks for 'em to eat when he's hatched.",objectives={"Bring 5 Silvermane Stalker Flanks to Agnar Beastamer in Hinterlands."}]])
R(4298,"為人父母",[[description="Whoa, it was a lot more ready than I thought...",objectives={"Speak to Agnar Beastamer in the Hinterlands."}]])
R(4299,"<NYI> <TXT>The Tomb of the Seven",[[description="Find the Tomb of the Seven, and place this PX83-Enigmatron there.  ",objectives={"Place the PX83-Enigmatron in the Tomb of the Seven, then return to Maxwort Uberglint."}]])
R(4300,"骨刃武器",[[description="Hmm, maybe there be somethin' you can do for the Hand now that me think 'bout it. Yes, Jes'rimon could use your help for sure.$B$BIn Un'Goro Crater there be raptors with deadly claws. Some of those raptors sometimes have white claws instead of ones black like death. The Hand have... clients... that like weapons crafted from these claws. Bring me many of those white claws, and me pay you good coin. Do it fast enough, and maybe me help you in other ways.",objectives={"Bring 8 White Ravasaur Claws to Jes'rimon in Orgrimmar."}]])
R(4301,"強大的尤爾查",[[description="While you have been exploring Un'Goro, I have seen other things that a mighty hunter such as yourself would relish in. One such sight was a huge ape among the other gorillas to the north. You have been to that cave before, but this time, I wonder if you'll survive the encounter if you accept my task.$B$BI call him U'cha, and he is one of the Earth Mother's greatest sons, of that you can be sure. Defeat U'cha and bring me his pelt. Do this, and I will defend your right to call yourself a great hunter.",objectives={"Bring U'cha's Pelt to Torwa Pathfinder at the entrance of Un'Goro Crater."}]])
R(4321,"分析水晶塔",[[description="The information you have given me about the pylons is very interesting...$B$BGive me a moment to do some calculations, $N. Speak to me again in a moment and I should be able to give you the answer we have been looking for.",objectives={"Speak with J.D. Collie in a moment."}]])
R(4322,"沖破牢籠！",[[description="We need to get out of here, $N. Help me get my gear back from the supply area and free my friends. If we make it out of here, you are to proceed to Morgan's Vigil and speak with Marshal Maxwell. He will give you further instruction.",objectives={"Help Marshal Windsor get his gear back and free his friends. Return to Marshal Maxwell if you succeed."}]])
R(4323,"<NYI> <TXT> Get those Hyenas!!!",[[description="I want some Hyena Pelts, and only the best will do!  Get me spotted Hyena pelts and I'll give you phat lewtz, yo.",objectives={"Bring 7 Spotted Hyena Pelts to TESTTAUREN at Freewind Post."}]])
R(4324,"尤卡·斯庫比格特",[[description="儘管我的弟弟雷布里一生都無所作為，但是我認為，最終他的生命還是有些價值的！然而……我們可能需要你的幫助來讓雷布里發揮他最後的價值。$B$B我姐姐尤卡這段日子以來都在尋找他，而且跟蹤他到了燃燒平原。她曾帶話給我，要我雇些人給她幫忙。$B$B那麼，你有興趣嗎？如果你想要試試的話，就去跟我姐姐說吧。她就住在巨槌石西北的稱作烈焰洞裡。",objectives={"與燃燒平原的尤卡·斯庫比格特談話。"}]])
R(4341,"卡蘭·巨錘",[[description="You have been to the smoldering ruins of Thaurissan? Did you happen to run into a pitiful lout named Kharan Mighthammer? The dwarf that was supposedly watching over my baby girl!$B$B<The King sobs.>$B$BAnd now she's gone, $N!$B$BI have had my men turn the Steppes upside down. The only clue they have as to the whereabouts of my daughter is that she may be inside the Depths. For all I know, she could be dead!$B$BKharan is supposedly being held prisoner there... find him! I want answers!",objectives={"Travel to Blackrock Depths and find Kharan Mighthammer.$B$BThe King mentioned that Kharan was being held prisoner there - perhaps you should try looking for a prison."}]])
R(4342,"卡蘭的故事",[[description="Please, hear me out before passing judgement!",objectives={"Listen as Kharan Mighthammer tells his story."}]])
R(4343,"被腐化的迎風花")
R(4361,"糟糕的消息",[[description="You must take this information back to King Magni, $N. He will know what to do!",objectives={"Return to Ironforge and deliver the bad news to King Magni Bronzebeard."}]])
R(4362,"王國的命運",[[description="看起來我的老對手——達格蘭·索瑞森——已經把我和鐵爐堡都置於他的控制之下了。$B$B你可能是我的最後希望了，$N。你必須拯救我親愛的女兒，茉艾拉！$B$B只有一種方法可以破除索瑞森施放在茉艾拉身上的咒語，那就是殺死他。$B$B還有，$N，不要傷害茉艾拉！記住，她正在被索瑞森控制著！她所做所說的一切都只是索瑞森邪惡咒語的結果！",objectives={"回到黑石深淵，從達格蘭·索瑞森大帝的魔掌中救出鐵爐堡公主茉艾拉·銅鬚。"}]])
R(4363,"語出驚人的公主",[[description="索瑞森是個偉大的、值得尊重的矮人。你毀了我的一生，還有我肚子裡的孩子的一生！$B$B<你認為茉艾拉公主也許是受到了索瑞森的法術影響才變成這樣的。>$B$B回鐵爐堡去告訴我父親，鐵爐堡的下一任統治者將會是個黑鐵矮人。$B$B不管他同不同意，事情都會是這樣。",objectives={"回到鐵爐堡去，與國王麥格尼·銅鬚談話。"}]])
R(4381,"恢復水晶")
R(4382,"精神水晶")
R(4383,"防禦水晶")
R(4384,"破甲水晶")
R(4385,"爆炸水晶")
R(4386,"尖刺水晶")
R(4401,"被腐化的輕歌花")
R(4402,"戈加爾的清涼果",[[description="試煉谷這裡真是熱得要死。$B$B<戈加爾擦了擦他的額頭。>$B$B如果我有仙人掌果的話，就可以做點清涼果來吃了！沒什麼能比清涼果更甘甜消暑的。$B$B我跟你說啊，$n，只要你給我弄十個仙人掌果來，我就幫你做一些清涼果。如果你感興趣的話，就到這附近去找找仙人掌，採集它們的果子。",objectives={"收集10個仙人掌果，把它們交給戈加爾。你記得他說可以在仙人掌上收集到這種果子。"}]])
R(4403,"被腐化的迎風花")
R(4421,"碧火薩特",[[description="很少有$r到這邊來……費伍德森林的墮落已經遍佈各個角落，而且仍在毫無節制地污染所有事物。$B$B作為翡翠議會的一員，我在努力治癒這片土地，但是仍然有些傢伙希望它被腐化墮落。$B$B我所說的就是居住在西南方的克斯特拉斯廢墟中的碧火薩特。他們的頭目是一個名叫薩瓦瑟拉斯的薩特，這些邪惡的惡魔仍在繼續將疾病散佈給他們遇到的一切生物。$B$B我們必須保衛這片原本屬於我們的土地。擊敗薩瓦瑟拉斯，消滅他的爪牙。",objectives={"殺掉11個碧火魔僕、9個碧火巡影者、9個碧火盜賊和薩瓦瑟拉斯。任務完成之後回到費伍德森林的艾瑞丹·藍風處覆命。"}]])
R(4441,"被禁錮的古樹",[[description="你所發現的長笛是由某個守護古樹——忠心守護著夜精靈的樹人——雕刻而成的。$B$B薩特能使他們接觸到的任何東西受到腐蝕，其中也包括那些在費伍德森林安家的古樹。他們的靈魂在惡魔能量的作用下受到束縛和折磨，永遠無法解脫。你找到的碧火魔符就是禁錮古樹的東西。$B$B我們必須淨化長笛，$N。為我從達納蘇斯的月神殿取回一瓶祝福之水吧。",objectives={"到達納蘇斯去，用艾瑞丹的瓶子收集月神殿中的祝福之水，然後回到艾瑞丹那兒。"}]])
R(4442,"凈化！",[[description="Using the water of Elune, I will attempt to purify the flute. We must end this suffering...$B$BMay Elune guide my hands and heart.$B$BSpeak with me again in a moment.",objectives={"Speak to Eridan again in a moment."}]])
R(4443,"被腐化的鞭根草")
R(4444,"被腐化的鞭根草")
R(4445,"被腐化的鞭根草")
R(4446,"被腐化的鞭根草")
R(4447,"被腐化的夜龍草")
R(4448,"被腐化的夜龍草")
R(4449,"被鎖起來的矮人",[[description="嘿！嘿，你！過來！$B$B你要幫幫我。我正在逃避黑鐵矮人的追擊，我藏在這裡，滿以為他們就找不到我了。但那些可惡的混蛋還有魔法！他們肯定看到我藏了起來，他們很快就把門鎖上，說了些什麼過一陣子再回來之類的話，然後就離開了。$B$B你要給它們的顏色瞧瞧！給那些黑鐵地質學家一個教訓！哦……對了，你能不能給我弄幾塊絲綢來做……做……呃，沒什麼。",objectives={"殺掉8個黑鐵地質學家，並將15塊絲綢交給灼熱峽谷裡那個被鎖在廁所中的矮人。"}]])
R(4450,"塔納利斯的賬本",[[description="哦，你猜怎麼著？我想起了一件事情。$B$B我現在仍然被困在這裡，那麼你可以幫我完成一項我在塔納利斯接受的任務嗎？很簡單……嗯，對於你來說是這樣的。$B$B加基森的克林科·古德斯迪爾需要一些從灼熱峽谷和其他地方收集的東西。也許你可以看一下清單，然後把東西交給他……$B$B如果你感興趣的話，我會把他的帳本從門下遞給你。把帳本和他需要的那些東西交給他就行了。",objectives={"把古德斯迪爾的帳本和上面所列的物品交給塔納利斯的克林科·古德斯迪爾。"}]])
R(4451,"自由的鑰匙",[[description="這把小黃銅鑰匙看起來非常普通……它唯一與眾不同的地方是刻在鑰匙頭部的一句話：$B$B「黑鐵廁所——請勿複製。」$B$B你完全不明白這是什麼意思，也不明白這鑰匙是幹什麼用的。",objectives={"搜尋灼熱峽谷並找到一個可以使用這把格里塞特庫房鑰匙的地方。"}]])
