R(7810,"競技場高手",[[description="要成為競技場高手肯定需要付出更多的代價！也許管理古拉巴什競技場的海盜知道到底要多少！",objectives={"與荊棘競技場的小個子約翰·米斯瑞爾談話。"}]])
