R(7961,"Waskily Wabbits!",[[description="These rabbits are breeding uncontrollably.  Something must be done!$b$bHelp us $n, you're our only hope.",objectives={"Kill 5 rabbits and return to Jon LeCraft by the forge on Designer Island."}]])
R(7962,"Wabbit Pelts",[[description="I want LeCrafty rabbit pelts.  Get me some from LeCrafty Rabbits.$b$bThis is important!",objectives={"Bring 3 LeCrafty Rabbit Pelts to Jon LeCraft."}]])
