R(8195,"祖利安、拉紮什和哈卡萊硬幣")
R(8196,"芒果精華")
R(8201,"祭司的頭顱",[[description="這是真的。哈卡現在藏身在祖爾格拉布中，他正沐浴在我們神的力量之下。被迷惑的高階牧師正將我們最神聖的能量傳輸給靈魂掠奪者，他的力量即將超過艾澤拉斯世界上所有的生物。我們必須阻止他！$B$B拿著這根神聖之索，將它穿過負責傳輸我們神的能量的高等祭司們的頭顱。$B$B當你完成了這一步之後，就回到我這裡來。",objectives={"穿上5顆導魔師的頭顱，然後把這串食人妖頭顱交給尤亞姆巴島上的伊克薩爾。"}]])
R(8221,"稀有魚類 - 基佛天使魚")
R(8222,"閃光的蠍血")
R(8223,"更多閃光的蠍血")
R(8224,"稀有魚類 - 迪森皇後魚")
R(8225,"稀有魚類 - 布隆奈爾藍斑魚")
R(8227,"納特的卷尺",[[description="Amongst the shattered fishing lures and tackle is a rolled, silken measuring tape.  Attached to the tape is a label that reads:$B$B\"Nat Pagle, Dustwallow Marsh.\"",objectives={"Return Nat's Measuring Tape to Nat Pagle in Dustwallow Marsh."}]])
R(8228,"能給我壹張宣傳單嗎？")
R(8229,"能給我壹張宣傳單嗎？")
R(8231,"碎浪多頭怪",[[description="The wavethrasher is an amphibious beast living only here in Azshara.  They are powerful and resilient.$b$bThe tough, reflective scales from a wavethrasher mirror the strength of the hunter.$b$bTrack and hunt wavethrashers along the coast of Azshara, and bring me their scales.",objectives={"Bring 6 Wavethrasher Scales to Ogtinc in Azshara.  Ogtinc resides atop the cliffs northeast the Ruins of Eldarath."}]])
R(8232,"神廟中的綠龍",[[description="我要交給你一項危險的狩獵任務，殺死綠龍摩弗拉斯，把它的牙齒帶給我。摩弗拉斯居住在悲傷沼澤的阿塔哈卡神廟深處。$B$B如果你想要打敗它的話，你必須叫上你的盟友。這條綠龍是很多人共同的敵人——去尋找那些志同道合的盟友吧。$B$B綠龍的牙齒是獵人實力的證明。將牙齒交給我，你會在狩獵中得到成長。",objectives={"將摩弗拉斯的牙齒交給艾薩拉的奧汀克。他住在埃達拉斯廢墟東北部懸崖的頂端。"}]])
R(8233,"簡單的要求",[[description="喬拉齊·拉文霍德公爵邀請你到他那兒去。這事得保密，我不能再透露更多消息了。$B$B拉文霍德莊園位於希爾斯布萊德丘陵，敦霍爾德城堡的西北方有一條道路通往那兒。",objectives={"和拉文霍德莊園的喬拉齊·拉文霍德公爵談一談。"}]])
R(8234,"密封的藍袋子",[[description="First things first.  What I've lost is a small blue bag, the contents of which are a private matter.$b$bDon't bother going after the thieves, because they are already dead.  What we do know is the fools couldn't get the bag open. so they sold it to some timbermaw shaman in Azshara as a holy relic.  Clever.$b$bI need you to travel to Azshara and retrieve it from the shaman through subtlety... or force.  Better luck with the first method, I'd wager.  Once acquired, take it to Archmage Xylem.",objectives={"Retrieve the Sealed Azure Bag from the Timbermaw Shaman in Azshara.  Then take the bag to Archmage Xylem, also found in Azshara."}]])
R(8235,"密文碎片",[[description="Lord Ravenholdt has asked a favor of us both.  He wishes to remove the enchantment from this bag.$b$bUnfortunately, some of my books on the subject of dispelling were taken recently, only to be destroyed by savages.  The remains of my books are still valuable to me.$b$bIf you can bring me enough of the encoded fragments, I can piece them back together.  Your best chance is to kill forest oozes, since they have a tendency to pick up just about anything.  You'll find them in northeast Azshara.",objectives={"Bring 10 Encoded Fragments to Archmage Xylem in Azshara."}]])
R(8236,"碧藍鑰匙",[[description="It will take some time to decipher the fragments and remove the enchantment.  When I am complete, I'll deliver the bag to Lord Ravenholdt personally.$b$bThere is still the matter of the key, said to be held by a green drake known as Morphaz.  The drake has made its home deep in the Temple of Atal'Hakkar, the entrance to which lies in the Swamp of Sorrows.$b$bGather your friends and venture to his lair.  Lord Ravenholdt will await your return with the key.",objectives={"Return the Azure Key to Lord Jorach Ravenholdt."}]])
R(8237,"REUSE")
R(8238,"古拉巴什、邪枝和枯木硬幣")
R(8239,"沙怒、碎顱和血頂硬幣")
R(8240,"贊紮的寶石",[[description="銷毀哈卡萊寶石對我們來說至關重要，我們甚至歡迎氏族之外的人幫助我們摧毀哈卡萊寶石！$B$B將你在祖爾格拉布找到的寶石帶往贊札祭壇進行銷毀。我會送你一枚氏族的榮譽勳章，僅此一次，下不為例；這東西可不是輕易能夠獲得的。$B$B願贊札的祝福保佑你！",objectives={"將你在祖爾格拉布找到的哈卡萊寶石帶往尤亞姆巴島的贊札祭壇進行銷毀。一旦成功，跟附近的溫卡薩談談。"}]])
R(8241,"熾熱助熔劑的補給：鐵錠")
R(8242,"熾熱助熔劑的補給：重皮")
R(8243,"贊紮的飲料")
R(8246,"贊達拉的徽記")
R(8249,"垃圾箱")
R(8250,"法師的會見",[[description="大法師克希雷姆最近不斷在問起有沒有像你這種經歷的$r。$b$b如果你想要找他可以去艾薩拉。他的塔就在懸崖的頂端，而唯一可以上去的方法就是由他那傲慢的僕從薩納斯所施放的傳送法術。$b$b薩納斯紮營在他的主人的塔下。如果你要找他，先去艾薩拉的主要道路彎向埃達拉斯廢墟的轉角處。從那個地方再往北直走就可以到達懸崖了。",objectives={"尋找薩納斯並獲得見到大法師克希雷姆的通路。"}]])
R(8251,"魔法的塵埃",[[description="在艾薩拉的血精靈正在尋求一種研磨他們獲得的魔法物品的方法。這種方法所獲得的粉末與普通的分解法術所獲得的材料是不同的。$B$B當我派我的學徒試圖去交換著中粉末的時候，他被毫不猶豫地幹掉了。因此，他們必須為此付出代價。$B$B談話結束，$N。找到艾薩拉北部的這些血精靈，然後使用更具「說服力」的方法來獲得他們閃光的粉末。",objectives={"為大法師克希雷姆收集10份閃光粉末。"}]])
R(8252,"納迦的珊瑚",[[description="看看你的四周吧。遺跡和海岸被惡鞭納迦所佔據了。最近，它們開始熟悉這塊土地並認識到艾薩拉所擁有的稀有材料。$B$B我說的就是魔化珊瑚——不知道為什麼，惡鞭納迦也盯上了它。海灣中的珊瑚所存無幾，這對於我的研究工作非常重要。我需要你去從惡鞭海妖那裡獲得6塊魔化珊瑚然後帶給我。",objectives={"收集6塊魔化珊瑚，然後把它們帶給大法師克希雷姆。"}]])
R(8253,"毀滅摩弗拉斯",[[description="在沉沒的神廟阿塔哈卡深處，有一條名叫摩弗拉斯的綠龍。$B$B數年前我受到他的襲擊，在我有能力組織防禦之前他就殺光了我所有的學徒。我知道有一名學徒已死於非命，他身上有一塊巨大的、擁有無限能量的祕法碎片。$B$B你必須跟盟友共同深入神廟。殺死摩弗拉斯，從這傢伙的胃中取出祕法碎片。",objectives={"從摩弗拉斯身上取回祕法碎片並返回大法師克希雷姆那兒。"}]])
R(8254,"塞納裏奧議會的求助",[[description="It is the way of the divine to help those in need.  The how is insignificant -- only the why matters.$b$bThe Cenarion Circle has such a need.  Speak with Ogtinc to lend aid to their plight.  He resides atop the cliffs to the northeast of the Ruins of Eldarath in Azshara.",objectives={"Seek out Ogtinc in Azshara."}]])
R(8255,"苔蹄快步者",[[description="艾薩拉的苔蹄快步者是一種曾經居住在費伍德森林的偉大生物。它們對疾病和毒藥免疫，因此沒有被那裡的墮落力量所感染。在它們遠古的智慧指引下，苔蹄快步者簡單地選擇了離開。$B$B雖然我感到非常遺憾，但是我希望你能幫助我去獵捕這些強大的野獸。收集4份健康的野鹿腺體，這是淨化藥膏的第一種成分——我們會利用淨化藥膏來治療費伍德森林的。",objectives={"收集4份健康的野鹿腺體並把它們帶給艾薩拉的奧汀克。奧汀克住在埃達拉斯廢墟東北部懸崖的頂部。"}]])
R(8256,"亡靈的腐液",[[description="For this restorative salve, you must use a simple formula: one part poison, two parts cure.  You have acquired one cure, now you must gather the poison.$b$bPowerful undead, such as the lingering highborne who wander the Ruins of Eldarath, are sometimes so infused with evil that it coalesces into a sickly greenish goo.  To the living, this substance is known as ichor of undeath.$b$bDue to the potency of this vile element, I require only a single ichor.",objectives={"Acquire an Ichor of Undeath for Ogtinc in Azshara.  Ogtinc resides atop the cliffs northeast the Ruins of Eldarath."}]])
R(8257,"摩弗拉斯之血",[[description="Now the last part, the second cure.$b$bThe green drake Morphaz is known to be immune to all forms of poison and disease -- many druids died to bring us this information.  There is no doubt his blood is potent for our needs.$b$bA courier from the Cenarion Circle will take the parts you have already collected while you gather the last.  Summon your allies and seek out the drake's lair in the sunken temple of Atal'Hakkar.  Bring his blood to Greta Mosshoof in Felwood.",objectives={"Kill Morphaz in the sunken temple of Atal'Hakkar, and return his blood to Greta Mosshoof in Felwood.  The entrance to the sunken temple can be found in the Swamp of Sorrows."}]])
R(8258,"達克雷爾的威脅",[[description="Death Knight Darkreaver lords over the Great Ossuary in the Scholomance.  He threatens to twist the spirit realm to do his own bidding, and he must be stopped!  This is where the scryer you helped make comes into play.$B$BUse the divination scryer in the heart of the Great Ossuary's basement to call forth Darkreaver's spirit minions.  Defeat the spirits and the death knight himself will appear.  $N, bring me his head!  Only his demise will reverse the damage done to the spirit realm!",objectives={"Use the Divination Scryer in the heart of the Great Ossuary's basement in the Scholomance.  Doing so will bring forth spirits you must fight.  Defeating these spirits will summon forth Death Knight Darkreaver; defeat him.$B$BBring Darkreaver's Head to Sagorne Creststrider in the Valley of Wisdom, Orgrimmar."}]])
