R(8436,"資源競賽",[[description="我們和聯盟的衝突已擴大為一場真正的戰爭，不久之後戰爭就將全面開戰。$B$B對於阿拉希盆地的爭奪就是一個很好的開戰理由。不是聯盟取得資源並將它們拿來對抗我們；就是我們取得資源並拿來支援我們的戰爭。幫助污染者保持這場資源競賽上的優勢吧，$N！",objectives={"將3枚阿拉希盆地榮譽獎章交給戰場外的部落戰爭使者。"}]])
R(8437,"資源競賽",[[description="Our conflict with the Alliance has escalated to a true war.  No longer are false pretenses to enter into battle used or expected by either side at this point.$B$BThe battle for the Arathi Basin is one of resources, plain and simple.  Either the Alliance gets the resources and uses them against us or we get them and use them to keep our war efforts going.  Help the Defilers maintain the flow of resources we need, $N!",objectives={"Bring 3 Arathi Basin Mark of Honor to a Horde Warbringer outside the battlegrounds."}]])
R(8438,"資源競賽",[[description="我們和聯盟的衝突已擴大為一場真正的戰爭，不久之後戰爭就將全面開戰。$B$B對於阿拉希盆地的爭奪就是一個很好的開戰理由。不是聯盟取得資源並將它們拿來對抗我們；就是我們取得資源並拿來支援我們的戰爭。幫助污染者保持這場資源競賽上的優勢吧，$N！",objectives={"將3枚阿拉希盆地榮譽獎章交給戰場外的部落戰爭使者。"}]])
