R(8687,"目標：佐拉坑道蠍",[[description="援軍已被徵召加入佐拉蟲巢的攻擊了。你被選為監看佐拉坑道蠍。完成你的任務之後再回報給指揮官瑪爾利斯。",objectives={"殺死30隻佐拉坑道蠍並回希利蘇斯向塞納里奧城堡的指揮官瑪爾利斯回報。你還必須將作戰任務簡報 VII帶去才能完成這個任務。"}]])
R(8688,"風路長者")
R(8689,"無盡智慧披風",[[description="我很高興聽到你正在協助我們準備攻擊安其拉，$N。我要給你一個保護物品協助你對抗我們的敵人，$c。$B$B我需要一塊其拉披風，我一定會為你量身訂做。我還需要塑像和甲蟲來做一個合適的鉤子。$B$B我保證你不會失望的。",objectives={"帶1件其拉軍用披風、2個翠玉雕像、5隻金色甲蟲和5隻泥土甲蟲給希利蘇斯的凱伊·迅爪。你還需要在塞納里奧議會達到崇敬聲望值才能完成此項任務。"}]])
R(8690,"聚集風暴披風",[[description="I'm glad to hear you're aiding us in our attack on Ahn'Qiraj, $N.  I can make you a protective item that'll be of assistance in the fight against our enemy, $c.$B$BI shall need a Qiraji drape, which I'll resize for you of course.  I'll also need idols and scarabs which I'll use to create a suitable clasp.$B$BI promise you won't be disappointed.",objectives={"Bring 1 Qiraji Regal Drape, 2 Obsidian Idols, 5 Clay Scarabs and 5 Gold Scarabs to Keyl Swiftclaw in Silithus.  You must also obtain Revered reputation with Cenarion Circle to complete this quest."}]])
R(8691,"魔法秘密披風",[[description="我很高興聽到你正在協助我們準備攻擊安其拉，$N。我要給你一個保護物品協助你對抗我們的敵人，$c。$B$B我需要一塊其拉披風，當然我會為你量身訂做。我還需要塑像和甲蟲來做一個合適的鉤子。$B$B我保證你不會失望的。",objectives={"帶1件其拉軍用披風、2個雪白雕像、5隻石甲蟲和5隻水晶甲蟲給希利蘇斯的凱伊·迅爪。你還需要在塞納里奧議會達到崇敬聲望才能完成這個任務。"}]])
R(8692,"不滅生命披風",[[description="I'm glad to hear you're aiding us in our attack on Ahn'Qiraj, $N.  I can make you a protective item that'll be of assistance in the fight against our enemy, $c.$B$BI shall need a Qiraji drape, which I'll resize for you of course.  I'll also need idols and scarabs which I'll use to create a suitable clasp.$B$BI promise you won't be disappointed.",objectives={"Bring 1 Qiraji Regal Drape, 2 Vermillion Idols, 5 Silver Scarabs and 5 Bone Scarabs to Keyl Swiftclaw in Silithus.  You must also obtain Revered reputation with Cenarion Circle to complete this quest."}]])
R(8693,"籠罩陰影披風",[[description="I'm glad to hear you're aiding us in our attack on Ahn'Qiraj, $N.  I can make you a protective item that'll be of assistance in the fight against our enemy, $c.$B$BI shall need a Qiraji drape, which I'll resize for you of course.  I'll also need idols and scarabs which I'll use to create a suitable clasp.$B$BI promise you won't be disappointed.",objectives={"Bring 1 Qiraji Martial Drape, 2 Azure Idols, 5 Bronze Scarabs and 5 Ivory Scarabs to Keyl Swiftclaw in Silithus.  You must also obtain Revered reputation with Cenarion Circle to complete this quest."}]])
R(8694,"禁斷邪語披風",[[description="我很高興聽到你正在協助我們準備攻擊安其拉，$N。我要給你一個保護物品協助你對抗我們的敵人，$c。$B$B我需要一塊其拉披風，當然我會為你量身訂做。我還需要塑像和甲蟲來做一個合適的鉤子。$B$B我保證你不會失望的。",objectives={"帶1件其拉帝王披風、2個琥珀雕像、5隻象牙甲蟲和5隻青銅甲蟲給希利蘇斯的凱伊·迅爪。同時你必須在塞納里奧議會達到崇敬聲望值才能完成這項任務。"}]])
R(8695,"永恒公正鬥篷",[[description="I'm glad to hear you're aiding us in our attack on Ahn'Qiraj, $N.  I can make you a protective item that'll be of assistance in the fight against our enemy, $c.$B$BI shall need a Qiraji drape, which I'll resize for you of course.  I'll also need idols and scarabs which I'll use to create a suitable clasp.$B$BI promise you won't be disappointed.",objectives={"Bring 1 Qiraji Regal Drape, 2 Obsidian Idols, 5 Gold Scarabs and 5 Clay Scarabs to Keyl Swiftclaw in Silithus.  You must also obtain Revered reputation with Cenarion Circle to complete this quest."}]])
R(8696,"隱秘通途披風",[[description="我很高興聽到你正在協助我們準備攻擊安其拉，$N。我要給你一個保護物品協助你對抗我們的敵人，$c。$B$B我需要一塊其拉披風，當然我會為你量身訂做。我還需要塑像和甲蟲來做一個合適的鉤子。$B$B我保證你不會失望的。",objectives={"帶1件其拉帝王披風、2個柔光雕像、5隻石甲蟲和5隻水晶甲蟲給希利蘇斯的凱伊·迅爪。同時你必須在塞納里奧議會達到崇敬聲望值才算完成任務。"}]])
R(8697,"無盡智慧之戒",[[description="謠傳其拉中尉戴的戒指讓他們有可怕的能力。這顆讓他們如虎添翼的腐敗寶石，理論上可以用較純淨的材料來替換為一個不腐敗的戒指。$B$B其拉雕像配戴的寶石就能有此功效，因為它們的質地非常好。$B$B幫我把戒指和雕像帶來我就能為你做一枚強大的戒指，$c。",objectives={"帶1枚其拉典禮戒指、2個黑曜石雕像、5隻銀色甲蟲和5隻白骨甲蟲給希利蘇斯的喚風者耶薩德拉。同時你必須在塞納里奧議會達到尊敬聲望值才能完成這項任務。"}]])
R(8698,"聚集風暴之戒",[[description="The rings worn by the Qiraji lieutenants are rumored to grant them formidable abilities.  The corrupted gems that adorn them could, in theory, be swapped out with more pure materials to create uncorrupted versions of the rings.$B$BThe gems that adorn Qiraji idols would work quite well, as their quality is superior.$B$BBring me the ring and idols and I'll create a powerful ring for you, $c.",objectives={"Bring 1 Qiraji Magisterial Ring, 2 Vermillion Idols, 5 Silver Scarabs and 5 Bone Scarabs to Windcaller Yessendra in Silithus.  You must also attain Honored reputation with Cenarion Circle to complete this quest."}]])
R(8699,"魔法秘密之戒",[[description="謠傳其拉中尉戴的戒指讓他們有可怕的能力。這顆讓他們如虎添翼的腐敗寶石，理論上可以用較純淨的材料來替換為一個不腐敗的戒指。$B$B其拉雕像配戴的寶石就能有此功效，因為它們的質地非常好。$B$B幫我把戒指和雕像帶來我就能為你做一枚強大的戒指，$c。",objectives={"帶1枚其拉將領戒指、2個碧藍雕像、5隻金色甲蟲和5隻泥土甲蟲給希利蘇斯的喚風者耶薩德拉。同時你必須在塞納里奧議會達到尊敬聲望值才能完成這項任務。"}]])
R(8700,"不滅生命之戒",[[description="The rings worn by the Qiraji lieutenants are rumored to grant them formidable abilities.  The corrupted gems that adorn them could, in theory, be swapped out with more pure materials to create uncorrupted versions of the rings.$B$BThe gems that adorn Qiraji idols would work quite well, as their quality is superior.$B$BBring me the ring and idols and I'll create a powerful ring for you, $g fellow : sister; druid.",objectives={"Bring 1 Qiraji Magisterial Ring, 2 Alabaster Idols, 5 Bronze Scarabs and 5 Ivory Scarabs to Windcaller Yessendra in Silithus.  You must also attain Honored reputation with Cenarion Circle to complete this quest."}]])
R(8701,"籠罩陰影之戒",[[description="謠傳其拉中尉戴的戒指讓他們有可怕的能力。這顆讓他們如虎添翼的腐敗寶石，理論上可以用較純淨的材料來替換為一個不腐敗的戒指。$B$B其拉雕像配戴的寶石就能有此功效，因為它們的質地非常好。$B$B幫我把戒指和雕像帶來我就能為你做一枚強大的戒指，$c。",objectives={"帶1枚其拉典禮戒指、2個瑪瑙雕像、5隻石甲蟲和5隻水晶甲蟲給希利蘇斯的喚風者耶薩德拉。同時你必須在塞納里奧議會達到尊敬聲望值才能完成這項任務。"}]])
R(8702,"禁斷邪語之戒",[[description="謠傳其拉中尉戴的戒指讓他們有可怕的能力。這顆讓他們如虎添翼的腐敗寶石，理論上可以用較純淨的材料來替換為一個不腐敗的戒指。$B$B其拉雕像配戴的寶石就能有此功效，因為它們的質地非常好。$B$B幫我把戒指和雕像帶來我就能為你做一枚強大的戒指，$c。",objectives={"帶1枚其拉典禮戒指、2個翠玉雕像、5隻石甲蟲和5隻水晶甲蟲給希利蘇斯的喚風者耶薩德拉。同時你必須在塞納里奧議會達到尊敬聲望值才能完成這項任務。"}]])
