R(9353,"Redeem iCoke Gift Box Voucher")
R(9362,"軍閥克雷利安",[[description="There isn't much time, $n!  My scrying spells have revealed a powerful source of magic.  I cannot leave the tower, and would ask you to kill the vile creature in possession of this artifact.$b$bThe pathetic little cretin is known as Warlord Krellian, hiding behind his guards in the Temple of Zin-Malor.  Burn him to ashes and take the prismatic shell he covets so dearly.",objectives={"Retrieve the Prismatic Shell for Archmage Xylem.  The Archmage resides in a tower atop the cliffs of Azshara."}]])
R(9364,"魔法的碎片",[[description="My research has revealed a unique purpose for the prismatic shell.$b$bCarry the shell and cast your polymorph spell on the Spitelash in Azshara.  If you wait a few moments, the chaotic aura of the shell will cause them to split into several smaller clones for a few moments.  Kill these clones as quickly as possible, and the shell will collect their essence.$b$bWhen the shell is full, return it to me.",objectives={"Polymorph the Spitelash of Azshara and kill the clones that appear several seconds later.  When you have slain 50 Polymorph Clones, return to Archmage Xylem in Azshara."}]])
R(9365,"小偷的獎勵")
R(9367,"火焰節慶",[[description="仲夏又來了！$b$b每一年，按照傳統，雀屏中選的營火管理者要負責看管我們城市裡的營火。當整個艾澤拉斯都是燃燒的火焰時，我們的火苗一定要是最熱烈、最明亮的，才能恰當地表現出對季節的尊敬。$b$b事實上，我有個任務要給你，如果你不介意的話。我還沒聽說所有主城裡的火焰是否都燃燒的恰如其分。前往那裡讓火焰為你取取暖 -- 確定它們都是燙的！",objectives={"觸摸暴風城，鐵爐堡和達納蘇斯裡的營火，再和任何一個主城裡的節慶傳說大師談談。"}]])
R(9368,"火焰節慶",[[description="仲夏又來了！$b$b每一年，按照傳統，雀屏中選的營火管理者要負責看管我們城市裡的營火。當整個艾澤拉斯都是燃燒的火焰時，我們的火苗一定要是最熱烈、最明亮的，才能恰當地表現出對季節的尊敬。$b$b事實上，我有個任務要給你，如果你不介意的話。我還沒聽說所有主城裡的火焰是否都燃燒的恰如其分。前往那裡讓火焰為你取取暖 -- 確定它們都是燙的！",objectives={"觸摸奧格瑪，雷霆崖和幽暗城裡的營火，再和任何一個主城裡的節慶故事使者談談。"}]])
R(9378,"DND FLAG The Dread Citadel - Naxxramas",[[description="In the thick of Plaguewood lies the entrance to the dread citadel of Naxxramas. Previously, all attempts to enter had been stymied by the magical wards placed upon the rune portal. That is, until now.$B$BWe have devised a way to gain entry via a permanent arcane cloaking of sorts - an old cantrip of the Kirin Tor with a few modifications of my own. With that said, the cloaking is costly; however, your dedication to the cause of the Dawn is unwavering! We will waive all cost associations.",objectives={"Archmage Angela Dosantos at Light's Hope Chapel in the Eastern Plaguelands will grant you Arcane Cloaking at no cost. You must be Exalted with the Argent Dawn."}]])
R(9386,"暗處之光",[[description="An eager one, aren't you? If you're willing to enter the depths once more, I'll gladly reward you.$b$bSeek out the bonfires burning within Stratholme, Scholomance, Dire Maul, and the halls of Blackrock Spire itself; I look forward to your return, $n.",objectives={"Find and touch the bonfires located within Blackrock Spire, Dire Maul, Scholomance, and Stratholme, then speak with the Festival Flamekeeper."}]])
R(9388,"卡林多的閃爍火焰",[[description="世界各地都有許多的火焰在燃燒著，$n。最難處理的火焰就是那些發著綠光的；沒有管理的話它們不會長久燃燒。為我們的營火管理者確認那些翠綠色的火焰仍在卡林多燃燒著，聽到了嗎？$b$b你可以在貧瘠之地的棘齒城，黑海岸的主宰之劍附近找到它們，還有從銀翼哨站旁的橋邊進入梣谷的森林裡，和沿著石爪山脈的幹道走到通往狂風峭壁的路上都能找到。",objectives={"探勘梣谷，貧瘠之地，黑海岸，和石爪山脈的營火，再和節慶營火管理者談談。"}]])
R(9389,"東部王國的閃爍火焰",[[description="仲夏火焰節慶傳統上會在整個土地上點燃無數的火焰。有些人說綠色的火焰是最美的，因為它們是最難維持的而且又有獨特的色澤。$b$b為我們的營火管理者確認它們仍在東部王國燃燒著。它們座落在濕地的丹莫德附近，銀松森林內的焚木村那裡也有，眺望濕地燈塔的峭壁上，和希爾斯布萊德丘陵廢棄的哨塔旁。",objectives={"探勘希爾斯布萊德丘陵，銀松森林，西部荒野，和濕地的營火，再和節慶營火管理者談談。"}]])
R(9411,"<UNUSED>Infused Bandages")
R(9412,"<UNUSED>Crystal Flake Throat Lozenge")
R(9413,"<UNUSED>Crystal Flake Throat Lozenge")
R(9414,"<UNUSED>Infused Bandages")
R(9415,"向布魯沃爾元帥報告",[[description="你是治安官藍牆的新兵嗎？你當然是啊。$b$b你還在等什麼？優秀的士兵都死在沙漠裡了。你不想快點加入他們嗎？$b$b現在，快去吧，別在路上變成人乾啊。",objectives={"到佐拉蟲巢旁的聯盟營地和治安官藍牆談談。"}]])
R(9416,"向吉裏卡將軍報到",[[description="你一定是奇立卡將軍的新兵。你也該是時候出現了。在沙漠裡體力很快就會負荷不了。$b$b矮人每天都在增加援軍，而我們不能在短缺資源的希利蘇斯損失土地。$b$b向將軍取得你的指令。我的工作不是訓練你，而是找到你。",objectives={"到雷戈蟲巢旁的部落營地和奇立卡將軍談談。"}]])
R(9419,"橫掃沙漠",[[description="我們最近發現部落一直在希利蘇斯沙漠中搜尋有用的資源，但是不用太擔心他們。我們認為這悶熱的沙漠不太值得部署大批軍力。$b$b不過，那些資源的重要性已被發現，現在我們正努力在趕進度。$b$b如果我能獲得你的協助，你一定要進入沙漠取得希利塞斯紅塵並將它帶回來這裡。",objectives={"找到並將希利塞斯紅塵送到希利塞斯提取器那裡，再到佐拉蟲巢附近的聯盟營地和治安官藍牆談談。"}]])
R(9422,"橫掃沙漠",[[description="我們已經汲取希利蘇斯沙漠的水晶資源好一陣子了。我們面對的唯一危險就是那些把這個地方當做他們家園的生物，令人受不了的沙子灰塵和高溫。$b$b但是現在聯盟似乎知道我們在這裡發現了什麼。我們之間展開了搶奪天然資源大賽還要防止它們被其他人奪走。$b$b我需要所有可獲得的幫助。我希望你能伸出援手。",objectives={"找到並將希利塞斯紅塵送到希利塞斯提取器那裡，再到雷戈蟲巢附近的部落營地和奇立卡將軍談談。"}]])
